insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', 'ROM', 3, 9, 'Nĩkĩ ĩndĩ? Twĩ aseo kũvĩta ala angĩ? Aiee, o na vanini: nũndũ nĩtwambie kwonan’ya kana Ayuti na Akiliki onthe me ungu wa naĩ;'),
('kam', 'ROM', 3, 10, 'o tondũ kũandĩkĩtwe, Kũi mũlũngalu, aiee, o na ũmwe;'),
('kam', 'ROM', 3, 11, 'Kũi ũla wĩ na ũmanyi, Kũĩ ũla ũmũmanthaa Ngai;'),
('kam', 'ROM', 3, 12, 'Onthe nĩmathũkĩte ũtee, matw’ĩkĩte mataĩle vamwe; Kũi ũla wĩkaa nesa, aiee, o na ũmwe:'),
('kam', 'ROM', 3, 13, 'Mĩmeo yoo nĩ mbũa mbingũe; Nĩmaneenie ũkengani na nĩmĩ syoo: Ũoi wa syĩko wĩ ilomonĩ syoo:'),
('kam', 'ROM', 3, 14, 'Makanyw’a moo nĩmausũĩte kĩumo na ũũ:'),
('kam', 'ROM', 3, 15, 'Maũũ moo me mĩtũkĩ kwĩtĩkya nthakame;'),
('kam', 'ROM', 3, 16, 'Wanangĩko na ũnyamao me moendelonĩ moo;'),
('kam', 'ROM', 3, 17, 'Na nzĩa ya mũuo matyaamĩmanya:'),
('kam', 'ROM', 3, 18, 'Kũmũkĩa Ngai kũi methonĩ moo.'),
('kam', 'ROM', 3, 19, 'Na nĩtwĩsĩ maũndũ o na meva ala maneenawa nĩ ĩla mĩao, ĩmatavasya ala me mĩaonĩ; nĩ kana kĩla kanyw’a ũtumw’e, na nthĩ yonthe ĩetwe ũsilĩloni wa Ngai:'),
('kam', 'ROM', 3, 20, 'nũndũ kwondũ wa meko ma ĩla mĩao vai mũndũ ũkatalĩlwa ũlũngalu mbee wake; nũndũ ũmanyi wa naĩ wũkaa kwondũ wa ĩla mĩao.'),
('kam', 'ROM', 3, 21, 'Ĩndĩ yu ũlũngalu wa Ngai nĩwumĩlĩtw’e vate mĩao, naw’o ũkũsĩĩwe nĩ ĩla mĩao na athani;'),
('kam', 'ROM', 3, 22, 'naw’o nĩ ũlũngalu wa Ngai ũla wosawa ũndũ wa kũĩkĩĩa Yesũ Klĩsto kwa onthe ala metĩkĩlaa; nũndũ kũi kĩvathũkan’yo;'),
('kam', 'ROM', 3, 23, 'nũndũ onthe nĩmeekie naĩ, na maivikĩaa ũtaĩo wa Ngai;'),
('kam', 'ROM', 3, 24, 'nĩ kũtalĩlwa ũlũngalu mana nĩ mumo wake kwondũ wa wovosyo ũla wĩ nthĩnĩ wa Klĩsto Yesũ:'),
('kam', 'ROM', 3, 25, 'ũla Ngai wambie ũmwia ethĩwe nthembo ya wĩw’anĩthyo, kwondũ wa mũĩkĩĩo nthakamenĩ yake, kwonan’ya ũlũngalu wake nũndũ wa kũkĩla naĩ ila syeekiwe tene, nũndũ wa wũmĩĩsyo wa Ngai;'),
('kam', 'ROM', 3, 26, 'kwa kwonan’ya ũlũngalu wake ĩvinda yĩĩ: nĩ kana ethĩwe mũlũngalu we mwene, na ĩngĩ ethĩwe mũnengani wa ũlũngalu kwa ũla ũmwĩtĩkĩlaa Yesũ.'),
('kam', 'ROM', 3, 27, 'Kwĩkathĩĩa kũĩva ĩndĩ? Nĩ kũvingĩe nza. Kwondũ wa mwĩao wa mũthemba mwaũ? Wa meko? Aiee: ĩndĩ nũndũ wa mwĩao wa mũĩkĩĩo.'),
('kam', 'ROM', 3, 28, 'Nĩtũkwona ĩndĩ kana mũndũ atalĩlwa ũlũngalu kwondũ wa kũĩkĩĩa vate meko ma ĩla mĩao.'),
('kam', 'ROM', 3, 29, 'Kana Ngai nĩ Ngai wa Ayuti oka? Ti Ngai wa Andũ‐ma‐mbaĩ‐ingĩ nao? Ĩĩ, nĩ wa Andũ‐ma‐mbaĩ‐ingĩ nao:'),
('kam', 'ROM', 3, 30, 'ethĩwa nĩ w’o Ngai nĩ ũmwe, na akamatalĩla ũlũngalu ala ma nzaĩko kwondũ wa kũĩkĩĩa, na ala mate ma nzaĩko kwondũ wa ũla mũĩkĩĩo.'),
('kam', 'ROM', 3, 31, 'Na ĩndĩ nĩtũkũtw’ĩkĩthya ĩla mĩao ta ĩte na ũtonyĩ kwondũ wa mũĩkĩĩo? Aiee, kũikethĩwe ũu: aiee, nĩtũũlũlũmĩlya ĩla miao.'),
('kam', 'ROM', 4, 1, 'Twĩasya ata ĩndĩ ũndũ wa asa waitũ, Avalaamu, kwondũ wa mwĩĩ oonie kyau?'),
('kam', 'ROM', 4, 2, 'Nũndũ ethĩwa Avalaamu atalĩlwe ũlũngalu kwondũ wa meko make, nũtonya, kwĩkathĩĩa; ĩndĩ ti vala ve Ngai.'),
('kam', 'ROM', 4, 3, 'Nũndũ maandĩko measya ata? Na Avalaamu nĩwetĩkĩlile Ngai, na kwatalilwe kwake kwĩthĩwa ũlũngalu.'),
('kam', 'ROM', 4, 4, 'Na ũla ũtethasya wĩa, ĩtuvi yake yĩitalawa ta ya mumo, ĩndĩ yĩtalawa ya thiĩ.'),
('kam', 'ROM', 4, 5, 'Ĩndĩ ũla ũtatethasya wĩa, ĩndĩ nĩwĩtĩkĩlaa ũla ũmũtalĩlaa ũlũngalu ũla ũtakĩaa Ngai, mũĩkĩĩo wake nũtalawa kwĩthĩwa nĩ ũlũngalu.'),
('kam', 'ROM', 4, 6, 'O tondũ Ndaviti wawetie ũathimo kwa mũndũ, ũla ũtalĩlawa ũlũngalu nĩ Ngai vate meko,'),
('kam', 'ROM', 4, 7, 'aiasya, Nĩ aathime ala maekeawa mothũkũ moo, Na ala naĩ syoo ivw’ĩkĩtwe.'),
('kam', 'ROM', 4, 8, 'Nĩ mũathime mũndũ ũtatalĩlawa naĩ nĩ Mwĩaĩi.'),
('kam', 'ROM', 4, 9, 'Ũathimo ũsu nũwetawa kwa ala ma nzaĩko, kana o na kwa ala mate ma nzaĩko nao? Nũndũ twĩasya, Mũĩkĩĩo wa Avalaamu watalilwe kwĩthĩwa nĩ ũlũngalu kwake.'),
('kam', 'ROM', 4, 10, 'Watalilwe ata? Yĩla waĩ mwaĩke, kana yĩla ũtaĩ mwaĩke? Ti yĩla waĩ mwaĩke, ĩndĩ nĩ yĩla ũtaĩ mwaĩke:'),
('kam', 'ROM', 4, 11, 'na nĩwosie ũla ũvano wa kwaĩkwa, ũsiĩlo wa ũlũngalu wa mũĩkĩĩo ũla waĩ naw’o yĩla ũtaĩ mwaĩke: nĩ kana ethĩwe ĩthe wa onthe ala metĩkĩlaa, o na ethĩwa ti aĩke, nĩ kana matalwe kwĩthĩwa na ũlũngalu;'),
('kam', 'ROM', 4, 12, 'na ethĩwe ĩthe wa nzaĩko tĩ wa ala maĩkawa oka, ĩndĩ o na wa ala makinyaa nyaĩĩnĩ sya ũla mũĩkĩĩo wa asa waitũ Avalaamu ũla waĩ naw’o yĩla ũtaĩ mwaĩke.'),
('kam', 'ROM', 4, 13, 'Nũndũ ũla watho Avalaamu wanengiwe na ũsyao wake atĩ akeethĩwa mũtiĩwa wa nthĩ ndwaĩ kwondũ wa ĩla mĩao, ĩndĩ nĩ kwondũ wa ũlũngalu wa mũĩkĩĩo.'),
('kam', 'ROM', 4, 14, 'Nũndũ ethĩwa ala ma ĩla mĩao nĩmo atiĩwa, mũĩkĩĩo nũtw’ĩkĩte wa mana, na ũla watho nũalyũkĩte kwĩthĩwa ti watho:'),
('kam', 'ROM', 4, 15, 'nũndũ ĩla mĩao ĩetae ũthatu; ĩndĩ vala vate mĩao, vai ĩvĩtyo.'),
('kam', 'ROM', 4, 16, 'Kwondũ wa ũu nĩ wa kũĩkĩĩa, nĩ kana ũtonye kwĩthĩwa wa mumo; nĩ kana ũla watho wĩthĩwe mũlũmu ũsyaonĩ w’onthe; ti kwa ala me na ĩla mĩao oka, ĩndĩ naw’o kwa ala me na mũĩkĩĩo wa Avalaamu, nake nĩ ĩthe wa ithyonthe'),
('kam', 'ROM', 4, 17, '(o tondũ kũandĩkĩtwe, Nakũtw’a we ĩthe wa mbaĩ mbingĩ) mbee wake ũla Avalaamu wamwĩtĩkĩlile, nake nĩ Ngai, ũla ũthayũũkasya akw’ũ, na ĩngĩ awetaa syĩndũ ite kw’o, ta syĩ kw’o.'),
('kam', 'ROM', 4, 18, 'Ũla weyĩtũkĩte wĩkwatyo nĩwetĩkĩlile na wĩkwatyo, nĩ kana atw’ĩke ĩthe wa mbaĩ mbingĩ, kwĩanana na ũndũ ũla waneenĩwe, Ũsyao waku ũkeethĩwa o ta ũu.'),
('kam', 'ROM', 4, 19, 'Nake ndaĩ mwonzu mũĩkĩĩonĩ wake, aililikana mwĩĩ wake ta mũkw’ũ (yĩla myaka yake yaĩ ta ĩana), na wũmũ wa ĩvu ya Sala;'),
('kam', 'ROM', 4, 20, 'aisyaĩĩsya ũla watho wa Ngai, ndaaya nzĩka kwa kũlea kwitĩkĩla, ĩndĩ ongeleelwa vinya nĩ mũĩkĩĩo wake, aimũnenga Ngai ndaĩa,'),
('kam', 'ROM', 4, 21, 'na nĩwamanyĩthĩtw’e vyũ, kana ũla wathaniwe nĩ Ngai nũtonya kũwĩka.'),
('kam', 'ROM', 4, 22, 'Kwondũ wa ũu naw’o nĩwatalilwe kwake kwĩthĩwa nĩ ũlũngalu.'),
('kam', 'ROM', 4, 23, 'Kũiaandĩkĩtwe kwondũ wake weka, kana nĩwatalĩlwe kwake ũu;'),
('kam', 'ROM', 4, 24, 'ĩndĩ kwondũ witũ naitũ, ala tũkatalĩlwa o ta ũu, ithyĩ ala tũmwĩtĩkĩlaa ũla wamũthayũũkisye Yesũ Mwĩaĩi waitũ kũmumya kwa akw’ũ,'),
('kam', 'ROM', 4, 25, 'ũla wanenganiwe kwondũ wa mavĩtyo maitũ, na athayũũkw’a nĩ kana tũtalĩlwe ũlũngalu.'),
('kam', 'ROM', 5, 1, 'Ĩndĩ twatalĩlwa ũlũngalu nũndũ wa mũĩkĩĩo, twĩ an mũuo na Ngai kwondũ wa Mwĩaĩi waitũ Yesũ Klĩsto;'),
('kam', 'ROM', 5, 2, 'na kwondũ wake nĩtwonete kwondũ wa kũĩkĩĩa ũthei wa kũvota nthĩnĩ wa mumo ũũ ũla tũũngeme nthĩnĩ waw’o; na nĩtũtanaa wĩkwatyonĩ wa ũtheu mũtisu wa Ngai.'),
('kam', 'ROM', 5, 3, 'Na ti ũu w’oka, ĩndĩ nĩtũtanaa mathĩnanĩ maitũ namo: twĩsĩ kana mathĩna maetae wũmĩĩsyo;'),
('kam', 'ROM', 5, 4, 'na wũmĩĩsyo ũetae ũlũmu; na ũlũmu ũetae wĩkwatyo;'),
('kam', 'ROM', 5, 5, 'na wĩkwatyo ndũsonokasya; nũndũ wendo wa Ngai nĩwonoetwe ngoonĩ sitũ nĩ Veva Mũtheu ũla tũnengetwe.'),
('kam', 'ROM', 5, 6, 'Nũndũ yĩla twaĩ onzu, ĩvinda yeanĩa Klĩsto amakw’ĩĩa ala matakĩaa Ngai.'),
('kam', 'ROM', 5, 7, 'Nũndũ nĩ vinya mũndũ kũkw’a kwondũ wa mũndũ mũlũngalu: ĩndĩ no kwĩthĩwa ve ũmwe ũtonya kũkw’a kwondũ wa mũndũ mũseo.'),
('kam', 'ROM', 5, 8, 'Ĩndĩ Ngai nĩwonanisye wendo wake mwene kwitũ, atĩ yĩla twaĩ athe, Klĩsto akw’a kwondũ witũ.'),
('kam', 'ROM', 5, 9, 'Ĩndĩ mbee mũno, yu tũtalĩlwe ũlũngalu nũndũ wa nthakame yake, tũkatangĩĩwa nĩwe kuma ũthatunĩ wa Ngai.'),
('kam', 'ROM', 5, 10, 'Nũndũ ethĩwa, yĩla twaĩ amaitha, twew’anĩthw’e na Ngai kwondũ wa kĩkw’ũ kya Mwana wake, mbee mũno ĩtina wa kwĩw’anĩthw’a, tũkatangĩĩwa nĩ thayũ wake;'),
('kam', 'ROM', 5, 11, 'na ti ũu w’oka, ĩndĩ nĩtũtanaa nthĩnĩ wa Ngai nũndũ wa Mwĩaĩi waitũ Yesũ Klĩsto, ũla kwondũ wake yu nĩtwosete ũla wĩw’anĩthyo.'),
('kam', 'ROM', 5, 12, 'Kwondũ wa ũu, nũndũ wa mũndũ ũmwe naĩ yalikile kũũ nthĩ, na kĩkw’ũ kwondũ wa naĩ; na kwa ũu kĩkw’ũ kyavikĩa andũ onthe, nĩkwĩthĩwa onthe nĩmeekie naĩ:—'),
('kam', 'ROM', 5, 13, 'nũndũ ĩla mĩao ĩtanoka naĩ yaĩ kũũ nthĩ; ĩndĩ naĩ ndĩtalawa mĩao ĩte vo.'),
('kam', 'ROM', 5, 14, 'Ĩndĩ kĩkw’ũ kyasumbikie kuma Atamu kũvika Mose, o na ĩũlũ wa ala matekĩte naĩ ya mũthemba wa ĩvĩtyo ya Atamu, nake nĩ ngelekan’yo ya ũla ũkoka.'),
('kam', 'ROM', 5, 15, 'Ĩndĩ ũla mũthĩnzĩo ndũilyĩ ta yĩla ĩvĩtyo. Nũndũ ethĩwa aingĩ makwie nĩ ĩvĩtyo ya ũmwe, mbee mũno mumo wa Ngai, na ũla mũthĩnzĩo nũndũ wa mumo wa mũndũ o ũmwe, Yesũ Klĩsto, waingĩva kwa aingĩ.'),
('kam', 'ROM', 5, 16, 'Na ũla mũthĩnzĩo ndũilyĩ ta ũndũ ũla waumie ĩvĩtyonĩ ya mũndũ ũmwe ũla wavĩtisye: nũndũ ũsilĩlo waumie kwa ũmwe waete ũsilĩlo ũtw’ĩtwe, ĩndĩ ũla mũthĩnzĩo nĩwookie kwondũ wa mavĩtyo maingĩ waete kũtalĩlwa ũlũngalu.'),
('kam', 'ROM', 5, 17, 'Nũndũ ethĩwa kwondu wa ĩvĩtyo ya ũla ũmwe, kĩkw’ũ kyasumbĩkie ũndũ wa ũmwe; mbee mũno ala mosaa wingĩ wa mumo na wa mũthĩnzĩo wa ũlũngalu makasumbĩka thayũnĩ kwondũ wa ũmwe, Yesũ Klĩsto.'),
('kam', 'ROM', 5, 18, 'Ĩndĩ o tondũ ũsilĩlo ũtw’ĩtwe wookie ĩũlũ wa andũ onthe kwondũ wa ĩvĩtyo yĩmwe; o ta ũu kwondũ wa wĩko ũmwe wa ũlũngalu ũla mũthĩnzĩo wookie kwa andũ onthe, waete kũtalĩlwa ũlũngalu wa thayũ.'),
('kam', 'ROM', 5, 19, 'Nũndũ wa kũlea kwĩw’a kwa mũndũ ũmwe aingĩ matwiwe athe, o ta ũu kwondũ wa kwĩw’a kwa ũmwe, aingĩ makatuwa alũngalu.'),
('kam', 'ROM', 5, 20, 'Na ila mĩao nayo nĩyalikile, nĩ kana yĩla ĩvĩtyo yingĩvw’e; ĩndĩ yĩla naĩ yaingĩvie, mumo waingĩvie mũno mbee:'),
('kam', 'ROM', 5, 21, 'nĩ kana, o tondũ naĩ yasumbĩkie kũvikĩa kĩkw’ũ, o ta ũu mumo ũsumbĩke kwondũ wa ũlũngalu kũvikĩa thayũ ũtathela kwondũ wa Yesũ Klĩsto Mwĩaĩi waitũ.'),
('kam', 'ROM', 6, 1, 'Twĩasya ata ĩndĩ, Twĩkale naĩnĩ nĩ kana mumo wingĩve?'),
('kam', 'ROM', 6, 2, 'Aiee, kũikethĩwe ũu. Ithyĩ ala twakwie kwa naĩ, tũkekala vo ĩngĩ ata?'),
('kam', 'ROM', 6, 3, 'Kana mũiĩsĩ, ithyonthe ala twavatisiwe kũlikwa nthĩnĩ wa Klĩsto Yesũ, nĩtwavatisiwe kũlikwa nthĩnĩ wa kĩkw’ũ kyake?'),
('kam', 'ROM', 6, 4, 'Twathikiwe ĩndĩ vamwe nake na nzĩa ya ũvatiso nthĩnĩ wa kĩkw’ũ kyake: nĩ kana o tondũ Klĩsto wathayũũkiw’e kuma kwa akw’ũ nũndũ wa ndaĩa ya Ĩthe, naitũ no ta ũu tũkinyae na thayũ mweũ.'),
('kam', 'ROM', 6, 5, 'Nũndũ ethĩwa tũkwatanĩtw’e nake mũvw’anĩlenĩ wa kĩkwũ kyake, tũkeethĩwa o ta ũu mũvw’anĩlenĩ wa ũthayũũkyo wake;'),
('kam', 'ROM', 6, 6, 'twĩsĩ ũũ, kana mũndũ mũkũũ waitũ nĩwambiwe vamwe nake, nĩ kana mwĩĩ wa naĩ wanangwe, nĩ kana tũikekale ĩngĩ ũkombonĩ wa naĩ;'),
('kam', 'ROM', 6, 7, 'nũndũ ũla wakwie nũtalĩtwe ta ũte na naĩ.'),
('kam', 'ROM', 6, 8, 'Ĩndĩ ethĩwa twakwie vamwe na Klĩsto, nĩtũkwĩtĩkĩla tũkeethĩwa thayũ vamwe nake;'),
('kam', 'ROM', 6, 9, 'twĩsĩ Klĩsto nĩwathayũũkiw’e kuma kwa akw’ũ ndakakw’a ĩngĩ; kĩkw’ũ kĩikamũsumbĩka ĩngĩ.'),
('kam', 'ROM', 6, 10, 'Nũndũ kĩkw’ũ kĩla wakwie akwie kwa naĩ o ĩmwe tũ: ĩndĩ thayũ ũla wĩ naw’o, e naw’o kwa Ngai.'),
('kam', 'ROM', 6, 11, 'O ta ũu nenyu ĩtalei ene kwĩthĩwa mwĩ akw’ũ kwa naĩ, ĩndĩ mwĩ thayũ kwa Ngai nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'ROM', 6, 12, 'Mũiketĩkĩle ĩndĩ nai ĩsumbĩke mĩĩnĩ yenyu ĩla ĩkusaa, kũvikĩa kwĩw’a mĩmeo yayo:'),
('kam', 'ROM', 6, 13, 'o na mũikanengane mamutha menyu kwĩka naĩ, methĩwe mĩio, ya ũte ũlũngalu; ĩndĩ ĩnenganei ene kwa Ngai, ta ala me thayu maumite kikw’ũnĩ, na mamutha menyu methĩwe mĩio ya ũlũngalu kwa Ngai.'),
('kam', 'ROM', 6, 14, 'Nũndũ naĩ ndĩkamũsumbĩka: nũndũ mũi ungu wa mĩao, ĩndĩ mwĩ ungu wa mumo.'),
('kam', 'ROM', 6, 15, 'Nata ĩndĩ? Twĩke nai, nũndũ tũi ũngũ wa ĩla mĩao, ĩndĩ twĩ ungu wa mumo? Aiee, kũikethĩwe ũu.'),
('kam', 'ROM', 6, 16, 'Mũiĩsĩ, kana kwa ũla mwĩnenganĩte ene mwĩthĩwe ngombo syake sya kwĩw’a, mwĩ ngombo syake ũla mũmwĩw’aa; ethĩwa nĩ ũkombo wa naĩ ũetae kĩkw’ũ, kana ethĩwa nĩ ũkombo wa kwĩw’a ũetae ũlũngalu?'),
('kam', 'ROM', 6, 17, 'Ĩndĩ mũvea wĩthĩwe kwa Ngai, nũndũ, yĩla mwaĩ ngombo sya naĩ, nimweewie kuma ngoonĩ mũthemba wa momanyĩsyo asu ala mweekĩiwe nthĩnĩ wamo;'),
('kam', 'ROM', 6, 18, 'na mũthaĩtw’e kuma nainĩ, mwatw’ĩka ngombo sya ũlũngalu.'),
('kam', 'ROM', 6, 19, 'Nĩneena o tondũ andũ maneenaa nũndũ wa ũvũthũ wa mĩĩ yenyu: o ũndũ mweenenganie mamutha menyu methĩwe ngombo sya kwĩka ũvuku na ũthũku kũendeea ũthũkunĩ, o ta ũu yu, ĩnenganei mamutha menyu methĩwe ngombo sya ũlũngalu kũvika kũvathĩka.'),
('kam', 'ROM', 6, 20, 'Nũndũ yĩla mwaĩ ngombo sya naĩ, mwaĩ athasye ngalĩ ĩla ya ũlũngalu.'),
('kam', 'ROM', 6, 21, 'Mwaĩ na ũsyao mwaũ ĩvinda yĩu maũndũnĩ asu ala mũmew’ĩaa nthoni yu? Nũndũ mũminũkĩlyo wa maũndũ asu nĩ kĩkw’ũ.'),
('kam', 'ROM', 6, 22, 'Ĩndĩ yu nĩmũthaĩtw’e kuma naĩnĩ, na mwatw’ĩka athũkũmi ma Ngai, mwĩ na ũsyao wenyu kũvika kũvathĩka, na mũminũkĩlyo nĩ thayũ ũtathela.'),
('kam', 'ROM', 6, 23, 'Nũndũ ĩtuvi ya naĩ nĩ kĩkw’ũ; ĩndĩ mũthĩnzĩo wa Ngai nĩ thayũ ũtathela nthĩnĩ wa Klĩsto Yesũ Mwĩaĩi waitũ.'),
('kam', 'ROM', 7, 1, 'Kana mũiĩsĩ, ana‐a‐asa makwa (nũndũ nĩngũneena na ala mesĩ ĩla mĩao), kana mĩao ĩsumbĩkĩte mũndũ ĩvinda yĩla wĩ thayũ?'),
('kam', 'ROM', 7, 2, 'Nũndũ mũndũ mũka ũla wĩ na mũũme nĩwovetwe nĩ mĩao kwa mũũme ĩvinda yĩla mũũme wĩ thayũ; ĩndĩ ethĩwa mũũme akakw’a, nĩwathaw’a kuma mwĩaonĩ wa mũũme.'),
('kam', 'ROM', 7, 3, 'O ta ũu ethĩwa ĩvinda yĩla mũũme wĩ thayũ, akatwawa nĩ mũndũ ũngĩ, akeetwa kĩlaalai: indĩ ethĩwa mũũme nĩwakw’a, nũthaĩtw’e mwĩaonĩ, nake we ti kĩlaalai, o na atwawa nĩ mũndũ ũngĩ.'),
('kam', 'ROM', 7, 4, 'Kwondũ wa ũu, ana‐a‐asa makwa, nĩmwatwiwe akw’ũ kwa ĩla mĩao nũndũ wa mwĩĩ wa Klisto; nĩ kana mũtwawe nĩ ũngĩ, na nĩwe ũla wathayũũkiw’e kuma kwa akw’ũ, nĩ kana tũtonye kũmũsyaĩaa Ngai ũsyao.'),
('kam', 'ROM', 7, 5, 'Nũndũ yĩla twaĩ maũndũnĩ ma mwĩĩ, mimeo ya naĩ ĩla yaĩ kwondũ wa ĩla mĩao yeekaa mamuthanĩ maitũ kũvika kũsyaĩaa kĩkw’ũ ũsyao.'),
('kam', 'ROM', 7, 6, 'Ĩndĩ yu nĩtwaumiw’e mĩaonĩ, tũkw’ĩte kwa ũsu watũlũmitye; nĩ kana tũthũkũmae mwĩkalĩlenĩ mweũ wa veva, na ti mwĩkalĩlenĩ wa tene wa maandĩko.'),
('kam', 'ROM', 7, 7, 'Twĩasya ata ĩndĩ? Ĩla mĩao nĩ naĩ? Aiee, kũikethĩwe ũu. Ĩndĩ, ndyaĩ nĩmanya naĩ, ate o kwondũ wa ĩla mĩao: nũndũ ndyaĩ nĩmanya ĩtomo, ate o ĩla mĩao kwasya, Ndũkew’e ĩtomo:'),
('kam', 'ROM', 7, 8, 'ĩndĩ naĩ, yoona ũthei, yeeka nthĩnĩ wakwa mĩthemba yonthe ya itomo kwondũ wa ũla mwĩao: nũndũ vate mĩao naĩ nĩ ngw’ũ.'),
('kam', 'ROM', 7, 9, 'Nakwa naĩ thayũ tene ĩla mĩao ĩte vo: ĩndĩ ũla mwĩao wooka, naĩ yookĩla ĩngĩ, na nyie nakw’a:'),
('kam', 'ROM', 7, 10, 'na mwĩao, ũla waĩ wa kũete thayũ, ũsu nawona nĩ wa kĩkw’ũ:'),
('kam', 'ROM', 7, 11, 'nũndũ yĩla naĩ yonie ũthei, kwondũ wa ũla mwĩao, nĩyanzesengie, na kwondũ waw’o yambũaa.'),
('kam', 'ROM', 7, 12, 'Na kwondũ wa ũu ila mĩao nĩ mĩtheu, na ũla mwĩao nĩ mũtheu, na nĩ mũlũngalu, na nĩ mũseo.'),
('kam', 'ROM', 7, 13, 'Ĩndĩ ũla ũseo nĩwatw’ĩkie kĩkw’ũ kwakwa? Aiee, kũikethĩwe ũu. Ĩndĩ naĩ, nĩ kana yoneke kwĩthĩwa nĩ naĩ, nĩyatethisye wĩa wa kĩkw’ũ nthĩnĩ wakwa kwondũ wa ũla ũseo; nĩ kana kwondũ wa ũla mwĩao naĩ ĩtw’ĩke nthũku mũno.'),
('kam', 'ROM', 7, 14, 'Nũndũ nĩtwĩsĩ kana ĩla mĩao nĩ ya veva: ĩndĩ nyie nĩ wa mwĩĩ, nĩ mũthoosye naĩnĩ.'),
('kam', 'ROM', 7, 15, 'Nũndũ ũla nĩkaa ndimanyaa: nĩkwĩthĩwa ũla nendaa, ũsu ndiwĩkaa; ĩndĩ ũla nĩmenaa, ũsu nĩw’o nĩkaa.'),
('kam', 'ROM', 7, 16, 'Ĩndĩ ethĩwa nĩkaa ũla ndendaa, nĩĩtĩkĩla ĩla mĩao nĩ mĩseo.'),
('kam', 'ROM', 7, 17, 'Ĩndĩ yu ti nyie ĩngĩ nĩkaa, ĩndĩ nĩ naĩ ĩla ĩtwĩe nthĩni wakwa nĩyo yĩkaa.'),
('kam', 'ROM', 7, 18, 'Nũndũ nĩnĩsi nthĩnĩ wakwa, naw’o nĩ nthĩnĩ wa mwĩĩ wakwa, vaitwĩe ũndũ ũseo: nũndũ kwenda kwĩ vo, ĩndĩ kwĩka ũla ũseo kũivaĩ.'),
('kam', 'ROM', 7, 19, 'Nũndũ ũseo ũla ngwenda ndiwĩkaa; ĩndĩ ũthũku ũla ndendaa, nĩw’o nĩkaa.'),
('kam', 'ROM', 7, 20, 'Ĩndĩ ethĩwa nĩkaa ũla ndendaa, tii nyie ĩngĩ nĩkaa, ĩndĩ nĩ naĩ ĩla ĩtwĩe nthĩnĩ wakwa.'),
('kam', 'ROM', 7, 21, 'Nonete ĩndĩ mwĩao ũũ, kana, kwakwa ngyenda kwĩka nesa, ũthũku wĩ o vo.'),
('kam', 'ROM', 7, 22, 'Nũndũ nĩtanĩaa ĩla mĩao ya Ngai mũndũnĩ wa nthĩnĩ:'),
('kam', 'ROM', 7, 23, 'ĩndĩ nĩona mwĩao wa mũthemba ũngĩ mamuthanĩ makwa, ũla wũkitaa na ũla mwĩao wĩ kĩlilikanonĩ kyakwa, na nũndavĩte ũkambĩkĩa mwĩaonĩ wa naĩ ũla wĩ mamuthanĩ makwa.'),
('kam', 'ROM', 7, 24, 'Mũndũ mũthĩni ninyie! Nũũ ũla ũtonya kũndangĩĩa kuma mwĩĩnĩ wa kĩkw’ũ kĩĩ?'),
('kam', 'ROM', 7, 25, 'Nĩmũtũngĩa Ngai mũvea nĩ ũndũ wa Yesũ Klĩsto Mwĩaĩi waitũ. Kwondũ wa ũu nyie mwene nĩthũkũmaa ĩla mĩao ya Ngai na kĩlilikano kyakwa: ĩndĩ mwĩĩnĩ wakwa nĩthũkũmaa ũla mwĩao wa naĩ.'),
('kam', 'ROM', 8, 1, 'Ĩndĩ yu, kwondũ wa ũu, kũi ũsilĩlo nongi ĩũlũ wa ala me nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'ROM', 8, 2, 'Nũndũ mwĩao wa Veva wa thayũ ũla wĩ nthĩnĩ wa Klĩsto Yesũ nũnthaĩtye kuma mwĩaonĩ wa naĩ na wa kĩkw’ũ.'),
('kam', 'ROM', 8, 3, 'Nĩkwĩthĩwa ũndũ ũla ũtaatonya kwĩkwa nĩ ĩla mĩao, kwa kwĩthĩwa yaĩ mĩvũthũ kwondũ wa mwĩĩ, Ngai, ũndũ wa ũmũtũma Mwana wake mwene na mũvw’ano wa mwĩĩ wa naĩ, na kwondũ wa naĩ, nĩwasilĩle naĩ mwĩĩnĩ:'),
('kam', 'ROM', 8, 4, 'nĩ kana ũtw’ĩo wa ĩla mĩao ũtonye kwĩanĩw’a nthĩnĩ waitũ, ithyĩ ala tũtavikĩlaa maũndũ ma mwĩĩ, ĩndĩ nĩtũvikĩlaa maũndũ ma Veva.'),
('kam', 'ROM', 8, 5, 'Nũndũ ala mavikĩlaa mwĩĩ malilikanaa maũndũ ma mwĩĩ; ĩndĩ ala mavikĩlaa Veva malilikanaa maũndũ ma Veva.'),
('kam', 'ROM', 8, 6, 'Nũndũ kũlilikana kwa mwĩĩ nĩ kĩkw’ũ; ĩndĩ kũlilikana kwa Veva nĩ thayũ na mũuo:'),
('kam', 'ROM', 8, 7, 'nĩkwĩthĩwa kũlilikana kwa mwĩĩ nĩ ũmaitha na Ngai; nũndũ kũikwĩnyivya mĩaonĩ ya Ngai, o na ĩngĩ kũitonyeka:'),
('kam', 'ROM', 8, 8, 'na ala ma mwĩĩ maitonya kũmwendeesya Ngai.'),
('kam', 'ROM', 8, 9, 'Ĩndĩ inyw’ĩ mũi ma mwĩĩ, ĩndĩ mwĩ ma Veva, ethĩwa nĩ w’o kana Veva wa Ngai atwĩe nthĩnĩ wenyu. Ĩndĩ ethĩwa mũndũ o na wĩva nde na Veva wa Klĩsto, ũsu ti wake nongi.'),
('kam', 'ROM', 8, 10, 'Na ethĩwa Klĩsto e nthĩnĩ wenyu, mwĩĩ nĩ mũkw’ũ kwondũ wa naĩ; ĩndĩ veva wĩ thayũ kwondũ wa ũlũngalu.'),
('kam', 'ROM', 8, 11, 'Ĩndĩ ethĩwa Veva wa ũla wamũthayũũkisye Yesũ kũmumya akw’ũnĩ nũtwĩe nthĩnĩ wenyu, ũla wamũthayũũkisye Klĩsto Yesũ kũmumya akw’ũnĩ akamĩnenga thayũ mĩĩ yenyu ĩla ĩkusaa, kwondũ wa Veva wake ũla ũtwie nthĩnĩ wenyu.'),
('kam', 'ROM', 8, 12, 'Kwondũ wa ũu ĩndĩ, ana‐a‐asa makwa, twĩ na thiĩ, ti wa mwĩĩ, kwĩkalya mathayũ maitũ kũatĩĩa maũndũ ma mwĩĩ:'),
('kam', 'ROM', 8, 13, 'nũndũ ethĩwa mwĩkala kũatĩĩa maũndũ ma mwĩĩ, mũitĩa kũkw’a; ĩndĩ ethĩwa kwondũ wa Veva mũkooaa meko ma mwĩĩ, mũkeethĩwa thayũ.'),
('kam', 'ROM', 8, 14, 'Nũndũ onthe ala matongoeaw’a nĩ Veva wa Ngai, asu nĩ o ana ma Ngai.'),
('kam', 'ROM', 8, 15, 'Nũndũ mũiaaosa veva wa ũkombo ĩngĩ ũetae w’ĩa; ĩndĩ nĩmwoosie veva wa kũtuwa ana, kwondũ wa ũu nĩtwĩkaĩlaa, tũkyasya, Nau, Asa.'),
('kam', 'ROM', 8, 16, 'Ũla Veva mwene akũsĩĩaa vamwe na maveva maitũ, kana ithyĩ twĩ syana sya Ngai:'),
('kam', 'ROM', 8, 17, 'na ethĩwa twĩ syana, twĩ atiĩwa; atiĩwa ma Ngai na atiĩwa vamwe na Klĩsto; ethĩwa nĩw’o kana tũkanyamaaw’a vamwe nake, nĩ kana tũtonye naw’o kũtaĩwa vamwe nake.'),
('kam', 'ROM', 8, 18, 'Nũndũ nĩtalaa mathĩna ma ĩvinda yĩĩ matiaĩle kũvw’ananw’a na ũtheu mũtisu ũla tũkavuanĩw’a ithyĩ.'),
('kam', 'ROM', 8, 19, 'Nũndũ syũmbe syonthe isyaĩĩsyaa mũno ikyeteela ana ma Ngai monanw’e.'),
('kam', 'ROM', 8, 20, 'Nũndũ syũmbe isumbĩkĩtwe nĩ wanangĩko, ti kwa kwenda kwasyo, ĩndĩ nĩ kwondũ wa ũla waitw’ĩĩe ũu, wĩkwatyonĩ:'),
('kam', 'ROM', 8, 21, 'nĩkwĩthĩwa syũmbe nasyo ikathaw’a kuma ũkombonĩ wa wanangiko, kũlika ũthasyonĩ wa ũtaĩo wa syana sya Ngai.'),
('kam', 'ROM', 8, 22, 'Nũndũ nĩtwĩsĩ kana syũmbe syonthe ilumaa na kwaũnyw’a nĩ woo vamwe kũvika o na yu.'),
('kam', 'ROM', 8, 23, 'Na ti ũu w’oka, ĩndĩ ithyĩ naitũ ala twĩ na mosyao ma mbee ma Veva, o naitũ ene nĩtũlumaa nthĩnĩ waitũ, tũkyeteela kũtuwa ana, nakw’o nĩ wovosyo wa mĩĩ yaitũ.'),
('kam', 'ROM', 8, 24, 'Nũndũ wĩkwatyonĩ nĩtwatangĩĩwe: ĩndĩ wĩkwatyo wenekee ti wĩkwatyo: nũndũ nũũ wĩkwatasya kĩla wene?'),
('kam', 'ROM', 8, 25, 'Ĩndĩ ethĩwa twĩĩkwatya kĩla tũtene, nĩvo ĩndĩ tũkyeteelaa na wũmĩĩsyo.'),
('kam', 'ROM', 8, 26, 'Na ĩngĩ o ta ũu ũla Veva nũtũtetheeasya wonzunĩ wĩtũ: nũndũ tũtyĩsĩ kũvoya tondũ twaĩlwe; ĩndĩ ũla Veva mwene nũtũvoyeaa na kũluma kũtaweteka;'),
('kam', 'ROM', 8, 27, 'nake ũla ũmanthaa ngoonĩ nĩwĩsĩ kwenda kwa Veva ũndũ kũilyĩ, nĩkwĩthĩwa avoyeaa atheu kwĩanana na kwenda kwa Ngai.'),
('kam', 'ROM', 8, 28, 'Naitũ nĩtwĩsĩ maũndũ onthe mekaa vamwe na kũete moseo kwa ala mamwendaa Ngai, kwa ala meetiwe kwĩanana na kwenda kwake.'),
('kam', 'ROM', 8, 29, 'Nĩkwĩthĩwa ala wesĩ kuma tene, asu nĩo wanyuvie kuma tene nĩ kana mavw’ananw’e na mũvw’ano wa Mwana wake, nĩ kana we ethĩwe mũsyawa wa mbee katĩ wa ana‐a‐asa aingĩ:'),
('kam', 'ROM', 8, 30, 'na ala wanyuvie kuma tene, asu nĩo wametie: na ala wetie, asu nĩo wamatalĩle ũlũngalu: na ala wamatalĩle ũlũngalu, asu nĩo wamataĩe.'),
('kam', 'ROM', 8, 31, 'Twĩasya ata ĩndĩ maũndũnĩ asu? Ethĩwa Ngai e ngalĩ ĩla yaitũ, nũũ ũla ũtwĩka ũndũ?'),
('kam', 'ROM', 8, 32, 'We ũla ũtaamwĩw’ĩa tei Mwana wake mwene, ĩndĩ amumisye kwondũ witũ ithyonthe, akaeka ata kũtũnenga mana syĩndũ syonthe nthĩnĩ wake?'),
('kam', 'ROM', 8, 33, 'Nũũ ũla wĩmavinganĩasya anyuve ma Ngai? Ngai nĩwe ũmatalĩlaa ũlũngalu.'),
('kam', 'ROM', 8, 34, 'Nũũ ũla wimasilĩlaa? Klĩsto Yesũ nĩwe wakwie, ĩĩ na kũvĩtũka ũu, nĩwathayũũkiw’e kuma akw’ũnĩ, na e ngalĩ ya kw’oko kwa aũme kwa Ngai, na ĩngĩ nĩwe ũtũvoyeaa.'),
('kam', 'ROM', 8, 35, 'Nũũ ũla witũvathanasya na wendo wa Klĩsto? Nĩ monyamao, kana woo, kana thĩna, kana yũa, kana ndwĩkĩwa, kana mũisyo, kana ũvyũ?'),
('kam', 'ROM', 8, 36, 'O ũndũ kũandĩkĩtwe. Kwondũ waku twĩũawa mũthenya w’onthe; Nĩtũtalawa kwĩthĩwa malondu ma kũawa.'),
('kam', 'ROM', 8, 37, 'Aiee, maũndũnĩ asu onthe nĩtũkĩlya vinya mũno kwondũ wa ũla watwendie.'),
('kam', 'ROM', 8, 38, 'Nũndũ nĩnĩsĩ vyũ, kana kĩkw’ũ, o na thayũ, o na alaĩka, o na monene, o na maũndũ ma yu, o na ala makoka, o na mavinya,'),
('kam', 'ROM', 8, 39, 'o na ũtũlu, o na ũliku, o na kĩla kyoombiwe kyonthe, kĩtitonya kũtũtaan’ya na wendo wa Ngai, ũla wĩ nthĩnĩ wa Klĩsto Yesũ Mwĩaĩi waitũ.'),
('kam', 'ROM', 9, 1, 'Nĩneenaa w’o nthĩnĩ wa Klĩsto, ndiũneena ũvũngũ, wasya wa ngoo wakwa nũũkũsĩĩa vamwe nakwa nthĩnĩ wa Veva Mũtheu,'),
('kam', 'ROM', 9, 2, 'kana nĩ na kyeva kĩnene na woo ũtathela ngoonĩ yakwa.'),
('kam', 'ROM', 9, 3, 'Nũndũ nenda nyie mwene nĩthĩwe nĩ mũumanĩe na kũvetwa nthĩnĩ wa Klĩsto kwondũ wa ana‐a‐asa makwa, mbaĩ yakwa kwa mwĩĩ:'),
('kam', 'ROM', 9, 4, 'nao nĩ Aisilaeli; kũtuwa ana nĩ kwoo, o na ĩla ndaĩa na motianĩo, na kũnengwa ĩla mĩao, na ũthũkũmi wa Ngai, na ala matho;'),
('kam', 'ROM', 9, 5, 'nao, ala aasa nĩ moo, na Klĩsto aumie kwoo kwondũ wa mwĩĩ, ũla wĩ ĩũlũ wa onthe, ũtaĩĩtwe nĩ Ngai tene na tene. Ameni.'),
('kam', 'ROM', 9, 6, 'Ĩndĩ ti kwĩthĩwa ndeto ya Ngai nĩyaemiwe. Nũndũ onthe ala masyaiwe nĩ Isilaeli, ti onthe Isilaeli:'),
('kam', 'ROM', 9, 7, 'o na onthe ti syana, ala ma ũsyao wa Avalaamu: ĩndĩ, Nthĩnĩ wa Isaka ũsyao waku ũketwa.'),
('kam', 'ROM', 9, 8, 'Kũilyĩ ati syana sya mwĩĩ ti syo syana sya Ngai: ĩndĩ o syana sya ũla watho italawa kwĩthĩwa nĩ ũsyao.'),
('kam', 'ROM', 9, 9, 'Nũndũ ĩno nĩyo ndeto ya watho, Ĩvinda ta yĩĩ nĩngoka, na Sala akethĩwa na mwana.'),
('kam', 'ROM', 9, 10, 'Na ti ũu w’oka; ĩndĩ Leveka aya ĩvu ya ũmwe, nake nĩ mũũme wake, asa waitũ Isaka,—'),
('kam', 'ROM', 9, 11, 'na syana itanamba ũsyawa, o na itanamba kwĩka ũndũ ũseo kana ũthũku, nĩ kana kwenda kwa Ngai kwĩanana na kũnyuva kwake kwĩkale, ti kwa meko, ĩndĩ nĩ kwa ũla wĩtanaa,'),
('kam', 'ROM', 9, 12, 'Leveka nĩwataviw’e, Ũla mũkũũ nũkathũkũma mũinae.'),
('kam', 'ROM', 9, 13, 'O ũndũ kũandĩkĩtwe, Yakovo nĩnamwendie, ĩndĩ Esau nĩnamũmenie.'),
('kam', 'ROM', 9, 14, 'Twĩasya ata ĩndĩ? Kwĩ ũte ũlũngalu kwa Ngai? Aiee, kũikethĩwe ũu.'),
('kam', 'ROM', 9, 15, 'Nũndũ nĩwamwĩie Mose, Ngamwĩw’ĩa tei ũla nĩmwĩw’ĩaa, na ngamwĩw’ĩa ĩnee ũla nĩmwĩw’ĩaa.'),
('kam', 'ROM', 9, 16, 'Na kwa ũu ti wa ũla wendaa, kana wa ũla ũsembaa, ĩndĩ nĩ wa Ngai ũla wĩw’ĩaa tei.'),
('kam', 'ROM', 9, 17, 'Nũndũ maandĩko memwĩa Valao, Kwondũ wa ũu nĩnakũũngamisye, nĩ kana nonan’ye vinya wakwa nthĩnĩ waku, na nĩ kana syĩtwa yakwa yĩtavanw’e nthĩ yonthe.'),
('kam', 'ROM', 9, 18, 'Kwa ũu amwĩw’ĩaa tei ũla ũkwenda kũmwĩw’ĩa, na ũla ũkwenda kũmya aiũmya.'),
('kam', 'ROM', 9, 19, 'Ĩndĩ ũkambĩa Kũilyĩ ata kwĩkalaa aitwona na mavĩtyo? Nũndũ nũũ ũla wĩsiĩĩa kwenda kwake?'),
('kam', 'ROM', 9, 20, 'Aiee, ĩndĩ we mũndũ, nue ũũ ũla ũmũkananĩsya Ngai? Kĩndũ kĩla kyoombiwe nĩkĩtonya kũmũtavya ũla wakyũmbie, Wambũmbĩe ũu kĩ?'),
('kam', 'ROM', 9, 21, 'Kana mũmbi nde na vinya ĩũlũ wa yũmba, kuma mũndonĩ ũmwe, kĩlungu kĩmwe kũmba mũio wĩthĩwe na ndaĩa, na kilungu kĩngĩ kumba mũio ũte wa ndaĩa?'),
('kam', 'ROM', 9, 22, 'Nata ethĩwa Ngai, akyenda kwonan’ya ũthatu wake, na kũmanyĩthan’ya vinya wake, nĩwomĩĩsye na wũmĩĩsyo mwingĩ mĩio ya ũthatu ĩla yombiwe ya wanangĩko:'),
('kam', 'ROM', 9, 23, 'nĩ kana amanyĩthan’ye wĩngĩ wa ndaĩa yake ĩũlũ wa mĩio ya tei, ĩla waseũvisye mbee yĩthĩwe ya ũtaĩo,'),
('kam', 'ROM', 9, 24, 'nayo nĩ ithyi, ala watwĩtie, ti kuma kwa Ayuti oka, ĩndĩ kuma kwa Andũ‐ma‐mbaĩ‐ingĩ nao?'),
('kam', 'ROM', 9, 25, 'O ũndũ waisye ĩvukunĩ ya Osea, Ngameta asu andũ makwa, ala mataĩ andũ makwa; Na ngamwĩta mwendwa, ũla ũtaĩ mwendwa.'),
('kam', 'ROM', 9, 26, 'Na kũkeethĩwa, vala meeiwe, Inyw’ĩ mũi andũ makwa, Vau makeetwa ana ma Ngai ũla wĩ thayũ.'),
('kam', 'ROM', 9, 27, 'Na Isaia eumya wasya wake kwondũ wa Isilaeli, Ethiwa ũtalo wa syana sya Isilaeli ũkethiwa ta kĩthangathi kya ũkanga, nĩ ũtialo ũla ũkatangĩĩwa:'),
('kam', 'ROM', 9, 28, 'nũndũ Mwĩaĩi akeanĩsya ndeto yake ĩũlũ wa nthĩ, aimĩminũkĩlya na kũmĩtila nguvi.'),
('kam', 'ROM', 9, 29, 'Na, tondũ Isaia wambie ũneena, Keka Mwĩaĩi wa Savaothi watũtiĩe ũsyao, Twĩthiwa twatw’ĩkie ta Sotomo, na tũkavw’ananw’a na Ngomola.'),
('kam', 'ROM', 9, 30, 'Twĩasya ata ĩndĩ? Kana Andũ‐ma‐mbaĩ‐ĩngĩ, ala mataaatĩĩa ũlũngalu, nĩmoonie ũlũngalu, naw’o nĩ ũlũngalu, ũla wa mũĩkĩĩo:'),
('kam', 'ROM', 9, 31, 'ĩndĩ Isilaeli, maatĩĩa mwĩao wa ũlũngalu, matyaavikĩa mwĩao ũsu.'),
('kam', 'ROM', 9, 32, 'Nĩ ũndũ wa kĩ? Nũndũ matyaamantha kwa kũĩkĩĩa, ĩndĩ kwa kwĩka. Nĩmalulutĩkilw’e nĩ yĩla ĩvia yĩlulutĩkasya;'),
('kam', 'ROM', 9, 33, 'o tondũ kũandĩkĩtwe, Sisyai, nĩngwia nthĩnĩ wa Saioni ĩvia ya kũtulya na ĩvia ĩnene ya kũlulutĩkya: Na ũla ũmwĩtĩkĩlaa ndakasonokw’a.'),
('kam', 'ROM', 10, 1, 'Ana‐a‐asa makwa, kwenda kwa ngoo yakwa na kũvoya kwakwa kwa Ngai nĩ kwondũ woo, nĩ kana matangĩĩwe.'),
('kam', 'ROM', 10, 2, 'Nũndũ nĩngũmakũsĩĩa kana me na ũthangaau mũnene kwa Ngai, ĩndĩ ti kwĩanana na ũmanyi.'),
('kam', 'ROM', 10, 3, 'Nũndũ wa kwĩthĩwa matyaamanya ũlũngalu wa Ngai, na makĩmantha kũlũlũmĩlya ũlũngalu woo ene, malea kwĩnyivĩsya ũlũngalu wa Ngai.'),
('kam', 'ROM', 10, 4, 'Nũndũ Klĩsto nĩ mũminũkĩlyo wa ĩla mĩao nĩ kana o ũla wĩtĩkĩlaa ethĩwe na ũlũngalu.'),
('kam', 'ROM', 10, 5, 'Nũndũ Mose eandĩka kana mũndũ ũla wĩkaa, ũlũngalu ũla wonekaa ĩla mĩaonĩ akekala thayũ nthĩnĩ waw’o.'),
('kam', 'ROM', 10, 6, 'Ĩndĩ ũlungalu ũla wonekaa mũĩkĩĩonĩ wĩneena atĩĩ, Ndũkasye ngooni yaku, Nũũ ũla ũkambata ĩtunĩ? (Naw’o, nĩ kũmũtheesya Klĩsto kũũ nthĩ:)'),
('kam', 'ROM', 10, 7, 'kana, Nũũ ũla ũkatheea ĩimanĩ yĩte kĩtulu? (Naw’o, nĩ kũmũkĩlya Klisto kũmumya akw’ũnĩ.)'),
('kam', 'ROM', 10, 8, 'Ĩndĩ maandĩko measya ata? Ĩla ndeto yĩ vakuvĩ naku, kanyw’anĩ waku na ngoonĩ yaku: nayo nĩ ĩla ndeto ya mũĩkĩĩo, ĩla ithyĩ tũtavanasya:'),
('kam', 'ROM', 10, 9, 'nĩkwĩthĩwa ethĩwa ũkamumbũla Yesũ na kanyw’a waku kana nĩwe Mwĩaĩi, na ũkeetĩkĩla ngoonĩ yaku kana Ngai nĩwamũthayũũkisye kũmumya akw’ũnĩ, ũkatangĩĩwa:'),
('kam', 'ROM', 10, 10, 'nũndũ mũndũ nĩwĩtĩkĩlaa na ngoo kũvikĩa ũlũngalu; na nĩwumbũlaa na kanyw’a kũvikĩa ũtangĩĩo.'),
('kam', 'ROM', 10, 11, 'Nũndũ maandĩko measya, O ũla ũkamwĩtĩkĩla ndakaasonokw’a.'),
('kam', 'ROM', 10, 12, 'Nũndũ kũi kĩvathũkan’yo kati wa Mũyuti na Mũkiliki: nũndũ Mwĩaii o ũsu ũmwe nĩ Mwĩaĩĩ wa onthe, na ni mũthwii kwa onthe ala mamwĩkaĩlaa:'),
('kam', 'ROM', 10, 13, 'nũndũ, O ũla ũkekaĩla syĩtwa ya Mwĩaĩi, nũkatangĩĩwa.'),
('kam', 'ROM', 10, 14, 'Ĩndĩ makamwĩkaĩla ata ũla matamwĩtĩkĩlĩte? Na makamwĩtĩkĩla ata we ũla mataamwĩw’a? Na makeew’a ata vate mũtavan’ya?'),
('kam', 'ROM', 10, 15, 'Na makatavan’ya ata mate atũme? O ũndũ kũandĩkitwe. A! Kote maseo maũũ ala maetae ũvoo wĩ mũyo wa maũndũ maseo!'),
('kam', 'ROM', 10, 16, 'Ĩndĩ ti onthe meewie ũla ũvoo mũseo. Nũndũ Isaia easya, Mwĩaĩi, ũla wetĩkĩlile ũvoo witũ nũũ?'),
('kam', 'ROM', 10, 17, 'Kwa ũu mũĩkĩĩo wũkaa kwondũ wa kwĩw’a, na kwĩw’a kũkaa kwondũ wa ndeto ya Klĩsto.'),
('kam', 'ROM', 10, 18, 'Ĩndĩ nĩngũkũlya, Matyaawĩw’a? Ĩĩ, nĩ w’o, Wasya woo nĩwatũnganie nthĩ yonthe, Na ndeto syoo syavika itulunĩ sya nthĩ.'),
('kam', 'ROM', 10, 19, 'Ĩndĩ ningũkũlya, Isilaeli matyaamanya? Mbee Mose easya, Ngamwĩw’ĩthya kĩwĩu na asu mate mbaĩ, Ngamũthatya na mbaĩ ĩte na ũmanyi,'),
('kam', 'ROM', 10, 20, 'Na Isaia nĩ ngũmbaũ nene, na easya, Nonekie nĩ andũ mataamantha; Naumila kwa ala mataangũlya.'),
('kam', 'ROM', 10, 21, 'Ĩndĩ kwondũ wa Isilaeli easya, Mũthenya mũima natambũũkĩsye moko makwa andũ matekwĩw’a, ala me na ngananĩo.'),
('kam', 'ROM', 11, 1, 'Nĩngũkũlya indĩ, Ngai nĩwamavetie andũ make? Aiee, kũĩkethĩwe ũu. Nũndũ nyie nakwa nĩ Mũisilaeli, wa ũsyao wa Avalaamu, wa mbaĩ ya Mbenyamini.'),
('kam', 'ROM', 11, 2, 'Ngai ndaamaveta andũ make ala wesĩ kuma tene. Kana mũiĩsĩ ũndũ maandĩko measya ũndũ wa Eliya? Ũndũ emwĩsũva Ngai aivinganĩsya Isilaeli, aiasya:'),
('kam', 'ROM', 11, 3, 'Mwĩaĩi, nĩmooaie athani maku, nĩmaomboie ithembeo syaku; nakwa ndiele nĩ nyioka, nao memantha thayũ wakwa.'),
('kam', 'ROM', 11, 4, 'Ĩndĩ ũsũngĩo wa Ngai wĩmwĩa ata? Nĩtialĩlye andũ ngili. Mũonza, ala mataatulĩlya Mbaali ndu.'),
('kam', 'ROM', 11, 5, 'O na yu ĩvindanĩ yĩĩ kwĩ ũtialo kwĩanana na kũnyuvwa kwa mumo.'),
('kam', 'ROM', 11, 6, 'Ĩndĩ ethĩwa nĩ ũndũ wa mumo ti ũndũ wa meko ĩngĩ: ethĩwa ti ũu mumo nũtw’ĩkĩte ti mumo.'),
('kam', 'ROM', 11, 7, 'Kũilyĩ ata ĩndĩ? Kĩla Isilaeli wamanthaa, ndaakyona; ĩndĩ ala anyuve nĩmakyonie, na ala angĩ nĩmoomiw’e:'),
('kam', 'ROM', 11, 8, 'o ũndũ kũandĩkĩtwe, Ngai nĩwamanengie veva wa too, metho maikone, na matũ maikew’e, kũvika mũthenya ũũ wa ũmũnthĩ.'),
('kam', 'ROM', 11, 9, 'Na Ndaviti easya, Mesa yoo yĩthĩwe mũkwa na kĩtei, Na yĩthĩwe yĩ ũlulutĩkyo, na ũĩvo kwoo:'),
('kam', 'ROM', 11, 10, 'Metho moo maye mbindu, kana maikone, Noimakunamya mũongo woo matukũ onthe.'),
('kam', 'ROM', 11, 11, 'Ĩndĩ nĩngũkũlya, Malulutĩkile mavalũke? Aiee, kũikethiwe ũu: ĩndĩ ũndũ wa kũvalũka kwoo ũtangĩĩo nũvikĩe Andũ‐ma‐mbaĩ‐ingĩ, nĩ kana nao mekĩwe kĩwĩu.'),
('kam', 'ROM', 11, 12, 'Na ethĩwa kũvalũka kwoo nĩ ũthwii kwa nthĩ, na wasyo woo nĩ ũthwii kwa Andũ‐ma‐mbaĩ‐ingĩ; nĩ mbee veanata wĩanĩu woo?'),
('kam', 'ROM', 11, 13, 'Ĩndĩ nĩngũneena nenyu Andũ‐ma‐mbaĩ‐ingĩ. O ũndũ nyie nĩ mũtũmwa kwa Andũ‐ma‐mbaĩ‐ingĩ, nĩtaĩa ũthũkũmi wakwa;'),
('kam', 'ROM', 11, 14, 'nĩ kana ndonye kwa ũndũ o na wĩva kũmew’ithya kĩwĩu ala ma mbai yakwa, na kũtangĩĩa amwe moo.'),
('kam', 'ROM', 11, 15, 'Nũndũ ethĩwa kũvetwa kwoo nĩ kwiw’anithw’a kwa nthĩ. Kwĩtĩkĩlwa kwoo kũkethĩwa nĩ ata, ate o thayũ kuma kikw’ũnĩ?'),
('kam', 'ROM', 11, 16, 'Na ethĩwa mũtuo wa ũsyao wa mbee nĩ mũtheu, no ta ũu mũndo w’onthe naw’o: na ethĩwa kĩtina nĩ kĩtheu, mbonge nasyo no ta ũu.'),
('kam', 'ROM', 11, 17, 'Ĩndĩ ethĩwa mbonge imwe nĩsyatũlilwe, naku, yĩla waĩ mũthata wa kĩthekanĩ, wasamaniw’e katĩ wasyo, na watw’ĩkie mwosi vamwe nasyo wa kĩla kĩtina na ũnou wa ũla mũthata;'),
('kam', 'ROM', 11, 18, 'ndũkekathĩie ĩũlũ wa ila mbonge: ĩndĩ ethĩwa nũkwĩkathĩĩa, tuue ũkuaa kĩtina, ĩndĩ nĩ kĩtina kĩũkuaa we.'),
('kam', 'ROM', 11, 19, 'Ĩndĩ ũkasya, Mbonge nĩsyatũlilwe, nĩ kana nĩsamanw’e vo.'),
('kam', 'ROM', 11, 20, 'Ni w’o; kwa kũlea kwĩtĩkĩla kwoo nĩmatũlilwe, naku ũũngeme ũndũ wa kũĩkĩĩa kwaku. Ndũkethĩwe na kĩlĩko kĩ mĩtũlyo, ĩndĩ ĩthĩwa na w’ĩa:'),
('kam', 'ROM', 11, 21, 'nũndũ ethĩwa Ngai ndaaekana na mbonge ila syai vo, o naku ndakakũeka.'),
('kam', 'ROM', 11, 22, 'Sisya ĩndĩ ũseo na wai wa Ngai: kwa ala mavalũkile, wai; ĩndĩ kwaku, ũseo wa Ngai, ethĩwa ũkekalaa ũseonĩ wake: na ethiwa ti ũu o naku ũkatilwa.'),
('kam', 'ROM', 11, 23, 'Na asu nao, ethĩwa maikekala na kũlea kwĩtĩkĩla kwoo, makasamanw’a: nũndũ Ngai nũtonya kũmasaman’ya ĩngĩ.'),
('kam', 'ROM', 11, 24, 'Nũndũ ethĩwa we nĩwatililwe waumw’a mũthatanĩ, mũthata wa mũtuo wa kĩthekanĩ, na wasamaniw’e ũndũ ũtekawa nthĩnĩ wa mũthata mũseo; ti mbee mũno asu, ala maĩ mbonge kwa mũtuo woo, kũsamanw’a mũthatanĩ ũla woo ene?'),
('kam', 'ROM', 11, 25, 'Nũndũ ndikwenda, ana‐a‐asa, mũlee ũmanya nzama ĩno, nĩ kana mũĩkeyone ta mwĩ oĩ, atĩ wũmũ wa kilungu nĩwamakwatie Isilaeli, kũvika wĩanĩu wa Andũ‐ma‐mbaĩ‐ingĩ wĩvika;'),
('kam', 'ROM', 11, 26, 'na ta ũu Isilaeli onthe makatangĩĩwa: o ũndũ kũandĩkĩtwe, Ũla Mwovosya akooka kũma Saionĩ: Akaathũkya ũndũ ũte wa ũmũkĩa Ngai wume kwa Yakovo:'),
('kam', 'ROM', 11, 27, 'Na ũu nĩw’o ũtianĩo wakwa nao, Yĩla ngamavetea naĩ syoo.'),
('kam', 'ROM', 11, 28, 'Ngalĩ ya ũvoo mũseo, matw’ĩkĩte amaitha kwondũ wenyu: ĩndĩ ngalĩ ya kũnyuvwa, matw’ĩkĩte endwa kwondũ wa ala aasa.'),
('kam', 'ROM', 11, 29, 'Nũndũ mĩthĩnzĩo na wĩtano wa Ngai itialyũlawa.'),
('kam', 'ROM', 11, 30, 'O tondũ inyw’ĩ tene mũtaamwĩw’a Ngai, ĩndĩ yu nĩmwĩw’ĩwe tei nũndu wa kũlea kwĩw’a kwoo,'),
('kam', 'ROM', 11, 31, 'o ta ũu, nao yu matw’ĩkĩte mate ewi, nĩ kana kwondũ wa tei ũla mweew’ĩwe, nao matonye kwĩw’iwa tei.'),
('kam', 'ROM', 11, 32, 'Nũndũ Ngai nũmavingĩĩte onthe vamwe kũvikĩa kũlea kwĩw’a, nĩ kana atonye kũmew’ĩa onthe tei.'),
('kam', 'ROM', 11, 33, 'A! Kyũngũ kya ũthwii wa ũĩ na ũmanyi wa Ngai! Motw’ĩo make matamanyĩka, na nzĩa syake itamanthĩka!'),
('kam', 'ROM', 11, 34, 'Nũndũ nũũ ũla wamanyie kĩlilikano kya Mwĩaĩi? Kana nũũ ũla waĩ mũtai wake?'),
('kam', 'ROM', 11, 35, 'Kana nũũ ũla wambie ũmũnenga kĩndũ, na kũĩvwa ĩngĩ o kyo?'),
('kam', 'ROM', 11, 36, 'Nũndũ syĩndĩ syonthe syumaa kwake, na ĩngĩ syĩ kwondũ wake, na ialũkaa kwake. Ndaĩa nĩ yake tene na tene. Ameni.'),
('kam', 'ROM', 12, 1, 'Nĩmwĩsũva ĩndĩno, ana‐a‐asa makwa, kwondũ wa matei ma Ngai, mwĩnengane mĩĩ yenyu ĩthĩwe nthembo ĩ thayũ, ntheu, ya kũmwendeesya Ngai, naw’o nĩ ũthaithi wenyu waĩlaa.'),
('kam', 'ROM', 12, 2, 'Mũikavw’ananw’e na nthĩ ĩno: ĩndĩ mũalyũkw’e mũtũngwe eũ ilĩkonĩ syenyu, nĩ kana mwĩkuũe ũndũ kũilyĩ kwenda kwa Ngai kũla kũseo na kũla kwĩtĩkĩlĩka na kũla kwĩanĩu.'),
('kam', 'ROM', 12, 3, 'Nũndũ nĩngũneena, kwondũ wa mumo ũla nanengiwe, kana kĩla mũndũ wenyu ndakalilikane mwene ta mũnene mbee wa vala vamwaĩle kũlilikana; ĩndĩ nalilikane eanĩsye, kwĩanana na ũndũ Ngai wamũaĩe kĩla mũndũ mũĩkĩĩo ũndũ wĩana.'),
('kam', 'ROM', 12, 4, 'Nũndũ o tondũ twĩ na mamutha maingĩ mwĩĩnĩ ũmwe, na mamutha onthe mati na wĩa ũmwe:'),
('kam', 'ROM', 12, 5, 'no ta ũu ithyĩ, o na twĩ aingĩ, twĩ mwĩĩ ũmwe nthĩnĩ wa Klĩsto, na ithyonthe twĩ mamutha kĩla ũmwe na ũla ũngĩ.'),
('kam', 'ROM', 12, 6, 'Na twĩ na mĩthĩnzĩo ya mĩthemba mingĩ kwĩanana na ũla mumo twanengiwe, ethĩwa nĩ kwathana, twathane kwĩanana na ũndũ mũĩkĩĩo witũ wĩana:'),
('kam', 'ROM', 12, 7, 'kana ethĩwa nĩ ũthũkũmi, twĩnengane ene ũthũkũminĩ witũ; kana ũla ũmanyĩasya, kũmanyĩsyanĩ kwake;'),
('kam', 'ROM', 12, 8, 'kana ũla ũtaaa, kwa ũtao wake: ũla ũnenganae, nanenganae na ũlau; ũla walanasya, nĩalanasye na kĩthito; ũla ũmwĩw’ĩaa ũngĩ teĩ, namwĩw’ĩae na ũtanu.'),
('kam', 'ROM', 12, 9, 'Wendo ndũkethĩwe na wangangan’yo. Menai kĩla ũthũku; lũmyai ũndũ ũseo.'),
('kam', 'ROM', 12, 10, 'Wendonĩ wa ana‐a‐asa, ĩthĩwai na wendo mũuu ene kwa ene; ndaĩanĩ, mataĩei ala angĩ mbee;'),
('kam', 'ROM', 12, 11, 'ũthangaaunĩ, mũte aleelu; mũvyũvĩte mavevanĩ menyu; mũkĩmũthũkũma Mwĩaĩi;'),
('kam', 'ROM', 12, 12, 'mũkĩtana wĩkwatyonĩ; mũkyũmĩĩsya mathĩnanĩ; mũkĩkala na ũlũmu mboyanĩ;'),
('kam', 'ROM', 12, 13, 'mũkĩnengane kwondũ wa mavata ma atheu; mũkĩthokya aeni na ũlau.'),
('kam', 'ROM', 12, 14, 'Maathimei ala mamũthĩnasya; athimai, o na mũikaumanĩe.'),
('kam', 'ROM', 12, 15, 'Tanai vamwe na ala meũtana; ĩai na ala mekũĩa.'),
('kam', 'ROM', 12, 16, 'Ĩthĩwai na kĩlilikano kĩmwe ene kwa ene. Mũikalilikane maũndũ ma mĩtũlyo, ĩndĩ ĩtheesyei maũndũnĩ ala ma wĩnyivyo. Mũiketale ene ta mwĩ oĩ.'),
('kam', 'ROM', 12, 17, 'Mũikekũle kwa mũndũ o na wĩva. Lilikanaai maũndũ ala maseo mbee wa metho ma andũ onthe.'),
('kam', 'ROM', 12, 18, 'Ethĩwa nũtonyeka, kwa ngalĩ ĩla yenyu, mwĩthĩwe na mũuo na andũ onthe.'),
('kam', 'ROM', 12, 19, 'Mũikeĩvanĩsye, endwa makwa, ĩndĩ ekeaĩ ũthatu wa Ngai ũthei; nũndũ nĩkũandĩkĩtwe, Ũĩvanĩsyo nĩ wakwa; ngaĩvanĩsya, easya ũu Ngai.'),
('kam', 'ROM', 12, 20, 'Ĩndĩ ethĩwa mũmaitha waku e na nzaa, mũathĩsye; ethĩwa e na waũni, mũnenge kya ũnyw’a; nũndũ kwa kwĩka ũu ũkamũmbĩĩa makaa ma mwaki mũtwenĩ wake.'),
('kam', 'ROM', 12, 21, 'Mũikakĩlw’e vinya nĩ ũthũku, ĩndĩ kĩlyai ũthũku vinya na ũseo.'),
('kam', 'ROM', 13, 1, 'Kĩla mũndũ nĩethĩwe e mwĩwi wa ala me na ũkũmũ: nũndũ kũi ũkũmũ ũtaumite kwa Ngai; na mokũmũ ala me kw’o nĩmatwiwe nĩ Ngai.'),
('kam', 'ROM', 13, 2, 'Kwondũ wa ũu ũla ũleaa kwĩw’a ũkũmũ ũsu, aleaa kwĩw’a ũtw’ĩo wa Ngai: na ala maleaa kwĩw’a makeeyoseaa ũsilĩlo ene.'),
('kam', 'ROM', 13, 3, 'Nũndũ ala masumbĩkĩte maitĩsasya andũ kwondũ wa meko maseo, ĩndĩ no kwondũ wa meko mathũku. Na nũkwenda kwĩkala ũte na w’ĩa kwa ũla wĩ na ũkũmũ? Ĩkaa ũseo, na ũkoosaa nguma kuma kwake:'),
('kam', 'ROM', 13, 4, 'nũndũ nĩ mũthũkũmi wa Ngai kwaku kwondũ wa ũseo. Ĩndĩ ethĩwa wĩkaa maũndũ ala mathũku, ĩthĩwa na w’ĩa; nũndũ ndakuaa ũvyũ mana: nũndũ nĩ mũthũkũmi wa Ngai mũĩvanĩsya wa ũthatu kwa ũla wĩkaa naĩ.'),
('kam', 'ROM', 13, 5, 'Kwondũ wa ũu, mũvaka mwĩthĩwe ewi, ti ũndũ wa ũthatu w’oka, ĩndĩ naw’o kwondũ wa wasya wa ngoo.'),
('kam', 'ROM', 13, 6, 'Nũndũ kwondũ wa ũu nĩmumasya kotĩ; nũndũ nĩ athũkũmi ma Ngai, mekalaa mavinda onthe ũndũnĩ o ũsu.'),
('kam', 'ROM', 13, 7, 'Nengai onthe kĩla kyaĩle: koti kwa ũla waĩlwe nĩ kũmĩw’a kotĩ: kumya mũvothi kwa ũla waĩlwe nĩ kumĩw’a mũvothi; w’ĩa kwa ũla waĩlwe nĩ kũkĩwa; ndaĩa kwa ũla waĩlwe nĩ kũtaĩwa.'),
('kam', 'ROM', 13, 8, 'Mũĩkethĩwe mwi thiĩ na mũndũ wa kĩndũ o na kĩva kyonthe, ate o kwendana inyw’ĩ kwa inyw’ĩ: nũndũ ũla ũmwendaa ũngĩ nĩwĩanĩsye ĩla mĩao.'),
('kam', 'ROM', 13, 9, 'Kwondũ wa ũu, Ndũkalaalae, Ndũkoae, Ndũkoye, Ndũkakĩw’ĩe kĩndũ kya ũngĩ ĩtomo, na ethĩwa kwĩ mwĩao ũngĩ, ũtalanĩlwe ndetonĩ ĩno, Mwende ũngĩ ũndũ wĩyendete mwene.'),
('kam', 'ROM', 13, 10, 'Wendo ndwĩkaa naĩ kwa ũngĩ; kwondũ wa ũu wendo nĩ wĩanĩsyo wa ĩla mĩao.'),
('kam', 'ROM', 13, 11, 'Na ũu, tũkĩmanya ĩvinda, kana yuyu kyathĩ nĩ kĩviku kya kũamũka kuma toonĩ: nũndũ yu ũtangĩĩo wĩ vakuvĩ naitũ kwĩ yĩla tweetĩkĩlile mbee.'),
('kam', 'ROM', 13, 12, 'Utukũ nĩ mũendu mũno, mũthenya nũthengeee: tumye ĩndĩ twĩkye kũasa mawĩa ma kĩvindu, na twĩkĩe mĩio ya kaũ ya kyeni.'),
('kam', 'ROM', 13, 13, 'Tũkinyae ũndũ kwaĩle, ta twĩ mũthenya; ti mbokanĩ itaĩle na ũthenginĩ, ti mĩmeonĩ mĩthũku na ũlaalainĩ, ti kũtetanĩ na kĩwĩunĩ.'),
('kam', 'ROM', 13, 14, 'Ĩndĩ ĩvw’ĩkei Mwĩaĩi Yesũ Klĩsto, na ũndũ wa mwĩĩ, mũikese kũlilikana kwĩka mawendi maw’o.'),
('kam', 'ROM', 14, 1, 'Ĩndĩ we ũla wĩ na mũĩkĩĩo mũnini mwĩtĩkĩlei, ĩndĩ ti kwa kũkananĩa maũndũ ala me nzika.'),
('kam', 'ROM', 14, 2, 'Mũndũ ũmwe e na mũĩkĩĩo wa kũya lĩu wa mĩthemba yonthe: ĩndĩ ũla mũvũthũ aĩsaa lĩu wa mũũndanĩ w’oka.'),
('kam', 'ROM', 14, 3, 'Ũla ũĩsaa ndakamũvũthye ũla ũtaĩsaa; na ũla ũtaĩsaa nake ndakamũsilĩle ũsu ũĩsaa: nũndũ Ngai nũmwĩtĩkĩlĩte.'),
('kam', 'ROM', 14, 4, 'We wĩ ũũ ũsilĩlaa mũthũkũmi wa ũngĩ? Kwa vwana wake mwene nũnũkũũngama kana nũnũũvalũka. Ni w’o, akaũngamw’a; nũndũ Mwĩaĩi e na vinya wa kũmũũngamya.'),
('kam', 'ROM', 14, 5, 'Mũndũ ũmwe nũtaĩaa mũthenya ũmwe kwi ũngĩ: mũndũ ũngĩ ataĩaa mĩthenya yonthe ũndũ ũmwe. Kĩla mũndũ namanyĩthw’e vyũ kĩlĩkonĩ kyake mwene.'),
('kam', 'ROM', 14, 6, 'Ũla ũsũvĩaa mũthenya, asũvĩaa kwondũ wa Mwĩaĩi: na ũla ũĩsaa, aĩsaa kwa Mwĩaĩi, nũndũ nũmũtũngĩaa Ngai mũvea; na ũla ũlea kũya, kwa Mwĩaĩi ndaĩsaa, na amũnengae Ngai mũvea.'),
('kam', 'ROM', 14, 7, 'Nũndũ vai ũmwe wa ithyĩ wĩkalaa thayũ kwondũ wake mwene, o na vai ũla ũkusaa kwondũ wake mwene.'),
('kam', 'ROM', 14, 8, 'Nũndũ ethĩwa nĩtũkwĩkala thayũ, twĩĩkala kwondũ wa Mwĩaĩi; kana ethĩwa nĩtũũkw’a, twĩkw’a kwondũ wa Mwĩaĩi: kwondũ wa ũu ethĩwa twĩĩkala thayũ, kana ethĩwa nĩ kũkw’a, twĩ ma Mwĩaĩi.'),
('kam', 'ROM', 14, 9, 'Nũndũ kwondũ wa ũu Klĩsto nĩwakwie na eethĩwa thayũ ĩngĩ, nĩ kana ethĩwe Mwĩaĩi wa ala akw’ũ na wa ala me thayũ.'),
('kam', 'ROM', 14, 10, 'Ĩndĩ we, wĩsilĩla mwana‐a‐au nũndũ wa ki? Kana ĩngĩ we, wĩvũthĩsya mwana‐a‐au kĩ? Nũndũ ithyonthe tũkaũngama mbee wa kĩvĩla kya sila kya Ngai.'),
('kam', 'ROM', 14, 11, 'Nũndũ nĩkũandĩkĩtwe, O ũndũ nĩ thayũ nyie, easya ũu Mwĩaĩi, mbee wakwa kĩla ĩu yĩkatulya ndu, Na kĩla ũĩmĩ ũkaumbũla mbee wa Ngai.'),
('kam', 'ROM', 14, 12, 'Kwa ũu ĩndĩ kĩla ũmwe waitũ akaumya ũvoo wake mbee wa Ngai.'),
('kam', 'ROM', 14, 13, 'Kwondũ wa ũu ĩndĩ kũikethĩwe ĩngĩ kũsilĩlana ithyĩ kwa ithyĩ: ĩndĩ nĩkwaĩle mũsile ũũ, kana mũndũ ndakamwiĩe mwana‐a‐ĩthe kya ũmũlulutĩkya, kana kya ũmũvalũkya.'),
('kam', 'ROM', 14, 14, 'Nĩnĩsĩ, na ndi na nzika nthĩnĩ wa Mwĩaĩi Yesũ, kana vai kĩndũ kĩvuku ũndũ wakyo kyoka: ate o kwa ũla wonaa kĩndũ nĩ kĩvuku, kwa ũsu kĩndũ kyu nĩ kĩvuku.'),
('kam', 'ROM', 14, 15, 'Nũndũ mwana‐a‐au eew’a woo kwondũ wa lĩu waku, ndũendaa ĩngĩ wendonĩ. Ndũkamwanange na lĩu waku ũla Klĩsto wakwie kwondũ wake.'),
('kam', 'ROM', 14, 16, 'Ndũkatume ĩndĩ ũseo waku ũwetwa naĩ:'),
('kam', 'ROM', 14, 17, 'nũndũ ũsumbĩ wa Ngai ti kũya na ti kũnyw’a, ĩndĩ nĩ ũlũngalu na mũuo na ũtanu nthĩnĩ wa Veva Mũtheu.'),
('kam', 'ROM', 14, 18, 'Nũndũ ũla ũmũthũkũmaa Klĩsto maũndũnĩ aa nũmwendeeasya Ngai, na nĩwĩtĩkĩlawa nĩ andũ.'),
('kam', 'ROM', 14, 19, 'Kwondũ wa ũu ĩndĩ, tũatĩĩe maũndũ ala ma mũuo, na maũndũ ala matumaa kĩla ũmwe aka ũngĩ.'),
('kam', 'ROM', 14, 20, 'Mũikanange wĩa wa Ngai kwondũ wa lĩu. Nĩ w’o syĩndũ syonthe nĩ ntheu; ĩndĩ nĩ ũthũku kwa ũsu ũĩsaa na ũlulutĩkyo.'),
('kam', 'ROM', 14, 21, 'Nĩ ũseo kũlea kũya nyama, kana kũnyw’a mbinyu, kana kwĩka ũndũ o na wĩva ũtuma mwana‐a‐au alulutĩka.'),
('kam', 'ROM', 14, 22, 'Mũĩkĩĩo ũla wĩ naw’o ĩthĩwa naw’o kwondũ waku mwene mbee wa Ngai. Nĩ mũtanu ũsu ũla ũtesilĩla mwene ũndũnĩ ũsu ũwĩtĩkĩlĩte.'),
('kam', 'ROM', 14, 23, 'Ĩndĩ ethĩwa mũndũ eya e na nzika nĩmũsilĩle kwĩthĩwa nĩ mũvĩtan’ya, nũndũ eya ate na mũĩkĩĩo; na ũndũ o na wĩva ũtaumaa mũĩkĩĩonĩ nĩ naĩ.'),
('kam', 'ROM', 15, 1, 'Ĩndĩ ithyĩ ala twĩ na vinya nĩtwaĩlwe nĩ kũkua mawonzu ma ala mate na vinya, na tũikeyendeesye ene.'),
('kam', 'ROM', 15, 2, 'Kĩla ũmwe wa ithyĩ namwendeesye ũngĩ kwa ũla ũseo, kwondũ wa kwakwa.'),
('kam', 'ROM', 15, 3, 'Nũndũ Klĩsto nake ndaaĩyendeesya mwene; ĩndĩ, tondũ kũandĩkĩtwe, Ivũthya sya ala makũvũthisye nĩsyambalũkile.'),
('kam', 'ROM', 15, 4, 'Nũndũ maũndũ o na meva ala mambie kũandĩkwa, nĩmaandĩkiwe nũndũ wa kũtũmanyĩasya, nĩ kana ũndũ wa wũmĩĩsyo na ũkiakisyo wa maandĩko twĩthĩwe na wĩkwatyo.'),
('kam', 'ROM', 15, 5, 'Na Ngai wa wũmĩĩsyo na wa ũkiakisyo namũnenge kwĩthĩwa na kĩlilikano kĩmwe kwondũ wa Klĩsto Yesũ:'),
('kam', 'ROM', 15, 6, 'nĩ kana kwa ngoo ĩmwe na kanyw’a ũmwe mũtonye kũmũtaĩa Ngai, Ĩthe wa Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', 'ROM', 15, 7, 'Kwondũ wa ũu ĩtĩkĩlanai ene kwa ene, o ũndũ Klĩsto nake wamwĩtĩkĩlile inyw’ĩ, nĩ kana Ngai ataĩwe.'),
('kam', 'ROM', 15, 8, 'Nũndũ nĩneena atĩ Klĩsto nĩwatwiwe mũthũkũmi wa nzaĩko kwondũ wa ũla w’o wa Ngai, nĩ kana alũlũmĩlye ala matho manengiwe aasa,'),
('kam', 'ROM', 15, 9, 'na nĩ kana Andũ‐ma‐mbaĩ‐ingĩ mamũkathe Ngai nũndũ wa tei wake; o ũndũ kũandĩkĩtwe, Kwondũ wa ũu ngakũtaĩa we kwa Andũ‐ma‐mbaĩ‐ingĩ, Na ngakumya syĩtwa yaku.'),
('kam', 'ROM', 15, 10, 'Na ĩngĩ easya, Tanai, inyw’ĩ Andũ‐ma‐mbaĩ‐ingĩ, vamwe na andũ make.'),
('kam', 'ROM', 15, 11, 'Na ĩngĩ, Mũkumyei Mwĩaĩi, inyw’onthe Andũ‐ma‐mbaĩ‐ingĩ; Na ngo syonthe sya andũ nimũtaĩe.'),
('kam', 'ROM', 15, 12, 'Na ĩngĩ, Isaia easya, Kũkeethĩwa kĩtina kya Yese, Nake ũla wĩũkĩla kũsumbĩka Andũ‐ma‐mbaĩ‐ingĩ; Nĩwe Andũ‐ma‐mbaĩ‐ingĩ makamwĩkwatya.'),
('kam', 'ROM', 15, 13, 'Na Ngai wa wĩkwatyo namusũsye inyw’ĩ na ũtanu w’onthe na mũuo kwondũ wa kwĩtĩkĩla, nĩ kana mwĩthĩwe na wĩkwatyo mwingĩ, vinyanĩ wa Veva Mũtheu.'),
('kam', 'ROM', 15, 14, 'Nakwa mwene, ana‐a‐asa makwa, nĩniĩkũthĩtw’e ũvoo wenyu, kana inyw’ĩ ene mũsiwe nĩ ũseo, na musũĩtwe nĩ ũmanyi w’onthe, na ĩngĩ nĩmũtonya kũtaana ene kwa ene.'),
('kam', 'ROM', 15, 15, 'Ĩndĩ namũandĩkĩa inywĩ na ũnyiau mũnene ilungunĩ ĩmwe sya valũa ũũ, ta kũmũlilikan’ya ĩngĩ, nũndũ wa mumo ũla nanengiwe nĩ Ngai,'),
('kam', 'ROM', 15, 16, 'kana nĩthĩwe mũthũkũmi wa Klĩsto Yesũ kwa Andũ‐ma‐mbaĩ‐ingĩ, ngĩthũkũma ũla ũvoo mũseo wa Ngai wĩa wa ũthembi, nĩ kana kũthembwa kwa Andũ‐ma‐mbaĩ‐ingĩ kwĩtĩkĩlĩke, kwa kũvathanw’a nĩ Veva Mũtheu.'),
('kam', 'ROM', 15, 17, 'Ĩndĩ nĩ na wĩkathĩĩi wakwa nthĩnĩ wa Klĩsto Yesũ maũndũnĩ ma Ngai.'),
('kam', 'ROM', 15, 18, 'Nũndũ nditata kũneena ũvoo wa maũndũ o na meva onthe ate o ala Klĩsto wekĩle vala nĩĩ, kũtuma Andũ‐ma‐mbaĩ‐ingĩ methĩwa ewi kwondũ wa ndeto o na meko,'),
('kam', 'ROM', 15, 19, 'vinyanĩ wa syama na moseng’yo, vinyanĩ wa Veva Mũtheu; o ũndũ kuma Yelusaleme, na kũũ ndee kũvika o na Iluliko, nĩtavanĩtye kw’onthe vyũ ũvoo mũseo wa Klĩsto;'),
('kam', 'ROM', 15, 20, 'ĩĩ, nĩngwĩthangaasya kũtavan’ya ũla ũvoo mũseo, ti vala syĩtwa ya Klĩsto yambie kũtavanw’a, nĩ kana ndikake ĩũlũ wa wambĩlĩlyo wa wako wa mũndũ ũngi;'),
('kam', 'ROM', 15, 21, 'ĩndĩ, o tondũ kũandĩkĩtwe, Nĩmakona, asu ala mataatavw’a ũvoo wake, Na asu ala mataaĩw’a nĩmakamanya.'),
('kam', 'ROM', 15, 22, 'Maũndũ asu nĩmo manziĩĩe mavinda maingĩ ndikoke kwenyu:'),
('kam', 'ROM', 15, 23, 'ĩndĩ yu, nũndũ vati ũtheĩ ũngĩ nthĩ ĩno, na kwa kwĩthĩwa myaka mingĩ nĩnaĩ na mea ma kũka kwenyu,'),
('kam', 'ROM', 15, 24, 'ĩvinda o na yĩva yĩla ngathĩ Sivania (nũndũ nĩngwĩkwatya kũmwona inyw’ĩ kyalonĩ kyakwa, na kumaaw’a nĩ inyw’ĩ, namina kũya mea nenyu)—'),
('kam', 'ROM', 15, 25, 'ĩndĩ yuyu nĩngũthi Yelusaleme, ngithũkũma ala atheu.'),
('kam', 'ROM', 15, 26, 'Nũndũ andũ ma Masetonia na Akaia nĩmendeew’e nĩ kumya ũelo kwondũ wa atheu me Yelusaleme ala ngya.'),
('kam', 'ROM', 15, 27, 'Ĩĩ, nĩmendeew’e; na ĩngĩ me thiĩ nao. Nũndũ ethĩwa Andũ‐ma‐mbaĩ‐ingĩ matw’ĩtwe osi vamwe nao ma syĩndũ syoo sya veva, me thiĩ nao kũmatethya syĩndũni ĩla sya mwĩĩ.'),
('kam', 'ROM', 15, 28, 'Ĩndĩ yĩla nĩanĩsya ũndũ ũsu, namina kũtwaa mĩthinzĩo ĩla yaumĩtw’e ĩmavikĩe nesa, ngauma kw’o na ngavĩtĩla kwenyu nĩthĩ Sivania.'),
('kam', 'ROM', 15, 29, 'Na nĩnĩsĩ kana, yĩla nĩũka kwenyu, ngooka na wĩanĩu wa ũathimo wa Klĩsto.'),
('kam', 'ROM', 15, 30, 'Ĩndĩ nĩmwĩsũva mũno, ana‐a‐asa, kwondũ wa Mwĩaĩi waitũ Yesũ Klĩsto, na kwondũ wa wendo wa ũla Veva, kana mwĩthing’ĩĩsye vamwe nakwa mboyanĩ syenyu kwa Ngai kwondũ wakwa;'),
('kam', 'ROM', 15, 31, 'kana ndangĩĩwe nyie kwa ala matew’aa ma Yutia, na nĩ kana ũthũkũmi wakwa ũla nĩ naw’o Yelusaleme wĩtĩkĩlĩke kwa atheu;'),
('kam', 'ROM', 15, 32, 'nĩ kana nĩũka kwenyu na ũtanu kwondũ wa kwenda kwa Ngai, na kwona ũthũmũo vamwe nenyu.'),
('kam', 'ROM', 15, 33, 'Na Ngai wa mũuo nĩethĩwe vamwe nenyu inyw’onthe. Ameni.'),
('kam', 'ROM', 16, 1, 'Nĩngũmũĩkĩĩthya kwenyu Voevi mwĩĩtu‐a‐asa waitũ, nake nĩ mũthũkũmi wa ĩkanisa yĩla yĩ Kengalea:'),
('kam', 'ROM', 16, 2, 'nĩ kana mũmwose nthĩnĩ wa Mwĩaĩi, o ũndũ atheu maĩlwe, na ĩngĩ mũmũtethye ũndũnĩ o na wĩva ũla wĩĩthĩwa e na vata naw’o kwenyu: nũndũ nake mwene aĩ mũtethya wa aingĩ, o na wakwa mwene.'),
('kam', 'ROM', 16, 3, 'Ngethesyai Vilisika na Akwila atethya ma wĩa vamwe nakwa nthĩnĩ wa Klĩsto Yesũ,'),
('kam', 'ROM', 16, 4, 'nao nĩmeeyũmbanĩtye kũtilwa mĩtwe yoo kwondũ wa thayũ wakwa; nĩ na mũvea kwoo, na tii nyie nyioka, ĩndĩ makanisa onthe ma Andũ‐ma‐mbaĩ‐ingĩ vamwe nakwa:'),
('kam', 'ROM', 16, 5, 'na ngethesyai ĩkanisa yĩla yĩ nyũmba kwoo. Ngethesyai Evaeneto mwendwa wakwa, nake nĩ ũsyao wa mbee wa nthĩ ya Asia kwa Klĩsto.'),
('kam', 'ROM', 16, 6, 'Ngethesyai Meli, ũla watethisye wĩa mwingĩ kwondũ wenyu.'),
('kam', 'ROM', 16, 7, 'Ngethesyai Andeloniko na Yunia, andũ ma mbaĩ yakwa, nao maĩ ove vamwe nakwa, nao nĩmawetawa nesa nĩ atũmwa, o na ĩngĩ maĩ nthĩnĩ wa Klĩsto mbee wakwa.'),
('kam', 'ROM', 16, 8, 'Ngethesyai Ambiliato, mwendwa wakwa nthĩnĩ wa Mwĩaĩi.'),
('kam', 'ROM', 16, 9, 'Ngethesyai Ulivano, mũtethya wa wĩa vamwe naitũ nthĩnĩ wa Klĩsto, na Sitakisi mwendwa wakwa.'),
('kam', 'ROM', 16, 10, 'Ngethesyai Avele ũla mwĩtĩkĩle nthĩnĩ wa Klĩsto. Ngethesyai ala ma nyũmba ya Alisitovulo.'),
('kam', 'ROM', 16, 11, 'Ngethesyai Elotioni wa mbaĩ yakwa. Ngethesyai ala ma nyũmba ya Nalikiso, asu ala me nthĩnĩ wa Mwĩaĩi.'),
('kam', 'ROM', 16, 12, 'Ngethesyai Tilivena na Tilivosa, ala matethasya wĩa wa Mwĩaĩi. Ngethesyai Velisi mwendwa, ũla watethisye wĩa mũno nthĩnĩ wa Mwĩaĩi.'),
('kam', 'ROM', 16, 13, 'Ngethesyai Luvusi, mũnyuve nthĩnĩ wa Mwĩaĩi, na inyia wake, nake nĩ mwaitũ.'),
('kam', 'ROM', 16, 14, 'Ngethesyai Asingilito, Velekona, Elime, Vatelova, Elima, na ana‐a‐asa ala me vamwe nao.'),
('kam', 'ROM', 16, 15, 'Ngethesyai Viloloko na Yulĩa, Neleo na mwĩĩtu‐a‐inyia, na Olimba, na atheu onthe ala me vamwe nao.'),
('kam', 'ROM', 16, 16, 'Kethan’yai ene kwa ene na ũmumunyano mũtheu. Makanisa onthe ma Klĩsto nĩmamũkethya.'),
('kam', 'ROM', 16, 17, 'Ĩndĩ nĩmwĩsũva mũno, ana‐a‐asa, maketeeei asu ala maetae motaanĩsyo na molulutĩkyo, matosana na ũmanyĩsyo ũla mwamanyĩiw’e: na ĩthyũũei na kũmatia.'),
('kam', 'ROM', 16, 18, 'Nũndũ ala mailyĩ ta asu maimũthũkũmaa Mwĩaĩi waitũ Klĩsto, ĩndĩ no mavu moo ene; na ĩngĩ kwondũ wa ndeto syoo nduu na sya kwendeesya nĩmakengaa andũ ala mate na ũthũku.'),
('kam', 'ROM', 16, 19, 'Nũndũ wĩwi wenyu nũũtũnganĩte kwa andũ onthe. Na kwondũ wa ũu nĩtanaa nũndũ wenyu: ĩndĩ nĩngwenda mwĩthĩwe mwĩ oĩ kwa maũndũ ala maseo, na mwĩthĩwe mũte na ũmanyi kwa ala mathũku.'),
('kam', 'ROM', 16, 20, 'Na Ngai wa mũuo akamũtumba Satani ungu wa nyaĩĩ syenyu mĩtũkĩ. Mumo wa Mwĩaĩi waitũ Yesũ Klĩsto nĩwĩthĩwe nenyu.'),
('kam', 'ROM', 16, 21, 'Timotheo mũtethya wa wĩa vamwe nakwa nĩwamũkethya; na Lukio na Yasoni na Sosiveteli ma mbaĩ yakwa.'),
('kam', 'ROM', 16, 22, 'Nyie Telitio, ũla waandĩka valũa ũũ, nĩngũmũkethya nthĩnĩ wa Mwĩatĩ.'),
('kam', 'ROM', 16, 23, 'Kaio mũthokya wakwa, na wa ĩkanisa yonthe, nĩwamũkethya. Elasito, ũla mũsũvĩi wa mbesa sya ndũa, nĩwamũkethya, na Kwalito mwana‐a‐asa.'),
('kam', 'ROM', 16, 24, '(Mumo wa Mwĩaĩi waitũ Yesũ Klĩsto nĩwĩthĩwe na inyw’onthe. Ameni.)'),
('kam', 'ROM', 16, 25, 'Na yu kwa ũla ũtonya ũmũlũlũmĩlya, kwĩanana na ũvoo mũseo wakwa na ũtavan’yo wa Yesũ Klĩsto, kwĩanana na ũvuan’yo wa ĩla nzama yavithĩtwe vyũ mavindanĩ ma tene tene,'),
('kam', 'ROM', 16, 26, 'ĩndĩ ĩvinda yĩĩ nĩyonanĩtw’e maandĩkonĩ ma athani, kwĩanana na mwĩao wa Ngai wa tene na tene, nĩmanyĩthĩtw’e mbaĩ syonthe kũvikĩa wĩwi wa mũĩkĩĩo:'),
('kam', 'ROM', 16, 27, 'kwa Ngai ũla mũĩ weka, nthĩnĩ wa Yesũ Klĩsto, kwake kwĩthĩwe ndaĩa tene na tene. Ameni.'),
('kam', '1CO', 1, 1, 'Vaulo, ũla wetiwe ethĩwe mũtũmwa wa Yesũ Klĩsto kwondũ wa kwenda kwa Ngai, na Sosithene mwana‐a‐asa waitũ,'),
('kam', '1CO', 1, 2, 'valũa ũũ witũ ũyĩvikĩe ĩkanisa ya Ngai yĩla yĩ Kolintho, asũ mavathanĩtw’e nthĩnĩ wa Klĩsto Yesũ, meetiwe methĩwe atheu, vamwe na onthe ma kĩla vandũ ala mekaĩlaa syĩtwa ya Mwĩaĩi waitũ Yesũ Klĩsto, Mwĩaĩi woo na waitũ:'),
('kam', '1CO', 1, 3, 'Mumo nĩwĩthĩwe nenyu na mũuo kuma kwa Ngai Asa waitũ na kwa Mwĩaĩi Yesũ Klĩsto.'),
('kam', '1CO', 1, 4, 'Nĩmũtũngĩaa Ngai wakwa mũvea matukũ onthe kwondũ wenyu, nũndũ wa mumo wa Ngai ũla mwanengiwe nthĩnĩ wa Klĩsto Yesũ;'),
('kam', '1CO', 1, 5, 'nĩkwĩthĩwa maũndũnĩ onthe nĩmũthuĩtw’e nthĩnĩ wake, ndetonĩ syonthe na ũmanyinĩ w’onthe;'),
('kam', '1CO', 1, 6, 'o tondũ ũkũsĩ wa Klĩsto walũlũmĩlw’e nthĩnĩ wenyu:'),
('kam', '1CO', 1, 7, 'ũkethĩa mũtiũnyivw’a nĩ mũthĩnzĩo o na wĩva w’onthe; mũkyeteela kwonanw’a kwa Mwĩaĩi waitũ Yesũ Klĩsto;'),
('kam', '1CO', 1, 8, 'nake nĩwe ũkamũlũlũmilya kũvĩka mũminũkĩlyo, nĩ kana mwĩthĩwe mũtavinganĩĩka mũthenya wa Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', '1CO', 1, 9, 'Ngai e kĩthito, ũla nthĩnĩ wake mweetiwe mũlike mũambanĩ wa Mwana wake Yesũ Klĩsto, Mwĩaĩi waitũ.'),
('kam', '1CO', 1, 10, 'Na yu nĩmwĩsũva, ana‐a‐asa, syĩtwanĩ ya Mwĩaĩi waitũ Yesũ Klĩsto, nĩ kana inyw’onthe mũneene ũndũ o ũmwe, na nĩ kana kũikethĩwe ũtilĩkangano katĩ wenyu; ĩndĩ nĩ kana mũlũmanw’e vamwe kĩsũanĩonĩ kĩmwe na mũĩkĩanĩonĩ ũmwe.'),
('kam', '1CO', 1, 11, 'Nũndũ nĩnĩmanyĩthĩtw’e ũndũ wenyu, ana‐a‐asa, nĩ ala ma nyũmba ya Kiloe, kana kwĩ mateta katĩ wenyu.'),
('kam', '1CO', 1, 12, 'Na yu ũla ngũneena nĩ atĩ kĩla mũndũ wenyu easya, Nyie nĩ wa Vaulo; nakwa nĩ wa Avolo; nakwa nĩ wa Keva; nakwa nĩ wa Klĩsto.'),
('kam', '1CO', 1, 13, 'Klĩsto nĩ mũaan’ye? Vaulo nĩwe wambiwe kwondũ wenyu? Kana nĩmwavatisĩwe syĩtwanĩ ya Vaulo?'),
('kam', '1CO', 1, 14, 'Nĩmũtũngĩa Ngai mũvea nĩkwĩthĩwa ndyaavatĩsa ũmwe wenyu, ate o Kilisivo na Kaio;'),
('kam', '1CO', 1, 15, 'nĩ kana mũndũ o na wĩva ndakasye kana mwavatisiwe syĩtwanĩ yakwa.'),
('kam', '1CO', 1, 16, 'Na ĩngĩ navatĩsie ala me nyũmba ya Sitevana: eka asu, ndyĩsĩ ethĩwa nĩnavatisie ũngĩ.'),
('kam', '1CO', 1, 17, 'Nũndũ Klĩsto ndaandũma kũvatisa, ĩndĩ nĩ kana nĩtavan’ye ũla ũvoo mũseo: ti ũini wa ndeto, nĩ kana ngelan’yo ya Klĩsto ndĩkatuwe ya mana.'),
('kam', '1CO', 1, 18, 'Nũndũ ndeto ya ĩla ngelan’yo nĩ ũtumanu kwa ala maaa; ĩndĩ kwa ithyĩ ala atangĩĩe, nĩ vinya wa Ngai.'),
('kam', '1CO', 1, 19, 'Nũndũ nĩkũandĩkĩtwe, Ngaananga ũĩ wa ala oĩ, Na ũmanyi wa ala me na kĩlĩko, ngoolea.'),
('kam', '1CO', 1, 20, 'Aĩva ũla mũĩ? Aĩva mũandĩkĩ? Aĩva ũla mũkananĩi wa ĩvinda yĩĩ? Ngai ndaatw’ĩkĩthya ũĩ wa nthĩ ũtumanũ?'),
('kam', '1CO', 1, 21, 'Nĩkwĩthĩwa ũĩnĩ wa Ngai, nthĩ, kwondũ wa ũĩ wayo, ndĩaamũmanya Ngai, Ngai endie kũmatangĩĩa asu metĩkĩlaa kwondũ wa ũtumanu wa ũvoo ũla ũtavanaw’a.'),
('kam', '1CO', 1, 22, 'Nĩkwĩthĩwa Ayutĩ mendaa syama, na Akilili mamanthaa ũĩ:'),
('kam', '1CO', 1, 23, 'ĩndĩ ithyĩ tũtavanasya Klĩsto ũla wambiwe, kwa Ayuti nĩ ũndũ wa ũlulutĩkya, na kwa Andũ‐ma‐mbaĩ‐ĩngĩ nĩ ũtumanũ;'),
('kam', '1CO', 1, 24, 'ĩndĩ kwa ala metawa, ethĩwa nĩ Ayuti kana Akiliki, nĩ Klĩsto vinya wa Ngai na ũi wa Ngai.'),
('kam', '1CO', 1, 25, 'Nĩkwĩthĩwa ũtumanu wa Ngai wĩ ũĩ kwĩ andũ; na wonzu wa Ngai wĩ vinya kwĩ andũ.'),
('kam', '1CO', 1, 26, 'Nũndũ sisyai kwĩtwa kwenyu, ana‐a‐asa, kana ti aingĩ ala me na ũĩ wa mwĩĩ, ti aingĩ me na vinya, ti aingĩ me nguma, metawa:'),
('kam', '1CO', 1, 27, 'ĩndĩ Ngaĩ nĩwanyuvie maũndũ ma ũtumanu ma nthĩ, nĩ kana atonye kũmasonokya asu oĩ; na Ngai nĩwanyuvie syĩndũ mbonzu sya nthĩ, nĩ kana atonye kwisonokya syĩndũ ila syĩ vinya;'),
('kam', '1CO', 1, 28, 'na syĩndũ sya nthĩ ite ndaĩa, na syĩndũ ila ivũthaw’a, nĩsyo Ngai wanyuvie, ĩĩ, na syĩndũ ila ite vo, nĩ kana atonye kwitw’ĩkĩthya sya mana syĩndũ ila syĩ vo:'),
('kam', '1CO', 1, 29, 'kũikethĩwe ũla wĩ na mwĩĩ o na wĩva w’onthe kwĩkathĩĩa mbee wa Ngai.'),
('kam', '1CO', 1, 30, 'Ĩndĩ nũndũ wake inyw’ĩ mũnengetwe kwĩthĩwa nthĩnĩ wa Klĩsto Yesũ, ũla ũtw’ĩtwe kwitũ ũĩ ũla wumaa kwa Ngai, na ũlũngalu, na kũvathanw’a, na wovosyo:'),
('kam', '1CO', 1, 31, 'nĩ kana, o tondũ kũandĩkĩtwe, Ũla wĩkathĩĩaa, nĩekathĩĩe nthĩnĩ wa Mwĩaĩĩ.'),
('kam', '1CO', 2, 1, 'Nakwa nyie, nooka kwenyu, ana‐a‐asa, ndyaaũka kũmũtavya nzama ya Ngai na ũseo mũnene wa ũneeni, kana ũĩ.'),
('kam', '1CO', 2, 2, 'Nũndũ neetw’ĩĩe ndikamanye ũndũ o na wĩva katĩ wenyu, ate o Yesũ Klĩsto, nake nĩ ũla wambiwe.'),
('kam', '1CO', 2, 3, 'Nakwa naĩ nenyu nĩ na wonzu, na w’ĩa, na kũtetema kwingĩ.'),
('kam', '1CO', 2, 4, 'Na kũneena kwakwa na kũtavan’ya kwakwa kũtyaĩ na ndeto sya ũĩ wa kũthing’ĩĩsya, ĩndĩ kwaĩ nthĩnĩ wa kwonan’ya kwa Veva na kwa vinya:'),
('kam', '1CO', 2, 5, 'nĩ kana mũĩkĩĩo wenyu ndũkethĩwe ũĩnĩ wa mũndũ, ĩndĩ wĩthĩwe vinyanĩ wa Ngai.'),
('kam', '1CO', 2, 6, 'Ĩndĩ, o na ũu, tũneenaa ũĩ kwa ala meanĩe: ĩndĩ ti ũĩ wa nthĩ ĩno, kana wa anene ma nthĩ ĩno, ala makatuwa ma mana:'),
('kam', '1CO', 2, 7, 'ĩndĩ tũneenaa ũĩ wa Ngai na nzama, naw’o nĩ ũla wavithĩtwe, ũla Ngai watwie tene mbee wa mavinda aa ũndũ wa ũtaĩo witũ:'),
('kam', '1CO', 2, 8, 'naw’o ũĩ ũsu vatyaĩ ũmwe wa anene ma nthĩ ĩno wawĩsĩ: nũndũ kethĩwa nĩmoomanyie, matyaĩ mamwamba Mwĩaĩi ũla ũtaĩawa:'),
('kam', '1CO', 2, 9, 'ĩndĩ o tondũ kũandĩkĩtwe, Maũndũ ala itho yĩtaamona, na kũtũ kũtaamew’a, Na ala mataalika ngoonĩ ya mũndũ, Maũndũ o na meva ala Ngai wamaseũvĩsye ala mamwendaa.'),
('kam', '1CO', 2, 10, 'Ĩndĩ Ngai nĩwatũvuanĩsye ithyĩ kwa nzĩa ya Veva: nũndũ Veva amanthaa maũndũ onthe, ĩĩ, o na maũndũ maliku ma Ngai.'),
('kam', '1CO', 2, 11, 'Nũndũ nũũ wa andũ ũmanyaa maũndũ ma mũndũ, ate o veva wa mũndũ ũla wĩ nthĩnĩ wake? No ta ũu maũndũ ma Ngai vai ũmamanya, ate o Veva wa Ngai.'),
('kam', '1CO', 2, 12, 'Ĩndĩ ithyĩ tũiaaosa veva wa maũndũ ma nthĩ, ĩndĩ nĩtwosete Veva ũla wumaa kwa Ngai; nĩ kana tũmanye maũndũ ala tũnengetwe mana nĩ Ngai.'),
('kam', '1CO', 2, 13, 'Maũndũ asu namo nĩtũũmaneena, na ti na ndeto imanyĩaw’a nĩ ũĩ wa andũ, ĩndĩ nĩ ila Veva ũmanyĩasya; tũkĩthiman’ya maũndũ ma veva na ala ma veva.'),
('kam', '1CO', 2, 14, 'Mũndũ wa mwĩkalĩle wa ki‐mũndũ ndosaa maũndũ ma Veva wa Ngai: nũndũ nĩ ũtumanu kwake: nake ndatonya kũmamanya nũndũ nĩmekuũawa nĩ veva.'),
('kam', '1CO', 2, 15, 'Ĩndĩ we ũla wa mwĩkalĩle wa veva ekuũaa maũndũ onthe, ĩndĩ we mwene ndekuũawa nĩ mũndũ o na wĩva.'),
('kam', '1CO', 2, 16, 'Nũndũ nũũ ũla ũmanyĩte kĩlilikano kya Mwĩaĩi, nĩ kana amũmanyĩsye? Ĩndĩ ithyĩ twĩ na kĩlĩlĩkano kya Klĩsto.'),
('kam', '1CO', 3, 1, 'Nakwa, ana‐a‐asa, ndyaatonya ũneena nenyu ta mwĩ ma mwĩkalĩle wa veva, ĩndĩ ta mwĩ ma mwĩkalĩle wa mwĩĩ, ta mwĩ tũũkenge nthĩnĩ wa Klĩsto.'),
('kam', '1CO', 3, 2, 'Nĩmũnengete ĩia ndimũnengete lĩu; nũndũ mũtyaĩ mũũtonya: aiee, o na yu mũinamba kũũtonya;'),
('kam', '1CO', 3, 3, 'nũndũ mwĩ ma mwĩkalĩle wa mwĩĩ o na yu: nũndũ mwĩ na kĩwĩu na ĩteta katĩ wenyu, mũi ma mwĩkalĩle wa mwĩĩ, na mũiendaa o ũndũ andũ maendaa?'),
('kam', '1CO', 3, 4, 'Nũndũ yĩla ũmwe ũnũkwasya, Nyie nĩ wa Vaulo; na ũngĩ easya, Nyie nĩ wa Avolo; inyw’ĩ mũi o andũ?'),
('kam', '1CO', 3, 5, 'Ĩndĩ Avolo nũũ? Na Vaulo nũũ? Nĩ athũkũmi, ala kwondũ wamo mwĩtĩkĩlĩte; na kĩla mũndũ o tondũ Mwĩaĩi wamũnengie.'),
('kam', '1CO', 3, 6, 'Nyie nĩnavandie, na Avolo nĩwanyithisye; ĩndĩ nĩ Ngai wĩanĩtye.'),
('kam', '1CO', 3, 7, 'Na kwondũ wa ũu, ũla ũvandaa ti kĩndũ, o na ũla ũnyithasya; ĩndĩ nĩ Ngai ũla wĩanasya.'),
('kam', '1CO', 3, 8, 'Na ĩndĩ ũla ũvandaa na ũla ũnyithasya nĩ ũndũ ũmwe: ĩndĩ kĩla mũndũ akoosa ĩtuvi yake mwene kwĩanana na kũthĩnĩa wĩa kwake.'),
('kam', '1CO', 3, 9, 'Nũndũ twĩ atethya ma wĩa vamwe na Ngai: inyw’ĩ mwĩ mũũnda wa Ngai, na wako wa Ngai.'),
('kam', '1CO', 3, 10, 'Kwĩanana na mumo wa Ngai nanengiwe, ta mũnene wa aki, mũĩ, nĩnambĩlĩlye wabĩlĩlyo; na ũngĩ eaka ĩũlũ waw’o. Ĩndĩ kĩla mũndũ nĩesisye ũndũ ũnũkwaka ĩũlũ waw’o.'),
('kam', '1CO', 3, 11, 'Nũndũ vai mũndũ ũtonya kwambĩlĩlya wambĩlĩlyo ũngĩ ate o ũla wambĩlĩlw’e, naw’o nĩ Yesũ Klĩsto.'),
('kam', '1CO', 3, 12, 'Ĩndĩethĩwa mũndũ o na wĩva eaka ĩũlũ wa wambĩlĩlĩlyo ũsu thaavu, kana vetha, kana mavia me thooa mũnene, kana mĩtĩ, kana nyeki, kana ũa;'),
('kam', '1CO', 3, 13, 'wĩa wa kĩla mũndũ nũkonanw’a: nũndũ mũthenya ũsu nũkawonan’ya, nĩkwĩthĩwa nũkavuanw’a nĩ mwaki; na ũla mwaki e w’o nũkatata wĩa wa kĩla mũndũ ũndũ ũilyi.'),
('kam', '1CO', 3, 14, 'Ethĩwa wĩa wa mũndũ o na wĩva ũla wakie ĩũlũ wa wambĩlĩlyo ũsu ũkekala, ũsu akoosa ĩtuvi.'),
('kam', '1CO', 3, 15, 'Ethĩwa wĩa wa mũndũ o na wĩva ũkavya, akoona wasyo; ĩndĩ we mwene akatangĩĩwa; ĩndĩ no ta kũvĩtĩla mwakinĩ.'),
('kam', '1CO', 3, 16, 'Mũtyĩsĩ kana mwĩ ĩkalũ ya Ngai, na kana Veva wa Ngai ekalaa nthĩnĩ wenyu?'),
('kam', '1CO', 3, 17, 'Ethĩwa mũndũ eananga ĩkalũ ya Ngai, we akaanangwa nĩ Ngai; nũndũ ĩkalũ ya Ngai nĩ ĩtheu, na ĩkalũ yĩu nĩ inyw’ĩ.'),
('kam', '1CO', 3, 18, 'Mũndũ ndakekenge mwene. Ethĩwa mũndũ o na wĩva eĩtalĩlya nĩ mũĩ katĩ wenyu ĩvindanĩ yĩĩ, natw’ĩke mũtumanu, nĩ kana atonye ũtw’ĩka mũĩ.'),
('kam', '1CO', 3, 19, 'Nũndũ ũĩ wa nthĩ ĩno nĩ ũtumanu kwa Ngai. Nũndũ nĩkũandĩkĩtwe, Ũla ũmakwataa ala oĩ ũselekenĩ woo:'),
('kam', '1CO', 3, 20, 'na ĩngĩ, Mwĩaĩi nĩwĩsĩ mosũanĩo ma ala oĩ, kana nĩ ma mana.'),
('kam', '1CO', 3, 21, 'Kwondũ wa ũu, mũndũ ndakekathĩĩe ũndũ wa andũ. Nũndũ syĩndũ syonthe nĩ syenyu;'),
('kam', '1CO', 3, 22, 'ethĩwa nĩ Vaulo, kana Avolo, kana Keva, kana nthĩ, kana thayũ, kana kĩkw’ũ, kana syĩndũ ila syĩ kw’o, kana ila ĩkethĩwa kw’o; syonthe nĩ syenyu;'),
('kam', '1CO', 3, 23, 'na inyw’i mwĩ ma Klĩsto; na Klĩsto nĩ wa Ngai.'),
('kam', '1CO', 4, 1, 'Mũndũ o na wĩva natũtale ithyĩ kwĩthĩwa twĩ athũkũmi ma Klĩsto, na asũvĩi ma nzama sya Ngai.'),
('kam', '1CO', 4, 2, 'Na ũndũ ũngĩ, veendwa asũvĩinĩ, mũndũ oneke e kĩthito.'),
('kam', '1CO', 4, 3, 'Ĩndĩ kwakwa nyie, ti kĩndũ ngĩkuũwa nĩ inyw’ĩ, kana mũthenya wa sila wa mũndũ; ĩĩ, o na ndyĩkuũaa mwene.'),
('kam', '1CO', 4, 4, 'Nũndũ ndyĩsĩ ũndũ ĩũlũ wakwa; ĩndĩ kwondũ wa ũu nditalawa kwĩthĩwa nĩ mũlũngalu: ĩndĩ ũla ũmbĩkuũaa nĩ Mwĩaĩi.'),
('kam', '1CO', 4, 5, 'Kwondũ wa ũu mũikasilĩle ũndũ ĩvinda yaw’o yĩtanavika, mũvaka yĩla Mwĩaĩi wĩũka, nake akaete kyeninĩ maũndũ mavithe ma kĩvindu, na kwonan’ya mosũanĩo ma ngoo; na ĩndĩ kĩla mũndũ akeethĩwa na ndaĩa yake yumĩte kwa Ngai.'),
('kam', '1CO', 4, 6, 'Maũndũ aa, ana‐a‐asa, naneena na ngelekan’yo ũndũ wakwa na Avolo kwondũ wenyu; nĩ kana ũndũ witũ mũtonye kwĩmanyĩsya mũtikavĩtũke mbee wa maũndũ ala maandĩkĩtwe; nĩ kana kũikethĩwe ũmwe wenyu kũkathĩĩa ũmwe kũte ũla ũngĩ.'),
('kam', '1CO', 4, 7, 'Nũndũ nũũ, ũla ũkũvathũkanĩtye we? Na ĩngĩ, wĩ na kyaũ ũtaaosa? Ethĩwa ĩndĩ we nĩwosete, wĩĩkathĩĩa kĩ, ta ũtosete?'),
('kam', '1CO', 4, 8, 'O na yu nĩmũvũnĩte, o na yu mũtw’ĩkĩte athwii, nĩmũsumbĩkĩte tũte vo ithyĩ: ĩĩ, nĩenda mwĩthĩwe mũsumbĩkĩte, nĩ kana naitũ tũsumbĩke vamwe nenyu.'),
('kam', '1CO', 4, 9, 'Nũndũ, nĩasya, Ngai nũtũtw’ĩte ithyĩ atũmwa twĩthĩwe ĩtina wa onthe, ta andũ masilĩlwe kũawa: nũndũ tũtw’ĩkĩte asyaĩĩw’a kwa nthĩ yonthe, kwa alaĩka, na kwa andũ nao.'),
('kam', '1CO', 4, 10, 'Ithyĩ twĩ atumanu kwondũ wa Klĩsto, ĩndĩ inyw’ĩ mwĩ oĩ nthĩni wa Klĩsto; ithyĩ twĩ onzu, ĩndĩ inyw’ĩ mwĩ na vinya: ĩnyw’ĩ mwĩ na nguma, ĩndĩ ithyĩ tũti na nguma.'),
('kam', '1CO', 4, 11, 'O na kũvika saa ũũ twĩ na nzaa, na waũni, na ũtw’ĩkĩwa, na kũlumangw’a, na tũi na ũtũo;'),
('kam', '1CO', 4, 12, 'na nĩtũũthĩnaa tũkĩtethya wĩa na moko maitũ ene: twaumangwa, nĩtũathimaa; twanyamaw’a, nĩtũmĩĩasya;'),
('kam', '1CO', 4, 13, 'twawetwa naĩ, nĩtwĩsũvanaa: tũtw’ĩtwe ta mavuthĩ ma nthĩ, ũvavao wa syĩndũ syonthe, kũvika o na yu.'),
('kam', '1CO', 4, 14, 'Ndiũandĩka maũndũ aa nĩmũsonokye, ĩndĩ nĩ kũmũtaa ta syana, endwa makwa.'),
('kam', '1CO', 4, 15, 'Nũndũ o na mũkethĩwa mwĩ na amanyĩsya ngili ĩkũmi nthĩnĩ wa Klĩsto, mũi na aaĩthe aingĩ: nũndũ nthĩnĩ wa Klĩsto Yesũ, ninyie namũsyaie kwa nzĩa ya ũla ũvoo mũseo.'),
('kam', '1CO', 4, 16, 'Ĩndĩ nĩmwĩsũva mwĩthĩwe mũkĩelekan’ya nakwa.'),
('kam', '1CO', 4, 17, 'Kwondũ wa ũu nĩnamũtũmie Timotheo oke kwenyu, nake nĩ mwana wakwa mwendwa wĩ kĩthito nthĩnĩ wa Mwĩaĩi, ũla wĩmũlilikan’ya ũvoo wa mĩendele yakwa ĩla ĩ nthĩnĩ wa Klĩsto, o tondũ nĩmanyĩasya kũndũ kw’onthe nthĩnĩ wa kĩla ĩkanisa.'),
('kam', '1CO', 4, 18, 'Yu amwe nĩmekwĩkathĩĩa, ta ndeũka kwenyu.'),
('kam', '1CO', 4, 19, 'Ĩndĩ ngooka kwenyu mĩtũkĩ, Mwĩaĩi enda; nakwa ngamanya ti ndeto ya asu mekathĩĩaa, ĩndĩ nĩ vinya woo.'),
('kam', '1CO', 4, 20, 'Nũndũ ũsumbĩ wa Ngai ndwĩ ndetonĩ, ĩndĩ wĩ vinyanĩ.'),
('kam', '1CO', 4, 21, 'Mwĩenda ata? Nũke kwenyu na ndata, kana na wendo na veva wa ũuu?'),
('kam', '1CO', 5, 1, 'Nĩ w’o, ũvoo nĩ mũnyaĩĩku kana kwĩ ũlaalai katĩ wenyu, na nĩ ũlaalai ũla ũte kwa Andũ‐ma‐mbaĩ‐ingĩ, kana ũmwe wenyu e na mũka wa ĩthe.'),
('kam', '1CO', 5, 2, 'Nenyu nĩmwĩkathĩĩe: o na mũinew’a woo, nĩ kana ũsu wĩkĩte ũndũ ũsu, avetwe katĩ wenyu.'),
('kam', '1CO', 5, 3, 'Nũndũ nĩ w’o, o na ethĩwa ndi vo na mwĩĩ, ĩndĩ vevanĩ nĩ vo, nyie nĩnĩminĩte kũmũsilĩla ũsu wĩkĩte ũndũ ũsu, ta nĩnaĩ kw’o mwene,'),
('kam', '1CO', 5, 4, 'syĩtwanĩ ya Mwĩaĩi waitũ Yesũ, inyw’ĩ mweethĩwa mũmbanĩte vamwe, o na vamwe na veva wakwa, na vinya wa Mwĩaĩi waitũ Yesũ,'),
('kam', '1CO', 5, 5, 'kũmumya mũndũ ũilyĩ ũu na kũmũnengane kwa Satani mwĩĩ wanangwe, nĩ kana veva ũtangĩĩwe mũthenya wa Mwĩaĩi Yesũ.'),
('kam', '1CO', 5, 6, 'Kwĩkathĩĩa kwenyu ti kũseo. Mũtyĩsĩ kana ĩlawa ĩnini nĩyĩkaatasya kĩmũtũ kyonthe?'),
('kam', '1CO', 5, 7, 'Ĩthesyei vyũ mũkyumya yĩla ĩlawa ya tene, mwĩthĩwe mũndo mweũ ki, o ta mũtekĩwe ĩlawa. Nũndũ vasaka witũ nũthembetwe, naw’o nĩ Klĩsto:'),
('kam', '1CO', 5, 8, 'kwondũ wa ũu, tũvokae mboka, ti na ĩlawa ĩkũũ, o na ti na ĩlawa ya ũmaitha na ũthũku; ĩndĩ na kĩmũtũ kĩte ĩlawa, kĩtheu na kya w’o.'),
('kam', '1CO', 5, 9, 'Namũandĩkĩe valũanĩ wakwa kana mũĩkavulane na ilaalai;'),
('kam', '1CO', 5, 10, 'ndikwasya o na vanini kana nĩ ilaalai sya nthĩ ĩno, kana ala me na ĩtomo, na avutani, kana athaithi ma mĩvw’anano; nũndũ ethĩwa nũu, mũvaka mume kũũ nthĩ:'),
('kam', '1CO', 5, 11, 'ĩndĩ nĩmũandĩkĩe mũikavulane na mũndũ ũnũkwĩtwa mwana‐a‐asa ethĩwa nĩ kĩlaalai, kana wĩ ĩtomo, kana mũthaithĩ wa mĩvw’anano, kana mũumani, kana mũnywi, kana mũvutani; mũndũ ũilyĩ ũu, mũikavulane nake, aiee, o na mũikaye nake.'),
('kam', '1CO', 5, 12, 'Nũndũ nĩ ũndũ mwaũ kũmasilĩla ala me ũtee? Mũtiũmasilĩla asu me nthĩnĩ?'),
('kam', '1CO', 5, 13, 'Ĩndĩ asu me ũtee Ngai nũmasilĩlaa. Mũvetei ĩndĩ ũsu mwathe, aume katĩ wenyu.'),
('kam', '1CO', 6, 1, 'Mũndũ o na wĩva wa inyw’ĩ, e na ũndũ na ũngĩ, nũtonya ũmũvinganĩsya mbee wa ala mate alũngalu, na ti mbee wa atheu?'),
('kam', '1CO', 6, 2, 'Kana mũtyĩsĩ kana atheu nĩmakasilĩla nthĩ? Na ethĩwa nthĩ nĩkasilĩlwa nĩ inyw’ĩ, mũtyaĩle kũsilaa maũndũ ala manini?'),
('kam', '1CO', 6, 3, 'Mũtyĩsĩ kana ithyĩ nĩtũkasilĩla alaĩka? Nĩ mbee veana ata, maũndũ ma thayũ ũũ?'),
('kam', '1CO', 6, 4, 'Ethĩwa ĩndĩ nĩ ũndũ wenyu kũsilaa maũndũ ma thayũ ũũ, mwĩmaia asu ala mate na ũtalo ĩkanisanĩ kũsilaa?'),
('kam', '1CO', 6, 5, 'Nĩneena ũu ndonye kũmũsonokya. Ũu nĩ w’o, kũioneka kwenyu mũndũ ũmwe mũĩ ũla ũtonya kũtw’a sila katĩ wa ana‐a‐ĩthe,'),
('kam', '1CO', 6, 6, 'ĩndĩ mũndũ nũsitakanaa na mwana‐a‐ĩthe, na ĩngĩ nĩ mbee wa ala matetĩkĩlĩte?'),
('kam', '1CO', 6, 7, 'Aiee, o na yu nũtw’ĩkĩte wasyo kwenyu, kwĩthĩwa na makoani inyw’ĩ kwa inyw’ĩ. Nĩkĩ ti kavaa kũmĩĩsya ũthũku? Nĩkĩ ti kavaa kũvutwa?'),
('kam', '1CO', 6, 8, 'Ĩndĩ inyw’ĩ ene nĩmwĩkaa naĩ, na mũivũtana, na ĩngĩ nĩ kwa ana‐a‐ĩthe menyu.'),
('kam', '1CO', 6, 9, 'Kana mũtyĩsĩ kana ala mate na ũlũngalu matikatiĩwa ũsumbĩ wa Ngai? Mũikakengeke: eki ma naĩ na eĩtu, o na athaithi ma mĩvw’anano, o na ilaalai, o na ala metusaa ta aka, o na ala meyĩkaa naĩ na aũme,'),
('kam', '1CO', 6, 10, 'o na ing’ei, o na ala me na ĩtomo, o na anywi, o na aumani, o na avutani, maĩkatiĩwa ũsumbĩ wa Ngai.'),
('kam', '1CO', 6, 11, 'Na amwe menyu mwailyĩ ũu: ĩndĩ nĩmũthambĩtw’e, ĩndĩ nĩmũvathĩtw’e mwĩthĩwe atheu, ĩndĩ nĩmũtalĩlwe ũlũngalu syĩtwanĩ ya Mwĩaĩi Yesũ Klĩsto, na nthĩnĩ wa Veva wa Ngai waitũ.'),
('kam', '1CO', 6, 12, 'Maũndũ onthe kwakwa nĩmatonyeka; ĩndĩ ti onthe mailaa. Maũndũ onthe kwakwa nĩmatonyeka; ĩndĩ nyie ndikalikw’a ũkũmũnĩ wa ũmwe o na wĩva.'),
('kam', '1CO', 6, 13, 'Sya ũya nĩ sya ĩvu, na ĩvu nĩ ya sya ũya: ĩndĩ Ngaĩ akaitw’ĩkĩthya sya mana ĩvu na sya ũya syelĩ. Ĩndĩ mwĩĩ ti wa kwĩka ũlaalai, ĩndĩ nĩ wa Mwĩaĩi; nake Mwĩaĩi nĩ wa mwĩĩ:'),
('kam', '1CO', 6, 14, 'na Ngai nake nĩwamũthayũũkisye Mwĩaĩi, na ĩngĩ akatũthayũũkya ithyĩ na vinya wake.'),
('kam', '1CO', 6, 15, 'Mũtyĩsĩ kana mĩĩ yenyu nĩ mamutha ma Klĩsto? Nose ĩndĩ mamutha ma Klĩsto, na kũmatw’a mamutha ma ĩlwaya? Aiee, kũikethĩwe ũu.'),
('kam', '1CO', 6, 16, 'Kana mũtyĩsĩ atĩ ũla ũnũũkoma na ĩlwaya nĩ mwĩĩ ũmwe nayo? Nũndũ aĩtye, Asu elĩ makethĩwa mwĩĩ ũmwe.'),
('kam', '1CO', 6, 17, 'Ĩndĩ ũla ũnũũthalanw’a na Mwĩaĩi nĩ veva ũmwe.'),
('kam', '1CO', 6, 18, 'Kĩai ũlaalai. Kĩla ũthũku mũndũ wĩkaa wĩ ũtee wa mwĩĩ wake; ĩndĩ ũla wĩkaa ũlaalai eyĩkaa mwĩĩ wake mwene naĩ.'),
('kam', '1CO', 6, 19, 'O na mũtyĩsĩ kana mwĩĩ wenyu nĩ ĩkalũ ya Veva Mũtheu, ũla wĩ nthĩnĩ wenyu, ũla mwĩ nake kuma kwa Ngai? Na mũi menyu ene;'),
('kam', '1CO', 6, 20, 'nũndũ nĩmũthooetwe na thooa mũnene: mũtaĩei Ngai ĩndĩ mĩĩnĩ yenyu.'),
('kam', '1CO', 7, 1, 'Ĩndĩ yu nĩtũsisye maũndũ ala mũnanandĩkĩe: Nĩ ũseo mũndũ ndakakiite mũndũ mũka.'),
('kam', '1CO', 7, 2, 'Ĩndĩ, nũndũ wa molaalai, kĩla mũndũ nĩethĩwe na kĩveti kyake mwene, na kĩla mũndũ mũka nake nĩethĩwe na mũũme wake mwene.'),
('kam', '1CO', 7, 3, 'Mũndũ mũũme namũnenge mũka wake ũla ũmwaĩle: na ta ũu, mũndũ mũka nake namũnenge mũũme wake ũla ũmwaĩle.'),
('kam', '1CO', 7, 4, 'Mũndũ mũka nde na ũkũmũ ĩũlũ wa mwĩĩ wake mwene, ĩndĩ nĩ mũũme: na no ta ũu mũũme nake nde na ũkũmũ ĩũlũ wa mwĩĩ wake mwene, ĩndĩ nĩ mũka.'),
('kam', '1CO', 7, 5, 'Mũikavatane ene kwa ene, ate o yĩla mwĩw’anĩte kwĩka ũu ĩvinda, nĩ kana mũtonye kwĩnengane ene kũvoya, na ĩtina kwĩthĩwa vamwe ĩngĩ, Satani ndakamũtate kwondũ wa kũlea kwĩyũmĩĩsya.'),
('kam', '1CO', 7, 6, 'Ĩndĩ nĩneena ũndũ ngwona, na tĩ ũndũ wa kwĩaa.'),
('kam', '1CO', 7, 7, 'Ĩndĩ nĩenda andũ onthe mekale takwa ũndũ ndilyĩ. Ĩndĩ kĩla mũndũ e na mũthĩnzĩo wake mwene wanengiwe nĩ Ngai, ũmwe ũndũ wake, na ũngĩ ũndũ wake.'),
('kam', '1CO', 7, 8, 'Ĩndĩ nĩmea ala matatwaanĩte, na aka ndiwa, atĩĩ, Nĩ ũseo mekale takwa o ũndũ ndilyĩ.'),
('kam', '1CO', 7, 9, 'Ĩndĩ ethĩwa maitonya kwĩyũmĩĩsya, nĩmatwaane: nũndũ nĩ ũseo kũtwaana kwĩ kwakana mwaki.'),
('kam', '1CO', 7, 10, 'Ĩndĩ kwa ala matwaanĩte nĩngwĩaa, o na tii nyie, ĩndĩ nĩ Mwĩaĩi, kana mũndũ mũka ndakamũlee mũũme,'),
('kam', '1CO', 7, 11, '(ĩndĩ ethĩwa nũnũũthi, nĩeyĩkalye ate mũtwae, kana ethĩwa ti ũu, ew’ane na mũũme wake;) na mũũme ndakamũlee mũka wake.'),
('kam', '1CO', 7, 12, 'Ĩndĩ kwa angĩ nĩneena nyie, ti Mwĩaĩi: Ethĩwa mwana‐asa o na wĩva e na mũndũ mũka ũtetĩkĩlĩte, nake mũndũ mũka eenda kwĩkala nake, ndakamũlee.'),
('kam', '1CO', 7, 13, 'Na mũndũ mũka wĩ na mũũme ũtetĩkĩlĩte, nake mũũme enda kwĩkala nake, ndakamũlee mũũme.'),
('kam', '1CO', 7, 14, 'Nũndũ mũũme ũla ũtetĩkĩlĩte nũvathĩkĩte nũndũ wa mũka, na mũka ũtetĩkĩlĩte nũvathĩkĩte nũndũ wa mũũme: kethĩwa ti ũu syana syenyu syĩthĩwa syĩ mbuku; ĩndĩ yu nĩ ntheu.'),
('kam', '1CO', 7, 15, 'Ĩndĩ ethĩwa ũla ũtetĩkĩlĩte nũnũũthi, nathi: mwana‐a‐asa kana mwĩĩtũ‐a‐asa ti ngombo maũndũnĩ mailyĩ ũu: ĩndĩ Ngai nũtwĩtĩte twĩkalae na mũuo.'),
('kam', '1CO', 7, 16, 'Nũndũ wĩsĩ ata we, kĩveti, kana ũkatangĩĩa mũemeu? Kana wĩsĩ ata we, mũũme, kana ũkatangĩĩa mũkau?'),
('kam', '1CO', 7, 17, 'Ĩndĩ tondũ Mwĩaĩi wamũaĩe kĩla mũndũ, na tondũ Ngai wamwĩtie kĩla mũndũ, naende o ũu. Nakwa nĩaa o ũu makanisanĩ onthe.'),
('kam', '1CO', 7, 18, 'Mũndũ o na wĩva eetiwe e mwaĩke? Ndakatw’ĩke ũte mwaĩke. Ve mũndũ o na wĩva wetiwe ate mwaĩke? Ndakaĩkwe.'),
('kam', '1CO', 7, 19, 'Nzaĩko ti kĩndũ, na kũlea kwaĩkwa ti kĩndũ; ĩndĩ kũatĩĩa mĩao ya Ngai.'),
('kam', '1CO', 7, 20, 'Kĩla mũndũ nĩekale ũndũ wailyĩ aiĩtwa.'),
('kam', '1CO', 7, 21, 'Wetiwe wĩ ngombo? Ndũkone ta ũndũ; ĩndĩ ethĩwa nũtonyeka kwaku kuma ũkombonĩ, kavaa wume.'),
('kam', '1CO', 7, 22, 'Nũndũ ũla wetiwe nthĩnĩ wa Mwĩaĩi, e ngombo, nĩ mũthasye wa Mwĩaĩi: na no ta ũu ũla wetiwe ate ngombo, ũsu nĩ ngombo ya Klĩsto.'),
('kam', '1CO', 7, 23, 'Nĩmwathooiwe na thooa; mũikatw’ĩke ngombo sya andũ.'),
('kam', '1CO', 7, 24, 'O ũndũ mũndũ wailyĩ yĩla wetiwe, ana‐a‐asa, nĩekale ũndũnĩ o ũsu, vamwe na Ngai.'),
('kam', '1CO', 7, 25, 'Ĩndĩ ũndũ wa eĩtu ndi na mwĩao wa Mwĩaĩi: ĩndĩ nĩmũtavya ũndũ ngwona, ta ũmwe ũla wosete tei wa Mwĩaĩi ethĩwe mũĩkĩĩwa.'),
('kam', '1CO', 7, 26, 'Ĩndĩ nĩona ũndũ ũũ ta ũseo kwondũ wa thĩna ũla twi naw’o, kana nĩ ũseo mũndũ ekale o ũndũ ũilyĩ.'),
('kam', '1CO', 7, 27, 'Nĩwovanĩtw’e na mũndũ mũka? Ndũkamanthe kũthaw’a. Nũthaanĩtwe na mũndũ mũka? Ndũkamanthe mũndũ mũka.'),
('kam', '1CO', 7, 28, 'Ĩndĩ, o na ethĩwa ũkatwaana, ndũkwĩka naĩ; na mwĩĩtũ aitwawa, ndekwĩka naĩ. Ĩndĩ ala mailyĩ ũu maitĩa kwĩthĩwa na mathĩna mwĩĩnĩ: nakwa nĩenda kũmũvonokya.'),
('kam', '1CO', 7, 29, 'Ĩndĩ nĩneena ũu, ana‐a‐asa, ĩvinda nĩ ĩkũvĩvye mũno, kana kũma yu, ala me na aka nĩmethĩwe ta mataĩ;'),
('kam', '1CO', 7, 30, 'na ala maĩaa, nĩmethĩwe ta mataĩaa; na ala matanaa, nĩmethĩwe ta matatanaa; na ala mathooaa, nĩmethĩwe ta mate na kĩndũ;'),
('kam', '1CO', 7, 31, 'na ala metethasya na syĩndũ sya nthĩ, nĩmethĩwe ta matasyĩkwatasya mũno: nũndũ mwĩkalĩle wa nthĩ ĩno nũũvita.'),
('kam', '1CO', 7, 32, 'Ĩndĩ nĩenda kana mũikaũũye. We, ũla ũtatwaanĩte, alilikanaa mũno maũndũ ma Mwiaĩi, ũndũ wĩmwendeeasya Mwĩaĩi:'),
('kam', '1CO', 7, 33, 'ĩndĩ ũla ũtwaanite alilikanaa mũno maũndũ ma nthĩ, ũndũ wĩmwendeeasya mũka.'),
('kam', '1CO', 7, 34, 'Na ĩngĩ kwĩ kĩvathũkan’yo kya mũndũ mũka na mwĩĩtu. Ũla ũte mũtwae alilikanaa mũno maũndũ ma Mwĩaĩi, nĩ kana atonye kwĩthĩwa mũtheu mwĩĩnĩ na vevanĩ: ĩndĩ ũla ũtwaĩtwe alilikanaa mũno maũndũ ma nthĩ, na ũndũ wĩmwendeeasya mũũme.'),
('kam', '1CO', 7, 35, 'Ĩndĩ ũu nĩneena kwondũ wa kũmũtethya; ti ũndũ wa kũmũtea, ĩndĩ nũndũ wa ũla waĩle, na ĩngĩ kana mũtonye kũmũthũkũma Mwĩaĩi mũtekũvũavũanw’a.'),
('kam', '1CO', 7, 36, 'Ĩndĩ ethĩwa mũndũ o na wĩva onaa ta ũtamwĩkaa mwĩĩtu wake ũndũ waĩle, na ethiwa nĩwavĩta ũseo wa wana wake, na ethĩwa kwĩ vata wa ũu, nĩeke ũndũ ũnũkwenda; ndekwĩka naĩ; nĩmatwaane.'),
('kam', '1CO', 7, 37, 'Ĩndĩ ũla ũũngeme na ũlũmu ngoonĩ yake, ateũingĩĩw’a, ĩndĩ e na vinya kwendanĩ kwake, na nĩwetw’ĩĩte ũndũ ũũ ngoonĩ yake, atũae na mwĩĩtu wake, ekaa nesa.'),
('kam', '1CO', 7, 38, 'Na kwondu wa ũu, ũla ũnũũmũtwaanĩthya mwĩĩtu wake eĩka nesa; na ũla ũteũmũtwaanĩthya mwĩĩtu wake eĩka nesa mbee.'),
('kam', '1CO', 7, 39, 'Mũndũ mũka nĩ mwove ĩvinda yĩla mũũme wĩ thayũ; ĩndĩ ethĩwa mũũme nũkw’ĩte, yu nũthaĩtw’e, na nũtonya kũtwawa nĩ ũla ũnũkwenda; ĩndĩ no nthĩnĩ wa Mwĩaĩi.'),
('kam', '1CO', 7, 40, 'Ĩndĩ nĩ ũseo mbee kwĩkalaa o ũndũ ũilyĩ, ũndũ ngwona: na ĩngĩ nĩasya nyie nĩ na Veva wa Ngai.'),
('kam', '1CO', 8, 1, 'Na yu, ũndũ wa syĩndũ ila ithembeawa mĩvw’anano: Nĩtwĩsĩ kana ithyonthe twĩ na ũmanyi. Ũmanyi ũetae ngathĩĩo, ĩndĩ wendo nĩwakaa.'),
('kam', '1CO', 8, 2, 'Ethĩwa mũndũ eyonaa ta wĩsĩ ũndũ o na wĩva, ndanamba kũmanya ũndũ waĩle ũmanya;'),
('kam', '1CO', 8, 3, 'ĩndĩ ethĩwa mũndũ o na wĩva nũmwendete Ngai, ũsu nĩwĩsĩkĩwe nĩwe.'),
('kam', '1CO', 8, 4, 'Ĩndĩ ũndũ wa ũvoo ũũ wa kũya syĩndũ ithembeawa mivw’anano, nĩtwĩsĩ kana mũvw’anano ti kĩndũ kũũ nthĩ, na atĩ kũi Ngai ũngĩ ate o ũmwe weka.'),
('kam', '1CO', 8, 5, 'Nũndũ o na kwethĩwa kwĩ ingĩ syĩtawa ngai, syethĩwa syĩ ĩtunĩ, o na syethĩwa syĩ nthĩ; o ũndũ kwĩ ngai nyingĩ, na eaii aingĩ;'),
('kam', '1CO', 8, 6, 'ĩndĩ kwitũ kwĩ Ngai o ũmwe, nake nĩwe Asa, ũla syĩndũ syonthe syumaa kwake, na ithyĩ twi make; na kwĩ Mwĩaĩi ũmwe, Yesũ Klĩsto, na syĩndũ syonthe nĩ kwondũ wake, na ithyĩ twi kwondũ wake.'),
('kam', '1CO', 8, 7, 'Ĩndĩ ũmanyi ũsu ndwĩ nthĩnĩ wa andũ onthe: ĩndĩ amwe, mamanyĩie maũndũ ma mĩvw’anano kũvika na yu, maĩsaa ta kĩndũ kĩthembewe mũvw’anano; na wasya wa ngoo woo nĩkwĩthĩwa nĩ mwonzu nũvukaa.'),
('kam', '1CO', 8, 8, 'Ĩndĩ kya ũya kĩitwĩtĩkĩlĩthya kwa Ngai: o na ethĩwa tũtiũya, tũtiũnyivĩwa nĩ kĩndũ; na ethĩwa nĩtũũya tũtingĩvĩwa nĩ kĩndũ.'),
('kam', '1CO', 8, 9, 'Ĩndĩ sũvĩai kũthaw’a ku kwenyu kũikethĩwe ũlulutĩkyo kwa ala onzu.'),
('kam', '1CO', 8, 10, 'Nũndũ ethĩwa mũndũ ekwona we, wĩ na ũmanyi, ũilyĩ lĩunĩ ĩkalũnĩ ya mũvw’anano; nake ethĩwa nĩ mwonzu, wasya wa ngoo wake ndũkongeleelwa ũkũmbaũ wa ũya syĩndũ ithembeawa mĩvw’anano?'),
('kam', '1CO', 8, 11, 'Nũndũ kwondũ wa ũmanyi waku ũla mwonzu nũnũkwaa, nake nĩ mwana‐a‐au, ũla Klĩsto wakwie kwondũ wake.'),
('kam', '1CO', 8, 12, 'Na kwondũ wa ũu, mũkimeka ana‐a‐au naĩ, na kũmakũna wasya wa ngoo woo ũte vinya, mwĩmwĩka Klĩsto naĩ.'),
('kam', '1CO', 8, 13, 'Kwondũ wa ũu, ethĩwa lĩu nũũmũlulutĩkya mwana‐a‐asa, ndikaya nyama kũvika tene na tene, nĩ kana ndikamũlulutĩkye mwana‐a‐asa.'),
('kam', '1CO', 9, 1, 'Nyie, ndi mũthaw’a? Ndi mũtũmwa nyie? Ndimwonete Yesũ Mwĩaĩi waitũ? Inyw’ĩ mũi wĩa wakwa nthĩnĩ wa Mwĩaĩi?'),
('kam', '1CO', 9, 2, 'Ethĩwa ndi mũtũmwa kwa angĩ, nĩ mũtũmwa kwenyu: nũndũ inyw’ĩ mwĩ ũsiĩlo wa ũtũmwa wakwa nthĩnĩ wa Mwĩaĩi.'),
('kam', '1CO', 9, 3, 'Ũsũngĩo wakwa nĩ ũũ, kwa ala mandoasya.'),
('kam', '1CO', 9, 4, 'Ithyĩ tũtitonya kũya na kũnyw’a?'),
('kam', '1CO', 9, 5, 'Ithyĩ tũtitonya kĩla mũndũ kũendan’ya na mũka wake wĩtĩkĩlĩte, o ta atũmwa ala angĩ na ana‐a‐inyia ma Mwĩaĩi, na Keva?'),
('kam', '1CO', 9, 6, 'Kana no nyie na Valanava tũtatonya kũeka kũtethya wĩa?'),
('kam', '1CO', 9, 7, 'Nĩ mũsikalĩ wĩva ũla ũthũkũmaa na syĩndũ syake mwene, o na ĩndĩĩ? Nũũ ũla ũvandaa mũũnda wa mĩsavivũ, na ndaĩsaa ũsyao waw’o? Kana nũũ ũla ũĩthasya ndĩthya ya indo, na ndanyusaa ĩia yasyo?'),
('kam', '1CO', 9, 8, 'Nĩneena maũndũ aa o tondũ andũ maneenaa? Kana ĩla mĩao ndĩneenete ũu, nayo?'),
('kam', '1CO', 9, 9, 'Nũndũ nĩkũandĩkĩtwe mĩaonĩ ya Mose, Ndũkamyove ng’ombe kanyw’a ĩkĩvũa isyo. No ng’ombe Ngai ũlilikanaa?'),
('kam', '1CO', 9, 10, 'Kana eneena ũu kwondũ witũ ki? Ĩĩ, nĩkũandĩkĩtwe kwondũ witũ: nũndũ we ũla wĩnzaa, nĩwaĩlwe nĩ kwĩnza na wĩkwatyo, na ũla ũvũaa, avũe na wĩkwatyo wa kwosa kĩlungu.'),
('kam', '1CO', 9, 11, 'Ethĩwa ithyĩ twamũvandie inyw’ĩ syĩndũ sya veva, nĩ ũndũ ũnene ethĩwa tũkaketha syĩndũ syenyu sya mwĩĩ?'),
('kam', '1CO', 9, 12, 'Ethĩwa angĩ me na ũkũmũ ĩũlũ wenyu, ithyĩ ti mbee? Ĩndĩ tũtyaaiyosea ũkũmũ ũsu; ĩndĩ nĩtũmĩĩasya maũndũ onthe, nĩ kana tũikasiĩĩe ũvoo mũseo wa Klĩsto na ũndũ o na wĩva.'),
('kam', '1CO', 9, 13, 'Mũtyĩsĩ kana ala mathũkũmaa maũndũnĩ ma ĩkalũ nĩmaĩsaa syĩndũ sya ĩkalũ, kana ala mathũkũmaa kĩthembeonĩ me na kĩanda kyoo vamwe nakyo?'),
('kam', '1CO', 9, 14, 'No ta ũu Mwĩaĩi eaie kana ala matavanasya ũla ũvoo mũseo makoona sya kwĩtethasya kwondũ wa ũvoo mũseo.'),
('kam', '1CO', 9, 15, 'Ĩndĩ nyie ndyaaosa syĩndũ isu o na kĩmwe: na ndiũandĩka maũndũ aa kana mekwe kwakwa; nũndũ kwakwa nĩ kavaa kũkw’a, kwĩ mũndũ o na wĩva kũekethya kwĩkathĩĩa kwakwa.'),
('kam', '1CO', 9, 16, 'Nũndũ, o na kau, nĩtavan’ya ũla ũvoo mũseo, ndi na ũndũ wa kwĩkathĩĩa; nĩkwĩthĩwa nĩnthingaatĩtwe; na woo nĩ wakwa, ethĩwa ndiũtavany’a ũvoo mũseo.'),
('kam', '1CO', 9, 17, 'Nũndũ neeka ũu ũndũ wa kwenda kwakwa mwene, nĩ na ĩtuvi: ĩndĩ ethĩwa ti ũndũ wa kwenda kwakwa mwene, nĩnĩĩkĩĩwe kũsyaĩĩsyanĩ.'),
('kam', '1CO', 9, 18, 'Ĩndĩ ĩtuvĩ yakwa nĩ kyaũ? Nĩ yĩĩ, kana ngĩtavan’ya ũvoo mũseo, ũvoo ũsu wĩthĩwe ũte wa thooa, ndekwĩanĩsya ũkũmũ wakwa ũvoonĩ mũseo.'),
('kam', '1CO', 9, 19, 'Nũndũ o na kau ndyaĩ ngombo ya mũndũ ona wĩva, nĩyiĩte mwene nĩthĩwe ũkombonĩ kwa onthe, nĩ kana ndonye kwona aingĩ mbee.'),
('kam', '1CO', 9, 20, 'Na kwa Ayuti neethĩwa ta Mũyuti, nĩ kana nĩmone Ayuti; na kwa ala me mĩaonĩ, neethĩwa ta nĩ mĩaonĩ, nde mĩaoni nyie, nĩ kana nĩmone ala me mĩaonĩ;'),
('kam', '1CO', 9, 21, 'na kwa ala mate na mĩao, neethĩwa ta nde na mĩao, tĩ atĩndyaĩ na mĩao kwa Ngai, ĩndĩ naĩ mĩaonĩ kwa Klĩsto, nĩ kana nĩmone asu mate na mĩao.'),
('kam', '1CO', 9, 22, 'Na kwa syonze neethĩwa ta kyonze, nĩ kana nĩsyone syonze: nĩtw’ĩkĩte maũndũ onthe kwa andũ onthe, nĩ kana kwa nzĩa syonthe nĩtonye kũmatangĩĩa amwe.'),
('kam', '1CO', 9, 23, 'Nakwa nĩkaa maũndũ aa onthe kwondũ wa ũla ũvoo mũseo, nĩ kana nĩthĩwe nĩ mwosi ũmwe waw’o vamwe na angĩ.'),
('kam', '1CO', 9, 24, 'Mũtyĩsĩ kana ala masembaa makĩlan’yonĩ ma maũũ, masembaa onthe, ĩndĩ no ũmwe wosaa kĩndũ? O ta ũu sembai, nĩ kana mwose.'),
('kam', '1CO', 9, 25, 'Na kĩla mũndũ ũkĩlanasya mathaũnĩ, esiĩĩaa maũndũnĩ onthe. Ĩndĩ asu mekaa ũu nĩ kana manengwe ngovia ya ũsumbĩ yanangĩkaa; ĩndĩ ithyĩ nĩ kana tũnengwe ĩla ĩtanangĩkaa.'),
('kam', '1CO', 9, 26, 'Kwondũ wa ũu, nyie nĩsembaa, nde na nzika; nĩkasya ngundi, ndeũkũna vathei:'),
('kam', '1CO', 9, 27, 'ĩndĩ nĩkanyangaa mwĩĩ wakwa na kũete ũkombonĩ: nĩ kana kũikethĩwe ũndũ o na wĩva w’onthe, ĩtĩna wa kũtavya angĩ, nyie mwene nĩkw’e ũtee.'),
('kam', '1CO', 10, 1, 'Nũndũ ndikwenda, ana‐a‐asa, mũlee ũmanya, ũndũ aasa maitũ onthe maĩ ungu wa ũla mũumbĩ, na onthe mavĩtĩle ũkanganĩ;'),
('kam', '1CO', 10, 2, 'na onthe mavatĩswa mũumbĩnĩ na ũkanganĩ methĩwe ma Mose;'),
('kam', '1CO', 10, 3, 'na onthe maya kya ũya kya veva o kĩmwe;'),
('kam', '1CO', 10, 4, 'na onthe manyw’a kya ũnyw’a kya veva o kĩmwe: nũndũ nĩmanywie kya ĩvia ya veva yĩla yamavikĩlile; na ĩvia yĩu yaĩ Klĩsto.'),
('kam', '1CO', 10, 5, 'Ĩndĩ aingĩ moo, Ngai ndaaendeew’a nĩo: nũndũ nĩmavalũkangilw’e weũnĩ.'),
('kam', '1CO', 10, 6, 'Na yu maũndũ asu maĩ ngelekan’yo kwitũ, nĩ kana ithyĩ tũikasyende syĩndũ nthũku, o tondũ asu nao mendie.'),
('kam', '1CO', 10, 7, 'O na mũikethĩwe athaithĩ ma mĩvw’anano, o ta amwe moo; o tondũ kũandĩkĩtwe, Andũ mekalile nthĩ kũya na kũnyw’a, na mookĩla mathaũke.'),
('kam', '1CO', 10, 8, 'O na tũikalaalae, tondũ amwe moo malaalaile, na mavalũka mũthenya ũmwe andũ ngili mĩongo ĩlĩ na itatũ.'),
('kam', '1CO', 10, 9, 'O na tũikamũtate Mwĩaĩi, tondũ amwe moo mamũtatie, na moawa nĩ ila nzoka.'),
('kam', '1CO', 10, 10, 'O na mũikanyungunyĩsye, tondũ amwe moo manyungunyĩisye, na moawa nĩ ũla mũai.'),
('kam', '1CO', 10, 11, 'Maũndũ asu mamakĩtĩkĩe methĩwe ngelekan’yo; na maandĩkiwe kwondũ wa ũtũtaa ithyĩ, ala tũvikĩwe nĩ mũminũkĩlyo wa mavĩnda.'),
('kam', '1CO', 10, 12, 'Kwondũ wa ũu ũla ũnũkwona e mũũngamu, nĩesũvĩe ndakavalũke.'),
('kam', '1CO', 10, 13, 'Mũtyaakwatwa inyw’ĩ nĩ matatwa ate o ala mũndũ ũtonya kũmomĩĩsya: ĩndĩ Ngai e kĩthito, na ndakamũeka mũtatwe kũvĩtũka vinya wenyu; ĩndĩ vamwe na kũtatwa akamantha nzĩa ya kũthonoka, nĩ kana mũtonye kũmomĩĩsya.'),
('kam', '1CO', 10, 14, 'Kwondũ wa ũu, endwa makwa, kĩai kũthaitha mĩvw’anano.'),
('kam', '1CO', 10, 15, 'Nĩneena ta ngũneena na andũ oĩ; osyai maũndũ asu ngwasya.'),
('kam', '1CO', 10, 16, 'Kĩkombe kya ũathimo kĩla tũathimaa, ti mũamba wa nthakame ya Klĩsto? Kĩmũtũ kĩla tũtilaa, nakyo, ti mũamba wa mwĩĩ wa Klĩsto?'),
('kam', '1CO', 10, 17, 'Nĩkwĩthĩwa ithyĩ ala twĩ aingĩ, twĩ kĩmũtũ kĩmwe, mwĩĩ ũmwe; nũndũ ithyonthe twĩ osi ma kĩmũtũ o kĩmwe.'),
('kam', '1CO', 10, 18, 'Sisyai Isilaeli ũndũ mailyĩ kwa kũsyawa: asu maĩsaa nthembo mati na mũamba na kĩthembeo?'),
('kam', '1CO', 10, 19, 'Nĩasya ata ĩndĩ? Kĩndũ kĩthembeawa mĩvw’anano nĩ kĩndũ, o na mũw’anano nĩ kĩndũ?'),
('kam', '1CO', 10, 20, 'Ĩndĩ nĩasya, kana syĩndũ ila Andũ‐ma‐mbaĩ‐ingĩ mathembaa, mathembeaa ndaimoni, matĩthembeaa Ngai: nakwa ndikwenda mwĩthĩwe na mũamba na ndaimoni.'),
('kam', '1CO', 10, 21, 'Mũtitonya kũnyw’a kĩkombe kya Mwĩaĩi, na kĩkombe kya ndaimoni: mũtitonya kũĩsanĩa mesanĩ ya Mwĩaĩi, na mesanĩ ya ndaimoni.'),
('kam', '1CO', 10, 22, 'Kana twĩmwĩw’ĩthya Mwĩaĩi kĩwĩu? Twĩ na vĩnya kwĩ we?'),
('kam', '1CO', 10, 23, 'Maũndũ onthe nĩmatonyeka; ĩndĩ ti onthe maĩlaa. Maũndũ onthe nĩmatonyeka; ĩndĩ ti onthe makaa.'),
('kam', '1CO', 10, 24, 'Mũndũ o na wĩva ndakamanthe kwĩuna mwene, ĩndĩ kĩla mũndũ namanthe kũuna ũngĩ.'),
('kam', '1CO', 10, 25, 'Kĩla kĩthooaw’a kĩthĩnzĩonĩ, yai, mũteũkũlya ũkũlyo kwondũ wa wasya wa ngoo;'),
('kam', '1CO', 10, 26, 'nũndũ nthĩ nĩ ya Mwĩaĩi, na syĩndũ syonthe ila imyusĩe.'),
('kam', '1CO', 10, 27, 'Ethĩwa ũmwe wa ala matetĩkĩlĩte emwĩta mbokanĩ, na mwĩenda ũthi; yai o kĩla kĩiwa mbee wenyu, mũteũkũlya ũkũlyo kwondũ wa wasya wa ngoo.'),
('kam', '1CO', 10, 28, 'Ĩndĩ ethĩwa mũndũ akamũtavya, Kĩĩ nĩkĩthembewe mũvw’anano, mũikaye, kwondũ wa ũsu watavan’ya, na kwondũ wa wasya wa ngoo:'),
('kam', '1CO', 10, 29, 'nĩasya wasya wa ngoo, ti wasya wa ngoo waku, ĩndĩ wa ũsu ũngĩ; nũndũ kũthaw’a kwakwa kũsilĩĩlwa kĩ nĩ wasya wa ngoo wa ũngĩ?'),
('kam', '1CO', 10, 30, 'Ethĩwa nyie ngĩtũnga mũvea, nĩkĩ ngũwetwa naĩ nũndũ wa kĩla natũngĩa mũvea?'),
('kam', '1CO', 10, 31, 'Ethĩwa ĩndĩ nĩmũũya, kana kũnyw’a, kana o ũndũ mũkwĩka o na wĩva w’onthe, ĩkai maũndũ onthe kwa kũtaĩa Ngai.'),
('kam', '1CO', 10, 32, 'Mũikaete molulutĩkyo kwa Ayuti, o na kwa Akiliki, o na kwa ĩkanisa ya Ngai:'),
('kam', '1CO', 10, 33, 'o tondũ nyie nakwa nendeeasya andũ onthe maũndũnĩ onthe, ndeũmantha kwĩuna mwene, ĩndĩ nĩmanthaa kũuna aingĩ, nĩ kana matangĩĩwe.'),
('kam', '1CO', 11, 1, 'Ĩthĩwai mũkĩelekan’ya nakwa, o ũndũ nyie nakwa nĩelekanasya na Klĩsto.'),
('kam', '1CO', 11, 2, 'Na yu nĩngũmũkatha nĩkwĩthĩwa nĩmũndilikanaa maũndũnĩ onthe, na ĩngĩ nĩmũkwataa mũno momanyĩsyo asu, o ũndũ namũnengie.'),
('kam', '1CO', 11, 3, 'Ĩndĩ nĩenda mũmanye, kana mũtwe wa kila mũndũ mũũme nĩ Klĩsto; na mũtwe wa mũndũ mũka nĩ mũũme; na mũtwe wa Klĩsto nĩ Ngai.'),
('kam', '1CO', 11, 4, 'Kĩla mũndũ mũũme aivoya kana aiathana, evw’ĩkĩte mũtwe wake, nũsonokasya mũtwe wake.'),
('kam', '1CO', 11, 5, 'Ĩndĩ kĩla mũndũ mũka aivoya aiathana atevw’ĩkĩte mũtwe wake nũsonokasya mũtwe wake; nũndũ nĩ ũndũ ũmwe ki na kwenzwa.'),
('kam', '1CO', 11, 6, 'Nũndũ ethĩwa mũndũ mũka ndeũvw’ĩka mũtwe wake, natilwe nzw’ĩĩ nasyo: ĩndĩ ethĩwa nĩ nthoni kwa mũndũ mũka kũtilwa nzw’ĩĩ kana kwenzwa, navw’ĩke mũtwe.'),
('kam', '1CO', 11, 7, 'Nũndũ mũndũ mũũme ndaĩlwe nĩ kũvw’ĩka mũtwe wake, nũndũ we nĩ mũvw’ano na ũtaĩo wa Ngai; ĩndĩ mũndũ mũka nĩ ũtaĩo wa mũũme.'),
('kam', '1CO', 11, 8, 'Nũndũ mũndũ mũũme ndaauma kwa mũndũ mũka; ĩndĩ mũndũ mũka aumie kwa mũndũ mũũme:'),
('kam', '1CO', 11, 9, 'o na mũndũ mũũme ndaaũmbwa kwondũ wa mũndũ mũka; ĩndĩ nĩ mũndũ mũka wombiwe kwondũ wa mũndũ mũũme:'),
('kam', '1CO', 11, 10, 'kwondũ wa ũu nĩkwaĩle mũndũ mũka ethĩwe na wonan’yo wa wĩnyivyo wake mũtwenĩ wake, nũndũ wa alaĩka.'),
('kam', '1CO', 11, 11, 'Ĩndĩ vamwe na ũu, o na mũndũ mũka ndethĩwa vate mũndũ mũũme, o na mũndũ mũũme ndethĩwa vate mũndũ mũka, nthĩnĩ wa Mwĩaĩi.'),
('kam', '1CO', 11, 12, 'Nũndũ o ũndũ mũndũ mũka waumie kwa mũndũ mũũme, no ta ũu mũndũ mũũme nũsyaawa nĩ mũndũ mũka; ĩndĩ maũndũ onthe maumaa kwa Ngai.'),
('kam', '1CO', 11, 13, 'Osyai inyw’ĩ ene: nĩkwaĩle mũndũ mũka kũmũvoya Ngai atevw’ĩkĩte mũtwe?'),
('kam', '1CO', 11, 14, 'O na mũtuo e w’o ndũũmũmanyĩsya, kana, ethĩwa mũndũ mũũme e na nzw’ĩĩ ndasa, nĩ nthoni kwake?'),
('kam', '1CO', 11, 15, 'Ĩndĩ ethĩwa mũndũ mũka e na nzw’ĩĩ ndasa, nĩ ũtaĩo kwake: nũndũ nzw’ĩĩ syake anengiwe syĩthĩwe sya kũmũvw’ĩkaa.'),
('kam', '1CO', 11, 16, 'Ĩndĩ ethĩwa mũndũ o na wĩva ailyĩ ta wĩ na ngananĩo, ithyĩ tũti na ũndũ ũsu, o na makanisa ma Ngai.'),
('kam', '1CO', 11, 17, 'Ĩndĩ ngĩmwĩaĩa mĩao ĩno, ndĩũmũkathĩĩa, nĩkwĩthĩwa nĩmũkũmbana, na ti kwondũ wa ũseo, ĩndĩ kwondũ wa ũthũku.'),
('kam', '1CO', 11, 18, 'Nũndũ mbee wa maũndũ angĩ, yĩla mũmbanaa ĩkanisanĩ, nĩw’aa kana motĩlĩkangano me katĩ wenyu; nakwa nĩngwĩtĩkĩla ũvoo ũsu vanini.'),
('kam', '1CO', 11, 19, 'Nũndũ vaitĩa kwĩthĩwa ũvathũkan’yo katĩ wenyu, nĩ kana asu metĩkĩlĩtwe matonye ũmanyĩka kwenyu.'),
('kam', '1CO', 11, 20, 'Ĩndĩ yĩla mũmbanaa vamwe, mũitonya ũya kya ũya kya mesa ya Mwĩaĩi:'),
('kam', '1CO', 11, 21, 'nũndũ mũkĩya, kĩla ũmwe ambaa kũya kya ũya kyake mwene mbee wa ũngĩ; na ũmwe e na nzaa, na ũngĩ nũnyw’ĩte.'),
('kam', '1CO', 11, 22, 'Nĩkĩ, mũti na nyũmba syenyu sya kũya lĩu na kũnyw’a? Kana mwĩvũthya ĩkanisa ya Ngai, na kũmasonokya asu mate kĩndũ? Nĩmwĩa ata? Nĩmũkathĩĩe kwondũ wa ũu? Aiee, ndiũmũkathĩĩa.'),
('kam', '1CO', 11, 23, 'Nũndũ nyie noosie kwa Mwĩaĩi kyu kĩla namũnengie inyw’ĩ, kana Mwĩaĩi Yesu, ũtũku ũla wavũnyanĩiwe oosie kĩmũtũ;'),
('kam', '1CO', 11, 24, 'na atũnga mũvea, atilan’ya na asya, Kĩĩ nĩkyo mwĩĩ wakwa, naw’o nĩ kwondũ wenyu: ĩkaai ũu ũndũ wa kũndilikana.'),
('kam', '1CO', 11, 25, 'No ta ũu oosie kĩkombe nakyo, ĩtina wa kũya, aiasya, Kĩkombe kĩĩ nĩ ũtianio mweũ nthakamenĩ yakwa: ĩkaai ũu, yĩla mũũnyw’a, ũndũ wa kũndilikana.'),
('kam', '1CO', 11, 26, 'Nũndũ o yĩla mũũya kĩmũtũ kĩĩ, na kũnyw’a kĩkombe kĩĩ, mwionan’ya kĩkw’ũ kya Mwĩaĩi kũvika yĩla wĩũka.'),
('kam', '1CO', 11, 27, 'Kwondũ wa ũu o mũndũ ũla wĩya kĩmũtũ kana kũnyw’a kĩkombe kya Mwĩaĩi ũndũ ũtaĩle, eĩyosea ũsilĩlo wa ũla mwĩĩ na ĩla nthakame ya Mwĩaĩi.'),
('kam', '1CO', 11, 28, 'Ĩndĩ mũndũ nĩeosye, na ĩndĩ naye kĩmũtũ, na ainyw’a kĩkombe.'),
('kam', '1CO', 11, 29, 'Nũndũ ũla ũĩsaa na kũnyw’a ateũvathũkan’ya ũla mwĩĩ, aĩsaa na kũnyw’a ũsilĩlo wake mwene.'),
('kam', '1CO', 11, 30, 'Kwondũ wa ũu aingĩ kwenyu nĩ syonze na awau, na ala makomete ti avũthũ.'),
('kam', '1CO', 11, 31, 'Ĩndĩ ethĩwa nĩtũkwĩsilĩla ene, tũisilĩlwa.'),
('kam', '1CO', 11, 32, 'Ĩndĩ tũkĩsilĩlwa, nĩtũũkanw’a nĩ Mwĩaĩi, nĩ kana tũikasilĩlwe vamwe na nthĩ.'),
('kam', '1CO', 11, 33, 'Kwondũ wa ũu, ana‐a‐asa makwa, mwoombana vamwe kũya, eteelanai inyw’ĩ kwa ĩnyw’ĩ.'),
('kam', '1CO', 11, 34, 'Ethĩwa mũndũ e na nzaa, naye nyũmbanĩ kwake; nĩ kana kũmbana kwenyu kũikethĩwe kwa kũvĩkĩa ũsilĩlo. Na maũndũ ala matiele ngaseũvya nooka.'),
('kam', '1CO', 12, 1, 'Na yu, ana‐a‐asa, ndikwenda mũlee ũmanya ũndũ wa mĩthĩnzĩo ya veva.'),
('kam', '1CO', 12, 2, 'Nĩmwĩsĩ kana yĩla mwaĩ Andũ‐mambaĩ‐ingĩ nĩmwaaĩtw’e na kũvikĩla mĩvw’anano ĩla ĩtaneenaa, o ũndũ mwatongoew’e.'),
('kam', '1CO', 12, 3, 'Kwondũ wa ũu nĩmũmanyĩthya, kana vai mũndũ ũneenaa nthĩnĩ wa Veva wa Ngai waasya, Yesũ nĩ anathema (ũalyũlo wayo nĩ, nũumanĩwe); na vai mũndũ ũtonya kwasya, Yesũ nĩ Mwĩaĩi, ate o nthĩnĩ wa Veva Mũtheu.'),
('kam', '1CO', 12, 4, 'Na ĩndĩ kwĩ ivathũkan’yo sya mĩthĩnzĩo, ĩndĩ Veva no ũmwe.'),
('kam', '1CO', 12, 5, 'Na kwĩ ivathũkan’yo sya mothũkũmi, na Mwĩaĩi no ũmwe.'),
('kam', '1CO', 12, 6, 'Na kwĩ ivathũkan’yo sya kwĩka, ĩndĩ nĩ Ngai o ũmwe, ũla wĩkaa maũndũ onthe nthĩnĩ wa onthe.'),
('kam', '1CO', 12, 7, 'Ĩndĩ kĩla mũndũ anengawe wonan’yo wa Veva kwondũ wa kwaĩlan’ya.'),
('kam', '1CO', 12, 8, 'Nũndũ ũmwe anengawe ndeto ya ũĩ nĩ Veva; na ũngĩ anengawe ndeto ya ũmanyĩ, nĩ Veva o ũsu ũmwe;'),
('kam', '1CO', 12, 9, 'na ũngĩ anengawe mũĩkĩĩo, nĩ Veva o ũsu ũmwe; na ũngĩ anengawe mĩthĩnzĩo ya ũvosya mowau, nĩ Veva o ũsu ũmwe;'),
('kam', '1CO', 12, 10, 'na ũngĩ anengawe kwĩka mavinya; na ũngĩ anengawe kwathana; na ũngĩ kũvathũkan’ya maveva; na ũngĩ mĩthemba ya ithyomo; na ũngĩ kũalyũla ĩthyomo:'),
('kam', '1CO', 12, 11, 'ĩndĩ Veva o ũsu ũmwe nĩwĩkaa maũndũ aa onthe na kũmũaĩa kĩla mũndũ, ũndũ Veva ũnũkwenda.'),
('kam', '1CO', 12, 12, 'Nũndũ o tondũ mwĩĩ nĩ ũmwe, na wĩ na mamutha maingĩ, na mamutha onthe ma mwĩĩ, me maingĩ, nĩ mwĩĩ ũmwe; Klĩsto nake ailyĩ o ta ũu.'),
('kam', '1CO', 12, 13, 'Nũndũ nthĩnĩ wa Veva ũmwe nĩtwavatisiwe ithyonthe kũlikwa mwĩĩnĩ ũmwe, o na ethĩwa twĩ Ayuti kana twĩ Akiliki, kana ethĩwa twĩ ngombo, kana tũti ngombo; naitũ ithyonthe twanyw’ĩthw’e Veva o ũmwe.'),
('kam', '1CO', 12, 14, 'Nũndũ mwĩĩ ti mutha ũmwe, ĩndĩ nĩ mamutha maingĩ.'),
('kam', '1CO', 12, 15, 'Ethĩwa kũũ kũkasya, Nũndũ tii nyie kw’oko, nyie ndi wa mwĩĩ; tiw’o ũtuma kũtethĩwa kwa mwĩĩ.'),
('kam', '1CO', 12, 16, 'Na ethĩwa kũtũ kũkasya, Nĩkwĩthĩwa tii nyie itho, nyie ndi wa mwĩĩ; ti ũu ũtuma kũtethĩwa mwĩĩ.'),
('kam', '1CO', 12, 17, 'Ethĩwa mwĩĩ w’onthe nĩ itho, kũĩva kwĩw’a? Ethĩwa mwĩĩ w’onthe nĩ kwĩw’a, kũĩva kũnyungĩa?'),
('kam', '1CO', 12, 18, 'Ĩndĩ yu Ngai eekĩie kĩla mutha mwĩĩnĩ, o ũndũ wendie.'),
('kam', '1CO', 12, 19, 'Na ethĩwa mamutha onthe nĩ mutha ũmwe, mwĩĩ ũĩva?'),
('kam', '1CO', 12, 20, 'Ĩndĩ yu nĩ mamutha maingĩ, ĩndĩ mwĩĩ no ũmwe.'),
('kam', '1CO', 12, 21, 'Na itho yĩtitonya kũtavya kw’oko, Ndi vata naku we: o na mũtwe ndũtonya kũtavya maũũ, Ndi vata nenyu.'),
('kam', '1CO', 12, 22, 'Ĩndĩ mbee mũno, mamutha asu ma mwĩĩ ala matalawa ta monzu mbee, me na vata mũno:'),
('kam', '1CO', 12, 23, 'na mamutha ma mwĩĩ, ala tũmatalĩlasya nĩ manyivu ndaĩa, nĩtũmataĩaa asu mũno mbee; na mamutha maitũ mate na ũseo, me na ũseo mbee mũno;'),
('kam', '1CO', 12, 24, 'nĩkwĩthĩwa mamutha maitũ me na ndaĩa mati na vata; ĩndĩ Ngai nĩwathalanilye mwĩĩ, na kũũnenga ndaĩa mbee mutha ũla ũnyivĩw’e;'),
('kam', '1CO', 12, 25, 'nĩ kana kũikethĩwe ũtilĩkangano mwĩĩnĩ; ĩndĩ nĩ kana mamutha onthe masũvĩanae.'),
('kam', '1CO', 12, 26, 'Na ethĩwa mutha ũmwe nũũkwatwa nĩ woo, aa angĩ onthe mathĩnaa vamwe naw’o; kana mutha ũmwe nũũtaĩwa, aa angĩ onthe nĩmatanaa vamwe naw’o.'),
('kam', '1CO', 12, 27, 'Na ĩndĩ inyw’ĩ mwĩ mwĩĩ wa Klĩsto, na ũmwe na ũmwe mwĩ mamutha maw’o.'),
('kam', '1CO', 12, 28, 'Na Ngai aiĩte amwe ĩkanisanĩ, mbee nĩ atũmwa, kelĩ athanĩ, katatũ amanyĩsya, na ĩtina mavinya, na ĩndĩ mĩthĩnzĩo ya kũvosya mowau, na motethan’yo, na motao moĩ, na mĩthemba ya ithyomo,'),
('kam', '1CO', 12, 29, 'Onthe nĩ atũmwa? Kana onthe nĩ athani? Kana onthe nĩ amanyĩsya? Kana onthe nĩ eki ma mavinya?'),
('kam', '1CO', 12, 30, 'Kana onthe me na mĩthĩnzĩo ya kũvosya mowau? Kana onthe nĩmaneena na ithyomo ingĩ? Kana onthe nĩmaalyũlaa ithyomo?'),
('kam', '1CO', 12, 31, 'Ĩndĩ endai mũno mĩthĩnzĩo ĩla mĩseo. Na ĩngĩ nĩmwon’ya nzĩa nzeo mbee.'),
('kam', '1CO', 13, 1, 'O na nganeena na ithyomo sya andũ na sya alaĩka, nakwa ndi na wendo, ndwĩkĩte kĩndũ kĩtuĩtwe kya ũthuku kĩambaa, kana kĩla kĩkayaa.'),
('kam', '1CO', 13, 2, 'O na ngethĩwa na wathani, na kũmanya nzama syonthe na ũmanyi w’onthe; o na ngethĩwa na mũĩkĩĩo w’onthe, o na wa kũthamya iĩma, na ndi na wendo, nyie tĩ kĩndũ.'),
('kam', '1CO', 13, 3, 'O na ngaumya syĩndũ syakwa syonthe kũĩthya ngya, na nganengane mwĩĩ wakwa ũvĩvw’e na mwaki, nde na wendo, ndũndandĩthĩsya kĩndũ, nongi.'),
('kam', '1CO', 13, 4, 'Wendo nĩwũmĩĩasya, na nĩwĩkaa moseo; wendo ndwĩ na kĩwĩu; wendo ndwĩtũlasya, o na ndwĩkathĩĩaa,'),
('kam', '1CO', 13, 5, 'o na ndwĩkaa ũndũ ũtaĩle, o na ndwĩmanthĩaa syĩndũ, o na ndũthataa, na ndũtalĩlaa ũthũku;'),
('kam', '1CO', 13, 6, 'ndũtanĩaa ũndũnĩ ũte ũlũngalu, ĩndĩ ũtanaa vamwe na ũla w’o;'),
('kam', '1CO', 13, 7, 'nũvw’ĩkaa maũndũ onthe, nĩwĩtĩkĩlaa maũndũ onthe, nĩwĩkwatasya maũndũ onthe, nĩwũmĩĩasya maũndũ onthe.'),
('kam', '1CO', 13, 8, 'Wendo ndũnyivaa o na ĩndĩĩ; ĩndĩ kwethĩwa kwĩ mawathanĩ, makavetwa; kwethĩwa kwĩ ithyomo, ikathela; kwethĩwa kwĩ ũmanyi, ũkavetwa.'),
('kam', '1CO', 13, 9, 'Nũndũ nĩtũmanyaa kũvũthũ, na nĩtwathanaa kũvũthũ:'),
('kam', '1CO', 13, 10, 'ĩndĩ yĩla kĩũka kĩla kĩanĩu, kĩla kĩvũthũ kĩkavetwa.'),
('kam', '1CO', 13, 11, 'Yĩla naĩ kana, naneenaa ta kana, namanyaa ta kana, nasũanĩaa ta kana: ĩndĩ yu nĩtw’ĩkĩte mũndũ mũima, nĩnĩvetete maũndũ ma wana.'),
('kam', '1CO', 13, 12, 'Nũndũ ĩvinda yĩĩ twĩona ta kĩsisyonĩ kĩ menyenyi; ĩndĩ ĩvinda yĩu tũkoona ũthyũ kwa ũthyũ: yu nĩnĩsĩ kũvũthũ; ĩndĩ ĩvinda yĩu ngamanya vyũ, o ũndũ nakwa neesĩkĩwe vyũ.'),
('kam', '1CO', 13, 13, 'Ĩndĩ yu kwĩkalĩte mũĩkĩĩo, na wĩkwatyo, na wendo, asu atatũ; na mũnene wa asu nĩ wendo.'),
('kam', '1CO', 14, 1, 'Atĩĩai wendo; na endai mũno mĩthĩnzĩo ya veva, ĩndĩ mbee nĩ kana mũtonye kwathana.'),
('kam', '1CO', 14, 2, 'Nũndũ ũla ũneenaa na kĩthyomo ndeũneena na andũ, ĩndĩ aneenaa na Ngai; nũndũ vai mũndũ ũnũkwĩw’a; ĩndĩ nthĩnĩ wa veva wake aneenaa nzama.'),
('kam', '1CO', 14, 3, 'Ĩndĩ ũla wathanaa aneenaa na andũ maũndũ ma kũmakaa, na kũmataa, na kũmakiakisya.'),
('kam', '1CO', 14, 4, 'Ũla ũneenaa na kĩthyomo eyakaa mwene; ĩndĩ ũsu wathanaa akaa ĩkanisa.'),
('kam', '1CO', 14, 5, 'Na nĩenda inyw’onthe mũneene na ithyomo, ĩndĩ mbee, nĩ kavaa mwathane: na ũsu wathanaa nĩ mũnene kwĩ ũla ũneenaa na ithyomo, ate o akĩalyũla, nĩ kana ĩkanisa yĩtonye kwakwa.'),
('kam', '1CO', 14, 6, 'Ĩndĩ, ana‐a‐asa, ethĩwa nĩũka kwenyu ngĩneena na ithyomo, ngamũuna na kyaũ, ndeũneena nenyu na ũvuan’yo, kana na ũmanyi, kana na wathani, kana na kũmanyĩsya?'),
('kam', '1CO', 14, 7, 'O na syĩndũ ite na thayũ ila syĩ wasya, ethĩwa nĩ mũtũlilũ kana mbeve, ite mawasya me kĩvathũkan’yo, ũkamanyĩka ata wasya ũla ũkũvuvwa kana ũla ũkũingwa?'),
('kam', '1CO', 14, 8, 'Nũndũ ethĩwa soo ũkavuvwa wasya ũtesĩkĩe, nũũ ũla wĩyũmban’ya kũkita?'),
('kam', '1CO', 14, 9, 'Nenyu no ta ũu, mũteũneena na ũĩmĩ ndeto itonya ũmanyĩka na mĩtũkĩ, ũkamanyĩka ata ũndũ ũla ũũneenwa? Kũndũ mũkeethĩwa mũineena mana.'),
('kam', '1CO', 14, 10, 'Nĩkũtonya kwĩthĩwa ithyomo nyingĩ kũũ nthĩ, na kũi kĩmwe kĩte na ũvoo wakyo.'),
('kam', '1CO', 14, 11, 'Ĩndĩ ethĩwa ndyĩsĩ ũalyũlo wa wasya wa ũla ũnũũneena, ngeethĩwa nĩ ta mũndũ wa kĩthyomo kĩngĩ vala ũĩ, na ngĩneena nyie akeethĩwa ta mũndũ wa kĩthyomo kĩngĩ vala nĩĩ.'),
('kam', '1CO', 14, 12, 'O ta ũu inyw’ĩ, kwa kwĩthĩwa nĩmũkwenda mũno kwĩthĩwa na mĩthĩnzĩo ya veva, manthai nĩ kana mũtonye kwingĩvĩw’a kwondũ wa kwaka ĩkanisa.'),
('kam', '1CO', 14, 13, 'Kwondũ wa ũu ũla ũneenaa na kĩthyomo, navoye nĩ kana atonye kũkĩalyũla.'),
('kam', '1CO', 14, 14, 'Nũndũ ethĩwa nĩvoya na kĩthyomo, veva wakwa nũũvoya, ĩndĩ kũmanya kwakwa kũti ũsyao.'),
('kam', '1CO', 14, 15, 'Nĩ kyaũ ĩndĩ? Ngavoya na veva, na ngavoya na ũmanyi naw’o: ngaina na veva, na ngaina na ũmanyi naw’o.'),
('kam', '1CO', 14, 16, 'Na ĩngĩ ethĩwa wĩtaĩa na veva, ũsu ũtwĩe ataamanyĩw’a, akasya Amenĩ ata, kwondũ wa kũtũnga mũvea kwaku, nĩkwĩthiwa ndesi ũndũ ũkwasya?'),
('kam', '1CO', 14, 17, 'Nũndũ nĩ w’o nũtũngaa mũvea nesa, ĩndĩ ũsu ũngĩ ndekwakwa.'),
('kam', '1CO', 14, 18, 'Nĩmũtungĩa Ngai mũvea, nũndũ nĩneenaa na ithyomo kwĩ inyw’onthe:'),
('kam', '1CO', 14, 19, 'ĩndĩ ĩkanisanĩ nĩenda kũneena ndeto itano na ũmanyi wakwa, nĩ kana ndonye ũmanyĩsya angĩ nao, kwĩ kũneena ndeto ngili ĩkũmi na kĩthyomo.'),
('kam', '1CO', 14, 20, 'Ana‐a‐asa, mũikethĩwe syana ilĩkonĩ syenyu: ĩndĩ kũla kwĩ ũthũkũ ĩthĩwaĩ tũũkenge, ĩndĩ kĩlĩkonĩ ĩthĩwai mwĩ aima.'),
('kam', '1CO', 14, 21, 'Mĩaonĩ nĩkũandĩkĩtwe, Nganeena na andũ aa na andũ me na ithyomo ĩtesĩkĩwe, na ilomo sya aenĩ; ĩndĩ o na neeka ũu, maikambĩw’a, eneena ũu Ngai.'),
('kam', '1CO', 14, 22, 'Kwondũ wa ũu ithyomo nĩ kwondũ wa wonan’yo, na ti kwondũ wa ala metĩkĩlĩte, ĩndĩ nĩ kwondũ wa ala matetĩkĩlĩte; ĩndĩ kwathana ti kwondũ wa ala matetĩkĩlĩte, ĩndĩ nĩ kwondũ wa ala metĩkĩlĩte.'),
('kam', '1CO', 14, 23, 'Ĩndĩ ethĩwa ĩkanisa yonthe nĩyũmbanĩte vamwe, na onthe maĩneena na ithyomo, na vaiũka vo andũ mataamanyĩw’a kana ala matetĩkĩlĩte, matiasya kana mwĩ na ndũũka?'),
('kam', '1CO', 14, 24, 'Ĩndĩ ethĩwa onthe nĩmekwathana, na vailika mũndũ ũtetĩkĩlĩte kana ũtaamanyĩw’a, nũnũũkanw’a nĩ onthe, na kũsilĩlwa nĩ onthe;'),
('kam', '1CO', 14, 25, 'maũndũ mavithe ma ngoo yake nĩmonanĩtw’e; na kwondũ wa ũu akavalũka na ũthyũ na kũmũthaitha Ngai na kũtavan’ya kana nĩ w’o Ngai e katĩ wenyu.'),
('kam', '1CO', 14, 26, 'Nĩ kyaũ ĩndĩ, ana‐a‐asa? Mwoombana vamwe, kĩla mũndũ e na wathi wa savuli, e na ũmanyĩsyo, e na ũvuan’yo, e na kĩthyomo, e na ũalyũli. Maũndũ onthe nĩmekwe kwondũ wa kwaka.'),
('kam', '1CO', 14, 27, 'Ethĩwa mũndũ o na wĩva eneena na kĩthyomo, nĩkwĩthĩwe elĩ, kũikathonoke atatũ, na asu nao makĩatĩanĩa; na ũmwe naalyũle:'),
('kam', '1CO', 14, 28, 'ĩndĩ ethĩwa kũi mũalyũli, navindye ĩkanisanĩ; naneena na ngoo yake mwene, na Ngai.'),
('kam', '1CO', 14, 29, 'Na athani nĩmaneene elĩ kana atatũ, na ala angĩ nĩmavathũkan’ye.'),
('kam', '1CO', 14, 30, 'Ĩndĩ ethĩwa ũngĩ ũilyĩ nthĩ nũnũũvuanĩw’a ũndũ, ũsu wa mbee navindye.'),
('kam', '1CO', 14, 31, 'Nũndũ nĩmũtonya kwathana inyw’onthe, na ũmwe, nĩ kana onthe memanyĩsye, na ĩngĩ kana onthe matawe;'),
('kam', '1CO', 14, 32, 'na maveva ma athani nĩmew’aa athani;'),
('kam', '1CO', 14, 33, 'nũndũ Ngai ti Ngai wa kĩthokoan’yo, ĩndĩ nĩ wa mũuo. O ũndũ kũilyĩ makanisanĩ onthe ma atheu,'),
('kam', '1CO', 14, 34, 'aka nĩmekale mavindĩtye ĩkanisanĩ: nũndũ mati na ũthei wa kũneena; ĩndĩ nĩmenyivye, o ũndũ mĩao ĩnĩkwasya nayo.'),
('kam', '1CO', 14, 35, 'Na ethĩwa nĩmekwenda ũmanya ũndũ o na wĩva, nĩmakũlye aũme moo ene nyũmbanĩ kwoo: nũndũ nĩ nthoni mũndũ mũka kũneena ĩkanisanĩ.'),
('kam', '1CO', 14, 36, 'Nĩ kyaũ? Ndeto ya Ngai yaumie kwenyu? Kana yamũvikĩe inyw’oka?'),
('kam', '1CO', 14, 37, 'Ethĩwa mũndũ o na wĩva eĩtalĩlya mwene kwĩthĩwa nĩ mwathanĩ, kana nĩ wa vevanĩ, namanye nesa maũndũ asu ngũmũandĩkĩa, kana nĩ mwĩao wa Mwĩaĩi.'),
('kam', '1CO', 14, 38, 'Ĩndĩ ethĩwa mũndũ o na wĩva nde na ũmanyi, nĩethĩwe ate na ũmanyi.'),
('kam', '1CO', 14, 39, 'Kwondũ wa ũu, ana‐a‐asa, endai mũno kwathana, na mũikavatane kũneena na ithyomo.'),
('kam', '1CO', 14, 40, 'Ĩndĩ maũndũ onthe nĩmekwe ũndũ kwaĩle, maatĩanĩe.'),
('kam', '1CO', 15, 1, 'Na yu, ana‐a‐asa, nĩmũmanyĩthya ũla ũvoo mũseo ũla namũtavisye, ũla naw’o mwoosie, na ũla nthĩnĩ waw’o mũũngeme,'),
('kam', '1CO', 15, 2, 'na kwondũ waw’o nĩmũũtangĩĩwa, ethĩwa mwĩlũmya ndeto ĩla namũtavisye, ateo o mweetĩkĩlile mana.'),
('kam', '1CO', 15, 3, 'Nũndũ mbee namũtavisye o ũla noosie nakwa: atĩ Klĩsto nĩwakwie kwondũ wa naĩ sitũ kwĩanana na maandĩko;'),
('kam', '1CO', 15, 4, 'na nĩwathikiwe; na kana nĩwathayũũkiw’e mũthenya wa katatũ kwĩanana na maandĩko;'),
('kam', '1CO', 15, 5, 'na nĩwamumĩlĩle Keva; na amaumĩlĩla ala ĩkũmi na elĩ;'),
('kam', '1CO', 15, 6, 'na ĩtina amaumĩlĩla ana‐a‐asa, andũ mbee wa maana atano, ĩvinda o yĩmwe, na aingĩ moo me o kw’o kũvika o na yu, ĩndĩ amwe nĩmakomete;'),
('kam', '1CO', 15, 7, 'na ĩtina wa ũu nĩwamumĩlĩle Yakovo; na ĩndĩ amaumĩlĩla atũmwa onthe;'),
('kam', '1CO', 15, 8, 'na ĩtina wa onthe anumĩlĩla nyie, ta ũmwe ũsyaĩtwe ĩvĩnda yĩte ya w’o.'),
('kam', '1CO', 15, 9, 'Nũndũ nyie nĩ mũnini kwĩ atũmwa onthe, ũla ũtaĩle kwĩtwa mũtũmwa, nĩkwĩthĩwa nathĩnisye ĩkanisa ya Ngai.'),
('kam', '1CO', 15, 10, 'Ĩndĩ kwondũ wa mũmo wa Ngai nĩilyĩ o ũndũ ndilyĩ: na mũmo wake nanengiwe ndwaĩ wa mana; ĩndĩ nathĩnĩe wĩa mbee wa asu angĩ onthe; ĩndĩ ti nyie, nĩ mumo wa Ngai ũla waĩ vamwe nakwa.'),
('kam', '1CO', 15, 11, 'Ĩndĩ ethĩwa nĩnyie kana nĩo, nĩw’o tũtavanasya, na nĩw’o mweetĩkĩlile.'),
('kam', '1CO', 15, 12, 'Na ethĩwa Klĩsto nũtavanaw’a kana nĩwathayũũkiw’e kuma kwa akw’ũ, amwe katĩ wenyu measya ata kana kũi kũthayũũkw’a kwa akw’ũ?'),
('kam', '1CO', 15, 13, 'Ĩndĩ ethĩwa kũi kũthayũũkw’a kwa akw’ũ, o na Klĩsto ndaathayũũkw’a:'),
('kam', '1CO', 15, 14, 'na ethĩwa Klĩsto ndaathayũũkw’a, kũtavan’ya kwitũ nĩ mana, na mũĩkĩĩo wenyu naw’o nĩ mana.'),
('kam', '1CO', 15, 15, 'Ĩĩ, o naitũ twonekete kwĩthĩwa ngũsĩ sya ũvũngũ sya Ngai; nĩkwĩthĩwa twaĩ ngũsĩ sya Ngai atĩ nĩwamũthayũũkisye Klĩsto: nake ndaamũthayũũkya, ethĩwa nĩ w’o kana akw’ũ maithayũũkaw’a.'),
('kam', '1CO', 15, 16, 'Nũndũ ethĩwa akw’ũ maithayũũkaw’a, o na Klĩsto ndaathayũũkw’a:'),
('kam', '1CO', 15, 17, 'na ethĩwa Klĩsto ndaathayũũkw’a, mũĩkĩĩo wenyu nĩ mana; na kũvika na yu mwĩ o naĩnĩ syenyu.'),
('kam', '1CO', 15, 18, 'Na ĩndĩ asu nao ala makomete nthĩnĩ wa Klĩsto nĩ au.'),
('kam', '1CO', 15, 19, 'Ethĩwa ithyĩ tũtw’ĩkĩte twĩkwatĩtye Klĩsto ũndũ wa thayũ ũũ w’oka, twĩ ma kwĩw’ĩwa tei mbee wa andũ angĩ onthe.'),
('kam', '1CO', 15, 20, 'Ĩndĩ yuyu Klĩsto nĩwathayũũkiw’e kuma kwa akw’ũ, ũsyao wa mbee wa ala makomete.'),
('kam', '1CO', 15, 21, 'Nũndũ nĩkwĩthĩwa kĩkw’ũ nĩkyookie kwondũ wa mũndũ, kũthayũũka kwa akw’ũ nakw’o nĩkwookie kwondũ wa mũndũ.'),
('kam', '1CO', 15, 22, 'Nũndũ o ũndũ onthe makusaa nthĩnĩ wa Atamu, o ta ũu nthĩnĩ wa Klĩsto onthe makeethĩwa thayũ.'),
('kam', '1CO', 15, 23, 'Ĩndĩ nĩ kĩla mũndũ vandũ vake mwene: Klĩsto ũsyao wa mbee; na ĩtina nĩ ala ma Klĩsto, yĩla wĩũka.'),
('kam', '1CO', 15, 24, 'Na ĩndĩ mũminũkĩlyo ũkyũka, yĩla Klĩsto ũkamũnenga Ngai, nake nĩwe Asa, ũla ũsumbĩ; yĩla ũkethĩwa avetete kĩla ũnene na kĩla ũkũmũ na vinya.'),
('kam', '1CO', 15, 25, 'Nũndũ mũvaka asumbĩke e we, kũvika yĩla ũkamaia amaitha make onthe ungu wa nyaĩĩ syake.'),
('kam', '1CO', 15, 26, 'Mũmaitha wa mũminũkĩlyo ũla ũkanangwa nĩ kĩkw’ũ.'),
('kam', '1CO', 15, 27, 'Nũndũ, aiie syĩndũ syonthe syĩthĩwe wĩnyivyonĩ ungu wa nyaĩĩ syake. Ĩndĩ yĩla ũnũkwasya, Syĩndũ syonthe siĩtwe wĩnyivyonĩ, nĩkwenekee kana nde vo we ũla waiie syĩndũ syonthe wĩnyivyonĩ kwake.'),
('kam', '1CO', 15, 28, 'Na syĩndũ syonthe syaiwa wĩnyivyonĩ kwake, nĩvo ĩndĩ Mwana nake ũkaiwa wĩnyivyonĩ kwa ũla wiĩte syĩndũ syonthe ũnyivyonĩ kwake, nĩ kana Ngai ethĩwe syonthe nthĩnĩ wa syonthe.'),
('kam', '1CO', 15, 29, 'Kana makeeka ata ala mavatisawa kwondũ wa akw’ũ? Ethĩwa akw’ũ maithayũũkw’a nongi, mavatisawa kwondũ wa akw’ũ nũndũ wa kĩ?'),
('kam', '1CO', 15, 30, 'Na ithyĩ twĩ mũisyonĩ kĩla saa nũndũ wa kĩ?'),
('kam', '1CO', 15, 31, 'Ĩĩ, kwondũ wa kwĩkathĩĩa kũla nĩ nakw’o kwondũ wenyu nthĩnĩ wa Klĩsto Yesũ, Mwĩaĩi waitũ, ana‐a‐asa, nĩngusaa kĩla mũthenya.'),
('kam', '1CO', 15, 32, 'Ethĩwa nokitie na nyamũ sya kĩthekanĩ na ku Eveso, o tondũ andũ mekaa, ngaunwa nĩ kyaũ? Ethĩwa akw’ũ matithayũũkw’a, tũye na tũinyw’a, nĩkwĩthĩwa ũnĩ tũkakw’a.'),
('kam', '1CO', 15, 33, 'Mũikakengeke: Itindo nthũkũ nĩsyanangaa mwĩkalĩle mũseo.'),
('kam', '1CO', 15, 34, 'Amũkai mwĩke nesa, na mũikeke naĩ; nũndũ amwe matiũmũmanya Ngai: nĩneena ũu nĩmũsonokye.'),
('kam', '1CO', 15, 35, 'Ĩndĩ kũkeethĩwa ũmwe wĩasya, Akw’ũ mathayũũkaw’a ata? Nao mokaa na mwĩĩ ũilyĩ ata?'),
('kam', '1CO', 15, 36, 'Wĩ mũtumanu, we; kĩla ũvuĩaa kĩinengawe thayũ kĩtanakw’a:'),
('kam', '1CO', 15, 37, 'na kĩla ũvuĩaa, ndũvuĩaa mwĩĩ ũla ũkethĩwa vo, ĩndĩ no mbeke nthei, o na yethĩwa nĩ ya nganũ, kana ya mũthemba ũngĩ;'),
('kam', '1CO', 15, 38, 'ĩndĩ Ngai amĩnengae mwĩĩ o tondũ wendaa, na kĩla mbeke mwĩĩ wayo,'),
('kam', '1CO', 15, 39, 'Nyama syonthe ti nyama ĩmwe: ĩndĩ ve nyama ĩmwe ya andũ, na ve nyama ĩngĩ ya nyamũ, na nyama ĩngĩ ya nyũnyi, na ĩngĩ ya makũyũ.'),
('kam', '1CO', 15, 40, 'Na ĩngĩ kwĩ mĩĩ ya ĩtunĩ, na mĩĩ ya nthĩ: ĩndĩ ũtheu mũtisu wa ĩla ya ĩtũnĩ nĩ ũmwe, na ũtheu mũtisu wa ĩla ya nthĩ nĩ ũngĩ.'),
('kam', '1CO', 15, 41, 'Kwĩ ũtheu mũtisu ũmwe wa syũa, na ũngĩ wa mwei, na ũngĩ wa ndata; nũndũ kwĩ kĩvathũkan’yo kya ũtheu mũtisu ndatanĩ ĩmwe na ĩla ĩngĩ.'),
('kam', '1CO', 15, 42, 'Kũthayũũkw’a kwa akw’ũ no ta ũu. Mwĩĩ nũvandawa ũla woaa; nũthayũũkaw’a na mwĩkalĩle ũte wa kwoa:'),
('kam', '1CO', 15, 43, 'nũvandawa ũte na ndaĩa; nũthayũũkaw’a wĩ na ndaĩa: nũvandawa wĩ mwonzu; nũthayũũkaw’a wĩ na vinya:'),
('kam', '1CO', 15, 44, 'nũvandawa mwĩĩ wa kĩ‐mũndũ; nũthayũũkaw’a mwĩĩ wa veva. Ethĩwa kwĩ mwĩĩ wa kĩ‐mũndũ, kwĩ mwĩĩ wa veva naw’o.'),
('kam', '1CO', 15, 45, 'O ta ũu naw’o nĩkũandĩkĩtwe, Mũndũ wa mbee, Atamu, atw’ĩka mũndũ wĩ thayũ, Atamũ wa mũminũkĩlyo atw’ĩka veva ũnenganae thayũ.'),
('kam', '1CO', 15, 46, 'Ĩndĩ ũla wa mbee tiw’o wa veva, ĩndĩ nĩ ũla wa kĩ‐mũndũ; na ĩtina ũla wa veva.'),
('kam', '1CO', 15, 47, 'Nũndũ mũndũ wa mbee aumie mũthanganĩ, na nĩ wa nthĩ: mũndũ wa kelĩ aumie ĩtunĩ.'),
('kam', '1CO', 15, 48, 'O tondũ ũilyĩ ũsu wa nthĩ, asu ma nthĩ nao mailyĩ o ũu: na o tondũ ũilyĩ ũsu wa ĩtunĩ, asu ma ĩtũnĩ nao mailyĩ o ũu.'),
('kam', '1CO', 15, 49, 'Na tondũ twaĩ na mũvw’ano wa ũsu wa nthĩ, o ta ũu tũkeethĩwa na mũvw’ano wa ũsu wa itunĩ.'),
('kam', '1CO', 15, 50, 'Na ĩndĩ ũla ngwasya nĩ ũũ, ana‐a‐asa, kana nyama na nthakame ititonya kũtiĩwa ũsumbĩ wa Ngai; o na kĩla kyanangĩkaa kĩtitonya kũtiĩwa kĩla kĩtanangĩkaa.'),
('kam', '1CO', 15, 51, 'Sisyai, nĩngũmũtavya nzama: Tũikakoma ithyĩ ithyonthe, ĩndĩ ithyonthe tũkaalyũkw’a,'),
('kam', '1CO', 15, 52, 'kavinda kanini, kũven’ya na kũsalukya, ũivuvwa soo wa mũminũkĩlyo: nũndũ soo ũkauuma, na akw’ũ makathayũũkw’a na wũmbe ũtanangĩkaa, naitũ tũkaalyũkw’a.'),
('kam', '1CO', 15, 53, 'Nũndũ mũvaka wũmbe ũũ wanangĩkaa ũvw’ĩkwe ũla ũtanangĩkaa, na ũũ ũkusaa ũvw’ikwe ũla ũtakusaa.'),
('kam', '1CO', 15, 54, 'Ĩndĩ yĩla ũũ wanangĩkaa ũkavw’ĩkwa ũla ũtanangĩkaa, na ũũ ũkusaa ũkavw’ĩkwa ũla ũtakusaa, nĩvo ĩkakĩtĩka ĩla ndeto ĩandĩkĩtwe, Kĩkw’ũ nĩkĩmeletw’e nĩ kũkĩlw’a vinya.'),
('kam', '1CO', 15, 55, 'Kũĩva, kĩkw’ũ, kũkĩlya vinya kwakũ? Ũĩva, kĩkw’ũ, ũmoa waku?'),
('kam', '1CO', 15, 56, 'Ũmoa wa kĩkw’ũ nĩ naĩ; na vinya wa naĩ nĩ mwĩao:'),
('kam', '1CO', 15, 57, 'ĩndĩ mũvea nĩwĩthĩwe kwa Ngai, ũla ũtũnengae kũkĩlya kwondũ wa Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', '1CO', 15, 58, 'Kwondũ wa ũu, ana‐a‐asa endwa, ĩlũlũmĩlyei, mũteũthingithĩka, mũkĩthangaaa mũno mavinda onthe wĩanĩ wa Mwĩaĩi, nĩkwĩthĩwa nĩmwĩsĩ kana kũthĩnĩa wĩa kwenyu ti kwa mana nthĩnĩ wa Mwĩaĩi.'),
('kam', '1CO', 16, 1, 'Na yu ũndũ wa ũelo wenyu kwondũ wa atheu, o tondũ neaĩe makanisa ma Kalatia, inyw’ĩ nenyu ĩkai o ta ũu.'),
('kam', '1CO', 16, 2, 'Mũthenya wa mbee wa kyumwa, kĩla mũndu wa inyw’ĩ nĩethĩwe akia, o ũndũ ũnengetwe, nĩ kana kũikethĩwe kũela o yĩla nĩũka.'),
('kam', '1CO', 16, 3, 'Na nooka, ngatũma o ala mwĩnyuva na ũmanenga mavalũa, matwae ũelo wenyu Yelusaleme:'),
('kam', '1CO', 16, 4, 'na ethĩwa nakwa nĩnaĩlwe nĩ ũthi, makaendan’ya nakwa.'),
('kam', '1CO', 16, 5, 'Ĩndĩ ngooka kwenyu, yĩla nĩĩsĩla Masetonia; nũndũ ngesĩla Masetonia;'),
('kam', '1CO', 16, 6, 'na nĩasya no kwĩthĩwa ngekalanga kwenyu, o na ĩvinda ya mbevo, nĩ kana inyw’ĩ mũnumaasye o kũla nĩthi.'),
('kam', '1CO', 16, 7, 'Nũndũ ndikwenda kwonana nenyu yu mbĩtĩte; nĩkwĩthĩwa nĩĩkwatya kwĩkalanga ĩvinda nenyu, Mwĩaĩi anenga ũthei.'),
('kam', '1CO', 16, 8, 'Ĩndĩ ngekala Eveso kũvika Vendekosito;'),
('kam', '1CO', 16, 9, 'nũndũ nĩvingũĩwe mũomo mũnene ũla waĩlĩte wa wĩa, na kwĩ nthũ nyingĩ.'),
('kam', '1CO', 16, 10, 'Na ethĩwa Timotheo akooka, sisyai kana ethĩwe nenyu ate kũkĩa; nũndũ etethya wĩa wa Mwĩaĩi, o ũndũ nyie nakwa nĩtethasya:'),
('kam', '1CO', 16, 11, 'kũikethĩwe ĩndĩ mũndũ kũmũvũthya. Ĩndĩ mumaasyeĩ na mũuo, nĩ kana oke vala nĩĩ: nũndũ nĩmweteele oke na ala ana‐a‐asa.'),
('kam', '1CO', 16, 12, 'Ĩndĩ ũndũ wa Avolo mwana‐a‐asa, namwĩsũvie kaingĩ oke kwenyu vamwe na ana‐a‐asa: nake ndanenda kũka oyu; ĩndĩ akooka yĩla wĩona ũthei.'),
('kam', '1CO', 16, 13, 'Syaĩĩsyai, ũngamai mwĩ alũmu mũĩkĩĩonĩ, ĩthĩwai aũme, ongelekai vinya.'),
('kam', '1CO', 16, 14, 'Maũndũ onthe ala mwĩkaa mekaei na wendano.'),
('kam', '1CO', 16, 15, 'Na yũ nĩmwĩsũva, ana‐a‐asa (nĩmwĩsĩ ĩla nyũmba ya Sitevana, kana nĩ ũsyao wa mbee wa Akaia, namo meyiĩte ene kũmathũkũma atheu,)'),
('kam', '1CO', 16, 16, 'nĩ kana ĩnyw’ĩ nenyu mwĩnyivye ene kwa ala mailyĩ ũu, na kwa kĩla mũndũ ũtethasya ũla wĩa na kũũthĩnĩa.'),
('kam', '1CO', 16, 17, 'Nakwa nĩngũtana kwondũ wa kũka kwa Sitevana na Volitunato na Akaiko: nĩkwĩthĩwa nĩmeanĩsye ũla mũtaaĩanĩsya.'),
('kam', '1CO', 16, 18, 'Nũndũ nĩmambuũkĩtye veva wakwa o na maveva menyu: mamanyei ala mailyĩ ũu.'),
('kam', '1CO', 16, 19, 'Makanisa ma Asia nĩmamũkethya. Akwila na Vilisika mamũkethya mũno nthĩnĩ wa Mwĩaĩi, vamwe na ĩkanisa yĩla yĩ myũmbanĩ yoo.'),
('kam', '1CO', 16, 20, 'Ana‐a‐asa onthe nĩmamũkethya. Kethan’yai inyw’ĩ kwa inyw’ĩ na ũmumunyano mũtheu.'),
('kam', '1CO', 16, 21, 'Nĩ ngethi yakwa, nyie Vaulo, na kw’oko kwakwa mwene.'),
('kam', '1CO', 16, 22, 'Ethĩwa mũndũ o na wĩva w’onthe ndeũmwenda Mwĩaĩi, nĩethĩwe anathema (ũalyũlo wayo nĩ, mũumanĩe). Malanatha (ũalyũlo wayo nĩ, Mwĩaĩi waitũ akilĩlye kũka).'),
('kam', '1CO', 16, 23, 'Mumo wa Mwĩaĩi Yesũ Klĩsto nĩwĩthĩwe vamwe nenyu.'),
('kam', '1CO', 16, 24, 'Wendo wakwa nĩwĩthĩwe vamwe nenyu inyw’onthe nthĩnĩ wa Klĩsto Yesũ. Ameni.'),
('kam', '2CO', 1, 1, 'Vaulo, mũtũmwa wa Klĩsto Yesũ kwondũ wa kwenda kwa Ngai, na Timotheo mwana‐a‐asa waitũ, valũa ũũ witũ ũyĩvikĩe ĩkanisa ya Ngai yĩla yĩ Kolintho, vamwe na ala atheu onthe, ala me nthĩ yonthe ya Akaia:'),
('kam', '2CO', 1, 2, 'Mumo na mũuo nĩmethĩwe nenyu kuma kwa Ngai Asa waitũ na kwa Mwĩaĩi Yesũ Klĩsto.'),
('kam', '2CO', 1, 3, 'Nataĩwe Ngai, Ĩthe wa Mwĩaĩi waitũ Yesũ Klĩsto, Ĩthe wa matei na Ngai wa ũkiakisyo w’onthe;'),
('kam', '2CO', 1, 4, 'ũla ũtũkiakiasya mathĩnanĩ maitũ onthe, nĩ kana ithyĩ tũtonye kũmakiakisya ala me thĩnanĩ o na wĩva, na ũkiakisyo ũla ithyĩ naitũ tũkiakiaw’a naw’o nĩ Ngai.'),
('kam', '2CO', 1, 5, 'Nĩkwĩthĩwa o tondũ mathĩna ma Klĩsto mausũĩte ki kwitũ, o ta ũu ũkiakisyo witũ naw’o nĩwusũĩte ki kwondũ wa Klĩsto.'),
('kam', '2CO', 1, 6, 'Ĩndĩ ethĩwa nĩtũthĩnaw’a, nĩ ũndũ wa ũkiakisyo na ũtangĩĩo wenyu; kana ethĩwa nĩtũkiakiaw’a, nĩ ũndũ wa ũkiakisyo wenyu, ũla ũtethasya wĩa wa kũmĩĩsya mathĩna o ala naitũ tũthĩnaw’a nĩo:'),
('kam', '2CO', 1, 7, 'na wĩkwatyo witũ kwondũ wenyu nĩ mũlũmu, twĩsĩ kana o tondũ mwĩ osi ma mathĩna, o ta ũu mwĩ osi ma mokiakisyo.'),
('kam', '2CO', 1, 8, 'O na tũikwenda, ana‐a‐asa, mũlee ũmanya mathĩna ala matũkwatĩe nthĩ ya Asia, kana twaitavĩwe mũno, kũvĩta vinya witũ, o na twayĩtũka kwĩthĩwa thayũ:'),
('kam', '2CO', 1, 9, 'ĩĩ, ithyĩ ene nthĩnĩ waitũ tweewie ta tũte ndĩi ya kũlea ũkw’a, nĩ kana tũikeĩkĩĩe ithyĩ ene, ĩndĩ tũmũĩkĩĩe Ngai ũla ũthayũũkasya akw’ũ:'),
('kam', '2CO', 1, 10, 'ũla watwovoisye kũtumya kĩkw’ũnĩ kĩnene ta kyu, nake akatwovosya: we ũla tũmwĩkwatĩtye kana akatwovoasya:'),
('kam', '2CO', 1, 11, 'inyw’ĩ nenyu mũkĩtetheanĩsya kũvoya kwondũ witũ; nĩ kana, kwondũ wa mũthĩnzĩo ũla twanengiwe ithyĩ nũndũ wa andũ aingĩ, aingĩ matonye kũtũnga mũvea kwondũ witũ.'),
('kam', '2CO', 1, 12, 'Nũndũ kwĩkathĩĩa kwitũ nĩ kũũ, ũkũsĩ wa wasya wa ngoo witũ, kana twekalile kũũ nthĩ, na mbee mũno nĩ kwenyu, twĩ na ũtheu na w’o wa ngoo wumĩte kwa Ngai, na ti na ũĩ wa mwĩĩ ĩndĩ mumonĩ wa Ngai.'),
('kam', '2CO', 1, 13, 'Nũndũ tũiũmũandĩkĩa maũndũ angĩ, no ala mũsomaa na kũmalĩkĩla, nakwa nĩnĩkwatĩtye kana mũkalĩkĩla kũvika mũminũkĩlyo:'),
('kam', '2CO', 1, 14, 'o tondũ nenyu mwatũlĩkĩle ithyĩ kũmwe, kana kĩtumi kya kwĩkathĩĩa kwenyu nĩ ithyĩ, o tondũ nenyu mwĩĩthĩwa kĩtumi kya kwĩkathĩĩa kwitũ, mũthenya wa Mwĩaĩi waitũ Yesũ.'),
('kam', '2CO', 1, 15, 'Na ngĩkwatya ũu, nenda kũka kwenyu mbee, nĩ kana mwone ũtethyo wa kelĩ;'),
('kam', '2CO', 1, 16, 'na ngĩvĩtĩla kwenyu kũvika nthĩ ya Masetonia, na ĩngĩ kuma Masetonia kũsyoka kwenyu, na ngyumaaw’a ĩngĩ nĩ inyw’ĩ kũthi Yutia.'),
('kam', '2CO', 1, 17, 'Ĩndĩ yĩla nasũanĩaa ũu, naĩ na mĩtwe ĩlĩ? Kana maũndũ ala nĩsũanĩaa, nĩsũanĩaa kwĩanana na mwĩĩ, kana kwakwa kwĩthĩwe ĩĩ na ĩĩ, na aiee na aiee?'),
('kam', '2CO', 1, 18, 'Ĩndĩ o tondũ Ngai wĩ kĩthito, ndeto yaitũ ĩla twamũtavisye ti ĩĩ na aiee.'),
('kam', '2CO', 1, 19, 'Nũndũ Mwana wa Ngai, Yesũ Klĩsto, ũla watavaniw’e kwenyu nĩ ithyĩ, nyie na Silivano na Timotheo, ndaĩ na ĩĩ na aiee, ĩndĩ nthĩnĩ wake nĩ ĩĩ.'),
('kam', '2CO', 1, 20, 'Nũndũ o ũndũ matho ma Ngai meana, nthĩnĩ wake nĩ ĩĩ: nayo Ameni nĩ kwondũ wake, nĩ kana Ngai ataĩwe kwondũ witũ.'),
('kam', '2CO', 1, 21, 'Ĩndĩ we ũla ũtũlũlũmĩlasya vamwe nenyu nthĩnĩ wa Klĩsto, na watwĩtĩkĩĩsye mauta, nĩ Ngai;'),
('kam', '2CO', 1, 22, 'nake nĩwe watũsiĩlile, na watũnengie ngwatĩlĩlyo, nayo nĩ Veva ngooni sitũ.'),
('kam', '2CO', 1, 23, 'Ĩndĩ nyie nĩngũmũweta Ngai akũsĩĩe ngoo yakwa, kana naleile kũka Kolintho nũndũ wa ũmwĩw’ĩa tei.'),
('kam', '2CO', 1, 24, 'Ti ati twĩsumbĩkĩtye mũĩkĩĩonĩ wenyu, ĩndĩ twĩ atethya ma ũtanu wenyu; nũndũ nĩmũũngeme na ũlũmu kwondũ wa mũĩkĩĩo.'),
('kam', '2CO', 2, 1, 'Ĩndĩ nĩnatwie ũu nyie mwene, kana ndikoke kwenyu ĩngĩ nĩ na woo.'),
('kam', '2CO', 2, 2, 'Nũndũ ethĩwa nyie ngamwĩw’ĩthya woo, nũũ ũla ũkambĩw’ĩthya mũyo ate o ũla wĩw’ĩthĩtw’e woo nĩ nyie?'),
('kam', '2CO', 2, 3, 'Na nĩnaandĩkie ũndũ ũũ naw’o, nĩ kana, nooka, ndikew’ĩthw’e woo nĩ ala naĩle nĩ ũmatanĩa; ngĩmũĩkĩĩa inyw’onthe, kana ũtanu wakwa nĩ ũtanu wenyu inyw’onthe.'),
('kam', '2CO', 2, 4, 'Nũndũ namũandĩkĩe na methoi maingĩ nĩ na thĩna mwingĩ na kũũũya kwa ngoo; ti kana inyw’ĩ mwĩw’ĩthw’e woo, ĩndĩ nĩ kana mũmanye wendo ũla nĩ naw’o, ũndũ wingĩvĩte kwenyu.'),
('kam', '2CO', 2, 5, 'Ĩndĩ ethĩwa ve ũmwe o na wĩva wew’ĩthanĩtye woo, ndaambĩw’ĩthya woo nyie, ĩndĩ ũndũ ũnini amwĩw’ĩthĩtye woo inyw’onthe (nĩ kana ndikamũvivinye mũno).'),
('kam', '2CO', 2, 6, 'Nĩwĩanĩe kwa mũndũ ta ũsu ũkan’yo ũla ũkanĩtw’e nĩ aingĩ;'),
('kam', '2CO', 2, 7, 'na inyw’ĩ ĩndĩ kavaa mũmũekee na kũmũkiakisya, nĩ kana mũndũ ũsu ndakaemelelwe kwondũ wa kwingĩvĩwa nĩ woo wake.'),
('kam', '2CO', 2, 8, 'Kwondũ wa ũu nĩngũmwĩsũva mũlũlũmĩlye wendo wenyu kwa ũsu.'),
('kam', '2CO', 2, 9, 'Nũndũ namũandĩkĩe kwondũ wa ũu, nĩ kana nĩmanye mwĩkalĩle wenyu, kana mwĩ ewi maũndũnĩ onthe.'),
('kam', '2CO', 2, 10, 'Ĩndĩ ũla mũmũekee ũndũ o na wĩva, nyie nakwa nĩngũmũekea: nũndũ ũla naekeie nyie, ethĩwa naekeie ũndũ o na wĩva, nĩnaekeie kwondũ wenyu mbee wa Klĩsto;'),
('kam', '2CO', 2, 11, 'nĩ kana tũikasesengwe nĩ Satani: nũndũ tũti ala matesĩ mosũanĩo make.'),
('kam', '2CO', 2, 12, 'Na yĩla navikie Teloa kwondũ wa ũvoo mũseo wa Klĩsto, na yĩla navingũĩwe mũomo nthĩnĩ wa Mwĩaĩi,'),
('kam', '2CO', 2, 13, 'veva wakwa ndwaausya nũndũ ndyaamwona Tito mwana‐a‐asa wakwa: ĩndĩ neanĩe nao, nauma nathi Masetonia.'),
('kam', '2CO', 2, 14, 'Ĩndĩ Ngai nakathwe, ũla ũtũtongoeasya mavinda onthe ũkĩlan’yonĩ nthĩnĩ wa Klĩsto, na ũla wonanĩlasya nthĩnĩ waitũ mũuke wa ũmanyi wake kũndũ kw’onthe.'),
('kam', '2CO', 2, 15, 'Nũndũ twi mũuke mũseo wa Klĩsto kwa Ngai, kũla kwĩ ala meũtangĩĩwa, na kũla kwĩ ala mekwaa;'),
('kam', '2CO', 2, 16, 'kwa amwe nĩ mũuke wumĩte kĩkw’ũnĩ kũthi kĩkw’ũnĩ; na kwa angĩ nĩ mũuke wumĩte thayũnĩ kũthi thayũnĩ. Na nũũ ũtonya kwĩanĩsya maũndũ aa?'),
('kam', '2CO', 2, 17, 'Nũndũ ithyĩ tũtiilyĩ ta aingĩ ala mathũkasya ndeto ya Ngai: ĩndĩ, twĩ ala ma w’o, ala matũmĩtwe nĩ Ngai, tũneenaa mbee wa Ngai nthĩnĩ wa Klĩsto.'),
('kam', '2CO', 3, 1, 'Nĩtũkwambĩlĩlya ĩngĩ kwĩĩkĩĩthya ithyĩ ene? Kana twĩ vata na mavalũa ma kũtũĩkĩĩthya maetwe kwenyu kana maume kwenyu tondũ amwe mekaa?'),
('kam', '2CO', 3, 2, 'Valũa witũ nĩ inyw’ĩ, ũandĩkĩtwe ngoonĩ sitũ, ũla wĩsĩkĩwe na ũsomawa nĩ andũ onthe;'),
('kam', '2CO', 3, 3, 'mũkyonanw’a kana mwĩ valũa wa Klĩsto, ũthũkũmĩtwe nĩ ithyĩ, ũla ũtaandĩkĩtwe na ingi, ĩndĩ na Veva wa Ngai ũla wĩ thayũ; na ti masengeanĩ ma mavia, ĩndĩ nĩ masengeanĩ ma ngoo sya nyama.'),
('kam', '2CO', 3, 4, 'Na wĩkwatyo ũsu twĩ naw’o ũmwelekele Ngai kwondũ wa Klĩsto:'),
('kam', '2CO', 3, 5, 'ti atĩ nĩtwĩanĩsye ĩthyĩ ene kũsũanĩa ũndũ o na wĩva ta wumĩte kwitũ; ĩndĩ wĩanĩsyo witũ wumaa kwa Ngai;'),
('kam', '2CO', 3, 6, 'ũla nake watwĩanĩsye twĩthĩwe athũkũmi ma ũtianĩo mweũ; ti wa ũandĩko, ĩndĩ nĩ wa veva; nũndũ ũandĩko nĩwũaa, ĩndĩ veva ũetae thayũ.'),
('kam', '2CO', 3, 7, 'Ĩndĩ ethĩwa ũla ũthũkũmi wa kĩkw’ũ, waandĩkĩtwe ũvanĩtwe masengeanĩ ma mavia, wookie na ũtheu mũtisu, ũndũ ana ma Isilaeli matyaatonya kũketeea ũthyũ wa Mose kwondũ wa ũtheu mũtisu waw’o; na nĩ ũtheu mũtisu ũla wavĩtĩte:'),
('kam', '2CO', 3, 8, 'nĩ mbee veana ata ũthũkũmi wa veva kwĩthĩwa wĩ na ũtheu mũtisu kwĩ ũsu?'),
('kam', '2CO', 3, 9, 'Nũndũ ethĩwa ũthũkũmi wa ũsilĩlo wĩ na ũtheu mũtisu, ũthũkũmi wa ũlũngalu wĩ na ũtheu mũtisu kũvĩtũka mũno mbee.'),
('kam', '2CO', 3, 10, 'Nũndũ nĩ w’o ũla wataĩiwe ndwaĩ ũtaĩo ũndũnĩ ũũ, nũndũ wa ũtaĩo ũvĩtũkĩte mũno.'),
('kam', '2CO', 3, 11, 'Nũndũ ethĩwa ũla ũvĩtĩte waĩ na ũtaĩo, ũla wĩkalaa nũvĩtũkĩte mũno mbee.'),
('kam', '2CO', 3, 12, 'Kwondũ wa kwĩthĩwa twĩ na wĩkwatyo ta ũsu, twĩneena na ũkũmbaũ mũnene,'),
('kam', '2CO', 3, 13, 'na tũtitilyĩ ta Mose, ũla wavw’ĩkie ũthyũ wake suka mũvũthũ, nĩ kana ana ma Isilaeli maikaketeee mũminũkĩlyo wa ũndũ wavĩtĩte:'),
('kam', '2CO', 3, 14, 'ĩndĩ mosũanĩo moo maĩ momũ: na kũvika mũnthĩ ũũ, ũtianĩo wa tene ũkĩsomwa, suka ũsu wĩ o vo, ndwaavetwa; ĩndĩ nũvetawa nthĩnĩ wa Klĩsto.'),
('kam', '2CO', 3, 15, 'Ĩndĩ kũvika ũmũnthĩ, o yĩla mavuku ma Mose meũsomwa, suka ũsu nũvw’ĩkĩte ngoo syoo.'),
('kam', '2CO', 3, 16, 'Ĩndĩ ĩvinda o yĩla mũndũ wĩmwĩthyũũĩa Mwĩaĩi, suka ũsu nũvetawa.'),
('kam', '2CO', 3, 17, 'Ĩndĩ Mwĩaĩi nĩwe Veva; na vala ve Veva wa Mwĩaĩi, nĩvo ve ũthasyo.'),
('kam', '2CO', 3, 18, 'Ĩndĩ ithyonthe, na mothyũ mate mavw’ĩke tũkyona ũtheu mũtisu wa Ngai ta kĩsisyonĩ, nĩtũũalyũlwa na kwosa mũvw’ano ũsu, kuma ũtheu mũtisu kũvĩkĩa ũtheu mũtisu, o ta kuma kwa Mwĩaĩi, nake nĩwe Veva.'),
('kam', '2CO', 4, 1, 'Kwondũ wa ũu, nĩkwĩthĩwa twĩ na ũthũkũmi ũũ, o ũndũ twĩw’ĩwe tei, tũtiũteva:'),
('kam', '2CO', 4, 2, 'ĩndĩ nĩtũleete maũndũ mavithe ma nthoni, na tũtiendaa na ũseleke, kana kũvulan’ya ndeto ya Ngai na ũkengani: ĩndĩ na kwonan’ya ũla w’o, nĩtũkwĩĩkĩĩthya ene wasyanĩ wa ngoo wa kĩla mũndũ mbee wa Ngai.'),
('kam', '2CO', 4, 3, 'Ĩndĩ o na ethĩwa ũvoo mũseo witũ nĩ mũvw’ĩke, nĩ mũvw’ĩke kwa ala mekwaa:'),
('kam', '2CO', 4, 4, 'ala nthĩnĩ woo ila ngai ya nthĩ ĩno nĩyaĩtye mosũanĩo ma ala matetĩkĩlaa, nĩ kana kyeni kya ũtheu mũtisu wa ũvoo mũseo wa Klĩsto, nake nĩwe mũvw’ano wa Ngai, kĩikamaumĩlĩle.'),
('kam', '2CO', 4, 5, 'Nũndũ tũikwĩtavan’ya ithyĩ ene, ĩndĩ twĩtavan’ya Klĩsto Yesũ kana nĩwe Mwĩaĩi, na ithyĩ ene ta ngombo syenyu kwondũ wa Yesũ.'),
('kam', '2CO', 4, 6, 'Nĩkwĩthĩwa nĩ Ngai ũla waisye, Kyeni kĩkakena kuma kĩvindunĩ, nake nĩwakenie ngoonĩ sitũ, kũtũnenga kyeni kya ũmanyi wa ũtheu mũtisu wa Ngai ũthyũnĩ wa Yesũ Klĩsto.'),
('kam', '2CO', 4, 7, 'Ĩndĩ twĩ na ũthwĩĩ ũsu mĩionĩ ya mũthanga, nĩ kana vinya ũsu mũnene ũvĩtũkĩte wĩthĩwe wĩ wa Ngai, na ti kuma kwitũ;'),
('kam', '2CO', 4, 8, 'nĩtũlĩlĩĩlawa ngalĩ syonthe, ĩndĩ ti kũthyũlũlũkwa; nĩtũsũanĩawa, ĩndĩ ti kwĩyĩtũka:'),
('kam', '2CO', 4, 9, 'nĩtũatĩĩawa, ĩndĩ tũtiũtiwa; nĩtũvalũkawa nthĩ, ĩndĩ tũikwanangwa;'),
('kam', '2CO', 4, 10, 'mavinda onthe nĩtũkuaa kũawa kwa Yesũ mĩĩnĩ yaitũ nĩ kana thayũ wa Yesũ naw’o wonanw’e mĩĩnĩ yaitũ.'),
('kam', '2CO', 4, 11, 'Nũndũ ithyĩ ala twĩ thayũ tũnenganawe tũkw’e mavinda onthe kwondũ wa Yesũ, nĩ kana thayũ wa Yesũ naw’o wonanw’e mĩĩnĩ yaitũ ĩla ĩkusaa.'),
('kam', '2CO', 4, 12, 'Kwa ũu ĩndĩ, kĩkw’ũ nĩkĩtethasya wĩa nthĩnĩ waitũ, ĩndĩ nthĩnĩ wenyu nĩ thayũ.'),
('kam', '2CO', 4, 13, 'Ĩndĩ nũndũ twĩ na veva wa ũla mũĩkĩĩo, kwĩanana na ũndũ kũandĩkĩtwe, Nĩneetĩkĩlile, na kwondũ wa ũu nĩnaneenie; naitũ nĩtũkwĩtĩkĩla, na kwondũ wa ũu naitũ nĩtũneenaa;'),
('kam', '2CO', 4, 14, 'twĩsĩ kana we ũla wamũthayũũkisye Mwĩaĩi Yesũ akatũthayũũkya ithyĩ naitũ vamwe na Yesũ, na kũtũnengane vamwe nenyu.'),
('kam', '2CO', 4, 15, 'Nũndũ maũndũ onthe nĩ kwondũ wenyu, nĩ kana mumo, ũkingĩvw’a kwondũ wa aingĩ, ũtume mũvea wingĩvw’a nĩ kana Ngai ataĩwe.'),
('kam', '2CO', 4, 16, 'Kwondũ wa ũu tũtiũteva; ĩndĩ o na ethĩwa mũndũ ũũ waitũ wa mwĩĩ nũnũkwoa, ĩndĩ mũndũ waitũ wa nthĩnĩ nĩweũvaw’a kĩla mũthenya.'),
('kam', '2CO', 4, 17, 'Nũndũ thĩna ũũ witũ mũvũthũ, ũla wa kavinda kanini, nũtethasya wĩa mbee na mbee mũno wa utũetee ũtaĩo ũtathimĩka wa tene na tene;'),
('kam', '2CO', 4, 18, 'tũteũsyaĩĩsya syĩndũ ila syonekaa, ĩndĩ tũkĩsyaĩĩsya syĩndũ ila itonekaa: nũndũ syĩndũ ila syonekaa no sya kavinda; ĩndĩ syĩndũ ila itonekaa nĩ sya tene na tene.'),
('kam', '2CO', 5, 1, 'Nũndũ nĩtwĩsĩ kana ethĩwa wĩkalo ũũ witũ wa ĩeema wa kũũ nthĩ ũkaanangĩka, twĩ na mwako ũngĩ wumaa kwa Ngai, nyũmba ĩtakĩtwe na moko, ya tene na tene, ĩtunĩ.'),
('kam', '2CO', 5, 2, 'Nũndũ nĩ w’o, wĩkalonĩ ũũ nĩtũlumaa, tũkyenda mũno mbee kũvw’ĩkwa wĩkalo ũla wumaa ĩtunĩ:'),
('kam', '2CO', 5, 3, 'nĩ kana twavw’ĩkwa tũtikoneka twĩ athei.'),
('kam', '2CO', 5, 4, 'Nũndũ nĩ w’o, ithyĩ ala twĩ wĩkalonĩ ũũ nĩtũlumaa, naw’o nĩ kũitavĩwa; ti kwĩthĩwa nĩtũkwenda kũvuũwa, ĩndĩ twĩenda mũno kũvw’ĩkwa, nĩ kana ũsu ũkusaa ũmelw’e nĩ thayũ.'),
('kam', '2CO', 5, 5, 'Na ũla watũseũvisye kwondũ wa ũndũ ũsu nĩ Ngai, ũla watũnengie ngwatĩlĩlyo, nayo nĩ Veva.'),
('kam', '2CO', 5, 6, 'Na ĩndĩ nĩkwĩthĩwa matukũ onthe twĩ na ũkũmbaũ, na kũmanya kana, yĩla twĩ vaa nthĩnĩ wa mwĩĩ, tũti kwa Mwĩaĩi:'),
('kam', '2CO', 5, 7, '(nũndũ tũkinyaa kwa kũĩkĩĩa, ti kwa kwona;)'),
('kam', '2CO', 5, 8, 'nĩngwasya twĩ na ũkũmbaũ mũnene, naitũ nĩtwĩtĩkĩle kavaa tũikethĩwe vo nthĩnĩ wa mwĩĩ, twĩthĩwe vamwe na Mwĩaĩi.'),
('kam', '2CO', 5, 9, 'Kwondũ wa ũu naitũ nĩtũkwĩthangaasya, ethĩwa twi mwĩĩnĩ kana ethĩwa tũti nthĩnĩ waw’o, twĩthĩwe twĩ andũ ma kũmwendeeasya we.'),
('kam', '2CO', 5, 10, 'Nũndũ ithyĩ ithyonthe nĩtũkaumĩlw’a mbee wa kĩvĩla kya sila kya Klĩsto; nĩ kana kĩla mũndũ ose maũndũ ala meekiwe e nthĩnĩ wa mwĩĩ, kwĩanana na ũndũ wekie, o na ethĩwa nĩ ũseo kana ũthũku.'),
('kam', '2CO', 5, 11, 'Ĩndĩ tũkĩmanya kũmũkĩa Mwĩaĩi, twĩmanzanza andũ, ĩndĩ nĩtwonanĩtw’e kwa Ngai; nakwa nĩnĩkwatĩtye kana nĩtwonanĩtw’e naw’o nthĩnĩ wa mawasya ma ngoo menyu.'),
('kam', '2CO', 5, 12, 'Tũikwĩĩkĩĩthya ene ĩngĩ mbee wenyu, ĩndĩ nĩtũũmũnenga ũthei wa kwĩkathĩĩa kwondũ witũ, nĩ kana mwĩthĩwe na ũndũ wa ũmasũngĩa ala mekwĩkathĩĩa maũndũnĩ ala monekaa nĩ andũ, na ti ala ma ngoonĩ.'),
('kam', '2CO', 5, 13, 'Nũndũ o na ethĩwa kĩlĩko kitũ nĩkyaĩte, nĩ kwondũ wa Ngai; kana ethĩwa twĩ nakyo, nĩ kwondũ wenyu.'),
('kam', '2CO', 5, 14, 'Nũndũ wendo wa Klĩsto nũũtũthing’ĩĩsya; nĩkwĩthĩwa twĩona atĩ ũmwe nĩwakwie kwondũ wa onthe, kwondũ wa ũu onthe nĩmakwie;'),
('kam', '2CO', 5, 15, 'nake nĩwamakwĩĩe onthe, nĩ kana ala me thayũ maikethĩwe naw’o ĩngĩ kwondũ woo ene, ĩndĩ no kwondũ wake ũla wakwie na athayũũka ĩngĩ kwondũ woo.'),
('kam', '2CO', 5, 16, 'Na kwa ũu kuma yu tũimwĩsĩ mũndũ kĩ‐mwĩĩ: o na ethĩwa nĩtwamũmanyĩte Klĩsto kĩ‐mwĩĩ, ĩndĩ yu tũtiũmũmanya ũu ĩngĩ.'),
('kam', '2CO', 5, 17, 'Na kwa ũu ethĩwa mũndũ o na wĩva e nthĩnĩ wa Klĩsto, nĩ kyũmbe kyeũ: maũndũ ala makũũ nĩ mavĩtu; sisyai, nĩmatw’ĩkĩte meũ.'),
('kam', '2CO', 5, 18, 'Ĩndĩ maũndũ onthe nĩ ma Ngai, ũla watwĩw’anĩthye nake mwene kwondũ wa Klisto, na watũnengie ũthũkũmi wa wĩw’anĩthyo;'),
('kam', '2CO', 5, 19, 'naw’o nĩ ũũ, Ngai aĩ nthĩnĩ wa Klĩsto, aimĩw’anĩthya nthĩ nake Klĩsto, aimĩw’anĩthya nthĩ nake mwene, ateũmatalĩla andũ mavĩtyo moo, na nũtwĩkĩĩte nthĩnĩ waitũ ĩla ndeto ya kwĩw’anĩthya.'),
('kam', '2CO', 5, 20, 'Na ĩndĩno twĩ atũmwa kwondũ wa Klĩsto, o ta Ngai ũnũkwĩsũvanĩla kwitũ: nitũũmwĩsũva kwondũ wa Klisto, mwĩw’anithw’e na Ngai.'),
('kam', '2CO', 5, 21, 'Ũla ũtaamanya naĩ amũtwie kwĩthĩwa naĩ kwondũ witũ; nĩ kana ithyĩ tũtw’ĩke ũlũngalu wa Ngai nthĩnĩ wake.'),
('kam', '2CO', 6, 1, 'Na ĩndĩ tũkĩtethan’ya vamwe nake twĩmwĩsũva mũikose mumo wa Ngai mana'),
('kam', '2CO', 6, 2, '(nũndũ we easya, Nĩnakwĩwie ĩvinda yĩla yĩtĩkĩlĩtwe, Na mũthenya wa ũtangĩĩo nĩnaũtethisye: sisyai, yĩĩ nĩyo ĩvinda yĩtĩkĩlĩtwe; sisyai, mũthenya wa ũtangĩĩo no yu):'),
('kam', '2CO', 6, 3, 'mũteũete ũndũ o na wĩva wa ũlulutĩkya, nĩ kana ũthũkũmi ũũ witũ ndũkawetwe naĩ;'),
('kam', '2CO', 6, 4, 'ĩndĩ maũndũnĩ onthe nĩtũkwĩĩkĩĩthya, ta athũkũmi ma Ngai, nthĩnĩ wa wũmĩĩsyo mwingĩ, na mathĩna, na mavata, na monyamao,'),
('kam', '2CO', 6, 5, 'na makũnwa, na kwovwa kolokolonĩ, na ituu, na thĩna wa mawĩa, na kũsyaĩĩsya, na kũtĩĩa kũya;'),
('kam', '2CO', 6, 6, 'na ũtheu, na ũmanyi, na wũmĩĩsyo, na ũseo, na nthĩnĩ wa Veva Mũtheu, na wendo ũte na wangangan’yo,'),
('kam', '2CO', 6, 7, 'na ndeto ya w’o, na vinya wa Ngai; kwondũ wa mĩio ya kaũ ya ũlũngalu kw’okonĩ kwa aũme na kw’okonĩ kwa aka.'),
('kam', '2CO', 6, 8, 'Ethĩwa nĩtũũtaĩwa kana kũtataĩwa, kũwetwa naĩ kana nesa; ta twĩ akengani, na kaĩ twĩ ma w’o;'),
('kam', '2CO', 6, 9, 'ta twĩ ala matesĩkĩwe, na kai twĩsĩkĩwe mũno; ta tũkusaa, na kaĩ twĩ thayũ; ta tũkũnawa, na kaĩ tũtyũawa;'),
('kam', '2CO', 6, 10, 'ta twi na kĩmako, na kaĩ tũtanaa mavinda onthe; ta twĩ ngya, na kaĩ tũmathuasya aingĩ; ta tũte kĩndũ, na kaĩ twĩ na syĩndũ syonthe.'),
('kam', '2CO', 6, 11, 'Makanyw’a maitũ nĩmwathamĩwe, inyw’ĩ Akolintho, ngoo sitũ ninenevetw’e.'),
('kam', '2CO', 6, 12, 'Ti inyw’ĩ mwaĩte va kwendelwa ngoonĩ sitũ, ĩndĩ ngoo syenyu nĩsyo syaĩte va kwendanĩla.'),
('kam', '2CO', 6, 13, 'Ĩndĩ nenevai ngoonĩ syenyu mũtũĩve kĩthemba o kyu (nĩneena ta ngũneena na syana syakwa).'),
('kam', '2CO', 6, 14, 'Mũtikovanĩw’e ĩsoki yĩmwe na ala mate etĩkĩli: nũndũ ũlũngalu na ũthũku wĩ mũamba mwaũ? Kana kyeni kĩ na mũamba mwaũ na kĩvindu?'),
('kam', '2CO', 6, 15, 'Na Klĩsto e na mũamba mwaũ na Veliali? Na ũla wĩtĩkĩlĩte e na kĩanda kyaũ vamwe na ũla ũtetĩkĩlĩte?'),
('kam', '2CO', 6, 16, 'Na ĩkalũ ya Ngai yĩ na wĩw’ano mwaũ na mĩvw’anano? Nũndũ ithyĩ twĩ ĩkalu ya Ngai ũla wĩ thayũ; o tondũ Ngai waisye, Ngekalaa nthĩnĩ woo, na kũendaa nthĩnĩ woo; na ngeethĩwa Ngai woo, namo makeethĩwa andũ makwa.'),
('kam', '2CO', 6, 17, 'Kwondũ wa ũu Umai katĩ woo, na mwĩthĩwe mwĩvathanĩte nao, eneena ũu Mwĩaĩi, Na mũikakiite kĩndũ kĩvuku; Nakwa ngamwosa,'),
('kam', '2CO', 6, 18, 'Na ngeethĩwa ĩthe wenyu, Na inyw’ĩ mũkeethĩwa ana makwa, aũme na eĩtu, eneena ũu Mwĩaĩi, Mwene Vinya W’onthe.'),
('kam', '2CO', 7, 1, 'Kwondũ wa kwĩthĩwa twĩ na matho aa, endwa, twĩthesye ene ũvuku w’onthe wa mwĩĩ na wa ngoo, tũkĩanĩsya ũtheu nthĩnĩ wa kũmũkĩa Ngai.'),
('kam', '2CO', 7, 2, 'Tũvingũĩei ngoo syenyu: tũimwĩkite mũndũ naĩ, tũiaathũkya mũndũ, tũiaasesenga mũndũ.'),
('kam', '2CO', 7, 3, 'Ndiũneena ũu nĩmũsilĩle inyw’ĩ: nũndũ nambie ũneena, kana mwĩ nthĩnĩ wa ngoo sitũ tũkw’e vamwe na twĩthĩwe thayũ vamwe.'),
('kam', '2CO', 7, 4, 'Kũneena kwakwa nenyu kwĩ na ũkũmbaũ mũnene, kwĩkathĩĩa kwakwa kwondũ wenyu nĩ kũnene: nusũĩtwe nĩ ũkiakisyo, na thĩnanĩ witũ w’onthe nusũĩtwe nĩ ũtanu ki, ũketĩka.'),
('kam', '2CO', 7, 5, 'Nũndũ o yĩla twavikie Masetonia mĩĩ yaitũ ndĩaĩ na ũthũmũo, ĩndĩ nĩtwathĩnaw’a ngalĩ syonthe; ũtee kwaĩ kaũ, na nthĩnĩ kwaĩ w’ĩa.'),
('kam', '2CO', 7, 6, 'Ĩndĩ vamwe na ũu Ngai, ũla ũkiakiasya, ala mavinyĩwe, nĩwe watũkiakiisye nũndũ wa Tito kũka;'),
('kam', '2CO', 7, 7, 'na ti ũndũ wa kũka kwake kw’oka, ĩndĩ ũndũ wa ũkiakisyo naw’o ũla ũkiakiĩtw’e nĩ inyw’ĩ, akĩtũtavya ũndũ wa mea menyu maingĩ, na kĩĩo, na kĩthing’ĩĩsyo kyenyu kwondũ wakwa; nakwa neethĩwa ngĩtana mũno mbee.'),
('kam', '2CO', 7, 8, 'Nũndũ o na ethĩwa namwĩw’ĩthisye woo na valũa wakwa, ndikwĩlila: o na ethĩwa nĩneelilile (nũndũ nĩngwona kana valũa ũsu nĩwamwĩw’ĩthisye woo, o na kau no kavinda),'),
('kam', '2CO', 7, 9, 'yu nĩngũtana, ti ũndũ mweew’ĩthiw’e woo, ĩndĩ nũndũ mwew’ĩthĩw’e woo kũvika ũalyũlo wa ngoo; nũndũ mwew’ĩthiw’e woo ũla Ngai wendete, nĩ kana mũikone wasyo kwondũ witũ ũndũnĩ o na wĩva.'),
('kam', '2CO', 7, 10, 'Nũndũ woo ũla Ngai wendete ũetae ũalyũlo wa ngoo kũvika ũtangĩĩo, naw’o nĩ ũalyũlo ũtaetae kwĩlila: ĩndĩ woo wa nthĩ ũetae kĩkw’ũ.'),
('kam', '2CO', 7, 11, 'Nũndũ sisyai ũndũ ũũ, kwĩw’ĩthw’a woo kũla Ngai wendete, ũndũ kwaetie kwĩsũvĩa kũnene nthĩnĩ wenyu, ĩĩ, na kwĩkaĩĩa, ĩĩ, na kũthata, ĩĩ, na kũkĩa, ĩĩ, na mea, ĩĩ, na kwĩthing’ĩĩsya, ĩĩ, na kũĩvanĩsya! Kĩla ũndũnĩ nĩmwĩyonanĩtye kwĩthĩwa mwĩ atheu ũndũnĩ ũsu.'),
('kam', '2CO', 7, 12, 'Na ĩndĩ o na ethĩwa nĩnamũandĩkĩe, ndyaamũandĩkĩa kwondũ wa ũsu wekĩte naĩ, o na ti ũndũ wa ũla wekĩtwe naĩ, ĩndĩ nĩ kana kĩthing’ĩĩsyo kyenyu kwondũ witũ kyoneke kwenyu mbee wa Ngai.'),
('kam', '2CO', 7, 13, 'Kwondũ wa ũu nĩtwakiakiiw’e: na kũkiakiw’anĩ kwitũ twatanie mũno mbee kwondũ wa ũtanu wa Tito, nũndũ veva wake nũvuũkĩtw’e nĩ inyw’ĩ inyw’onthe.'),
('kam', '2CO', 7, 14, 'Nũndũ ethĩwa nĩneekathĩĩe kwake ũndũnĩ ũmwe kwondũ wenyu, ndyaasonokw’a; ĩndĩ o ũndũ twamũtavisye maũndũ onthe w’o, o ta ũu kwĩkathĩĩa kwitũ nakw’o kũla nakathĩĩaa mbee wa Tito kwoonekie nĩ kwa w’o.'),
('kam', '2CO', 7, 15, 'Na wendo wake wa ngoo wingĩvĩte mũno kwenyu, yĩla ũnũũlilikana wĩwi wenyu inyw’onthe, ũndũ mwamwosie na w’ĩa na kũtetema.'),
('kam', '2CO', 7, 16, 'Nĩngũtana nũndũ maũndũnĩ onthe nĩ na ũnyiau mwingĩ kwondũ wenyu.'),
('kam', '2CO', 8, 1, 'O na ĩngĩ, ana‐a‐asa, twĩmũtavya mumo wa Ngai ũla ũnenganĩtwe makanisanĩ ma Masetonia;'),
('kam', '2CO', 8, 2, 'ũndũ wa kũtatwa na monyamao maingĩ, wingĩ wa ũtanu woo na ũkya woo mũnene waingĩvie mũno kũvika ũthwii wa ũlau woo.'),
('kam', '2CO', 8, 3, 'Nũndũ nĩngũmakũsĩĩa, kana kwĩanana na ũndũ maĩ matonya, ĩĩ, na mbee wa kũtonya kwoo, nĩmanenganie na kwenda kwa ngoo syoo ene,'),
('kam', '2CO', 8, 4, 'makĩtũthing’ĩĩsya vamwe na kũtwĩsũva mũno ũndũ wa mumo ũũ na mũamba wa ũthũkũmi ũũ kwa atheu:'),
('kam', '2CO', 8, 5, 'na ti tondũ twaasya, ĩndĩ mbee nĩmeenenganie ene kwa Mwĩaĩi, na kwitũ, o tondũ Ngai wendete.'),
('kam', '2CO', 8, 6, 'Kwa ũu twamũtaie Tito, kana o ũndũ wambĩlĩlye mbee, o ta ũu eanĩsye nthĩnĩ wenyu mumo ũũ naw’o.'),
('kam', '2CO', 8, 7, 'Ĩndĩ o tondũ mwingĩvĩwe mũno maũndũnĩ onthe, mũĩkĩĩonĩ, na kũneenanĩ, na ũmanyinĩ, na kĩthing’ĩĩsyonĩ kyonthe, na wendonĩ wenyu kwa ithyĩ, sisyai kana mwingĩvĩwe mumonĩ ũũ naw’o.'),
('kam', '2CO', 8, 8, 'Ndiũneena na kwĩaa, ĩndĩ nĩngũtata w’o wa wendo wenyu kwa kĩthing’ĩĩsyo kya angĩ.'),
('kam', '2CO', 8, 9, 'Nũndũ nĩmũũmanya mumo wa Mwĩaĩi waitũ Yesũ Klĩsto, kana, o na kau aĩ mũthwii, atw’ĩka ngya kwondũ wenyu, nĩ kana inyw’ĩ kwondũ wa ũkya wake mũtonye ũtw’ĩka athwii.'),
('kam', '2CO', 8, 10, 'Na ũndũnĩ ũu nĩmũtavya ũndũ ngwona: nũndũ ũũ nũmwaĩle inyw’ĩ, ala mwambĩlĩlye mbee, yu mũminĩte mwaka, na ti kwĩka kw’oka, ĩndĩ nĩ kwĩka na kwenda nakw’o.'),
('kam', '2CO', 8, 11, 'Ĩndĩ yu ĩanĩsyai kwĩka nakw’o; nĩ kana ũndũ mweeyũmbanĩtye kwenda, o ta ũu mwĩanĩsye kwĩka kwĩanana na ũndũ mũtonya.'),
('kam', '2CO', 8, 12, 'Nũndũ kweethĩwa kwĩ ngoo ĩyũmbanĩtye, nĩkwĩtĩkĩlawa kwĩanana na kĩla mũndũ wĩ nakyo, ti kwĩanana na kĩla mũndũ ũte nakyo.'),
('kam', '2CO', 8, 13, 'Nũndũ ndikwasya ũu kana angĩ mathũmũe na inyw’ĩ mũthĩne:'),
('kam', '2CO', 8, 14, 'ĩndĩ nĩkwĩthĩwe kwĩanan’ya: ĩvinda yĩĩ kusũa kwenyu kũtethye kũnyivĩwa kwoo, nĩ kana kusũa kwoo kũtethye kũnyivĩwa kwenyu: nĩ kana mwĩanan’ye:'),
('kam', '2CO', 8, 15, 'o ũndũ kũandĩkĩtwe, Ũla wombanisye mwingĩ ndaatialya; na ũla wombanisye mũnini ndaanyivĩwa.'),
('kam', '2CO', 8, 16, 'Ĩndĩ Ngai nataĩwe, ũla wĩkĩaa kĩthing’iĩsyo kyu kwondũ wenyu ngoonĩ ya Tito.'),
('kam', '2CO', 8, 17, 'Nũndũ nĩwosie ũtao witũ; ĩndĩ nĩkwĩthĩwa we mwene aĩ na kĩthing’ĩĩsyo kingĩ mũno, ooka kwenyu kwa kwenda kwake mwene.'),
('kam', '2CO', 8, 18, 'Naitũ tũmũtũmanĩsye na mwana‐a‐asa ũsu, ũla nguma yake ũvoonĩ mũseo ĩnyaĩĩkĩte makanisanĩ onthe'),
('kam', '2CO', 8, 19, 'o na ti ũu w’oka, ĩndĩ anyuvĩtwe nĩ makanisa asu athi vamwe naitũ ũthũkũminĩ wa moelo nĩ kana Mwĩaĩi ataĩwe, na kwonan’ya kwĩyũmban’ya kwitũ;'),
('kam', '2CO', 8, 20, 'tũkĩsũvĩa, mũndũ o na wĩva ndakatwilĩĩle mavĩtyo ũlaunĩ ũũ ũthũkũmawa nĩ ithyĩ:'),
('kam', '2CO', 8, 21, 'nũndũ twĩsũanĩa maũndũ ala maĩlu, ti mbee wa Ngai weka, ĩndĩ o na mbee wa andũ.'),
('kam', '2CO', 8, 22, 'Naitũ tũmũtũmĩte mwana‐a‐asa waitũ vamwe nao, ũla tũmwonete kaingĩ e kĩthing’ĩĩsyo maũndũni maingĩ, ĩndĩ yu e kĩthing’ĩĩsyo mũno mbee, nũndũ wa kũĩkĩĩa kũnene kũla ũmũĩkĩĩe inyw’ĩ.'),
('kam', '2CO', 8, 23, 'Na ethĩwa mũndũ nũnũũkũlya ũndũ wa Tito, we e mũamba nakwa na nĩ mũtethya wa wĩa vamwe nakwa kwondũ wenyu; na ethĩwa mũndũ nũnũũkũlya ũndũ wa ana‐a‐asa maitũ, nao nĩ atũmwa ma makanisa, na nĩmo matumaa Klĩsto ataĩwa.'),
('kam', '2CO', 8, 24, 'Kwondũ wa ũu monesyei mbee wa makanisa w’o wa wendo wenyu na wa kwĩkathĩĩa kwitũ kwondũ wenyu.'),
('kam', '2CO', 9, 1, 'Nũndũ ũndũ wa ũthũkũmi kwondũ wa ala atheu, ndi na vata wa ũmũandĩkĩa:'),
('kam', '2CO', 9, 2, 'nũndũ nĩnĩsĩ kwĩyũmban’ya kwenyu, kũla ngwĩkathĩĩa nũndũ wakw’o ngalĩ ĩla yenyu kwa ala ma Masetonia, kana andũ ma Akaia nĩmeyũmbanĩtye mwaka mũima; na ũthangaau wenyu nũthangaaĩtye aingĩ mũno moo.'),
('kam', '2CO', 9, 3, 'Ĩndĩ namatũma ana‐a‐asa, nĩ kana kwĩkathĩĩa kwitũ kwondũ wenyu kũtikatw’ĩke kwa mana ũndũnĩ ũũ; nĩ kana mwĩthĩwe mwĩyũmbanĩtye, o ũndũ naisye:'),
('kam', '2CO', 9, 4, 'nĩ kana kũikethĩwe kwa ũndũ o na wĩva, ethĩwa andũ ma Masetonia makookan’ya nakwa na kũmwona mũteyũmbanĩtye, ithyĩ tũsonoke ũndũ wa kũĩkĩĩa kũla twamũĩkĩĩe (tũikwasya nĩ inyw’ĩ mwĩsonoka).'),
('kam', '2CO', 9, 5, 'Ĩndĩ nonie nĩnaĩlwe nĩ kũmesũva ana‐a‐asa asu, nĩ kana maendae mbee kũvika kwenyu, na kũmban’ya ũla mũthĩnzĩo wenyu wathanĩtwe, nĩ kana wĩthĩwe wũmbanĩtw’e ũndũ waĩle mũthĩnzĩo, na ti kumw’a na vinya.'),
('kam', '2CO', 9, 6, 'Ĩndĩ nĩneena ndeto ii, Ũla ũvuĩaa nini akethaa nini; na ũla ũvuĩaa nyingĩ akethaa nyingĩ.'),
('kam', '2CO', 9, 7, 'Kĩla mũndũ nĩeke o tondũ utw’ĩte ngoonĩ yake: ti kwa kulea kwenda, kana kwa kũingĩĩw’a: nũndũ Ngai endete mũndũ ũnenganae na ũtanu.'),
('kam', '2CO', 9, 8, 'Na Ngai nũtonya kwingĩvya mumo w’onthe kwa inyw’ĩ; nĩ kana inyw’ĩ, mwĩanĩwe vyũ mavinda onthe maũndũnĩ onthe, mwingĩve kĩla wĩanĩ mũseo:'),
('kam', '2CO', 9, 9, 'o tondũ kũandĩkĩtwe, Nũvuĩĩte, nũnengete ngya; Ũlũngalu wake nĩwĩkalaa tene na tene.'),
('kam', '2CO', 9, 10, 'Na ũla ũnengae mũvuĩi mbeũ na kĩmũtũ kya kũya, akamũnenga na kwingĩvya mbeũ syenyu sya ũvuĩaa, na akaingĩvya mosyao ma ũlũngalu wenyu:'),
('kam', '2CO', 9, 11, 'mwĩthĩwe mũthuĩtw’e maũndũnĩ onthe kũvika ũlau w’onthe, ũla kwondũ wa wĩa witũ ũtumaa Ngai atũngĩwa mũvea.'),
('kam', '2CO', 9, 12, 'Nũndũ kwĩka kwa ũthũkũmi ũũ kũtyĩanĩasya mavata ma ala atheu kw’oka, ĩndĩ nakw’o nĩkwingĩvasya mĩvea kwa Ngai:'),
('kam', '2CO', 9, 13, 'nũndũ makĩmũosya na ũthũkũmi ũũ mamũtaĩaa Ngai kwondũ wa wĩwi wa kumbũla kwenyu kwa ũvoo mũseo wa Klĩsto, na kwondũ wa ũlau wa ũelo wenyu kwamo na kwa andũ onthe;'),
('kam', '2CO', 9, 14, 'nao ene, makĩsũvana kwondũ wenyu, me na mea nenyu mũno nũndũ wa mumo wa Ngai ũla wingĩvĩte mũno nthĩnĩ wenyu.'),
('kam', '2CO', 9, 15, 'Ngai natũngĩwe mũvea kwondũ wa mũthĩnzĩo wake ũtaweteka.'),
('kam', '2CO', 10, 1, 'Na yu, nyie Vaulo mwene, nĩngũmwĩsũva na wĩnyivyo na ũuu wa Klĩsto, nyie ũla nĩ na wĩnyivyo yĩla nĩ vamwe nenyu, ĩndĩ neethĩwa nĩ kũasa nenyu nĩ na ũkũmbaũ mwingĩ kwenyu:'),
('kam', '2CO', 10, 2, 'ĩĩ, nĩngũmwĩsũva, nĩ kana yĩla nĩĩthĩwa vamwe nenyu ndikethĩwe ngyonan’ya ũkũmbaũ mũnene ũla ngũtala kũmakũmbaĩa amwe, ala matũtalaa ta tũendaa kĩ‐mwĩĩ.'),
('kam', '2CO', 10, 3, 'Nũndũ o na kau twĩkinya na mwĩĩ, tũikũkita kwĩanana na mwĩĩ'),
('kam', '2CO', 10, 4, '(nũndũ mĩio ya kaũ ya kũkita kwitũ ti ya mwĩĩ, ĩndĩ yĩ na vinya kwa Ngai wa kũomboa ngome syĩ vinya);'),
('kam', '2CO', 10, 5, 'tũkĩomboa malilikano, na kĩla kĩndũ kĩtũlu kĩtũlĩtye kĩlee ũmanyi wa Ngai, na tũkĩete kĩla kĩsũanĩo ũkombonĩ wa kũmwĩw’a Klĩsto;'),
('kam', '2CO', 10, 6, 'na tũkĩthĩwa twĩyũmbanĩtye kũivanĩsya kũlea kwĩw’a kw’onthe, o yĩla kwĩwa kwenyu kũkeanĩw’a.'),
('kam', '2CO', 10, 7, 'Mwĩsisya maũndũ ala me mbee wa mothyũ menyu. Ethĩwa mũndũ o na wĩva nũkwĩĩkĩĩa mwene kana nĩ wa Klĩsto, nasũanĩe ĩngĩ nthĩnĩ wake, kana, o ũndũ we nĩ wa Klĩsto, naitũ no ta ũu.'),
('kam', '2CO', 10, 8, 'Nũndũ o na ngekathĩĩa mũnango kwondũ wa ũkũmũ witũ (ũla Ngai watũnengie wa kũmwaka, na ti wa kũmũomboa), ndikasonoka:'),
('kam', '2CO', 10, 9, 'ndikesa kwoneka ta ngũmũtĩsya na mavalũa makwa.'),
('kam', '2CO', 10, 10, 'Nĩkwĩthĩwa measya, Mavalũa make nĩ maito na me vinya; ĩndĩ yĩla wĩ vo mwĩĩnĩ nĩ kyonze, na ũneeni wake ndwĩ ũndũ ũtonya.'),
('kam', '2CO', 10, 11, 'Ũla uilyĩ ũu nasũanĩe ũũ, kana, o ũndũ tũilyĩ ndetonĩ sya mavalũa tũte vo, nĩw’o tũilyĩ kwa meko twĩ vo.'),
('kam', '2CO', 10, 12, 'Nũndũ tũti na ũkũmbaũ wa kwĩtala kana kwĩelekan’ya na asu ala mekwĩkathĩĩa ene: ĩndĩ nao ene, makĩthima ene kwa ene, na kwĩelekan’ya ene kwa ene, mati na ũmanyi.'),
('kam', '2CO', 10, 13, 'Ĩndĩ ithyĩ tũikekathĩĩa kũvita vala tũthimĩwe, ĩndĩ o kwĩanana na kĩthimo kĩla Ngai watũthimĩe, nĩ kana tũvike o na kwenyu.'),
('kam', '2CO', 10, 14, 'Nũndũ tũtiũvĩtũka vala tũthimĩwe, ta tũteũvika kwenyu: nũndũ twambie kũvika o na kwenyu tũkĩtavan’ya ũvoo mũseo wa Klĩsto:'),
('kam', '2CO', 10, 15, 'o na ti kwĩkathĩĩa kũvĩtũka vala tũthimĩwe, ta kwĩkathĩĩa mawĩanĩ ma andũ angĩ; ĩndĩ tũkĩkwatya kana ũndũ mũĩkĩĩo wenyu wĩanaa, tũkataĩwa kwenyu mũno kwĩanana na vala tũthimĩwe,'),
('kam', '2CO', 10, 16, 'nĩ kana tũtonye kũtavan’ya ũla ũvoo mũseo kũvika nthĩ ila syĩ mbee wa kwenyu, tũtekwĩkathĩĩa wĩanĩ wa mũndũ ũngĩ maũndũnĩ ala maminĩtwe kũseũvw’a.'),
('kam', '2CO', 10, 17, 'Ĩndĩ ũla ũnũkwĩkathĩĩa, nĩekathĩĩe nthĩnĩ wa Mwĩaĩi.'),
('kam', '2CO', 10, 18, 'Nũndũ ti ũla ũnũkwĩkathĩĩa mwene wĩtĩkĩlawa, ĩndĩ no ũla Mwĩaĩi ũnũũmũkathĩĩa.'),
('kam', '2CO', 11, 1, 'Nĩ ũseo ethĩwa nĩmutonya kũmĩĩsya ũtũmanu wakwa mũnini: ĩĩ, mbũmĩĩsyai.'),
('kam', '2CO', 11, 2, 'Nũndũ nĩmwĩw’ĩaa kĩwĩu, ĩĩ, kĩwĩu kya Ngai: nũndũ nyie nĩmwĩvaĩsye mũũme ũmwe, nĩtonye ũmũnenga Klĩsto ta mwĩĩtu mũtheu.'),
('kam', '2CO', 11, 3, 'Ĩndĩ nĩngũkĩa kũikethĩwe kwa ũndũ o na wĩva, o tondũ ĩla nzoka yamũkengie Eva na ũseleke wayo, mosũanĩo menyu manangwe na kũtia ũlũngalu na ũtheu ũla welekele Klĩsto.'),
('kam', '2CO', 11, 4, 'Nũndũ ethĩwa ũla wĩũka emũtavya ũvoo wa Yesũ ũngĩ, ũla tũtaamũtavya, kana ethĩwa mwĩosa veva ũngĩ, ũla mũtaaosa, kana ũvoo mũseo ũngĩ, ũla mũtaawĩtĩkĩla, nĩ ũseo mũmĩĩsye.'),
('kam', '2CO', 11, 5, 'Nũndũ nĩngũtala kana ndi ĩtina o na vanini wa atũmwa ala anene mbee.'),
('kam', '2CO', 11, 6, 'Ĩndĩ o na ngethĩwa nĩ mũndũ ũtesĩ ũneena, ĩndĩ ũmanyinĩ tiw’o ndilyĩ; ĩndĩ maũndũnĩ onthe kwa nzĩa syonthe nĩtũmwonetye ũu.'),
('kam', '2CO', 11, 7, 'Kana nĩneekie naĩ ngĩnyivya nĩ kana inyw’ĩ mũtũlw’e, nũndũ namũtavisye ũvoo mũseo wa Ngai vate ĩtuvi?'),
('kam', '2CO', 11, 8, 'Navutie makanisa angĩ, ngyosa ĩtuvi kwoo nĩ kana nĩmũthũkũme inywĩ;'),
('kam', '2CO', 11, 9, 'na yĩla naĩ vamwe nenyu na naĩ mũnyivĩe, ndyaĩ mũio kwa mũndũ o na wĩva; nũndũ ana‐a‐asa, mooka kuma Masetonia, nĩmo mambusũisye kũnyivĩwa kwakwa; na maũndũnĩ onthe nesũvĩie ndikethĩwe nĩ mũio kwenyu, na ngeesũvĩaa o ũu.'),
('kam', '2CO', 11, 10, 'O ũndũ w’o wa Klĩsto wĩ nthĩnĩ wakwa, vai mũndũ wĩnziĩĩa kwĩkathĩĩa kwakwa nĩ nthĩ sya Akaia.'),
('kam', '2CO', 11, 11, 'Nũndũ wa kĩ? Nĩkwĩthĩwa ndiũmwenda? Ngai nĩwĩsĩ.'),
('kam', '2CO', 11, 12, 'Ĩndĩ ũla ngwĩka, nĩw’o ngeka, nĩ kana nĩmaĩsye ũthei asu mekwenda ũthei; nĩ kana moneke taitũ, ũndũnĩ ũsu mekwĩkathĩia.'),
('kam', '2CO', 11, 13, 'Nũndũ andũ ta asu nĩ atũmwa ma ũvũngũ, atethya ma wĩa na ũseleke, makĩalyũla ene methĩwe ta atũmwa ma Klĩsto.'),
('kam', '2CO', 11, 14, 'Na ti ũndũ wa useng’ya; nũndũ o na Satani nake nĩwĩalyũlaa mwene ethĩwe ta mũlaĩka wa kyeni.'),
('kam', '2CO', 11, 15, 'Na kwondũ wa ũu ti ũndũ ũnene athũkũmi make kwĩalyũla methĩwe ta athũkũmi ma ũlũngalu; namo mũminũkilyo woo ũkeethĩwa ta mawĩa moo.'),
('kam', '2CO', 11, 16, 'Nĩmũtavya ĩngĩ, Mũndũ ndakasye nĩ mũtumanu; ĩndĩ ethĩwa no ũu, mbosai ta mũtumanu, nĩ kana nyie nakwa nĩkathĩĩe vanini.'),
('kam', '2CO', 11, 17, 'Ũu ngũneena, ndiũneena ta wumĩte kwa Mwĩaĩi, ĩndĩ ta kwa ũtumanu, wĩkwatyonĩ ũũ wa kwĩkathĩĩa.'),
('kam', '2CO', 11, 18, 'Nĩkwĩthĩwa aingĩ mekathĩĩaa maũndũni ma mwĩĩ, nakwa ngeekathĩĩa.'),
('kam', '2CO', 11, 19, 'Nũndũ nĩmũmĩĩasya ala atumanu na ũtanu, nĩkwĩthĩwa mwĩ oĩ.'),
('kam', '2CO', 11, 20, 'Nũndũ nĩmũmĩĩasya mũndũ, akĩmũlikya ũkombonĩ, aimũya, aimũtava, akĩnenevya, aimũkũna ũthyũ.'),
('kam', '2CO', 11, 21, 'Nĩneena na kwĩvũthĩĩsya, ta twaĩ onzu ithyĩ. Ĩndĩ ũndũnĩ o na wĩva ve ngũmbaũ (nĩneena na ũtumanu), nyie nakwa nĩ ngũmbaũ.'),
('kam', '2CO', 11, 22, 'Nĩ Ayuti mo? O nakwa. Nĩ Aisilaeli mo? O nakwa. Nĩ ũsyao wa Avalaamu mo? O nakwa.'),
('kam', '2CO', 11, 23, 'Nĩ athũkũmi ma Klĩsto? (Nĩneena ta ũla wĩ na ndũũka) nyie nĩ mbee; mathĩnanĩ ma wĩa nyie nĩ mbee mũno, naĩ kolokolonĩ kaingĩ muno, kũkũnwa nĩ kaingĩ mbee, na kĩkw’ũnĩ nĩ kaingĩ.'),
('kam', '2CO', 11, 24, 'Kwa Ayuti nĩnakũniwe mavinda atano ivoko mĩongo ĩna kũoleka kĩmwe.'),
('kam', '2CO', 11, 25, 'Nĩkũnangĩtwe na ndata mavinda atatũ, nĩkimangĩtwe na mavia ĩvinda yĩmwe, ngalawa syaanangĩkie mavinda atatũ nĩ kyalonĩ, naĩ ũkanganĩ ũtukũ ũmwe na mũthenya ũmwe;'),
('kam', '2CO', 11, 26, 'naĩ syalonĩ kaingĩ, mĩisyonĩ ya mbũsĩ, mĩisyo ya ing’ei, mĩisyo ya andũ ma mbaitũ, mĩisyo ya Andũ‐ma‐mbaĩ‐ingĩ, mĩisyo ya ndũanĩ, mĩisyo ya weũnĩ, mĩisyo ya ũkanganĩ, mĩisyo ya ana‐a‐asa ma ũvũngũ;'),
('kam', '2CO', 11, 27, 'thĩnanĩ wa mawĩa na woonĩ, kũsyaĩĩsya nĩ kaingĩ, kwĩw’a nzaa na waũni, kũtĩĩa kũya nĩ kaingĩ, mbevonĩ na kũtwĩkĩwa.'),
('kam', '2CO', 11, 28, 'Na eka maũndũ ala ndanaweta, ve ũla ũmbivinyaa matukũ onthe, kũũũyĩa makanisa onthe.'),
('kam', '2CO', 11, 29, 'Nũũ ũla mwonzu, nakwa ndi mwonzũ? Nũũ ũla ũnũũlulutĩkw’a, na ndikũvya nĩ woo?'),
('kam', '2CO', 11, 30, 'Ethĩwa no mũvaka nĩkathĩĩe, ngeekathĩĩa maũndũnĩ asu ma wonzu wakwa.'),
('kam', '2CO', 11, 31, 'Ngai, Ĩthe wa Mwĩaĩi waitũ Yesũ, ũla ũtaĩawa kũvika tene na tene nĩwĩsĩ kana ndiũneena ũvũngũ.'),
('kam', '2CO', 11, 32, 'Ndũanĩ ya Ndamasiku, ngavana ũla waĩ ĩtheo wa mũsumbĩ Aleta nĩwasũvĩie ndũa ĩsu ya Andamasiku, nĩ kana angwate:'),
('kam', '2CO', 11, 33, 'na natonyelw’e mbũthinĩ natheelelw’a ũvainĩ nĩ kĩkavũnĩ nthĩnĩ, na natbonoka mokonĩ make.'),
('kam', '2CO', 12, 1, 'Mũvaka nĩkathĩĩe, o na kau ti ũndũ waĩle; ĩndĩ ngaweta mawoni na movuan’yo ma Mwĩaĩi.'),
('kam', '2CO', 12, 2, 'Nĩnĩsĩ mũndũ nthĩnĩ wa Klĩsto, yu nĩvĩtĩte myaka ĩkumi na ĩna (ethĩwa aĩ nthĩnĩ wa mwĩĩ, ndyĩsĩ; kana ethĩwa ndaĩ nthĩnĩ wa mwĩĩ, ndyĩsĩ; Ngai nĩwĩsĩ), ũsu ambatiw’e kũvika ĩtunĩ ya katatũ.'),
('kam', '2CO', 12, 3, 'Nakwa nĩnĩmwĩsĩ mũndũ ũsu (ethĩwa aĩ nthĩnĩ wa mwĩĩ, kana ndaĩ nthĩnĩ wa mwĩĩ, ndyĩsĩ; Ngai nĩwĩsĩ),'),
('kam', '2CO', 12, 4, 'ũndũ wambatiw’e alikw’a Ũseonĩ, na eew’a ndeto ila itaweteka, na ila itaĩle mũndũ kwineena.'),
('kam', '2CO', 12, 5, 'Kwondũ wa mũndũ ũtilyĩ ta ũsu ngeekathĩĩa; ĩndĩ kwondũ wakwa ndiĩkathĩĩa, ate o mawonzunĩ makwa.'),
('kam', '2CO', 12, 6, 'Nũndũ o na ngethĩwa ngyenda kwĩkathĩĩa, ndikethĩwa nĩ mũtumanu; nũndũ nganeena w’o: ĩndĩ nĩngũeka, nĩ kana mũndũ o na wĩva ndakandalĩle mbee wa ũndũ wonaa niilyĩ, kana ũla wĩw’aa kuma kwakwa.'),
('kam', '2CO', 12, 7, 'Na kwondũ wa movuan’yo asu manene mũno mavĩtũku, nĩ kana ndikethĩwe ngĩnenevya mbee wa ũndũ naĩlwe, nanengiwe mwĩw’a mwĩĩnĩ wakwa, mũtũmwa wa Satani wa kũnumangya, nĩ kana ndikenenevye mbee wa ũndũ naĩlwe.'),
('kam', '2CO', 12, 8, 'Kwondũ wa kindũ kyu navoya Ngai katatũ, ni kana kyume kwakwa.'),
('kam', '2CO', 12, 9, 'Nake ambĩa, Mumo wakwa nũkwĩanĩe: nĩkwĩthĩwa vinya wakwa wĩanĩe vala ve wonzu. Ngeekathĩĩa ĩndĩ wonzunĩ wakwa na ũtanu mwingĩ, nĩ kana vinya wa Klĩsto wĩkalae ĩũlũ wakwa.'),
('kam', '2CO', 12, 10, 'Kwondũ wa ũu nĩtanaa mawonzunĩ, na mbũthyanĩ, na mavatanĩ, na mathĩnanĩ, na monyamaonĩ, kwondũ wa Klĩsto: nĩkwĩthĩwa yĩla nĩ mwonzu, nĩvo nĩ na vinya.'),
('kam', '2CO', 12, 11, 'Nĩtw’ĩkĩte mũtumanu: nĩ inyw’ĩ mwatumie nĩka ũu; nũndũ nyie naĩle kũkathwa nĩ inyw’ĩ: nũndũ ndyaĩ ĩtina wa atũmwa ala me mbee kwa ũndũ o na ũmwe, o na kau nyie ti kĩndũ.'),
('kam', '2CO', 12, 12, 'Nĩ w’o, maũndũ ala monanasya mũtũmwa nĩmeekiwe kwenyu na wũmĩĩsyo w’onthe, na syama na maũndũ ma ũseng’ya na mavinya.'),
('kam', '2CO', 12, 13, 'Nũndũ nĩ ũndũnĩ mwaũ mũnyivĩwe kwĩ makanisa ala angĩ, ate o kana nyie ndyaĩ mũio kwenyu? Ndekeai ĩvĩtyo yĩu.'),
('kam', '2CO', 12, 14, 'Sisyai, yĩĩ nĩ ya katatũ nĩyũmbanĩtye kũka kwenyu; na ndikethĩwa nĩ mũio kwenyu: nũndũ ndiũmantha syĩndũ syenyu, ĩndĩ nĩ inyw’ĩ: nũndũ syana ityaĩlwe nĩ kũmbanĩsya asyai, ĩndĩ asyai nĩmaĩlwe nĩ kũmbanĩsya syana.'),
('kam', '2CO', 12, 15, 'Nakwa nyie nganengane na ũtanu mwingi na kwĩnengane vyũ kwondũ wenyu. Ethĩwa nyie nĩmwendaa mũno mbee, nĩw’o ũtuma mũnyivya kũmbenda?'),
('kam', '2CO', 12, 16, 'Ĩndĩ o na ethĩwa nĩ ũu, nyie mwene ndyaamwilĩĩla mũio; ĩndĩ kwa kwĩthĩwa nĩ mũĩ, namũkwatie na ũseleke.'),
('kam', '2CO', 12, 17, 'Nĩmũsesengetwe nĩ ũmwe o na wĩva wa ala natũmie kwenyu?'),
('kam', '2CO', 12, 18, 'Namũtaie Tito, na natũmie ũla mwana‐a‐asa vamwe nake. Tito nĩwamũsesengie? Tũiaendaa na Veva o ũmwe? Na matambya o amwe?'),
('kam', '2CO', 12, 19, 'Na ĩvinda yĩĩ yonthe mwaasya kana nĩtũkwĩmila kwenyu. Mbee wa Ngai tũneenaa nthĩnĩ wa Klĩsto. Ĩndĩ maũndũ onthe, endwa, nĩ kwondũ wa kũmwaka.'),
('kam', '2CO', 12, 20, 'Nũndũ nĩngũkĩa, kũikethĩwe kwa ũndũ o na wĩva, yĩla nĩũka, nĩmwone mũilyĩ ũndũ ndekwenda, nakwa mwene noneke nĩ inyw’ĩ nĩilyĩ ũndũ mũtekwenda; kũikethĩwe kwa undũ o na wĩva ĩteta, na kĩwĩu, na mothiliku, na ngananĩo, na nzukũ, na kũwetana na kĩwe, na mĩyimbyo na ituu;'),
('kam', '2CO', 12, 21, 'nakwa yĩla nĩũka ĩngĩ Ngai wakwa ndakese kũnyivya mbee wenyu, nise kwĩthĩwa na kĩmako ũndũ wa aingĩ ala meekie naĩ, na matyaalyũla ngoo ũndũ wa ũvuku na ũlaalai na mĩmeo mĩthũku ala meekie.'),
('kam', '2CO', 13, 1, 'Yũka yĩĩ niũka kwenyu nĩ ya katatũ. Ũndũ wa makanyw’a ma ngũsĩ ili kana itatũ kĩla ũndũ ũkalũlũmĩlw’a.'),
('kam', '2CO', 13, 2, 'Nambie kũneena na nĩngũneena ĩngĩ nde vo, o tondũ namũtavisye yĩla naĩ nenyu ĩvinda ya kelĩ, no ta ũu yu, kana ala meekie naĩ na vu tene na ala angĩ onthe, ethĩwa nĩngũka ĩngĩ, ndiĩw’ĩa tei;'),
('kam', '2CO', 13, 3, 'nũndũ nĩmũkũmantha ũndũ wa kũmũmanyĩthya kana Klĩsto nĩwe ũneenaa nthĩnĩ wakwa; ũla ũte mwonzu kwenyu, ĩndĩ e na vinya nthĩnĩ wenyu:'),
('kam', '2CO', 13, 4, 'nũndũ ambiwe kwondũ wa wonzu, ĩndĩ e thayũ kwondũ wa vinya wa Ngai. Nũndũ ithyĩ naitũ twĩ onzu nthĩnĩ wake, ĩndĩ tũkeethĩwa thayũ vamwe nake kwondũ wa vinya Ngai ũla welekele kwenyu.'),
('kam', '2CO', 13, 5, 'Ĩthimei inyw’ĩ ene, kana mwĩ ũla mũĩkĩĩonĩ; iosyei inyw’ĩ ene. Kana mũtyĩsĩ ũndũ wenyu, atĩ Yesũ Klĩsto e nthĩnĩ wenyu? Ate ũu mwĩthĩwa mũleetwe.'),
('kam', '2CO', 13, 6, 'Ĩndĩ nĩngwĩkwatya kana mũkamanya kana ithyĩ tũtileetwe.'),
('kam', '2CO', 13, 7, 'Na yu twĩmũvoya Ngai kana mũikeke naĩ; ti kana ithyĩ twoneke twĩtĩkĩlwe, ĩndĩ nĩ kana inyw’ĩ mwĩke ũla waĩle, o na kau nĩ ta tũleetwe.'),
('kam', '2CO', 13, 8, 'Nũndũ tũtitonya kwĩka ũndũ o na wĩva wa ũsiĩĩa ũla w’o, ĩndĩ no kwa ngalĩ ya ũla w’o.'),
('kam', '2CO', 13, 9, 'Nũndũ nĩtũtanaa, yĩla ithyĩ twĩ onzu, na inyw’ĩ mwĩ na vinya: na ĩngĩ nĩtũvoyeaa ũndũ ũũ naw’o, nĩ kana mwĩanĩe.'),
('kam', '2CO', 13, 10, 'Kwondũ wa ũu nĩandĩka maũndũ aa nde vo, nĩ kana yĩla nĩĩthĩwa vo ndikeke ũndũ na ũkandĩa, kwĩanana na ũkũmũ ũla Mwĩaĩi wanengie kwondũ wa kwaka, na ti kũomboa.'),
('kam', '2CO', 13, 11, 'Na kũminũkĩlya, ana‐a‐asa, ĩkalai na ũvoo. Ianĩai; kiakiw’ai; ĩthĩwai na kĩlilikano kĩmwe; ĩkalai mũuonĩ: na Ngai wa wendo na mũuo akeethĩwa nenyu.'),
('kam', '2CO', 13, 12, 'Kethan’yai na ũmumunyano mũtheu.'),
('kam', '2CO', 13, 13, 'Atheu onthe nĩmamũkethya.'),
('kam', '2CO', 13, 14, 'Mumo wa Mwĩaĩi Yesũ Klĩsto, na wendo wa Ngai, na mũamba wa Veva Mũtheu, nĩmethĩwe nenyu inyw’onthe.'),
('kam', 'GAL', 1, 1, 'Vaulo, mũtũmwa (ti kuma kwa andũ kana kwondũ wa mũndũ, ĩndĩ nĩ kwondũ wa Yesũ Klĩsto, na Ngai Asa, ũla wamũthayũũkisye kũmumya kwa akw’ũ),'),
('kam', 'GAL', 1, 2, 'na ana‐a‐asa onthe ala me vamwe nakwa, valũa ũũ witũ ũmavikĩe makanisa ma Kalatia:'),
('kam', 'GAL', 1, 3, 'Mumo nĩwĩthĩwe kwenyu na mũuo kuma kwa Ngai Asa, na kwa Mwĩaĩi waitũ Yesũ Klĩsto,'),
('kam', 'GAL', 1, 4, 'ũla wenenganie mwene kwondũ wa naĩ sitũ, nĩ kana atũtangĩĩe tume nthĩ ĩno nthũku ya ĩvinda yĩĩ, kwĩanana na kwenda kwa Ngai, Asa waitũ:'),
('kam', 'GAL', 1, 5, 'ndaĩa nĩyĩthĩwe kwake tene na tene, Ameni.'),
('kam', 'GAL', 1, 6, 'Nĩngũseng’a nũndũ nĩmũũthamw’a na mĩtũkĩ ta ũu na kũmũtia ũla wamwĩtie nthĩnĩ wa mumo wa Klĩsto na kũkwata ũvoo mũseo ũngĩ;'),
('kam', 'GAL', 1, 7, 'naw’o ti ũvoo mũseo ũngĩ: ĩndĩ kwĩ amwe ala meũmũthĩn’ya, nao meenda kũalyũla ũvoo mũseo wa Klĩsto.'),
('kam', 'GAL', 1, 8, 'Ĩndĩ o na ethĩwa nĩ ithyĩ, kana mũlaĩka wumĩte ĩtunĩ, ũnũũtavan’ya kwenyu ũvoo mũseo ũngĩ o na wĩva eka ũla twamũtavisye, ũsu nĩethĩwe anathema (ũalyũlo wayo nĩ, mũumanĩe).'),
('kam', 'GAL', 1, 9, 'O tondũ twamba ũneena, nĩw’o ngũneena ĩngĩ yu, Ethĩwa mũndũ o na wĩva w’onthe emũtavya ũvoo mũseo ũngĩ eka ũla mwosete, ũsu nĩethĩwe anathema (ũalyũlo wayo nĩ, mũumanĩe).'),
('kam', 'GAL', 1, 10, 'Nũndũ yu nĩmantha kwĩtĩkĩlwa nĩ andũ, kana nĩ Ngai? Kana nĩĩthing’ĩĩsya kwendeesya andũ? Ethĩwa kũvika o na yu nĩendeesya andũ, ndyĩthĩwa nĩ ngombo ya Klĩsto.'),
('kam', 'GAL', 1, 11, 'Nũndũ nĩngũmũmanyĩthya, ana‐a‐asa, ũndũ wa ũla ũvoo mũseo namũtavisye, kana ũvoo ũsu ti wa mũndũ.'),
('kam', 'GAL', 1, 12, 'Nũndũ ndyaawosa kwa mũndũ, na ndyaaũmanyĩw’a, ĩndĩ nĩwookie kwakwa nũndũ wa ũvuan’yo wa Yesũ Klĩsto.'),
('kam', 'GAL', 1, 13, 'Nũndũ nĩmwĩw’ĩte ũvoo wa mwĩkalĩle wakwa wa tene mũthaithĩlenĩ wa Ayuti, ũndũ nathĩnisye ĩkanisa ya Ngai kũthonoka kũthima, na kũyananga:'),
('kam', 'GAL', 1, 14, 'nakwa naendeee ũla mũthaithĩlenĩ wa Ayuti kũvĩta aingĩ ma mbaĩ yakwa ala maĩ ĩika yĩmwe nakwa, kwa kwĩthĩwa naĩ na ũthangaau mũnene nũndũ wa mokũũ ma aasa makwa.'),
('kam', 'GAL', 1, 15, 'Ĩndĩ yĩla Ngai wonie nĩ ũseo, ũla wambathũkanisye, o na kuma ĩvunĩ ya mwaitũ, na ambĩta kwondũ wa mumo wake,'),
('kam', 'GAL', 1, 16, 'kwonan’ya Mwana wake nthĩnĩ wakwa, kana nĩmũtavan’ye kwa Andũ‐ma‐mbaĩ‐ingĩ; yu ndyaasũanĩa na andũ me na mwĩĩ na nthakame:'),
('kam', 'GAL', 1, 17, 'o na ndyaambata Yelusaleme kwa ala mai atũmwa mbee wakwa: ĩndĩ naendie nthĩ ya Alavu; na ĩngi naalũka Ndamasiku.'),
('kam', 'GAL', 1, 18, 'Ĩndĩ ĩtina wa myaka ĩtatũ nambatie Yelusaleme kũmanyana na Keva, na nekala nake matukũ ĩkũmi na atano.'),
('kam', 'GAL', 1, 19, 'Ĩndĩ ndyaamona atũmwa ala angĩ, ate o Yakovo mwana‐a‐inyia wa Mwĩaĩi.'),
('kam', 'GAL', 1, 20, 'Na ũvoo wa maũndũ ala ngũmũandĩkĩa, sisyai, mbee wa Ngai, ndiũneena ũvũngũ.'),
('kam', 'GAL', 1, 21, 'Na ĩtina naendie nthĩ ya Silia na Silisia.'),
('kam', 'GAL', 1, 22, 'Na ĩvinda yĩu ndyeesĩkĩwe ũthyũ wakwa nĩ makanisa ma Yutia ala maĩ nthĩnĩ wa Klĩsto:'),
('kam', 'GAL', 1, 23, 'ĩndĩ meew’ĩte kũineenwa tũ, Ũla watũthĩnasya tene, yu nũtavanasya mũĩkiĩo ũla wanangaa tene;'),
('kam', 'GAL', 1, 24, 'nao mataĩa Ngai kwondũ wakwa.'),
('kam', 'GAL', 2, 1, 'Na ĩndĩ ĩtina wa myaka ĩkũmi na ina, nambatie ĩngĩ Yelusaleme nyie na Valanava, na Tito naĩ nake.'),
('kam', 'GAL', 2, 2, 'Nakwa nambatie nũndũ nĩnavuanĩw’e; na nĩnamonisye ũvoo mũseo ũla nĩtavanasya kwa Andũ‐ma‐mbaĩ‐ingĩ, ĩndĩ nĩnamatavisye ala maĩ na nguma me oka, nĩ kana kwa ũndũ o na wĩva ndikethĩwe ngĩsemba mana, kana nasembie mana.'),
('kam', 'GAL', 2, 3, 'Ĩndĩ o na Tito ũla waĩ vamwe nakwa, nake aĩ Mũkiliki, ndaathing’ĩĩw’a kwaĩkwa:'),
('kam', 'GAL', 2, 4, 'na ũu nĩ kwondũ wa ana‐a‐asa ma ũvũngũ ala malikilw’e nthĩnĩ na kĩmbithĩ, ala mavotie na kĩmbithĩ mathiane kũthaw’a kwitũ kũla twĩ nakw’o nthĩnĩ wa Klĩsto Yesũ, nĩ kana matũtwae ũkombonĩ:'),
('kam', 'GAL', 2, 5, 'nao tũtyaamanenga ũthei ta kũmenyivĩsya, aiee, o na saa ũmwe; nĩ kana ũla w’o wa ũvoo mũseo wikale nenyu.'),
('kam', 'GAL', 2, 6, 'Ĩndĩ kwa asu ala maĩ na nguma ya kwĩthĩwa nĩ anene (ũndũ mekalile, vai ũndũ kwakwa: Ngai ndendeeaw’a nĩ wũmbe wa mũndũ) — nao, nĩasya, ala maĩ na nguma matyaambongeleela ũndũ:'),
('kam', 'GAL', 2, 7, 'ĩndĩ ngalĩ ĩla, ĩngĩ, yĩla moonie kana nĩwaiiwe kwakwa ũvoo mũseo nĩtavan’ye kwa ala mate aĩke, o ũndũ Vetelo waĩ na ũvoo mũseo aitavan’ya kwa ala aĩke'),
('kam', 'GAL', 2, 8, '(nũndũ ũla wamũtonyethisye Vetelo kwĩthĩwa mũtũmwa kwa asu aĩke wandonyethisye nĩtw’ĩke mũtũmwa kwa Andũ‐ma‐mbaĩ‐ingĩ);'),
('kam', 'GAL', 2, 9, 'na yĩla mamanyie ũla mumo nanengiwe, Yakovo na Keva na Yoana, ala matalawa kwĩthĩwa nĩmo ituĩ, manengie nyie vamwe na Valanava moko ma aũme ma mũamba, nĩ kana ithyĩ tũthi kwa Andũ‐ma‐mbaĩ‐ingĩ, nao mathi kwa ala maĩkawa;'),
('kam', 'GAL', 2, 10, 'ĩndĩ no ũndũ ũmwe mendie nĩ kana tũmalilikane ala ngya; naw’o ũndũ ũsu naĩ na ũthangaau kũwĩka.'),
('kam', 'GAL', 2, 11, 'Ĩndĩ yĩla Keva wokie Andiokia, nĩnamũkananĩsye twenene, nũndũ aĩ mũsilĩle kwĩthĩwa nĩ mũvĩtan’ya.'),
('kam', 'GAL', 2, 12, 'Nũndũ mbee wa andũ amwe matanauma kwa Yakovo, aĩsaa lĩu na Andũ‐ma‐mbaĩ‐ingĩ; ĩndĩ yĩla mookie, atundua na eevathana nao, aimakĩa asu ala maĩkawa.'),
('kam', 'GAL', 2, 13, 'Na Ayuti ala angĩ meealyũlile vamwe nake; o na Valanava nĩwaiwe nĩ wangangan’yo woo.'),
('kam', 'GAL', 2, 14, 'Ĩndĩ yila noonie kana maiendaa na mĩendele myaĩlu kwĩanana na ũla w’o wa ũvoo mũseo, namũtavĩsye Keva mbee wamo onthe, Ethĩwa we, wĩ Mũyuti, ũvikĩlaa maũndũ ma Andũ‐ma‐mbaĩ‐ingĩ, na ti ala ma Ayuti, kũilyĩ ata we kũingĩĩsya Andũ‐ma‐mbaĩ‐ingĩ kũvikĩlaa maũndũ ma Ayuti?'),
('kam', 'GAL', 2, 15, 'Ithyĩ ala twĩ Ayuti kwa mũtuo witũ, na ti andũ athe ma Andũ‐ma‐mbaĩĩngi,'),
('kam', 'GAL', 2, 16, 'ĩndĩ twĩsĩ mũndũ ndatalĩlawa ũlũngalu kwondũ wa meko ma ĩla mĩao ĩndĩ nĩ kwondũ wa kũĩkĩĩa Yesũ Klĩsto, o naitũ nĩtwĩtĩkĩlĩte Klĩsto Yesũ, nĩ kana tũtalĩlwe ũlũngalu nũndũ wa kũmũĩkĩĩa Klĩsto, na ti kwa meko ma ĩla mĩao: nĩkwĩthĩwa kwondũ wa meko ma ĩla miao vai mwĩĩ ũtonya kũtalĩlwa ũlũngalu.'),
('kam', 'GAL', 2, 17, 'Ĩndĩ ethĩwa, yĩla twamanthie kũtalwa kwĩthĩwa alũngalu nthĩnĩ wa Klĩsto, ithyĩ naitũ twonekie twĩ andũ athe, Klĩsto nĩ mũthũkũmi wa naĩ? Aiee, kũikethĩwe ũu.'),
('kam', 'GAL', 2, 18, 'Nũndũ ethĩwa nĩngwaka ĩngĩ maũndũ asu ala naanangie, nĩngwĩyonan’ya kana nĩ mũvĩtan’ya.'),
('kam', 'GAL', 2, 19, 'Nũndũ kwa nzĩa ya ĩla mĩao nĩnakwie kwa ĩla mĩao, nĩ kana nĩthĩwe thayũ kwa Ngai.'),
('kam', 'GAL', 2, 20, 'Nĩnambiwe ngelan’yonĩ vamwe na Klĩsto; na tii nyie nĩ thayũ ĩngĩ, ĩndĩ no Klĩsto wĩ thayũ nthĩnĩ wakwa: na thayũ ũũ nĩ naw’o yu mwĩĩnĩ nĩngwĩkala naw’o mũĩkĩĩonĩ, mũĩkĩĩo ũla wĩ nthĩnĩ wa Mwana wa Ngai, ũla wambendie, na eenengane kwondũ wakwa.'),
('kam', 'GAL', 2, 21, 'Ndiũvetanga mumo wa Ngai: nũndũ ethĩwa ũlũngalu wonekaa kwondũ wa ĩla mĩao, Klĩsto akeethĩwa ta wakwie mana.'),
('kam', 'GAL', 3, 1, 'Inyw’ĩ Akalatia mũte na kĩlĩko, nũũ, ũla ũmũalyũlĩte inyw’ĩ ala Yesũ Klĩsto wonanĩtw’e nesa mbee wa metho menyu ambĩtwe?'),
('kam', 'GAL', 3, 2, 'Nĩngwenda kũmanya ũndũ ũũ ũmwe kwenyu, Mwosete ũla Veva nũndũ wa meko ma ĩla mĩao, kana nũndũ wa kwĩw’a kumĩte mũĩkĩĩonĩ?'),
('kam', 'GAL', 3, 3, 'Kaĩ, mũtumanĩte ũũ? Mwambĩlĩlye Vevanĩ, na yu mwĩĩanĩw’a mwĩĩnĩ?'),
('kam', 'GAL', 3, 4, 'Nĩmwathĩnie mathĩna maingĩ meana ũu mana? Ethĩwa nĩ w’o ni mana.'),
('kam', 'GAL', 3, 5, 'Ĩndĩ we ũla ũmũnengae ũla Veva, na kwĩka mavinya katĩ wenyu, nĩwĩkaa kwondũ wa meko ma ĩla mĩao, kana nũndũ wa kwĩw’a kumĩte mũĩkĩĩonĩ?'),
('kam', 'GAL', 3, 6, 'O ũndũ Avalaamu wetĩkĩlile Ngai, na nĩkwatalilwe kwake kwĩthĩwa ũlũngalu.'),
('kam', 'GAL', 3, 7, 'Manyai ĩndĩ kana ala me na mũĩkĩĩo, asu nĩo ana ma Avalaamu.'),
('kam', 'GAL', 3, 8, 'Na ũandĩko, woonie mbee kana Ngai akamatalĩla Andũ‐ma‐mbaĩ‐ingĩ ũlũngalu kwondũ wa mũĩkĩĩo, watavisye Avalaamu ũvoo mũseo tene, ũkyasya, Nthĩnĩ waku mbaĩ syonthe nikaathimwa.'),
('kam', 'GAL', 3, 9, 'Na kwondũ wa ũu ala ma mũĩkĩĩo nĩmaathimĩtwe vamwe na Avalaamu ũla waĩ mũĩkĩĩi.'),
('kam', 'GAL', 3, 10, 'Nũndũ onthe ala ma meko ma ĩla mĩao me ungu wa kĩumo: nũndũ nĩkũandĩkĩtwe, Nũumanĩwe kĩla mũndũ ũtekalaa aiĩkaa maũndũ onthe ala maandĩkĩtwe ĩvukunĩ ya mĩao.'),
('kam', 'GAL', 3, 11, 'Ĩndĩ nĩkwonekete kana vai mũndũ ũtalĩlawa ũlũngalu kwa Ngai kwondũ wa ĩla mĩao: nũndũ, Ũla mũlũngalu akekala thayũ kwondũ wa mũĩkĩĩo;'),
('kam', 'GAL', 3, 12, 'na ĩla mĩao ti ya mũĩkĩĩo; ĩndĩ, Ũla wĩkaa maũndũ ma ĩla mĩao akekala thayũ nthĩnĩ wayo.'),
('kam', 'GAL', 3, 13, 'Klĩsto atwovoisye kuma kĩumonĩ kya ĩla mĩao, nũndũ nĩwatw’ĩkie kĩumo kwondũ witũ; nĩkwĩthĩwa nĩkũandĩkĩtwe, Nũumanĩwe, kĩla mũndũ ũsũaw’a mũtĩnĩ ĩũlũ:'),
('kam', 'GAL', 3, 14, 'nĩ kana ũathimo wa Avalaamu nthĩnĩ wa Klĩsto Yesũ ũtonye ũmavikĩa Andũ‐ma‐mbaĩ‐ingĩ; nĩ kana ithyĩ tũtonye kwosa watho wa Veva kwondũ wa mũĩkĩĩo.'),
('kam', 'GAL', 3, 15, 'Ana‐a‐asa, nĩngũneena o tondũ andũ makothaa kũneena: O na ethĩwa no ũtianĩo wa mũndũ, ĩndĩ yĩla ũlũlũmĩlw’e, vai mũndũ ũkoveta, kana kũwongela ũndũ.'),
('kam', 'GAL', 3, 16, 'Na ĩndĩ Avalaamu nĩwe wataviw’e matho, na ũsyao wake. Ndaasya, Kwa mosyao, ta andũ aingĩ; ĩndĩ ta mũndũ ũmwe, Kwa ũsyao waku, naw’o nĩ Klĩsto.'),
('kam', 'GAL', 3, 17, 'Ĩndĩ nĩngũneena ũũ: Ũtianĩo walũlũmĩlw’e mbee nĩ Ngai, ĩla mĩao, ĩla yokie ĩtina wa myaka maana ana na mĩongo ĩtatũ, ndyaananga, ta kũtw’ĩkĩthya watho ta wa mana.'),
('kam', 'GAL', 3, 18, 'Nũndũ ethĩwa ũtiĩwa nĩ kwondũ wa ĩla mĩao, ti wa watho ĩngĩ: ĩndĩ Ngai amũnengie Avalaamu nũndũ wa watho.'),
('kam', 'GAL', 3, 19, 'Ĩndĩ ĩla mĩao nĩ myaũ? Yongeleelwe nũndũ wa mavĩtyo, kũvika yĩla ũsyao ũkoka ũla wathiwe watho; na yatwiwe nĩ alaĩka ĩnenganĩtwe na kw’oko kwa mwĩw’anĩthya.'),
('kam', 'GAL', 3, 20, 'Ĩndĩ mwĩw’anĩthya ndethĩawa mwĩw’anĩthya wa ũmwe; ĩndĩ Ngai ni ũmwe.'),
('kam', 'GAL', 3, 21, 'Ĩndĩ mĩao ko ĩkananĩsye matho ma Ngai? Aiee: kũikethĩwe ũu: nũndũ ethĩwa kwaĩ mwĩao wanenganiwe ũla ũtonya kũnenga andũ thayũ, nĩ w’o ũlũngalu wĩthĩwa waĩ wa ĩla mĩao.'),
('kam', 'GAL', 3, 22, 'Ĩndĩ maandĩko nĩmavingĩĩte maũndũ onthe ungu wa naĩ, nĩ kana watho kwondũ wa mũĩkĩĩo nthĩnĩ wa Yesũ Klĩsto, ũtonye ũnengwa ala metĩkĩlaa.'),
('kam', 'GAL', 3, 23, 'Ĩndĩ mbee wa mũĩkĩĩo ũtanoka, twekalĩte twovetwe ungu wa mĩao, tũvingĩĩtwe kũvika ũla mũĩkĩĩo ũkonanw’a.'),
('kam', 'GAL', 3, 24, 'Kwondũ wa ũu ĩla mĩao yatw’ikie mũmanyĩsya waitũ kũtũete kwa Klĩsto, nĩ kana tũtonye kũtalĩlwa ũlũngalu kwondũ wa mũĩkĩĩo.'),
('kam', 'GAL', 3, 25, 'Ĩndĩ yu, mũĩkĩĩo wooka, tũi ungu wa mũmanyĩsya ĩngĩ.'),
('kam', 'GAL', 3, 26, 'Nũndũ inyw’onthe mwĩ ana ma Ngai, kwondũ wa mũĩkĩĩo, nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'GAL', 3, 27, 'Nũndũ inyw’ĩ o ala mwavatisiwe kũlikw’a nthĩnĩ wa Klĩsto nĩmwĩvw’ĩkĩte Klĩsto.'),
('kam', 'GAL', 3, 28, 'Kũitonya kwĩthĩwa Mũyuti o na Mũkiliki, na kũitonya kwĩthĩwa mwove na ũte mwove, na kũitonya kwĩthĩwa mũndũ mũũme na mũndũ mũka; nũndũ inyw’onthe mwĩ ũmwe nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'GAL', 3, 29, 'Na ethĩwa mwĩ ma Klĩsto, mwĩ ũsyao wa Avalaamu, na atiĩwa kwĩanana na watho.'),
('kam', 'GAL', 4, 1, 'Ĩndĩ nĩneena kana ĩvinda ya mũtiĩwa e kana, nde kĩvathũkan’yo na ngombo, o na kau nĩ mwene wa syĩndũ syonthe;'),
('kam', 'GAL', 4, 2, 'ĩndĩ ke ungu wa asũvĩi na asyaĩĩsya ma syĩndũ syako, kũvika ũla mũthenya watwiwe nĩ ĩthe.'),
('kam', 'GAL', 4, 3, 'Naitũ no ta ũu, yĩla twaĩ syana, twalũlũmĩlw’e ũkombonĩ momanyĩsyonĩ ma kwambĩlĩlya ma nthĩ:'),
('kam', 'GAL', 4, 4, 'ĩndĩ wianĩu wa ĩvinda wooka, Ngai atũma Mwana wake, wasyaiwe nĩ mũndũ mũka, wasyaiwe ungu wa ĩla mĩao,'),
('kam', 'GAL', 4, 5, 'nĩ kana amovosye asu ala maĩ ungu wa ĩla mĩao, nĩ kana tũtuwe ana.'),
('kam', 'GAL', 4, 6, 'Na kwa kwĩthĩwa mwĩ ana, Ngai atũmie Veva wa Mwana wake alike ngoonĩ sitũ, akĩtanaa, akyasya, Nau, Asa.'),
('kam', 'GAL', 4, 7, 'Na yu ndwĩ ngombo ĩngĩ, ĩndĩ wĩ mwana; na ethĩwa wĩ mwana, wĩ mũtiĩwa ĩndĩ kwondũ wa Ngai.'),
('kam', 'GAL', 4, 8, 'Ĩndĩ ĩvinda yĩu, kwa kwĩthĩwa mũtyamwĩsĩ Ngai, mwatwĩe mwĩ ngombo sya ngai ila kwa mũtuo wasyo ti ngai:'),
('kam', 'GAL', 4, 9, 'ĩndĩ yu mwamũmanya Ngai, kana kavaa kwasya nĩmwĩsĩkĩwe nĩ Ngai, mũtonya ata kwĩthyũũa na kũsyokea ĩngĩ momanyĩsyo ma kwambĩlĩlya ala monzu na ala mate vata, ala kwondũ wamo nĩmũkwenda kũsyoka ũkombonĩ ĩngĩ?'),
('kam', 'GAL', 4, 10, 'Nĩmũsũvĩaa mĩthenya, na myei, na mavinda, na myaka.'),
('kam', 'GAL', 4, 11, 'Nĩngũkĩa nũndũ wenyu, no kwĩthĩwa nathĩnĩe wĩa kwondũ wenyu mana.'),
('kam', 'GAL', 4, 12, 'Nĩngũmwĩsũva, ana‐a‐asa, ĩthĩwai tondũ nĩilyĩ, nĩkwĩthĩwa nyie nĩilyĩ tondũ inyw’ĩ mũilyĩ. Mũtyaambĩka naĩ:'),
('kam', 'GAL', 4, 13, 'ĩndĩ nĩmwĩsĩ kana nũndũ wa wonzu wa mwĩĩ ĩvinda ya mbee nĩnatavanisye ũvoo mũseo kwenyu:'),
('kam', 'GAL', 4, 14, 'na ũndũ ũla waĩ ũtatwa kwenyu mwĩĩnĩ wakwa mũtyaavũthya, kana kũlea; ĩndĩ mwambosa ta mũlaĩka wa Ngai, o ta Klĩsto Yesũ.'),
('kam', 'GAL', 4, 15, 'Kũĩva ĩndĩ kwĩyĩta aathime? Nũndũ nĩngũmũkũsĩĩa, kana, kethĩwa nĩ ũndũ ũla waĩ ũtonyeka, mwĩthĩwa mwanumĩsye metho menyu mũkanenga.'),
('kam', 'GAL', 4, 16, 'Na ĩndĩ yu nĩtw’ĩkĩte mũmaitha wenyu, nũndũ wa kũmũtavya ũla w’o?'),
('kam', 'GAL', 4, 17, 'Nĩmeũmũmantha na ũthangaau, ĩndĩ ti kwa ũseo; aiee, nĩmekwenda kũmũvingĩa nza, nĩ kana inyw’ĩ mũmamanthe.'),
('kam', 'GAL', 4, 18, 'Ĩndĩ nĩ ũseo kũmanthawa na ũthangaau ũndũnĩ ũseo mavinda onthe, na ti o yĩla nĩ vamwe nenyu.'),
('kam', 'GAL', 4, 19, 'Syana syakwa nini, ĩla ngwaũnyĩa ĩngĩ mũvaka Klĩsto ombĩke nthĩnĩ wenyu,'),
('kam', 'GAL', 4, 20, 'ĩĩ, nenda nĩthĩwe vamwe nenyu oyu, na kũalyũla wasya wakwa; nũndũ nĩngũsaanĩw’a nĩ inyw’ĩ.'),
('kam', 'GAL', 4, 21, 'Ndavyaĩ, inyw’ĩ ala mũkwenda kwĩthĩwa ungu wa mĩao, mũtimĩw’aa ĩla mĩao?'),
('kam', 'GAL', 4, 22, 'Nũndũ nĩkũandĩkĩtwe, kana Avalaamu aĩ na ana elĩ aũme, ũmwe asyaĩtwe nĩ ngombo, na ũngĩ asyaĩtwe nĩ mũndũ mũka ũtaĩ ngombo.'),
('kam', 'GAL', 4, 23, 'Ĩndĩ mwana ũla wasyaiwe nĩ ngombo asyaiwe kwondũ wa mwĩĩ; na mwana ũla wasyaiwe nĩ mũndĩ mũka ũtaĩ ngombo asyaiwe kwondũ wa watho.'),
('kam', 'GAL', 4, 24, 'Maũndũ asu me na ngelekan’yo: nũndũ aka asu nĩ motianĩo elĩ; ũmwe waumie kĩĩmanĩ kya Sinai, ũla ũsyaaa syana sya ũkombo, naw’o nĩ Akali.'),
('kam', 'GAL', 4, 25, 'Na Akali ũsu nĩ kĩĩma kya Sinai kĩla kĩ nthĩ ya Alavu, na kĩvw’anene na Yelusaleme ya ĩvinda yĩĩ: nũndũ ĩ ũkombonĩ vamwe na syana syayo.'),
('kam', 'GAL', 4, 26, 'Ĩndĩ Yelusaleme ĩla yĩ ĩũlũ nĩ nthasye, nayo nĩ inyia waitũ.'),
('kam', 'GAL', 4, 27, 'Nũndũ nĩkũandĩkĩtwe, Tana, we ngũngũ ũtaasyaa; Ũkĩlya wasya ũsĩĩlĩle, we ũla ũtaaũnya: Nũndũ syana sya ũla ũtwĩe e weka nĩ mbingĩ kũte sya ũla wĩ na mũũme.'),
('kam', 'GAL', 4, 28, 'Ĩndĩ ithyĩ, ana‐a‐asa, twĩ syana sya watho, o ta Isaka.'),
('kam', 'GAL', 4, 29, 'Ĩndĩ o ta ĩvinda yĩu, ũla wasyaiwe kwondũ wa mwĩĩ athĩnisye ũsu wasyaiwe kwondũ wa veva, na ĩvinda yĩĩ no ta ũu.'),
('kam', 'GAL', 4, 30, 'Ĩndĩ maandĩko measya ata? Mũlũngye mũndũ mũka ngombo na mwana wake: nũndũ mwana wa ngombo ndakatiĩwa vamwe na mwana wa ũla ũte ngombo.'),
('kam', 'GAL', 4, 31, 'Kwondũ wa ũu, ana‐a‐asa, ithyĩ tũi syana sya ngombo, ĩndĩ twĩ syana sya mũndũ mũka ũte ngombo.'),
('kam', 'GAL', 5, 1, 'Kwa kũthaw’a, Klĩsto nũtũthaĩtye: kwondũ wa ũu ũngamai na ũlũmu, mũikalingisane ĩngĩ kwovwanĩ kwa ũkombo.'),
('kam', 'GAL', 5, 2, 'Sisyai, nyie Vaulo nĩmwĩa, mwaĩkwa, Klĩsto ndakamũuna na ũndũ nongi.'),
('kam', 'GAL', 5, 3, 'Ĩĩ, nĩngũkũsĩĩa ĩngĩ kĩla mũndũ ũla waĩkawa, kana e na thiĩ wa kwĩka ĩla mĩao yonthe.'),
('kam', 'GAL', 5, 4, 'Nĩmũtaanĩtw’e na Klĩsto, inyw’ĩ ala mũkwenda kũtalĩlwa ũlũngalu kwondũ wa ĩla mĩao; nĩmwavalũkĩte kuma mumonĩ.'),
('kam', 'GAL', 5, 5, 'Nũndũ ithyĩ kwondũ wa ũla Veva nĩtweteelaa wĩkwatyo wa ũlũngalu kwa nzĩa ya mũĩkĩĩo.'),
('kam', 'GAL', 5, 6, 'Nũndũ nthĩnĩ wa Klĩsto Yesũ kwaĩkwa kũiaĩlya ũndũ, kana kũlea kwaĩkwa; ĩndĩ mũĩkĩĩo ũla ũtethasya wĩa kwondũ wa wendo.'),
('kam', 'GAL', 5, 7, 'Mwasembete nesa; nũũ ũla wamũsiĩĩe mũikawĩw’e ũla w’o?'),
('kam', 'GAL', 5, 8, 'Kũsesengwa ku kũtyumĩte kwa ũla ũmwĩtaa.'),
('kam', 'GAL', 5, 9, 'Ĩlawa ĩnini nĩyĩkaatasya kĩmũtũ kyonthe.'),
('kam', 'GAL', 5, 10, 'Nĩngũmũĩkĩĩa inyw’ĩ mũno nthĩnĩ wa Mwĩaĩi, kana mũikethĩwa na kĩlilikano kĩngĩ: ĩndĩ ũla ũmũthĩnasya akakua ũsilĩlo wake mwene, o na ethĩwa nũũ.'),
('kam', 'GAL', 5, 11, 'Ĩndĩ nyie, ana‐a‐asa, ethĩwa nĩtavan’ya nzaĩko kũvika o na yu, nĩthĩnĩaw’a kĩ? Ethĩwa ũu nĩ w’o ũlulutĩkyo wa ngelan’yo nũvetetwe.'),
('kam', 'GAL', 5, 12, 'Nenda asu meũmũthingithya maketile e mo ene.'),
('kam', 'GAL', 5, 13, 'Nũndũ inyw’ĩ, ana‐a‐asa, mwetiwe mwĩthĩwe mwĩ athasye; ĩndĩ kũthaw’a kwenyu kũikethĩwe ũthei wa kwendeesya mwĩĩ, ĩndĩ thũkũmanai ene kwa ene kwondũ wa wendo.'),
('kam', 'GAL', 5, 14, 'Nũndũ ĩla mĩao yonthe ĩanĩw’e ndetonĩ ĩmwe, nayo nĩ ĩno: Mwende mũtũi waku o ũndũ wĩyendete mwene.'),
('kam', 'GAL', 5, 15, 'Ĩndĩ ethĩwa nĩmũkũumana na kũĩsana inyw’ĩ kwa inyw’ĩ, ĩsũviei mũikaminane inyw’ĩ kwa inyw’ĩ.'),
('kam', 'GAL', 5, 16, 'Ĩndĩ nĩneena, Kinyaai mũtongoew’e nĩ Veva, na mũikeanĩsya mĩmeo ya mwĩĩ.'),
('kam', 'GAL', 5, 17, 'Nũndũ mwĩĩ nĩwendaa ũkĩlan’ya vinya na ũla Veva, na Veva ũkĩlan’ya na mwĩĩ; nũndũ asu elĩ me na kaũ ene kwa ene; nĩ kana mũikatonye kwĩka maũndũ ala mũkwenda.'),
('kam', 'GAL', 5, 18, 'Ĩndĩ ethĩwa nĩmũtongoeaw’a nĩ Veva, mũi ungu wa mĩao.'),
('kam', 'GAL', 5, 19, 'Na yu mawĩa ma mwĩĩ nĩ moneku, nĩmo aa: ũlaalai, ũvuku, mĩmeo mĩthũku,'),
('kam', 'GAL', 5, 20, 'kũthaitha mĩvw’anano, ũoi, ũmaitha, ĩteta kĩwĩu, mothilĩku, ngananĩo, ũtaanĩsyo, momanyĩsyo ma ũvũngũ,'),
('kam', 'GAL', 5, 21, 'mawendi, ũthengi, mboka itaĩle, na maũndũ angĩ mailyĩ ta asu; kũla kwi maũndũ asu nĩmũtaa mbee, o ũndũ namũtaie, kana ala mekaa maũndũ ta asu maikatiĩwa ũsumbĩ wa Ngai.'),
('kam', 'GAL', 5, 22, 'Ĩndĩ ũsyao wa Veva nĩ wendo, ũtanu, mũuo, wũmĩĩsyo, kwĩka angĩ nesa, ũseo, kĩthito,'),
('kam', 'GAL', 5, 23, 'ũuu, wĩting’o; kũĩ mwĩao kwa maũndũ ala mavw’anene na asu.'),
('kam', 'GAL', 5, 24, 'Na ala ma Klĩsto Yesũ nĩmambĩte mwĩĩ vamwe na mĩmeo na mawendi maw’o.'),
('kam', 'GAL', 5, 25, 'Ethĩwa twĩĩkala thayũ kwondũ wa ũla Veva, o ta ũu tũendae kwondũ wa Veva.'),
('kam', 'GAL', 5, 26, 'Tũikekathĩĩe mana, tũikathatan’ye, na kwĩw’anĩa kĩwĩu.'),
('kam', 'GAL', 6, 1, 'Ana‐a‐asa, o na ethĩwa mũndũ ekwatwa nĩ ĩvĩtyo o na yĩva, inyw’ĩ ala mwĩ ma Veva, mũtũngĩĩei ta ũsu na veva wa ũuu; ũkĩsyaĩĩsya mwene, ndũkatatwe.'),
('kam', 'GAL', 6, 2, 'Kuan’yai mĩio ene kwa ene, na ũu mũkeanĩsya mwĩao wa Klĩsto.'),
('kam', 'GAL', 6, 3, 'Nũndũ ethĩwa mũndũ eĩtalĩlya kwĩthĩwa kĩndũ, nake ti kĩndũ, eĩkenga mwene.'),
('kam', 'GAL', 6, 4, 'Ĩndĩ kĩla mũndũ aosye wĩa wake mwene, na nĩvo ĩndĩ wĩĩthĩwa na ũndũ wa kwĩkathĩĩa e we mwene, na ti kwĩelekan’ya na ũngĩ ũndũ wĩkaa.'),
('kam', 'GAL', 6, 5, 'Kwa kwĩthĩwa kĩla mũndũ akakua mũio wake mwene.'),
('kam', 'GAL', 6, 6, 'Ĩndĩ mũmanyĩw’a wa ĩla ndeto namũaĩe mũmanyĩsya syĩndũ syake syonthe nzeo.'),
('kam', 'GAL', 6, 7, 'Mũikakengeke; Ngai ndavũĩawa ngũĩ: nũndũ o kĩla mũndũ ũvuĩaa, nokyo ũkaketha.'),
('kam', 'GAL', 6, 8, 'Nũndũ ũla ũvuĩĩaa mwĩĩ wake, kwa mwĩĩ wake akaketha wanangĩko; ĩndĩ ũla ũvuĩĩaa ũla Veva, kwa Veva akaketha thayũ ũtathela.'),
('kam', 'GAL', 6, 9, 'Na tũikanoe nĩ kwĩka nesa: nũndũ kyathĩ kyavika tũkaketha, ethĩwa tũileela.'),
('kam', 'GAL', 6, 10, 'Kwondũ wa ũu, o ũndũ twĩĩthĩwa na ũthei, twĩkei andũ onthe nesa, ĩndĩ mũno ala ma nyũmba ya mũĩkĩĩo.'),
('kam', 'GAL', 6, 11, 'Sisyai ũndũ maandĩko manenevete aa ngũmũandĩkĩa na kw’oko kwakwa mwene.'),
('kam', 'GAL', 6, 12, 'Onthe ala mekwenda kwoneka me aseo mwĩĩnĩ, nĩmeũmũthing’ĩĩsya mwaĩkwe; no kana maikathĩnw’e nũndũ wa ngelan’yo ya Klĩsto.'),
('kam', 'GAL', 6, 13, 'Nũndũ o na asu ala maĩkawa nao ene matikwataa ĩla mĩao; ĩndĩ nĩmekwenda inyw’ĩ mwaĩkwe, nĩ kana mone ũndũ wa kwĩkathĩĩa mĩĩnĩ yenyu.'),
('kam', 'GAL', 6, 14, 'Ĩndĩ kũikethĩwe nyie kwĩkathĩĩa, ate o ngelan’yonĩ ya Mwĩaĩi waitũ Yesũ Klĩsto, nayo kwondũ wayo nthĩ nĩyambĩtwe kwakwa, nakwa kwa nthĩ.'),
('kam', 'GAL', 6, 15, 'Nũndũ kwaĩkwa ti ũndũ, o na kũlea kwaĩkwa, ĩndĩ nĩ kyũmbe kyeũ.'),
('kam', 'GAL', 6, 16, 'Na onthe ala makaendaa maatĩĩe kĩeleelo kĩĩ, mũuo nĩwĩthĩwe kwamo, na tei, o na kwa Isilaeli ma Ngai.'),
('kam', 'GAL', 6, 17, 'Kuma yu mũndũ o na wĩva ndakanyamasye; nũndũ nĩngũkua movano ma Yesũ mwĩĩnĩ wakwa.'),
('kam', 'GAL', 6, 18, 'Mumo wa Mwĩaĩi waitũ Yesũ Klĩsto nĩwĩthĩwe vamwe na maveva menyu, ana‐a‐asa. Ameni.'),
('kam', 'EPH', 1, 1, 'Vaulo, mũtũmwa wa Klĩsto Yesũ kwondũ wa kwenda kwa Ngai, valũa ũũ wakwa ũmavikĩe atheu ala me Eveso, na ala me na kĩthito nthĩnĩ wa Klĩsto Yesũ:'),
('kam', 'EPH', 1, 2, 'Mumo nĩwĩthĩwe nenyu na mũuo kuma kwa Ngai Asa waitũ na Mwĩaĩi Yesũ Klĩsto.'),
('kam', 'EPH', 1, 3, 'Nakathwe Ngai, Ĩthe wa Mwĩaĩi waitũ Yesũ Klĩsto, ũla ũtũathimĩte na kĩla ũathimo wa veva nthĩnĩ wa Klĩsto ĩtunĩ:'),
('kam', 'EPH', 1, 4, 'o ũndũ watũnyuvie nthĩnĩ wake nthĩ ĩtanambĩlĩlw’a, nĩ kana twĩthĩwe atheu tũte na ũndũ ũtaĩle mbee wake nthĩnĩ wa wendo:'),
('kam', 'EPH', 1, 5, 'ũndũ watũnyuvie kuma tene tũtuwe ana kwake kwondũ wa Yesũ Klĩsto, kwĩanana na ũndũ wendie na kwenda kwake,'),
('kam', 'EPH', 1, 6, 'nĩ kana ũtheu mũtisu wa mumo wake ũkathwe, ũla watũnengie mana nthĩnĩ wa ũla Mwendwa:'),
('kam', 'EPH', 1, 7, 'nake nthĩnĩ wake twĩ na wovosyo witũ kwondũ wa nthakame yake, ũekeo wa mavĩtyo maitũ, kwĩanana na ũthwii wa mumo wake,'),
('kam', 'EPH', 1, 8, 'naw’o atwingĩvĩsye na ũĩ w’onthe na ũmanyi,'),
('kam', 'EPH', 1, 9, 'akĩtũmanyĩthya nzama ya kwenda kwake, kwĩanana na kwenda kwake kũseo kũla watwie nthĩnĩ wake'),
('kam', 'EPH', 1, 10, 'kũvika walanyonĩ wa wĩanĩu wa mavinda, atũngĩanĩe syĩndũ syonthe nthĩnĩ wa Klĩsto, syĩndũ syi ĩtunĩ, na syĩndũ syĩ kũũ nthĩ; ĩĩ, nthĩnĩ wake we,'),
('kam', 'EPH', 1, 11, 'na ingĩ nthĩnĩ wake ithyĩ nĩtwatwiwe ũtiĩwa wake, nĩkwĩthĩwa nĩtwanyuviwe kuma tene kwĩanana na kwenda kwake we ũla wĩkaa maũndũ onthe kwa ũtw’ĩo wa kwenda kwake;'),
('kam', 'EPH', 1, 12, 'nĩ kana ithyĩ twĩthĩwe ma kũtuma ũtheu wake mũtisu ũkathwa, ithyĩ ala twambie kwĩkwatya Klĩsto;'),
('kam', 'EPH', 1, 13, 'na nthĩnĩ wake o nenyu, mweew’a ndeto ya ũla w’o, nayo nĩ ũvoo mũseo wa ũtangĩĩo wenyu, — nake, mwamwĩtĩkĩla, nĩmwekĩiwe ũsiĩlo, naw’o nĩ Veva Mũtheu ũla wathaniwe,'),
('kam', 'EPH', 1, 14, 'nake nĩ ngwatĩlĩlyo ya ũtiĩwa witũ, kũvika wovosyo wa ala make mwene ala wathooie, nĩ kana ũtheu wake mũtisu ũkathwe.'),
('kam', 'EPH', 1, 15, 'Kwondũ wa ũu o nakwa, neew’a ũvoo wa mũĩkĩĩo ũla mwĩ naw’o nthĩnĩ wa Mwĩaĩi Yesũ, na wendo ũla mwonanasya kwa atheu onthe,'),
('kam', 'EPH', 1, 16, 'ndiekaa kũtũnga mũvea kwondũ wenyu, ngĩmũweta mboyanĩ syakwa;'),
('kam', 'EPH', 1, 17, 'kwa Ngai wa Mwĩaĩi waitũ Yesũ Klĩsto, Asa wa ũtheu mũtisu, amũnenge veva wa ũĩ na ũvuan’yo wa kũmũmanya we;'),
('kam', 'EPH', 1, 18, 'metho ma ngoo syenyu mekĩwe kyeni, nĩ kana mũmanye ũndũ ũilyĩ wĩkwatyo wa wĩtano wake, na ũndũ ũilyĩ wingĩ wa ndaĩa wa ũtiĩwa wake nthĩnĩ wa atheu,'),
('kam', 'EPH', 1, 19, 'na ũndũ ũilyĩ ũnene mũvĩtũku wa vinya wake kwondũ witũ ala twĩtĩkĩlaa, kwĩanana na kwĩka kwa vinya wa ũtonyi wake'),
('kam', 'EPH', 1, 20, 'ũla wekie nthĩnĩ wa Klĩsto, yĩla wamũthayũũkisye kũmumya kwa akw’ũ, na kũmwĩkalya kw’okonĩ kwa aũme kwake kwake ĩtunĩ,'),
('kam', 'EPH', 1, 21, 'ĩũlũ mũno mbee wa ũnene w’onthe, na ũkũmũ, na vinya, na ũsumbĩko, na kĩla syĩtwa yĩwetawa, ti ĩvinda yĩĩ yoka, ĩndĩ o na ĩvinda yĩla yĩkoka:'),
('kam', 'EPH', 1, 22, 'na nĩwaiie syĩndũ syonthe ungu wa nyaĩĩ syake aisumbĩke, na amwia ethĩwe mũtwe ĩũlũ wa maũndũ onthe kwondũ wa ĩkanisa,'),
('kam', 'EPH', 1, 23, 'nayo nĩ mwĩĩ wake, wĩanĩu wake ũla wusũasya maũndũ onthe nthĩnĩ wa onthe.'),
('kam', 'EPH', 2, 1, 'Nake nĩwamũthayũũkisye inyw’ĩ, yĩla mwai akw’ũ kwondũ wa mavĩtyo menyu na naĩ syenyu,'),
('kam', 'EPH', 2, 2, 'ila mwaendie nthĩni wasyoĩvinda ya tene kwĩanana na mĩendele ya nthĩ ĩno, kwĩanana na mũnene wa mavinya ma yayaya, wa veva ũla wĩkaa wĩa yu nthĩnĩ wa ana ma ũlei;'),
('kam', 'EPH', 2, 3, 'o naitũ ithyonthe tene twekalile katĩ woo mĩmeonĩ ya mĩĩ yaitũ, tũkĩka mawendi ma mĩĩ na ma mosũanĩo, na nũndu wa mwĩkalĩle witũ twaĩ syana sya ũthatu, o ta ala angĩ:—'),
('kam', 'EPH', 2, 4, 'ĩndĩ Ngai, nĩkwĩthĩwa aĩ na tei mwingĩ, nũndũ wa wendo wake mũnene ũla watwendie naw’o,'),
('kam', 'EPH', 2, 5, 'o na yĩla twaĩ akw’ũ kwondũ wa mavĩtyo maitũ, atũnengie thayũ vamwe na Klĩsto (nĩmũtangĩĩĩtwe nĩ mumo),'),
('kam', 'EPH', 2, 6, 'naitũ nthĩnĩ wa Klĩsto Yesũ nĩwatũthayũũkisye vamwe nake, na kũtwĩkalya nthĩ vamwe nake ĩtunĩ:'),
('kam', 'EPH', 2, 7, 'nĩ kana mavinda ala mokĩte atonye kwonan’ya ũthwii mwingĩ wa mumo wake kwondũ wa ũseo wake kwitũ nthĩnĩ wa Klĩsto Yesũ:'),
('kam', 'EPH', 2, 8, 'nũndũ nĩmũtangĩĩĩtwe na mumo kwondũ wa mũĩkĩĩo; naw’o ndumĩte kwa inyw’ĩ ene, nĩ mũthĩnzĩo wa Ngai;'),
('kam', 'EPH', 2, 9, 'ti ũndũ wa meko, kana kũikethĩwe mũndũ o na wĩva kwĩkathĩĩa.'),
('kam', 'EPH', 2, 10, 'Nũndũ ithyĩ twĩ wĩa wake, twombiwe nthĩnĩ wa Klĩsto Yesũ twĩkae meko maseo, ala Ngai waseũvisye mbee nĩ kana tũendae nthĩnĩ wamo.'),
('kam', 'EPH', 2, 11, 'Kwondũ wa ũu lilikanai, kana ĩvinda ya tene inyw’ĩ, Andũ‐ma‐mbaĩ‐ingĩ kwa mwĩĩ, ala mwĩtawa Mũtaĩkawa nĩ ala metawa Maĩkawa, nayo nĩ nzaĩko ya mwĩĩ, ĩla yaĩkawa na moko;'),
('kam', 'EPH', 2, 12, 'kana inyw’ĩ ĩvinda yĩu mũtyaĩ na Klĩsto, mwavathũkenw’e na mbaĩ ya Isilaeli, na mwaĩ aeni, andũ mate na motianĩo ma ũla watho, mũtaĩ na wĩkwatyo na mũtaĩ na Ngai kũũ nthĩ.'),
('kam', 'EPH', 2, 13, 'Ĩndĩ yu nthĩnĩ wa Klĩsto Yesũ inyw’ĩ ala mwaĩ kũasa nĩmũthengeew’e nĩ nthakame ya Klĩsto.'),
('kam', 'EPH', 2, 14, 'Nũndũ nĩwe mũuo witũ, ũla watumie ithyelĩ tũtw’ika ũmwe, na nĩwaomboie ũvai wa mũvaka ũla waĩ katĩ,'),
('kam', 'EPH', 2, 15, 'avetete na mwĩĩ wake ũla ũmaitha, naw’o nĩ ĩla mĩao ya wiaĩi yaandĩkĩtwe motw’ĩonĩ; nĩ kana ombe wa asu elĩ mũndũ ũmwe mweũ nthĩnĩ wake mwene, na kwondũ wa ũu aete mũuo;'),
('kam', 'EPH', 2, 16, 'na nĩ kana amew’anĩthye na Ngai me elĩ mwĩĩnĩ ũmwe kwondũ wa ngelan’yo, oaĩte ũla ũmaitha nayo:'),
('kam', 'EPH', 2, 17, 'nake ooka na atavan’ya ũvoo mũseo wa mũuo kwa inyw’ĩ ala mwaĩ kũasa, na mũuo kwa ala maĩ vakuvĩ:'),
('kam', 'EPH', 2, 18, 'nũndũ kwondũ wake ithyelĩ twĩ na ũthei witũ wa kũthengeea mbee wa Asa nthĩnĩ wa Veva ũmwe.'),
('kam', 'EPH', 2, 19, 'Na kwondũ wa ũu mũti aeni na avĩti ĩngĩ, ĩndĩ mwĩ andũ ma kĩĩndĩ vamwe na atheu, na andũ ma nyũmba ya Ngai,'),
('kam', 'EPH', 2, 20, 'nũndũ nĩmwakĩtwe ĩũlũ wa wambĩlĩlyo, naw’o nĩ atũmwa na athani, Klĩsto Yesũ mwene nĩwe yĩla ĩvia ĩnene ya kĩkotonĩ;'),
('kam', 'EPH', 2, 21, 'na nthĩnĩ wake kĩla wako, ũithalanw’a nesa, nĩwĩanaa ũkethĩwa ĩkalũ nthĩnĩ wa Mwĩaĩi;'),
('kam', 'EPH', 2, 22, 'na nthĩnĩ wake nĩmwakĩtwe vamwe mwĩthĩwe wĩkalo wa Ngai nthĩnĩ wa Veva.'),
('kam', 'EPH', 3, 1, 'Kwondũ wa ũu nyie Vaulo, mwovwa wa Klĩsto Yesũ kwondũ wenyu Andũ‐ma‐mbaĩ‐ingĩ,—'),
('kam', 'EPH', 3, 2, 'ethĩwa nĩmwĩw’ĩte ũvoo wa walan’yo wa mumo wa Ngai ũla nanengiwe kwondũ wenyu;'),
('kam', 'EPH', 3, 3, 'kana kwondũ wa kũvuanĩw’a nĩnamanyĩthiw’e ĩla nzama, o tondũ nambie kũandĩka na ndeto mbũthũ,'),
('kam', 'EPH', 3, 4, 'na kwondũ wa ũu, yĩla mũũsoma, mũkoona ũmanyi wakwa wa ĩla nzama ya Klĩsto;'),
('kam', 'EPH', 3, 5, 'nayo ndyaamanyĩthw’a ana ma andũ ma nzyawa ĩngĩ, o ũndũ atũmwa make atheu na athani mavuanĩw’e yu nthĩnĩ wa Veva;'),
('kam', 'EPH', 3, 6, 'atĩ Andũ‐ma‐mbaĩ‐ingĩ nĩ atiĩwa vamwe naitũ, na mamutha ma ũla mwĩĩ vamwe naitũ, na osi vamwe naitũ ma watho ũla wĩ nthĩnĩ wa Klĩsto Yesũ kwondũ wa ũvoo mũseo,'),
('kam', 'EPH', 3, 7, 'ũla nyie natwiwe mũthũkũmi waw’o, kwĩanana na mũthĩnzĩo wa mumo wa Ngai ũla nanengiwe kwĩanana wa kwĩka kwa vinya wake.'),
('kam', 'EPH', 3, 8, 'Nyie ũla nĩ mũnini kwĩ ũla mũnini mbee kati wa atheu onthe, nĩnanengiwe mumo ũũ, kũtavan’ya kwa Andũ‐ma‐mbaĩ‐ingĩ ũthwii wa Klĩsto ũla ũtatalĩka;'),
('kam', 'EPH', 3, 9, 'na kũtuma andũ onthe mamanya ũndũ ũilyĩ ũla walan’yo wa nzama ĩla kuma tene tene yavithiwe nthĩnĩ wa Ngai ũla wombie syĩndũ syonthe;'),
('kam', 'EPH', 3, 10, 'nĩ kana yu kwa nzĩa ya ĩkanisa, ũĩ wa Ngai wa mĩthemba mingĩ ũmanyĩke kwa monene na mokũmũ ma ĩtunĩ,'),
('kam', 'EPH', 3, 11, 'kwĩanana na ũtw’ĩo wa tene na tene ũla watwie nthĩnĩ wa Klĩsto Yesũ Mwĩaĩi waitũ:'),
('kam', 'EPH', 3, 12, 'na nthĩnĩ wake twĩ na ũkũmbaũ na ũthei wa kũthengeea na wĩkwatyo, kwondũ wa mũĩkĩĩo witũ nthĩnĩ wake.'),
('kam', 'EPH', 3, 13, 'Kwondũ wa ũu nĩngũmwĩsũva mũikaleele nũndũ wa mathĩna makwa kwondũ wenyu, namo nĩ ũtaĩo wenyu.'),
('kam', 'EPH', 3, 14, 'Kwondũ wa ũu nĩtulya ndu mbee wa Asa,'),
('kam', 'EPH', 3, 15, 'o ũla mĩvĩa yonthe ya ĩtunĩ na ya nthĩ nĩyĩtanĩawa nake.'),
('kam', 'EPH', 3, 16, 'Nĩ kana amũnenge inyw’ĩ, kwĩanana na wingi wa ndaĩa yake, kana mwongeleelwe vinya mũndũ wa nthĩnĩ kwondũ wa Veva wake;'),
('kam', 'EPH', 3, 17, 'nĩ kana Klĩsto ekalae ngoonĩ syenyu kwondũ wa mũĩkĩĩo; nĩ kana inyw’ĩ mũtambũũkĩtye mĩi na kũlũlũmĩlw’a nthĩnĩ wa wendo.'),
('kam', 'EPH', 3, 18, 'Mwĩthĩwe na vinya wa ũkwata vamwe na atheu onthe ũndũ ũilyĩ ũthanthau na ũasa na ũtũlu na ũliku,'),
('kam', 'EPH', 3, 19, 'na kũmanya wendo wa Klĩsto ũla ũvĩtũkĩte ũmanyi, nĩ kana mũtonye kusũwa kũvikĩa wusũu w’onthe wa Ngai.'),
('kam', 'EPH', 3, 20, 'Na yu we ũla ũtonya kwĩka mũno mbee kũvĩta onthe ala tũvoyaa kana kũlilikana, kwĩanana na vinya ũla wĩkaa nthĩnĩ waitũ,'),
('kam', 'EPH', 3, 21, 'ndaĩa nĩyĩthĩwe yake ĩkanisanĩ na nthĩnĩ wa Klĩsto Yesũ nzyawanĩ syonthe tene na tene. Ameni.'),
('kam', 'EPH', 4, 1, 'Na kwondũ wa ũu nyie, mwovwa nthĩnĩ wa Mwĩaĩi, nĩngũmwĩsũva mũendae o ũndũ waĩle wĩtano ũla mweetiwe naw’o,'),
('kam', 'EPH', 4, 2, 'na wĩnyivyo w’onthe na ũuu, na wũmĩĩsyo, mũkyũmĩanĩsya inyw’ĩ kwa inyw’ĩ nthĩnĩ wa wendo;'),
('kam', 'EPH', 4, 3, 'mũkĩthing’ĩĩsya kũsũvĩa wĩw’ano ũmwe wa Veva wovanonĩ wa mũuo.'),
('kam', 'EPH', 4, 4, 'Mwĩĩ nĩ ũmwe, na Veva nĩ ũmwe, o ũndũ mweetiwe wĩkwatyonĩ ũmwe wa wĩtano wenyu;'),
('kam', 'EPH', 4, 5, 'Mwĩaĩi ũmwe, mũĩkĩĩo ũmwe, ũvatiso ũmwe,'),
('kam', 'EPH', 4, 6, 'Ngai ũmwe, nake ni Ĩthe wa onthe, ũla wĩ ĩũlũ wa onthe, na kũtũngana kwa onthe, na nthĩni wa onthe.'),
('kam', 'EPH', 4, 7, 'Ĩndĩ kĩla ũmwe waitũ nũnengetwe ũla mumo kwĩanana na kĩthimo kya mũthĩnzio wa Klĩsto.'),
('kam', 'EPH', 4, 8, 'Kwondũ wa ũu easya, Yĩla wambatie ĩũlũ, nĩwatavie mũtavo, Na anenga andũ mĩthĩnzĩo.'),
('kam', 'EPH', 4, 9, '(Na ndeto ĩno, Nĩwambatie, nata ate o kwasya kana nĩwatheeie alike kũndũ kũliku kwa nthĩ?'),
('kam', 'EPH', 4, 10, 'Ũla watheeie niwe ũsu wambatie ĩũlũ mũno mbee wa matu onthe, nĩ kana ausũsye syĩndũ syonthe.)'),
('kam', 'EPH', 4, 11, 'Nake anengie andũ amwe methĩwe atũmwa; na angĩ, athani; na angĩ, atavan’ya ma ũla ũvoo mũseo; na angi, aĩthi, na amanyisya;'),
('kam', 'EPH', 4, 12, 'nĩ kana atheu meanĩwe, ũndũ wa wĩa wa kũthũkũma, nĩ kana mwĩĩ wa Klĩsto wakwe:'),
('kam', 'EPH', 4, 13, 'mũvaka ithyonthe tũvikĩe wĩw’ano ũmwe wa mũĩkĩĩo, na wa kũmũmanya Mwana wa Ngai, kũvikĩa mũndũ mwĩanĩu, kũvikĩa kĩthimo kya ũtũlu wa wĩanĩu wa Klĩsto;'),
('kam', 'EPH', 4, 14, 'nĩ kana kuma yu tũikethĩwe syana nini, tũkĩluutangwa kũũ na kũũ na kũkuwa nĩ kĩla kĩseve kya ũmanyĩsyo, na maũĩ ma andũ, na ũsesengano, kũatĩĩa nzĩa ya ũkengani wa kwasya andũ;'),
('kam', 'EPH', 4, 15, 'ĩndĩ tũkĩneena w’o nthĩnĩ wa wendo, twĩane maũndũnĩ onthe tũmũvikie we, nake nĩwe mũtwe, Klĩsto;'),
('kam', 'EPH', 4, 16, 'na kuma kwake mwĩĩ w’onthe, ũikomanw’a nesa na kũkwatanw’a, nĩwĩanaa nũndũ wa ũtethyo wa kĩla ũleenyũ, kwĩanana na kĩthimo kya wĩa wa kĩla mutha, ũmwe na ũmwe, ũkiyaka e w’o wendonĩ.'),
('kam', 'EPH', 4, 17, 'Na ĩndĩ nĩneena ũu, na kũkũsĩĩa nthĩnĩ wa Mwĩaĩi, kana kuma yu inyw’ĩ mũikaende ũndũ Andũ‐ma‐mbaĩ‐ingĩ maendaa, na ũtumanu wa ilĩko syoo,'),
('kam', 'EPH', 4, 18, 'nũndũ ũmanyi woo nĩwĩkĩĩtwe kĩvindu, mavathĩtwe kũasa na thayũ wa Ngai, nũndũ wa kũlea kũmanya kũla kwĩ nthĩnĩ woo, nũndũ wa wũmũ wa ngoo syoo;'),
('kam', 'EPH', 4, 19, 'nao mavĩtũkĩte kwĩw’a, meenenganie mĩmeonĩ mĩthũku, meke ũvuku w’onthe na wendi.'),
('kam', 'EPH', 4, 20, 'Ĩndĩ inyw’ĩ tiw’o mweemanyĩsye Klĩsto;'),
('kam', 'EPH', 4, 21, 'ethĩwa nĩw’o nĩmwamwĩwie, na kũmanyĩw’a nthĩnĩ wake, o ũndũ w’o ũilyĩ nthĩnĩ wa Yesũ:'),
('kam', 'EPH', 4, 22, 'ũndũ wa mwĩkalĩle wenyu wa tene, mumyei mwĩkye kũasa mũndũ wa tene, ũla wanangĩkaa kwa ũvikĩlaa mĩmeo ya ũkengani;'),
('kam', 'EPH', 4, 23, 'mũtw’ĩkithw’e eũ vevani wa ilĩko syenyu.'),
('kam', 'EPH', 4, 24, 'Na mwĩvw’ĩke mũndũ mweũ, ũla wombiwe na mũvw’ano wa Ngai nthĩnĩ wa ũlũngalu na ũtheu wa w’o.'),
('kam', 'EPH', 4, 25, 'Kwondũ wa ũu, mũkĩveta ũvũngũ, neenai w’o kila mũndũ na ũla ũngĩ: nĩkwĩthiwa twĩ mamutha ene kwa ene.'),
('kam', 'EPH', 4, 26, 'Thatai, na mũikeke naĩ: mũikaeke syũa vĩthũe mwi na ũthilĩku:'),
('kam', 'EPH', 4, 27, 'o na mũikamũnenge Satani ũthei.'),
('kam', 'EPH', 4, 28, 'Ũla woyie ndakoye ingi: ĩndĩ kavaa atethye wĩa, akĩkaa na moko make ũndũ waĩlĩte, ni kana ethĩwe na kĩndũ kya ũmũnenga ũla wi na vata.'),
('kam', 'EPH', 4, 29, 'Ndeto nthũku itikaume makanyw’anĩ menyu, ĩndĩ no ila nzeo sya kwaka o ũndũ vata wĩana, nĩ kana imanenge mumo ala mekwiw’a.'),
('kam', 'EPH', 4, 30, 'Na mũikew’ĩthye Veva Mũtheu wa Ngai woo, nake nthĩnĩ wake mwĩkĩĩtwe ũsiĩlo kũvika mũthenya wa wovosyo.'),
('kam', 'EPH', 4, 31, 'Ĩndĩ ũũ, na ũthilĩku, na ũthatu, na ĩteta, na moumano, mavetwe kwenyu, vamwe na kĩla ũthũku:'),
('kam', 'EPH', 4, 32, 'na mwĩthĩwe mũkyaĩlan’ya ene kwa ene, mũkĩw’anĩa tei, mũkĩekanĩa inyw’ĩ kwa inyw’ĩ, o ũndũ Ngai nake wamũekeie inyw’ĩ nthĩnĩ wa Klĩsto.'),
('kam', 'EPH', 5, 1, 'Nũndũ wa ũu, ĩthĩwai mũkĩelekan’ya na Ngai, ta twana twendetwe;'),
('kam', 'EPH', 5, 2, 'na mũkĩendaa nthinĩ wa wendo, o ũndũ Klĩsto nake wamwendie inyw’ĩ, na eeyumya mwene kwondũ witũ, mũthĩnzĩo na nthembo kwa Ngai, yi na mũuke mũseo.'),
('kam', 'EPH', 5, 3, 'Ĩndĩ ũlaalai, na ũvuku w’onthe, na wendi, maikawetwe kati wenyu, o ũndũ kwaĩle atheu;'),
('kam', 'EPH', 5, 4, 'o na ũla wĩ nthoni, o na kũneena na ũtumanu, kana kũvũa ngũĩ, maũndũ asu mataĩle: ĩndĩ kavaa ni kũtũnga mũvea.'),
('kam', 'EPH', 5, 5, 'Nũndũ nĩmwĩsĩ ũũ vyũ, atĩ kĩlaalai, kana mũndũ mũvuku, kana mũndũ wĩ na wendi, nake ni mũthaithi wa mĩvw’anano, asu mati na ũtiĩwa o na wiva ũsumbĩnĩ wa Klĩsto na Ngai.'),
('kam', 'EPH', 5, 6, 'Mũndũ ndakamũkenge na ndeto sya mana: nũndũ kwondũ wa maũndũ aa ũthatu wa Ngai nũmokiaa ana ma ũlei.'),
('kam', 'EPH', 5, 7, 'Mũikethĩwe mwĩ mũamba nao;'),
('kam', 'EPH', 5, 8, 'nũndũ inyw’ĩ tene mwai kĩvindu, ĩndĩ yu mwĩ kyeni nthĩni wa Mwĩaĩi: endaai ta syana sya kyeni'),
('kam', 'EPH', 5, 9, '(nũndũ ũsyao wa kyeni wĩ nthĩnĩ wa ũseo w’onthe na ũlũngalu na w’o),'),
('kam', 'EPH', 5, 10, 'mũkĩthima maũndũ ala mamwendeeasya Mwĩaĩi;'),
('kam', 'EPH', 5, 11, 'na mũikethĩwe na mũamba na mawĩa ma kĩvindu mate na ũsyao, ĩndĩ kavaa nĩ kũmakan’ya;'),
('kam', 'EPH', 5, 12, 'nũndũ maũndũ ala mekawa nĩmo kĩmbithĩ nĩ nthoni o na kũmaweta.'),
('kam', 'EPH', 5, 13, 'Ĩndĩ maũndũ onthe makanw’a nĩmonananw’a nĩ kyeni: nũndũ kĩla ũndũ wonanĩtw’e no kyeni.'),
('kam', 'EPH', 5, 14, 'Kwondũ wa ũu easya, Amũka, we ũla ũkomete, noithayũũka kuma kwa akw’ũ, na Klĩsto akakũtisĩa.'),
('kam', 'EPH', 5, 15, 'Ĩsũvĩei ĩndĩ nesa ũndũ mũendaa, ti ta ala mate na ũĩ, ĩndĩ ta ala oĩ;'),
('kam', 'EPH', 5, 16, 'mũkĩtangĩĩa ĩvinda, nĩkwĩthĩwa mĩthenya nĩ myathe.'),
('kam', 'EPH', 5, 17, 'Kwondũ wa ũu mũikethĩwe atumanu, ĩndĩ manyai kwenda kwa Mwĩaĩi ũndũ kũilyĩ.'),
('kam', 'EPH', 5, 18, 'Na mũikatoonw’e nĩ mbinyu, nayo ĩ mĩkwa mĩthũku, ĩndĩ usũwai nĩ Veva;'),
('kam', 'EPH', 5, 19, 'mũkĩneena ene kwa ene na savuli na mbathi sya kũmũkumya Ngai na mbathi sya veva, mũkĩmwinĩa Mwĩaĩi na kũmũtaia ngoonĩ syenyu;'),
('kam', 'EPH', 5, 20, 'mũkĩmũtũngĩa Ngai Asa mũvea, mavinda onthe kwondũ wa maũndũ onthe, syĩtwanĩ ya Mwĩaĩi waitũ Yesũ Klĩsto;'),
('kam', 'EPH', 5, 21, 'mũkĩnyivanĩsya ene kwa ene nũndũ wa kũmũkĩa Klĩsto.'),
('kam', 'EPH', 5, 22, 'Inyw’i iveti, ĩnyivĩsyei aũme menyu ta mwinyivĩsye Mwĩaĩi.'),
('kam', 'EPH', 5, 23, 'Nũndũ mũndũ mũũme nĩ mũtwe wa kĩveti, o tondũ Klĩsto nake nĩ mũtwe wa ikanisa, nake nĩ mũtangĩĩi wa mwĩĩ.'),
('kam', 'EPH', 5, 24, 'Ĩndĩ o ũndũ ikanisa yimwinyivĩasya Klĩsto, o ta ũu iveti nasyo nĩsyinyiviasye aũme masyo maũndũni onthe.'),
('kam', 'EPH', 5, 25, 'Aũme, endai iveti syenyu, o ũndũ Klĩsto wendie ĩkanisa, na enengane mwene kwondũ wayo;'),
('kam', 'EPH', 5, 26, 'nĩ kana ayĩvathan’ye, ayĩtheetye ũndũ wa kũthambya na manzĩ nthinĩ wa ndeto,'),
('kam', 'EPH', 5, 27, 'nĩ kana atonye kwĩnenga mwene ĩkanisa ĩtaie, yĩte na ilanga kana ũkũnzanu kana ũndũ ũngĩ ta asu; ĩndĩ nĩ kana yĩthĩwe itheu yĩte na ũndũ ũtaĩle.'),
('kam', 'EPH', 5, 28, 'O ta ũu aũme namo nĩmaĩlwe nĩ kũsyenda iveti syoo o ũndũ mendete mĩĩ yoo ene. Ũla wendaa kĩveti kyake eyendaa mwene:'),
('kam', 'EPH', 5, 29, 'nũndũ vai mũndũ waamena mwĩĩ wake o na ĩndĩĩ; ĩndi nĩwũnengae lĩu na kũũsũvĩa, o tondũ Klĩsto ũyĩsũvĩaa ikanisa;'),
('kam', 'EPH', 5, 30, 'nũndũ twĩ mamutha ma mwĩĩ wake.'),
('kam', 'EPH', 5, 31, 'Kwondũ wa ũu mũndũ akatia ĩthe na inyia, na akalũman’ya na kĩveti kyake; na me elĩ makatw’ĩka mwĩĩ ũmwe.'),
('kam', 'EPH', 5, 32, 'Nzama ino nĩ nene: ĩndĩ nĩneena ũvoo wa Klĩsto na ĩkanisa.'),
('kam', 'EPH', 5, 33, 'Ĩndĩ kĩla mũndũ wenyu nakyende kĩveti kyake o ũndũ wĩyendete mwene; na kĩveti nĩkĩmũkĩe mũũme.'),
('kam', 'EPH', 6, 1, 'Syana, mew’ei ala mamũsyaie nthĩnĩ wa Mwĩaĩi: nũndũ ũu nĩw’o waĩle.'),
('kam', 'EPH', 6, 2, 'Taĩa au na mwenyu (naw’o nĩ mwĩao wa mbee wĩ na watho),'),
('kam', 'EPH', 6, 3, 'nĩ kana kwĩthĩwe ũseo kwaku, na wĩkale mũno kũũ nthĩ.'),
('kam', 'EPH', 6, 4, 'Na, inyw’ĩ aaĩthe, mũikathatye syana syenyu: ĩndĩ ieei na mosilĩlo na motao ma Mwĩaĩi.'),
('kam', 'EPH', 6, 5, 'Ngombo, mew’ei mavwana menyu kwondũ wa mwĩĩ, na w’ĩa na kũtetema, na ũthalĩku wa ngoo syenyu, ta kũmwĩw’a Klĩsto;'),
('kam', 'EPH', 6, 6, 'ti kwa ũthũkũmi wa kũsyaĩĩw’a, ta endeesya ma andũ; ĩndĩ ta ngombo sya Klĩsto, mũkĩka na ngoo ũndũ wendetwe nĩ Ngai;'),
('kam', 'EPH', 6, 7, 'mũkĩthũkũma na kwenda kũseo, ta mũũthũkũma Mwĩaĩi, na ti andũ:'),
('kam', 'EPH', 6, 8, 'mũkĩmanya kana ũndũ ũseo o na wĩva ũla mũndũ wĩkaa, akoosa o w’o ĩngi kuma kwa Mwĩaĩi, e ngombo, kana ate ngombo.'),
('kam', 'EPH', 6, 9, 'Na inyw’ĩ mavwana, mekei maũndũ o asu, na ekai kũmakandĩa: mũkĩmanya kana Vwana woo, nowe wenyu, e ĩtunĩ, na kwake kũi wendeesyo wa andũ.'),
('kam', 'EPH', 6, 10, 'Kũminũkĩlya, ithiwai na vinya nthĩnĩ wa Mwĩaĩi, na vinyani wa ũtonyi wake.'),
('kam', 'EPH', 6, 11, 'Ĩkĩai mĩio yonthe ya kaũ ya Ngai, nĩ kana mũtonye kũsiĩĩa maũĩ ma Satani.'),
('kam', 'EPH', 6, 12, 'Nũndũ kũkĩlan’ya vinya kwitũ ti kũkĩlan’ya na mwĩĩ na nthakame, ĩndĩ ni kũkĩlan’ya na monene, na mokũmũ, na ala masumbĩkĩte kĩvindunĩ kĩĩ, na nguthu sya maveva ma ũthũku ĩtunĩ.'),
('kam', 'EPH', 6, 13, 'Kwondũ wa ũu osai mĩio yonthe ya kaũ ya Ngai, nĩ kana mũtonye kũkĩlya vinya mũthenya ũla mũthũku, na, mweeka ũu w’onthe, kũũngama.'),
('kam', 'EPH', 6, 14, 'Ũngamai ĩndĩ, mwĩvotoete inyunyunĩ syenyu na w’o, na mwĩkĩĩte ngao ya kĩthũi ya ũlũngalu,'),
('kam', 'EPH', 6, 15, 'na maũũnĩ menyu mwĩkĩĩte iatũ sya kwĩyũmban’ya sya ũvoo mũseo wa mũuo;'),
('kam', 'EPH', 6, 16, 'na vamwe na mĩio ĩsu yonthe mũkyosa ngao ya mũĩkĩĩo, ĩla kwondũ wayo mũkatonya kũvosya mĩsyĩ yonthe yĩ na mwaki ya ũla mũthũku.'),
('kam', 'EPH', 6, 17, 'Na osai ngovia ya ũtangĩĩo, na ũvyũ wa Veva, naw’o nĩ ndeto ya Ngai:'),
('kam', 'EPH', 6, 18, 'mũkĩvoya nthĩnĩ wa Veva mavinda onthe na mboya syonthe na kwĩsũva, na mũkĩsyaĩisya ũndũni ũsu na kĩthing’ĩĩsyo na kwĩsũvana kw’onthe kwondũ wa atheu onthe,'),
('kam', 'EPH', 6, 19, 'na kwondũ wakwa nyie, nĩ kana nĩnengwe kũneena, nathamye kanyw’a wakwa na ũkũmbaũ, nonan’ye nzama ya ũvoo mũseo,'),
('kam', 'EPH', 6, 20, 'ũla kwondũ waw’o nĩ mũtũmwa mĩnyololonĩ; nĩ kana nthĩnĩ waw’o nĩneene na ũkũmbaũ, o ũndũ naĩlwe nĩ kũneena.'),
('kam', 'EPH', 6, 21, 'Ĩndĩ nĩ kana nenyu mũmanye maũndũ makwa, ũndũ ndilyĩ, Tikiko, ũla mwana‐a‐asa mwendwa, na mũthũkũmi wĩ kĩthito nthinĩ wa Mwĩaĩi, akamũtavya maũndũ onthe:'),
('kam', 'EPH', 6, 22, 'ũla nĩmũtũmĩte kwenyu kwondũ wa kĩtumi kĩĩ, kana mũmanye ũndũ tũilyĩ, na nĩ kana akiakisye ngoo syenyu.'),
('kam', 'EPH', 6, 23, 'Mũuo nĩwĩthĩwe na ana‐a‐asa, na wendo vamwe na mũĩkĩĩo, kuma kwa Ngai Asa na Mwĩaĩi Yesũ Klĩsto.'),
('kam', 'EPH', 6, 24, 'Mumo nĩwĩthĩwe na onthe ala mamwendaa Mwĩaĩi waitũ Yesũ Klĩsto na wendo ũtanangĩkaa.'),
('kam', 'PHP', 1, 1, 'Vaulo na Timotheo, ngombo sya Klĩsto Yesũ, valũa ũũ witũ ũmavikĩe atheu onthe nthĩnĩ wa Klĩsto Yesũ ala me Vilivi, vamwe na asyaĩĩsya na athũkũmi:'),
('kam', 'PHP', 1, 2, 'Mumo nĩwĩthĩwe nenyu na mũuo kuma kwa Ngai Asa waitũ na Mwĩaĩi Yesũ Klĩsto.'),
('kam', 'PHP', 1, 3, 'Nĩmũtũngĩa Ngai wakwa mũvea o yĩla ngũmũlilikana,'),
('kam', 'PHP', 1, 4, 'mavinda onthe kwĩsũvananĩ kwakwa kw’onthe kwondũ wenyu inyw’onthe ngĩsũvana na ũtanu,'),
('kam', 'PHP', 1, 5, 'nũndũ wa mũamba wenyu nthĩnĩ wa kũnyaĩĩkya ũla ũvoo mũseo, kuma mũthenya wa mbee kũvika o na yu;'),
('kam', 'PHP', 1, 6, 'nĩnĩsĩ vyũ ũndũ ũũ, kana we ũla wambĩlĩlye wĩa mũseo nthĩnĩ wenyu akawĩanĩsya kũvika mũthenya wa Yesũ Klĩsto:'),
('kam', 'PHP', 1, 7, 'o ũndũ kwaĩlĩte kwakwa kũlilikana ũu kwondũ wenyu ĩinyw’onthe, nĩkwĩthĩwa mwĩ ngoonĩ yakwa, nũndũ inyw’onthe mwĩ osi ma mumo vamwe nakwa, kwovwanĩ kwakwa, o na nthĩnĩ wa kũwũkitĩa na kũlũlũmĩlya ũla ũvoo mũseo.'),
('kam', 'PHP', 1, 8, 'Nũndũ Ngai nĩ ngũsĩ yakwa, ũndũ nĩmwendaa inyw’onthe na matei mololo ma Klĩsto Yesũ.'),
('kam', 'PHP', 1, 9, 'ũũ nĩw’o nĩvoyaa, kana wendo wenyu wingĩve mũno mbee nthĩnĩ wa ũmanyi na ũĩ w’onthe;'),
('kam', 'PHP', 1, 10, 'nĩ kana mũmetĩkĩle maũndũ ala maseo mbee; nĩ kana mwĩthĩwe ma w’o na mũte na molulutĩkyo kũvika mũthenya wa Klĩsto;'),
('kam', 'PHP', 1, 11, 'mũkyusũwa nĩ mosyao ma ũlũngalu, ala me kwondũ wa Yesũ Klĩsto, nĩ kana Ngai ataĩwe na akathwe.'),
('kam', 'PHP', 1, 12, 'Ĩndĩ, ana‐a‐asa, nĩngwenda mũmanye, kana maũndũ ala mangwatie nĩmo matumĩte ũla ũvoo mũseo ũendeea na mbee;'),
('kam', 'PHP', 1, 13, 'ũkethĩa o na kwovwa kwakwa nĩkũmanyĩkĩte vyũ nĩ asikalĩ onthe ala masũvĩaa nyũmba ya mũsumbĩ, na ala angĩ onthe, kana nĩ kwondũ wa Klĩsto;'),
('kam', 'PHP', 1, 14, 'na vakuvĩ onthe ma ana‐a‐asa nthĩnĩ wa Mwĩaĩi, makyongelwa vinya kwondũ wa kwovwa kwakwa, me na ũkũmbaũ mũno wa kũneena ndeto ya Ngai vate w’ĩa.'),
('kam', 'PHP', 1, 15, 'Amwe nĩ w’o memũtavan’ya Klĩsto nũndũ wa kĩwĩu na motetan’yo; na angĩ nao kwondũ wa kwenda kũseo:'),
('kam', 'PHP', 1, 16, 'amwe mekaa ũu kwondũ wa wendo, makĩmanya kana niĩtwe kwondũ wa kũwũkitĩa ũla ũvoo mũseo:'),
('kam', 'PHP', 1, 17, 'ĩndĩ asu angĩ memũtavan’ya Klĩsto na ngananĩo, na ti ũndũ wa w’o, makĩsũanĩa kũmbũkĩlĩlya thĩna kwovwanĩ kwakwa.'),
('kam', 'PHP', 1, 18, 'Nata ĩndĩ? Ate o nzĩanĩ syonthe, ethĩwa nĩ nthĩnĩ wa wangangan’yo kana nĩ nthĩnĩ wa w’o, Klĩsto nũtavanaw’a; na kwondũ wa ũu nĩngũtana, ĩĩ, na ngatana.'),
('kam', 'PHP', 1, 19, 'Nũndũ nĩnĩsĩ kana ũndũ ũũ ũkangalyũkĩla kwĩthĩwa nĩ ũtangĩĩo wakwa, ũndũ wa kũvoya kwenyu na kũtethw’a nĩ Veva wa Yesũ Klĩsto,'),
('kam', 'PHP', 1, 20, 'kwĩanana na kũsyaĩĩsya mũno na kwĩkwatya kwakwa, kana ũndũnĩ o na wĩva ndikasonokw’a, ĩndĩ na ũkũmbaũ w’onthe, ta mavinda onthe, no ta ũu yu Klĩsto akanenevw’a mwĩĩnĩ wakwa, ethĩwa nĩ kwĩkala na thayũ, kana nĩ kũkw’a.'),
('kam', 'PHP', 1, 21, 'Nũndũ kwakwa nyie kwĩkala thayũ no Klĩsto, na kũkw’a nĩ ũunĩko.'),
('kam', 'PHP', 1, 22, 'Ĩndĩ ethĩwa kwĩkala thayũ mwĩĩnĩ,— ethĩwa ũu nĩw’o ũsyao wa wĩa wakwa, ndiũmanya ũla nĩnyuva.'),
('kam', 'PHP', 1, 23, 'Mbivinyĩtwe nĩ maũndũ asu elĩ, nĩ na mea ma kũthi nĩthĩwe vamwe na Klĩsto; nũndũ ũu nĩ ũseo mũno mbee:'),
('kam', 'PHP', 1, 24, 'ĩndĩ kwĩkala mwĩĩnĩ kwĩ vata mũno kwondũ wenyu.'),
('kam', 'PHP', 1, 25, 'Na ngĩkwatya ũu, nĩnĩsĩ ngekala, ĩĩ, na ngekalan’ya nenyu inyw’onthe, kwondũ wa kũendeea kwenyu na ũtanu wenyu nthĩnĩ wa mũĩkĩĩo;'),
('kam', 'PHP', 1, 26, 'nĩ kana kwĩtaĩa kwenyu kwingĩve nthĩnĩ wa Klĩsto Yesũ kwondũ wakwa kwĩthĩwa nenyu ĩngĩ.'),
('kam', 'PHP', 1, 27, 'Ĩndĩ mwĩkalĩle wa thayũ wenyu wĩthĩwe waĩle ũvoo mũseo wa Klĩsto: kana, nooka na kũmwona inyw’ĩ kana o na neethĩwa nde vo, nĩĩw’a ũvoo wenyu, kana mũũngamĩte na ũlũmu vevanĩ ũmwe, mũkyũkitĩa na ngoo ĩmwe mũĩkĩĩo wa ũla ũvoo mũseo;'),
('kam', 'PHP', 1, 28, 'na mũikatĩsw’e nĩ amaitha ũndũnĩ o na wĩva; naw’o kwoo nĩ wonan’yo vyũ wa kwaa, ĩndĩ kwenyu nĩ wa ũtangĩĩo, naw’o wumĩte kwa Ngai;'),
('kam', 'PHP', 1, 29, 'nĩkwĩthĩwa nĩmũnengetwe kwondũ wa Klĩsto, ti kũmwĩtĩkĩla kw’oka, ĩndĩ o na kũthĩnw’a nakw’o kwondũ wake:'),
('kam', 'PHP', 1, 30, 'mũkyũkitaa kaũ o ũmwe ũla mwambonie nĩ naw’o, na nĩmwĩw’aa o na yu nĩ o naw’o.'),
('kam', 'PHP', 2, 1, 'Ethĩwa ĩndĩ kwĩ ũtao o na wĩva nthĩnĩ wa Klĩsto, ethĩwa kwĩ ũkiakisyo o na wĩva wa wendo, ethĩwa kwĩ mũamba o na wĩva wa Veva, ethĩwa kwĩ matei mololo na kwĩw’anĩa manee o na meva,'),
('kam', 'PHP', 2, 2, 'wusũsyei ũtanu wakwa, kana mwĩthĩwe na kĩlilikano o kĩmwe, mwĩ na wendo ũmwe, mwĩ na ngoo ĩmwe, mũkĩlilikana ũndũ ũmwe;'),
('kam', 'PHP', 2, 3, 'mũikeke ũndũ o na wĩva na ngananĩo kana kwĩkathĩĩa kwa mana, ĩndĩ na wĩnyivyo kĩla mũndũ namũtale ũla ũngĩ mũseo kwĩ we mwene;'),
('kam', 'PHP', 2, 4, 'kĩla mũndũ wenyu ndakasũvĩe syĩndũ syake mwene, ĩndĩ kĩla ũmwe wenyu nasũvĩe syĩndũ sya ala angĩ nasyo.'),
('kam', 'PHP', 2, 5, 'Ĩthĩwai na kĩlilikano kĩĩ nthĩnĩ wenyu, o kĩla kyaĩ nthĩnĩ wa Klĩsto Yesũ:'),
('kam', 'PHP', 2, 6, 'nake, yĩla waĩ na mũvw’ano wa Ngai, ndaatala kwĩanana na Ngai ta nĩ ũndũ wa kũkwatwa,'),
('kam', 'PHP', 2, 7, 'ĩndĩ eeyĩkalya e mũthei, aiosa mũvw’ano wa ngombo, eethĩwa ailyĩ ũndũ ũmwe na mũndũ;'),
('kam', 'PHP', 2, 8, 'na ooneka e na wũmbe wa mũndũ, eenyivya mwene, atw’ĩka mwĩwi, o na kũvika kĩkw’ũ, ĩĩ, kĩkw’ũ kya ngelan’yo.'),
('kam', 'PHP', 2, 9, 'Kwondũ wa ũu Ngai amũnenevya mũno, na amũnenga syĩtwa yĩla yĩ mbee wa masyĩtwa onthe;'),
('kam', 'PHP', 2, 10, 'nĩ kana kwa syĩtwa ya Yesũ kĩla ĩu yĩtulya ndu, ya ala me ĩtunĩ na ala me nthĩ na ala me ungu wa nthĩ,'),
('kam', 'PHP', 2, 11, 'na nĩ kana kĩla ũĩmĩ wĩumbũla kana Yesũ Klĩsto nĩ Mwĩaĩi, kwa ndaĩa ya Ngai Asa.'),
('kam', 'PHP', 2, 12, 'Kwondũ wa ũu ĩndĩ, endwa makwa, o ũndũ mwaĩ ewi mavinda onthe, ti yĩla naĩ vo yoka, ĩndĩ yu mbee mũno nde vo, ĩanĩsyai ũtangĩĩo wenyu na kĩkĩo na kĩtetemo;'),
('kam', 'PHP', 2, 13, 'nũndũ nĩ Ngai ũla wĩkaa nthĩnĩ wenyu akĩtuma mwendaa na kwĩkaa kwenda kwake kũseo.'),
('kam', 'PHP', 2, 14, 'Ĩkai maũndũ onthe mũtekũnyungunyĩsya na kũkananĩa;'),
('kam', 'PHP', 2, 15, 'nĩ kana mwĩthĩwe mũtailĩĩlĩka ũthũku na mwĩ auu, syana sya Ngai ite na ũndũ ũtaĩle katĩ wa ũsyao mũthũku na mũemu, naw’o nthĩnĩ waw’o nĩmwonekaa ta syeni kũũ nthĩ,'),
('kam', 'PHP', 2, 16, 'mũkĩlĩtye ndeto ya thayũ; nĩ kana nĩthĩwe na ũndũ wa kwĩkathĩĩa mũthenya wa Klĩsto, kana ndyaasemba mana kana kũtethya wĩa mana.'),
('kam', 'PHP', 2, 17, 'Ĩĩ, na ethĩwa nĩtulũlwa ĩũlũ wa nthembo na ũthũkũmi wa mũĩkĩĩo wenyu, nĩngwĩw’a mũyo, na kũtana vamwe nenyu inyw’onthe:'),
('kam', 'PHP', 2, 18, 'na inyw’ĩ o ta ũu tanai, na ĩthiwai na mũyo vamwe nakwa.'),
('kam', 'PHP', 2, 19, 'Ĩndĩ nĩngwĩkwatya nthĩnĩ wa Mwĩaĩi Yesũ kũmũtũma Timotheo kwenyu mĩtũkĩ, nĩ kana nyie nĩtonye kũkiakiw’a, namanya ũndũ mũilyĩ.'),
('kam', 'PHP', 2, 20, 'Nũndũ ndi na mũndũ ũngĩ ũla ũlilikanaa ũndũ ũmwe nakwa, ũla ũtonya kũsisya w’o mwĩkalĩle wenyu.'),
('kam', 'PHP', 2, 21, 'Nũndũ onthe nĩmeũmantha maũndũ moo ene, ti maũndũ ma Yesũ Klĩsto.'),
('kam', 'PHP', 2, 22, 'Ĩndĩ nĩmwĩsĩ ũndũ wake, kana nĩwatethisye wĩa vamwe nakwa kwondũ wa ũnyaĩĩkya ũla ũvoo mũseo, o ũndũ mwana ũtethasya ĩthe wake.'),
('kam', 'PHP', 2, 23, 'Ĩndĩ nĩngwĩkwatya kũtũma ũsu mĩtũkĩ, o yĩla nĩmanya ũndũ nĩĩkwa:'),
('kam', 'PHP', 2, 24, 'ĩndĩ nĩngũĩkĩĩa Mwĩaĩi kana nyie mwene ngooka mĩtũkĩ.'),
('kam', 'PHP', 2, 25, 'Ĩndĩ nona no mũvaka nĩmũtũme Evavilotito kwenyu, mwana‐a‐asa wakwa na mũtethya wa wĩa vamwe nakwa na mũsikalĩ vamwe nakwa, nake nĩ mũtũmwa wenyu na mũthũkũmi wa vata wakwa;'),
('kam', 'PHP', 2, 26, 'nĩkwĩthĩwa aĩ na mea nenyu inyw’onthe, na aũũyaa ngoonĩ, nũndũ mwewie kana aĩ mũwau:'),
('kam', 'PHP', 2, 27, 'nũndũ nĩ w’o, aĩ mũwau mũno, vakuvĩ kũkw’a: ĩndĩ Ngai nĩwamwĩwĩie tei; na ti we weka, ĩndĩ o na nyie nakwa, nĩ kana ndikethĩwe na woo ĩũlũ wa woo.'),
('kam', 'PHP', 2, 28, 'Kwondũ wa ũu neethĩwa na kĩthing’ĩĩsyo kingĩ kya ũmũtũma, nĩ kana, mwamwona ĩngĩ, mũtonye kũtana, nakwa nĩnyivĩwe nĩ woo.'),
('kam', 'PHP', 2, 29, 'Mwosei ĩndĩ nthĩnĩ wa Mwĩaĩi na ũtanu w’onthe; na mataĩei ala mailyĩ take:'),
('kam', 'PHP', 2, 30, 'nĩkwĩthĩwa kwondũ wa wĩa wa Klĩsto aĩ vakuvĩ kũkw’a, na ndaasũvĩa thayũ wake nĩ kana eanĩsye kĩla kyatialĩte kwenyu kya ũndethya.'),
('kam', 'PHP', 3, 1, 'Kũminũkĩlya, ana‐a‐asa, tanai nthĩnĩ wa Mwĩaĩi. Kũmũandĩkĩa inyw’ĩ maũndũ o asu ĩngĩ, ndiũnoa, ĩndĩ kwenyu ni ũsũvĩo.'),
('kam', 'PHP', 3, 2, 'Ĩsũvĩei ila ngitĩ, ĩsũvĩei ala atethya ma mawĩa mathũkũ, ĩsũvĩei ala metemaa:'),
('kam', 'PHP', 3, 3, 'nũndũ ithyĩ twĩ ala maĩkawa, ala tũthaithaa ũndũ wa Veva wa Ngai, na twĩkathĩĩaa nthĩnĩ wa Klĩsto Yesũ, na tũtiĩkĩĩaa mwĩĩ:'),
('kam', 'PHP', 3, 4, 'o na kau nyie mwene nĩndonya kũĩkĩĩa mwĩĩ: ethĩwa mũndũ ũngĩ o na wĩva eona e na ũndũ wa kũĩkĩĩa mwĩĩ, nyie nĩ mbee:'),
('kam', 'PHP', 3, 5, 'naĩkiwe mũthenya wa nyanya, nĩ wa mbaĩ ya Isilaeli, wa mũvĩa wa Mbenyamini, Mũevelania wa Aevelania; ũndũ wa ĩla mĩao, naĩ Mũvalisi;'),
('kam', 'PHP', 3, 6, 'ũndũ wa ũthangaau mũnene, nathĩnisye ĩkanisa; na ũndũ wa ũlũngalu ũla wĩ mĩaonĩ, ndyaailĩĩlĩka ũndũ.'),
('kam', 'PHP', 3, 7, 'Ĩndĩ maũndũ ala maĩ ma nguna, nĩmo natalile kwĩthĩwa nĩ wasyo kwondũ wa Klĩsto.'),
('kam', 'PHP', 3, 8, 'Ĩĩ nĩ w’o, na nĩtalaa syĩndũ syonthe kwĩthĩwa nĩ wasyo ũndũ wa ũseo mũnene wa ũmũmanya Klĩsto Yesũ Mwĩaii wakwa: we ũla kwondũ wake naaisye syindũ syonthe, na kwitala kwĩthĩwa nĩ mavuthĩ, nĩ kana nĩmwone Klĩsto,'),
('kam', 'PHP', 3, 9, 'nakwa noneke nthĩnĩ wake, nde na ũlũngalu wakwa mwene, naw’o ti ũla wonekaa ĩla maĩonĩ, ĩndĩ ũla wonekaa kwondũ wa kũikĩĩa Klĩsto, ũlũngalu ũla wumaa kwa Ngai kwondũ wa mũĩkĩĩo:'),
('kam', 'PHP', 3, 10, 'nĩ kana nĩmũmanye we, na vinya wa kũthayũũka kwake, na mũamba wa mathĩna make, ngĩvw’ananw’a na kikw’ũ kyake;'),
('kam', 'PHP', 3, 11, 'nĩ kana kwa ũndũ o na wĩva w’onthe nĩtonye kũvikĩa ũthayũũkyo kuma kwa akw’ũ.'),
('kam', 'PHP', 3, 12, 'Ti atĩ nĩnĩvikĩte, kana ngethĩwa mwĩanĩu: ĩndĩ nĩngwĩthĩng’iĩsya kũthi na mbee, nĩ kana nĩtonye kũkikwata kĩla kwondũ wakyo nakwatiwe nĩ Klĩsto Yesũ.'),
('kam', 'PHP', 3, 13, 'Ana‐a‐asa, ndikwĩtala mwene ta nĩkwatĩte: ĩndĩ ũndũ ũũ ũmwe nĩngwĩka, ngyũlwa nĩ maũndũ ala me ĩtina, na ngikoota nĩvĩkĩe maũndũ ala me mbee,'),
('kam', 'PHP', 3, 14, 'nĩngwĩthĩng’iĩsya kũthi nĩvikĩe ngoolu kwondũ wa mũthĩnzĩo ũla neetiwe ĩũlũ nĩ Ngai nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'PHP', 3, 15, 'Ithyĩ ĩndĩ ala eanĩu tũlilikane ũu: na ethĩwa nĩmũũlilikana ũndũ ũngĩ, ũndũnĩ o na wĩva, Ngai akamũvuanĩsya ũndũ ũsu naw’o:'),
('kam', 'PHP', 3, 16, 'ĩndĩ o vala tũvikĩte tũendeei ũndũnĩ o ũsu.'),
('kam', 'PHP', 3, 17, 'Ana‐a‐asa, inyw’onthe ĩthĩwai mũkĩelekan’ya nakwa, na masisyei ala maendaa na kũatĩĩa ngelekan’yo ĩla twamũnengie.'),
('kam', 'PHP', 3, 18, 'Nũndũ aingĩ nĩmaendaa, ala nĩmũtavasya ũvoo woo kaingĩ, na yu nĩngũmũtavya o ngĩtĩkya methoi, kana nĩ amaitha ma ngelan’yo ya Klĩsto:'),
('kam', 'PHP', 3, 19, 'na mũminũkĩlyo woo nĩ wanangĩko, na ngai yoo nĩ ĩvu, na kwĩtaĩa kwoo kwĩ maũndũnĩ ma nthoni syoo, na malilikanaa maũndũ ma nthĩ.'),
('kam', 'PHP', 3, 20, 'Nũndũ kwitũ nĩ ĩtunĩ; naitũ nĩtweteelaa Mũtangĩĩi ũla wĩuma vo, nake nĩ Mwĩaĩi Yesũ Klĩsto:'),
('kam', 'PHP', 3, 21, 'ũla ũkaalyũla mwĩĩ ũũ wa ũnyivu witũ, wĩthĩwe ũvw’anene na mwĩĩ wa ũtaĩo wake, kwĩanana na kwĩka kũla ũtonya o na kũnyivya syĩndũ syonthe syĩthĩwe ĩtheo wake mwene.'),
('kam', 'PHP', 4, 1, 'Kwondũ wa ũu, ana‐a‐asa makwa ala nendete mũno na ala nĩ na mea ma kũmwona, ũtanu wakwa na ngovia ya ũsumbĩ, ũngamai na ũlũmu nthĩnĩ wa Mwĩaĩi, endwa makwa.'),
('kam', 'PHP', 4, 2, 'Nĩmwĩsũva Euotia, na nĩmwĩsũva Sinitike nake, methĩwe na kĩlilikano kimwe nthĩnĩ wa Mwĩaĩi.'),
('kam', 'PHP', 4, 3, 'Ĩĩ, na nĩngũkwisũva we, mwovanĩw’a wa w’o vamwe nakwa wĩanĩ, ũmatethye aka asu, nũndũ nĩmatethisye wĩa vamwe nakwa ũla ũvoonĩ mũseo, vamwe na Kilemendi nake, na ala angĩ atethya ma wĩa vamwe nakwa. Nao masyĩtwa moo me ĩvukunĩ ya thayũ.'),
('kam', 'PHP', 4, 4, 'Tanaai nthĩnĩ wa Mwĩaĩi mavinda onthe: na ĩngĩ nĩngwasya Tanaai.'),
('kam', 'PHP', 4, 5, 'Wũmĩĩsyo wenyu ũmanyĩke nĩ andũ onthe, Mwĩaĩi e vakuvĩ.'),
('kam', 'PHP', 4, 6, 'Mũikemakĩe kwa ũndũ o na wĩva; ĩndĩ kĩla ũndũnĩ mavata menyu nĩmatavanw’e kwa Ngai na kũvoya na kwĩsũva vamwe na kũtũnga mũvea.'),
('kam', 'PHP', 4, 7, 'Na mũuo wa Ngai, ũla ũvĩtũkĩte ũmanyi w’onthe, ũkasũvĩaa ngoo syenyu na mosũanĩo menyu nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'PHP', 4, 8, 'Kũminũkĩlya, ana‐a‐asa, maũndũ o na meva ala ma w’o, maũndũ o na meva ala me na ndaĩa, maũndũ o na meva ala malũngalu, maũndũ o na meva ala matheu, maũndũ o na meva ala ma kwendeesya, maũndũ o na meva ala me na nguma nzeo; ethĩwa ve ũseo o na wĩva w’onthe, na ethĩwa ve ndaĩa o na yĩva yonthe, malilikanei maũndũ asu.'),
('kam', 'PHP', 4, 9, 'Maũndũ ala mweemanyĩisye kwakwa na kũmosa na kũmew’a na kũmona, mekei maũndũ asu: na Ngai wa mũuo akeethĩwa vamwe nenyu.'),
('kam', 'PHP', 4, 10, 'Ĩndĩ nĩtana mũno nthĩnĩ wa Mwĩaĩi, atĩ yu nĩmwambĩlĩlye ĩngĩ kũndilikana; na nĩmwandilikene w’o, ĩndĩ mũtyaaona ũthei.'),
('kam', 'PHP', 4, 11, 'Ti atĩ nĩneena ũu nũndũ nĩ na vata: nũndũ nĩneemanyĩisye, ũndũnĩ o na wĩva ũla nĩ naw’o, kwĩthĩwa ndi na ũndũ.'),
('kam', 'PHP', 4, 12, 'Nĩnĩsĩ ũndũ kũilyĩ kũnyivĩwa, na nĩnĩsĩ ũndũ kũilyĩ kwingĩvĩwa nakw’o: kĩla ũndũnĩ na maũndũnĩ onthe nĩnĩmanyĩĩtye kũvũna o na kwĩw’a nzaa, kwĩthĩwa na nyingĩ na kũnyivĩwa.'),
('kam', 'PHP', 4, 13, 'Nĩndonya maũndũ onthe nthĩnĩ wake ũla ũndonyethasya.'),
('kam', 'PHP', 4, 14, 'Ĩndĩ mwekie nesa mũno mweethĩwa na mũamba nakwa mathinanĩ makwa.'),
('kam', 'PHP', 4, 15, 'Nenyu ene nĩmwĩsĩ, inyw’ĩ Avilivi, kana wambĩlĩlyonĩ wa ũla ũvoo mũseo, yĩla naumie Masetonia, vaiai ĩkanisa yaĩ na mũamba nakwa ũndũnĩ ũũ wa kũnengane na kwosa, ate o inyw’ĩ inyw’oka;'),
('kam', 'PHP', 4, 16, 'nĩkwĩthĩwa o na kũu Thesalonika nĩmwandetee ũtethyo kwondũ wa vata wakwa, o na ti ĩvinda yĩmwe.'),
('kam', 'PHP', 4, 17, 'Ti kwĩthĩwa nĩngũwenda ũla mũthĩnzĩo; ĩndĩ nĩngwenda ũsyao ũla wingĩvaa ũtalonĩ wenyu.'),
('kam', 'PHP', 4, 18, 'Ĩndĩ nĩ na syĩndũ syonthe, na nĩningĩvĩwe: na ĩngĩ nĩnusũĩte, nũndũ nĩnĩsyosete mokonĩ ma Evavilotito syĩndũ ila syumĩte kwenyu, nĩ mũuke mũseo, nĩ nthembo ĩtĩkĩlawa, ĩla ĩmwendeeasya Ngai.'),
('kam', 'PHP', 4, 19, 'Na Ngai wakwa akawĩanĩsya kĩla vata wenyu kwĩanana na ũthwii wake ndaĩanĩ nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'PHP', 4, 20, 'Na yu Ngai, Asa waitũ, nataĩwe tene na tene. Ameni.'),
('kam', 'PHP', 4, 21, 'Ngethesyai kĩla mũtheu nthĩnĩ wa Klĩsto Yesũ. Ana‐a‐asa ala me nakwa nĩmamũkethya.'),
('kam', 'PHP', 4, 22, 'Atheu onthe nĩmamũkethya, na mũno nĩ ala ma nyũmba ya Kaisali.'),
('kam', 'PHP', 4, 23, 'Mumo wa Mwĩaĩi Yesũ Klĩsto nĩwĩthĩwe na maveva menyu.'),
('kam', 'COL', 1, 1, 'Vaulo mũtũmwa wa Klĩsto Yesũ kwondũ wa kwenda kwa Ngai, na Timotheo mwana‐a‐asa waitũ,'),
('kam', 'COL', 1, 2, 'valũa ũũ witũ ũmavikĩe atheu na ana‐a‐asa nthĩnĩ wa Klĩsto ala me na kĩthito, ala me Kolosai: Mumo nĩwĩthĩwe kwenyu na mũuo kuma kwa Ngai Asa waitũ.'),
('kam', 'COL', 1, 3, 'Nĩtũũtũngĩa Ngai mũvea, Ĩthe wa Mwĩaĩi waitũ Yesũ Klĩsto, tũkĩmũvoyea mavinda onthe,'),
('kam', 'COL', 1, 4, 'nũndũ nĩtwĩw’ĩte ũvoo wa mũĩkĩĩo wenyu nthĩnĩ wa Klĩsto Yesũ, na wendo ũla mũmendaa atheu onthe naw’o,'),
('kam', 'COL', 1, 5, 'nũndũ wa wĩkwatyo ũla mwaiĩwe ĩtunĩ, naw’o nĩmweew’ĩte tene ũvoo waw’o ndetonĩ ya ũla w’o wa ũvoo mũseo,'),
('kam', 'COL', 1, 6, 'ũla wamũvikĩe; o tondũ ũilyĩ nthĩ yonthe ũisyaa ũsyao na kwongeleka, o ũndũ ũilyĩ nthĩnĩ wenyu, kuma mũthenya ũla mweewie na mwamanya ũla mumo wa Ngai katĩ wa w’o;'),
('kam', 'COL', 1, 7, 'o tondũ mũmanyĩĩtw’e nĩ Evavila mwendwa, mũtethya wa wĩa vamwe naitũ, nake nĩ mũthũkũmi wĩ kĩthito wa Klĩsto kwondũ witũ,'),
('kam', 'COL', 1, 8, 'nake nĩwatũtavisye wendo wenyu nthĩnĩ wa Veva.'),
('kam', 'COL', 1, 9, 'Kwondũ wa ũu ithyĩ naitũ, kuma mũthenya ũla tweewie, tũtiekaa kũvoya na kũmũvoyeaa, nĩ kana musũe ũmanyi wa kwenda kwake nthĩnĩ wa ũĩ w’onthe na kũmanya kwa veva,'),
('kam', 'COL', 1, 10, 'mũkinyae ũndũ waĩle Mwĩaĩi kũvikĩa kũmwendeesya vyũ, mũkĩsyaa ũsyao kĩla wĩanĩ mũseo, na kwongeleka kũmũmanya Ngai;'),
('kam', 'COL', 1, 11, 'mũkitonyethw’a na ũtonyi w’onthe, kwĩanana na vinya wa ũtheu wake mũtisu, kũvikĩa kwĩlũĩũmĩlya kw’onthe na kũmĩĩsya mũtanĩte;'),
('kam', 'COL', 1, 12, 'mũkĩmũtũngĩa Asa mũvea, ũla watũtwie aĩlu twĩthĩwe osi ma ũtiĩwa wa atheu nthĩnĩ wa kyeni;'),
('kam', 'COL', 1, 13, 'ũla watũtangĩĩe kuma vinyanĩ wa kĩvindu na kũtũthamya na kũtũlikya ũsumbĩnĩ wa Mwana wake mwendwa;'),
('kam', 'COL', 1, 14, 'nake nthĩnĩ wake twĩ na wovosyo witũ, ũekeo wa naĩ sitũ:'),
('kam', 'COL', 1, 15, 'nake nĩ mũvw’ano wa Ngai ũtonekaa, mũsyawa ũla wĩ mbee wa syũmbe syonthe;'),
('kam', 'COL', 1, 16, 'nĩkwĩthĩwa nthĩnĩ wake syĩndũ syonthe nĩsyoombiwe, sya ĩtunĩ na sya kũũ nthĩ, syĩndũ ila syonekaa na ila itonekaa, ethĩwa nĩ ivĩla sya ũsumbĩ, o na mosumbĩ, o na monene, o na mokũmũ; syĩndũ syonthe nĩsyoombiwe nĩwe, syĩthĩwe syake;'),
('kam', 'COL', 1, 17, 'nake e mbee wa syĩndũ syonthe, na nthĩnĩ wake syĩndũ syonthe nikwatene.'),
('kam', 'COL', 1, 18, 'Nake nĩwe mũtwe wa mwĩĩ, naw’o nĩ ĩkanisa: nake nĩ mwambĩlĩlyo, na mũsyawa wa mbee kuma akw’ũnĩ; nĩ kana maũndũnĩ onthe ethĩwe e mbee.'),
('kam', 'COL', 1, 19, 'Nĩkwĩthĩwa kwaĩ kwenda kũseo kwa Ĩthe atĩ wĩanĩu w’onthe wĩkalae nthĩnĩ wake;'),
('kam', 'COL', 1, 20, 'na kwondũ wake kũsyĩw’anĩthya syĩndũ syonthe nake mwene, aetete mũuo kwondũ wa nthakame ya ngelan’yo yake; kwondũ wake, ethĩwa nĩ syĩndũ sya kũũ nthĩ, kana syĩndũ syĩ ĩtunĩ.'),
('kam', 'COL', 1, 21, 'Na inyw’ĩ, mwekalĩte ĩvinda ya tene mũte na wĩw’ano na mwĩ amaitha ilĩkonĩ syenyu na mĩkĩlenĩ yenyu mĩthũku,'),
('kam', 'COL', 1, 22, 'ĩndĩ yu nũmwĩw’ĩthanĩtye na mwĩĩ wake wa nyama kwondũ wa kũkw’a, nĩ kana amũete inyw’ĩ mbee wake, mwĩ atheu, mũte na ũndũ ũtaĩle na mũtavinganĩĩka:'),
('kam', 'COL', 1, 23, 'ethĩwa nĩ w’o mũkekala mũĩkĩĩonĩ, mwĩ ĩũlũ wa wambĩlĩlyo na mwĩ alũmu, na mũte kũthamwa kũtia wĩkwatyo wa ũvoo mũseo ũla mweewie, ũla watavaniw’e syũmbenĩ syonthe syĩ ĩtheo wa ĩtu; naw’o nyie Vaulo natwĩwe mũthũkũmi waw’o.'),
('kam', 'COL', 1, 24, 'Na yu nĩngũtana mathĩnanĩ makwa kwondũ wenyu, na nĩĩanĩsya mwĩĩnĩ wakwa mathĩna ala matialĩte ma Klĩsto kwondũ wa mwĩĩ wake, naw’o nĩ ĩkanisa;'),
('kam', 'COL', 1, 25, 'nayo nyie natwiwe mũthũkũmi wayo, kwĩanana na walan’yo wa Ngai ũla nanengiwe kwa ngalĩ ĩla yenyu, kwĩanĩsya ndeto ya Ngai,'),
('kam', 'COL', 1, 26, 'nayo nĩ ĩla nzama ĩvithĩtwe kuma tene tene na ĩvithĩtwe nzyawa syonthe: ĩndĩ yu nĩvuanĩtw’e kwa atheu make,'),
('kam', 'COL', 1, 27, 'namo Ngai endeew’e nĩ kũmamanyĩthya ũndũ ũtilyĩ wingĩ wa ndaĩa ya nzama ĩno kwa Andũ‐ma‐mbaĩ‐ĩngĩ, nayo nĩ Klĩsto nthĩnĩ wenyu, wĩkwatyo wa ũtheu mũtisu:'),
('kam', 'COL', 1, 28, 'na nĩwe ũla ithyĩ tũũmũtavan’ya, tũimũtaa kĩla mũndũ na tũkĩmũmanyĩsya kĩla mũndũ na ũĩ w’onthe, nĩ kana tũtonye kũete kĩla mũndũ e mwĩanĩu nthĩnĩ wa Klĩsto;'),
('kam', 'COL', 1, 29, 'nakwa nĩtethasya wĩa nũndũ wa ũu, ngĩthing’ĩĩsya kwĩanana na kwĩka kwake, ũla ũtethasya nthĩnĩ wakwa na vinya.'),
('kam', 'COL', 2, 1, 'Nũndũ nĩenda mũmanye kĩthing’ĩĩsyo kĩla nĩ nakyo kwondũ wenyu, na kwondũ wa ala me Laotisia, na kwondũ wa ala mataawona ũthyũ wakwa wa mwĩĩ;'),
('kam', 'COL', 2, 2, 'nĩ kana ngoo syoo ikiakiw’e, makwatanĩtw’e nĩ wendo, mavikĩe ũthwii w’onthe wa wĩanĩu wa ũmanyi, nĩ kana mamanye ĩla nzama ya Ngai, nayo nĩ Klĩsto,'),
('kam', 'COL', 2, 3, 'ũla nthĩnĩ wake ũthwii w’onthe wa ũĩ na ũmanyi nũvithitwe.'),
('kam', 'COL', 2, 4, 'Nĩneena ũu, nĩ kana mũndũ o na wĩva ndakamũkenge na ndeto nzeũvye.'),
('kam', 'COL', 2, 5, 'Nũndũ o na ethĩwa ndi vamwe nenyu kwa mwĩĩ, kwa veva nĩ vamwe nenyu, ngĩtana na kwona mũseũvĩlye wa maũndũ menyu, na ũlũmu wa mũĩkĩĩo wenyu nthĩnĩ wa Klĩsto.'),
('kam', 'COL', 2, 6, 'Ĩndĩ o tondũ mwamwosie Klĩsto Yesũ Mwĩaĩi, endaai o ũu nthĩnĩ wake,'),
('kam', 'COL', 2, 7, 'mwĩ na mĩi mĩlũmu, na kwakwa nthĩnĩ wake, na kũlũlũmĩlw’a mũĩkĩĩonĩ wenyu, o ũndũ mwamanyĩiw’e, mũkingĩva kũtũnga mũvea.'),
('kam', 'COL', 2, 8, 'Ĩsũvĩei mũndũ o na wĩva ndakamũtave na ũĩ na ũkengani wake wa mana, kũatĩĩa mokũũ ma andũ, na momanyĩsyo ma kwambĩlĩlya ma nthĩ, na ti kũmũatĩĩa Klĩsto:'),
('kam', 'COL', 2, 9, 'nũndũ wĩanĩu w’onthe wa Ũ‐Ngai ũtwĩe nthĩnĩ wake e o na mwĩĩ,'),
('kam', 'COL', 2, 10, 'na inyw’ĩ nĩmwĩanĩw’e nthĩnĩ wake, nake nĩ mũtwe wa monene na mokũmũ onthe:'),
('kam', 'COL', 2, 11, 'na nthĩnĩ wake nĩmwaĩkĩtwe na nzaĩko ĩtaĩkawa na moko, ũndũ wa kũveta mwĩĩ wa nyama, nthĩnĩ wa nzaĩko ya Klĩsto;'),
('kam', 'COL', 2, 12, 'nĩmwathikiwe vamwe nake ũvatisonĩ, na nthĩnĩ waw’o nĩmwathayũũkiw’e vamwe nake kwondũ wa mũĩkĩĩo nthĩnĩ wa kwĩka kwa Ngai, ũla wamũthayũũkisye kũmumya kwa akw’ũ.'),
('kam', 'COL', 2, 13, 'Nenyu yĩla mwaĩ akw’ũ kwondũ wa mavĩtyo menyu na kũlea kwaĩkwa kwa mĩĩ yenyu, inyw’ĩ, nĩwamũtw’ĩkĩthisye kwĩthĩwa thayũ vamwe nake, atũekeete mavĩtyo maitũ onthe;'),
('kam', 'COL', 2, 14, 'amina kwananga ũandĩko ũla waandĩkĩtwe motw’ĩonĩ ũla waĩ ĩũlũ waitũ, ũla waĩ na ũmaitha kwitũ: na ooveta, aiwamba ngelan’yonĩ yake;'),
('kam', 'COL', 2, 15, 'eevetea monene na mokũmũ amaumĩlya ũtheinĩ, akimakĩlya vinya nũndũ wa ngelan’yo ĩsu.'),
('kam', 'COL', 2, 16, 'Kwondũ wa ũu mũndũ o na wĩva ndakamũsilĩle ũndũ wa kya ũya, kana kya ũnyw’a, kana kwondũ wa mũthenya wa mboka, kana mwei mũtisu, kana mũthenya wa savato:'),
('kam', 'COL', 2, 17, 'maũndũ asu nĩ kyuu kya maũndũ ala makoka; ĩndĩ mwĩĩ nĩ wa Klĩsto.'),
('kam', 'COL', 2, 18, 'Mũndũ o na wĩva ndakamũvute mũthĩnzĩo wenyu kwondũ wa kwĩnyivya kwa kwenda kwake mwene, na kũthaitha alaĩka, na kwĩlikya maũndũnĩ ala ũtaamona, akĩkathĩĩa mana kwondũ wa kĩlĩko kyake kya mwĩĩ,'),
('kam', 'COL', 2, 19, 'na ndeũlũmya ũla Mũtwe, ũla kuma kwake mwĩĩ w’onthe, ũinengwa vinya na ũithalanw’a na maleenyũ na malangũ, nĩwĩanaa ũndũ Ngai wianasya.'),
('kam', 'COL', 2, 20, 'Ethĩwa mwakwie vamwe na Klĩsto kwa momanyĩsyo ma kwambĩlĩlya ma nthĩ, nĩkĩ mũsumbĩkĩtwe nĩ motw’ĩo ta mwĩ thayũ kũũ nthĩ,'),
('kam', 'COL', 2, 21, 'atĩĩ, Mũikakwate, kana kũsama, kana kũkiita'),
('kam', 'COL', 2, 22, '(syĩndũ isu syonthe ila ikanangĩka ĩvinda ya kwĩkaa ũndũ nasyo), kũatĩĩa motao na momanyĩsyo ma andũ?'),
('kam', 'COL', 2, 23, 'Maũndũ asu nĩ w’o me na wonan’yo wa ũĩ kwa kũthaitha kwĩanana na kwenda kwa mũndũ, na wĩnyivyo, na kũthĩn’ya mwĩĩ; ĩndĩ maũndũ asu maitonya kũsiĩĩa mawendi ma mwĩĩ.'),
('kam', 'COL', 3, 1, 'Ethĩwa ĩndĩ mwathayũũkiw’e vamwe na Klĩsto, manthai maũndũ ala me ĩũlũ, vala Klĩsto ũĩ, ailyi nthĩ ngalĩ ya kw’oko kwa aũme kwa Ngai.'),
('kam', 'COL', 3, 2, 'Mosũanĩo menyu malũme maũndũnĩ ala me ĩũlũ, na ti maũndũnĩ ala me nthĩ.'),
('kam', 'COL', 3, 3, 'Nĩkwĩthĩwa nĩmwakwie, na thayũ wenyu ũvithĩtwe vamwe na Klĩsto nthĩnĩ wa Ngai.'),
('kam', 'COL', 3, 4, 'Yĩla Klĩsto ũkonanw’a, nake nĩwe thayũ witũ, nĩvo ĩndĩ nenyu mũkonanw’a vamwe nake ũtheunĩ mũtisu.'),
('kam', 'COL', 3, 5, 'Kwondũ wa ũu, ũaai mamutha menyu ala me kũũ nthĩ: ũlaalai, na ũvuku, na mĩmeo mĩthũku, na kwenda maũndũ mathũku, na ĩtomo, nayo nĩ kũthaitha mĩvw’anano;'),
('kam', 'COL', 3, 6, 'kwondũ wa maũndũ asu ũthatu wa Ngai wũkaa kwa ana ala matew’aa:'),
('kam', 'COL', 3, 7, 'nenyu tene mwaendaa nthĩnĩ wamo, yĩla mwatwĩe maũndũnĩ asu;'),
('kam', 'COL', 3, 8, 'ĩndĩ yu vetai kũasa nenyu maũndũ asu onthe: ũthatu, na ũthilĩku, na kĩmena, na kũumana, ndeto mbathe itikethĩwe makanyw’anĩ menyu:'),
('kam', 'COL', 3, 9, 'mũikaneene ũvũngũ ene kwa ene; nĩkwĩthĩwa nĩmumĩtye mũndũ ũla wa tene na meko make,'),
('kam', 'COL', 3, 10, 'na nĩmwĩvw’ĩkĩte mũndũ mweũ, ũla ũtũngawa mweũ kũvikĩa ũmanyi kũatĩĩa mũvw’ano wa ũla wamũmbie:'),
('kam', 'COL', 3, 11, 'vala vatatonyeka kwĩthĩwa Mũkiliki kana Mũyuti, kwaĩkwa kana kũlea kwaĩkwa, ũla ũte na ũmanyi kana Mũsithiani, ngombo kana ũla ũte ngombo; ĩndĩ Klĩsto nĩ onthe, na e nthĩnĩ wa onthe.'),
('kam', 'COL', 3, 12, 'Ĩndĩ tondũ mwĩ anyuve ma Ngai, atheu na endwa, ĩvw’ĩkei ngoo yĩ na ĩnee ya kwĩw’anĩa tei, wĩnyivyo, ũuu, wũmĩĩsyo;'),
('kam', 'COL', 3, 13, 'kũmĩĩasya ũmwe kwa ũla ũngĩ, na kũekeanĩa ene kwa ene, ethĩwa mũndũ o na wĩva e na ũndũ na ũngĩ; o tondu Mwĩaĩi wamũekeie, inyw’ĩ nenyu ĩkaai o ta ũu:'),
('kam', 'COL', 3, 14, 'na mbee wa maũndũ aa onthe ĩvw’ĩkei wendo, naw’o nĩ wovano wa wĩanĩu.'),
('kam', 'COL', 3, 15, 'Na mũuo wa Klĩsto ũsumbĩke ngoonĩ syenyu, ũla kwondũ waw’o nenyu mweetiwe nthĩnĩ wa mwĩĩ ũmwe; na ĩthĩwai na mũvea.'),
('kam', 'COL', 3, 16, 'Ndeto ya Klĩsto yĩkalae na ũthwii mwingĩ nthĩnĩ wenyu; nthĩnĩ wa ũĩ w’onthe mũimanyĩan’ya na kũtaana inyw’ĩ kwa inyw’ĩ na savuli na mbathi sya kũmũkumya Ngai na mbathi sya veva, mũkĩmwinĩa Ngai na mumo ngoonĩ syenyu.'),
('kam', 'COL', 3, 17, 'Na ũndũ o na wĩva mwĩkaa, kwa ndeto kana kwa meko, ĩkaai w’onthe syĩtwanĩ ya Mwĩaĩi Yesũ, mũimũnenga Ngai Asa mũvea kwondũ wake.'),
('kam', 'COL', 3, 18, 'Iveti, ĩnyivĩsyei aũme menyu ũndũ waĩle nthĩnĩ wa Mwĩaĩi.'),
('kam', 'COL', 3, 19, 'Aũme, endai iveti syenyu, na mũikasyĩw’ĩe woo.'),
('kam', 'COL', 3, 20, 'Syana mew’ei asyai menyu maũndũnĩ onthe, nũndũ ũu nĩwendeeasya nthĩn ĩ wa Mwĩaĩi.'),
('kam', 'COL', 3, 21, 'Aasa, mũikathatye syana syenyu, itikakw’e ngoo.'),
('kam', 'COL', 3, 22, 'Ngombo, mew’ei mavwana menyu kwondũ wa mwĩĩ maũndũnĩ onthe; ti na ũthũkũmi wa kũsyaĩĩwa, ta endeesya ma andũ, ĩndĩ na ũthalĩku wa ngoo, mũkĩmũkĩa Mwĩaĩi:'),
('kam', 'COL', 3, 23, 'ũndũ mũkwĩka o na wĩva, wĩkei kuma ngoonĩ, ta kũmũthũkũma Mwĩaĩi, na ti andũ:'),
('kam', 'COL', 3, 24, 'mwĩsĩ kana mũkoosa kuma kwa Mwĩaĩi ĩtuvi ya ũla ũtiĩwa: nũndũ nĩmũthũkũmaa Mwĩaĩi Klĩsto.'),
('kam', 'COL', 3, 25, 'Nũndũ ũla wĩkaa ũthũku akoosa ĩngĩ kwondũ wa ũthũku ũla wekie: na kũi wendeesyo wa andũ.'),
('kam', 'COL', 4, 1, 'Mavwana, nengai ngombo syenyu kĩla kyaĩle na kĩla kya katĩ; mwĩsĩ kana inyw’ĩ nenyu mwĩna Vwana ĩtunĩ.'),
('kam', 'COL', 4, 2, 'Ĩkalai mũlũlũmĩle mboyanĩ, voyai mũkĩsyaĩĩsya vamwe na kũtũnga mũvea;'),
('kam', 'COL', 4, 3, 'na vamwe na ũu mũkĩtũvoyea ithyĩ, nĩ kana Ngai atũvingũĩe mũomo kwondũ wa ĩla ndeto, kũneena nzama ya Klĩsto, nayo kwondũ wayo nĩ mwove;'),
('kam', 'COL', 4, 4, 'nĩ kana nĩmyonan’ye, o tondũ naĩlwe nĩ kũneena.'),
('kam', 'COL', 4, 5, 'Endaai na ũĩ kwa ala me ũtee, mũkĩtangĩĩa ĩvinda.'),
('kam', 'COL', 4, 6, 'Ndeto syenyu syĩthĩwe na mumo mavinda onthe, isamae mũnyũ, nĩ kana mũmanye ũndũ mwaĩlwe nĩ ũsũngĩa kĩla mũndũ.'),
('kam', 'COL', 4, 7, 'Maũndũ makwa onthe Tikiko akamũmanyĩthya, nake nĩ mwana‐a‐asa mwendwa, na mũthũkũmi wĩ na kĩthito, na ngombo vamwe nakwa nthĩnĩ wa Mwĩaĩi:'),
('kam', 'COL', 4, 8, 'nake nĩmũtũmĩte oke kwenyu kwondũ wa ũndũ o ũsu, nĩ kana mũmanye ũndũ tũilyĩ, na nĩ kana amũkiakisye ngoo syenyu;'),
('kam', 'COL', 4, 9, 'vamwe na Onesimo, ũla mwana‐a‐asa wĩ na kĩthito na mwendwa, nake nĩ ũmwe wenyu. Makamũtavya maũndũ onthe ala mekawa kũũ.'),
('kam', 'COL', 4, 10, 'Alisitaliko mwovwa vamwe nakwa nĩmwamũkethya, na Maliko, mwĩvae wa Valanava (ũla mwoosie mĩao ũndũ wake; ethĩwa akooka kwenyu mũthokyei),'),
('kam', 'COL', 4, 11, 'na Yesũ, ũla wĩtawa Yusito, nao nĩ andũ ala maĩkawa: asu me oka nĩ atethya ma wĩa vamwe nakwa kwondũ wa ũsumbĩ wa Ngai, andũ ala mangiakiisye.'),
('kam', 'COL', 4, 12, 'Evavila, nake nĩ ũmwe wenyu, ngombo ya Klĩsto Yesũ, nĩwamũkethya, aithetheesya kũvoya kwondũ wenyu mavinda onthe, nĩ kana mũũngame mwĩ ethĩanu na mwĩthĩwe mũte na nzika nongi kwendanĩ kw’onthe kwa Ngai.'),
('kam', 'COL', 4, 13, 'Nũndũ nĩngũmũkũsĩĩa, e na wĩa mwingĩ kwondũ wenyu, na kwondũ wa ala ma Laotisia, na kwondũ wa ala ma Ielavoli.'),
('kam', 'COL', 4, 14, 'Luka, mũiiti ũla mwendwa, na Ndema nĩmamũkethya.'),
('kam', 'COL', 4, 15, 'Ngethesyai ana‐a‐asa ala me Laotisia, na kethyai Nimba, na ĩkanisa yĩla yĩ nyũmbanĩ yake.'),
('kam', 'COL', 4, 16, 'Na valũa ũũ wasomwa kwenyu, twaai ũsomwe naw’o ĩkanisanĩ ya Alaotisia; na inyw’ĩ nenyu mwĩsoma valũa ũla wĩuma Laotisia.'),
('kam', 'COL', 4, 17, 'Na mwĩe Alikivo atĩĩ, Sũvĩa mũno ũthũkũmi ũla wosete nthĩnĩ wa Mwĩaĩi, nĩ kana ũwĩanĩsye.'),
('kam', 'COL', 4, 18, 'Ngethi yakwa, nyie Vaulo nĩngũandĩka na kw’oko kwakwa mwene. Lilikanai kwovwa kwakwa. Mumo nĩwĩthĩwe nenyu.'),
('kam', '1TH', 1, 1, 'Vaulo, na Silivano, na Timotheo, valũa ũũ witũ ũyĩvikĩe ĩkanisa ya Athesalonika yĩla yĩ nthĩnĩ wa Ngai Asa na Mwĩaĩi Yesũ Klĩsto: Mumo nĩwĩthĩwe nenyu na mũuo.'),
('kam', '1TH', 1, 2, 'Nĩtũũmũtũngĩa Ngai mũvea mavinda onthe kwondũ wenyu inyw’onthe, tũkĩmũweta mboyanĩ sitũ;'),
('kam', '1TH', 1, 3, 'tũkĩlilikana tũteũeka wĩa wenyu wa mũĩkĩĩo, na kũthĩnĩa wĩa kwenyu kwa wendo, na wũmĩĩsyo wenyu wa wikwatyo nthĩnĩ wa Mwĩaĩi waitũ Yesũ Klĩsto, mbee wa Ngai Asa waitũ:'),
('kam', '1TH', 1, 4, 'tũkĩmanya, ana‐a‐asa, endwa ma Ngai, kũnyuvwa kwenyu,'),
('kam', '1TH', 1, 5, 'nĩkwĩthĩwa ũvoo mũseo witũ ndwaamũvikia na ndeto syoka, ĩndĩ na vinya, na nthĩnĩ wa Veva Mũtheu, na wĩanĩu wa ũmanyi; o tondũ mwĩsĩ ũndũ mwĩkalile witũ wailyĩ mbee wenyu kwondũ wenyu.'),
('kam', '1TH', 1, 6, 'Nenyu mwatw’ĩka eelekan’ya maitũ, na ma Mwĩaĩi, mwosete ĩla ndeto na ũnyamao mwingĩ, vamwe na ũtanu wa Veva Mũtheu;'),
('kam', '1TH', 1, 7, 'na nũndũ wa ũu mũtw’ĩkĩte ngelekan’yo kwa andũ onthe ala metĩkĩlaa Masetonia na Akaia.'),
('kam', '1TH', 1, 8, 'Nũndũ isyũ ya ndeto ya Mwĩaĩi nĩyĩw’ĩkĩte yumĩte kwenyu, na ti Masetonia na Akaia kw’oka, ĩndĩ kĩla vandũ mũĩkĩĩo wenyu ũla mwi naw’o kwa Ngai nũtũnganĩte; na nũndũ wa ũu tũi na vata wa kũneena ũndũ.'),
('kam', '1TH', 1, 9, 'Nũndũ mo ene nĩmeũtavan’ya ũvoo witũ ũndũ kwailyĩ kũlika kwitũ kwenyu; na ũndũ mweethyũũie kũmweiekela Ngai na kũtia mĩvw’anano, nĩ kana mũthũkũme Ngai ũla wĩ thayũ na ũla wa w’o.'),
('kam', '1TH', 1, 10, 'Na kũmweteela Mwana wake kuma ĩtunĩ, ũla wamũthayũũkisye kũmumya kwa akw’ũ, nake nĩ Yesũ, Mũtũtangiĩi kwa ũthatu ũla wũkĩte.'),
('kam', '1TH', 2, 1, 'Nũndũ inyw’ĩ ene, ana‐a‐asa, nĩmwĩsĩ kũlika kwitũ kwenyu, kana kũiaaĩthĩwa kwa mana:'),
('kam', '1TH', 2, 2, 'ĩndĩ nũndũ nĩtwathĩniw’e mbee na kwĩkwa maũndũ mathũku ndũanĩ ya Vilivi, o ũndũ inyw’ĩ mwĩsĩ, nĩtwongelekile ũkũmbaũ nthĩnĩ wa Ngai waitũ wa kũneena nenyu ũla ũvoo mũseo wa Ngai o na tũkĩsiiĩwa mũno.'),
('kam', '1TH', 2, 3, 'Nũndũ ũtao witũ ti wa kwasya andũ, kana wa ũvuku, kana nthĩnĩ wa ũĩ wa ũkengani:'),
('kam', '1TH', 2, 4, 'ĩndĩ o ũndũ tweetĩkĩlilwe nĩ Ngai tũsũvĩe ũla ũvoo mũseo, nĩw’o tũũneena; ti kwondũ wa kũmendeesya andũ, ĩndĩ nĩ kũmwendeesya Ngai ũla ũoasya ngoo sitũ.'),
('kam', '1TH', 2, 5, 'Nũndũ tũtyaaoneka o na ĩvinda yĩva tũkĩneena ndeto sya kũkathĩĩa andũ, o ũndũ mwĩsĩ, kana kũvw’ĩka wendi wa syĩndũ, Ngai nĩwe ngũsĩ;'),
('kam', '1TH', 2, 6, 'o na tũtyaamantha ndaĩa kuma kwa andũ, o na inyw’ĩ kana andũ angĩ, o na kau twaĩ tũtonya kwĩthĩwa mũio mũito kwenyu nũndũ twaĩ atũmwa ma Klĩsto.'),
('kam', '1TH', 2, 7, 'Ĩndĩ twaĩ auu katĩ wenyu, o tondũ mũei ũsũvĩaa syana syake mwene:'),
('kam', '1TH', 2, 8, 'o ta ũu, tũkĩmwenda na wendo mwingĩ, nĩtweewie mũyo mũno kũmũnenga inyw’ĩ ti ũla ũvoo mũseo wa Ngai w’oka, ĩndĩ o na mathayũ maitũ, nĩkwĩthiwa mũtw’ĩkĩte endwa maitũ.'),
('kam', '1TH', 2, 9, 'Nũndũ nĩmũũlilikana, ana‐a‐asa, kũthĩnĩa wĩa kwitũ na ũnyamao witũ; tũkĩtethya wĩa ũtukũ na mũthenya, nĩ kana tũikethĩwe mũio kwa mũndũ o na wĩva wenyu, twamũtavisye ũla ũvoo mũseo wa Ngai.'),
('kam', '1TH', 2, 10, 'Inyw’ĩ mwi ngũsĩ, o na Ngai nake, ũndũ twekalile kwenyu inyw’ĩ ala mwĩtĩkĩlaa twĩ na mwĩkalĩle wa ũtheu na ũlũngalu na tũtyailĩĩlĩka ũthũku:'),
('kam', '1TH', 2, 11, 'o tondũ mwĩsĩ ũndũ twamwĩkĩe kĩla ũmwe wenyu, ta ũndũ ĩthe wĩkaa syana syake mwene, tũkĩmũtaa, na kũmwĩkĩa vinya ngoonĩ, na kũkũsĩĩa,'),
('kam', '1TH', 2, 12, 'nĩ kana mũendae ũndũ kwaĩle kwa Ngai, ũla ũmwĩtaa mũlike ũsumbĩnĩ na ũtheunĩ wake mũtisu.'),
('kam', '1TH', 2, 13, 'Na kwondũ wa ũu ithyĩ nĩtũmũtũngĩaa Ngai mũvea tũtekũeka, nũndũ yĩla mwoosie kwitũ ĩla ndeto ya ũtũmane wa Ngai, mũtyaamyosa ta ndeto ya andũ, ĩndĩ, o ũndũ ĩtilyĩ w’o, ndeto ya Ngai, ĩla nayo ĩtethasya wĩa nthĩnĩ wenyu ala mwĩtĩkĩlaa.'),
('kam', '1TH', 2, 14, 'Nũndũ inyw’ĩ, ana‐a‐asa, nĩmũtw’ĩkĩte eelekan’ya ma makanisa ma Ngai ala me Yutia nthĩnĩ wa Klĩsto Yesũ: nĩkwĩthĩwa inyw’ĩ nĩmwathĩniw’e nĩ andũ ma nthĩ yenyu, o mathĩna ala mathĩniw’e namo nĩ Ayuti;'),
('kam', '1TH', 2, 15, 'ala mamũaie Mwĩaĩi Yesũ na athani, na matũlũngya ithyĩ, na maimwendeeasya Ngai, na nĩmakananĩasya andũ onthe;'),
('kam', '1TH', 2, 16, 'makĩtũvata kũneena na Andũ‐ma‐mbaĩ‐ingĩ matangĩĩwe: nĩ kana meanĩsye naĩ syoo mavinda onthe: ĩndĩ ũthatu nũmavikĩe kũvika ũminũkĩlyo.'),
('kam', '1TH', 2, 17, 'Ĩndĩ ithyĩ, ana‐a‐asa, twataanĩsya nenyu ĩvinda ĩnini, kwa mwĩĩ na ti ngoonĩ, nĩtwatatie mũno na kwenda kũnene kwona mothyũ menyu:'),
('kam', '1TH', 2, 18, 'nĩkwĩthĩwa nĩtwendie kũka kwenyu, nyie Vaulo ti ĩvinda yĩmwe; na Satani atũsiĩĩa.'),
('kam', '1TH', 2, 19, 'Nũndũ wĩkwatyo witũ, kana ũtanu witũ, kana ngovia ya ũsumbĩ yaitũ ya kwĩkathĩĩa kwitũ nĩ kyaũ? Ti o inyw’ĩ, mbee wa Mwĩaĩi waitũ Yesũ ĩvinda ya kũka kwake?'),
('kam', '1TH', 2, 20, 'Nũndũ inyw’ĩ mwĩ ũtaĩo witũ na ũtanu witũ.'),
('kam', '1TH', 3, 1, 'Kwondũ wa ũu yĩla twaĩ tũtatonya kũmĩĩsya mbee wa ũu, nĩtwoonie nĩ ũseo tũtiwe Athene ithyoka;'),
('kam', '1TH', 3, 2, 'na twamũtũma Timotheo, mwana‐a‐asa waitũ na mũthũkũmi wa Ngai ũvoonĩ mũseo wa Klĩsto, amũlũlũmĩlye, na kũmũkiakisya mũĩkĩĩonĩ wenyu;'),
('kam', '1TH', 3, 3, 'nĩ kana kũikethĩwe mũndũ o na wĩva kũthingithangw’a nĩ mathĩna aa; nĩkwĩthĩwa inyw’ĩ ene nĩmwĩsĩ nĩmo twiĩwe.'),
('kam', '1TH', 3, 4, 'Nũndũ nĩ w’o, yĩla twaĩ nenyu, nĩtwamũtavisye mbee kana tũkathĩnw’a; o tondũ kweekĩkie, nenyu nĩmwĩsĩ.'),
('kam', '1TH', 3, 5, 'Kwondũ wa ũu nyie nakwa, yĩla ndaĩ ndonya kũmĩĩasya ĩngĩ, natũmanie nĩ kana nĩmanye mũĩkĩĩo wenyu, kana ũla mũtati nĩwĩthĩwa amũtatie inyw’ĩ na ũndũ o na wĩva, na wĩa witũ ũla twathĩnĩaa ũkethĩwa wĩ wa mana.'),
('kam', '1TH', 3, 6, 'Ĩndĩ yu yĩla Timotheo woka kwitũ kuma kwenyu, na atũetee ũvoo mũseo wa mũĩkĩĩo wenyu na wendo, na ĩngĩ kana mũtũlilikanaa nesa mavinda onthe, mwĩ na mea ma kũtwona, o ũndũ naitũ twĩ na mea ma kũmwona;'),
('kam', '1TH', 3, 7, 'kwondũ wa ũu, ana‐a‐asa, nĩtũkiakiiw’e kwondũ wenyu thĩnanĩ na ũnyamaonĩ witũ w’onthe kwondũ wa mũĩkĩĩo wenyu:'),
('kam', '1TH', 3, 8, 'nũndũ yu twĩ thayũ ethĩwa inyw’ĩ nĩmũkũũngama na ũlũmu nthĩnĩ wa Mwĩaĩi.'),
('kam', '1TH', 3, 9, 'Nũndũ nĩ mũvea wĩva ũla tũtonya kũmũtũngĩa Ngai kwondũ wenyu, nũndũ wa ũtanu w’onthe ũla tũtanaa kwondũ wenyu mbee wa Ngai waitũ;'),
('kam', '1TH', 3, 10, 'tũkĩvoya mũno ũtukũ na mũthenya nĩ kana tũtonye kwona mothyũ menyu, na kwĩanĩsya kĩla kĩtiele mũĩkĩĩonĩ wenyu?'),
('kam', '1TH', 3, 11, 'Na yu Ngai mwene Asa waitũ, na Mwĩaĩi waitũ Yesũ, natũtongoesye nzĩanĩ yaitũ tũvike kwenyu;'),
('kam', '1TH', 3, 12, 'na Mwĩaĩi namwongeleele na kũmwingĩvĩsya wendo inyw’ĩ kwa inyw’ĩ, na kwa andũ onthe, o ũndũ naitũ tũilyĩ kwenyu;'),
('kam', '1TH', 3, 13, 'nĩ kana atonye kũlũlũmĩlya ngoo syenyu syĩkalae itailĩĩlĩka ũthũku ũtheunĩ mbee wa Ngai Asa waitũ, ĩvinda ya kũka kwa Mwĩaĩi Yesũ vamwe na atheu make onthe.'),
('kam', '1TH', 4, 1, 'Kũminũkĩlya ĩndĩ, ana‐a‐asa, nĩtũũmwĩsũva na kũmũtaa nthĩnĩ wa Mwĩaĩi Yesũ, kana, o ũndũ mwoosie kwitũ ũndũ mwaĩlwe nĩ kũendaa na kũmwendeesya Ngai, o ũndũ mũendaa, kana mwongeleele ũu mũno mbee.'),
('kam', '1TH', 4, 2, 'Nũndũ nĩmwĩsĩ mĩao ĩla twamũnengie kwondũ wa Mwĩaĩi Yesũ.'),
('kam', '1TH', 4, 3, 'Nũndũ ũũ nĩw’o ũla wendetwe nĩ Ngai, naw’o nĩ kũvathwa kwenyu mwĩthĩwe atheu, nĩ kana mwĩvathane na ũlaalai;'),
('kam', '1TH', 4, 4, 'kana kĩla ũmwe wenyu amanye ũndũ wa kwĩkalya mwĩĩ wake mwene kũvathwanĩ na ndaĩanĩ,'),
('kam', '1TH', 4, 5, 'ti nthĩnĩ wa wendi mũthũku, o ta Andũ‐ma‐mbaĩ‐ingĩ ala matamwĩsĩ Ngai;'),
('kam', '1TH', 4, 6, 'nĩ kana mũndũ o na wĩva ndakavĩtye, na kũmwĩka mwana‐a‐ĩthe naĩ ũndũnĩ ũsu: nĩkwĩthĩwa Mwĩaĩi nĩ mũĩvanĩsya maũndũnĩ asu onthe, o ũndũ twamwonisye mbee na twakũsĩĩa.'),
('kam', '1TH', 4, 7, 'Nĩkwĩthĩwa Ngai ndaatwĩtĩa ũvuku, ĩndĩ nĩ kũvathwa.'),
('kam', '1TH', 4, 8, 'Kwondũ wa ũu ũla ũnũũlea, ndeũmũlea mũndũ, ĩndĩ emũlea Ngai, ũla ũmũnengae inyw’ĩ Veva Mũtheu wake.'),
('kam', '1TH', 4, 9, 'Ĩndĩ ũndũ wa wendano wa ana‐a‐asa mũi na vata wa mũndũ kũmũandĩkĩa: nũndũ inyw’ĩ ene nĩmũmanyĩaw’a nĩ Ngai kwendana ene kwa ene;'),
('kam', '1TH', 4, 10, 'nũndũ nĩ w’o nĩmwĩkaa ũndũ ũũ kwa ana‐a‐asa onthe ala me Masetonia kw’onthe. Ĩndĩ nĩtũũmwĩsũva, ana‐a‐asa, nĩ kana mwongeleele ũu mũno mbee;'),
('kam', '1TH', 4, 11, 'na nĩ kana mwĩmanyĩsye kwĩthĩwa na ũuu, na kwĩka maũndũ menyu ene, na kũtethya wĩa na moko menyu, o ũndũ twamwĩaĩe;'),
('kam', '1TH', 4, 12, 'nĩ kana mũendae ũndũ waĩle mbee wa ala me ũtee, na ĩngĩ mũikethĩwe na vata wa kĩndũ o na kĩva.'),
('kam', '1TH', 4, 13, 'Ĩndĩ, ana‐a‐asa, tũikwenda mũlee kũmanya ũvoo wa ala makomaa; nĩ kana mũtikethĩwe na kĩmako, ta ala angĩ mate na wĩkwatyo.'),
('kam', '1TH', 4, 14, 'Nũndũ ethĩwa nĩtũkwĩtĩkĩla kana Yesũ nĩwakwie na athayũũka ĩngĩ, o ta ũu nao ala makomete nthĩnĩ wa Yesũ, Ngai akamaete vamwe nake.'),
('kam', '1TH', 4, 15, 'Nũndũ ũũ nĩtũũmũtavya kwondũ wa ndeto ya Mwĩaĩi, kana ithyĩ ala twĩ thayũ, ala tũkatiala kũvika kũka kwa Mwĩaĩi, tũikamatongoesya nongi ala makomie.'),
('kam', '1TH', 4, 16, 'Nĩkwĩthĩwa Mwĩaĩi mwene akatheea kuma ĩtunĩ, na wasya mũtũlu, na wasya wa mũlaĩka mũnene, na soo wa Ngai: na ala makwie nthĩnĩ wa Klĩsto makathayũũka mbee;'),
('kam', '1TH', 4, 17, 'na ĩndĩ ĩtina ithyĩ ala twĩ thayũ ala twatialile, tũkavulw’a vamwe nao mathweonĩ, kũmũthaũa Mwĩaĩi yayayanĩ: na ũu tũkeethĩwa vamwe na Mwĩaĩi tene na tene.'),
('kam', '1TH', 4, 18, 'Kwondũ wa ũu kiakianasyai na ndeto ii.'),
('kam', '1TH', 5, 1, 'Ĩndĩ ũndũ wa mavinda na syathĩ, ana‐a‐asa, mũi na vata kũandĩkiwa ũndũ.'),
('kam', '1TH', 5, 2, 'Nũndũ inyw’ĩ ene nĩmwĩsi vyũ kana mũthenya wa Mwĩaĩi wĩũka o ũndũ kĩng’ei kyũkaa ũtukũ.'),
('kam', '1TH', 5, 3, 'Ĩvinda yĩla mekwasya, Kwĩ mũuo na vai mũisyo, o ĩvinda yĩu nĩw’o wanangĩko wĩũka ĩũlũ woo mĩtũkĩ, o tondũ woo wa kwaũnya ũkwataa mũndũ mũka wĩ ĩvu; na maikavonoka nongi.'),
('kam', '1TH', 5, 4, 'Ĩndĩ inyw’ĩ, ana‐a‐asa, mũi kĩvindunĩ, ũndũ mũthenya ũsu ũmũvikĩa ta kĩng’ei:'),
('kam', '1TH', 5, 5, 'nũndũ inyw’onthe mwĩ ana ma kyeni, na ana ma mũthenya: ithyĩ tũi ma ũtukũ kana ma kĩvindu;'),
('kam', '1TH', 5, 6, 'nũndũ wa ũu tũikakome, ta ala angĩ, ĩndĩ tũsyaĩĩsye na kwĩthĩwa na wĩting’o.'),
('kam', '1TH', 5, 7, 'Nũndũ ala makomaa, makomaa ũtukũ; na ala matoonaa, matoonaa ũtukũ.'),
('kam', '1TH', 5, 8, 'Ndĩ ithyĩ, nũndũ twĩ ma mũthenya, twĩthĩwe na wĩting’o, tũkĩkĩa ngao ya kĩthũi ya mũĩkĩĩo na wendo; na ngovia yĩthĩwe nĩyo wĩkwatyo wa ũtangĩĩo.'),
('kam', '1TH', 5, 9, 'Nũndũ Ngai ndaatwia twĩthĩwe ma kũthatĩwa, ĩndĩ ma kwosa ũtangĩĩo kwondũ wa Mwĩaĩi waitũ Yesũ Klĩsto,'),
('kam', '1TH', 5, 10, 'ũla wakwie nũndũ witũ, nĩ kana, ethĩwa nĩtũamũkĩte kana kũkoma, twĩthĩwe thayũ vamwe nake.'),
('kam', '1TH', 5, 11, 'Kwondũ wa ũu kiakian’yai, na kĩla mũndũ akyaka ũla ũngĩ, o ũndũ mwĩkaa.'),
('kam', '1TH', 5, 12, 'Ĩndĩ nĩtũũmwĩsũva, ana‐a‐asa, mũmanye ala mathĩnĩaa wĩa katĩ wenyu, na me ĩũlũ wenyu nthĩnĩ wa Mwĩaĩi, na mamũtaaa inyw’ĩ;'),
('kam', '1TH', 5, 13, 'na kũmataĩa mũno nthĩnĩ wa wendo kwondũ wa wĩa woo. Ĩthĩwai na mũuo inyw’ĩ kwa inyw’ĩ.'),
('kam', '1TH', 5, 14, 'Na nĩtũũmũtaa, ana‐a‐asa, mataaei ala matekalaa nesa, mekĩaei vinya ala me na ngoo mbũthũ, tw’ĩĩkaai ala onzu, ũmĩanĩasyai na andũ onthe.'),
('kam', '1TH', 5, 15, 'Sisyai kana mũndũ o na wĩva ndakekũle kwa ũngĩ; ĩndĩ mavinda onthe atĩĩaai ũla ũseo, ene kwa ene, na kwa onthe.'),
('kam', '1TH', 5, 16, 'Tanaai mavinda onthe;'),
('kam', '1TH', 5, 17, 'voyaai mũtekũeka;'),
('kam', '1TH', 5, 18, 'tũngaai mũvea kĩla ũndũnĩ: nũndũ ũu nĩw’o Ngai wendaa nthĩnĩ wa Klĩsto Yesũ ngalĩ ĩ yenyu.'),
('kam', '1TH', 5, 19, 'Mũikamũvosye Veva;'),
('kam', '1TH', 5, 20, 'mũikavũthye mawathani;'),
('kam', '1TH', 5, 21, 'oasyai maũndũ onthe; lũmasyai ũla ũseo;'),
('kam', '1TH', 5, 22, 'ĩvathanaei na kĩla mũthemba wa ũthũku.'),
('kam', '1TH', 5, 23, 'Na Ngai wa mũuo mwene namũvathan’ye mwĩthĩwe atheu vyũ; veva na ngoo na mwĩĩ syĩthĩwe syĩ nima, itailĩĩlĩka ũthũku akyũka Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', '1TH', 5, 24, 'E na kĩthito ũla ũmwĩtaa inyw’ĩ, nake akeeka ũu.'),
('kam', '1TH', 5, 25, 'Ana‐a‐asa, tũvoyeei.'),
('kam', '1TH', 5, 26, 'Kethyai ana‐a‐asa onthe na ũmumunyano mũtheu.'),
('kam', '1TH', 5, 27, 'Nĩngũmwĩavĩthya kwa Mwĩaĩi nĩ kana valũa ũũ ũsomewe ana‐a‐asa onthe.'),
('kam', '1TH', 5, 28, 'Mumo wa Mwĩaĩi waitũ Yesũ Klĩsto nĩwĩthĩwe vamwe nenyu.'),
('kam', '2TH', 1, 1, 'Vaulo, na Silivano, na Timotheo, valũa ũũ witũ ũyĩvikĩe ĩkanisa ya Athesalonika yĩla yĩ nthĩnĩ wa Ngai Asa waitũ na Mwĩaĩi Yesũ Klĩsto;'),
('kam', '2TH', 1, 2, 'Mumo nĩwĩthiwe nenyu na mũuo kuma kwa Ngai Asa na Mwĩaĩi Yesũ Klĩsto.'),
('kam', '2TH', 1, 3, 'Nĩtwaĩlwe nĩ kũmũtũngĩa Ngai mũvea mavinda onthe kwondũ wenyu, ana‐a‐asa, o tondũ kwaĩle nĩkwĩthĩwa mũĩkĩĩo wenyu nũkwĩana mũno, na wendo wa kĩla ũmwe wenyu kwa ala angĩ nũkwingĩva;'),
('kam', '2TH', 1, 4, 'ũndũ ithyĩ ene nĩtũkwĩkathĩĩa ũndũ wenyu makanisanĩ ma Ngai, kwondũ wa wũmĩĩsyo wenyu na mũĩkĩĩo monyamaonĩ menyu onthe na mathĩnanĩ ala mũmĩĩasya;'),
('kam', '2TH', 1, 5, 'naw’o nĩ wonan’yo wa ũsilĩlo mũlũngalu wa Ngai; ni kana inyw’ĩ mũtonye kũtalĩlwa kwĩthĩwa mwaĩle ũsumbĩ wa Ngai, ũla kwondũ waw’o mũthĩnaw’a:'),
('kam', '2TH', 1, 6, 'nũndũ nĩ ũlũngalu kwa Ngai kũmaĩva mathĩna ala mamũthĩnasya inyw’ĩ,'),
('kam', '2TH', 1, 7, 'na kũmũnenga inyw’ĩ ala mũthĩnaw’a ũthũmũo vamwe naitũ, ĩvinda yĩla Mwĩaĩi Yesũ ũkavuanw’a kuma ĩtunĩ vamwe na alaĩka ma vinya wake ũlĩlĩnzĩnĩ wa mwaki,'),
('kam', '2TH', 1, 8, 'akĩĩvanĩsya kwa ala matamwĩsĩ Ngai, na ala matawiw’aa ũvoo mũseo wa Mwĩaĩi waitũ Yesũ:'),
('kam', '2TH', 1, 9, 'ala makona ũsilĩlo, naw’o ni wanangĩko ũtakathela, kũvetwe ũthyũni wa Mwĩaĩi na ũtheuni mũtisu wa vinya wake,'),
('kam', '2TH', 1, 10, 'yĩla ũkoka kũtaĩĩwa nthĩnĩ wa atheu make na kũseng’ewa mũthenya ũsu nthĩnĩ wa onthe ala metĩkĩlĩte (nĩkwĩthĩwa ũkũsĩ witũ kwenyu nĩweetĩkililwe).'),
('kam', '2TH', 1, 11, 'Na kwondũ wa ũu nĩtũmũvoyeaa inyw’ĩ mavinda onthe, kana Ngai waitũ amũtale mwaĩle kwĩtwa kwenyu, na kwĩanĩsya na vinya wake kĩla kwenda kwa ũseo na kĩla wĩa wa mũĩkĩĩo;'),
('kam', '2TH', 1, 12, 'nĩ kana syitwa ya Mwĩaĩi waitũ Yesũ yĩtaĩwe nthĩni wenyu, nenyu nthĩnĩ wake, kwĩanana na mumo wa Ngai waitũ na Mwĩaĩi Yesũ Klĩsto.'),
('kam', '2TH', 2, 1, 'Ĩndĩ nĩtũũmwĩsũva, ana‐a‐asa, ũndũ wa ũvoo wa kũka kwa Mwĩaĩi waitũ Yesũ Klĩsto, na kũmbanĩa kwitũ mbee wake;'),
('kam', '2TH', 2, 2, 'nĩ kana mũikathingithw’e na mĩtũkĩ ilĩkonĩ syenyu, kana mũikaũũye, o na ethĩwa nĩ kwondũ wa veva, o na ndeto, o na valũa ũũtalwa ta wumĩte kwitũ ta mũthenya wa Mwĩaĩi nĩ mũviku;'),
('kam', '2TH', 2, 3, 'mũndũ o na wĩva ndakamũkenge na ũndũ o na wĩva: nũndũ mũthenya ũsu ndũkoka, ũalyũko ũtambĩte kũka, na ũla mũndũ wa naĩ kũvuanw’a, mwana wa wanangĩko,'),
('kam', '2TH', 2, 4, 'ũla wĩsiĩĩa na kwĩnenevya mwene ĩũlũ wa kyonthe kĩla kĩtawa Ngai kana kĩla kĩthaithawa; ũndũ wĩĩkalaa ĩkalũnĩ ya Ngai, akĩyonan’ya ta nĩwe Ngai.'),
('kam', '2TH', 2, 5, 'Mũtiũlilikana, kana, yĩla naĩ nenyu, namũtavisye maũndũ asu?'),
('kam', '2TH', 2, 6, 'Na yu nĩmwĩsĩ kĩla kĩsiĩĩaa, nĩ kana atonye kũvuanw’a ĩvinda yake mwene.'),
('kam', '2TH', 2, 7, 'Nĩkwĩthĩwa ĩla nzama ya ũng’endu yu nĩnĩũtethya wĩa: ĩndĩ kwĩ ũmwe ũla ũsiĩĩaa yu, kũvika yĩla ũkathũkw’a nzĩanĩ.'),
('kam', '2TH', 2, 8, 'Nĩvo ĩndĩ ũla mũng’endu ũkavuanw’a, ũla Mwĩaĩi Yesũ wĩmũaa na mĩthũmũ ya kanyw’a wake, na kũmwananga na ũvuan’yo wa kũka kwake;'),
('kam', '2TH', 2, 9, 'ũla kũka kwake nĩ kwĩanana na kwĩka kwa Satani na vinya w’onthe na syama na moseng’yo ma ũvũngũ,'),
('kam', '2TH', 2, 10, 'na ũkengani w’onthe wa ũla ũte ũlũngalu kwa ala maaa; nĩkwĩthĩwa matyaaosa wendo wa ũla w’o, nĩ kana matangĩĩwe.'),
('kam', '2TH', 2, 11, 'Na kwondũ wa ũu Ngai nũmaeteae vinya wa kũmasya, nĩ kana metĩkĩle ũvũngũ:'),
('kam', '2TH', 2, 12, 'nĩ kana onthe masilĩlwe ala maleile kwĩtĩkĩla ũla w’o, ĩndĩ nĩmatanĩe ũla ũte ũlũngalu.'),
('kam', '2TH', 2, 13, 'Ĩndĩ nĩtwaĩlwe nĩ kũmũtũngĩa Ngai mũvea mavinda onthe kwondũ wenyu, ana‐a‐asa, endwa ma Mwĩaĩi, nĩkwĩthĩwa Ngai nĩwamũnyuvie inyw’ĩ kuma mwambĩlĩlyonĩ mwone ũtangĩĩo kwondũ wa kũvathwa nĩ Veva na kwĩtĩkĩla ũla w’o:'),
('kam', '2TH', 2, 14, 'nake amwĩtĩe ũndũ ũsu kwondũ wa ũvoo mũseo witũ, mwose ũtheu mũtisu wa Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', '2TH', 2, 15, 'Kwondũ wa ũu ĩndĩ, ana‐a‐asa, ũngamai na ũlũmu, na kũkwata momanyĩsyo ala mũmanyĩĩtw’e, ethĩwa nĩ ndeto, kana nĩ valũa witũ.'),
('kam', '2TH', 2, 16, 'Na yu Mwĩaĩi waitũ Yesũ Klĩsto mwene, na Ngai Asa waitũ ũla watwendie na kũtũnenga ũkiakisyo ũtathela na wĩkwatyo mũseo kwondũ wa mumo,'),
('kam', '2TH', 2, 17, 'nakiakisye ngoo syenyu na kwilũlũmĩlya nthĩnĩ wa kĩla wĩa mũseo na ndeto.'),
('kam', '2TH', 3, 1, 'Kũminũkĩlya, ana‐a‐asa, tũvoyeei, kana ndeto ya Mwĩaĩi ĩtonye ũthi ĩsembete na kũtaĩwa, o ũndũ ĩtilyĩ kwenyu;'),
('kam', '2TH', 3, 2, 'na kana tũtangĩĩwe kwa andũ mbaa matũ na andũ athe; nũndũ ti andũ onthe me na mũĩkĩĩo.'),
('kam', '2TH', 3, 3, 'Ĩndĩ Mwĩaĩi e na kĩthito, nake akamũlũlũmĩlya, na kũmũsũvĩa kwa ũla mũthũku.'),
('kam', '2TH', 3, 4, 'Na nĩtũũmũĩkĩĩa Mwĩaĩi kwondũ wenyu, kana nĩmũkwĩka maũndũ ala tũmwĩaĩaa na mũkamekaa.'),
('kam', '2TH', 3, 5, 'Na Mwĩaĩi natongoesye ngoo syenyu ilike wendonĩ wa Ngai, na wũmĩĩsyonĩ wa Klĩsto.'),
('kam', '2TH', 3, 6, 'Nĩtũũmwĩaĩa, ana‐a‐asa, syĩtwanĩ ya Mwĩaĩi waitũ Yesũ Klĩsto, kana mwĩvathane na kĩla mwana‐a‐asa ũla ũvikĩlaa maũndũ mataĩle, na ti kũvikĩla ũmanyĩsyo ũla mwoosie kwitũ.'),
('kam', '2TH', 3, 7, 'Nũndũ inyw’ĩ ene nĩmwĩsĩ ũndũ mwaĩlwe nĩ kwĩelekan’ya naitũ: nĩkwĩthĩwa tũtyaavikĩla maũndũ mataĩle yĩla twaĩ kwenyu:'),
('kam', '2TH', 3, 8, 'o na tũtyaaya lĩu wa mũndũ o na wĩva mana, ĩndĩ wĩanĩ wĩ vinya na ũnyamaonĩ, ũtukũ na mũthenya twatethisye wĩa, nĩ kana tũikamũtw’ĩkĩe mũio mũndũ o na wĩva kwenyu:'),
('kam', '2TH', 3, 9, 'ti kwĩthĩwa tũti na ũkũmũ, ĩndĩ nĩ kana twĩtw’ĩkĩthye ngelekan’yo kwenyu, nĩ kana inyw’ĩ mwĩelekanasye naitũ.'),
('kam', '2TH', 3, 10, 'Nũndũ o yĩla twaĩ nenyu, nĩtwamwĩaĩe ũũ. Ethĩwa mũndũ o na wĩva ndekwenda kũtethya wĩa, o na kũya, ndakaye.'),
('kam', '2TH', 3, 11, 'Nũndũ nĩtũkwĩw’a ũvoo wa andũ amwe ala maendaa katĩ wenyu ũndũ ũtaĩle, ala matatethasya wĩa nongi, ĩndĩ nĩ elikya maũndũnĩ ma andũ angĩ.'),
('kam', '2TH', 3, 12, 'Na ala mailyĩ ũu nĩtũũmeaĩa na kũmataa nthĩnĩ wa Mwĩaĩi Yesũ Klĩsto, kana matethye wĩa mauĩtye, na kũya lĩu woo ene.'),
('kam', '2TH', 3, 13, 'Ĩndĩ inyw’ĩ, ana‐a‐asa, mũikanoe nĩ kwĩka nesa.'),
('kam', '2TH', 3, 14, 'Na ethĩwa mũndũ o na wĩva ndew’aa ndeto yaitũ ya valũa ũũ, mũsisyei mũndũ ũsu, mũikavulane nake, nĩ kana asonoke.'),
('kam', '2TH', 3, 15, 'Ĩndĩ mũikamũtale kwĩthĩwa nĩ mũmaitha, ĩndĩ mũtaei ta mwana‐a‐asa.'),
('kam', '2TH', 3, 16, 'Na yu Mwĩaĩi wa mũuo we mwene namũnenge mũuo mavinda onthe maũndũnĩ onthe. Mwĩaĩi nĩethĩwe vamwe nenyu inyw’onthe.'),
('kam', '2TH', 3, 17, 'Ngethi yakwa, nyie Vaulo, na kw’oko kwakwa mwene, naw’o nĩ ũvano kĩla valũanĩ; ũu nĩw’o nĩandĩkaa.'),
('kam', '2TH', 3, 18, 'Mumo wa Mwĩaĩi waitũ Yesũ Klĩsto nĩwĩthĩwe vamwe nenyu inyw’onthe.'),
('kam', '1TI', 1, 1, 'Vaulo, mũtũmwa wa Klĩsto Yesũ kwĩanana na mwĩao wa Ngai Mũtangĩĩi waitũ, na Klĩsto Yesũ wĩkwatyo witũ;'),
('kam', '1TI', 1, 2, 'valũa ũũ wakwa ũmũvikĩe Timotheo, mwana wakwa wa w’o nthĩnĩ wa mũĩkĩĩo: Mũmo, na tei, na mũuo, kuma kwa Ngai Asa na Klĩsto Yesũ Mwĩaĩi waitũ.'),
('kam', '1TI', 1, 3, 'O tondũ nakwĩsũvie wĩkale Eveso, yĩla naendete Masetonia, nĩ kana ũtonye kwĩaĩa andũ amwe maikamanyĩsye ũmanyĩsyo wa mũthemba ũngĩ,'),
('kam', '1TI', 1, 4, 'o na maikethukĩĩsye mbano na ũsyaanĩo ũte na mũminũkĩlyo, namo maetae mokũlangyo, na ti walan’yo wa Ngai ũla wĩ kwondũ wa mũĩkĩĩo; na yu nĩkwĩaĩa o ũũ.'),
('kam', '1TI', 1, 5, 'Ĩndĩ mũminũkĩlyo wa wĩaĩi ũsu nĩ wendo ũla wumaa ngoonĩ ntheu na wasyanĩ mũseo wa ngoo na mũĩkĩĩo ũte na wangangan’yo:'),
('kam', '1TI', 1, 6, 'na amwe makĩvĩtya maũndũnĩ asu nĩmathũkĩte ũtee kũvika kũneena mana;'),
('kam', '1TI', 1, 7, 'makyenda kwĩthĩwa amanyĩsya ma ĩla mĩao, o na kau maiũmanya maũndũ asu ala maneenaa, o na kĩtina kya maũndũ ala maneenaa ta mamesĩ vyũ.'),
('kam', '1TI', 1, 8, 'Ĩndĩ ithyĩ nĩtwĩsĩ kana ĩla mĩao nĩ mĩseo, ethĩwa mũndũ ekaa nayo ũndũ ũmyaĩle.'),
('kam', '1TI', 1, 9, 'Akĩmanya ũũ, kana ĩla mĩao ti kwondũ wa mũndũ mũlũngalu, ĩndĩ nĩ kwondũ wa ala maleaa mĩao na ala ang’endu, nũndũ wa ala mateũmũkĩa Ngai na ala athe, nũndũ wa ala mate atheu na ala avuku, nũndũ wa ala moaa aaĩthe na ala moaa aainyia, na nũndũ wa oai,'),
('kam', '1TI', 1, 10, 'nũndũ wa ilaalai, na aũme ala mekaa naĩ na aũme angĩ, nũndũ wa ala moyaa andũ, nũndũ wa aneeni ma ũvũngũ, nũndũ wa ala mevĩtaa ũvũngũ, na ethĩwa ve ũndũ ũngĩ ũtosana na momanyĩsyo ala ma w’o;'),
('kam', '1TI', 1, 11, 'kwĩanana na ũvoo mũseo wa ũtheu mũtisu wa Ngai ũla mũtaĩwa, ũvoo ũla naĩkĩĩiwe nĩsũvĩe.'),
('kam', '1TI', 1, 12, 'Nĩmũtũngĩa mũvea ũla wandonyethisye, nake nĩ Klĩsto Yesũ Mwĩaĩi waitũ, nũndũ nĩwandalile kwĩthĩwa na kĩthito akĩndw’a wa kũmũthũkũma;'),
('kam', '1TI', 1, 13, 'o na kau na vu tene naĩ mũumi wa Ngai, na mũthĩn’ya wa andũ, na kũmeka naĩ: ĩndĩ nĩneew’ĩwe tei, nũndũ nĩneekie ndesĩ ndanamba kwĩtĩkĩla;'),
('kam', '1TI', 1, 14, 'na mumo wa Mwĩaĩi waitũ waingĩvie mũno vamwe na mũĩkĩĩo na wendo ũla wĩ nthĩnĩ wa Klĩsto Yesũ.'),
('kam', '1TI', 1, 15, 'Nĩ ndeto ya kũĩkĩĩwa, na nĩyaĩlwe nĩ kwĩtĩkĩlwa nĩ andũ onthe, kana Klĩsto Yesũ ookie kũũ nthĩ kũmatangĩĩa andũ athe; na ũla wa mbee woo, ninyie:'),
('kam', '1TI', 1, 16, 'ĩndĩ kwondũ wa ũu nĩneew’ĩwe tei, kana nthĩnĩ wakwa, nyie ũla mũthũku mbee, Yesũ Klĩsto atonye kumĩlya wũmĩĩsyo wake w’onthe, kwondũ wa ngelekan’yo kwa ala makamwĩtĩkĩla ĩtina methĩwe na thayũ ũtathela.'),
('kam', '1TI', 1, 17, 'Na yu kwa Mũsumbĩ wa tene na tene, ũla ũtanangĩkaa, na ũtonekaa, Ngai ũla wĩ weka, kwĩthĩwe nguma na ndaĩa tene na tene. Ameni.'),
('kam', '1TI', 1, 18, 'Wĩaĩi ũũ nĩngũtia naku, mwana wakwa Timotheo, kwianana na ndeto sya athani ila syatongoisye mbee waku, nĩ kana kwondũ wasyo ũtonye kũkita kaũ ũla mũseo;'),
('kam', '1TI', 1, 19, 'ũikwata mũĩkĩĩo na wasya mũseo wa ngoo; ũla amwe maluutĩte kũasa namo na makaa mũĩkĩĩonĩ woo, tondũ andũ maaa ngalawa yaanangĩka:'),
('kam', '1TI', 1, 20, 'amwe ma asu nĩ Aimenaio na Alesanda; nao namũnengie Satani, nĩ kana mamanyĩw’e maikamũume Ngai.'),
('kam', '1TI', 2, 1, 'Ĩndĩ, mbee wa maũndũ onthe, nĩngwĩsũva kana kwĩsũvana, na kũvoya, na kũvoyea, na kũtũnga mũvea, kwĩkawe kwondũ wa andũ onthe;'),
('kam', '1TI', 2, 2, 'kwondũ wa asumbĩ na onthe me na ũnene; nĩ kana twĩthĩwe na thayũ mũuu na mũuo katĩ wa kũmũkĩa Ngai kw’onthe na mwĩkalo mũseo.'),
('kam', '1TI', 2, 3, 'Ũndũ ũũ nĩ ũseo na nĩwĩtĩkĩlawa kwa Ngai Mũtangĩĩi waitũ;'),
('kam', '1TI', 2, 4, 'ũla wendaa andũ onthe matangĩĩwe, na moke mamanye ũla w’o.'),
('kam', '1TI', 2, 5, 'Nũndũ Ngai no ũmwe, na mwĩw’anĩthya katĩ wa Ngai na andũ no ũmwe, nake nĩ mũndũ, Klĩsto Yesũ,'),
('kam', '1TI', 2, 6, 'ũla wenenganie ethĩwe mbovosya ya andũ onthe; ũkũsĩ ũkaumĩlwa mavindanĩ maw’o;'),
('kam', '1TI', 2, 7, 'naw’o kwondũ waw’o nyie niĩtwe nĩthĩwe mũtavan’ya na mũtũmwa (nĩneena w’o, ndiũneena ũvũngũ), mũmanyĩsya wa Andũ‐ma‐mbaĩ‐ingĩ nthĩnĩ wa mũĩkĩĩo na wa ũla w’o.'),
('kam', '1TI', 2, 8, 'Kwondũ wa ũu, nĩenda aũme mavoyae kĩla vandũ, makyũkĩlya moko matheu, vate ũthatu na ngananĩo.'),
('kam', '1TI', 2, 9, 'Na aka no ta ũu, meyanakavye na kwĩvw’ĩka ngũa imaĩle, vamwe na wĩnyivyo na kĩlĩko; ti na nzw’ĩĩ mbokothe, na thaavu kana lũlũ kana ngũa sya thooa mũnene;'),
('kam', '1TI', 2, 10, 'ĩndĩ mevw’ĩke meko maseo (o ũndũ ũmaĩle aka ala maumbũlaa kũmũkĩa Ngai).'),
('kam', '1TI', 2, 11, 'Mũndũ mũka emanyĩsye auĩtye na wĩnyivyo w’onthe.'),
('kam', '1TI', 2, 12, 'Ĩndĩ ndĩũmũnenga mũndũ mũka ũthei wa kũmanyĩsya, kana kũsumbĩka mũndũ mũũme, ĩndĩ nĩethĩwe auĩtye.'),
('kam', '1TI', 2, 13, 'Nũndũ Atamu oombiwe mbee, na Eva ĩtina;'),
('kam', '1TI', 2, 14, 'na Atamu ndaakengwa, ĩndĩ mũka akengwa nĩwavalũkile ĩvĩtyonĩ:'),
('kam', '1TI', 2, 15, 'ĩndĩ akatangĩĩwa aisyaa syana, ethĩwa makekala mũĩkĩĩonĩ na wendonĩ na ũtheunĩ vamwe na kilĩko.'),
('kam', '1TI', 3, 1, 'Ndeto nĩ ya kwĩtĩkĩlwa, Ethĩwa mũndũ eenda wĩa wa mũsyaĩĩsya wa ĩkanisa, eenda wĩa mũseo.'),
('kam', '1TI', 3, 2, 'Mũsyaĩĩsya ĩndĩ mũvaka ethĩwe ataweteka ũthũku, mũũme wa kĩveti o kĩmwe, mwĩting’u, wĩ na kĩlĩko, mwaĩlu, mũthokya wa aeni, wĩ na ũtonyi wa kũmanyĩsya;'),
('kam', '1TI', 3, 3, 'ndakethiwe mũnywi wa ũkĩ, kana mũkũni wa andũ; ĩndĩ ethĩwe e mũuu, ti mũndũ wa kũtetan’ya, na ti mwendi wa mbesa;'),
('kam', '1TI', 3, 4, 'mũndũ ũla ũũngamĩaa nyũmba yake nesa, mũndũ wĩ na syana syĩ na winyivyo vamwe na kĩkĩo kyonthe;'),
('kam', '1TI', 3, 5, '(ĩndĩ ethĩwa mũndũ ndesĩ kũũngamĩa nyũmba yake, akasũvĩa ata ĩkanisa ya Ngai?)'),
('kam', '1TI', 3, 6, 'Ti mũndũ ũla wĩtĩkĩlĩte mĩtũkĩ, nĩkwĩthiwa eekathĩĩa akavalũka ũsilĩlonĩ wa Satani.'),
('kam', '1TI', 3, 7, 'Na ĩngĩ mũvaka ala me ũtee methĩwe na ũkũsĩ kana nĩ mũseo; ndakavalũke na kũwetwa ũthũku na kũlika mũkwanĩ wa Satani.'),
('kam', '1TI', 3, 8, 'No ta ũu athũkũmi mũvaka methĩwe andũ me kĩkĩo, ti andũ me na nĩmĩ ilĩ, ti anywi ma mbinyu mbingĩ, ti mwendi wa kũunwa nĩ syĩndũ itamwaĩle;'),
('kam', '1TI', 3, 9, 'nĩmethĩwe makĩkwata nzama ya ũla mũĩkĩĩo na wasya mũtheu wa ngoo.'),
('kam', '1TI', 3, 10, 'Na asu nao mambe kũow’a; na ĩtina nĩmathũkũme, ethĩwa matiũweteka ũthũku.'),
('kam', '1TI', 3, 11, 'Aka nao, no ta ũu, methĩwe na kĩkĩo, na ti ailĩanĩli, ĩndĩ eting’u, ala me na kĩthito maũndũnĩ onthe.'),
('kam', '1TI', 3, 12, 'Athũkũmi methĩwe kĩla ũmwe mũũme wa kĩveti o kĩmwe, maiũngamĩa syana syoo na nyũmba syoo nesa.'),
('kam', '1TI', 3, 13, 'Nũndũ ala mathũkũmĩte nesa, wĩa wa ũtumĩa wa ĩkanisa, meyoneaa nguma nzeo, na ũkũmbaũ mũnene mũĩkĩĩonĩ ũla wĩ nthĩnĩ wa Klĩsto Yesũ.'),
('kam', '1TI', 3, 14, 'Nakũandĩkĩa maũndũ aa, ngĩkwatya kũka kwaku mĩtũkĩ;'),
('kam', '1TI', 3, 15, 'ĩndĩ ethĩwa nĩĩkala mũno, naandĩka nĩ kana ũmanye ũndũ andũ maĩle kwĩyĩkalya nyũmbanĩ ya Ngai, nayo nĩ ĩkanisa ya Ngai ũla wĩ thayũ, kĩtuĩ na wambĩlĩlyo wa ũla w’o.'),
('kam', '1TI', 3, 16, 'Na vate ngananĩo nzama ya kũmũkĩa Ngai nĩ nene; We ũla wonaniw’e e na mwĩĩ, Atalĩlwa ũlũngalu vevanĩ, Ooneka nĩ alaĩka, Atavanw’a kwa Andũ‐ma‐mbaĩ‐ingĩ, Eetĩkĩlwa kũũ nthĩ Atwawa ĩũlũ ũtheunĩ mũtisu.'),
('kam', '1TI', 4, 1, 'Ĩndĩ Veva eneena vyũ, kana mavinda ma mũminũkĩlyo amwe makatia ũla mũikĩio, makĩthukĩĩsya maveva ala makenganaa, na momanyĩsyo ma ndaimoni.'),
('kam', '1TI', 4, 2, 'Nũndũ wa wangangan’yo wa andũ ala maneenaa movũngũ, wasya woo wa ngoo ene ũkyowa ta kwowa na kyoo kyauma mwakinĩ;'),
('kam', '1TI', 4, 3, 'maivata andũ kũtwaana, na kũmeaĩa mevathane na lĩu, ũla Ngai wombie wosawe na mũvea nĩ ala metĩkĩlaa na mesĩ ũla w’o.'),
('kam', '1TI', 4, 4, 'Nũndũ kĩla kyũmbe kya Ngai nĩ kĩseo, na vai kya ũlewa, kethĩwa kĩkooswa na mũvea:'),
('kam', '1TI', 4, 5, 'nũndũ nĩ kĩvathan’ye kĩthĩwe kĩtheu kwondũ wa ndeto ya Ngai na kũvoya.'),
('kam', '1TI', 4, 6, 'Ethĩwa ũkamalilikan’ya ana‐a‐asa maũndũ asu, ũkeethĩwa wĩ mũthũkũmi mũseo wa Klĩsto Yesũ, wĩkĩĩtwe vinya ndetonĩ sya ũla mũĩkĩĩo, na momanyĩsyonĩ maseo ala ũatĩĩaa:'),
('kam', '1TI', 4, 7, 'ĩndĩ lea mbano mbuku na sya iveti ngũũ. Ĩthangaasye mwene kũmũkĩa Ngai:'),
('kam', '1TI', 4, 8, 'nũndũ kwĩthangaasya kwa mwĩĩ kwaĩlaa vanini; ĩndĩ kũmũkĩa Ngai kwaĩlaa maũndũnĩ onthe, kwĩ na watho wa thayũ wa ĩvinda yĩĩ, na wa ũla ũkoka.'),
('kam', '1TI', 4, 9, 'Ndeto nĩ ya kũĩkĩĩwa, na nĩyaĩle kwĩtĩkĩlwa.'),
('kam', '1TI', 4, 10, 'Kwondũ wa ũu nĩtũũtethya wĩa na kwĩthing’ĩĩsya, nĩkwĩthĩwa twiĩte wĩkwatyo wĩtũ kwa Ngai ũla wĩ thayũ, nake nĩ Mũtangĩĩi wa andũ onthe, na mbee mũno wa ala metĩkĩlaa.'),
('kam', '1TI', 4, 11, 'Maũndũ aa meaĩe na mamanyĩsye.'),
('kam', '1TI', 4, 12, 'Mũndũ o na wĩva ndakavũthye wana waku; ĩndĩ ĩthĩwa wĩ ngelekan’yo kwa ala metĩkĩlaa, nthĩnĩ wa ndeto, na mwĩkalĩle wa thayũ, na wendo, na mũĩkĩĩo, na ũtheu.'),
('kam', '1TI', 4, 13, 'Ĩthĩwa wĩ mũthangaau kũsoma, kũtaa, na kũmanyĩsya, mũvaka nooka.'),
('kam', '1TI', 4, 14, 'Ndũkethĩwe ũteũsũvĩa mũthĩnzĩo ũla wĩ nthĩnĩ waku, ũla wanengiwe kwondũ wa wathani, vamwe na kwilĩĩlwa moko ma atumĩa.'),
('kam', '1TI', 4, 15, 'Ĩthĩwa na ũthangaau maũndũnĩ aa; ĩnengane kwamo vyũ; nĩ kana kũendeea na mbee kwaku kwĩthĩwe kwĩ kwoneku kwa onthe.'),
('kam', '1TI', 4, 16, 'Ĩsũvĩe mwene, vamwe na momanyĩsyo maku. Ĩkalaa maũndũnĩ asu; nũndũ kwa kwĩka ũu ũkeetangĩĩa mwene na asu nao ala makakwĩw’aa.'),
('kam', '1TI', 5, 1, 'Ndũkakan’ye mũtumĩa, ĩndĩ mũtae ta au; na aũme mate akũũ ta ana‐a‐au:'),
('kam', '1TI', 5, 2, 'aka akũũ ta amwenyu; na ala anini ma mũika ta eĩtu‐a‐mwenyu, na ũtheu w’onthe.'),
('kam', '1TI', 5, 3, 'Taĩa iveti ndiwa, ila ndiwa sya w’o.'),
('kam', '1TI', 5, 4, 'Ĩndĩ ethĩwa ndiwa yĩ na syana kana nzũkũlũ, syĩmanyĩsye mbee kwĩka maũndũ maĩle kwa andũ ma nyũmba yoo ene, na kũmaiva asyai moo: nũndũ ũũ nĩwendeeasya mbee wa Ngai.'),
('kam', '1TI', 5, 5, 'Na ĩndĩ we ũla ndiwa w’o, na e weka, ekwatasya Ngai, na ekalaa akĩsũva na kũvoya ũtukũ na mũthenya.'),
('kam', '1TI', 5, 6, 'Ĩndĩ ndiwa ĩla ĩnenganae kwĩka mawendi mayo nĩ ngw’ũ ĩ o thayũ.'),
('kam', '1TI', 5, 7, 'Maũndũ asu nao ĩae, nĩ kana methĩwe mataweteka ũthũku.'),
('kam', '1TI', 5, 8, 'Ĩndĩ mũndũ o na wĩva ũtamasũvĩaa ala make, na mbee mũno ala ma nyũmba yake, nũkaĩĩte ũla mũĩkĩĩo, na nĩ mũthũku mbee wa ũla ũtetĩkilĩte.'),
('kam', '1TI', 5, 9, 'Ndiwa ndĩkaandĩkwe ĩtavikĩtye myaka mĩongo thanthatũ, yaĩ mũndũ mũka wa mũũme o ũmwe,'),
('kam', '1TI', 5, 10, 'ũwetawa kwĩthĩwa na meko maseo; ethĩwa nĩwaeie syana, ethĩwa nĩwathokisye aeni, ethĩwa nĩwathambisye maũũ ma ala atheu, ethĩwa nĩwamatethisye ala mathĩnaa, ethĩwa nĩwaatĩĩe kĩla wĩa mũseo na ũthangaau.'),
('kam', '1TI', 5, 11, 'Ĩndĩ ndiwa sya mũika mũnini ndũkaiandĩke: nũndũ yĩla syĩkwatwa nĩ mĩmeo ya ũmũtia Klĩsto, ikenda kũtwawa;'),
('kam', '1TI', 5, 12, 'nasyo syĩ na ũsilĩlo, nũndũ nĩsyaekie mũĩkĩĩo wasyo wa mbee.'),
('kam', '1TI', 5, 13, 'Na vamwe na ũu nĩsyĩmanyĩasya ũtulu, na kwanganga nyũmba na nyũmba; nasyo ti kũtula kw’oka, ĩndĩ nĩ aei ma ngewa na kwĩlikya maũndũnĩ ma andũ angĩ, ikĩneena ndeto itaĩle kũneenwa.'),
('kam', '1TI', 5, 14, 'Nĩngwenda ĩndĩ ndiwa sya mũika mũnini itwawe, isyaae syana, iũngamĩe nyũmba syoo, itikamũnenge mũmaitha ũthei kwiweta naĩ:'),
('kam', '1TI', 5, 15, 'nũndũ o na yu imwe nĩsyathũkĩte kũmũatĩĩa Satani.'),
('kam', '1TI', 5, 16, 'Ethiwa mũndũ mũka wĩtĩkĩlĩte e na aka ndiwa, naitethye, ĩkanisa yĩtikakue mũio ũsu; nĩ kana yĩtethye ndiwa ila sya w’o.'),
('kam', '1TI', 5, 17, 'Atumĩa ala masilaa nesa nĩmatalwe kwĩthĩwa maĩle kũnengwa ndaĩa nene, na mbee mũno nĩ asu ala matethasya wĩa wa ĩla ndeto na wa kũmanyĩsya.'),
('kam', '1TI', 5, 18, 'Nũndũ maandĩko maĩtye atĩĩ, Ndũkamyove ng’ombe kanyw’a ĩkĩvũa isyo. Na, Mũtethya wa wĩa nĩwaĩlwe nĩ ĩtuvi yake.'),
('kam', '1TI', 5, 19, 'Ndũketĩkĩle ũvingan’yo iũlũ wa mũtumĩa, vate ngũsĩ itĩ kana itatũ.'),
('kam', '1TI', 5, 20, 'Ala mekaa naĩ makanĩasye mbee wa andũ onthe, nĩ kana ala angĩ nao methĩwe na w’ĩa.'),
('kam', '1TI', 5, 21, 'Nĩkwĩaĩa mbee wa Ngai, na Klĩsto Yesũ, na alaĩka anyuve, nĩ kana wĩkae maũndũ asu onthe ũtekũtw’a na mĩtũkĩ, ndũkeke ũndũ na wendeesyo.'),
('kam', '1TI', 5, 22, 'Ndũkailĩĩle mũndũ o na wĩva moko na mĩtũkĩ, o na ndũkethĩwe na mũamba na nai sya andũ angĩ: ĩyĩkalye mwene wĩ mũtheu.'),
('kam', '1TI', 5, 23, 'Kuma yu ndũkanyusae manzĩ me oka, ĩndĩ nyusaa mbinyu nini nũndũ wa ĩvu yaku na nũndũ wa mowau ala maũkwataa mavinda maingĩ.'),
('kam', '1TI', 5, 24, 'Naĩ sya andũ amwe nĩsyenekee, syĩmatongoesye kũvika ũsilĩlonĩ; na andũ amwe naĩ syoo imavikĩlaa ĩtina.'),
('kam', '1TI', 5, 25, 'No ta ũu kwĩ mawĩa maseo ala menekee; na ala mate maseo maitonyeka kũvithwa.'),
('kam', '1TI', 6, 1, 'Ngombo o na syĩva ila syĩ ĩsokinĩ nitale mavwana masyo nĩmaĩle ndaĩa yonthe, nĩ kana syĩtwa ya Ngai na ũla ũmanyĩsyo maikaumwe.'),
('kam', '1TI', 6, 2, 'Na ala me na mavwana metĩkĩlĩte, maikamavũthye, nũndũ nĩ ana‐a‐ĩthe; ĩndĩ kavaa mamathũkũme, nũndũ ala monaa ũtethyo wa wĩa woo nĩ etĩkĩli na endwa. Maũndũ aa manyĩsya, noitaa.'),
('kam', '1TI', 6, 3, 'Ethĩwa mũndũ o na wĩva amanyĩasya ũmanyĩsyo ũngĩ, na ndeũsyĩtĩkĩla ndeto syĩ na waĩlo, nasyo nĩ ndeto sya Mwĩaĩi waitũ Yesũ Klĩsto, na ũmanyĩsyo wĩanene na kũmũkĩa Ngai;'),
('kam', '1TI', 6, 4, 'e na ngathĩĩo, na nde ũndũ wĩsĩ, ĩndĩ mwĩkalo wake nĩ wa ũwau wa kũkũlangya na kũkananĩa ndeto, vala vaumaa kĩwĩu, na ĩteta, na kũumana, na kũtalĩlya ũthũku,'),
('kam', '1TI', 6, 5, 'na motũngĩthan’yo ma andũ ala manangĩkĩte kĩlĩkonĩ kyoo, na ala mevetee ũla w’o, makĩtalĩlya kũmũkĩa Ngai nĩ nzĩa ya kwona ũtandĩthyo.'),
('kam', '1TI', 6, 6, 'Ĩndĩ kũmũkĩa Ngai vamwe na kwĩanĩwa nĩ kĩla twĩ nakyo nĩ ũtandĩthyo mũnene:'),
('kam', '1TI', 6, 7, 'nũndũ tũtyaaũka kũũ nthĩ twĩ na kĩndũ, o na tũitonya kuma na kĩndũ;'),
('kam', '1TI', 6, 8, 'ĩndĩ tweethĩwa na kya ũya na kya kwĩvw’ika, syĩndũ isu ikatwĩanĩa.'),
('kam', '1TI', 6, 9, 'Ĩndĩ ala mekwenda kwĩthĩwa athwii nĩmavalũkaa na kũlika kũtatwanĩ na mũkwanĩ na mĩmeonĩ mingĩ ya ũtumanu na ya kũthũkya, ta ĩla ĩthikaa andũ makaa na kwanangĩka.'),
('kam', '1TI', 6, 10, 'Nũndũ wendi wa mbesa nĩ kĩtina kya mĩthemba yonthe ya ũthũku: namo andũ amwe makĩsyenda mũno, nĩmaĩtw’e na kũtia ũla mũĩkĩĩo, na kwĩtonya ene na mawoo maingĩ.'),
('kam', '1TI', 6, 11, 'Ĩndĩ we, mũndũ wa Ngai, kĩa maũndũ asu; noiatĩĩa ũlũngalu, na kũmũkĩa Ngai, na mũĩkĩĩo, na wendo, na wũmĩĩsyo, na ũuu.'),
('kam', '1TI', 6, 12, 'Ĩlũlũmĩlye kũkita kaũ ũla mũseo wa ũla mũĩkĩĩo, lũmya ũla thayũ wa tene na tene, ũla weetĩwe wĩthĩwe naw’o, na wakũsĩĩe ũkũsĩ mũseo ngũsĩ nyingĩ syene.'),
('kam', '1TI', 6, 13, 'Nĩngũkwĩaĩa mbee wa Ngai, ũla ũnengae syĩndũ syonthe thayũ, na mbee wa Klĩsto Yesũ, ũla wakũsĩĩe ũkũsĩ mũseo yĩla waĩ mbee wa Vondio Vilato;'),
('kam', '1TI', 6, 14, 'kana ũsũvĩae mwĩao ũũ, ũte ĩlanga, ũtaweteka ũthũku, kũvika kumĩla kwa Mwĩaĩi waitũ Yesũ Klĩsto:'),
('kam', '1TI', 6, 15, 'mavindanĩ makw’o we mwene nũkonan’ya, ũla Mũtonyi mũtaĩwa e weka, Mũsumbĩ wa asumbĩ, na Mwĩaĩi wa eaĩi;'),
('kam', '1TI', 6, 16, 'ũla e we weka ũtakwatawa nĩ kĩkw’ũ, ũtwĩe kyeninĩ kĩtathengeeka; o na vai mũndũ waamwona, o na ndatonya ũmwona; nĩwe mwene ndaĩa na vinya tene na tene. Ameni.'),
('kam', '1TI', 6, 17, 'Meaĩe ala me na ũthwii wa nthĩ ĩno, maikekathĩĩe, o na maikekwatye ũthwii ũla wanangĩkaa, ĩndĩ mekwatye Ngai, ũla ũtũnengae syĩndũ syonthe na wingĩ, tũtanaw’e nĩsyo;'),
('kam', '1TI', 6, 18, 'kana mekae nesa, kana methĩwe athwii ma kwĩkaa nesa, methĩwe meyũmbanĩtye kumya syĩndũ syoo, methĩwe me na mũamba wa ngoo na ala angĩ;'),
('kam', '1TI', 6, 19, 'meyiĩe ene mwambĩlĩlyo mũseo wa ĩvinda yĩla yũkite, nĩ kana makwate ũla thayũ wa tene na tene, naw’o nĩ thayũ wa w’o.'),
('kam', '1TI', 6, 20, 'Naku Timotheo, sũvĩa kĩla kyaiiwe kwaku, wĩvathane na ndeto sya mana na sya ngananĩo sya kĩla kĩtwa ũmanyi na tiw’o;'),
('kam', '1TI', 6, 21, 'amwe nĩmekwitĩkĩla ũu na nĩmavĩtĩtye ũla mũĩkĩĩo. Mumo nĩwĩthĩwe naku.'),
('kam', '2TI', 1, 1, 'Vaulo, mũtũmwa wa Klĩsto Yesũ kwondũ wa kwenda kwa Ngai, kwĩanana na watho wa thayũ ũla wĩ nthĩnĩ wa Klĩsto Yesũ,'),
('kam', '2TI', 1, 2, 'valũa ũũ wakwa ũmũvikĩe Timotheo, mwana wakwa mwendwa: Mumo, na tei, na mũuo, kuma kwa Ngai Asa na Klĩsto Yesũ Mwĩaĩi waitũ.'),
('kam', '2TI', 1, 3, 'Nĩmũtũngĩa Ngai mũvea, ũla nĩmũthũkũmaa na wasya wa ngoo mũtheu o ta aaũmae makwa, ũndũ ngũlilikanaa vate kũeka mboyanĩ syakwa, ũtukũ na mũthenya;'),
('kam', '2TI', 1, 4, 'ngĩlilikana methoi maku, nĩ na mea ma ũkwona, nĩ kana ũtanu wakwa wusũe;'),
('kam', '2TI', 1, 5, 'nũndũ nĩlilikanĩte mũĩkĩĩo ũte na wangangan’yo ũla wĩ naw’o; ũla tene waĩ na ũsũe waku Loisi, na waĩ na mwenyu Eunike; na nĩnĩtĩkĩlĩte vyũ, kana naku wĩ naw’o.'),
('kam', '2TI', 1, 6, 'Kwondũ wa ũu nĩngũũlilikan’ya wakan’ye ũla mũthĩnzĩo wa Ngai wĩ naw’o kwondũ wa kwilĩĩlwa moko makwa.'),
('kam', '2TI', 1, 7, 'Nũndũ Ngai ndaatũnenga veva wa w’ĩa; ĩndĩ atũnengie veva wa vinya na wa wendo na wa kĩlĩko kĩanĩu.'),
('kam', '2TI', 1, 8, 'Kwondũ wa ũu ndũkawĩw’ĩe nthoni ũkũsĩ wa Mwĩaĩi waitũ, o na ndũkambĩw’ĩe nthonĩ nyie mwovwa wake; ĩndĩ ũmĩĩasya maũndũ maito vamwe na ũvoo mũseo kwĩanana na vinya wa Ngai;'),
('kam', '2TI', 1, 9, 'ũla watũtangĩĩe, na kũtwĩta na wĩtano mũtheu, ti kwĩanana na meko maitũ tondũ mailyĩ, ĩndĩ kwĩanana na kwenda kwake mwene na mumo ũla twanengiwe nthĩnĩ wa Klĩsto Yesũ mbee wa mavinda ma tene tene,'),
('kam', '2TI', 1, 10, 'ĩndĩ yu nĩwonanĩtw’e kwondũ wa kumĩla kwa Mũtangĩĩi waitũ Klĩsto Yesũ, ũla wanangie kĩkw’ũ, na kumĩlya thayũ na kũveta wanangĩko kwondũ wa ũvoo mũseo,'),
('kam', '2TI', 1, 11, 'naw’o kwondũ waw’o nyie naiiwe mũtavan’ya, na mũtũmwa, na mũmanyĩsya.'),
('kam', '2TI', 1, 12, 'Kwondũ wa ũu nĩngũthĩnw’a nĩ maũndũ aa nao: ĩndĩ ndiũsonoka; nũndũ nĩnĩmwĩsĩ we ũla nĩtĩkĩlĩte, na ĩngĩ nĩnĩsĩ vyũ kana we nũtonya kũsũvĩaa kĩla niĩte kwake kũvika mũthenya ũsu.'),
('kam', '2TI', 1, 13, 'Kwata kĩeleelo kya ndeto ila syaĩle ila weewie kwakwa, na mũĩkĩĩo na wendo ũla wĩ nthĩnĩ wa Klĩsto Yesũ.'),
('kam', '2TI', 1, 14, 'Ũndũ ũsu mũseo ũla wiĩtwe kwaku ũsũvĩe kwa nzĩa ya Veva Mũtheu ũla ũtwĩe nthĩnĩ waitũ.'),
('kam', '2TI', 1, 15, 'Nĩwĩsĩ ũũ, kana onthe ala me Asia nĩmaalũkile na mandia; na amwe mao nĩ Vikelo na Elimakane.'),
('kam', '2TI', 1, 16, 'Mwĩaĩi namew’ĩe tei ala ma nyũmba ya Onesivolo: nũndũ nĩwambuũkisye kaingĩ, na ndaawĩw’ĩa nthoni ũla mũnyololo wakwa;'),
('kam', '2TI', 1, 17, 'ĩndĩ, yĩla waĩ Lomi, amanthie na ũthangaau, na ambona'),
('kam', '2TI', 1, 18, '(Mwĩaĩi namũnenge kwona tei wa Mwĩaĩi mũthenya ũsu); we nĩwĩsĩ nesa nĩ maũndũ meana ata wanthũkũmie namo Eveso.'),
('kam', '2TI', 2, 1, 'We ĩndĩ, mwana wakwa, ĩthĩwa ũkyongeleelwa vinya mumonĩ ũla wĩ nthĩnĩ wa Klĩsto Yesũ.'),
('kam', '2TI', 2, 2, 'Na maũndũ ala weewie kwakwa na ngũsĩ nyingĩ, asu maie kwa andũ me na kĩthito, ala makatonya kũmanyĩsya angĩ nao.'),
('kam', '2TI', 2, 3, 'Ũmĩĩsya maũndũ maito vamwe nakwa, ta mũsikalĩ mũseo wa Klĩsto Yesũ.'),
('kam', '2TI', 2, 4, 'Vai mũsikalĩ e kaũnĩ ũvĩndanĩw’a na maũndũ ma thayũ ũũ; nĩ kana amwendeesye ũla wamũandĩkie ethĩwe mũsikalĩ.'),
('kam', '2TI', 2, 5, 'Na ĩngĩ ethĩwa mũndũ etata mathaũnĩ, ndanengawe ngovĩa, ate o akakĩlan’ya ũndũ weeaiwe.'),
('kam', '2TI', 2, 6, 'Nĩkwaĩle mũĩmi ũla watethisye wĩa ethĩwe wa mbee kwosa mosyao.'),
('kam', '2TI', 2, 7, 'Sũanĩa ũndũ ũla ngwasya; nũndũ Mwĩaĩi akakũnenga ũmanyi maũndũnĩ onthe.'),
('kam', '2TI', 2, 8, 'Mũlilikane Yesũ Klĩsto, ũla wathayũũkie kuma akw’ũnĩ, ũla waĩ wa ũsyao wa Ndaviti, kwĩanana na ũvoo mũseo wakwa:'),
('kam', '2TI', 2, 9, 'ũla kwondũ waw’o nĩthĩnaw’a kũvika kwovwa, ta mwĩki wa naĩ; ĩndĩ ndeto ya Ngai ndyovawa.'),
('kam', '2TI', 2, 10, 'Kwondũ wa ũu nũmĩĩasya maũndũ onthe nũndũ wa ala anyuve, nĩ kana nao mose ũtangĩĩo ũla wĩ nthĩnĩ wa Klĩsto Yesũ vamwe na ũtaĩo wa tene na tene.'),
('kam', '2TI', 2, 11, 'Nĩ ndeto ya kũĩkĩĩwa: Nũndũ ethĩwa twakwie vamwe nake, tũkeethĩwa thayũ naw’o vamwe nake;'),
('kam', '2TI', 2, 12, 'Ethĩwa nĩtũkũmĩĩsya, tũkasumbĩka vamwe nake: Ethĩwa tũkamũkaĩa we, nake akatũkaĩa ithyĩ:'),
('kam', '2TI', 2, 13, 'Ethĩwa tũti na kĩthito, we ekalaa na kĩthito; nũndũ ndatonya kwĩkaĩa mwene.'),
('kam', '2TI', 2, 14, 'Malilikan’ye maũndũ asu, ũkĩmeaĩa mbee wa Mwĩaĩi, maikethĩwe na ngananĩo sya ndeto, ila ite na kĩndũ imoneaa, na imaasya ala mew’aa.'),
('kam', '2TI', 2, 15, 'Thangaa kwĩnengane mwene wĩtĩkĩlĩlwe nĩ Ngai, mũtethya wa wĩa ũtasonokw’a, ũivathũkan’ya ũndũ waĩle ndeto ya ũla w’o.'),
('kam', '2TI', 2, 16, 'Ĩndĩ ĩvathane na ndeto sya mana: nũndũ ikaendeea na mbee ũndũnĩ wa kũlea kũmũkĩa Ngai,'),
('kam', '2TI', 2, 17, 'na ndeto yoo ĩkeethĩwa ĩkĩya ta kĩtau kya yaso: asu amwe nĩ Aimenaio na Vileto;'),
('kam', '2TI', 2, 18, 'andũ ala mavĩtĩtye ũla w’o, makyasya kana ũthayũũkyo nĩ mũvĩtu o na yu, na maing’uthũla mũĩkĩĩo wa amwe.'),
('kam', '2TI', 2, 19, 'Ĩndĩ wambĩlĩlyo mũlũmu wa Ngai nũũngeme, wĩ na ũsiĩlo ũũ, Mwĩaĩi nũmesĩ ala make: na, Kĩla mũndũ ũwetaa syĩtwa ya Mwĩaĩi natie ũndũ ũte ũlũngalu.'),
('kam', '2TI', 2, 20, 'Na nyũmbanĩ nene vaiĩthĩawa mĩio ya thaavu na vetha yoka, ĩndĩ o na ya mĩtĩ na ya yũmba; na ĩmwe yĩ na ndaĩa na ĩngĩ ĩte na ndaĩa.'),
('kam', '2TI', 2, 21, 'Ethĩwa ĩndĩ mũndũ etheasya kwa asu, akeethĩwa e mũio wa kwona ndaĩa, ũvathĩtwe ethĩwe mũtheu, waĩle wĩa wa Mwĩaĩi, ũseũvĩtw’e kwa kĩla wĩa mũseo.'),
('kam', '2TI', 2, 22, 'Ĩndĩ kĩa mĩmeo ya wana, na ũkĩatĩĩa ũlũngalu, na mũĩkũo, na wendo, na mũuo, vamwe na ala mamwĩkaĩlaa Mwĩaĩi na ngoo ntheu.'),
('kam', '2TI', 2, 23, 'Ĩndĩ lea mokũlyo ma ũtumanu na ala mate na ũmanyi, ũkĩmanya kana maetae ngandanĩo.'),
('kam', '2TI', 2, 24, 'Na ngombo ya Mwĩaĩi ndyaĩlwe nĩ ũkandanĩa, ĩndĩ nĩyaĩle kwĩthĩwa ĩ nduu kwa andũ onthe, ĩ na ũtonyi wa kũmanyĩsya, ĩ na wũmĩĩsyo:'),
('kam', '2TI', 2, 25, 'ĩkĩmataa na ũuu ala akananĩi; no kwĩthĩwa Ngai emanenga ũalyũlo wa ngoo kũvika ũmanyi wa ũla w’o,'),
('kam', '2TI', 2, 26, 'matonye ũvindũka na kuma mũkwanĩ wa ndevili matavĩtwe nĩ mũthũkũmi wa Mwĩaĩi, kũvika kwĩka kwenda kwa Ngai.'),
('kam', '2TI', 3, 1, 'Ĩndĩ manya ũũ, kana mĩthenyanĩ ya mũminũkĩlyo kũkeethĩwa mavinda ma mũisyo.'),
('kam', '2TI', 3, 2, 'Nũndũ andũ makeethĩwa makĩyenda ene, makyenda mbesa, makĩkathĩĩa, na kwĩtaĩa, na kũumana, matew’aa asyai, mate mũvea, mate atheu,'),
('kam', '2TI', 3, 3, 'mate na wendo waĩle, mate na wĩw’ano, ailĩanĩli, mate na wĩting’o, ai, matendete ũseo,'),
('kam', '2TI', 3, 4, 'akaĩi, me na ngũlũ, me na mĩyimbyo, endi ma motanu ma nthĩ mbee wa kũmwenda Ngai;'),
('kam', '2TI', 3, 5, 'me na mũvw’ano wa kĩkĩo kwa Ngai, ĩndĩ nĩmakaĩĩte vinya wakyo: ĩvathane na asu nao.'),
('kam', '2TI', 3, 6, 'Nũndũ andũnĩ asu ve ala melikasya nyũmbanĩ sya andũ na kũtava aka atumanu ala makuaa mũio ya naĩ, matongoew’e nĩ mĩmeo ya mĩthemba mingĩ,'),
('kam', '2TI', 3, 7, 'memanyĩasya mĩthenya yonthe, na maitonya o na ĩndĩĩ kũvikĩa ũmanyi wa ũla w’o.'),
('kam', '2TI', 3, 8, 'Na o tondũ Yane na Yambale mamũsiĩĩe Mose, no ta ũu aa nao nĩmasiĩĩaa ũla w’o; andũ mavukĩtwe ilĩkoni syoo, matetĩkĩlĩka mũĩkĩĩoni.'),
('kam', '2TI', 3, 9, 'Ĩndĩ maikaendeea na mbee: nũndũ ũtumanu woo ũkeethĩwa wenekee kwa andũ onthe, o tondũ wa asu woonekie.'),
('kam', '2TI', 3, 10, 'Ĩndĩ we nĩwavikĩlile ũmanyĩsyo wakwa, na mũendele, na kwenda kwakwa, na mũĩkĩĩo, na wũmĩĩsyo, na wendo, na wĩlũlũmĩlyo,'),
('kam', '2TI', 3, 11, 'na monyamao, na mathĩna; na maũndũ ala mangwatĩe Andiokia, na Ikonio, na Lisitela; monyamao ala neeyũmĩĩsye: na Mwĩaĩi andangĩĩa na kũnumya maũndũnĩ asu onthe.'),
('kam', '2TI', 3, 12, 'Ĩĩ, na onthe ala mendaa kwĩkalya thayũ woo kũmũkĩa Ngai nthĩnĩ wa Klĩsto Yesũ makathĩnw’a.'),
('kam', '2TI', 3, 13, 'Ĩndĩ andũ athe na akengani makaendeea na kwongeleka kũthũka, makĩkengana na kũkengwa.'),
('kam', '2TI', 3, 14, 'Ĩndĩ we, ĩkala maũndũnĩ ala wamanyĩiw’e na ala wamanyie vyũ, nĩkwĩthĩwa nĩwĩsĩ andũ ala weemanyĩisye kwamo;'),
('kam', '2TI', 3, 15, 'na ĩngĩ kuma wĩ kana kanini nĩweesĩ maandĩko matheu, ala matonya ũkũĩvya kũvika ũtangĩĩo ũla wĩ kwondũ wa mũĩkĩĩo wĩ nthĩnĩ wa Klĩsto Yesũ.'),
('kam', '2TI', 3, 16, 'Kĩla Ũandĩko nĩwaveveewe nĩ Ngai, naw’o nĩwaĩle wa kũmanyĩsya, na kũĩkĩĩthya andũ mavĩtyo, na kũmatũngĩĩa, na kũsilĩla kwa ũlũngalu:'),
('kam', '2TI', 3, 17, 'nĩ kana mũndũ wa Ngai atonye kwĩthĩwa e mwĩanĩu, eanĩe kũtethya kĩla wĩa mũseo.'),
('kam', '2TI', 4, 1, 'Nĩkwĩaĩa mbee wa Ngai, na mbee wa Klĩsto Yesũ, ũla ũkasilĩla ala me thayũ na ala akw’ũ, o na ĩngĩ ũndũ wa kumĩla kwake na ũsumbĩ wake:'),
('kam', '2TI', 4, 2, 'tavan’ya ĩla ndeto; ĩthĩwa wĩ mũthangaau ĩvinda yaĩle, na yĩla yĩtaĩle; onan’ya mavĩtyo, kan’ya, taa, na wũmĩĩsyo w’onthe na kũmanyĩsya.'),
('kam', '2TI', 4, 3, 'Nũndũ ĩvinda yĩkooka yĩla mataketĩkĩla kũtavw’a momanyisyo ma w’o; ĩndĩ, nĩkwĩthĩwa me na matũ meũmanyeea, makeeyũmbanĩsya amanyĩsya o kwĩanana na mĩmeo yoo;'),
('kam', '2TI', 4, 4, 'nao makathyũũa matũ moo maikew’e ũla w’o, na kwathũka kwĩthukĩĩsya mbano.'),
('kam', '2TI', 4, 5, 'Ĩndĩ ĩthĩwa wĩ na kĩlĩko maũndũnĩ onthe, ũmĩĩsya maũndũ maito, tethya wĩa wa mũtavan’ya wa ũvoo mũseo ĩanĩsya ũthũkũmi waku.'),
('kam', '2TI', 4, 6, 'Nũndũ o na yu nĩngũtulũlwa ta nthembo, na ĩvinda yakwa ya kũthi nĩ ĩviku.'),
('kam', '2TI', 4, 7, 'Nĩnũkitĩte kaũ ũla mũseo, nĩnĩminĩte mũendo, nĩnĩsũvĩĩte ũla mũĩkĩĩo:'),
('kam', '2TI', 4, 8, 'kuma yu nĩniĩwe ngovia ya ũsumbĩ ya ũlũngalu, nayo Mwĩaĩi, mũsili ũla mũlũngalu, akanenga mũthenya ũsu; na ti nyie nyioka, ĩndĩ andũ onthe nao ala mendaa kumĩlw’a kwake.'),
('kam', '2TI', 4, 9, 'Thangaaa kũka kwakwa na mĩtũkĩ:'),
('kam', '2TI', 4, 10, 'nũndũ Ndema nĩwandiie, endie nthĩ ĩno ya ĩvinda yĩĩ, na anaendie Thesalonika; na Keliseke anaendie Kalatia, na Tito anaendie Ndalamatia.'),
('kam', '2TI', 4, 11, 'No Luka e weka nĩ nake. Mwose Maliko wũke nake kũũ; nũndũ nĩ na vata nake wianĩ wa ũthũkũmi.'),
('kam', '2TI', 4, 12, 'Ĩndĩ Tikiko nĩnamũtũmie Eveso.'),
('kam', '2TI', 4, 13, 'Ngũa ya ĩũlũ ĩla natiie na Kalivo nthĩ ya Teloa, wĩete ũyũka, vamwe na ala mavuku, na mũno mbee ũka na ala ma mbũa.'),
('kam', '2TI', 4, 14, 'Alesanda ũla mũtwii wa ũthuku nĩwambĩkie ũthũku mwingĩ: Mwĩaĩi akamũĩva kwĩanana na mawĩa make:'),
('kam', '2TI', 4, 15, 'naku mwĩsũvĩe mũno; nũndũ nĩwasiĩĩe mũno ndeto sitũ.'),
('kam', '2TI', 4, 16, 'Ũsũngĩo wakwa wa mbee vai mũndũ waũngamie vamwe nakwa, ĩndĩ onthe nĩmandiie; maikaatalĩlwe ũndũ ũsu.'),
('kam', '2TI', 4, 17, 'Ĩndĩ Mwĩaĩi nĩwaũngamie vamwe nakwa, na anenga vinya; nĩ kana kwondũ wakwa ũla ũtũmane ũtonye kũtavanw’a vyũ, na nĩ kana Andũ‐ma‐mbaĩ‐ingi onthe mew’e: nakwa natangĩĩwe kumw’a kanyw’anĩ wa ũla mũnyambũ.'),
('kam', '2TI', 4, 18, 'Mwĩaĩi akandangĩĩa kĩla ũndũ ũthũku, na akanzũvĩa kũvika ũsumbĩ wake wa ĩtunĩ: ndaĩa nĩyĩthĩwe yake kũvika tene na tene. Ameni.'),
('kam', '2TI', 4, 19, 'Ngethesya Vilisika na Akwila, na nyũmba ya Onesivolo.'),
('kam', '2TI', 4, 20, 'Elasito ekalile Kolintho: ĩndĩ Telovimo namũtiie Mileto e mũwau.'),
('kam', '2TI', 4, 21, 'Thangaa kũka ĩvinda ya mbevo yĩtanavika. Euvulo nĩwaũkethya, na Vuteni, na Leno, na Kilautia, na ana‐a‐asa onthe.'),
('kam', '2TI', 4, 22, 'Mwĩaĩi nĩethĩwe vamwe na veva waku. Mumo nĩwĩthĩwe nenyu.'),
('kam', 'TIT', 1, 1, 'Vaũlo, ngombo ya Ngai, na mũtũmwa wa Yesũ Klĩsto kwĩanana na mũĩkĩĩo wa anyuve ma Ngai, na ũmanyi wa ũla w’o ũla wĩanene na kũmũkĩa Ngai,'),
('kam', 'TIT', 1, 2, 'nthĩnĩ wa wĩkwatyo wa thayũ ũtathela, ũla Ngai wathie mbee wa mavinda ma tene tene, nake ndatonya kũneena ũvũngũ;'),
('kam', 'TIT', 1, 3, 'ĩndĩ mavindanĩ make nĩwavuanisye ndeto yake nthĩnĩ wa ũtũmane, ũla nyie naĩkĩĩwe nĩthĩwe naw’o kwondũ wa mwĩao wa Ngai Mũtangĩĩi waitũ;'),
('kam', 'TIT', 1, 4, 'valũa ũũ wakwa ũmũvikĩe Tito, mwana wakwa wa w’o nũndũ wa mũĩkĩĩo ũmwe ũla twĩ naw’o: Mumo na mũuo kuma kwa Ngai Asa na Klĩsto Yesũ Mũtangĩĩi waitũ.'),
('kam', 'TIT', 1, 5, 'Kwondũ wa ũndũ ũũ nakũtiie Kilete, nĩ kana maũndũ ala matiele kwikwa ũmaseũvye, na kwia atumĩa kĩla ndũa, o tondũ nakwĩaĩe;'),
('kam', 'TIT', 1, 6, 'ethĩwa mũndũ ndaweteka ũndũ ũthũku, na nĩ mũũme wa kiveti o kimwe, ũla wĩ na syana syĩtikĩlaa, itavinganĩw’a kwĩthĩwa na ngũlũ na wau wa matũ.'),
('kam', 'TIT', 1, 7, 'Nũndũ mũsyaĩĩsya nĩwaĩle kwĩthĩwa ataweteka ũndũ ũthũku, ta mũsũvĩi maũndũnĩ ma Ngai; na ndakethĩwe na mĩtavyo, kana kũthata mitũkĩ, ndakethiwe mũnywi wa ũki, kana mũkũni wa andũ, ndakethiwe mwendi wa kũunwa nĩ syĩndũ itamwaĩle;'),
('kam', 'TIT', 1, 8, 'ĩndĩ ethĩwe mũthokya wa aeni, na mwendi wa ũseo, ũla wĩ na kĩlĩko, mũndũ mũlũngalu, mũndũ mũtheu, na mwĩting’u;'),
('kam', 'TIT', 1, 9, 'ailũmya ndeto ĩla ya kĩthito ĩla yĩanene na ũla ũmanyĩsyo, nĩ kana atonye kũtaa ũmanyĩsyonĩ ũla wa w’o, vamwe na kũmaĩkĩĩthya akananĩi mavĩtyo.'),
('kam', 'TIT', 1, 10, 'Nũndũ kwi mbaa matũ mbingĩ, aneenĩ ma ndeto sya mana na akengani, na mũno nĩ ma ala maĩkawa,'),
('kam', 'TIT', 1, 11, 'namo mũvaka makanyw’a moo mavindĩthw’e; andũ ala makulumanasya nyũmba nĩma sya andũ, makimanyĩsya maũndũ mataĩle, kwondũ wa kwenda kũunwa nĩ syĩndũ itamaĩle.'),
('kam', 'TIT', 1, 12, 'Mũndũ ũmwe wamo, mwathanĩ woo, aisye, Akilete nĩ aneeni ma ũvũngũ mavinda onthe, nyamũ nthũku, ayi matatethasya wĩa.'),
('kam', 'TIT', 1, 13, 'Ũkũsĩ ũsu nĩ wa w’o. Kwondũ wa ũu makan’ye na ndeto sya vinya, nĩ kana methĩwe aima mũĩkĩĩonĩ,'),
('kam', 'TIT', 1, 14, 'mateũatĩĩa mbano sya Ayuti, na mĩao ya andũ ala mathũkĩaa ũla w’o.'),
('kam', 'TIT', 1, 15, 'Kwa atheu maũndũ onthe nĩ matheu; ĩndĩ kwa ala avuku na matetĩkĩlĩte vai kĩndũ kĩtheu; ĩndĩ ĩlĩko syoo vamwe na wasya wa ngoo woo nĩvũkĩtw’e.'),
('kam', 'TIT', 1, 16, 'Maasya kana nĩmesĩ Ngai; ĩndĩ mekonĩ moo nĩmeũmũkaĩa, nao nĩmathatasya na matew’aa, na wĩanĩ mũseo o na wĩva maiĩtĩkĩlĩka.'),
('kam', 'TIT', 2, 1, 'Ĩndĩ we, neena maũndũ ala maĩle ũmanyĩsyo ũla wa w’o;'),
('kam', 'TIT', 2, 2, 'atĩ atumĩa akũũ methĩwe na wĩting’o, na kĩkĩo, na kĩlĩko, methĩwe aima mũĩkĩĩonĩ, na wendonĩ, na wũmĩĩsyonĩ:'),
('kam', 'TIT', 2, 3, 'na ivetĩ ngũũ nasyo no ta ũu syĩthĩwe na mwĩkalĩle wa ũtheu, ite nzũkani kana ngombo sya mbinyu mbingĩ, syĩthĩwe amanyĩsya ma maũndũ ala maseo;'),
('kam', 'TIT', 2, 4, 'nĩ kana imanyĩasye aka ma mũika kwenda aũme moo, na kũsyenda syana syoo,'),
('kam', 'TIT', 2, 5, 'methĩwe na kĩlĩko, mate na wathe, atethya ma wĩa mĩsyĩ kwoo, kwĩka angĩ nesa, na kwĩnyivya kwa aũme moo ene, nĩ kana ndeto ya Ngai ndĩkaumwe:'),
('kam', 'TIT', 2, 6, 'aũme mate akũũ nao mataae methĩwe na kĩlĩko:'),
('kam', 'TIT', 2, 7, 'maũndũnĩ onthe ũkĩyonan’ya mwene wĩ ngelekan’yo ya meko maseo; ũmanyĩsyonĩ waku ũkyonan’ya ũndũ ũla ũtatonya kũthũkya, na kĩkĩo,'),
('kam', 'TIT', 2, 8, 'na ndeto syaĩle itatonya kũsilĩlwa; nĩ kana ũla ũkwenda ũkũvinganĩsya atonye kũsonoka, nũndũ ndakethĩwa na ndeto sya kũtũneenea.'),
('kam', 'TIT', 2, 9, 'Ngombo syĩnyivye kwa mavwana masyo, na syĩthĩwe ĩkĩmendeesya maũndũnĩ onthe; itikatũngĩthasya;'),
('kam', 'TIT', 2, 10, 'na itikethĩwe osangi ma syĩndũ, ĩndĩ ikyonan’ya kĩthito kĩseo kyonthe; nĩ kana syanakavye maũndũnĩ onthe ũmanyĩsyo wa Ngai Mũtangĩĩi waitũ.'),
('kam', 'TIT', 2, 11, 'Nũndũ mumo wa Ngai nĩwumĩlĩte, ũkĩetee andũ onthe ũtangĩĩo,'),
('kam', 'TIT', 2, 12, 'ũkĩtũmanyĩsya atĩ tũlee maũndũ onthe mate ma kũmũkĩa Ngai na mawendi onthe ma nthĩ, twĩkalasye mathayũ maitũ na kĩlĩko kĩanĩu na ũlũngalu na kũmũkĩa Ngai ĩvindanĩ yĩĩ tũĩ;'),
('kam', 'TIT', 2, 13, 'tũkĩsyaĩĩsya wĩkwatyo ũla wĩ na ũathimo na kumĩla kwa ũtheu mũtisu wa Ngai ũla mũnene na Mũtangĩĩi waĩtũ Yesũ Klĩsto;'),
('kam', 'TIT', 2, 14, 'ũla wenenganie mwene kwondũ witũ, nĩ kana atwovosye kũtumya mothũkunĩ onthe, na kwĩtheesya andũ methĩwe make mwene, me na ũthangaau mawĩanĩ ala maseo.'),
('kam', 'TIT', 2, 15, 'Maũndũ aa neena, noitaa, noikan’ya, na ũkũmũ w’onthe. Mũndũ ndakakũvũthye.'),
('kam', 'TIT', 3, 1, 'Malilikan’ye kwĩnyivĩasya anene, na ala me na ũkũmũ, na kũmew’a, methĩwe meyũmbanĩte kĩla wĩanĩ mũseo,'),
('kam', 'TIT', 3, 2, 'maikaneenee mũndũ o na wĩva naĩ, kana kũtetan’ya, methĩwe me avoo, makyonan’ya ũuu w’onthe kwa andũ onthe.'),
('kam', 'TIT', 3, 3, 'Nĩkwĩthĩwa ithyĩ naitũ tene twaĩ atũmanu, tũtyaĩ ewi, twaĩ akenge, tũkĩthũkũma mawendi na motanu ma nthĩ ma mĩthemba mingĩ, tũkĩkalya mathayũ maitũ maũndũnĩ mai, na kwĩw’anĩa iwĩu, tũkimeneka, na kũmenana ithyĩ kwa ithyĩ.'),
('kam', 'TIT', 3, 4, 'Ĩndĩ yĩla ũseo wa Ngai Mũtangĩĩi waitũ, na wendo wake welekele andũ, waumilile,'),
('kam', 'TIT', 3, 5, 'ti kwondũ wa meko ma ũlũngalu, ala ithyĩ tweekie, ĩndĩ kwĩanana na tei wake nĩwatũtangĩĩe, kwondũ wa kũthambw’a kwa kũsyawa ĩngĩ, na kũtw’ĩkĩthw’a eũ nĩ Veva Mũtheu,'),
('kam', 'TIT', 3, 6, 'ũla watwonoesye kwa wingĩ, kwondũ wa Yesũ Klĩsto Mũtangĩĩi waitũ;'),
('kam', 'TIT', 3, 7, 'nĩ kana, ũndũ wa kũtalĩlwa ũlũngalu kwondũ wa mumo wake, tũtonye kũtuwa atiĩwa kwĩanana na wĩkwatyo wa thayũ ũtathela.'),
('kam', 'TIT', 3, 8, 'Ndeto nĩ ya kũĩkĩĩwa, na kwondũ wa maũndũ aa nĩngwenda ũneene na vinya, nĩ kana ala metĩkĩlĩte Ngai mesũvĩe mũno mekae meko maseo. Maũndũ aa nĩ maseo na me na ũtandĩthyo andũnĩ:'),
('kam', 'TIT', 3, 9, 'ĩndĩ mokũlyo ma ũtumanu, na mosyaanĩo, na mateta, na kũkita ũndũ wa ĩla mĩao, ĩvete maũndũnĩ asu; nũndũ mati na ũtandĩthyo na nĩ ma mana.'),
('kam', 'TIT', 3, 10, 'Mũndũ ũla ũetae kĩvathũkangano, ĩtina wa kũmũtaa ya mbee na ya kelĩ, mũlee;'),
('kam', 'TIT', 3, 11, 'ũkĩmanya kana mũndũ ũilyĩ ũsu nũalyũkĩte, na ekaa naĩ, nĩwĩsilĩlĩte mwene kwĩthĩwa nĩ mũvĩtan’ya.'),
('kam', 'TIT', 3, 12, 'Yĩla nĩtũma Alitema kwaku, kana Tikiko, ĩthangaasye kũka Nikovoli vala nĩĩ: nĩkwĩthĩwa nĩnĩminĩte kũtw’a kwĩkala kw’o ĩvinda ya mbevo.'),
('kam', 'TIT', 3, 13, 'Matethye mũno Nzena ũla mũmanyĩsya wa mĩao na Avolo kyalonĩ kyoo, matikanyivĩwe nĩ kĩndũ o na kĩmwe.'),
('kam', 'TIT', 3, 14, 'Na andũ maitũ nao memanyĩsye kwĩyĩkalya mawĩanĩ maseo kwondũ wa kwĩanĩsya mavata, nĩ kana matikethĩwe mate na ũsyao.'),
('kam', 'TIT', 3, 15, 'Andũ onthe ala me vamwe nakwa nĩmaũkethya. Tũkethesye ala matwendaa nthĩnĩ wa ũla mũĩkĩĩo. Mumo nĩwĩthĩwe nenyu inyw’onthe.'),
('kam', 'PHM', 1, 1, 'Vaulo, mwovwa wa Klĩsto Yesũ, na Timotheo mwana‐a‐asa waitũ, valũa ũũ witũ ũmũvikĩe Vilemona mwendwa waitũ na mũtethya wa wĩa vamwe naitũ,'),
('kam', 'PHM', 1, 2, 'na Avia mwĩĩtũ‐wa‐asa waitũ, na Alikivo mũsikalĩ vamwe naitũ, na ikanisa yĩla yĩ nyũmbanĩ yaku:'),
('kam', 'PHM', 1, 3, 'Mumo nĩwĩthĩwe nenyu na mũuo kuma kwa Ngai Asa waitũ na kwa Mwĩaĩi Yesũ Klĩsto.'),
('kam', 'PHM', 1, 4, 'Nĩmũtũngĩa Ngai wakwa mũvea mavinda onthe, ngĩũweta mboyanĩ syakwa,'),
('kam', 'PHM', 1, 5, 'ngĩw’a ũvoo wa wendo waku, na mũĩkĩĩo ũla wĩ naw’o ũmwelekele Mwĩaĩi Yesũ, na atheu onthe:'),
('kam', 'PHM', 1, 6, 'nĩ kana mũamba wa mũĩkĩĩo waku wĩthĩwe ũitethya wĩa wa w’o, ũmanyinĩ wa kĩla ũndũ ũseo wĩ nthĩnĩ wenyu, kwondũ wa Klĩsto.'),
('kam', 'PHM', 1, 7, 'Nũndũ nai na ũtanu mwingĩ na ũkiakisyo kwondũ wa wendo waku, nĩkwĩthĩwa ngoo sya atheu nivuũkĩtw’e nue, mwana‐a‐asa.'),
('kam', 'PHM', 1, 8, 'Kwondũ wa ũu, o na kau nĩ na ũnyiau w’onthe nthĩnĩ wa Klĩsto kũkwĩaĩa wĩke ũndũ waile,'),
('kam', 'PHM', 1, 9, 'ĩndĩ kwondũ wa wendo nĩ kavaa nĩkwĩsũve, nĩkwĩthĩwa nyie Vaulo nĩ mũkũũ, na yu nĩ mwovwa wa Klĩsto Yesũ:'),
('kam', 'PHM', 1, 10, '10 nĩkwĩsũva ũndũ wa mwana wakwa, ũla nĩsyaĩte nĩ o mwove, nake nĩ Onesimo,'),
('kam', 'PHM', 1, 11, 'ũla tene ũtaĩ ũuno kwaku, ĩndĩ yu e ũuno kwaku o na kwakwa:'),
('kam', 'PHM', 1, 12, 'nake namũtũma we mwene asyoke kwaku, nake nĩ ngoo yakwa ki:'),
('kam', 'PHM', 1, 13, 'ũla nendie ekale nakwa, nĩ kana anthũkũmae vandũ vaku wovwanĩ wa ũla ũvoo mũseo:'),
('kam', 'PHM', 1, 14, 'ĩndĩ ndinenda kwĩka ũndũ vate ũtw’ĩo waku; nĩ kana ũseo waku ndũkethĩwe ta wa kũĩngĩĩw’a, ĩndĩ wĩthĩwe wa kwenda kwaku.'),
('kam', 'PHM', 1, 15, 'Nũndũ no kwĩthĩwa nĩ kwondũ wa ũu ataaniw’e naku kavinda, nĩ kana wĩthĩwe nake tene na tene;'),
('kam', 'PHM', 1, 16, 'kuma yu ti ta ngombo, ĩndĩ nĩ mbee wa ngombo, nĩ mwana‐a‐asa mwendwa; nyie nĩnĩmwendete mũno, ĩndĩ kwaku nĩ mbee mũno, nthĩnĩ wa mwĩĩ o na nthĩnĩ wa Mwĩaĩi.'),
('kam', 'PHM', 1, 17, 'Ethĩwa ĩndĩ wĩona nyie nĩ ngwatanĩo vamwe naku, mwĩtĩkĩle we o takwa mwene.'),
('kam', 'PHM', 1, 18, 'Ĩndĩ ethĩwa nĩwakũvĩtanĩsye ũndũ, kana e thiĩ naku wa kindũ, andĩka ĩũlũ wakwa;'),
('kam', 'PHM', 1, 19, 'nyie Vaulo niandĩka ũu na kw’oko kwakwa mwene, nyie ngaĩva: o na ndiũkwĩa kana wĩ thiĩ nakwa wa thayũ waku mwene.'),
('kam', 'PHM', 1, 20, 'Ĩĩ, mwana‐a‐asa, nĩthĩwe na ũtanu kwondũ waku nthĩnĩ wa Mwĩaĩi: vuũkya ngoo yakwa nthĩnĩ wa Klĩsto.'),
('kam', 'PHM', 1, 21, 'Ngĩĩkĩĩa mũno wĩwi waku nĩngũkũandĩkĩa, ngĩmanya kana ũkeeka o na kũthonoka ũndũ ngwasya.'),
('kam', 'PHM', 1, 22, 'Ĩndĩ vamwe na ũu nzeũvĩsya vandũ va kwĩkala: nũndũ nĩĩkwatya kwondũ wa mboya syenyu nganengwa kũka kwenyu.'),
('kam', 'PHM', 1, 23, 'Evavila, mwovwa vamwe nakwa nthinĩ wa Klĩsto Yesũ, nĩwaũkethya;'),
('kam', 'PHM', 1, 24, 'na ta ũu Maliko, na Alisitaliko, na Ndema, na Luka, atethya ma wĩa vamwe nakwa.'),
('kam', 'PHM', 1, 25, 'Mumo wa Mwĩaĩi waĩtũ Klĩsto nĩwĩthĩwe na maveva menyu. Ameni.'),
('kam', 'HEB', 1, 1, 'Ngai, ũla waneenie na aasa tene nthĩnĩ wa athani na ilungu nyingĩ na nzĩa nyingĩ,'),
('kam', 'HEB', 1, 2, 'mũminũkĩlyo wa mĩthenya ĩno nũneenete naitũ nthĩnĩ wa Mwana wake, ũla wamwiie ethĩwe mũtiĩwa wa syĩndũ syonthe, na kwondũ wake oombie nthĩ syonthe;'),
('kam', 'HEB', 1, 3, 'nake nĩkwĩthĩwa nĩ kyeni kya ũtheu wake mũtisu, na mũvw’ano ki wa mũvw’anĩle wake, na nĩwĩkalasya syĩndũ syonthe na ndeto ya vĩnya wake, amina ũthesyo wa naĩ, ekala ngalĩ ya kw’oko kwa aũme kwa Ũnene ĩũlũ;'),
('kam', 'HEB', 1, 4, 'nĩkwĩthĩwa nũtw’ĩkĩte mũseo mũno kũvĩtũka alaĩka, o tondũ syĩtwa yake ya ũtiĩwa yĩvĩtũkĩte mũno masyĩtwa moo.'),
('kam', 'HEB', 1, 5, 'Nũndũ nĩ wĩva wa alaĩka ũla, o na ĩvinda yĩva, weiwe, We, nue Mwana wakwa, Ũmũnthĩ nĩnaũsyaa? Na ĩngĩ, Ngeethĩwa Ĩthe wake, Nake akeethĩwa Mwana wakwa?'),
('kam', 'HEB', 1, 6, 'Na aimũete ĩngĩ mũsyawa wa mbee kũũ nthĩ easya, Na alaĩka onthe ma Ngai nĩmamũthaithae.'),
('kam', 'HEB', 1, 7, 'Na ũvoo wa alaĩka easya, Ũla ũtusaa alaĩka make iseve, Na athũkũmi make kĩtw’ĩki kya mwaki:'),
('kam', 'HEB', 1, 8, 'ĩndĩ ũvoo wa Mwana easya, Kĩvĩla kyaku kya ũsumbĩ, we Ngai, nĩ kya tene na tene; Na ndata ya ũsumbĩ ya ũlũngalu nĩyo ndata ya ũsumbĩ waku.'),
('kam', 'HEB', 1, 9, 'We, nĩwendete ũlũngalu, na kũmena ũthũku; Kwondũ wa ũu Ngai, Ngai waku, nĩwakwĩtĩkĩsye mauta, Namo nĩ mauta ma ũtanu, kũvĩta atindan’ya maku.'),
('kam', 'HEB', 1, 10, 'Na ĩngĩ, We, Mwĩaĩi, mwambĩlĩlyonĩ nĩwakwatisye wambĩlĩlyo wa nthĩ, Na matu nĩ mawĩa ma moko maku:'),
('kam', 'HEB', 1, 11, 'Syo ikanangĩka; ĩndĩ we nĩwĩkalaa: Na syonthe ikakũa o ta ngũa;'),
('kam', 'HEB', 1, 12, 'Na ũkaikũnza ta ngũa ya ĩũlũ, Nasyo ikaalyũka ta ngũa: Ĩndĩ we nue ũla wĩkalaa o ũndũ ũmwe, Na myaka yaku ndĩkathela.'),
('kam', 'HEB', 1, 13, 'Ĩndĩ nĩ wĩva wa alaĩka ũla, o na ĩvinda yĩva, weiwe, Ĩkala ngalĩ ya kw’oko kwakwa kwa aũme, Mũvaka natw’a amaitha maku kavĩla ka nyaĩĩ syaku?'),
('kam', 'HEB', 1, 14, 'Asũ onthe ti maveva ma ũthũkũmi, ala matũmitwe kũthũkũma kwondũ wa ala makatiĩwa ũtangĩĩo?'),
('kam', 'HEB', 2, 1, 'Kwondũ wa ũu nĩtwaĩle kũmasũvĩaa mũno maũndũ ala mew’ĩtwe, tũikese kũmatia.'),
('kam', 'HEB', 2, 2, 'Nũndũ ethĩwa ndeto ĩla yaneeniwe nĩ alaika yai nũmu, na kĩla ĩvĩtyo na kũlea kwĩw’a syoosie itũvi yasyo ilũngalu;'),
('kam', 'HEB', 2, 3, 'ithyĩ tũkavonoka ata, twavũthya ũtangĩĩo ũnenevete ũu? Ũla wambie ũneenwa nĩ Mwĩaĩi, na walũlũmĩlw’e kwitũ na ala meewie;'),
('kam', 'HEB', 2, 4, 'Ngai nake akĩkũsĩĩa vamwe nao, na syama na moseng’yo na mavinya ma mĩthemba mingĩ, na mĩthĩnzĩo ya Veva Mũtheu, kwĩanana na kwenda kwake.'),
('kam', 'HEB', 2, 5, 'Nũndũ ndaaia nthĩ ĩla yũkĩte ĩtheo wa alaĩka, ĩla tũũneena ũvoo wayo.'),
('kam', 'HEB', 2, 6, 'Ĩndĩ mũndũ ũmwe aĩ na ũkũsĩ vandũ vamwe, akyasya, Mũndũ nĩ kyaũ, ũndũ ũmũlilikana? Kana mwana wa mũndũ, ũndũ ũthi vala ũĩ?'),
('kam', 'HEB', 2, 7, 'Nĩwamũtwie mũnini ĩvinda kwĩ alaĩka. Nĩwamwĩkĩie ngovia ya ũsumbĩ ya ndaĩa na nguma, Na wamwia ĩũlũ wa mawĩa ma moko maku:'),
('kam', 'HEB', 2, 8, 'Nĩwamwiĩe syĩndũ syonthe wĩnyivyonĩ ungu wa nyaĩĩ syake. Nũndũ akia syĩndũ syonthe ĩtheo wake, ndaatialya kĩndũ kĩmwe kĩtaiĩtwe ĩtheo wake. Ĩndĩ yu tũinamba kwona syĩndũ syonthe siĩtwe ĩtheo wake.'),
('kam', 'HEB', 2, 9, 'Ĩndĩ nĩtũũmwona Yesũ ũla waniniwiv’e ĩvinda kwĩ alaĩka, kwondũ wa mathĩna ma kĩkw’ũ ekĩĩtwe ngovia ya ũsumbĩ ya ndaĩa na nguma, nĩ kana kwondũ wa mumo wa Ngai asame kĩkw’ũ vandũ va kĩla mũndũ.'),
('kam', 'HEB', 2, 10, 'Nũndũ nĩwaĩlwe we, ũla kwondũ wake, na kwondũ wa wĩa wake syĩndũ syonthe syĩ vo, amina kũete ana aingĩ ndaĩanĩ yake, kũmwĩanĩsya mũnene wa ũtangĩĩo woo kwondũ wa mathĩna.'),
('kam', 'HEB', 2, 11, 'Nĩkwĩthĩwa ũla ũvathanasya na ala mavathanaw’a, onthe maumaa nthĩnĩ wa ũmwe: kwondũ wa ũu ndew’aa nthoni kũmeta ana‐a‐ĩthe,'),
('kam', 'HEB', 2, 12, 'akyasya, Ngatavan’ya syĩtwa yaku kwa ana‐a‐asa makwa, Ngakũtaĩĩa ũmbanonĩ.'),
('kam', 'HEB', 2, 13, 'Na ĩngĩ, Ngamwĩkwatya we. Na ĩngĩ, Sisya, nyie na syana ila Ngai ũnengete.'),
('kam', 'HEB', 2, 14, 'Ĩndĩ nĩkwĩthĩwa syana nĩsyosaa mwĩĩ na nthakame, we nake mwene nĩwosie o ta ũu; nĩ kana kwondũ wa kĩkw’ũ amwasye vinya ũla wai na vinya wa kĩkw’ũ, nake nĩ ndevili;'),
('kam', 'HEB', 2, 15, 'na amathasya onthe ala kwondũ wa w’ĩa wa kĩkw’ũ maĩ ũkombonĩ thayũ woo w’onthe.'),
('kam', 'HEB', 2, 16, 'Nũndũ nĩ w’o ndeũmatethya alaĩka, ĩndĩ ematethya ala ma ũsyao wa Avalaamu.'),
('kam', 'HEB', 2, 17, 'Kwondũ wa ũu nĩwaĩlwe we nĩ kũvw’ananw’a maũndũni onthe na ana‐a‐ĩthe make, nĩ kana ethĩwe mũthembi mũnene wĩ tei na kĩthito maũndũnĩ ala melekele Ngai, nĩ kana ethĩwe nthembo ya wĩw’anĩthyo kwondũ wa naĩ sya andũ.'),
('kam', 'HEB', 2, 18, 'Nĩkwĩthĩwa we mwene nĩwathĩniw’e aitatwa, nũtonya kũmatetheesya ala matatawa.'),
('kam', 'HEB', 3, 1, 'Kwondũ wa ũu, ana‐a‐asa atheu, osi ma wĩtano wa ĩtunĩ, sũanĩai mũno ũla Mũtũmwa na Mũthembi Mũnene wa kumbũla kwitũ, nake nĩ Yesũ;'),
('kam', 'HEB', 3, 2, 'ũla waĩ na kĩthito kwa ũla wamwiie, o tondũ Mose nake wailyĩ nyũmbanĩ yake yonthe.'),
('kam', 'HEB', 3, 3, 'Nũndũ we nĩwatalilwe nĩwaĩlwe nĩ ũtaĩo mwingĩ kwĩ Mose, o tondũ ũla wakĩte nyũmba wĩ na ndaĩa nyingĩ kwĩ ĩ nyũmba.'),
('kam', 'HEB', 3, 4, 'Nĩkwĩthĩwa kĩla nyũmba yakĩtwe nĩ mũndũ: ĩndĩ ũla ũseũvĩtye syĩndũ syonthe nĩ Ngai.'),
('kam', 'HEB', 3, 5, 'Na nĩ w’o Mose aĩ na kĩthito nyũmbanĩ yake yonthe ta mũthũkũmi, ethĩwe na ũkũsĩ wa maũndũ asu ala makaneenwa ĩtina;'),
('kam', 'HEB', 3, 6, 'ĩndĩ Klĩsto ta mwana, ĩũlũ wa nyũmba ya Ngai; nayo nyũmba yake nĩ ithyĩ, ethĩwa nĩtũũlũmya mũno ũkũmbaũ witũ na kwĩkathĩĩa kwa wĩkwatyo witũ kũvika mũminũkĩlyo.'),
('kam', 'HEB', 3, 7, 'Kwondũ wa ũu, o tondũ Veva Mũtheu ũnũũneena, Ũmũnthĩ ethĩwa nĩmũkwĩw’a wasya wake,'),
('kam', 'HEB', 3, 8, 'Mũikomye ngoo syenyu, ta yĩla ĩvinda ya kũthatya, Ta mũthenya wa kũtatwa weũnĩ,'),
('kam', 'HEB', 3, 9, 'Vala aaĩthe menyu mandatĩe ũndũ wa kwĩnguũa, Na moona mawĩa makwa myaka mĩongo ĩna.'),
('kam', 'HEB', 3, 10, 'Kwondũ wa ũu new’ĩthiw’e woo nĩ ũsyao ũũ, Na nasya, Nĩmavĩtasya mavinda onthe ngoonĩ syoo: Ĩndĩ matyaamanya nzĩa syakwa;'),
('kam', 'HEB', 3, 11, 'O ũndũ neevĩtie ũthilĩkunĩ wakwa, Matikalika ũthũmũonĩ wakwa.'),
('kam', 'HEB', 3, 12, 'Ĩsũvĩei, ana‐a‐asa, kũikese kwĩthĩwa ũmwe wenyu wĩ na ngoo mbathe ya ũlea kwĩtĩkĩla, na kwĩvathana na Ngai ũla wĩ thayũ:'),
('kam', 'HEB', 3, 13, 'ĩndĩ taanai kĩla mũndũ na ũla ũngĩ mĩthenya yonthe, o ĩvinda yĩla yĩtawa Ũmũnthĩ; nĩ kana kũikethĩwe ũmwe wenyu ũtw’ĩka mũmũ kwondũ wa ũkengani wa naĩ:'),
('kam', 'HEB', 3, 14, 'nũndũ nĩtũw’ĩkĩte osi vamwe na Klĩsto, ethĩwa nĩtũkwataa wambĩlĩlyo wa kũĩkĩĩa kwitũ tũkĩlũmya kũvika mũminũkĩlyo:'),
('kam', 'HEB', 3, 15, 'yĩla kũũneenwa, Ũmũnthĩ ethĩwa nĩmũkwĩw’a wasya wake, Mũikomye ngoo syenyu, ta yĩla ĩvinda ya kũthatya.'),
('kam', 'HEB', 3, 16, 'Nũndũ naaũ ala mathatisye yĩla meewie? Ti o asu onthe ala maumie Misili makĩtongoew’a nĩ Mose?'),
('kam', 'HEB', 3, 17, 'Na naaũ ala mamwĩw’ĩthisye woo myaka mĩongo ĩna? Ti o asu ala mavĩtisye, ala simba syoo syavalũkile weũnĩ?'),
('kam', 'HEB', 3, 18, 'Na ĩngĩ naaũ ala wevĩtie kana maikalika ũthũmũonĩ wake, ate o asu ala mataaĩw’a?'),
('kam', 'HEB', 3, 19, 'Na ithyĩ nĩtũkwona kana matyaatonya kũlika kwondũ wa kũlea kwĩtĩkĩla.'),
('kam', 'HEB', 4, 1, 'Nĩkwĩthĩwa watho nĩvo ũĩ wa kũlika ũthũmũonĩ wake, twĩthĩwe ĩndĩ na w’ĩa, kũikethĩwe mũndũ o na wĩva katĩ wenyu ũla ũnũkwoneka ta waemiwe nĩ kũvikĩa.'),
('kam', 'HEB', 4, 2, 'Nũndũ nĩ w’o ithyĩ nĩtwataviw’e ũla ũvoo mũseo, o tamo: ĩndĩ ĩla ndeto yew’ĩkie ndĩaamauna nĩkwĩthĩwa ndyaavulanw’a na mũĩkĩĩo kwa ala mamĩwie.'),
('kam', 'HEB', 4, 3, 'Nũndũ ithyĩ ala twĩtĩkĩlĩte nĩtũvotaa ũthũmũonĩ ũsu; o tondũ waisye, O ũndũ neevĩtie ũthilĩkunĩ wakwa, Matikalika ũthũmũonĩ wakwa: o na kau mawĩa nĩmaminiwe kuma mwambĩlĩlyo wa nthĩ.'),
('kam', 'HEB', 4, 4, 'Nũndũ nũneenete vandũ vamwe ũvoo wa mũthenya wa mũonza ta ũũ, Na Ngai nĩwathũmũie mũthenya wa mũonza ũndũ wa mawĩa make onthe;'),
('kam', 'HEB', 4, 5, 'na vaa navo, Matikalika ũthũmũonĩ wakwa.'),
('kam', 'HEB', 4, 6, 'Ĩndĩ nĩkũtialĩte amwe makalika nthĩnĩ waw’o, na ala mambie ũtavw’a ũla ũvoo mũseo maiaalika nũndũ wa kũlea kwĩw’a,'),
('kam', 'HEB', 4, 7, 'nĩwiĩte ĩngĩ mũthenya ũmwe, Ũmũnthĩ, akyasya nthĩnĩ wa Ndaviti ĩtina wa ĩvinda ĩasa (o tondũ kwaneeniwe mbee), Ũmũnthĩ ethĩwa nĩmũkwĩw’a wasya wake, Mũikomye ngoo syenyu.'),
('kam', 'HEB', 4, 8, 'Nũndũ kethĩwa Yosua amanengie ũthũmũo, ndethĩwa aaneena ĩtina ũvoo wa mũthenya ũngĩ.'),
('kam', 'HEB', 4, 9, 'Nĩvatialĩte ĩndĩ ũthũmũo wa savato ũndũ wa andũ ma Ngai.'),
('kam', 'HEB', 4, 10, 'Nũndũ ũla ũlikĩte ũthũmũonĩ wake nũthũmũĩte mwene ũndũ wa mawĩa make, o ũndũ Ngai wathũmũie ũndũ wa mawĩa make.'),
('kam', 'HEB', 4, 11, 'Twĩthing’ĩĩsye ĩndĩ kũvota ũthũmũoni ũsu, nĩ kana mũndũ o na wĩva ndakavalũke kwondũ wa kũatĩĩa ngelekan’yo ĩsu ya kũlea kwĩw’a.'),
('kam', 'HEB', 4, 12, 'Nĩkwĩthĩwa ndeto ya Ngai ĩ thayũ, na nĩ nthangaau, na nĩ mbũĩ kwĩ ũvyũ ũla mũĩ ngalĩ syelĩ, nayo ĩtonyaa kũvika kũaan’ya thayũ na veva, na maleenyũ na mũthungo, na ĩ mĩtũkĩ ya kũmanya mosũanĩo na kwenda kwa ngoo.'),
('kam', 'HEB', 4, 13, 'Na vai kĩndũ kyũmbe kĩtaumĩlĩte mbee wake: ĩndĩ syĩndũ syonthe nĩ nthei na kumĩlw’a methonĩ ma ũla wĩ na maũndũ maitũ.'),
('kam', 'HEB', 4, 14, 'Ĩndĩ nĩkwĩthĩwa twĩ na mũthembi mũnene mbee, ũla walikile ĩtunĩ, Yesũ Mwana wa Ngai, tũkwate mũno kumbũla kwitũ.'),
('kam', 'HEB', 4, 15, 'Nũndũ tũi na mũthembi mũnene ũla ũtatonya kũtwĩw’ĩa tei mawonzunĩ maitũ; ĩndĩ nĩ ũmwe watatiwe maũndũnĩ onthe o tondũ tũtatawa, ate na naĩ.'),
('kam', 'HEB', 4, 16, 'Nĩtũthengeee ĩndĩ na ũkũmbaũ kĩla kĩvĩla kya ũsumbĩ kya mumo, nĩ kana twose ĩnee, na kwona mumo wa kũtũtethya ĩvinda ya vata.'),
('kam', 'HEB', 5, 1, 'Nũndũ kĩla mũthembi mũnene, aumĩtw’e katĩ wa andũ, aiĩtwe kwondũ wa andũ maũndũnĩ ala melekele Ngai, nĩ kana athembe mĩthĩnzĩo na nthembo kwondũ wa naĩ:'),
('kam', 'HEB', 5, 2, 'ũla ũtonya kũmĩĩsya e mũuu kwa ala mate na ũmanyi na ala mavĩtasya, nũndũ we mwene nũthyũlũlũkĩtwe nĩ wonzu;'),
('kam', 'HEB', 5, 3, 'na kwondũ wa ũu nĩwaĩlwe nĩ kũthemba kwondũ wa naĩ, ũndũ wa naĩ sya andũ o na syake mwene.'),
('kam', 'HEB', 5, 4, 'Na vai mũndũ ũkwĩyosea mwene ndaĩa ĩsu, no ũla wĩĩtwa nĩ Ngai, o ta Aluni.'),
('kam', 'HEB', 5, 5, 'Ta ũu Klĩsto nake ndaaĩnenevya mwene atuwe mũthembi mũnene, ĩndĩ nĩ ũla waneenie nake, We nue Mwana wakwa, Ũmũnthĩ nĩnaũsyaa:'),
('kam', 'HEB', 5, 6, 'o tondũ easya vandũ vangĩ, We wĩ mũthembi wa tene na tene O ta ũndũ Melikiseteki wailyĩ.'),
('kam', 'HEB', 5, 7, 'Ũla, matukũ ma mwĩĩ wake, wamũvoyie ũla waĩ atonya kũmũtangĩĩa kũmumya kĩkw’ũnĩ, na mboya na mawĩsũvano vamwe na kũĩa mũno na methoi, na eethukĩĩw’a nũndũ wa kũmũkĩa Ngai,'),
('kam', 'HEB', 5, 8, 'o na kau aĩ Mwana, eemanyĩsya kwĩw’aa ũndũ wa mathĩna ala mamũkwatie;'),
('kam', 'HEB', 5, 9, 'na eanĩw’a, atw’ĩka mwambĩlĩlya wa ũtangĩĩo wa tene na tene kwa onthe ala mamwĩw’aa;'),
('kam', 'HEB', 5, 10, 'ũla wetiwe nĩ Ngai ethĩwe mũthembi mũnene o ta ũndũ Melikiseteki wailyĩ.'),
('kam', 'HEB', 5, 11, 'Twĩ na maũndũ maingĩ ma ũneena ũvoonĩ wake, namo nĩ vinya kũmavuan’ya nũndũ mũtw’ĩkĩte andũ ala matew’aa nesa.'),
('kam', 'HEB', 5, 12, 'Nũndũ wa ĩvinda ĩasa yĩvĩtĩte mwaĩle kwĩthĩwa mwĩ amanyĩsya, ĩndĩ mwĩ na vata wa mũndũ kũmũmanyĩsya ĩngĩ momanyĩsyo ma mbee ma ndeto ila syaneeniwe nĩ Ngai; na mũtw’ĩkĩte ala me na vata wa ĩia, na ti lĩu mũmũ.'),
('kam', 'HEB', 5, 13, 'Nũndũ kĩla mũndũ ũnyusaa ĩia ndesĩ mũno ndeto ya ũlũngalu; nũndũ nĩ kana kanini.'),
('kam', 'HEB', 5, 14, 'Ĩndĩ lĩu mũmũ nĩ wa andũ aima, ala, nũndũ wa kwĩmanyĩsya, ilĩko syoo nimanyĩĩtw’e kũvathũkan’ya ũseo na ũthũku.'),
('kam', 'HEB', 6, 1, 'Kwondũ wa ũu tũkĩtia momanyĩsyo ma maũndũ ma mbee ma Klĩsto, twĩthing’ĩĩsye kũendeea mbee kũvikĩa wĩanĩu; tũte kwia ĩngĩ wambĩlĩlyo wa ũalyũlo wa ngoo kuma mawĩanĩ ala makw’ũ, na wa kũĩkĩĩa Ngai,'),
('kam', 'HEB', 6, 2, 'na wa momanyĩsyo ma movatiso, na wa kwilĩĩlwa moko, na wa kũthayũũkw’a kwa akw’ũ, na wa ũsilĩlo wa tene na tene.'),
('kam', 'HEB', 6, 3, 'Na ũu tũkeeka ethĩwa Ngai akatũtethya.'),
('kam', 'HEB', 6, 4, 'Na ũndũ wa ala maminĩte kũnengwa kyeni na kũsama ũla mũthĩnzĩo wa ĩtunĩ, na kũtuwa osi ma Veva Mũtheu,'),
('kam', 'HEB', 6, 5, 'na kũsama ndeto nzeo ya Ngai, na mavinya ma ĩvinda yĩla yũkĩte,'),
('kam', 'HEB', 6, 6, 'na ĩndĩ makĩalyũka na kũtia, kũtitonyeka kũmatũnga eũ ĩngĩ kũvikĩa ũalyũlo wa ngoo; nĩkwĩthĩwa memwambĩthya ĩngĩ Mwana wa Ngai kwa o ene, na kũmũsonokya ũtheinĩ.'),
('kam', 'HEB', 6, 7, 'Nũndũ nthĩ ĩla ĩnyw’ĩte mbua ĩla ĩmyuĩaa mavinda maingĩ, na ĩimesya nyũnyi ĩmaĩle ala ĩĩmawa kwondũ wamo, yosaa ũathimo kuma kwa Ngai:'),
('kam', 'HEB', 6, 8, 'ĩndĩ ethĩwa nĩnĩkũmesya mĩw’a na thangila, nĩleawa na ĩ vakuvĩ na kũumanĩwa; na mũminũkĩlyo wayo nĩ kũvĩvw’a.'),
('kam', 'HEB', 6, 9, 'Ĩndĩ, endwa, o na ethĩwa nĩtũũneena ũu, nĩtwĩtĩkĩlĩte maũndũ maseo mbee kwenyu, na maũndũ ala makwatene na ũtangĩĩo:'),
('kam', 'HEB', 6, 10, 'nĩkwĩthĩwa Ngai ti ũla ũte mũlũngalu ũndũ ũtonya kũlwa nĩ wĩa wenyu na wendo ũla mwonanĩtye kwondũ wa syĩtwa yake, nĩkwĩthĩwa nĩmwamathũkũmie ala atheu, o na yu nĩmũmathũkũmaa.'),
('kam', 'HEB', 6, 11, 'Na nĩtũkwenda kĩla ũmwe wenyu onanasye kĩthing’ĩĩsyo kyu kũvikĩa wĩanĩu wa wĩkwatyo o na kũvika mũminũkĩlyo:'),
('kam', 'HEB', 6, 12, 'nĩ kana mũikethĩwe atulu, ĩndĩ mũkĩelekan’ya na ala meũtiĩwa matho kwondũ wa mũĩkĩĩo na wũmĩĩsyo.'),
('kam', 'HEB', 6, 13, 'Nũndũ yĩla Ngai wamwathie Avalaamu, nĩkwĩthĩwa ndaatonya kwĩvĩta na ũngĩ mũnene mbee, nĩwevĩtie we mwene,'),
('kam', 'HEB', 6, 14, 'akyasya, Nĩ w’o kũũathima ngakũathima, na kwingĩvya ngakwingĩvya.'),
('kam', 'HEB', 6, 15, 'Na kwondũ wa ũu, ĩtina wa kũmĩĩsya kwake, nĩwosie ũla watho.'),
('kam', 'HEB', 6, 16, 'Nũndũ andũ mevĩtaa na ũla mũnene: na nthĩnĩ wa ngananĩo syoo syonthe wĩvĩto nĩw’o ũminaa ũvoo ũlũme.'),
('kam', 'HEB', 6, 17, 'Nthĩnĩ wa ũvoo ũsu Ngai, akyenda kũmon’ya mũno mbee atiĩwa ma ũla watho ũndũ ũtw’ĩo wake ũtatonya kũalyũka, nĩwekĩie wĩvĩto katĩ wake namo;'),
('kam', 'HEB', 6, 18, 'nĩ kana kwondũ wa maũndũ elĩ ala mataalyũlĩka, nao nthĩnĩ wamo kũitonyeka Ngai kũneena ũvũngũ, twĩthĩwe na ũkiakisyo wĩ na vinya, ithyĩ ala twakũkie twone wĩvitho tũkwate wĩkwatyo ũla wiĩtwe mbee waitũ:'),
('kam', 'HEB', 6, 19, 'ũla twĩ naw’o ta nanga ya ngoo, wĩkwatyo wĩ na ũlũmu na ũtakũĩka, ũlikaa nthĩnĩ wa vala ve ũla tũtũ;'),
('kam', 'HEB', 6, 20, 'vala Yesũ ta mũtongoesya walikile kwondũ witũ, atw’ĩkĩte mũthembi mũnene wa tene na tene o ta ũndũ Melikiseteki wailyĩ.'),
('kam', 'HEB', 7, 1, 'Nũndũ Melikiseteki ũsu, mũsumbĩ wa Saleme, mũthembi wa Ngai Ũla Wĩ Ĩũlũ wa Onthe, ũla wakomanie na Avalaamu asyokete kuma kũmoaa asumbĩ, na amũathima,'),
('kam', 'HEB', 7, 2, 'na ũla Avalaamu wamũaĩe kĩlungu kya ĩkũmi kya syĩndũ syonthe (mbee, ũalyũlo wa syĩtwa yĩu nĩ, Mũsũmbĩ wa ũlũngalu, na ĩngĩ, Mũsumbĩ wa Saleme, ũalyũlo wayo nĩ, Mũsumbĩ wa mũuo;'),
('kam', 'HEB', 7, 3, 'ũte ĩthe, ũte nyinyia, ũte mosyaanĩo ma mbaĩ yake, ũte wambĩlĩlyo wa mĩthenya yake kana mũminũkĩlyo wa thayũ wake, ĩndĩ avw’ananw’a na Mwana wa Ngai), ekalaa e mũthembi tene na tene.'),
('kam', 'HEB', 7, 4, 'Sũanĩaĩ ĩndĩ ũndũ mũndũ ũsu wanenevete, ũla Avalaamu, ĩthe waitũ mũnene, wamũnengie kĩlungu kya ĩkũmi kya syĩndũ ila syaĩ nzeo mbee sya mũtavo.'),
('kam', 'HEB', 7, 5, 'Na nĩ w’o ala ma ana ma Livaĩ ala mosaa ũthembi me na mwĩao wa kwosa ilungu sya ĩkũmi sya andũ kwĩanana na ĩla mĩao, na ũu nĩ kwa ana‐a‐ĩthe moo, o na kau asu maumĩte kĩnyunyunĩ kya Avalaamu:'),
('kam', 'HEB', 7, 6, 'ĩndĩ we, ũla mosyaanĩo make matatalawa kuma kwa asu, nĩwosie ilungu sya ĩkũmi sya Avalaamu, na amũathima ũsu waĩ na ala matho.'),
('kam', 'HEB', 7, 7, 'Ĩndĩ vate ngananĩo ũla mũnini nũathimawa nĩ ũla mũnene.'),
('kam', 'HEB', 7, 8, 'Na vaa andũ ala makusaa nĩmosaa ilungu sya ĩkũmi; ĩndĩ ku kwaĩ ũmwe wosie, ũla ũkũsĩĩawa kana e thayũ.'),
('kam', 'HEB', 7, 9, 'Na nĩkũtonya kũneenwa, kana kwa nzĩa ya Avalaamu, o na Livai, ũla wosaa ilungu sya ĩkũmi, nake nĩwaumisye ilungu sya ĩkũmi;'),
('kam', 'HEB', 7, 10, 'nũndũ we aĩ kĩnyunyunĩ kya ĩthe wake Avalaamu, o yĩla Melikiseteki wakomanie nake.'),
('kam', 'HEB', 7, 11, 'Ĩndĩ ethĩwa kwaĩ wĩanĩu kwondũ wa ũthembi wa Alivai (nĩkwĩthĩwa andũ nĩmoosie ĩla mĩao kwondũ waw’o), kwaĩ vata ũngĩ wa kyaũ kana mũthembi ũngĩ okĩle ũilyĩ ta Melikiseteki, na ndakatalwa ta ũndũ Aluni wailyĩ?'),
('kam', 'HEB', 7, 12, 'Nĩkwĩthĩwa ũthembi waalyũka, no mũvaka ĩla mĩao nayo ĩalyũke.'),
('kam', 'HEB', 7, 13, 'Nũndũ ũla ũneeneawa maũndũ asu nĩ wa mbaĩ ĩngĩ, na kuma nthĩnĩ wayo vai mũndũ ũla wathũkũmie kĩthembeonĩ.'),
('kam', 'HEB', 7, 14, 'Nĩkwĩthĩwa nĩwenekee vyũ kana Mwĩaĩi waitũ aumie mbaĩnĩ ya Yuta; na Mose ndaaneena ũvoo wa athembi mbaĩnĩ ĩsu.'),
('kam', 'HEB', 7, 15, 'Na ũndũ ũla tũũneena nĩwenekee mũno mbee, ethĩwa mũthembi ũngĩ akookĩla ũilyĩ ta Melikiseteki,'),
('kam', 'HEB', 7, 16, 'ũla watwiwe mũthembi, ti kwondũ wa ũtw’ĩo wa mwĩao ũla wĩ kwondũ wa mwĩĩ, ĩndĩ kwondũ wa vinya wa thayu ũtathela:'),
('kam', 'HEB', 7, 17, 'nũndũ nĩwakũsĩĩwe, We wĩ mũthembi wa tene na tene O ta ũndũ Melikiseteki wailyĩ.'),
('kam', 'HEB', 7, 18, 'Nũndũ kwĩ kũveta kwa ũla mwĩao ũla waĩ mbee nũndũ ndwĩ vinya na ndwĩ vata'),
('kam', 'HEB', 7, 19, '(nũndũ ĩla mĩao ndyaaĩanĩsya ũndũ), na kwĩ kũete wĩkwatyo mũseo mbee, ũla kwondũ waw’o tũmũthengeeaa Ngai.'),
('kam', 'HEB', 7, 20, 'Na nĩkwĩthĩwa ũndũ ũsu ndwaaĩkwa vate wĩvĩto'),
('kam', 'HEB', 7, 21, '(nũndũ nĩ w’o asu matwiwe athembi vate wĩvĩto; ĩndĩ we nĩwatwiwe na wĩvĩto nĩ ũla wamwĩie, Mwĩaĩi nĩwevĩtie na ndakealyũla, We wĩ mũthembi wa tene na tene);'),
('kam', 'HEB', 7, 22, 'kwĩanana na ũndũ o ũsu Yesũ atw’ĩkĩte mũĩkĩĩwa wa ũtianĩo mũseo mbee.'),
('kam', 'HEB', 7, 23, 'Na nĩ w’o nĩmatwiwe athembi aingĩ, nĩkwĩthĩwa kwondũ wa kĩkw’ũ nĩmeũsiĩĩwa kwĩkalaa:'),
('kam', 'HEB', 7, 24, 'ĩndĩ we, nĩkwĩthĩwa ekalaa kũvika tene na tene, e na ũthembi wake ũla ũtatwĩkanaa.'),
('kam', 'HEB', 7, 25, 'Kwondũ wa ũu nake nũtonya kũmatangĩĩa vyũ ala mamũthengeeaa Ngai mavĩtĩle kwake, nũndũ e thayũ mĩthenya yonthe kũmavoyeaa.'),
('kam', 'HEB', 7, 26, 'Nĩkwĩthĩwa mũthembi mũnene ta ũsu nĩwatwaĩle ithyĩ, ũla mũtheu, ũtaĩ na ũkengani, ũtaĩ na ũvuku, ũla wavathanĩtw’e na andũ athe, na watũlilw’e ĩũlũ wa matu;'),
('kam', 'HEB', 7, 27, 'ũla ũte vata kĩla mĩthenya, ta athembi asu anene, kumya nthembo, mbee kwondũ wa nai syake mwene, na ĩndĩ kwondũ wa naĩ sya andũ; nũndũ nĩwekie ũu o ĩmwe, yĩla weyumisye mwene.'),
('kam', 'HEB', 7, 28, 'Nũndũ ĩla mĩao ĩmaiaa andũ me na wonzu methĩwe athembi anene; ĩndĩ ndeto ya wĩvĩto, ũla wookie ĩtina wa ĩla mĩao, yamwiie Mwana ũla wĩanĩe kũvika tene na tene.'),
('kam', 'HEB', 8, 1, 'Ĩndĩ maũndũnĩ ala tũũneena ũndũ wa mbee nĩ atiĩ: Twĩ na mũthembi mũnene ũilyĩ ũu, ũla wekalile ngalĩ ya kw’oko kwa aũme kwa kĩvĩla kya ũsumbĩ kya ũla Ũnene matunĩ,'),
('kam', 'HEB', 8, 2, 'mũthũkũmi wa vandũ vatheu, na wa ĩeema yĩla ya w’o, yĩla yaakiwe nĩ Mwĩaĩi, na ti mũndũ.'),
('kam', 'HEB', 8, 3, 'Nũndũ kĩla mũthembi mũnene aiawa nĩ kana athembe mĩthĩnzĩo na nthembo ya kũtonywa: kwondũ wa ũu nĩkwaĩle kana mũthembi ũũ mũnene ethĩwe na kĩndũ kya ũthemba.'),
('kam', 'HEB', 8, 4, 'Ĩndĩ kethĩwa e kũũ nthĩ, ndethĩwa e mũthembi nongi, nĩkwĩthĩwa kwĩ ala mathembaa mĩthĩnzĩo kwĩanana na ĩla mĩao;'),
('kam', 'HEB', 8, 5, 'ala mathũkũmaa ngelekan’yo na kyuu kya syĩndũ sya ĩtunĩ, o tondũ Mose wataiwe nĩ Ngai weyũmbanĩtye kwaka yĩla ĩeema: nũndũ easya, Sisya kana ũseũvye syĩndũ syonthe o ta ngelekan’yo ĩla woonew’e kĩĩmanĩ.'),
('kam', 'HEB', 8, 6, 'Ĩndĩ yu nĩwosete ũthũkũmi ũla mũseo mbee, kwĩanana na ũndũ we nake nĩ mwĩw’anĩthya wa ũtianĩo mũseo mbee, ũla watwiwe ĩũlũ wa matho maseo mbee.'),
('kam', 'HEB', 8, 7, 'Nũndũ kethĩwa ũtianĩo wa mbee, waĩ mwĩanĩu, vaiĩthĩwa na ũthei wa kũmantha ũngĩ wa kelĩ.'),
('kam', 'HEB', 8, 8, 'Nũndũ aimonea mavĩtyo, easya, Sisyai, mĩthenya nĩyũkĩte, easya ũu Mwĩaĩi, Yĩla ngatianĩa ũtianĩo mweũ na nyũmba ya Isilaeli na nyũmba ya Yũta;'),
('kam', 'HEB', 8, 9, 'Ndũkethĩwa ũilyĩ ta ũtianĩo ũla natianĩe na aaĩthe moo Mũthenya ũla namakwatie moko kũmatongoesya kũmaumya nthĩ ya Misili; Nũndũ matyaaĩkala ũtianĩonĩ wakwa, Nakwa ndyaamona ta kĩndũ, easya ũu Mwĩaĩi.'),
('kam', 'HEB', 8, 10, 'Nũndũ ũũ nĩw’o ũtianĩo ũla ngatianĩa na nyũmba ya Isilaeli Ĩtina wa mĩthenya ĩsu, easya ũu Mwĩaĩi; Ngeekĩa mĩao yakwa ilĩkonĩ syoo, Na ngamĩandĩka ngoonĩ syoo: Na ngeethĩwa Ngai woo, Nao makeethĩwa andũ makwa:'),
('kam', 'HEB', 8, 11, 'Na matĩkamanyĩan’ya kĩla mũndũ na mũtũi wake, Na kĩla mũndũ na mwana‐a‐inyia wake, makyasya, Mũmanye Mwĩaĩi: Nĩkwĩthĩwa onthe makamanya nyie, Kuma ũla mũnini woo kũvika ũla mũnene woo.'),
('kam', 'HEB', 8, 12, 'Nũndũ ngeew’ĩaa tei mothũkũ moo, Na naĩ syoo ndikaililikana ĩngĩ.'),
('kam', 'HEB', 8, 13, 'We, kwondũ wa kũneena, Ũtianĩo mweũ, nĩwatwie ũla wa mbee mũkũũ. Ĩndĩ kĩla kyambĩlĩlya ũkũa na kwanangĩka nĩ vakuvĩ kĩthele vyũ.'),
('kam', 'HEB', 9, 1, 'Ĩndĩ o na ũla ũtianĩo wa mbee waĩ na motw’io ma kũthaitha Ngai, na vandũ vatheu vaw’o vaĩ va nthĩ ĩno.'),
('kam', 'HEB', 9, 2, 'Nũndũ nĩkwaseũvitw’e ĩeema, yĩla ya mbee, nthĩnĩ wayo kwaĩ kĩndũ kĩla kyeekĩawa mataa, na mesa, na imũtũ ila syaiĩawa Ngai; vala veetawa Vandũ Vatheu.'),
('kam', 'HEB', 9, 3, 'Na ĩtina wa tũtũ wa kelĩ, yĩla ĩeema yeetawa Vandũ Vatheu mbee;'),
('kam', 'HEB', 9, 4, 'na vo vaĩ kĩtoeesya kya thaavu kya kũtoeesya ũvani, na ĩsandũkũ ya ũtianĩo yavw’ĩkĩtwe thaavu ngalĩ syonthe ĩũlũ na nthĩnĩ, na nthĩnĩ wayo vaĩ kavisũ ka thaavu kala kaĩ na lĩu wĩtawa mana, na ndata ya Aluni ĩla yathongooie, na masengea ma mavia ma ũla ũtianĩo;'),
('kam', 'HEB', 9, 5, 'na ĩũlũ wayo vaĩ akeluvi ma ũtheu mũtisu mekĩae muunyĩ wĩkalonĩ wa tei; tũitonya kũneena yu ũvoo wa syĩndũ ĩsu kĩmwe na kĩmwe.'),
('kam', 'HEB', 9, 6, 'Ĩndĩ syĩndũ isu iminĩtwe kũseũvw’a ũu, athembi nĩmalikaa ĩeemanĩ ya mbee mĩthenya yonthe, makĩanĩsya ũthaithi woo;'),
('kam', 'HEB', 9, 7, 'ĩndĩ vala va kelĩ mũthembi mũnene avotaa weka, o ĩmwe kĩla mwaka, ĩndĩ ndalikaa vate nthakame, ĩla wathembaa kwondũ wake mwene, na kwondũ wa mavĩtyo ma andũ:'),
('kam', 'HEB', 9, 8, 'Veva Mũtheu akyonan’ya kana nzĩa ya kũlika vandũ vatheu ndĩnamba kwonanw’a, yĩla ĩeema ya mbee yĩũngeme;'),
('kam', 'HEB', 9, 9, 'na ũndũ ũũ naw’o nĩ ngelekan’yo ya ĩvinda yĩĩ twĩ nayo; na kwĩanana nayo mĩthĩnzĩo na nthembo sya kũtonywa nithembawa ila itatonya kũmwĩanĩsya ũsu ũthaithaa ũndũ wa wasya wa ngoo,'),
('kam', 'HEB', 9, 10, 'nĩkwĩthĩwa nĩ motw’ĩo ma maũndũ ma mwĩĩ ki, sya ũya na sya ũnyw’a na kũthesya kwa mĩthemba mingĩ, ala maiiwe kũvika ĩvinda yĩkoka yĩla maũndũ makaseũvw’a methĩwe meũ.'),
('kam', 'HEB', 9, 11, 'Ĩndĩ Klĩsto ooka mũthembi mũnene wa maũndũ maseo ala makethĩwa kwondũ wa ieema ĩnene na yĩanĩu mbee, yĩtaseũvĩtw’e na moko, na ũu nĩ kwasya, ti ya wũmbe ũũ,'),
('kam', 'HEB', 9, 12, 'o na ti kwondũ wa nthakame ya mbũi na tũsaũ, ĩndĩ kwondũ wa nthakame yake mwene, nĩwavotie vala vandũ o ĩmwe tũ, osete wovosyo wa tene na tene.'),
('kam', 'HEB', 9, 13, 'Nũndũ ethĩwa nthakame ya mbũi na nzaũ, na kwĩtĩkya mũu wa moi ĩũlũ wa ala mavukĩtw’e, nitheasya kũvika kũthesya mwĩĩ:'),
('kam', 'HEB', 9, 14, 'nĩ mbee veana ata nthakame ya Klĩsto, ũla kwondũ wa Veva wa tene na tene wenenganie mwene kwa Ngai ate kĩema, kũtheasya wasya wa ngoo wenyu mume mawĩanĩ makw’ũ mũthũkũme Ngai ũla wĩ thayũ?'),
('kam', 'HEB', 9, 15, 'Na kwondũ wa ũu nĩ mwĩw’anĩthya wa ũtianĩo mweũ, kana kĩkw’ũ kyamina kwĩthĩwa kw’o ũndũ wa wovosyo wa mavĩtyo ala meekĩtwe ĩvinda ya ũtianĩo wa mbee, ala meetiwe mose ũla watho wa ũtiĩwa wa tene na tene.'),
('kam', 'HEB', 9, 16, 'Nũndũ vala ve ũtianĩo, mũvaka vethĩwe kĩkw’ũ kya ũla watianĩa.'),
('kam', 'HEB', 9, 17, 'Nũndũ ũtianĩo wĩ na vinya vala ve kĩkw’ũ: nũndũ ndwĩ na vinya o na ĩndĩĩ yĩla ũla watianĩa wĩ thayũ.'),
('kam', 'HEB', 9, 18, 'Kwondũ wa ũu o na ũtianĩo wa mbee ndwaambĩlĩlw’a vate nthakame.'),
('kam', 'HEB', 9, 19, 'Nũndũ Mose amina kũneena na andũ onthe kĩla mwĩao o tondũ kweeaiwe ĩla mĩaonĩ, oosaa nthakame ya tũsaũ na mbũi, vamwe na manzĩ na w’ĩa mũtune wa ĩlondu na ĩseve ya mũtĩ wa ĩsovo, na aminzangĩsya ĩvuku e yo na andũ onthe,'),
('kam', 'HEB', 9, 20, 'akyasya, Ĩno nĩyo nthakame ya ũtĩanĩo ũla Ngai wamwĩaĩe.'),
('kam', 'HEB', 9, 21, 'Na ĩngĩ ĩeema na mĩio yonthe ya ũthaithĩ aminzangĩsya nthakame o ta ũu.'),
('kam', 'HEB', 9, 22, 'Na kwĩanana na ĩla mĩao, vakuvĩ syĩndũ syonthe nitheaw’a na nthakame, na vate kwĩtĩka nthakame ũekeo ndwoneka.'),
('kam', 'HEB', 9, 23, 'Ĩndĩ mũvaka ngelekan’yo sya syĩndũ syĩ ĩtũnĩ ithew’e na nthembo isu; ĩndĩ syindũ sya itunĩ syo ithew’e na nthembo sya kũtonywa nzeo kwĩ isu.'),
('kam', 'HEB', 9, 24, 'Nũndũ Klĩsto ndaalika vandũ vatheu vaseũvĩtw’e na moko, ngelekan’yo ya vala va w’o; ĩndĩ alikile ĩtunĩ e yo, nĩ kana onekae yu mbee wa ũthyũ wa Ngai kwondũ witũ:'),
('kam', 'HEB', 9, 25, 'o na ti kana eyumye mwene mavinda maingĩ, o ũndũ mũthembĩ mũnene ũlikaa vala vandũ vatheu kĩla mwaka na nthakame ĩte yake mwene;'),
('kam', 'HEB', 9, 26, 'kethĩwa nĩ ũu, ethĩwa athĩniw’e mavinda maingĩ kuma mwambĩlĩlyo wa nthĩ: ĩndĩ yu o ĩmwe tũ ĩvinda ya mũminũkĩlyo wa mavinda nĩwonaniw’e nĩ kana avete naĩ aithembwa e we mwene.'),
('kam', 'HEB', 9, 27, 'Na o ũndũ andũ matw’ĩĩwe maiiwe kũkw’a o ĩmwe, na ĩtina wa kũkw’a ũsilĩlo;'),
('kam', 'HEB', 9, 28, 'o ta ũu Klĩsto, aumw’a o ĩmwe akue naĩ sya aingĩ, akaumĩla ĩvinda ya kelĩ, ate na ũvoo wa naĩ, kwa ala mamweteelaa kũvikĩa ũtangĩĩo.'),
('kam', 'HEB', 10, 1, 'Nĩkwĩthĩwa ĩla mĩao yaĩ kyuu kya syĩndũ nzeo ĩla ikoka, na ti mũvw’ano vyũ wa syĩndũ isu, ndĩtonya o na ĩndĩĩ na nthembo isu ila maumasya kĩla mwaka, kũmeanĩsya ala mathengeeaa.'),
('kam', 'HEB', 10, 2, 'Kethĩwa nitonya itiekwa kũthembwa? Nĩkwĩthĩwa athaithi, mamina kũthew’a ĩvinda yĩmwe, matyĩyona ĩngĩ me na nai.'),
('kam', 'HEB', 10, 3, 'Ĩndĩ nthembonĩ isu kwĩ kũlilikanw’a naĩ kĩla mwaka.'),
('kam', 'HEB', 10, 4, 'Nũndũ ndũtonyeka nthakame ya nzaũ na mbũi kũveta naĩ.'),
('kam', 'HEB', 10, 5, 'Kwondũ wa ũu akyũka kũũ nthĩ, easya, Nthembo ya kũtonywa na syĩndũ ila syumaw’a ndwaasyenda, Ĩndĩ wanzeũvĩsye mwĩĩ;'),
('kam', 'HEB', 10, 6, 'Ndwaaendeew’a nĩ ila nthembo nima sya kũvĩvw’a na nthembo kwondũ wa naĩ:'),
('kam', 'HEB', 10, 7, 'Nĩvo naisye, Sisya, nĩnooka (Ĩvukunĩ ĩkũnze nĩkũandĩkĩtwe ũndũ wakwa) Kwĩka kwenda kwaku, we Ngai.'),
('kam', 'HEB', 10, 8, 'Aneenete mbee, Nthembo sya kũtonywa na syĩndũ ila syumaw’a na nthembo nima sya kũvĩvw’a na nthembo kwondũ wa naĩ ndwaasyenda, o na ndwaaendeew’a nĩsyo (ila ithembawa kwĩanana na ĩla mĩao),'),
('kam', 'HEB', 10, 9, 'nĩvo ĩndĩ waisye, Sisya, nĩnooka kwĩka kwenda kwaku. Avetete ũla wa mbee, nĩ kana alũlũmĩlye ũla wa kelĩ.'),
('kam', 'HEB', 10, 10, 'Na nũndũ wa kwenda kwake nĩtwavathiwe twĩthĩwe atheu kwondũ wa kũthembwa kwa mwĩĩ wa Yesũ Klĩsto o ĩmwe tũ.'),
('kam', 'HEB', 10, 11, 'Na kĩla mũthembi aũngamaa kĩla mũthenya aithũkũma na kũthemba nthembo o isu mavinda maingĩ, ila itaatonya o na ĩndĩĩ kũveta naĩ:'),
('kam', 'HEB', 10, 12, 'ĩndĩ we, athemba nthembo o ĩmwe kwondũ wa naĩ kũvika tene ne tene, ekala nthĩ ngalĩ ya kw’oko kwa aũme kwa Ngai;'),
('kam', 'HEB', 10, 13, 'kuma ĩvinda yĩu eteelaa amaitha make matwiwe kavĩla ka nyaĩĩ syake.'),
('kam', 'HEB', 10, 14, 'Nũndũ kwondũ wa nthembo o ĩmwe nĩwameanĩsye kũvika tene na tene ala mavathanĩtw’e.'),
('kam', 'HEB', 10, 15, 'Na Veva Mũtheu nake nũtũkũsĩĩaa; nũndũ ĩtina wa kũneena,'),
('kam', 'HEB', 10, 16, 'Ũu nĩw’o ũtianĩo ũla ngatianĩa nao Ĩtina wa mĩthenya ĩsu, easya ũu Mwĩaĩi: Ngeekĩa mĩao ngoonĩ syoo, Na ngamĩandĩka ilĩkonĩ syoo; nĩvo ĩndĩ easya,'),
('kam', 'HEB', 10, 17, 'Na naĩ syoo na mothũku moo, ndikamalilikana ĩngĩ.'),
('kam', 'HEB', 10, 18, 'Na vala ve ũekeo wa asu, kũi nthembo ĩngĩ kwondũ wa naĩ.'),
('kam', 'HEB', 10, 19, 'Na ĩndĩ, ana‐a‐asa, kwa kwĩthĩwa twĩ na ũkũmbaũ wa kũlika nthĩnĩ wa vala vandũ vatheu kwondũ wa nthakame ya Yesũ,'),
('kam', 'HEB', 10, 20, 'na nzĩa ĩla watũvingũĩe, nzĩa nzaũ na yĩ na thayũ, kwa nazĩ ya tũtũ, naw’o nĩ mwĩĩ wake;'),
('kam', 'HEB', 10, 21, 'na nĩkwĩthĩwa twĩ na mũthembi mũnene ĩũlũ wa nyũmba ya Ngai;'),
('kam', 'HEB', 10, 22, 'nĩtũthengeee na ngoo ya w’o wĩanĩunĩ wa mũĩkĩĩo, ngoo sitũ iminzangĩw’e tũeke wasya mwathe wa ngoo: na mĩĩ yaitũ kũthambw’a na manzĩ matheu,'),
('kam', 'HEB', 10, 23, 'nĩtũlũmye kumbũla kwa wĩkwatyo witũ ndũkathingithange; nũndũ we ũla wathanie e kĩthito:'),
('kam', 'HEB', 10, 24, 'na nĩtũlilikanan’ye ithyĩ kwa ithyĩ kũthangaan’ya wendonĩ na mawĩanĩ maseo;'),
('kam', 'HEB', 10, 25, 'tũtekũeka kũmbana kwitũ vamwe, o tondũ amwe mekaa, ĩndĩ tũkĩtaana; na mbee mũno, mũkyona mũthenya ũsu ũkĩthengeea.'),
('kam', 'HEB', 10, 26, 'Nũndũ ethĩwa twĩkaa naĩ na ngũlũ ĩtina wa kwosa ũmanyi wa ũla w’o, kũitiele nthembo ĩngĩ kwondũ wa naĩ,'),
('kam', 'HEB', 10, 27, 'ĩndĩ kwĩ kweteela ũsilĩlo wa ũkĩwa, na wai wa mwaki ũla ũkamelya nthũ.'),
('kam', 'HEB', 10, 28, 'Mũndũ ũla wavũthisye mĩao ya Mose akusaa vate tei kwondũ wa ndeto ya ngũsĩ ilĩ kana itatũ:'),
('kam', 'HEB', 10, 29, 'mwĩona aĩlĩtwe nĩ ũsilĩlo mũnene wĩana ata, ũla ũmũkinyangĩte Mwana wa Ngai, na watalile nthakame ya ũtianĩo ĩla ũtheetw’e nayo kĩndũ kĩte kĩtheu, na wamũvũthisye vyũ Veva wa mumo?'),
('kam', 'HEB', 10, 30, 'Nũndũ nĩtũmwĩsĩ ũla waisye, Ũĩvanĩsyo nĩ wakwa, nyie ngaĩvanĩsya. Na ĩngĩ, Mwĩaĩi nũkaslĩla andũ make.'),
('kam', 'HEB', 10, 31, 'Nĩ ũndũ wa kũkĩwa mũno kũvalũka mokonĩ ma Ngai ũla wĩ thayũ.'),
('kam', 'HEB', 10, 32, 'Ĩndĩ lilikanai mĩthenya ĩla mĩvitu, ĩla nthĩnĩ wayo mwamina kwĩkĩwa kyeni, mwoomĩĩsye ũkĩlan’yonĩ mũnene wa mathĩna;'),
('kam', 'HEB', 10, 33, 'mavĩnda amwe, mũtw’ĩkĩte ma kũkũnũĩwa metho kwondũ wa kĩvũthya na mathĩna; na mavinda angĩ, mũtw’ĩkĩte osi vamwe ma ala meekiwe o ta ũu.'),
('kam', 'HEB', 10, 34, 'Nũndũ nĩmwamew’ĩie tei ala maĩ ove, na ĩngĩ mweetĩkĩla na ũtanu kũvũtwa syĩndũ syenyu, mũkĩmanya kana nthĩnĩ wenyu ene mwĩ na ũthwii mũseo mbee na ũla wĩkalaa.'),
('kam', 'HEB', 10, 35, 'Ĩndĩ mũikekye ũtee ũkũmbaũ wenyu, ũla wĩ na ĩtuvi ĩnene.'),
('kam', 'HEB', 10, 36, 'Nũndũ mwĩ na vata wa wũmĩĩsyo, kana, mwĩkĩte kwenda kwa Ngai, mũtonye kwosa ũla watho.'),
('kam', 'HEB', 10, 37, 'Nũndũ vatiele kavinda kanini mũno, Ũla wũkĩte oke, na ndeĩkala.'),
('kam', 'HEB', 10, 38, 'Ĩndĩ ũla mũlũngalu wakwa akekala thayũ kwondũ wa mũĩkĩĩo: Na ethĩwa akatundua, ngoo yakwa ndĩtanwa nĩwe.'),
('kam', 'HEB', 10, 39, 'Ĩndĩ ithyĩ tũti ma ala matunduaa kũvikĩa kwaa; ĩndĩ twĩ ma ala me na mũĩkĩĩo kũvikĩa ũtangĩĩo wa thayũ.'),
('kam', 'HEB', 11, 1, 'Na ĩndĩ mũĩkĩĩo nĩ kĩla kĩmanyĩthasya vyũ maũndũ ala mekwatĩtw’e, na nĩ kĩla kĩĩkĩĩthasya maũndũ ala matonekaa.'),
('kam', 'HEB', 11, 2, 'Nũndũ kwondũ waw’o atumĩa ma tene nĩmakũsĩĩwe.'),
('kam', 'HEB', 11, 3, 'Kwondũ wa mũĩkĩĩo nĩtũũmanya kana nthĩ nĩsyoombiwe na ndeto ya Ngai, na syĩndũ ila syonekaa ĩtyaaũmbwa kuma syĩndũnĩ syenekee.'),
('kam', 'HEB', 11, 4, 'Kwondũ wa mũĩkĩĩo Aveli nĩwamũthembeie Ngai nthembo nzeo kũvĩta ĩla ya Kaini, na kwondũ wayo nĩwakũsĩĩwe atĩ aĩ mũlũngalu, Ngai aikũsĩĩa mĩthĩnzĩo yake: na kwondũ waw’o o na kau nũkw’ĩte aneenaa kũvika o na yu.'),
('kam', 'HEB', 11, 5, 'Kwondũ wa mũikĩĩo Enoku nĩwambatiw’e ndakone kĩkw’ũ; na ndaoneka, nũndũ Ngai nĩwamwambatisye: nũndũ mbee wa kwambatw’a kwake nĩwakũsĩĩwe kana nĩwamwendeeasya Ngai:'),
('kam', 'HEB', 11, 6, 'na vate mũĩkĩĩo kũitonyeka kũmwendeesya; nũndũ ũla wũkaa kwa Ngai mũvaka etĩkĩle kana e vo, na ĩngĩ kana nũmanengae ĩtuvi ala mamũmanthaa.'),
('kam', 'HEB', 11, 7, 'Kwondũ wa mũĩkĩĩo Noa, ooniw’e nĩ Ngai ũvoo wa maũndũ ala matanamba kwoneka, ũndũ wa kũmũkĩa Ngai, nĩwaseũvisye ngalawa avĩtye nyũmba yake; na kwondũ waw’o asilĩla nthĩ, na atw’ĩka mũtiĩwa wa ũlũngalu ũla wonekaa kwondũ wa mũĩkĩĩo.'),
('kam', 'HEB', 11, 8, 'Kwondũ wa mũĩkĩĩo Avalaamu, eetwa, eew’a, na auma athi vandũ vala wĩnengwa ũtiĩwa; na auma, atesi vala ũnũũthi.'),
('kam', 'HEB', 11, 9, 'Kwondũ wa mũĩkĩĩo atw’ĩka mwĩkali wa ũeninĩ nthĩ ĩla ya watho, ta nthĩ ĩte yake, akĩkala maeemanĩ vamwe na Isaka na Yakovo, atiĩwa vamwe nake ma watho o ũsu:'),
('kam', 'HEB', 11, 10, 'nũndũ nĩweteelaa onw’e ndũa ĩla yĩ na myambĩlĩlyo, na mwambĩlĩlya na mwaki wayo nĩ Ngai.'),
('kam', 'HEB', 11, 11, 'Kwondũ wa mũĩkĩĩo o na Sala anengiwe vinya wa kũitava yĩla weyĩtũkĩte, nũndũ nĩwamwonie e kĩthito ũla wamwathie:'),
('kam', 'HEB', 11, 12, 'kwondũ wa ũu masyaiwe nĩ ũmwe, nake aĩ ta mũkw’ũ, andũ aingĩ o tondũ ndata sya ĩtunĩ singĩvĩte, na ta kĩthangathĩ kĩla kĩ ũtee wa ũkanga kĩtatalĩka.'),
('kam', 'HEB', 11, 13, 'Asu onthe nĩmakwie mũĩkĩĩonĩ, matosete matho, ĩndĩ mamonete me kũasa na kũmatanĩa, na makĩtĩkĩla kana maĩ aeni na aendĩ ma kyalo ĩũlũ wa nthĩ.'),
('kam', 'HEB', 11, 14, 'Nũndũ ala maneenaa ndeto ta isu meonan’ya vyũ kana memantha nthĩ yoo ene.'),
('kam', 'HEB', 11, 15, 'Na kethĩwa nĩmalilikanile nthĩ ĩla maumie, methĩwa maĩ na ũthei wa kũalũka.'),
('kam', 'HEB', 11, 16, 'Ĩndĩ yu mendaa nthĩ nzeo mbee, nayo nĩ ĩtunĩ: kwondũ wa ũu Ngai ndeũsonoka kwondũ wamo kwĩtwa Ngai woo, nĩkwĩthĩwa nũmaseũvĩsye ndũa.'),
('kam', 'HEB', 11, 17, 'Kwondũ wa mũĩkĩĩo Avalaamu, atatwa, aumya Isaka ethĩwe nthembo: ĩĩ, we ũla wosete na ũtanu ala matho aĩ anathemba mwana wake ũla wasyaiwe e weka;'),
('kam', 'HEB', 11, 18, 'we, ũla weiwe, Ũsyao waku ũkeetwa nthĩnĩ wa Isaka:'),
('kam', 'HEB', 11, 19, 'aitala kana Ngai nũtonya kũmũthayũũkya o na kũmumya akw’ũnĩ; na kuma vo amwosa ĩngĩ kwa ngelekan’yo.'),
('kam', 'HEB', 11, 20, 'Kwondũ wa mũĩkĩĩo Isaka amaathima Yakovo na Esau, o na ũvoonĩ wa maũndũ ala makoka.'),
('kam', 'HEB', 11, 21, 'Kwondũ wa mũĩkĩĩo Yakovo, yĩla wakussa, aathima ana elĩ ma Yosevu; na athaitha, etw’ĩĩkĩte na mũthya wa ndata yake.'),
('kam', 'HEB', 11, 22, 'Kwondũ wa mũĩkĩĩo Yosevu, yĩla mũminũkĩlyo wake waĩ vakuvĩ, aweta ũvoo wa kuma kwa ana ma Isilaeli; na eeaa ũndũ wa mavĩndĩ make.'),
('kam', 'HEB', 11, 23, 'Kwondũ wa mũĩkĩĩo Mose, asyawa, avithwa myei ĩtatũ ni ala mamũsyaie, nũndũ moonie e kana kaseo; na matyaakĩa mwĩao wa mũsumbĩ.'),
('kam', 'HEB', 11, 24, 'Kwondũ wa mũĩkĩĩo Mose, yĩla waĩ aneana, nĩwaleile kwĩtwa mwana wa mwĩĩtu wa Valao;'),
('kam', 'HEB', 11, 25, 'akĩnyuva kavaa kũthĩnw’a vamwe na andũ ma Ngai, kwi kũtana maũndũnĩ ma naĩ ĩvinda;'),
('kam', 'HEB', 11, 26, 'aitala kũvũthw’a kwa Klĩsto nĩ ũthwii mwingi kũvĩta ũthwii wa Misili, nũndũ nĩwasyaisye ituvi yĩla yĩkanenganwe.'),
('kam', 'HEB', 11, 27, 'Kwondũ wa mũĩkĩĩo niwaumie Misili: ateũkĩa ũthatu wa mũsumbĩ: nũndũ nĩwomĩisye ta ũmwonaa ũla ũtonekaa.'),
('kam', 'HEB', 11, 28, 'Kwondũ wa mũĩkĩĩo nĩwalilikanile Vasaka na aminzangisya nthakame, nĩ kana ũla mwanangi wa ala masyaiwe mbee ndakamakiite.'),
('kam', 'HEB', 11, 29, 'Kwondũ wa mũĩkĩĩo nĩmavĩtĩle Ũkanganĩ Mũtune katĩ, ta kũvĩtĩla nthĩ nyũmũ: na Amisili matata kwĩka ũu mamelw’a.'),
('kam', 'HEB', 11, 30, 'Kwondũ wa mũĩkĩĩo maũvai ma Yeliko mavalũka, ĩtina wa kũthyũlũlũkwa mĩthenya mũonza.'),
('kam', 'HEB', 11, 31, 'Kwondũ wa mũĩkĩĩo Laavi yĩla ĩlwaya ndaanangwa vamwe na ala maleile kwĩw’a, nũndũ athokisye athiani na mũuo.'),
('kam', 'HEB', 11, 32, 'Na nĩneena ũndũ ũngĩ wĩva? Nũndũ ĩvinda yĩimbĩanĩa ethĩwa nĩngũweta ũvoo wa Ngiteonĩ, na Mbalaka, na Samusoni, na Yevitha; na wa Ndaviti na Samueli na athani:'),
('kam', 'HEB', 11, 33, 'ala kwondũ wa mũĩkĩĩo makĩlilye mosumbĩ vinya, meekie ũlũngalu, moosie matho, matumisye makanyw’a ma mĩnyambũ,'),
('kam', 'HEB', 11, 34, 'mavoisye vinya wa mwaki, mavonokie ũĩ wa ũvyũ, yĩla maĩ onzu meekĩiwe vinya, maĩ ai kaũnĩ, malũngilye ita sya aeni'),
('kam', 'HEB', 11, 35, 'Aka nĩmoosie akw’ũ moo ala mathayũũkiw’e: na angĩ mathĩniw’e na mathĩna mai, matekwĩtĩkĩla kũthaw’a; nĩ kana mone ũthayũũkyo mũseo kwĩ ũsu:'),
('kam', 'HEB', 11, 36, 'na angĩ maĩ na matatwa ma kũvũthw’a na kũkũnwa mũno, ĩĩ, o na kwovwa na kwĩkĩwa kolokolonĩ:'),
('kam', 'HEB', 11, 37, 'nĩmakimiwe na mavia, nĩmatililwe na mang’weli, nĩmatatiwe, nĩmooaiwe na ũvyũ: mangangie makĩvw’ĩka mbũa sya malondu na sya mbũi; matyaĩ na kĩndũ, maĩ na monyamao, meekiwe naĩ'),
('kam', 'HEB', 11, 38, '(andũ ala nthĩ ĩtaĩle kwĩthĩwa nao), mangangie maweũnĩ na iĩmanĩ na ngunganĩ, na maimanĩ ma nthĩ.'),
('kam', 'HEB', 11, 39, 'Na asu onthe makũsĩĩwe kwondũ wa mũĩkĩĩo woo, matyaaosa ũla watho,'),
('kam', 'HEB', 11, 40, 'nĩkwĩthĩwa Ngai nĩwatũseũvĩsye kĩndũ kĩseo mbee, nĩ kana asu matikethĩwe meanĩwe ithyĩ tũte vo.'),
('kam', 'HEB', 12, 1, 'Kwondũ wa ũu ithyĩ naitũ, nĩkwĩthĩwa nitũthyũlũlũkĩtwe nĩ mũumbĩ mũnene wĩana ũu wa ngũsĩ, nĩtwie ũtee kĩla kĩũtũvata kũthi kyonthe, na naĩ ĩla ĩtũsiĩiaa na ũvũthũ, na tũsembe na wũmĩĩsyo ũkĩlan’yonĩ ũla wiĩtwe mbee waĩtũ,'),
('kam', 'HEB', 12, 2, 'tũkĩmũsisya Yesũ, mwambĩlĩlya na mwĩanisya wa mũĩkĩĩo witũ, ũla kwondũ wa ũtanu ũla waiiwe mbee wake oomĩĩsya ĩla ngelan’yo, aivũthya nthoni, na nĩwekalile nthĩ ngalĩ ya kw’oko kwa aũme kwa kĩvĩla kya ũsumbĩ kya Ngai.'),
('kam', 'HEB', 12, 3, 'Sũanĩai mũno ũla womĩĩsye mosiĩĩo mailyĩ ũu ma ala athe, nĩ kana mũikanoe, mũkĩteva ngoonĩ syenyu.'),
('kam', 'HEB', 12, 4, 'Mũinamba kũkita kũvika kwĩtĩkya nthakame, mũkyũkita na naĩ:'),
('kam', 'HEB', 12, 5, 'na nĩmũlĩtwe nĩ ũtao ũla ũmũtaa inyw’ĩ ta mwĩ ana, Mwana wakwa, ndũkone ta ũndũ ũnini kũsilĩlwa nĩ Mwĩaĩi, Kana ndũkateve yĩla ũkũkanw’a nĩwe;'),
('kam', 'HEB', 12, 6, 'Nũndũ ũla Mwĩaĩi ũmwendaa nũmũsilĩlaa, Na kũvũa kĩla mwana ũla wosaa.'),
('kam', 'HEB', 12, 7, 'Nĩ kwondũ wa kũsilĩlwa mũmĩĩasya; Ngai amwĩkaa ta ana; nũndũ nĩ mwana wĩva ũla ũtasilĩlawa nĩ ĩthe?'),
('kam', 'HEB', 12, 8, 'Ĩndĩ ethĩwa mũtiũsilĩlwa, ũndũ onthe mekawa, mwi ana ma ũlaalainĩ, na ti ana ma w’o.'),
('kam', 'HEB', 12, 9, 'Na vamwe na ũu, twaĩ na aaĩthe maitũ ma mwĩĩ matũsilĩlaa, na nĩtwamataĩaa: ti kavaa mũno kũmwĩnyivĩsya Asa wa maveva maitũ, na kwĩthĩwa thayũ?'),
('kam', 'HEB', 12, 10, 'Nũndũ nĩ w’o asu vandũ va matukũ manini matũsilĩlaa o ũndũ moonaa ta ũseo; ĩndĩ we kwondũ wa kũtũuna, nĩ kana twĩthĩwe osi ma ũtheu wake.'),
('kam', 'HEB', 12, 11, 'Kũsilĩlwa kw’onthe ĩvinda yĩĩ kũioneka ta ũndũ wa ũtanu ĩndĩ ta ũndũ wa woo; ĩndĩ ĩtina nĩkũmaeteae ala mamanyĩĩtw’e nĩkw’o ũsyao wa mũuo naw’o nĩ ũsyao wa ũlũngalu.'),
('kam', 'HEB', 12, 12, 'Kwondũ wa ũu ũkĩlyai moko ala maleelu, na maũũ ala monzu;'),
('kam', 'HEB', 12, 13, 'na seũvĩsyai nyaĩĩ syenyu nzĩa ndũngalu, nĩ kana mutha ũla ũthuaa ndũkavĩtĩthw’e, ĩndĩ kavaa ũvow’e.'),
('kam', 'HEB', 12, 14, 'Manthai kwĩthiwa na mũuo na andũ onthe, na kũvathwa mwĩthĩwe atheu kũla mũndũ ate nakw’o ndakamwona Mwĩaĩi:'),
('kam', 'HEB', 12, 15, 'mũkĩsisya mũno mũndũ o na wĩva ndakatiale kũvikĩa ũla mumo wa Ngai; kĩtina kya ũũ kĩikathongooe na kũmũthĩn’ya, na kwondũ wakyo aingĩ kũvukw’a;'),
('kam', 'HEB', 12, 16, 'kũikethĩwe kĩlaalai, kana ũla ũtamũkĩaa Ngai, ta Esau, ũla nũndũ wa kya ũya kĩmwe wathooisye ũtiĩwa wa ũkithathi wake.'),
('kam', 'HEB', 12, 17, 'Nũndũ nĩmwĩsĩ kana o na ĩtina yĩla wendie kũtiĩwa ũla ũathimo, nĩwaleilwe; nũndũ ndaaona ũthei wa kwĩalyũla, o na kau nĩwomanthie mũno na methoi.'),
('kam', 'HEB', 12, 18, 'Nũndũ mũtyaavikĩa kĩĩma kĩla kĩtonya ũkiitwa, na kĩla kyakanie mwaki, o na wiũ, na kĩvindu, na kĩuutani,'),
('kam', 'HEB', 12, 19, 'na wasya wa soo, na wasya wa ndeto; na ala meewie wasya ũsu meesũvana maikatavw’e ndeto ĩngĩ;'),
('kam', 'HEB', 12, 20, 'nũndũ matyaatonya kũmĩĩsya ũndũ weeaiwe, atĩĩ, Ethĩwa o na nyamũ ĩkakiita kĩĩma kyu, ĩkooawa na mavia;'),
('kam', 'HEB', 12, 21, 'ũndũ ũsu woonekie waĩ wa kwĩw’ĩthya w’ĩa mũno, o ũndũ Mose waisye, Nĩnalikwa nĩ w’ĩa mũno na kũtetema:'),
('kam', 'HEB', 12, 22, 'ĩndĩ inyw’ĩ mũvikĩe kĩĩma kya Saioni, na mũsyĩ wa Ngai ũla wĩ thayũ, Yelusaleme wa itunĩ, na nguthu sya alaĩka ngili nyingĩ,'),
('kam', 'HEB', 12, 23, 'na ũmbano mũnene, naw’o nĩ ĩkanisa ya ala masyaiwe mbee ala maandĩkiwe ĩtunĩ, na kwa Ngai Mũsili wa andũ onthe, na maveva ma andũ alũngalu ala meanĩwe,'),
('kam', 'HEB', 12, 24, 'na kwa Yesũ mwĩw’anĩthya wa ũtianĩo mweũ, na nthakame ya kũminzangisya ĩla ĩneena nesa kwĩ ĩla ya Aveli.'),
('kam', 'HEB', 12, 25, 'Sisyai mũikamũlee ũla ũneenaa. Nũndũ ethĩwa asu matyaavonoka ala mamũleile ũla wamataĩe kũũ nthĩ, mbee mũno ithyĩ tũikavonoka twamwĩthyũũĩa na kũmũtia ũla ũtũ taa e ĩtunĩ:'),
('kam', 'HEB', 12, 26, 'ũla wasya wake wathingithisye nthĩ: ĩndĩ yu nĩwathanĩte, akyasya, No ĩngĩ ĩmwe ngathingithya, tĩ nthĩ yoka, ĩndĩ o na itu nayo.'),
('kam', 'HEB', 12, 27, 'Na ndeto ĩno, No ĩngĩ ĩmwe, nĩyonanasya kũvetwa kwa syindũ ila itonya kũthingithw’a, ta syĩndũ ila syoombiwe, ni kana syĩndũ ila itatonya kũthingithw’a itonye kwĩkala.'),
('kam', 'HEB', 12, 28, 'Kwondũ wa ũu, tũkyosa ũsumbi ũla ũtatonya kũthingithw’a, nĩtwĩthĩwe na mumo, naw’o kwondũ waw’o tũtonya kũmũnenga Ngai ũthũkũmi ũla wĩmwendeesya vamwe na ũtaĩo na kũmũkĩa:'),
('kam', 'HEB', 12, 29, 'nũndũ Ngai waitũ nĩ mwaki ũĩsaa.'),
('kam', 'HEB', 13, 1, 'Wendano wa ana‐a‐asa nĩwĩkalae.'),
('kam', 'HEB', 13, 2, 'Mũikolwe nĩ kũmon’ya aenĩ wendo: nũndũ kwa nzĩa ĩsu amwe nĩmathokisye alaĩka matesĩ.'),
('kam', 'HEB', 13, 3, 'Malilikanei ala ove, ta mwovetwe vamwe nao; na ala mekawa naĩ, nĩkwĩthĩwa inyw’i nenyu mwĩ o na mwĩĩ.'),
('kam', 'HEB', 13, 4, 'Mũtwaano nũtaĩwe nĩ andũ onthe, na ũkomo wĩthĩwe ũte mũvukye: nũndũ mathaaa na ilaalai Ngai akamasilĩla.'),
('kam', 'HEB', 13, 5, 'Mũikethĩwe na wendi wa mbesa; ĩanĩwai nĩ syĩndũ ila mwĩ nasyo: nũndũ we mwene nĩwaisye, Ndikakũnyivĩa o na ata, na ndikakũtia o na ĩndĩĩ.'),
('kam', 'HEB', 13, 6, 'Kwondũ wa ũu nĩtũkwasya na ũnyiau, Mwĩaĩi nĩ mũtetheesya wakwa; ndikakĩa: Mũndũ akambĩka ata?'),
('kam', 'HEB', 13, 7, 'Malilikanei ala maĩ na ũtongoi ĩũlũ wenyu, ala mamũtavisye ndeto ya Ngai; na mũkĩsũanĩa mũno mũminũkĩlyo wa mathayũ moo, ĩelekan’yei na mũĩkĩĩo woo.'),
('kam', 'HEB', 13, 8, 'Yesũ Klĩsto no ũndũ ũmwe ĩoo na ũmũnthĩ, ĩĩ, o na kũvika tene na tene.'),
('kam', 'HEB', 13, 9, 'Mũikaw’e nĩ momanyĩsyo ma mĩthemba mingĩ na ala meũ: nũndũ nĩ ũseo ngoo ĩlũlũmĩlw’e nĩ mumo; ti ũndũ wa sya ũya, nasyo ityaamauna ala maendeee nasyo.'),
('kam', 'HEB', 13, 10, 'Twĩ na kĩthembeo, na ala mathũkũmaa yĩla ĩeemanĩ mati na ũthei wa kũĩsaa vo.'),
('kam', 'HEB', 13, 11, 'Nũndũ indo isu ila nthakame yasyo yaetawe nthĩnĩ wa vala vandũ vatheu nĩ mũthembi mũnene kwondũ wa naĩ, mĩĩ yasyo nĩyavĩvĩaw’a ũtee wa mwako wa maeema.'),
('kam', 'HEB', 13, 12, 'Kwondũ wa ũu Yesũ nake, nĩ kana avathan’ye andũ na nthakame yake mwene methĩwe atheu, nĩwanyamaie ngalĩ ya nza ya mbingĩlo.'),
('kam', 'HEB', 13, 13, 'Kwondũ wa ũu nĩtumaale vala ũĩ ũtee wa mwako wa maeema, tũkĩkua kũvũthw’a kwake.'),
('kam', 'HEB', 13, 14, 'Nũndũ vaa tũi na ndũa yĩkalaa, ĩndĩ nĩtũũmantha ĩla ĩkoka.'),
('kam', 'HEB', 13, 15, 'Kwondũ wake ĩndĩ tũmũthembeae Ngai nthembo ya ndaĩa mavinda onthe, nayo, nĩ ũsyao wa ilomo sitũ ila syumbũlaa syĩtwa yake.'),
('kam', 'HEB', 13, 16, 'Ĩndĩ mũikolwe nĩ kwĩka nesa na kũolanĩla: nũndũ Ngai nĩwendeeaw’a nĩ nthembo ta isu.'),
('kam', 'HEB', 13, 17, 'Mew’ei ala me na ũtongoi ĩũlũ wenyu, na ĩnyivyei kwamo: nũndũ nĩmeũsyaĩĩsya ũndũ wa mathayũ menyu, ta ala makaumya ũtalo; nĩ kana meke ũu na mũyo, na ti na woo: nĩkwĩthĩwa ũu ndũmũuna inyw’ĩ.'),
('kam', 'HEB', 13, 18, 'Tũvoyeei: nũndũ nĩtwĩtĩkĩlĩte ki kana twĩ na wasya mũseo wa ngoo, tũkyenda kwĩkalaa na mĩendele mĩseo maũndũnĩ onthe.'),
('kam', 'HEB', 13, 19, 'Na nĩmwĩsũva mũno mbee mwĩke ũu nĩ kana nĩtũngwe kwenyu mĩtũkĩ.'),
('kam', 'HEB', 13, 20, 'Na yu Ngai wa mũuo, ũla wamũetie kũmumya kwa akw’ũ ũla mũĩthi mũnene wa malondu ũndũ wa nthakame ya ũtianĩo wa tene na tene, nake nĩ Mwĩaĩi waitũ Yesũ,'),
('kam', 'HEB', 13, 21, 'namwĩanĩsye kĩla ũndũnĩ ũseo mwĩkae kwenda kwake, aiĩka nthĩnĩ waitũ ũla wendeeasya mbee wake, kwondũ wa Yesũ Klĩsto, ndaĩa nĩ yake tene na tene. Ameni.'),
('kam', 'HEB', 13, 22, 'Ĩndĩ nĩngũmwĩsũva, ana‐a‐asa, mũmĩĩsye ndeto ya ũtao: nũndũ namũandĩkia ndeto mbũthũ.'),
('kam', 'HEB', 13, 23, 'Manyai kana mwana‐a‐asa waitũ Timotheo nũthaĩtw’e; nake ethĩwa akooka mĩtũkĩ, ngoonana nenyu vamwe nake.'),
('kam', 'HEB', 13, 24, 'Ngethesyai onthe ala me na ũtongoi ĩũlũ wenyu, na atheu onthe. Ala me Italia nĩmamũkethya.'),
('kam', 'HEB', 13, 25, 'Mumo nĩwĩthĩwe nenyu inyw’onthe. Ameni.'),
('kam', 'JAS', 1, 1, 'Yakovo, ngombo ya Ngai na ya Mwĩaĩi Yesũ Klĩsto, valũa ũũ wakwa wivikĩe ila mbaĩ ĩkũmi na ili syi Ũnyaĩĩkyonĩ, nĩ ngethi.'),
('kam', 'JAS', 1, 2, 'Ana‐a‐asa makwa ĩtalĩlei kwĩthĩwa nĩ ũtanu mũthei, yila mũũlika matatwanĩ ma mĩthemba mingĩ;'),
('kam', 'JAS', 1, 3, 'mũkĩmanya atĩ kũtatwa kwa mũĩkĩĩo wenyu kũetae wũmĩĩsyo.'),
('kam', 'JAS', 1, 4, 'Na wũmĩĩsyo nĩwĩthĩwe na wĩa waw’o mwĩanĩũ, nĩ kana inyw’ĩ mũtw’ĩke eanĩu na aima, mũtatielye ũndũni o na wĩva.'),
('kam', 'JAS', 1, 5, 'Ĩndĩ ethĩwa ũmwe wenyu nũtielye ũĩ, namũvoye Ngai, ũla ũnengae andũ onthe na ũlau na ndeũkan’ya; nake akanengwa.'),
('kam', 'JAS', 1, 6, 'Ĩndĩ navoye na mũĩkĩĩo, ate nzika nongi: nũndũ ũla ũĩsaa nzika ailyĩ ta kĩtũlũmo kya ũkanga kĩkyũkĩlangw’a nĩ kĩseve na kũtwawa kũũ na kũũ.'),
('kam', 'JAS', 1, 7, 'Nũndũ mũndũ ũsu ndakatalĩlye kana akanengwa kĩndũ o na kĩva nĩ Mwĩaĩi;'),
('kam', 'JAS', 1, 8, 'mũndũ wĩ na mĩtwe ĩlĩ, ũtalũmaa nzĩanĩ syake syonthe.'),
('kam', 'JAS', 1, 9, 'Ĩndĩ mwana‐a‐asa ũla ũte ndaĩa natane ũndũ wa kũnenevw’a kwake:'),
('kam', 'JAS', 1, 10, 'na ũla mũthwii, ũndũ wa kũnyivĩw’a kwake: nĩkwĩthĩwa o ta ĩlaa ya nyeki akavĩta.'),
('kam', 'JAS', 1, 11, 'Nũndũ syũa nĩyumaa vamwe na kĩseve kĩla kĩvĩvasya, na kũmya nyeki; na ĩlaa yasyo nĩyĩtĩkaa, na ũseo wa wũmbĩle wayo nĩwaaa: o ta ũu nake mũthwii akaaĩa mĩendelenĩ yake.'),
('kam', 'JAS', 1, 12, 'Nĩ mũathime mũndũ ũla wũmĩĩasya matatwa; nũndũ eetĩkĩlwa, akanengwa ngovia ya ũsumbĩ ya thayũ, ĩla Mwĩaĩi wamathie ala mamwendaa.'),
('kam', 'JAS', 1, 13, 'Mũndũ o na wĩva atatwa ndakasye, Nĩngũtatwa nĩ Ngai; nũndũ Ngai ndatonya kũtatwa nĩ ũthũku, o nake mwene ndatataa mũndũ:'),
('kam', 'JAS', 1, 14, 'ĩndĩ kĩla mundũ atatawa akĩkusw’a na kũkengwa nĩ ĩtomo yake mwene.'),
('kam', 'JAS', 1, 15, 'Na ĩndĩ ĩtomo yaya ĩvu, yĩsyaaa naĩ: na ĩla naĩ yeana, ĩsyaaa kĩkw’ũ.'),
('kam', 'JAS', 1, 16, 'Mũikakengwe, ana‐a‐asa makwa endwa.'),
('kam', 'JAS', 1, 17, 'Kĩla kũnengwa kũseo na kĩla kũnengwa kwĩthĩanu nikumaa ĩũlũ, kũtheeaa kuma kwa Ĩthe wa syeni, na kwake kũitonyeka kwĩthĩwa kũalyũkĩka, kana kyuu kya kũalyũka.'),
('kam', 'JAS', 1, 18, 'Kwondũ wa kwenda kwake nũtũsyaĩte na ndeto ya ũla w’o, nĩ kana twĩthĩwe twĩ mosyao ma mbe ma syũmbe syake.'),
('kam', 'JAS', 1, 19, 'Nĩmwĩsĩ ũu, ana‐a‐asa makwa endwa. Ĩndĩ kĩla mũndũ nĩethĩwe mwiwi wa mĩtũki, na kũlea kũneena mĩtũkĩ, na kũlea kũthata mĩtũkĩ:'),
('kam', 'JAS', 1, 20, 'nũndũ ũthilĩku wa mũndũ ndwĩkaa ũlũngalu wa Ngai.'),
('kam', 'JAS', 1, 21, 'Kwondũ wa ũu ĩndĩ vetai kũasa nenyu ũvukyo w’onthe na wingĩ wa ũthũku, mũkyosa na ũuu ndeto ĩla ĩvandĩtwe, ĩla ĩtonya kũtangĩĩa mathayũ menyu,'),
('kam', 'JAS', 1, 22, 'Ĩndĩ ĩthĩwai mwĩ eki ma ndeto, na ti ewi oka, mũkĩkenga ene.'),
('kam', 'JAS', 1, 23, 'Nũndũ ethĩwa mũndũ ni mwĩwi wa ndeto na ti mwĩki, ailyi mũndũ ũla ũsyaasya ũthyũ wake, ũla wasyaiwe naw’o, kĩsisyonĩ:'),
('kam', 'JAS', 1, 24, 'nũndũ esisya mwene, na aithi, oyu niwũlawa ũndũ eĩĩlyi.'),
('kam', 'JAS', 1, 25, 'Ĩndĩ ũla ũsyaasya nthĩnĩ wa mwĩao mwĩthĩanu, naw’o nĩ mwĩao wa ũthasyo, na ekalaa vo, na akĩthĩwa ti mwĩwi ũla wũlawa ĩndĩ nĩ mwĩki ũla wĩkaa, mũndũ ũsu akaathimwa mawĩanĩ ala wĩkaa.'),
('kam', 'JAS', 1, 26, 'Ethĩwa mũndũ o na wĩva eyonaa mwene ta ũmũkĩaa Ngai, na ndeũsiĩĩa ũĩmĩ wake ĩndĩ ekenga ngoo yake, kũmũkĩa Ngai kwa mũndũ ũsũ nĩ kwa mana.'),
('kam', 'JAS', 1, 27, 'Kũmũkĩa Ngai kũla kũtheu na kũte na ũthũku mbee wa Ngai Asa waitũ nĩ kũũ, kũthi, kũsisya syana ila ikw’ĩĩwe nĩ aaĩthe na aka ndiwa thĩnanĩ woo, na kwĩsũvĩa mwene ndakavukw’e nĩ maũndũ ma nthĩ.'),
('kam', 'JAS', 2, 1, 'Ana‐a‐asa makwa, mũĩkakwatanĩsye mũĩkiĩo wa Mwĩaii waitũ Yesũ Klĩsto, Mwĩaii ũla ũtaĩawa, na wendeesyo wa andũ.'),
('kam', 'JAS', 2, 2, 'Nũndũ ethĩwa vakooka ũmbanonĩ wenyu mũndũ wĩ na ngome ya thaavu, wĩkĩĩte ngũa nzeo, na vakooka mũndũ ũngĩ ngya wĩkĩĩte ngũa nthũku;'),
('kam', 'JAS', 2, 3, 'na inyw’ĩ mũkĩmũtaĩa ũla wĩkĩĩte ngũa nzeo mũkĩmwĩa, Ĩkala nthĩ vaa vandũ vaseo; na mũkĩmwĩa ũla ngya, Naku ũngama vaya, kana ĩkala nthi maũũnĩ makwa;'),
('kam', 'JAS', 2, 4, 'mũtikwĩvathan’ya inyw’ĩ, na kũtw’ĩka asili me na malilikano mathũku?'),
('kam', 'JAS', 2, 5, 'Ĩthukĩĩsyei, ana‐a‐asa endwa; Ngai ndaamanyuva ala ngya ma kũũ nthĩ methĩwe athwii mũĩkĩĩonĩ, na atiĩwa ma ũsumbĩ ũla wamathie ala mamwendaa?'),
('kam', 'JAS', 2, 6, 'Ĩndĩ inyw’ĩ nĩmwanangĩe ndaĩa ũla ngya. Ala athwii maiũmũthĩn’ya, na kũmũtwaa na vinya mbee wa ivĩla sya sila?'),
('kam', 'JAS', 2, 7, 'Matiũyiuma syĩtwa yĩ ndaĩa yĩla mwĩtanĩaw’a nayo.'),
('kam', 'JAS', 2, 8, 'Ĩndĩ ethiwa mũkeanĩsya mwiao ũla ũkĩlĩte ĩla ĩngĩ yonthe, kwĩanana na maandĩko, Mwende ũngĩ o tondũ wiyendete mwene, mmwĩkaa nesa:'),
('kam', 'JAS', 2, 9, 'ĩndĩ ethiwa mwĩendeesya andũ, nĩmũkwĩka nai na nĩmũũsilĩlwa nĩ ĩla mĩao kwĩthĩwa avĩtan’ya.'),
('kam', 'JAS', 2, 10, 'Nĩkwĩthĩwa mũndũ o na wĩva asũvĩa ĩla mĩao yonthe, na avĩtya kamwe kayo, atw’ĩkĩte avĩtĩtye yonthe.'),
('kam', 'JAS', 2, 11, 'Nũndũ ũla waisye, Ndũkalaalae, nowe waisye, Ndũkoae. Ĩndĩ walea kwĩka ũlaalai, ĩndĩ nũkũaa, nũtw’ĩkĩte mũvĩtan’ya wa ĩla mĩao.'),
('kam', 'JAS', 2, 12, 'Neenaaĩ na ĩkaai ta andũ ala makasilĩlwa nĩ mwĩao wa ũthasyo.'),
('kam', 'JAS', 2, 13, 'Nũndũ ũsilĩlo ndwĩ na tei kwa ũla ũleaa kwĩw’ĩa angĩ tei: tei wĩtaiaa ĩũlũ wa ũsilĩlo.'),
('kam', 'JAS', 2, 14, 'Kũuna kyaũ, ana‐a‐asa makwa, ethĩwa mũndũ easya e na mũĩkĩĩo, ĩndĩ nde na meko? Mũĩkĩĩo ũsu nũtonya kũmũtangĩĩa?'),
('kam', 'JAS', 2, 15, 'Ethĩwa mwana‐a‐asa kana mwĩĩtu‐a‐asa nde na ngũa na aĩwe nĩ kya ũya.'),
('kam', 'JAS', 2, 16, 'Na ũmwe wenyu aimea, Endai na ũvoo, mũkote mwaki na kũvũna; ĩndĩ mũiũmanenga syĩndũ syĩ vata sya mwĩĩ; kũuna kyaũ?'),
('kam', 'JAS', 2, 17, 'O ta ũu mũĩkĩĩo, ethĩwa ndwĩ na meko, nĩ mũkw’u naw’o.'),
('kam', 'JAS', 2, 18, 'Ĩĩ, mũndũ nũtonya kwasya, We, wĩ na mũĩkĩĩo, nakwa nĩ na meko: mbon’ya mũĩkĩĩo waku ute na meko, nakwa nĩngũkwon’ya mũĩkĩĩo wakwa na meko makwa.'),
('kam', 'JAS', 2, 19, 'We wĩtĩkĩlaa, atĩ Ngai nĩ ũmwe; wĩkaa nesa: ndaimoni nasyo nĩsyĩtĩkĩlaa, na kũtetema.'),
('kam', 'JAS', 2, 20, 'Ĩndĩ nũkwenda kũmanya, we mũndũ wa mana, kana mũĩkĩĩo ũte na meko ndwĩ na ũsyao?'),
('kam', 'JAS', 2, 21, 'Avalaamu, ĩthe waitũ, ndaatalĩlwa ũlũngalu ũndũ wa meko, yĩla wathembie Isaka mwana wake kĩthembeonĩ?'),
('kam', 'JAS', 2, 22, 'Nũkwona ũndũ mũĩkĩĩo watethanisye na meko make, na kwondũ wa meko mũĩkĩĩo nĩweanĩw’e;'),
('kam', 'JAS', 2, 23, 'na maandĩko nĩmeanĩw’e ala maĩtye, Na Avalaamũ nĩwetĩkĩlĩle Ngai, na kwatalilwe kwake nĩ ũlũngalu; na nĩwetiwe mũnyanyae wa Ngai.'),
('kam', 'JAS', 2, 24, 'Nĩmũkwona ũndũ mũndũ ũtalĩlawa ũlũngalu kwondũ wa meko, na ti kwondũ wa mũĩkĩĩo wi w’oka.'),
('kam', 'JAS', 2, 25, 'No ta ũu Laavi, yĩla ĩlwaya, ndaatalĩlwa ũlũngalu kwondũ wa meko, amathokya ala matũmĩtwe, na amaumaalya mathi na nzĩa ĩngĩ?'),
('kam', 'JAS', 2, 26, 'Nũndũ o tondũ mwĩĩ ũte na veva nĩ mũkw’ũ, no ta ũu mũĩkĩĩo ũte na meko nĩ mũkw’ũ.'),
('kam', 'JAS', 3, 1, 'Mũikethĩwe amanyĩsya aingĩ, ana‐a‐asa makwa, mũkĩmanya kana ithyĩ tũkasilĩlwa na ũsilĩlo mũnene kũvĩta ala angĩ.'),
('kam', 'JAS', 3, 2, 'Nũndũ maũndũnĩ maingĩ ithyonthe nĩtũlulutĩkaa. Ethĩwa mũndũ ndalulutĩkaa ndetonĩ, ũsu nĩ mũndũ mwĩanĩu, ũtonya kũvota o na mwĩĩ wake w’onthe.'),
('kam', 'JAS', 3, 3, 'Na ethĩwa nĩtwĩkĩaa mĩkwa na itanga makanyw’anĩ ma mbalasi nĩ kana itwĩw’e, nĩtũthyũũaa mĩĩ yasyo yonthe.'),
('kam', 'JAS', 3, 4, 'Sisyai, ngalawa nasyo, o na kau inenevete ũu, na kũtwawa nĩ kĩseve kyai, nithyũũawa nĩ sukani nini mũno, o kũla mũtwai ũnũkwenda.'),
('kam', 'JAS', 3, 5, 'O ta ũu ũĩmĩ nĩ mutha mũnini, naw’o wĩkathĩĩaa na maũndũ manene. Sisyai, ũndũ mwaki mũnini ũvĩvasya kĩtheka kĩnene mũno!'),
('kam', 'JAS', 3, 6, 'Na ũĩmĩ nĩ mwaki: nthĩ ya ũthũku mamuthanĩ maitũ nĩ ũĩmĩ ũla ũvukasya mwĩĩ w’onthe, na nũkwatasya mwaki mosyaanĩo onthe, naw’o nĩwakanaw’a mwaki nĩ Ngiena.'),
('kam', 'JAS', 3, 7, 'Nũndũ kĩla mũthemba wa nyamũ na wa nyũnyi, na wa tũsamũ tũla tũtambũkaa o na nyamũ syĩ ũkanganĩ, nivoovaw’a, o na nĩsyavooviw’e nĩ andũ:'),
('kam', 'JAS', 3, 8, 'ĩndĩ vai mũndũ ũtonya kũvoovya ũĩmĩ; nĩ ũthũku ũtauasya, wusũĩte ũoi ũetae kĩkw’ũ.'),
('kam', 'JAS', 3, 9, 'Nĩtũmũtaĩaa Mwĩaĩi Asa waitũ naw’o; na nĩtũmevĩkaa andũ naw’o, ala moombiwe na mũvw’ano wa Ngai:'),
('kam', 'JAS', 3, 10, 'kanyw’anĩ o ũmwe kumaa ndaĩa na kĩumo. Ana‐a‐asa makwa, maũndũ asu matyaĩle kwĩthĩwa ũu.'),
('kam', 'JAS', 3, 11, 'Manzĩ me mũyo na manzĩ me ũũ nĩmatonya kuma nthongonĩ ĩmwe?'),
('kam', 'JAS', 3, 12, 'Ana‐a‐asa makwa, mũkũyũ nũtonya kũsyaa mathata, kana mũ savivũ kũsyaa makũyũ? No ta ũu vai nthongo itonya kumya manzĩ me mũnyũ na manzĩ me mũyo.'),
('kam', 'JAS', 3, 13, 'Nũũ wenyu mũĩ na wĩ na ũmanyi? Nĩonan’ye mawĩa make kwondũ wa mũendele wake mũseo nthĩnĩ wa ũuu wa ũĩ.'),
('kam', 'JAS', 3, 14, 'Ĩndĩ ethĩwa mwĩ na kĩwĩu kyai na ngananĩo ngoonĩ syenyu, mũikekathĩĩe na mũikanenee ũla w’o ũvũngũ.'),
('kam', 'JAS', 3, 15, 'Ũsu ti ũĩ ũla ũtheeaa kuma ĩũlũ, ĩndĩ nĩ wa nthĩ, nĩ wa kĩ‐mũndũ, na nĩ wa ndaimoni.'),
('kam', 'JAS', 3, 16, 'Nũndũ vala ve kĩwĩu na ngananĩo, nĩvo ve kĩthokoo na kĩla wĩa mũthũku.'),
('kam', 'JAS', 3, 17, 'Ĩndĩ ũĩ ũla wumaa ĩũlũ, mbee nĩ mũtheu, na ĩndĩ nĩ wa mũuo, nĩ mũuu, nĩwĩsũvĩkaa na ũvũthũ, wusũĩte tei na mosyao maseo, ũte na wendeesyo kana wangangan’yo.'),
('kam', 'JAS', 3, 18, 'Na ũsyao wa ũlũngalu nũvuĩawa nthĩnĩ wa mũuo nĩ ala maetae mũuo.'),
('kam', 'JAS', 4, 1, 'Kaũ na kũkita kwĩ katĩ wenyu kumaa va? Kũtyumaa vau mĩmeonĩ mĩthũku yenyu ĩla yũkitaa mamuthanĩ menyu?'),
('kam', 'JAS', 4, 2, 'Nĩmwendaa, na mũti na kĩndũ: nĩmũaa, na kwĩw’ĩaa kĩwĩu, na mũtitonya kwosa; nĩmũkwatasya kaũ na kũkita; na mũi na kĩndũ nũndũ mũivoyaa.'),
('kam', 'JAS', 4, 3, 'Nĩmũvoyaa, na mũtĩunengwa nũndũ nĩmũvoyaa naĩ, nĩ kana mwanange motanunĩ menyu.'),
('kam', 'JAS', 4, 4, 'Inyw’ĩ ilaalai, mũiĩsĩ kana ũnyanya wa nthĩ nĩ ũmaitha na Ngai? Kwondũ wa ũu o ũla ũkwenda kwĩthĩwa e mũnyanyae wa nthĩ nũtw’ĩkĩte mũmaitha wa Ngai.'),
('kam', 'JAS', 4, 5, 'Kana mwĩtalĩlya maandĩko meneena mana? Veva ũla ũtwĩe nthĩnĩ waitũ nĩwendaa kũvika kwĩw’ĩa kĩwĩũ?'),
('kam', 'JAS', 4, 6, 'Ĩndĩ nũtũnengae mumo mwingĩ mbee. Kwondũ wa ũu maandĩko maĩtye, Ngai nũmasiĩĩaa ala me na wing’athĩlĩlyo, ĩndĩ nũmanengae mumo ala me na wĩnyivyo.'),
('kam', 'JAS', 4, 7, 'Ĩnyivyei ĩndĩ kwa Ngai; ĩndĩ mũsiĩĩei ndevili, nake akamũkĩa.'),
('kam', 'JAS', 4, 8, 'Mũthengeei Ngai, nake akamũthengeea inyw’ĩ. Thambyai moko menyu, inyw’ĩ athe; na mũithesya ngoo syenyu, inyw’ĩ mwĩ na mĩtwe ĩlĩ.'),
('kam', 'JAS', 4, 9, 'Ĩthĩn’yei, na kũmeta, na kũĩa: kũtheka kwenyu nikũalyũlwe kĩmeto, na ũtanu wenyu ũalyũlwe kĩmako.'),
('kam', 'JAS', 4, 10, 'Ĩnyivyei mbee wa Mwĩaĩi, nake akamũnenevya.'),
('kam', 'JAS', 4, 11, 'Mũikailĩanĩle, ana‐a‐asa. Ũla ũmwilĩĩlaa mwana‐a‐ĩthe, kana kũmũsilĩla, amilĩĩlaa ĩla mĩao, na amĩsilaa ĩla miao: ĩndĩ ethĩwa ũsilĩlaa ĩla mĩao, nũtw’ĩkĩte ndwĩ mwĩki wa ĩla mĩao, ĩndĩ wĩ mũsili.'),
('kam', 'JAS', 4, 12, 'Mũnengani wa mĩao na mũsili no ũmwe, nake nĩ ũla ũtonya kũtangĩĩa na kwananga: ĩndĩ we wĩ ũũ ũla ũsilĩlaa ũngĩ?'),
('kam', 'JAS', 4, 13, 'Ĩndĩ yu, ala mũkwasya, Ũmũnthĩ kana ũnĩ tũkathi ndũanĩ ĩno, na kwĩkala vo mwaka, tũkĩtandĩthya, na kwona ũtandĩthyo:'),
('kam', 'JAS', 4, 14, 'na ĩndĩ mũiĩsĩ maũndũ ũndũ meĩthĩwa ũnĩ. Thayũ wenyu nĩ kyaũ? Nũndũ mwĩ mĩthũmũ ĩla yonekaa kavinda kanini, na ĩkyaa.'),
('kam', 'JAS', 4, 15, 'Nĩkwĩthĩwa ũndũ mwaĩle kwasya nĩ atĩĩ, Ethĩwa nĩ kwenda kwa Ngai tũkeethĩwa thayũ, na kwĩka ũna na ũna.'),
('kam', 'JAS', 4, 16, 'Ĩndĩ yu mwĩĩkathĩĩa wĩnenevyonĩ wenyu: kwĩkathĩĩa kw’onthe kũilyĩ ũu nĩ kũthũku.'),
('kam', 'JAS', 4, 17, 'Ũla wĩsĩ kwĩka nesa, na ndekaa, kwa ũsu nĩ naĩ.'),
('kam', 'JAS', 5, 1, 'Ĩndĩ yu, inyw’ĩ athwii, ĩai na kũkaya nũndũ wa mathĩna ala mokĩte ĩũlũ wenyu.'),
('kam', 'JAS', 5, 2, 'Mothwii menyu nĩmoete, na ngũa syenyu nilĩkĩte nĩ lungulu.'),
('kam', 'JAS', 5, 3, 'Thaavu wenyu na vetha wenyu niĩte nganga; na nganga yasyo ĩkamũkũsĩĩa, nayo ĩkaĩsaa mĩĩ yenyu ta mwaki. Nĩmwĩyiĩe ũthwii wenyu mĩthenya ya mũminũkĩlyo.'),
('kam', 'JAS', 5, 4, 'Sisyai, ĩtuvi ya atethya ma wĩa ala makethie mĩũndanĩ yenyu, yĩla mwaleile ũmanenga kwondũ wa ũkengani, nĩyĩũlonzan’ya mũno: na iĩo sya ala akethĩ nilikĩte matũnĩ ma Mwĩaĩi wa Savaothi.'),
('kam', 'JAS', 5, 5, 'Inyw’ĩ nĩmwaatĩĩe kwĩyendeesya ene kũũ nthĩ, na kwĩtan’ya ene; na mwaiĩthasya ngoo syenyu mũthenya wa kũawa.'),
('kam', 'JAS', 5, 6, 'Nĩmwamũsilĩle na kũmũaa ũla mũlũngalu; nake ndakĩlanasya nenyu.'),
('kam', 'JAS', 5, 7, 'Ũmĩĩsyai ĩndĩ, ana‐a‐asa, kũvika kũka kwa Mwĩaĩi. Sisyai, mũĩmi nĩweteelaa ũsyao wa nthĩ ũla wĩ vata akyũmĩĩsya ũndũ waw’o, kũvika oona mbua ya nthwa na ya uũa.'),
('kam', 'JAS', 5, 8, 'Inyw’ĩ nenyu ũmĩĩsyai; lũlũmĩlyai ngoo syenyu: nũndũ kũka kwa Mwĩaĩi kwĩ vakuvĩ.'),
('kam', 'JAS', 5, 9, 'Mũikanyungunyĩanĩsye inyw’ĩ kwa inyw’ĩ, ana‐a‐asa, nĩ kana mũikasilĩlwe: sisyai, mũsili nũũngeme mĩomonĩ.'),
('kam', 'JAS', 5, 10, 'Ana‐a‐asa, mosei athani ala maneenie syĩtwanĩ ya Mwĩaĩi, methĩwe ngelekan’yo kwenyu ya kũthĩna na ya kũmĩĩsya.'),
('kam', 'JAS', 5, 11, 'Sisyai, nĩtũmetaa aathimwa ala moomĩĩsye: nĩmweewie ũvoo wa wũmĩĩsyo wa Yovu, na ĩngĩ nĩmwoonie mũminũkĩlyo wa Mwĩaĩi, ũndũ Mwĩaĩi wusũĩte ĩnee na tei.'),
('kam', 'JAS', 5, 12, 'Ĩndĩ mbee wa maũndũ onthe, ana‐a‐asa makwa, mũikevĩte na ĩtũ, o na nthĩ, kana na wĩvĩto ũngĩ: ĩndĩ ĩĩ wenyu nĩwĩthĩwe ĩĩ, na aiee wenyu nĩwĩthĩwe aiee; nĩ kana mũikavalũke ũsilĩlonĩ.'),
('kam', 'JAS', 5, 13, 'Ve mũndũ katĩ wenyu ũla ũnũũthĩna? Navoye. Ve ũla wĩ na ũtanu? Naine mbathi sya ndaĩa.'),
('kam', 'JAS', 5, 14, 'Ve ũla ũwaĩte katĩ wenyu? Namete atumĩa ma ĩkanisa; mamũvoyee, makĩmũvaka mauta syĩtwanĩ ya Mwĩaĩi:'),
('kam', 'JAS', 5, 15, 'na kũvoya kwa mũĩkĩĩo kũkatangĩĩa ũsu mũwau, na Mwĩaĩi akamũvosya; na ethĩwa ekĩte naĩ, akaekewa.'),
('kam', 'JAS', 5, 16, 'Kwondũ wa ũu ũmbũlanĩlai naĩ syenyu inyw’ĩ kwa inyw’ĩ, na mũivoyanĩa inyw’ĩ kwa inyw’ĩ, nĩ kana mũvow’e. Kwĩsũvana kwa mũndũ mũlũngalu nĩkũvotaa mũno akĩvoya na kĩthetheesyo.'),
('kam', 'JAS', 5, 17, 'Eliya aĩ mũndũ wa mwĩkalĩle ũmwe naitũ, na avoya na kĩthing’ĩĩsyo mbua ndĩ kaue; na mbua ndyaaua ĩũlũ wa nthĩ ĩvinda ya myaka ĩtatũ na myei thanthatũ.'),
('kam', 'JAS', 5, 18, 'Na avoya ĩngĩ; na ĩtu yausya mbua, na nthĩ yamesya ũsyao wayo.'),
('kam', 'JAS', 5, 19, 'Ana‐a‐asa makwa, ethĩwa ve mũndũ wenyu ũvĩtĩtye nzĩa ya ũla w’o, na ũngĩ aimũalyũla;'),
('kam', 'JAS', 5, 20, 'ũsu namanye, kana ũla wamũalyũla mũndũ mwathe aume nzĩanĩ ĩla ũvĩtĩtye nayo akatangĩĩa mũndũ kuma kĩkw’ũnĩ, na akavw’ĩka naĩ nyingĩ.'),
('kam', '1PE', 1, 1, 'Vetelo, mũtũmwa wa Yesũ Klĩsto, valũa ũũ wakwa ũmavikĩe anyuve ala me Ũnyaĩĩkyonĩ, matwĩe ũeninĩ nthĩ sya Vondo, Kalatia, Kavatosia, Asĩa, na Vithinia,'),
('kam', '1PE', 1, 2, 'kwĩanana na ũndũ Ngai Asa wamanyie kuma tene, kwondũ wa kũvathanw’a nĩ Veva kwĩthĩwe atheu kũvika kwĩw’a na kũminzangĩw’a nthakame ya Yesũ Klĩsto: Mumo nĩwĩthĩwe nenyu na mũuo nĩwingĩvw’e.'),
('kam', '1PE', 1, 3, 'Nakathwe Ngai, Ĩthe wa Mwĩaĩi waitũ Yesũ Klĩsto, ũla kwĩanana na tei wake mwingĩ watũsyaie ĩngĩ twĩthĩwe na wĩkwatyo wĩ thayũ kwondũ wa kũthayũũka kwa Yesũ Klĩsto kuma akw’ũnĩ,'),
('kam', '1PE', 1, 4, 'twĩthĩwe na ũtiĩwa ũtanangĩkaa, na ũtavukaa, na ũtathelaa, wiĩtwe ĩtunĩ kwondũ wenyu,'),
('kam', '1PE', 1, 5, 'ala mũsũvĩawa nĩ vinya wa Ngai ũndũ wa mũĩkĩĩo mwĩthĩwe na ũtangĩĩo wũmbanĩtw’e kwonanw’a ĩvinda ya mũminũkĩlyo.'),
('kam', '1PE', 1, 6, 'Mwĩtana mũno maũndũnĩ asu, o na kau yu kavinda kanini, ethĩwa kwĩ vata, nĩmwĩw’ĩthaw’a woo nĩ matatwa ma mĩthemba mingĩ,'),
('kam', '1PE', 1, 7, 'nĩ kana kũtatwa kwa mũĩkĩĩo wenyu, nakw’o kwĩ vata mũno kwĩ thaavu ũla wanangĩkaa o na watatwa na mwaki, kũtonye kũete ngatho na ndaĩa na nguma ĩvinda ya kwonanw’a kwa Yesũ Klĩsto:'),
('kam', '1PE', 1, 8, 'ũla mũmwendaa o na kau mũiaamwona; o na mũtiũmwona yu, ĩndĩ mũkĩmwĩtĩkĩla, mwĩtana mũno na ũtanu ũtaneeneka na wusũĩtwe nĩ ndaĩa:'),
('kam', '1PE', 1, 9, 'mũkyosa mũminũkĩlyo wa mũĩkĩĩo wenyu, naw’o nĩ ũtangĩĩo wa mathayũ menyu.'),
('kam', '1PE', 1, 10, 'Na athani makũlilye na kũmantha mũno ũvoo wa ũtangĩĩo ũsu, namo nĩmathanie ũndũ wa mumo ũla ũkoka kwenyu:'),
('kam', '1PE', 1, 11, 'makĩmantha nĩ ĩvinda yĩva kana nĩ ĩvinda yĩilyĩ ata yĩla yoonaniw’e nĩ Veva wa Klĩsto ũla waĩ nthĩnĩ woo, yĩla wambie ũkũsĩĩa mathĩna ma Klĩsto, na ndaia ila ikethĩwa ĩtina wamo.'),
('kam', '1PE', 1, 12, 'Nao nĩmooniw’e, kana ti kwondũ woo ene, ĩndĩ nĩ kwondũ wenyu, mathũkũmie maũndũ asu, ala matavaniw’e kwenyu nĩ andũ ala mamũtavisye ũvoo mũseo nthĩnĩ wa Veva Mũtheu ũla watũmiwe kuma ĩtunĩ; maũndũ asu alaĩka mendaa ũkunĩkĩla.'),
('kam', '1PE', 1, 13, 'Kwondũ wa ũu ĩvotoei ilĩkonĩ syenyu, na ĩthĩwai na kĩlĩko mũkĩkwatya vyũ mumo ũla mwĩetewe ũv uan’yonĩ wa Yesũ Klĩsto;'),
('kam', '1PE', 1, 14, 'ta syana mbĩwi, mũtekwĩvw’anan’ya na mĩmeo yenyu mĩthũku ya tene ĩvinda yĩla mũteesĩ:'),
('kam', '1PE', 1, 15, 'ĩndĩ o tondũ ũla wamwĩtie nĩ mũtheu, o ta ũu ĩthĩwai atheu mwĩkalĩlenĩ wenyũ w’onthe wa thayũ;'),
('kam', '1PE', 1, 16, 'nĩkwĩthĩwa nikũandĩkĩtwe, Ĩthĩwai atheu; nũndũ nyie nĩ mũtheu.'),
('kam', '1PE', 1, 17, 'Na ethĩwa nĩmũmwĩkaĩlaa Asa, we ũla ũsilĩlaa kĩla mũndũ kwĩanana na wĩa wake vate wendeesyo, ĩkalai na w’ĩa ĩvinda yenyu yĩla mwĩ vaa ũeninĩ:'),
('kam', '1PE', 1, 18, 'mũkũmanya kana nĩmwoovoiw’e mume mwĩkalĩlenĩ wenyu wa mana ũla mwoosie kuma kwa aaũmae menyu, na mũiaaovow’a na syĩndũ ila syanangĩkaa, ta vetha kana thaavu;'),
('kam', '1PE', 1, 19, 'ĩndĩ mwovoetw’e na nthakame yĩ vata mũno, ta ya katena ka ĩlondu kate kawathe kana kaũndũ nongi, nayo nĩ nthakame ya Klĩsto;'),
('kam', '1PE', 1, 20, 'ũla wambie ũmanyĩka w’o mbee wa nthĩ itanambĩlĩlw’a, ĩndĩ nĩwumĩlĩtw’e mũminũkĩlyo wa mavinda kwondũ wenyu,'),
('kam', '1PE', 1, 21, 'inyw’ĩ ala kwondũ wake mwĩtĩkĩlĩte Ngai, ũla wamũthayũũkisye kũmumya kwa akw’ũ, na kũmũnenga ndaĩa; nĩ kana mũĩkĩĩo wenyu na wĩkwatyo wenyu wĩthĩwe nthĩnĩ wa Ngai.'),
('kam', '1PE', 1, 22, 'Nũndũ nĩmũtheetye ngoo syenyu kwondũ wa kwĩw’a kwenyu kwa ũla w’o kũvika kwenda ana‐a‐asa kũte wangangan’yo, endanai na wendo mũvyũ kuma ngoonĩ:'),
('kam', '1PE', 1, 23, 'nũndũ mũsyaĩtwe ingĩ, na ti kwa mbeũ ĩla yanangĩkaa, ĩndĩ nĩ ĩla ĩtanangĩkaa, ũndũ wa ndeto ya Ngai, ĩla yĩ thayũ na yĩkalaa.'),
('kam', '1PE', 1, 24, 'Nũndũ, Mĩĩ yonthe nĩ ta nyeki, Na ndaĩa yonthe yayo nĩ ta ĩlaa ya nyekĩ. Nyeki nĩyũmaa, na ĩlaa nĩyĩtĩkaa:'),
('kam', '1PE', 1, 25, 'Ĩndĩ ndeto ya Mwĩaĩi nĩyĩkalaa tene na tene. Na ndeto ĩno nĩ ndeto ya ũla ũvoo mũseo ũla watavaniw’e kwenyu.'),
('kam', '1PE', 2, 1, 'Mũkĩveta ĩndĩ ũthũku w’onthe, na ũĩ wa ũkengani w’onthe, na myangangan’yo, na iwĩu, na kwilĩanĩla kw’onthe,'),
('kam', '1PE', 2, 2, 'ta tũũkenge tũsyaĩtwe mĩtũkĩ, endaĩ mũno ĩia ya kĩlĩko yĩte ĩthũkye, nĩ kana mwĩane ũtangĩĩonĩ kwondũ wayo;'),
('kam', '1PE', 2, 3, 'ethĩwa nĩmũsamĩte kana Mwĩaĩi nĩ mũseo:'),
('kam', '1PE', 2, 4, 'mũkĩmũendea we, ĩvia yĩla yĩ thayũ, yaleilwe ki nĩ andũ, ĩndĩ nĩyĩnyuvĩtwe nĩ Ngai, yĩ vata mũno,'),
('kam', '1PE', 2, 5, 'inyw’ĩ nenyũ, ta mavia me thayũ, nĩmwakawa mwĩthĩwe nyũmba ya veva, ũthembi mũtheu, mũthembae nthembo sya veva, ila syĩtĩkĩlawa nĩ Ngai kwondũ wa Yesũ Klĩsto.'),
('kam', '1PE', 2, 6, 'Nĩkwĩthĩwa ndeto ii syĩ vo maandĩkonĩ, Sisya, nĩngwia nthĩnĩ wa Saioni ĩvia ĩnene ya kĩkotonĩ, ĩnyuve, yĩ vata mũno: Na ũla ũmwĩtĩkĩlaa ndakasonoka.'),
('kam', '1PE', 2, 7, 'Kwenyu inyw’ĩ ala mwĩtĩkĩlaa e vata mũno: ĩndĩ kwa ala matetĩkĩlaa, Ĩvia yĩla aki maleile, Nĩyo yatw’ĩkie ĩnene ya kĩkotonĩ;'),
('kam', '1PE', 2, 8, 'na ĩngĩ, Ĩvia ya ũtulya, na ĩvia ĩnene ya ũlulutĩkya; nũndũ nĩmalulutĩkaa nĩ ĩla ndeto, makĩmĩlea, nao maiĩwe ũndũ ũsu.'),
('kam', '1PE', 2, 9, 'Ĩndĩ ĩnyw’ĩ mwĩ ũsyao mũnyuve, ũthembi wa kĩũsumbĩ, mbaĩ ntheu, andũ make ki, nĩ kana mwonan’ye moseo manene ma ũla wamwĩ tie mume kĩvindunĩ mũlike kyeninĩ kyake kya ũseng’ya:'),
('kam', '1PE', 2, 10, 'inyw’ĩ ala tene mũtaĩ andũ, ĩndĩ yu mwĩ andũ ma Ngai: ala mũteew’ĩwe tei, ĩndĩ yu nĩmwĩw’ĩwe tei.'),
('kam', '1PE', 2, 11, 'Endwa, nĩngũmwĩsũva ta mwĩ ekali ma ũeninĩ na aendi ma kyalo, mwĩvathane na mĩmeo mĩthũku ya mwĩĩ, ĩla yũkitaa na ngoo;'),
('kam', '1PE', 2, 12, 'mwĩthĩwe na mwĩkalĩle waĩle kwa Andũ‐ma‐mbaĩ‐ingĩ; nĩ kana o na vala mamwilĩĩlaa ta mwĩ eki ma naĩ, yĩla meona meko menyu maseo, mamũtaĩe Ngai mũthenya wa kũsiw’a nĩwe.'),
('kam', '1PE', 2, 13, 'Ĩnyivĩsyei kĩla ũtw’ĩo wa mũndũ kwondũ wa Mwĩaĩi: ethĩwa nĩ wa mũsumbĩ, ta mũnene mbee;'),
('kam', '1PE', 2, 14, 'kana wa makavana, tao matũmĩtwe nĩwe kũmasilĩla ala mekaa naĩ na kũtaĩa ala mekaa nesa.'),
('kam', '1PE', 2, 15, 'Nĩkwĩthĩwa ũu nĩw’o kwenda kwa Ngai, nĩ kana kwondũ wa kwĩka nesa mũtonye ũvindĩthya kũtamanya kwa andũ atumanu:'),
('kam', '1PE', 2, 16, 'ta mwĩ athaw’a, na kũthaw’a kwenyu kũikethĩwe ũthei wa kũvw’ĩka ũthũku, ĩndĩ ta mwĩ ngombo sya Ngai.'),
('kam', '1PE', 2, 17, 'Taĩai andũ onthe. Endai ana‐a‐asa. Mũkĩei Ngai. Mũtaĩei mũsumbĩ.'),
('kam', '1PE', 2, 18, 'Athũkũmi, ĩnyivĩsyei mavwana menyu na kũkĩa kwingĩ; ti ala aseo na auu oka, ĩndĩ o na ala ai.'),
('kam', '1PE', 2, 19, 'Nũndũ ũu nĩ ũseo mũno, ethĩwa kwondũ wa wasya wa ngoo ũla welekele Ngaĩ, mũndũ nĩwũmĩĩasya mawoo akĩnyamaw’a ũndũ ũte wa w’o.'),
('kam', '1PE', 2, 20, 'Nũndũ nĩ ũtaĩo mwaũ, ethĩwa yĩla mũkwĩka naĩ, na mũikũnwa, nĩmũkũmĩĩsya? ĩndĩ ethĩwa yĩla mũkwĩka nesa, na mũithĩnw’a nĩmũkũmĩĩsya, ũu nĩw’o ũseo mũno mbee wa Ngai.'),
('kam', '1PE', 2, 21, 'Nũndũ mweetĩwe ũndũ ũsu: nĩkwĩthĩwa Klĩsto nake nĩwathĩniw’e kwondũ wenyu, aimũtiĩa ngelekan’yo, nĩ kana mũatĩĩae nyaĩĩ syake:'),
('kam', '1PE', 2, 22, 'we ũla ũtaaĩka naĩ, o na ũseleke ndwaaoneka kanyw’anĩ wake:'),
('kam', '1PE', 2, 23, 'we ũla, aumwa, ndaaĩumĩa; athĩnw’a, ndaakanda; ĩndĩ eeyia mwene kwa ũla ũsilaa w’o;'),
('kam', '1PE', 2, 24, 'nake mwene akua naĩ sitũ mwĩĩnĩ wake mũtĩnĩ ĩũlũ, nĩ kana ithyĩ, tũkw’ĩte kwa naĩ, twĩthĩwe thayũ kwa ũlũngalu; na kwondũ wa makũnwa make nĩmwavoiw’e.'),
('kam', '1PE', 2, 25, 'Nũndũ mwaendaa mwaĩte ta malondu; ĩndĩ yu nĩmũmũsyokee Mũĩthi na Mũsyaĩĩsya wa ngoo syenyu.'),
('kam', '1PE', 3, 1, 'O ta ũu, inyw’ĩ iveti, ĩnyivĩsyei aũme menyu; nĩ kana ethĩwa ve amwe mate ewi ma ĩla ndeto, matonye kwonw’a nĩ mwĩkalĩle wa iveti syoo vate ĩla ndeto;'),
('kam', '1PE', 3, 2, 'makyona mwĩkalĩle wenyu mũtheu wĩ na w’ĩa.'),
('kam', '1PE', 3, 3, 'Kwĩseũvya kwenyu kũikethĩwe kwĩseũvya kwa ũtheinĩ kwa kwokotha nzw’ĩĩ, na kwĩkĩa mĩio ya wanake ya thaavu, kana kwĩkĩa ngũa;'),
('kam', '1PE', 3, 4, 'ĩndĩ nĩkwĩthĩwe mũndũ ũla ũtonekaa wa ngoo, kwĩvw’ĩkanĩ kũla kũtanangĩkaa kwa veva wa wĩnyivyo na wa ũuu, ũla wĩ vata mũno mbee wa Ngai.'),
('kam', '1PE', 3, 5, 'Nũndũ ũu nĩw’o aka atheu ma tene ala mekwatĩtye Ngai meeseũvisye, makĩnyivĩsya aũme moo:'),
('kam', '1PE', 3, 6, 'o tondũ Sala wamwĩw’aa Avalaamu, akĩmwĩta vwana: nenyu mwĩ syana syake, ethĩwa mwĩkaa nesa, mũteũtĩsw’a nĩ w’ĩa o na wĩva.'),
('kam', '1PE', 3, 7, 'O ta ũu, inyw’ĩ aũme, ĩkalai na iveti syenyu kwĩanana na ũmanyi, mũkĩmũnenga mũndũ mũka ndaĩa, ta mũio ũte na vinya, ta mwĩ atiĩwa vamwe ma mumo wa thayũ; nĩ kana mboya syenyu itikaisĩĩwe.'),
('kam', '1PE', 3, 8, 'Kũminũkĩlya, inyw’onthe ĩthĩwai na kĩlilikano o kĩmwe, mwĩw’anĩe tei, mwendene ta ana‐a‐asa, mwĩ na ngoo yĩ ĩnee, mwĩ na wĩnyivyo:'),
('kam', '1PE', 3, 9, 'mũikekũle, kana kwĩumĩa mwaumwa; ĩndĩ athimaai; nũndũ mweetĩwe ũndũ ũũ, nĩ kana mũtiĩwe ũathimo.'),
('kam', '1PE', 3, 10, 'Nũndũ, Ũla wĩenda thayũ, Na kwona matukũ maseo, Nasiĩĩe ũĩmĩ wake ndũkaneene ũthũku, Na ilomo syake itikaneene na ũseleke:'),
('kam', '1PE', 3, 11, 'Nĩevathane na naĩ, naiĩka ũseo; Namanthe mũuo, naiũatĩĩa.'),
('kam', '1PE', 3, 12, 'Nũndũ metho ma Mwĩaĩi masyaasya ala alũngalu, Na matũ make nĩmethukĩĩasya mboya syoo: Ĩndĩ ũthyũ wa Mwĩaĩi wĩ ĩũlũ wa ala mekaa naĩ.'),
('kam', '1PE', 3, 13, 'Nũũ ũla wĩmwĩka naĩ, ethĩwa mwĩthangaaĩa ũndũ ũseo?'),
('kam', '1PE', 3, 14, 'Ĩndĩ o na ethĩwa mũkathĩnw’a kwondũ wa ũlũngalũ, mwĩ aathime; na mũikakĩe kũtĩsya kwoo, o na mũikaũũye;'),
('kam', '1PE', 3, 15, 'ĩndĩ mũtw’ei Klĩsto ethĩwe Mwĩaĩi ngoonĩ syenyu: ĩthĩwai mwĩyũmbanĩtye mavĩnda onthe kũmũsũngĩa kĩla mũndũ ũnũũmũkũlya ũndũ ũtumaa mwĩthĩwa na wĩkwatyo ũla wĩ nthĩnĩ wenyu ĩndĩ ũu nĩwĩkwe na ũuu na w’ĩa:'),
('kam', '1PE', 3, 16, 'mwĩ na wasya mũseo wa ngoo: nĩ kana, ũndũnĩ ũla mũkwilĩĩlwa, masonokw’e ala mekũumanga mwĩkalĩle wenyu mũseo nthĩnĩ wa Klĩsto.'),
('kam', '1PE', 3, 17, 'Nũndũ nĩ ũseo mbee, kũthĩnw’a kwondũ wa kwĩka nesa kwĩ kũthĩnw’a kwondũ wa kwĩka naĩ, ethĩwa nĩw’o kwenda kwa Ngai.'),
('kam', '1PE', 3, 18, 'Nũndũ Klĩsto nake nĩwathĩniw’e kwondũ wa naĩ ĩvinda o yĩmwe, ũla mũlũngalu vandũ va ala mate alũngalu, nĩ kana atũete kwa Ngai; akyũawa mwĩĩ, ĩndĩ akĩkĩwa thayũ vevanĩ;'),
('kam', '1PE', 3, 19, 'na e nthĩnĩ waw’o athi atavan’ya kwa maveva ala me kolokolonĩ,'),
('kam', '1PE', 3, 20, 'ala maleile kwĩw’a tene, yĩla wũmĩĩsyo wa Ngai weteelile matukũ ma Noa, yĩla ngalawa yakawa, na nthĩnĩ wayo andũ anini, namo nĩ nyanya, matangĩĩwe ũndũ wa manzĩ;'),
('kam', '1PE', 3, 21, 'ala memũtangĩĩa inyw’ĩ yu ta ngelekan’yo ya w’o, nayo nĩ ũvatiso, na ti kũveta ĩko ya mwĩĩ, ĩndĩ nĩ ũsũngĩo wa wasya mũseo wa ngoo mbee wa Ngai, ũndũ wa ũthayũũkyo wa Yesũ Klĩsto;'),
('kam', '1PE', 3, 22, 'ũla waendie ĩtunĩ na e ngalĩ ya kw’oko kwa aũme kwa Ngai: alaĩka na mokũmũ na mavinya manyivĩtw’e kwake.'),
('kam', '1PE', 4, 1, 'Ĩndĩ nĩkwĩthĩwa Klĩsto nĩwathĩniw’e e na mwĩĩ, nenyu o ta ũu ĩkĩai miio ya kau ya kĩlilikano kyu; nĩkwĩthĩwa ũla wathĩniw’e e na mwĩĩ nũekanĩte na naĩ;'),
('kam', '1PE', 4, 2, 'nĩ kana kuma yu, ĩvinda yenyu yĩla yĩtiele mwĩ mwĩĩnĩ, mũikekalae mĩmeonĩ ya andũ, ĩndĩ kwendanĩ kwa Nagi.'),
('kam', '1PE', 4, 3, 'Nũndũ ĩvinda yĩla ĩvitu nĩyeanĩe kwĩka ũndũ Andũ‐ma‐mbaĩ‐ingĩ mendaa, na kũkinya maũndũnĩ ma ũlaalai, na mĩmeo mĩthũku, na ũthengi, na mboka itaĩle, na ũnywi, na ũthaithi wa mĩvw’anano ũtosana na mĩao:'),
('kam', '1PE', 4, 4, 'nao monaa nĩ ũseng’yo inyw’ĩ kũlea kũsemba vamwe nao kũendeeaa naĩnĩ isũ vate kwĩsiĩĩa, makĩmũneenea naĩ:'),
('kam', '1PE', 4, 5, 'na nĩmakamũnenga ũtalo we ũla wĩyũmbanĩtye kũsilĩla ala me thayũ na ala akw’ũ.'),
('kam', '1PE', 4, 6, 'Nũndũ wa ũu ũla ũvoo mũseo nĩwataviw’e ala makwie, nĩ kana masilĩlwe o tondũ andũ me na mwĩĩ masilĩlawa, ĩndĩ methĩwe thayũ vevanĩ o tondũ Ngai ũnũkwenda.'),
('kam', '1PE', 4, 7, 'Ĩndĩ mũminũkĩlyo wa maũndũ onthe nĩ mũthengeeu: kwondũ wa ũu ĩthĩwai na kĩlĩko kĩanu, na mũkĩsyaĩĩsya kũvoyanĩ:'),
('kam', '1PE', 4, 8, 'na mbee wa maũndũ onthe ĩthĩwai mũkyendana mũno na wendo mũvyũ inyw’ĩ kwa inyw’ĩ; nũndũ wendo nũvw’ĩkaa wingĩ wa naĩ:'),
('kam', '1PE', 4, 9, 'mũkĩthokan’ya ene kwa ene mũtekũnyungunyĩsya:'),
('kam', '1PE', 4, 10, 'kwĩanana na ũndũ kĩla mũndũ wosie mũthĩnzĩo, thũkũmanai ene kwa ene, ta asuvĩi aseo ma mumo wa Ngai wa mĩthemba mingĩ;'),
('kam', '1PE', 4, 11, 'ethĩwa mũndũ nũkũneena, naneene o ta ndeto syaneeniwe nĩ Ngai; ethĩwa mũndũ nũkũthũkũma, nathũkũme na vinya ũla ũnengetwe nĩ Ngai: nĩ kana maũndũnĩ onthe Ngai ataĩwe ũndũ wa Yesũ Klĩsto, ũtaĩo na ũsumbĩko nĩ wake tene na tene. Ameni.'),
('kam', '1PE', 4, 12, 'Endwa, mũikone ta ũndũ wa ũseng’ya ũtatwa ũilyĩ ta mwaki ũla wĩ kwenyu, ũla ũmũvikĩaa ũmũtate, ta ũndũ weũ wamũkwata:'),
('kam', '1PE', 4, 13, 'ĩndĩ o ũndũ mwĩ osi ma mathĩna ma Klĩsto, tanai; nĩ kana mũtane ũtanu mũnene mũno ĩvinda ya ũvuan’yo wa ũtheu wake mũtisu.'),
('kam', '1PE', 4, 14, 'Ethĩwa mwĩvũthw’a kwondũ wa syĩtwa ya Klĩsto, mwĩ aathime: nĩkwĩthĩwa Veva wa ũtaĩo, o Veva wa Ngai, ekalaa ĩũlũ wenyu.'),
('kam', '1PE', 4, 15, 'Kũikethĩwe ũmwe wenyu kũthĩnw’a nĩkwĩthĩwa nĩ mũaani, kana kĩng’ei, kana mwĩki wa naĩ, kana mwĩlikya maũndũnĩ ma andũ angĩ:'),
('kam', '1PE', 4, 16, 'ĩndĩ ethĩwa mũndũ nũthĩnaw’a nĩkwĩthĩwa nĩ Mũklĩsto, ndakasonoke; ĩndĩ namũkathe Ngai syĩtwanĩ yĩũ.'),
('kam', '1PE', 4, 17, 'Nũndũ ĩvinda nĩ ĩviku ya ũsilĩlo kwambĩlĩlw’a nyũmbanĩ ya Ngai: na ethĩwa wĩambĩlĩlw’a kwa ithyĩ, mũminũkĩlyo wa ala matew’aa ũvoo mũseo wa Ngai ũkeethĩwa ata?'),
('kam', '1PE', 4, 18, 'Na ethĩwa mũndũ mũlũngalu evonoka na vinya, ũla ũtakĩaa Ngai na ũla mwathe akooneka va?'),
('kam', '1PE', 4, 19, 'Kwondũ wa ũu nao ala mathĩnaw’a kwĩanana na kwenda kwa Ngai nĩmamwiĩe Mũmbi ũla wĩ kĩthito ngoo syoo, makĩka nesa.'),
('kam', '1PE', 5, 1, 'Ĩndĩ nĩngũtaa atumĩa ala me kwenyu, nakwa nĩ mũtumĩa o tao, na nĩ ngũsĩ ya mathĩna ma Klĩsto, o na nĩ mwosi wa ũtheu mũtisu ũla ũkonanw’a:'),
('kam', '1PE', 5, 2, 'sũvĩai ĩĩthya ya Ngai yĩla yĩ kwenyu, mũkĩyĩsisya, ti ũndũ wa kũingĩĩw’a, ĩndĩ na kwenda, o na ti ũndũ wa kũunwa nĩ syĩndũ itaĩle, ĩndĩ na kĩlĩko kĩyũmbanĩtye;'),
('kam', '1PE', 5, 3, 'o na ti kwĩsumbĩkya kĩandanĩ kĩla mũnengetwe, ĩndĩ mũkĩtw’ĩkĩthya ene ngelekan’yo sya yĩla ĩĩthya.'),
('kam', '1PE', 5, 4, 'Na yĩla Mũĩthi mũnene ũkaumĩla, mũkoosa ngovia ya ũsumbĩ ya ũtheu mũtisu ĩla ĩtaalyũkaa.'),
('kam', '1PE', 5, 5, 'O ta ũu, inyw’ĩ ma mũika mũninangi, ĩnyivĩsyei atumĩa. Ĩĩ, inyw’onthe ĩvotoei wĩnyivyo, mũtethan’ye inyw’ĩ kwa inyw’ĩ: nĩkwĩthĩwa Ngai nũsiĩĩaa ala mekwĩnenevya, ĩndĩ amanengae mumo ala menyivasya.'),
('kam', '1PE', 5, 6, 'Ĩnyivyei ĩndĩ ungu wa kw’oko kwa Ngai kwĩ na vinya, nĩ kana amũnenevye ĩvinda yeanĩa;'),
('kam', '1PE', 5, 7, 'mũkĩmwiĩa kwĩmakĩa kwenyu kw’onthe, nũndũ nĩwe ũmũsũvĩaa.'),
('kam', '1PE', 5, 8, 'Ĩthĩwai na kĩlĩko, syaĩĩsyai: mũvinganĩsya wenyu ndevili angangaa kũũ na kũũ ta mũnyambũ ũkũluma, aimantha mũndũ aye:'),
('kam', '1PE', 5, 9, 'nake mũsiĩĩei mũlũmite mũĩkĩĩonĩ wenyu mũkĩmanya kana mathĩna o asu meanĩaw’a nthĩnĩ wa ana‐a‐ĩthe menyu ala me kũũ nthĩ.'),
('kam', '1PE', 5, 10, 'Na Ngai wa mumo w’onthe, ũla wamwĩtie inyw’ĩ mũlike ndaĩanĩ yake ya tene na tene nthĩnĩ wa Klĩsto, mwamina kũthĩnw’a ĩvinda ĩnini, we mwene akamwĩanĩsya, na ũmũlũlũmĩlya, na ũmwĩkĩa vinya.'),
('kam', '1PE', 5, 11, 'Ũsumbĩko nĩ wake tene na tene. Ameni.'),
('kam', '1PE', 5, 12, 'Namũandĩkĩa ndeto mbũthũ na kũmũetee na kw’oko kwa Silivano, mwana‐a‐asa waitũ wĩ kĩthito, o tondũ nĩtalaa, ngĩmũtaa, na kũkũsĩĩa kana ũũ nĩ mumo wa w’o wa Ngai: ũngamai na ũlũmu nthĩnĩ waw’o.'),
('kam', '1PE', 5, 13, 'Ũla mũnyuve tenyu, ũla wĩ Mbaviloni, nĩwamũkethya; na Maliko mwana wakwa nĩwamũkethya.'),
('kam', '1PE', 5, 14, 'Kethan’yai na ũmumunyano wa wendo. Mũuo nĩwĩthĩwe na inyw’onthe ala mwĩ nthĩnĩ wa Klĩsto.'),
('kam', '2PE', 1, 1, 'Simoni Vetelo, ngombo na mũtũmwa wa Yesũ Klĩsto, valũa ũũ wakwa ũmavikĩe ala moosie vamwe naitũ mũĩkĩĩo o ũsu ũmwe ũla wĩ vata mũnene nthĩnĩ wa ũlũngalu wa Ngai waitũ na Mũtangĩĩi waitũ Yesũ Klĩsto:'),
('kam', '2PE', 1, 2, 'Mumo nĩwĩthĩwe nenyu na mũuo wingĩvw’e nthĩnĩ wa ũmũmanya Ngai na Yesũ Mwĩaĩi waitũ.'),
('kam', '2PE', 1, 3, 'Nĩkwĩthĩwa vinya wake wa Ũ‐Ngai nũtũnengete maũndũ onthe me vata ma thayũ na ma kũtuma tũmũkĩa Ngai, kwondũ wa ũmũmanya we ũla watwĩtie ũndũ wa ndaĩa yake mwene na ũseo wake;'),
('kam', '2PE', 1, 4, 'na kwondũ wa maũndũ asu nũtũnengete mawatho make manene mũno ala me vata mũnene; nĩ kana kwondũ wamo mũtw’ĩke osi ma mũtuo wa Ngai, mũvonokete wanangĩko ũla wĩ kũũ nthĩ kwondũ wa mĩmeo.'),
('kam', '2PE', 1, 5, 'Ĩĩ, na kwondũ wa ũũ mũkyongeleela ũthangaau w’onthe ngalĩ yenyu, mũĩkĩĩonĩ wenyu ĩkĩai ũseo; na ũseonĩ wenyu ũmanyi;'),
('kam', '2PE', 1, 6, 'na ũmanyinĩ wenyu wĩting’o; na wĩting’onĩ wenyu wũmĩĩsyo; na wũmĩĩsyonĩ wenyu kũmũkĩa Ngai;'),
('kam', '2PE', 1, 7, 'na nthĩnĩ wa kũmũkĩa Ngai kwenyu wendano wa ana‐a‐asa; na wendanonĩ wenyu wa ana‐a‐asa wendo.'),
('kam', '2PE', 1, 8, 'Nũndũ maũndũ asu methĩwa nĩ menyu na kũmusũa ki, nĩmeũtuma mwĩthĩwa mũte atulu o na mũtiĩthĩwa mũte na ũsyao mũkĩmanya Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', '2PE', 1, 9, 'Nũndũ ũla ũte na maũndũ asu nĩ kĩlilinda, akyona kĩla kĩ vakuvĩ kyoka, akyũlwa nĩ kũthew’a kwa naĩ syake sya tene.'),
('kam', '2PE', 1, 10, 'Kwondũ wa ũu, ana‐a‐asa, thangaai mũno mũlũlũmĩlye kwĩtwa kwenyu na kũnyuvwa kwenyu: nũndũ ethĩwa nĩmũkwĩka maũndũ asu, muikalulutĩka o na ĩndĩĩ:'),
('kam', '2PE', 1, 11, 'nũndũ o ũu mukanengwa na ũlau kũlika ũsumbinĩ wa tene na tene wa Mwĩaĩi waitũ na Mũtangĩĩi Yesũ Klĩsto.'),
('kam', '2PE', 1, 12, 'Kwondũ wa ũu ngeethĩawa nĩyũmbanĩtye mavinda onthe kũmũlilikanasya maũndũ aa, o na kau nĩmũmesĩ, na kũlũlũmĩlw’a nthĩnĩ wa ũla w’o mwĩ naw’o.'),
('kam', '2PE', 1, 13, 'Nakwa nĩona nĩ ũseo, ĩvinda yĩla ngwĩkala ĩeemanĩ, yĩĩ, kũmũvindũa ũndũ wa kũmũlilikan’ya;'),
('kam', '2PE', 1, 14, 'ngĩmanya kana kũveta ĩeema yakwa kwĩũka mĩtũkĩ, o ũndũ Mwĩaĩi waitũ Yesũ Klĩsto wambonisye.'),
('kam', '2PE', 1, 15, 'Ĩĩ, nĩngũthangaaa nĩ kana mavinda onthe ĩtina wa kũkw’a kwakwa mũtonye ũlilikana maũndũ aa.'),
('kam', '2PE', 1, 16, 'Nũndũ tũtyaaatĩĩa mbano itilĩtwe na ũĩ, yila twamũmanyĩthisye vinya wake na kũka kwa Mwĩaĩi waitũ Yesũ Klĩsto, ĩndĩ twaĩ ngũsĩ sya ũtheu mũtisu wake sya kwona na metho.'),
('kam', '2PE', 1, 17, 'Nũndũ nĩwosie kuma kwa Ngai Asa ndaĩa na ũtheu mũtisu, yĩla wavikĩwe nĩ wasya waumie ũtheuni mũnene mũtisu, ũkyasya, Ũũ nĩwe Mwana wakwa mwendwa, ũla nenendeeaw’a nĩwe:'),
('kam', '2PE', 1, 18, 'na ithyĩ nĩtweewie wasya ũsu ũiuma ĩtunĩ, yĩla twaĩ vamwe nake kĩĩmanĩ kĩla kĩtheu.'),
('kam', '2PE', 1, 19, 'Na twĩ na ndeto ya wathani ĩlũlũmĩlw’e mũno; nayo mwĩĩka nesa mũimĩkwata, ta taa ũkenaa vala ve kĩvundu mũvaka kwakya, na ĩla ndata ya kĩoko ĩkyũkĩla ngoonĩ syenyu:'),
('kam', '2PE', 1, 20, 'mũkĩmanya ũũ mbee, kana vai wathani maandĩkonĩ wĩ na ũalyũlo wa mũndũ mwene.'),
('kam', '2PE', 1, 21, 'Nũndũ wathani o na wĩva ndwaaetwe nĩ kwenda kwa mũndũ: ĩndĩ andũ maneenie ndeto syaumie kwa Ngai, maitongoew’a nĩ Veva Mũtheu.'),
('kam', '2PE', 2, 1, 'Ĩndĩ kwookĩlile athani ma ũvũngũ katĩ wa andũ, o tondũ kũkeethĩwa amanyĩsya ma ũvũngũ katĩ wenyu, ala melikya na ũĩ ũmanyĩsyo wa kwasya, makĩmũkaĩa o na Mwĩaĩi ũla wamathooie, makĩyĩetee wanangĩko wa mĩtũkĩ.'),
('kam', '2PE', 2, 2, 'Na aingĩ makaatĩĩa meko moo ma mĩmeo mĩthũku; na kwondũ wamo nzĩa ya ũla w’o ĩkawetawa naĩ.'),
('kam', '2PE', 2, 3, 'Na nthĩnĩ wa wendĩ woo makeyonea ũtandĩthyo kwenyu ũndũ wa ndeto sya ũkengani: ũsilĩlo woo ũla watwiwe kuma tene ndwĩĩkala, na kwanangwa kwoo kũtikakoma.'),
('kam', '2PE', 2, 4, 'Nũndũ ethĩwa Ngai ndaamaeka alaĩka ala mavĩtisye, ĩndĩ amekya Ngienani, na ũmalikya maimanĩ manene me kĩvindu, masũvĩwe kũvika ũsilĩlo wũke;'),
('kam', '2PE', 2, 5, 'na ndaamĩeka nthĩ ya tene, ĩndĩ amũvĩtya Noa, mũtavan’ya wa ũlũngalu, vamwe na angĩ mũonza, yĩla waetie kĩw’ũ kingĩ ĩũlũ wa nthĩ ya ala matamũkĩaa Ngai;'),
('kam', '2PE', 2, 6, 'na kwitw’ĩkĩthya mũu ndũa sya Sotomo na Ngomola aisilĩla na kwing’uthũla akitw’ĩkĩthya ngelekan’yo kwa ala matakamũkĩa Ngai;'),
('kam', '2PE', 2, 7, 'na amũvĩtya Loto ũla waĩ mũlũngalu, anyamaĩtw’e nĩ mwĩkalĩle wa mĩmeo mĩthũku ya ala athe'),
('kam', '2PE', 2, 8, '(nũndũ mũndũ ũsu mũlũngalu, aiĩkala katĩ woo, akyona na kwĩw’a, athĩn’ya ngoo yake ndũngalu kĩla mũthenya na meko moo ma ũng’endu):'),
('kam', '2PE', 2, 9, 'Mwĩaĩi nĩwĩsĩ nzĩa ya kũmavonokya ala mamũkĩaa Ngai maume matatwanĩ, na kwĩkalya ala mate alũngalu kũvika mũthenya wa ũsilĩlo masilĩlwe;'),
('kam', '2PE', 2, 10, 'ĩndĩ mũno nĩ ala maatĩĩaa mwĩĩ mĩmeonĩ ya ũvuku, na kũvũthya ũsumbĩko. Aemi, eyĩaĩi, mateũtetema makĩumanga monene:'),
('kam', '2PE', 2, 11, 'ĩndĩ alaĩka o na kau nĩ anene kwĩ o ũtonyinĩ na vinyanĩ, matietae ũvingan’yo mũthũku ĩũlũ woo mbee wa Mwĩaĩi.'),
('kam', '2PE', 2, 12, 'Ĩndĩ asu, ta nyamũ ite ilĩko, masyaiwe nyamũ ki sya ũkwatwa na kwanangwa, makĩneena ndeto nthũku maũndũnĩ ala mateũmanya, nthĩnĩ wa kwananga kwoo makaanangwa w’o,'),
('kam', '2PE', 2, 13, 'makĩkwatwa nĩ thĩna o ĩtuvi ya kwĩka naĩ; matalaa nĩ mũyo kwĩthĩwa na mboka ĩtaĩle mũthenya, matw’ĩkĩte malanga na mawathe, makĩvikĩla maũndũ ma mboka syoo sya ũkengani na makĩsyoka kũĩsanĩa vamwe nenyu;'),
('kam', '2PE', 2, 14, 'me na metho mausũĩte ũlaalai, ala mataekaa kwĩka naĩ; makĩkusya andũ mate alũmu; me na ngoo imanyĩĩtw’e nthĩnĩ wa wendi; syana sya kĩumo;'),
('kam', '2PE', 2, 15, 'makĩtia nzĩa ndũngalu, maaa, makĩatĩĩa nzĩa ya Mbalaamu mwana wa Mbeoli, ũla wendie ĩtuvi ya kwĩka naĩ;'),
('kam', '2PE', 2, 16, 'ĩndĩ nĩwakaniw’e ũndũ wa ĩvĩtyo yake mwene: ĩng’oi yĩtaneenaa yaneena na wasya wa mũndũ na yasiĩĩa ndũũka ya mwathani ũsu.'),
('kam', '2PE', 2, 17, 'Asu nĩ mbuluti ite manzĩ, na nundu isisivaa iitwawa nĩ kĩuutani; nao nĩmaiĩwe wiũ wa kĩvindu.'),
('kam', '2PE', 2, 18, 'Nũndũ, makĩneena ndeto nene mũno sya kwĩkathĩĩa, kwondũ wa mĩmeo ya mwĩĩ na maũndũ mathavu makusasya ala meũthonoka yu kuma katĩ wa ala mekalaa ũmamyĩsyonĩ wa ũvũngũ;'),
('kam', '2PE', 2, 19, 'makĩmantha kũthaw’a, o yĩla mo ene me ngombo sya wanangĩko; nũndũ, mũndũ akĩlw’a vinya nĩ ũngĩ, alikaw’a ũkombonĩ wa ũsu wamũkĩlya vinya.'),
('kam', '2PE', 2, 20, 'Nũndũ ethĩwa, ĩtina wa kũvonoka movukyo ma nthĩ ũndũ wa kũmũmanya Mwĩaĩi na Mũtangĩĩi Yesũ Klĩsto, maikwatwa ĩngĩ nĩo na ũkĩlw’a vinya, mwĩkalĩle woo wa mũminũkĩlyo nĩ mũthũku kũvĩta ũla wa mbee.'),
('kam', '2PE', 2, 21, 'Nũndũ nĩ kavaa kwoo kethĩwa maiaamanya nzĩa ya ũlũngalu, kwĩ kũmĩmanya na ĩtina kũalũka na kũtia mwĩao mũtheu ũla manengiwe.'),
('kam', '2PE', 2, 22, 'Nĩkwatw’ĩkĩkie kwamo kwĩanana na nthimo ya w’o, Ngitĩ kũalũkĩla ĩngĩ matavĩka mayo, na ngũlũe ĩla ithambĩtw’e kwĩyalalya ĩngĩ ndakanĩ.'),
('kam', '2PE', 3, 1, 'Endwa, valũa ũũ nĩ wa kelĩ namũandĩkĩa; na nthĩnĩ wamo elĩ nĩvindũa ilĩko syenyu sya w’o kwondũ wa ũmũlilikan’ya;'),
('kam', '2PE', 3, 2, 'nĩ kana mũlilikane ndeto ila syaneeniwe tene nĩ athani atheu, na mwĩao wa Mwĩaĩi na Mũtangĩĩi ũla waetiwe nĩ atũmwa menyu:'),
('kam', '2PE', 3, 3, 'mũkĩmanya ũũ mbee, atĩ mĩthenya ya mũminũkĩlyo akaakaan’ya makooka na ũkaakaasya, makĩatĩĩa mĩmeo yoo mĩthũkũ,'),
('kam', '2PE', 3, 4, 'na makyasya, Ũla watho wa kũka kwa Klĩsto ũĩva? nũndũ, kuma ĩvinda yĩla aaũmae maitũ makomie, syĩndũ syonthe iilyĩ o ũndũ syailyĩ kuma mwambĩlĩlyo wasyo kũmbwa.'),
('kam', '2PE', 3, 5, 'Kwondũ wa kwenda kwoo ene nĩmolawa nĩ ũũ kana kwaĩ matu kuma tene, na nthĩ ĩkwatene ũtee wa manzĩ na nthinĩ wa manzĩ, ũndũ wa ndeto ya Ngai;'),
('kam', '2PE', 3, 6, 'na kwondũ wa ũu nthĩ ĩla yaĩ vo yaaa, ĩkĩvwĩkwa nĩ manzĩ:'),
('kam', '2PE', 3, 7, 'ĩndĩ matu ala me vo yu, na nthĩ, sĩĩwe mwaki ũndũ wa ndeto o ĩsu, ikĩsũvĩwa kũvika mũthenya wa ũsilĩlo na kwanangwa kwa andũ ala matamũkĩaa Ngai.'),
('kam', '2PE', 3, 8, 'Ĩndĩ mũikolwe nĩ ũndũ ũũ ũmwe, endwa, kana mũthenya ũmwe kwa Mwĩaĩi nĩ ta myaka ngili, na myaka ngili no ta mũthenya ũmwe.'),
('kam', '2PE', 3, 9, 'Mwĩaĩi nde kĩkono ũndũ wa kwĩanĩsya watho wake, tondũ amwe matalaa kĩkono; ĩndĩ nũnũkũmĩĩsya ũndũ wenyu, atekwenda ũmwe o na wĩva ae, ĩndĩ endaa onthe mavikĩe ũalyũlonĩ wa ngoo.'),
('kam', '2PE', 3, 10, 'Ĩndĩ mũthenya wa Mwĩaĩi ũkooka ta kĩng’ei; na mũthenya ũsu matu makavĩta na kĩlituko kĩnene, na syĩndũ sya ĩtũnĩ ikanyaĩĩkw’a nĩ mwaki mwai, na nthĩ na mawĩa ala me nthĩnĩ wayo makavĩvw’a.'),
('kam', '2PE', 3, 11, 'Nĩkwĩthĩwa syĩndũ isu syonthe nikanyaĩĩkw’a ũu, inyw’ĩ mwaĩle kwĩthĩwa andũ mailyĩ ata mwĩkalĩlenĩ mũtheu wa thayũ na kũmũkĩa Ngai,'),
('kam', '2PE', 3, 12, 'mũkyeteela na kwenda mũno kũka kwa mũthenya wa Ngai, na kwondũ wakw’o matu makanyaĩĩkw’a nĩ kwakana mwaki, na syĩndũ sya ĩtunĩ ikatheũka nĩ mwaki mwai?'),
('kam', '2PE', 3, 13, 'Ĩndĩ, kwĩanana na watho wake, tweteele matu meũ na nthĩ nzaũ, naw’o ũlũngalu ũtwĩe nthĩnĩ wayo.'),
('kam', '2PE', 3, 14, 'Kwondũ wa ũu, endwa, nĩkwĩthĩwa mweteele maũndũ asu, thangaai kana mwoneke mũuonĩ, mũte na ĩlanga na mũtekwilĩĩlĩka mbee wake.'),
('kam', '2PE', 3, 15, 'Na talai kana wũmĩĩsyo wa Mwĩaĩi waitũ nĩ ũtangĩĩo; o ũndũ mwana‐a‐asa waitũ Vaulo, ũla tũmwendete mũno, wamũandĩkĩe kwĩanana na ũĩ ũla wanengiwe;'),
('kam', '2PE', 3, 16, 'mavalũanĩ make onthe nao aiweta maũndũ aa; na nthĩnĩ wamo ve maũndũ amwe me vinya kũmanya, ala andũ matamanyĩĩtw’e na mate alũmu mathyoekasya, o ũndũ mekaa na maandĩko ala angĩ, makĩyĩetee wanangĩko woo ene.'),
('kam', '2PE', 3, 17, 'Inyw’ĩ ĩndĩ, endwa, nũndũ nĩmwĩsĩ maũndũ aa mbee, ĩsũvĩei mũikavalũke kuma ũlũmunĩ wenyu nũndũ wa kwaw’a nĩ ũmanyĩsyo wa ũvũngũ wa andũ athe.'),
('kam', '2PE', 3, 18, 'Ĩndĩ ĩanaai mumonĩ na ũmanyinĩ wa Mwĩaĩi waitũ na Mũtangĩĩi Yesũ Klĩsto. Ũtaĩo nĩ wake yu na tene na tene. Ameni.'),
('kam', '1JN', 1, 1, 'Ũla waĩ kuma mwambĩlĩlyonĩ, ũla tweewie, na ũla twoonie na metho maitũ, ũla twasyaisye, na ũla twavavatie na moko maitũ, ũndũ wa ĩla Ndeto ya thayũ'),
('kam', '1JN', 1, 2, '(na thayũ ũsu nĩwoonaniw’e na ithyĩ nĩtwonete, na nĩtũũkũsĩĩa, na nĩtũũmũtavya inyw’ĩ thayũ, ũla thayũ ũtathela, ũla waĩ vamwe an Asa, na woonaniw’e kwitũ);'),
('kam', '1JN', 1, 3, 'ũla twoonie na kũwĩw’a nĩw’o tũũmũtavya inyw’ĩ, nĩ kana inyw’ĩ nenyu mwĩthĩwe na mũamba naitũ: ĩĩ, na mũamba witũ nĩ ũmwe na Asa na Mwana wake Yesũ Klĩsto:'),
('kam', '1JN', 1, 4, 'na maũndũ asu nĩtũũmũandĩkĩa nĩ kana ũtanu witũ wusũe.'),
('kam', '1JN', 1, 5, 'Na ũtũmane nĩ ũũ ũla tweewie kwake na twĩmũtavya inyw’ĩ, kana Ngai nĩ kyeni, na nthĩnĩ wake vai kĩvindu nongi.'),
('kam', '1JN', 1, 6, 'Ethĩwa twĩasya kana twĩ mũamba nake na tũendaa na kĩvindu, twĩneena ũvũngũ, na tũtyĩkaa ũla w’o:'),
('kam', '1JN', 1, 7, 'ĩndĩ ethĩwa tũendaa na kyeni, tondũ we wĩ kyeninĩ, twĩ na mũamba ene kwa ene, na nthakame ya Yesũ Mwana wake nĩtũtheasya naĩ syonthe.'),
('kam', '1JN', 1, 8, 'Ethĩwa twĩasya tũi na naĩ, nĩtũkwĩkenga ene, na ũla w’o ndwĩ nthĩnĩ waitũ.'),
('kam', '1JN', 1, 9, 'Ethĩwa nĩtũkumbũla naĩ sitũ, we e kĩthito, na nĩ mũlũngalu wa utũekea naĩ sitũ, na kũtũthesya ũndũ ũte ũlũngalu w’onthe.'),
('kam', '1JN', 1, 10, 'Ethĩwa twĩasya tũtyĩkĩte naĩ, twĩmũtw’a e ũvũngũ, na ndeto yake ndĩ nthĩnĩ waitũ.'),
('kam', '1JN', 2, 1, 'Syana syakwa nini, maũndũ aa nĩmũandĩkĩa nĩ kana mũikeke naĩ. Na ethĩwa mũndũ akeeka naĩ, twĩ na Mũtũvoyei kwa Asa, Yesũ Klĩsto ũla mũlũngalu:'),
('kam', '1JN', 2, 2, 'nake nĩwe nthembo ya wĩw’anĩthyo kwondũ wa naĩ sitũ; na ti sitũ syoka, ĩndĩ nũndũ wa naĩ sya nthĩ yonthe.'),
('kam', '1JN', 2, 3, 'Na ũndũnĩ ũũ nĩtwĩsĩ kana nĩtũmũmanyĩte, ethĩwa nĩtũkwataa mĩao yake.'),
('kam', '1JN', 2, 4, 'Ũla waasya, Nyie nĩnĩmwĩsĩ, na ndakwataa mĩao yake, ũsu e ũvũngũ, na ũla w’o ndwĩ nthĩnĩ wake;'),
('kam', '1JN', 2, 5, 'ĩndĩ ũla ũkwataa ndeto yake, nthĩnĩ wake wendo wa Ngai nĩwĩanĩw’e ki. Kwa ũu nĩtũũmanya kana twĩ nthĩnĩ wake:'),
('kam', '1JN', 2, 6, 'ũla waasya atwĩe nthĩnĩ wake nĩwaĩle mwene kũendaa o ũndũ we waendaa.'),
('kam', '1JN', 2, 7, 'Endwa, ndiũmũandĩkĩa mwĩao mweũ, ĩndĩ nĩ mwĩao wa tene ũla mwaĩ naw’o kuma mwambĩlĩlyonĩ: na mwĩao ũsu wa tene nĩ ndeto ĩla mweewie.'),
('kam', '1JN', 2, 8, 'Na ĩngĩ, nĩmũandĩkĩa mwĩao mweũ, naw’o nĩ wa w’o nthĩnĩ wake na nthĩnĩ wenyu; nĩkwĩthĩwa kĩvĩndu nĩkĩũvĩta na kyeni kya w’o nĩkĩkenaa o na yu.'),
('kam', '1JN', 2, 9, 'Ũla waasya e kyeninĩ na amenaa mwana‐a‐ĩthe, ũsu e kĩvindunĩ kũvika yu.'),
('kam', '1JN', 2, 10, 'Ũla ũmwendaa mwana‐a‐ĩthe atwĩe kyeninĩ, na nthĩnĩ wake vai ũlulutĩkyo.'),
('kam', '1JN', 2, 11, 'Ĩndĩ ũla ũmenaa mwana‐a‐ĩthe e kĩvindunĩ, na aendaa kĩvindunĩ, na ndesĩ kũla ũnũũthi, nũndũ kĩvindu nĩkĩmwaĩtye metho.'),
('kam', '1JN', 2, 12, 'Nĩmũandĩkĩa inyw’ĩ, syana syakwa nini, nũndũ nĩmũekewe naĩ syenyu kwondũ wa syĩtwa yake.'),
('kam', '1JN', 2, 13, 'Nĩmũandĩkĩa inyw’ĩ, aasa, nĩkwĩthĩwa nĩmũmwĩsĩ we ũla wĩ kuma mwambĩlĩlyonĩ. Nĩmũandĩkĩa inyw’ĩ, anake, nĩkwĩthĩwa nĩmwakĩlilye ũla mũthũku vinya. Nĩnamũandĩkĩa inyw’ĩ, syana nini, nũndũ nĩmũmwĩsĩ Asa.'),
('kam', '1JN', 2, 14, 'Nĩnamũandĩkĩa inyw’ĩ, aasa, nũndũ nĩmũmwĩsĩ we ũla wĩ kuma mwabĩlĩlyonĩ. Nĩnamũandĩkĩa inyw’ĩ, anake, nũndũ mwĩ na vinya, na ndeto ya Ngai ĩtwĩe nthĩnĩ wenyu, na nĩmwakĩlilye ũla mũthũku vinya.'),
('kam', '1JN', 2, 15, 'Mũikamyende nthĩ, o na syĩndũ sya nthĩ. Ethĩwa mũndũ o na wĩva nũnũũmyenda nthĩ, wendo wa Asa ndwĩ nthĩnĩ wake.'),
('kam', '1JN', 2, 16, 'Nĩkwĩthĩwa kĩla kĩ kũũ nthĩ, wendi wa mwĩĩ na wendi wa metho na wĩyĩan’yo wa thayũ ityumaa kwa Asa, ĩndĩ nĩ sya nthĩ.'),
('kam', '1JN', 2, 17, 'Na nthĩ nĩnĩũvĩta, na wendi wayo: ĩndĩ ũla wĩkaa kwenda kwa Ngai ekalaa tene na tene.'),
('kam', '1JN', 2, 18, 'Syana nini, nĩ saa wa mũminũkĩlyo: na tondũ mweewie kana nthũ ya Klĩsto nĩnĩkũka, o na yu nthũ sya Klĩsto nĩsyaingĩvie; na ũndũ wa ũu nĩtwĩsĩ kana nĩ saa wa mũminũkĩlyo.'),
('kam', '1JN', 2, 19, 'Nĩmeeyumisye kwitũ, ĩndĩ matyaĩ maitũ; nũndũ kethĩwa maĩ maitũ, methĩwa makĩkala vamwe naitũ: ĩndĩ nĩmeeyumisye, nĩ kana monanw’e atĩ asu onthe ti maitũ.'),
('kam', '1JN', 2, 20, 'Nenyu mwĩ amenesye mauta kuma kwa ũla Mũtheu, na nĩmwĩsĩ maũndũ onthe.'),
('kam', '1JN', 2, 21, 'Ndinamũandĩkĩa nũndũ mũtyĩsĩ ũla w’o, ĩndĩ nũndũ nĩmũwĩsĩ, na vai ũvũngũ o na wĩva wumaa nthĩnĩ wa ũla w’o.'),
('kam', '1JN', 2, 22, 'Ũla wĩ ũvũngũ nũũ, ate o ũla ũnũũlea kana Yesũ nĩwe Klĩsto? Ũsu nĩwe nthũ ya Klĩsto, ũla ũkaĩaa Asa na Mwana.'),
('kam', '1JN', 2, 23, 'O ũla ũnũũmũkaĩa Mwana, ũsu nde na Asa: ũla ũnũũmumbũla Mwana e na Asa nake.'),
('kam', '1JN', 2, 24, 'Ĩndĩ inyw’ĩ, ũekei wĩkale nthĩnĩ wenyu ũvoo ũla mweewie kuma mwambĩlĩlyonĩ. Ethĩwa ũvoo ũsu mweewie kuma mwambĩlĩlyonĩ wĩkalaa nthĩnĩ wenyu, mũkekalaa nthĩnĩ wa Mwana, na nthĩnĩ wa Asa.'),
('kam', '1JN', 2, 25, 'Na ũũ nĩw’o watho ũla watwathie ithyĩ, naw’o nĩ ũla thayũ ũtathela.'),
('kam', '1JN', 2, 26, 'Maũndũ aa namũandĩkĩa ũndũ wa ala mekwenda kũmwasya.'),
('kam', '1JN', 2, 27, 'Nenyu, kũmenew’a mauta kũla mwanengiwe nĩwe nĩkwĩkalĩte nthĩnĩ wenyu na mũi na vata wa kũmanyĩw’a nĩ mũndũ; ĩndĩ nũndũ kũmenew’a mauta kũla kumaa kwake nĩkũmũmanyĩasya maũndũ onthe, na nĩ kwa w’o, na ti ũvũngũ, na o ũndũ kwamũmanyĩisye, ĩkalai nthĩnĩ wake.'),
('kam', '1JN', 2, 28, 'Na yu, syana syakwa nini, ĩkalai nthĩnĩ wake; nĩ kana yĩla wĩonanw’a twĩthĩwe na ũnyiau, na tũtikasonoke mbee wake, ooka.'),
('kam', '1JN', 2, 29, 'Ethĩwa nĩmwĩsĩ kana we nĩ mũlũngalu, manyai kana kĩla mũndũ wĩkaa ũlũngalu nũsyaĩtwe nĩwe.'),
('kam', '1JN', 3, 1, 'Sisyai ũndũ wendo wa Asa ũilyĩ ũla ũtwendete naw’o, kana twĩtwe syana sya Ngai; na nĩ w’o twĩ syo. Ũndũ wa ũu nthĩ ndĩtwĩsĩ, nĩkwĩthĩwa ndyaamũmanya we.'),
('kam', '1JN', 3, 2, 'Endwa, yu twĩ syana sya Ngai, na ndũnamba kwonanw’a ũndũ tũkethĩwa tũilyĩ. Nĩtwĩsĩ kana, yĩla wĩonanw’a, tũkavw’anana nake; nũndũ tũkamwona we o ũndũ ũilyĩ.'),
('kam', '1JN', 3, 3, 'Na kĩla mũndũ wĩ na wĩkwatyo ũũ nĩwĩtheasya mwene, o tondũ nake nĩ mũtheu.'),
('kam', '1JN', 3, 4, 'Kĩla mũndũ wĩkaa naĩ ekaa ũng’endu; na naĩ nĩ ũng’endu.'),
('kam', '1JN', 3, 5, 'Nenyu nĩmwĩsĩ kana nĩwonaniw’e avete naĩ; na nthĩnĩ wake vai naĩ.'),
('kam', '1JN', 3, 6, 'O mũndũ ũla ũtwĩe nthĩnĩ wake ndekaa naĩ: ũla wĩkaa naĩ ndaamwona, o na ndamwĩsĩ.'),
('kam', '1JN', 3, 7, 'Syana syakwa nini, mũiketĩkĩle mũndũ amwasye: ũla wĩkaa ũlũngalu nĩ mũlũngalu, o ũndũ we nĩ mũlũngalu:'),
('kam', '1JN', 3, 8, 'ũla wĩkaa naĩ nĩ wa ndevili; nũndũ ndevili atwĩe ekaa naĩ kuma mwambĩlĩlyonĩ. Kwondũ wa ũu Mwana wa Nagi nĩwonaniw’e, nĩ kana anange mawĩa ma ndevili.'),
('kam', '1JN', 3, 9, 'O mũndũ ũla ũsyaĩtwe nĩ Ngai ndekaa naĩ, nĩkwĩthĩwa mbeũ yake ĩtwĩe nthĩnĩ wake: na ndatonya kwĩkaa naĩ, nĩkwĩthĩwa nũsyaĩtwe nĩ Ngai.'),
('kam', '1JN', 3, 10, 'Ũndũnĩ ũũ syana sya Ngai nikwonanw’a, o na syana sya ndevili: o mũndũ ũla ũtekaa ũlũngalu ti wa Ngai, o na ũla ũtamwendaa mwana‐a‐ĩthe.'),
('kam', '1JN', 3, 11, 'Nũndũ ũtũmane ũla mweewie kuma mwambĩlĩlyonĩ nĩ ũũ, twendane ene kwa ene:'),
('kam', '1JN', 3, 12, 'na ti ta Kaini ũla waĩ wa ũla mũthũku, na ooaa mwana‐a‐ĩnyia. Na amũaie nũndũ wa kĩ? Nũndũ mawĩa make maĩ mathũku, na ma mwana‐a‐inyia maĩ malũngalu.'),
('kam', '1JN', 3, 13, 'Mũikaseng’e, ana‐asa, ethĩwa nthĩ nĩnĩũmũmena.'),
('kam', '1JN', 3, 14, 'Nĩtwĩsĩ kana nĩtũvĩtĩte twauma kĩkw’ũnĩ twavota thayũnĩ, nĩkwĩthĩwa nĩtũmendaa ana‐a‐asa. Ũla ũtendanaa atwĩe kĩkw’ũni.'),
('kam', '1JN', 3, 15, 'O mũndũ ũla ũmenaa mwana‐a‐ĩthe nĩ mũaani: nenyu nĩmwĩsĩ kana vai mũaani wĩ na thayũ ũtathela ũtwĩe nthĩnĩ wake.'),
('kam', '1JN', 3, 16, 'Ũndũnĩ ũũ nĩtũũmanya wendo, nũndũ we anenganie thayũ wake kwondũ witũ; naitũ nĩtwaĩle kũnengane mathayũ maitũ kwondũ wa ana‐a‐asa.'),
('kam', '1JN', 3, 17, 'Ĩndĩ o ũla wĩ na syĩndũ sya kũũ nthĩ, nake aimwona mwana‐a‐ĩthe e na vata, na ailea ũmwĩw’ĩa tei, wendo wa Ngai ũtwĩe nthĩnĩ wake ata?'),
('kam', '1JN', 3, 18, 'Syana syakwa nini, tũikendane na ndeto, kana na ũĩmĩ; ĩndĩ twendane na kwĩka, na twendane w’o.'),
('kam', '1JN', 3, 19, 'Kwondũ wa ũu nĩtũũmanya kana twĩ ma ũla w’o, na nĩtũtonya kũvindĩthya ngoo sitũ, twĩ mbee wake:'),
('kam', '1JN', 3, 20, 'nũndũ ethĩwa ngoo sitũ niũtũsilĩla, Ngaĩ nĩ mũnene kwĩ ngoo sitũ, na nĩwĩsĩ maũndũ onthe.'),
('kam', '1JN', 3, 21, 'Endwa, ethĩwa ngoo sitũ itiũtũsilĩla, twĩ na ũnyiau vala ve Ngai;'),
('kam', '1JN', 3, 22, 'na o ũndũ ũla tũũvoya nĩtũũnengwa nĩwe, nĩkwĩthĩwa nĩtũkwataa mĩao yake na nĩtwĩkaa maũndũ ala mamwendeeasya.'),
('kam', '1JN', 3, 23, 'Na mwĩao wake nĩ ũũ, kana twĩtĩkĩle syĩtwa ya Mwana wake Yesũ Klĩsto, na kwendana, o ũndũ watwĩaĩe.'),
('kam', '1JN', 3, 24, 'Na ũla ũkwataa mĩao yake ũsu atwĩe nthĩnĩ wake, nake atwĩe nthĩnĩ wake. Na ũndũnĩ ũũ nĩtwĩsĩ kana nũtwĩe nthĩnĩ waitũ, nũndũ wa Veva ũla watũnengie.'),
('kam', '1JN', 4, 1, 'Endwa, mũiketĩkĩle kĩla veva, ĩndĩ ĩkuũei maveva, kana nĩ ma Ngai; nũndũ athani aingĩ ma ũvũngũ nĩmanyaĩĩkie kũũ nthĩ.'),
('kam', '1JN', 4, 2, 'Ũndũnĩ ũũ nĩmũũmanya Veva wa Ngai: kĩla veva wumbũlaa kana Yesũ Klĩsto nĩwokie e na mwĩĩ nĩ wa Ngai:'),
('kam', '1JN', 4, 3, 'na kĩla veva ũtaumbũlaa Yesũ, ti wa Ngai: na ũsu nĩw’o veva wa ĩla nthũ ya Klĩsto, ũndũ mweewie kana ũkooka; o na yu wĩ kũũ nthĩ.'),
('kam', '1JN', 4, 4, 'Inyw’ĩ, syana syakwa nini, mwĩ ma Ngai, na nĩmũmakĩlĩtye vinya: nĩkwĩthĩwa ũla wĩ nthĩnĩ wenyu nĩ mũnene kwĩ ũla wĩ kũũ nthĩ.'),
('kam', '1JN', 4, 5, 'Asu nĩ ma nthĩ: na kwondũ wa ũu maneenaa ta ma nthĩ, na nthĩ nĩmew’aa.'),
('kam', '1JN', 4, 6, 'Ithyĩ twĩ ma Ngai: ũla ũmwĩsĩ Ngai nũtwĩw’aa; ũla ũte wa Ngai ndatwĩw’aa. Kwondũ wa ũu nĩtũũmanya veva wa ũla w’o, na veva wa kwasya.'),
('kam', '1JN', 4, 7, 'Endwa, twendanei ene kwa ene: nũndũ wendo nĩ wa Ngai; na kĩla mũndũ wendanaa nũsyaĩtwe nĩ Ngai, na nũmwĩsĩ Ngai.'),
('kam', '1JN', 4, 8, 'Ũla ũtendanaa ndamwĩsĩ Ngai; nũndũ Ngai nĩ wendo.'),
('kam', '1JN', 4, 9, 'Ũndũnĩ ũũ wendo wa Ngai nĩwonanĩtw’e kwitũ, nũndũ Ngai nĩwamũtũmie Mwana wake kũũ nthĩ, ũla wasyaiwe e ũmwe, nĩ kana twĩthĩwe na thayũ kwondũ wake.'),
('kam', '1JN', 4, 10, 'Ũũ nĩw’o wendo, ti ithyĩ twamwendie Ngai, ĩndĩ nĩwe watwendie ithyĩ, na atũma Mwana wake ethĩwe nthembo ya wĩw’anĩthyo kwondũ wa naĩ sitũ.'),
('kam', '1JN', 4, 11, 'Endwa, ethĩwa Ngai nĩwatwendie ũu, naitũ nĩtwaĩlwe nĩ kwendana.'),
('kam', '1JN', 4, 12, 'Vai mũndũ waamwona Ngai o na ĩndĩĩ: ethĩwa nĩtũkwendana, Ngai nũtwĩe nthĩnĩ waitũ, na wendo wake nĩwĩanĩw’e nthĩnĩ waitũ;'),
('kam', '1JN', 4, 13, 'ũndũnĩ ũũ nĩtũũmanya kana tũtwĩe nthĩnĩ wake nake nthĩnĩ waitũ, nũndũ nũtũnengete Veva wake.'),
('kam', '1JN', 4, 14, 'Naitũ nĩtwonete na twĩ na ũkũsĩ kana Asa nĩwatũmie Mwana ethĩwe Mũtangĩĩi wa nthĩ.'),
('kam', '1JN', 4, 15, 'O ũla wumbũlaa kana Yesũ nĩ Mwana wa Ngai, Ngai nũtwĩe nthĩnĩ wake, nake atwĩe nthĩnĩ wa Ngai.'),
('kam', '1JN', 4, 16, 'Naitũ nĩtwĩsĩ na nĩtwĩkĩlĩte wendo ũla Ngai wĩ naw’o nthĩnĩ waitũ. Ngai nĩ wendo; na ũla wĩkalaa wendonĩ ekalaa nthĩnĩ wa Ngai, na Ngai ekalaa nthĩnĩ wake.'),
('kam', '1JN', 4, 17, 'Kwondũ wa ũu wendo, nĩwĩanĩw’e kwitũ, nĩ kana twĩĩthĩwa na ũnyiau mũthenya wa ũsilĩlo; nũndũ ũndũ ũilyĩ we, nĩw’o ithyĩ tũilyĩ kũũ nthĩ.'),
('kam', '1JN', 4, 18, 'Vai w’ĩa nthĩnĩ wa wendo: ĩndĩ wendo mwĩanĩu nĩwĩkasya w’ĩa ũtee, nũndũ w’ĩa wĩ thĩna; na ũla wĩ na w’ĩa ti mwĩanĩu wendonĩ.'),
('kam', '1JN', 4, 19, 'Ithyĩ nĩtwendanaa nĩkwĩthĩwa nĩwambie ũtwenda.'),
('kam', '1JN', 4, 20, 'Ethĩwa mũndũ easya, Nyie nĩnĩmwendete Ngai, na emena mwana‐a‐ĩthe, nĩ mũneeni wa ũvũngũ: nũndũ ũla ũtamwendaa mwana‐a‐ĩthe ũla wonaa, ndatonya kũmwenda Ngai ũla ũtaamwona.'),
('kam', '1JN', 4, 21, 'Naitũ twĩ na mwĩao ũũ kuma kwake, kana ũla ũmwendaa Ngai namwende mwana‐a‐ĩthe nake.'),
('kam', '1JN', 5, 1, 'O mũndũ ũla wĩtĩkĩlaa atĩ Yesũ nĩwe Klĩsto ũsu nũsyaĩtwe nĩ Ngai: na o ũla ũmwendaa ũla wamũsyaie nĩwendaa ũla ũsyaĩtwe nĩwe.'),
('kam', '1JN', 5, 2, 'Ũndũnĩ ũũ nĩtũũmanya kana nĩtũsyendete syana sya Ngai, tũkĩmwenda Ngai na kwĩka mĩao yake.'),
('kam', '1JN', 5, 3, 'Nũndũ kũmwenda Ngai nĩ kũũ, tũkwatae mĩao yake: na mĩao yake ti mĩito.'),
('kam', '1JN', 5, 4, 'Nũndũ o kĩla kĩsyaĩtwe nĩ Ngai nĩkĩkĩlasya nthĩ vinya: na kĩla kĩkĩlasya nthĩ vinya, nĩ mũĩkĩĩo witũ.'),
('kam', '1JN', 5, 5, 'Na ũla ũkĩlasya nthĩ vinya nũũ, ate o ũla wĩtĩkĩlaa kana Yesũ nĩ Mwana wa Ngai?'),
('kam', '1JN', 5, 6, 'Ũũ nĩ ũla wokie kwa manzĩ na nthakame, nake nĩwe Yesũ Klĩsto; ndaaũka ũndũ wa manzĩ oka, ĩndĩ nĩwokie ũndũ wa manzĩ vamwe na nthakame.'),
('kam', '1JN', 5, 7, 'Na nĩ Veva ũla ũkũsĩĩaa, nĩkwĩthĩwa Veva nĩwe w’o.'),
('kam', '1JN', 5, 8, 'Nũndũ nĩ atatũ ala makũsĩĩaa, ũla Veva, na manzĩ, na nthakame: na asu atatũ nĩmew’anaa ũndũ ũmwe.'),
('kam', '1JN', 5, 9, 'Ethĩwa nĩtwĩtĩkĩlaa ũkũsĩ wa andũ, ũkũsĩ wa Ngai nĩ mũnene mbee: nũndũ ũkũsĩ wa Ngaĩ nĩw’o ũũ, nĩwakũsĩĩe Mwana wake.'),
('kam', '1JN', 5, 10, 'Ula ũmwĩtĩkĩlaa Mwana wa Ngai ũsu e na ũkũsĩ nthĩnĩ wake: na ũla ũtamwĩtĩkĩla Ngai emũtw’a e ũvũngũ; nĩkwĩthĩwa ndaaĩtĩkĩla ũkũsĩ ũla Ngai wanenganie ũndũ wa Mwana wake.'),
('kam', '1JN', 5, 11, 'Na ũkũsĩ nĩw’o ũũ, kana Ngai nĩwatũnengie thayũ wa tene na tene, na thayũ ũsu wĩ nthĩnĩ wa Mwana wake.'),
('kam', '1JN', 5, 12, 'Ũla wĩ na Mwana e na thayũ ũsu; na ũla ũte na Mwana wa Ngai nde na thayũ ũsu.'),
('kam', '1JN', 5, 13, 'Maũndũ asu namũandĩkĩa, nĩ kana mũmanye mwĩ na thayũ wa tene na tene, inyw’ĩ ala mwĩtĩkĩlaa syĩtwa ya Mwana wa Ngai.'),
('kam', '1JN', 5, 14, 'Na ũũ nĩw’o ũnyiau ũla twĩ naw’o vala ũĩ, ethĩwa tũkavoya ũndũ kwĩanana na kwenda kwake, nũtwĩw’aa:'),
('kam', '1JN', 5, 15, 'na ethĩwa nĩtwĩsĩ kana nũtwĩw’aa o ũndũ tũũvoya, nĩtwĩsĩ kana maũndũ ala twavoya twĩ namo.'),
('kam', '1JN', 5, 16, 'Ethĩwa mũndũ eona mwana‐a‐ĩthe aiĩka naĩ ĩte ya ũvikĩa kĩkw’ũ, navoye, na Ngai akamũnenga thayũ o na ala mekwĩka naĩ ĩte ya ũvikĩa kĩkw’ũ. Kwĩ naĩ ya ũvikĩa kĩkw’ũ: na ndikwasya navoye kwondũ wa ĩsu.'),
('kam', '1JN', 5, 17, 'Ũndũ w’onthe ũte ũlũngalu nĩ naĩ: na kwĩ naĩ ĩte ya ũvikĩa kĩkw’ũ.'),
('kam', '1JN', 5, 18, '1 Yoa 3.9; Yoa 17.15. Nĩtwĩsĩ kana o mũndũ ũla ũsyaĩtwe nĩ Ngai ndekaa naĩ; ĩndĩ ũla ũsyaĩtwe nĩ Ngai nĩwĩsũvĩaa mwene, na ũla mũthũku ndamũkiita.'),
('kam', '1JN', 5, 19, 'Nĩtwĩsĩ kana twĩ ma Ngai, na nthĩ yonthe ĩtwĩe nthĩnĩ wa ũla mũthũku.'),
('kam', '1JN', 5, 20, 'Na nĩtwĩsĩ kana Mwana wa Ngai nĩwokie, na nũtũnengete ũmanyi, nĩ kana tũmũmanye we ũla wa w’o, naitũ twĩ nthĩnĩ wa ũsu ũla wa w’o, nthĩnĩ wa Mwana wake Yesũ Klĩsto. Ũũ nĩwe Ngai wa w’o, na thayũ wa tene na tene.'),
('kam', '1JN', 5, 21, 'Syana syakwa nini, isũvĩei mĩvw’anano.'),
('kam', '2JN', 1, 1, 'Nyie, ũla mũtumĩa, valũa ũũ wakwa ũkĩvikĩe kĩveti kĩla kĩnyuve na syana syakyo, ala nĩmendete w’o; na tii nyie nyioka, ĩndĩ o na onthe ala mesĩ ũla w’o;'),
('kam', '2JN', 1, 2, 'kwondũ wa ũla w’o ũtwĩe nthĩnĩ waitũ, naw’o ũkeethĩwa naitũ kũvika tene na tene:'),
('kam', '2JN', 1, 3, 'Mumo, na tei, na mũuo makeethĩwa naitũ, kuma kwa Ngai Asa, na kwa Yesũ Klĩsto, ũla Mwana wa Asa, nthĩnĩ wa w’o na wendo.'),
('kam', '2JN', 1, 4, 'Nĩngũtana mũno nũndũ nĩneethĩe syana syaku imwe iendete nthĩnĩ wa ũla w’o, o ũndũ tweeaĩwe nĩ Asa.'),
('kam', '2JN', 1, 5, 'Na yu, kĩveti, nĩngũkwĩsũva, ti atĩ nĩ mwĩao mweũ ngũkũandĩkĩa, ĩndĩ no ũla twaĩ naw’o kuma mwambĩlĩlyonĩ, atĩ twendane.'),
('kam', '2JN', 1, 6, 'Na ũũ nĩw’o wendo, tũendae tũatĩĩe mĩao yake. Ũũ nĩw’o mwĩaĩo, o ũndũ mweewie kuma mwambĩlĩlyonĩ, mũendae nthĩnĩ wa wendo.'),
('kam', '2JN', 1, 7, 'Nĩkwĩthĩwa akengani aingĩ nĩmaumĩlĩte kũũ nthĩ, na nĩ ala mataumbũlaa kana Yesũ Klĩsto nĩwokie na mwĩĩ. Ũsu nĩ mũkengani na nthũ ya Klisto.'),
('kam', '2JN', 1, 8, 'Ĩsũvĩei mũtikasye mawĩa ala mũtethetye, ĩndĩ mwose ĩtuvi yĩanĩu.'),
('kam', '2JN', 1, 9, 'O mũndũ ũla wĩvĩtũkasya mbee na ndekalaa ũmanyĩsyonĩ wa Klĩsto, nde na Ngai: ĩndĩ ũla wĩkalaa ũmanyĩsyonĩ, ũsu e na Asa na Mwana.'),
('kam', '2JN', 1, 10, 'Ethĩwa mũndũ o na wĩva akooka kwenyu, na ndeũete ũmanyĩsyo ũũ, mũtikamũthokye nyũmba kwenyu, o na mũikamũkethye:'),
('kam', '2JN', 1, 11, 'nũndũ ũla ũmũkethasya e mũamba nake mawĩanĩ make mathũku.'),
('kam', '2JN', 1, 12, 'O na kau nĩ na maũndũ maingĩ ma ũmũandĩkĩa, ndikwenda kũmaandĩka ĩkalatasinĩ na ingi: ĩndĩ nĩngwĩkwatya kũka kwenyu, tũneena’nye twenene, nĩ kana ũtanu wenyu wusũe.'),
('kam', '2JN', 1, 13, 'Syana sya mwĩĩtu‐a‐mwenyu ũla mũnyuve nĩsyaũkethya.'),
('kam', '3JN', 1, 1, 'Nyie, ũla mũtumĩa, valũa ũũ wakwa ũmũvikĩe Kaio mwendwa, ũla nĩmwendaa w’o.'),
('kam', '3JN', 1, 2, 'Mwendwa, nĩngũvoya nĩ kana ũathimĩke maũndũnĩ onthe na wĩthĩwe na mwĩĩ mũseo, o ũndũ ngoo yaku ĩathimĩkĩte.'),
('kam', '3JN', 1, 3, 'Nũndũ natanie mũno, yĩla ana‐a‐asa mookie maikũsĩĩa w’o waku, o ũndũ ũendaa nthĩnĩ wa ũla w’o.'),
('kam', '3JN', 1, 4, 'Ndi na ũtanu ũngĩ mũnene ũvĩtũkĩte ũũ, ngĩw’a ũvoo wa syana syakwa ũndũ iendaa nthĩnĩ wa ũla w’o.'),
('kam', '3JN', 1, 5, 'Mwendwa, wĩkaa kĩla wĩa na kĩthito ũkĩmatethya ana‐a‐asa, o na aeni;'),
('kam', '3JN', 1, 6, 'nao nĩmakũsĩĩe wendo waku ĩkanisanĩ: naku ũkeeka nesa ũkĩmaumasaya kyalonĩ kyoo ũndũ waĩle kwa Ngai:'),
('kam', '3JN', 1, 7, 'nĩkwĩthĩwa nĩmaumie kwoo nũndũ wa yĩla Syĩtwa, matekwosa kĩndũ kwa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', '3JN', 1, 8, 'Kwondũ wa ũu nĩtwaĩle kũthokya andũ ta asu, nĩ kana twĩthĩwe atethan’ya ma wĩa ma ũla w’o.'),
('kam', '3JN', 1, 9, 'Naandĩkĩe ĩkanisa ũvoo: ĩndĩ Ndioteleve, ũla wendete kwĩthĩwa e mũnene katĩ wamo, ndaatwĩtĩkĩla.'),
('kam', '3JN', 1, 10, 'Kwondũ wa ũu, ethĩwa ngooka, ngalilikana mawĩa make ala wĩkaa, aitũvulũkila ndeto mbathe: na ndeĩanĩwa nĩ ũu, ĩndĩ we mwene ndamathokya ana‐a‐asa, o na ala menda kũmathokya nũnũũmavata na kũmalũngya ĩkanisanĩ.'),
('kam', '3JN', 1, 11, 'Mwendwa, ndũkeelekan’ye na ũndũ ũthũku, ĩndĩ ĩelekanasye na ũla ũseo. Ũla wĩkaa nesa nĩ wa Ngai: ũla wĩkaa naĩ ndaamwona Ngai.'),
('kam', '3JN', 1, 12, 'Ndemetelio nũkũsĩĩwe nĩ andũ onthe, vamwe na ũla w’o: ĩĩ, o na ithyĩ nĩtũũkũsĩĩa; na nĩwĩsĩ ũkũsĩ witũ nĩ wa w’o.'),
('kam', '3JN', 1, 13, 'Naĩ na maũndũ maingĩ ma ũkũandĩkĩa, ĩndĩ ndikwenda kũmaandĩka na ingi na kĩandĩki:'),
('kam', '3JN', 1, 14, 'ĩndĩ nĩngwĩkwatya ngakwona mĩtũkĩ, na ĩndĩ tũkaneenan’ya twenene.'),
('kam', '3JN', 1, 15, 'Mũuo nĩwĩthĩwe naku. Anyanyae maitũ nĩmakũkethya. Ngethesya ala anyanyawa, kĩla mũndũ na syĩtwa yake.'),
('kam', 'JUD', 1, 1, 'Yuta, ngombo ya Yesũ Klĩsto, na mwana‐a‐inyia wa Yakovo, valũa ũũ wakwa ũmavikĩe ala meetiwe, endwa nthĩnĩ wa Ngai Asa, na asũvĩwa ũndũ wa Yesũ Klĩsto:'),
('kam', 'JUD', 1, 2, 'Tei na mũuo na wendo nĩmaingĩv’we kwenyu.'),
('kam', 'JUD', 1, 3, 'Endwa, yĩla neeyũmbanĩtye kũmũandĩkĩa inyw’ĩ ũvoo wa ũtangĩĩo witũ ithyonthe, naingĩĩw’e kũmũandĩkĩa inyw’ĩ ngimũtaa mũkitĩe ũla mũĩkĩĩo wanengiwe atheu ĩvinda o yĩmwe tũ.'),
('kam', 'JUD', 1, 4, 'Nũndũ kwĩ andũ amwe melikĩtye na kĩmbithĩ, andũ ala maandĩkĩwe tene ũsilĩlo ũũ, Andũ matamũkĩaa Ngai, makĩalyũla mumo wa Ngai waitũ wĩthĩwe ũthei wa kwĩka mĩmeo mĩthũku, na kũmũkaĩa Mwamũli na Mwĩaĩi waitũ, nĩwe ũmwe e weka, Yesũ Klĩsto.'),
('kam', 'JUD', 1, 5, 'Na yu nĩngwenda kũmũlilikan’ya, o na kau nĩmũminĩte kũmanya maũndũ onthe, ũndũ Mwĩaĩi wambie kũtangĩĩa andũ kũmaumya nthĩ ya Misili, na ĩtina nĩwamanangie ala mataaĩtĩkĩla.'),
('kam', 'JUD', 1, 6, 'Na alaĩka ala mataasũvĩa ũnene woo ene, ĩndĩ matiie ũtũo woo ũla wamaĩle, amekalilye me ove na mbĩngũ sya tene na tene kĩvindunĩ kũvika ũsilĩlo wa mũthenya ũla mũnene.'),
('kam', 'JUD', 1, 7, 'O tondũ Sotomo na Ngomola, na ndũa ila ingĩ syaĩ ndee, meenenganĩte ene, o ta asu, kwĩka ũlaalai, na kũatĩĩa maũndũ ma mwĩĩ matekawa, nĩmaumĩlilw’e methĩwe ngelekan’yo ya kũthĩna ũsilĩlonĩ wa mwaki wa tene na tene.'),
('kam', 'JUD', 1, 8, 'No ta ũu asu nao nĩmavukasya mwĩĩ na maũndũ me namo ta mekũota, mailea ũsumbĩko, na makĩumanga monene.'),
('kam', 'JUD', 1, 9, 'Ĩndĩ Mikaeli ũla mũlaĩka mũnene, yĩla wakandanĩe na ndevili na ũkananĩa nake ũndũ wa mwĩĩ wa Mose, ndaatata kũmũvinganĩsya ta kũmũuma, ĩndĩ aisye, Mwĩaĩi nakũkan’ye.'),
('kam', 'JUD', 1, 10, 'Ĩndĩ andũ aa nĩmaumaa maũndũ matesĩ: na maũndũ ala mamanyaa na ũĩ wa mwĩĩ, maũndũnĩ asu nĩmeyanangaa, o ta nyamũ ite na kĩlĩko.'),
('kam', 'JUD', 1, 11, 'Woo nĩ woo! Nũndũ nĩmaendie nzĩanĩ ya Kaini, na kũatĩĩa ĩvĩtyo ya Mbalaamu vate kwĩsiĩĩa ene nĩ kana mose ũtandĩthyo, nao maanangwa katĩ wa ngananĩo ya Kola.'),
('kam', 'JUD', 1, 12, 'Andũ asu nĩmo mavia matonekaa mbokanĩ syenyu sya wendo yĩla meũya vamwe nenyu, aĩthi meĩthasya ene vate w’ĩa; mĩumbĩ ĩte na manzĩ, ĩkĩtwawa nĩ iseve; nĩ mĩtĩ ĩvinda yĩla ya kwĩtĩkya matũ ĩte na ũsyao, yũmite kelĩ, ĩkũĩtwe na mĩi vyũ;'),
('kam', 'JUD', 1, 13, 'nĩ itulumo sya ũkanga ila itasiĩĩkaa, makyumya nthoni syoo ta ĩvuo; nao nĩ ndata ila syangangaa, na maiĩwe wiũ wa kĩvindu kũvika tene na tene.'),
('kam', 'JUD', 1, 14, 'Nake Enoko, ũla waĩ wa mũonza kũtala kuma Atamu, athanie, akyasya, Sisyai, Mwĩai nĩwokie vamwe na atheu make, nguthu ĩtatalĩka,'),
('kam', 'JUD', 1, 15, 'kũmasilĩla andũ onthe, na kũmaĩkĩĩthya onthe ala matamũkĩaa Ngai ũndũ wa meko moo onthe ma kũlea kũmũkĩaa Ngai ala meekie, na nũndũ wa ndeto syoo syonthe nyũmũ ila asu athe matamũkĩaa Ngai mamũneeneete.'),
('kam', 'JUD', 1, 16, 'Asu nĩo anyungunyĩsya, andũ ma kĩnyinginyi, maatĩĩaa mĩmeo yoo mĩthũku (na makanyw’a moo maneenaa maũndũ manene ma kwĩkathĩĩa), makĩmendeesya andũ ũndũ wa kũnengwa syĩndũ nĩmo.'),
('kam', 'JUD', 1, 17, 'Ĩndĩ inyw’ĩ, endwa, lilikanai ndeto ila syambie ũneenwa nĩ atũmwa ma Mwĩaĩi waitũ Yesũ Klĩsto;'),
('kam', 'JUD', 1, 18, 'nĩkwĩthĩwa mamwĩie atĩĩ, Ĩvinda ya mũminũkĩlyo kũkeethĩwa avũthya, makĩatĩĩa mĩmeo mĩthũku yoo ya kũlea kũmũkĩa Ngai.'),
('kam', 'JUD', 1, 19, 'Asu nĩo ala metilaa, andũ ma mwĩkalĩle wa kĩ‐mũndũ, mate na ũla Veva.'),
('kam', 'JUD', 1, 20, 'Ĩndĩ inyw’ĩ, endwa, mũkĩyaka ĩũlũ wa mũĩkĩĩo wenyu ũla mũtheu mũno, mũkĩvoya nthĩnĩ wa Veva Mũtheu,'),
('kam', 'JUD', 1, 21, 'ĩyĩkalyei ene wendonĩ wa Ngai, mũkyeteela tei wa Mwĩaĩi waitũ Yesũ Klĩsto kũvika thayũ ũtathela.'),
('kam', 'JUD', 1, 22, 'Mew’ĩei tei andũ amwe ala me na nzika;'),
('kam', 'JUD', 1, 23, 'na amwe matangĩĩei, mũkĩmavulya kũmaumya mwakinĩ, na angĩ mew’ĩei tei vamwe na w’ĩa; mũkĩmena o na ngũa ĩthũkĩtwe nĩ maũndũ ma mwĩĩ.'),
('kam', 'JUD', 1, 24, 'Na ĩndĩ kwa ũla ũtonya kũmũsũvĩa mũikalulutĩke, na kũmwia mbee wa ũtheu wake mũtisu mũte na ũndũ ũtaĩle na mwĩ na ũtanu mũthonoku,'),
('kam', 'JUD', 1, 25, 'we nĩwe Ngai weka Mũtangĩĩi waitũ, kwondũ wa Yesũ Klĩsto Mwĩaĩi waitũ, kwake kwĩthĩwe ndaĩa, na ũnene, na ũtonyi, na ũkũmũ, mbee wa tene w’onthe, na yu, na kũvika tene tene. Ameni.'),
('kam', 'REV', 1, 1, 'Ũvuan’yo wa Yesũ Klĩsto, ũla Ngai wamũnengie nĩ kana asyon’ye ngombo syake maũndũ ala matatĩa kwĩkĩka mĩtũkĩ; na atũma mũlaĩka wake amyon’ye ngombo yake Yoana;'),
('kam', 'REV', 1, 2, 'ũla wakũsĩĩe ndeto ya Ngai, na ũkũsĩ wa Yesũ Klĩsto, o na maũndũ onthe ala wonie.'),
('kam', 'REV', 1, 3, 'Nĩ mũathime ũla ũsomaa, na ala mew’aa ndeto sya wathani ũũ, na kũsũvĩa maũndũ ala maandĩkĩtwe vo: nũndũ ĩvinda nĩ ĩthengeeu.'),
('kam', 'REV', 1, 4, 'Yoana, valũa wakwa ũmavikĩe makanisa asu mũonza ale me nthĩ ya Asia: Mumo nĩwĩthĩwe nenyu na mũuo, kuma kwa ũla wĩ vo na ũla waĩ vo na ũla ũkoka; na kuma kwa ala Maveva mũonza ala me mbee wa kĩvĩla kya ũsumbĩ kyake;'),
('kam', 'REV', 1, 5, 'na kuma kwa Yesũ Klĩsto, ngũsĩ yĩ kĩthito, na mũsyawa wa mbee wa akw’ũ, na mũnene wa asumbĩ ma nthĩ. Kwa ũsu ũtwendete, na kũtũthasya na nthakame yake tume naĩnĩ sitũ;'),
('kam', 'REV', 1, 6, 'na atũtwie ũsumbĩ, twĩthĩwe athembi ma Ngai, Ĩthe wake; ndaĩa na ũtonyi nĩ syake kũvika tene na tene. Ameni.'),
('kam', 'REV', 1, 7, 'Sisyai, nĩwũkĩte na mathweo; na kĩla itho yĩkamwona, na ala mamũtonyie; na mbaĩ syonthe sya nthĩ ikaĩa kwondũ wake. Ĩĩ, Ameni.'),
('kam', 'REV', 1, 8, 'Nyie nĩ Aliva na Omeka, mwambĩlĩlyo na mũminũkĩlyo, easya ũu Mwĩaĩi Ngai, ũla wĩ vo na ũla waĩ vo na ũla ũkoka, Mwene Vinya W’onthe.'),
('kam', 'REV', 1, 9, 'Nyie Yoana, mwana‐a‐ĩthe wenyu na mwosi ũmwe nenyu wa mathĩna na ũsumbĩ na wũmĩĩsyo ala me nthĩnĩ wa Yesũ, naĩ kĩthamanĩ kĩtawa Vatimo, nũndũ wa ndeto ya Ngai na ũkũsĩ wa Yesũ.'),
('kam', 'REV', 1, 10, 'Naĩ nthĩnĩ wa Veva mũthenya wa Mwĩaĩi, na neew’a wasya mũnene ĩtina wakwa, ta wa soo,'),
('kam', 'REV', 1, 11, 'ũkyasya, Ũla ũkwona, andĩka ĩvukunĩ noĩmatwaĩa ala makanisa mũonza ala me nthĩ ya Asia: Eveso, na Simulina, na Velikamo, na Thiatila, na Salite, na Vilatelivia, na Laotisia.'),
('kam', 'REV', 1, 12, 'Na neethyũũa none wasya ũla waneena nakwa. Na neethyũũa noona syĩndũ mũonza sya thaavu ila syĩkĩawa mataa;'),
('kam', 'REV', 1, 13, 'na katĩ wa syĩndũ isu noona ũmwe ũilyĩ mwana wa mũndũ, ekĩĩte ngũa ĩvikĩte maũũnĩ make, na eevotoele ndavũ ya thaavu nondonĩ.'),
('kam', 'REV', 1, 14, 'Na mũtwe wake na nzw’ĩĩ syake syaĩ nzaũ ta w’ĩa mweũ wa ilondu, nzaũ ta ĩa; na metho make mailyĩ ũmũĩ wa mwaki;'),
('kam', 'REV', 1, 15, 'na nyaĩĩ syake syailyĩ ũthuku mũkute mũno ta ũtheew’e ikonĩ ĩnene yĩ mwaki; na wasya wake waĩ ta wasya wa iw’ũ nyingĩ.'),
('kam', 'REV', 1, 16, 'Nake aĩ na ndata mũonza kw’okonĩ kwake kwa aũme: na ũvyũ mũĩ ngalĩ syelĩ wauma kanyw’anĩ wake: na ũthyũ wake wailyĩ syũa yĩkĩtisa na vinya wayo.'),
('kam', 'REV', 1, 17, 'Na namwona, navalũka maũũnĩ make ta ũmwe mũkw’ũ. Nake ambilĩĩla kw’oko kwake kwa aũme, akyasya, Ndũkakĩe; ninyie mwambĩlĩlyo na mũminũkĩlyo,'),
('kam', 'REV', 1, 18, 'na nĩ Ũla wĩ thayũ; nakwa naĩ mũkw’ũ, na sisya, nĩ thayũ kũvika tene na tene, na nĩ na mbungũo sya kĩkw’ũ na sya vala maveva ma akw’ũ mekalaa.'),
('kam', 'REV', 1, 19, 'Andĩka ĩndĩ maũndũ ala wonie, na ala me vo, na maũndũ ala makekĩka ĩtina;'),
('kam', 'REV', 1, 20, 'na nzama ya ndata mũonza ila wonie kw’okonĩ kwakwa kwa aũme, na syĩndũ mũonza sya thaavu syĩkĩawa mataa. Ndata isu mũonza nĩ alaĩka ma ala makanisa mũonza: na ila syĩndũ mũonza nĩ makanisa mũonza.'),
('kam', 'REV', 2, 1, 'Mũandĩkĩe mũlaĩka wa ĩkanisa yĩla yĩ Eveso atĩĩ: Maũndũ aa easya ũla ũkwataa ila ndata mũonza kw’okonĩ kwake kwa aũme, ũla ũendaa katĩ wa ila syĩndũ mũonza sya thaavu syĩkĩawa mataa:'),
('kam', 'REV', 2, 2, 'Nĩnĩmesĩ mawĩa maku, na thĩna wa wĩa waku, na wũmĩĩsyo waku, na kana ndũtonya kũmĩanĩsya na andũ athũku, na ĩngĩ nũmatatĩte asu mekwĩyĩta atũmwa, na ti w’o, na wamonie me akengani;'),
('kam', 'REV', 2, 3, 'nĩweelũlũmĩlye na nĩwũmĩĩsye kwondũ wa syĩtwa yakwa, na ndwaanoa.'),
('kam', 'REV', 2, 4, 'Ĩndĩ nĩ na ũndũ naku, nũndũ nũtiĩte wendo waku wa mbee.'),
('kam', 'REV', 2, 5, 'Lilikana ĩndĩ vala waumie ũkĩvalũka, na alyũla ngoo na ĩka mawĩa ala ma mbee; kana ethĩwa ndũkwĩka ũu ngooka kwaku, na ngaveta kĩndũ kyaku kya taa vandũ vakyo, walea kũalyũla ngoo.'),
('kam', 'REV', 2, 6, 'Ĩndĩ ũndũ ũũ wĩ naw’o, atĩ ũmenaa mawĩa ma Anikolai, ala nĩmenaa nakwa.'),
('kam', 'REV', 2, 7, 'Ũla wĩ na kũtũ, nĩew’e ũndũ Veva ũnũũtavya makanisa. Ũla ũkĩlasya, ngamũnenga we aye ũsyao wa mũtĩ wa thayũ, ũla wĩ mũũndanĩ wa Ngai.'),
('kam', 'REV', 2, 8, 'Na mũandĩkĩe mũlaĩka wa ĩkanisa yĩla yĩ Simulina atĩĩ: Maũndũ aa easya ũla wa mbee na ũla wa mũminũkĩlyo, ũla waĩ mũkw’ũ, na eethĩwa thayũ ĩngĩ:'),
('kam', 'REV', 2, 9, 'Nĩnĩsĩ ũnyamao waku, na ũkya waku (ĩndĩ wĩ mũthwii), na nĩnĩsĩ kũumana kwa asu meyĩtaa Ayuti, na ti w’o, ĩndĩ nĩ ĩsinakoke ya Satani.'),
('kam', 'REV', 2, 10, 'Ndũkakĩe maũndũ ala ũkilĩlye kũthĩnw’a nĩmo: sisya, ndevili nũkilĩlye kwĩkya amwe ma inyw’ĩ kolokolonĩ, nĩ kana mũtatwe; nenyu mũkeethĩwa na ũnyamao matukũ ĩkũmi. Ĩthĩwa wĩ na kĩthito kũvikĩa kĩkw’ũ, nakwa ngakũnenga ngovia ya ũsumbĩ ya thayũ.'),
('kam', 'REV', 2, 11, 'Ũla wĩ na kũtũ, nĩew’e ũndũ Veva ũnũũtavya makanisa. Ũla ũkĩlasya ndakakwatwa nĩ woo wa kĩkw’ũ kya kelĩ.'),
('kam', 'REV', 2, 12, 'Na mũandĩkĩe mũlaĩka wa ĩkanisa yĩla yĩ Velikamo atĩĩ: Maũndũ aa easya ũla wĩ na ũvyũ mũĩ ngalĩ syelĩ:'),
('kam', 'REV', 2, 13, 'Nĩnĩsĩ vala ũtwĩe, navo nĩ vala ve kĩvĩla kya ũsumbĩ kya Satani: naku ũyĩkwete mũno syĩtwa yakwa, o na ndwaakaĩa mũĩkĩĩo wakwa, o na ĩvinda ya Andiva ngũsĩ yakwa yĩ kĩthito, ũla woaĩwe kwenyu, vala Satani ũtwĩe.'),
('kam', 'REV', 2, 14, 'Ĩndĩ nĩ na maũndũ mavũthũ naku, nũndũ wĩ na amwe vu ala makwataa momanyĩsyo ma Mbalaamu, ũla wamũmanyĩsye Mbalaki kwĩkya ũlulutĩkyo mbee wa ana ma Isilaeli, nĩ kana maye syĩndũ ila syathembewe mĩvw’anano, na kũlaalaa.'),
('kam', 'REV', 2, 15, 'O ta ũu naku wĩ na andũ amwe ala makwataa momanyĩsyo ma Anikolai.'),
('kam', 'REV', 2, 16, 'Alyũla ngoo ĩndĩ; ethĩwa ndũkwĩka ũu ngooka kwaku mĩtũkĩ, na ngakwatya kaũ nao na ũvyũ wa kanyw’a wakwa.'),
('kam', 'REV', 2, 17, 'Ũla wĩ na kũtũ, nĩew’e ũndũ Veva ũnũũtavya makanisa. Ũla ũkĩlasya, ngamũnenga kũya lĩu wĩtawa mana ũla mũvithe, na ngamũnenga ĩvia yeũ, na ĩũlũ wa ĩvia yĩu vaandĩkĩtwe syĩtwa yeũ, yĩtesĩkĩwe nĩ mũndũ ate o ũla ũnũũyosa.'),
('kam', 'REV', 2, 18, 'Na mũandĩkĩe mũlaĩka wa ĩkanisa yĩla yĩ Thiatila atĩĩ: Maũndũ aa easya Mwana wa Ngai, ũla wĩ na metho mailyĩ ũmũĩ wa mwaki, na nyaĩĩ syake itilyĩ ũthuku mũkute mũno:'),
('kam', 'REV', 2, 19, 'Nĩnĩsĩ mawĩa maku, na wendo waku na mũĩkĩĩo na ũthũkũmi na wũmĩĩsyo, na kana mawĩa maku ma mũminũkĩlyo nĩmathonokete ala ma mbee.'),
('kam', 'REV', 2, 20, 'Ĩndĩ nĩ na ũndũ naku, atĩ nũmwĩtĩkĩlaa ũla mũndũ mũka Yeseveli, ũla wĩyĩtaa mwathani; na amanyĩasya na kwasya ngombo syakwa kana ilaalae, na kũya syĩndũ ithembeawa mĩvw’anano.'),
('kam', 'REV', 2, 21, 'Nakwa namũnengie ĩvinda kana alyũle ngoo; nake ndekwenda kwĩalyũla na kũeka ũlaalai wake.'),
('kam', 'REV', 2, 22, 'Sisya, nĩmwĩkya ũkomonĩ, na asu mekaa ũlaalai nake ũnyamaonĩ mũnene, ethĩwa maikwĩalyũla na kũeka mawĩa make.'),
('kam', 'REV', 2, 23, 'Nakwa ngooaa syana syake na kĩkw’ũ; na makanisa onthe makamanya kana ninyie nĩoasya malilikano na ngoo: na ngamũnenga kĩla mũndũ wa kwenyu kwĩanana na mawĩa menyu.'),
('kam', 'REV', 2, 24, 'Ĩndĩ nĩmũtavya inyw’ĩ ala mũtiele Thiatila, o ũndũ mwĩana ala mũte na ũmanyĩsyo ũsu, ala mũtesĩ maũndũ maliku ma Satani, o tondũ mekwasya; Nyie ndiũmwilĩĩla mũio ũngĩ.'),
('kam', 'REV', 2, 25, 'Ĩndĩ ũla mwĩ naw’o, lũmyai mũvaka yĩla nĩũka.'),
('kam', 'REV', 2, 26, 'Na ũla ũkĩlasya, na we ũla ũsũvĩaa mawĩa makwa kũvĩka mũminũkĩlyo, ngamũnenga ũsu ũkũmũ ĩũlũ wa Andũ‐ma‐mbaĩ‐ingĩ:'),
('kam', 'REV', 2, 27, 'nake akasumbĩka ĩũlũ woo na ndata ya kĩaa, ta mĩio ya mũmbi yanangawa vyũ; otondũ nyie nakwa noosie kwa Asa wakwa:'),
('kam', 'REV', 2, 28, 'na ngamũnenga ĩla ndata ya kĩoko.'),
('kam', 'REV', 2, 29, 'Ũla wĩ na kũtũ, nĩew’e ũndũ Veva ũnũũtavya makanisa.'),
('kam', 'REV', 3, 1, 'Na mũandĩkĩe mũlaĩka wa ĩkanisa yĩla yĩ Salite atĩĩ: Maũndũ aa easya ũla wĩ na Maveva mũonza ma Ngai na ila ndata mũonza: Nĩnĩsĩ mawĩa maku, kana wĩ na syĩtwa ya kwĩthĩwa thayũ, na wĩ mũkw’ũ.'),
('kam', 'REV', 3, 2, 'Ĩthĩwa ũisyaĩĩsya, noimalũlũmĩlya maũndũ ala matiele, ala makilyĩ ũkw’a: nĩkwĩthĩwa ndyaaona mawĩa maku meanĩe mbee wa Ngai wakwa.'),
('kam', 'REV', 3, 3, 'Lilikana ĩndĩ ũndũ wosete na ũndũ wĩw’ĩte; noisũvĩa, na kũalyũla ngoo. Ethĩwa ĩndĩ ndũkasyaĩĩsya, ngooka ta kĩng’ei, na ndũkamanya saa ũla nĩũka kwaku.'),
('kam', 'REV', 3, 4, 'Ĩndĩ wĩ na masyĩtwa amwe mavũthũ ku Salite ala mataavukya ngũa syoo: nao makaendanasya nakwa mekĩĩte ngũa nzaũ; nũndũ nĩmaĩle.'),
('kam', 'REV', 3, 5, 'Ũla ũkĩlasya, o ta ũu akavw’ĩkwa ngũa nzaũ; na ndikananga nongi syĩtwa yake ĩvukunĩ ya thayũ, na ngayumbũla syĩtwa yake mbee wa Asa wakwa, na mbee wa alaĩka make.'),
('kam', 'REV', 3, 6, 'Ũla wĩ na kũtũ, nĩew’e ũndũ Veva ũnũũtavya makanisa.'),
('kam', 'REV', 3, 7, 'Na mũandĩkĩe mũlaĩka wa ĩkanisa yĩla yĩ Vilatelivĩa atĩĩ: Maũndũ aa easya ũla mũtheu, na ũla wa w’o, ũla wĩ na ũvungũo wa Ndaviti, ũla ũvingũaa na kũi ũvinga, na ũla ũvingaa na kũi ũvingũa:'),
('kam', 'REV', 3, 8, 'Nĩnĩsĩ mawĩa maku (sisya, nĩnaia mbee waku mũomo mũvingũe, naw’o kũi ũtonya kũvinga), nĩnĩsĩ kana wĩ na vinya mũnini, naku nĩwasũvĩie ndeto yakwa, na ndwaayĩkaĩa syĩtwa yakwa.'),
('kam', 'REV', 3, 9, 'Sisya, nĩmanengane ala ma ĩsinakoke ya Satani, ala maasya nĩ Ayuti, na ti w’o, ĩndĩ meneena ũvũngũ; sisya, ngatuma moka mathaithe mbee wa maũũ maku, na kũmanya kana nyie nĩngwendete.'),
('kam', 'REV', 3, 10, 'Nĩkwĩthĩwa nĩwasũvĩie ndeto ya wũmĩĩsyo wakwa, nakwa ngakũsũvĩa wume ĩvindanĩ yĩu ya ũtatwa, yĩla yĩũka nthĩ yonthe, kũmatata ala matwĩe nthĩ.'),
('kam', 'REV', 3, 11, 'Ngooka mĩtũkĩ: lũmya ũla wĩ naw’o, nĩ kana mũndũ o na wĩva ndakose ngovia yaku ya ũsumbĩ.'),
('kam', 'REV', 3, 12, 'Ũla ũkĩlasya, ngamũtw’a kĩtuĩ ĩkalũnĩ ya Ngai wakwa, na ndakaumaala ĩngĩ nongi: na ngaandĩka ĩũlũ wake syĩtwa ya Ngai wakwa, na syĩtwa ya mũsyĩ wa Ngai wakwa, ũla Yelusaleme mweũ, ũla ũtheeaa kuma ĩtunĩ kwa Ngai wakwa, na ngaandĩka ĩũlũ wake syĩtwa yakwa mwene yĩla yeũ.'),
('kam', 'REV', 3, 13, 'Ũla wĩ na kũtũ, nĩew’e ũndũ Veva ũnũũtavya makanisa.'),
('kam', 'REV', 3, 14, 'Na mũandĩkĩe mũlaĩka wa ĩkanisa yĩla yĩ Laotisia atĩĩ: Maũndũ aa easya ũla Ameni, ngũsĩ yĩ kĩthito na ya w’o, mwambĩlĩlya wa wũmbi wa Ngai:'),
('kam', 'REV', 3, 15, 'Nĩnĩsĩ mawĩa maku, kana ndwĩ mũthithu o na ndwĩ mũvyũ: nĩenda wĩthĩwe wĩ mũthithu kana wĩ mũvyũ.'),
('kam', 'REV', 3, 16, 'Na ĩndĩ nĩkwĩthĩwa wĩ kamulutĩla, o na ndwĩ mũvyũ na ndwĩ mũthithu, ngaũtwĩla wume kanyw’anĩ wakwa.'),
('kam', 'REV', 3, 17, 'Nũndũ, wĩasya, Nyie nĩ mũthwii, na nĩnĩthuĩtye, na ndi vata wa kĩndũ; na ndwĩsĩ kana we wĩ mũnyamai na mwonzu na ngya na kĩlilinda na mũthei:'),
('kam', 'REV', 3, 18, 'nĩngũũtaa kana ũthooe kwakwa thaavu ũla ũtheetw’e na mwaki, nĩ kana ũtonye ũtw’ĩka mũthwii; na ngũa nzaũ, nĩ kana ũtonye kwĩvw’ĩka, nthoni syaku sya kwĩthĩwa mũthei itikoneke; na mũti wa metho wa ũvaka metho maku, nĩ kana ũtonye kwona.'),
('kam', 'REV', 3, 19, 'O asu ala nĩmendaa, nĩnĩmakanasya na kũmakũna: ĩthĩwa na ũthangaau ĩndĩ, noialyũla ngoo,'),
('kam', 'REV', 3, 20, 'Sisya, nĩũngeme mũomonĩ na kũvingũsya: ethĩwa mũndũ o na wĩva akeew’a wasya wakwa na kũmbingũĩa mũomo, ngalika kwake, na ngaĩsanĩa nake, nake akaĩsanĩa nakwa.'),
('kam', 'REV', 3, 21, 'Ũla ũkĩlasya, ngamũnenga kwĩkala vamwe nakwa kĩvĩlanĩ kyakwa kya ũsumbĩ, o ũndũ nakwa nakĩlilye, na kwĩkala vamwe na Asa wakwa kĩvĩlanĩ kyake kya ũsumbĩ.'),
('kam', 'REV', 3, 22, 'Ũla wĩ na kũtũ, nĩew’e ũndũ Veva ũnũũtavya makanisa.'),
('kam', 'REV', 4, 1, 'Ĩtina wa maũndũ aa nĩnoonie, na sisya, mũomo ũvingũkĩte ĩtunĩ, na wasya wa mbee ũla neewie, ta wasya wa soo ũineena nakwa, ũmwe akyasya, Ambata kũũ, nakwa ngakwon’ya maũndũ ala mate ndĩi kwĩkĩka ĩtina.'),
('kam', 'REV', 4, 2, 'Na oyu naĩ nthĩnĩ wa Veva: na sisya, kwaĩ kĩvĩla kya ũsumbĩ kiĩtwe ĩtunĩ, na ũmwe ekalile kĩla kĩvĩla;'),
('kam', 'REV', 4, 3, 'na ũla wakĩkalĩle, ũkĩmũsisya ailyĩ kavila ka yasivi na ka salitũ; na kwaĩ ũtaathi ũthyũlũlũkĩte kĩvĩla kyu, ũisisya ũilyĩ kavila ka sumalatai.'),
('kam', 'REV', 4, 4, 'Na kwaĩ ivĩla sya ũsumbĩ mĩongo ĩlĩ na inya ithyũlũlũkĩte kĩla kĩvĩla kya ũsumbĩ: na ivĩlanĩ isu nĩnoonie atumĩa mĩongo ĩlĩ na ana masyĩkalĩle, mekĩe ngũa nzaũ; na mĩtwenĩ yoo kwaĩ ngovia sya ũsumbĩ sya thaavu.'),
('kam', 'REV', 4, 5, 'Na kĩvĩlanĩ kyu kwauma motisi na mawasya na itundumo. Na kwaĩ mataa mũonza ma mwaki makanĩte mbee wa kĩvĩla kyu kya ũsumbĩ, nao nĩ ala Maveva mũonza ma Ngai;'),
('kam', 'REV', 4, 6, 'na mbee wa kĩvĩla, kwaĩ kĩndũ kĩilyĩ ũkanga wa kĩsisyo kĩtisu; na kĩvĩlanĩ kyu katĩ, na kũthyũlũlũka kĩvĩla, kwaĩ syũmbe inya syĩ thayũ syusĩe metho mbee na ĩtina.'),
('kam', 'REV', 4, 7, 'Na kyũmbe kya mbee kyailyĩ mũnyambũ, na kya kelĩ ta kasaũ, na kya katatũ kyaĩ na ũthyũ ta wa mũndũ, na kĩla kya kana kyailyĩ ndiũ ĩũlũkĩte.'),
('kam', 'REV', 4, 8, 'Na syũmbe isu inya syĩ thayũ, kĩla kĩmwe kyethĩwa na nthwau thanthatũ, syusũĩte metho ndee syonthe na nthĩnĩ; nasyo itithũmũaa mũthenya na ũtukũ, ikyasya, Mũtheu, mũtheu, mũtheu, nĩ Mwĩaĩi Ngai, Mwene Vinya W’onthe, ũla waĩ vo, na ũla wĩ vo, na ũla wĩũka.'),
('kam', 'REV', 4, 9, 'Na yĩla ila syũmbe syĩ thayũ syĩmũnenga ndaĩa na nguma na mũvea ũla wĩkalaa kĩvĩlanĩ kya ũsumbĩ, ũla wĩ thayũ kũvika tene na tene,'),
('kam', 'REV', 4, 10, 'ala atũmĩa mĩongo ĩlĩ na ana makavalũka mbee wa ũla wĩkalĩte kĩvĩlanĩ kya ũsumbĩ, na makamũthaitha ũla wĩ thayũ kũvika tene na tene, na makekya ngovia syoo sya ũsumbĩ mbee wa kĩvĩla kya ũsumbĩ, makyasya,'),
('kam', 'REV', 4, 11, 'Nĩwaĩle we, Mwĩaĩi waitũ na Ngai waitũ, kwosa ndaĩa na nguma na vinya: nĩkwĩthĩwa nĩwoombie syĩndũ syonthe, na kwondũ wa kwenda kwaku syaĩ kw’o, na ĩngĩ syoombwa.'),
('kam', 'REV', 5, 1, 'Na nĩnoonie kw’okonĩ kwa aũme kwa ũla wekalĩte kĩvĩlanĩ kya ũsumbĩ ĩvuku yĩandĩkĩtwe nthĩnĩ na ngalĩ ya ĩũlũ, yĩsiĩlĩtwe vyũ na masiĩlo mũonza.'),
('kam', 'REV', 5, 2, 'Na noona mũlaĩka wĩ na vinya aitavan’ya na wasya mũnene, Nũũ ũla waĩle kũvuũa ĩvuku, na kũmbũa mosiĩlo mayo?'),
('kam', 'REV', 5, 3, 'Na vaiaĩ mũndũ ũmwe o na wĩva ĩtunĩ, kana nthĩ, kana ungu wa nthĩ, waĩ atonya kũvũua ĩvuku yĩu, kana kũyĩsisya.'),
('kam', 'REV', 5, 4, 'Nakwa naĩa mũno, nĩkwĩthĩwa kũaiaaoneka ũmwe waĩlĩte kũvuũa ĩvuku yĩu, kana kũyĩsisya:'),
('kam', 'REV', 5, 5, 'na ũmwe wa atumĩa ambĩa, Ndũkaĩe; sisya, Mũnyambũ ũla wa mbaĩ ya Yuta, Kĩtina kya Ndaviti, nũkĩlĩtye atonye kũvuũa yĩla ĩvuku na kumbũa mosiĩlo mũonza mayo.'),
('kam', 'REV', 5, 6, 'Na noona katĩ wa kĩvĩla kyu kya ũsumbĩ na ila syũmbe inya syĩ thayũ, na katĩ wa ala atumĩa, Katena ka ĩlondu kaũngeme, kailyĩ ta koaĩtwe, ke na mbya mũonza, na metho mũonza, nao nĩ ala Maveva mũonza ma Ngai, ala matũmĩtwe mathi nthĩ yonthe.'),
('kam', 'REV', 5, 7, 'Nake ooka, na oosa yĩla ĩvuku kw’okonĩ kwa aũme kwa ũla wekalĩte kĩvĩlanĩ kya ũsumbĩ.'),
('kam', 'REV', 5, 8, 'Na oosa yĩla ĩvuku, ila syũmbe inya syĩ thayũ na ala atumĩa mĩongo ĩlĩ na ana mavalũka mbee wa kala Katena, na kĩla ũmwe woo aĩ na mbeve, na mbakũli sya thaavu syusũĩte ũvani, naw’o nĩ mboya sya ala atheu.'),
('kam', 'REV', 5, 9, 'Nao meina wathi weũ, makyasya, Nĩwaĩle we kwosa yĩla ĩvuku, na kũmbũa mosiĩlo mayo: nĩkwĩthĩwa nĩwooaiwe, na kũmũthooea Ngai na nthakame yaku andũ ma kĩla mbaĩ, na kĩthyomo, na ũko, na mĩthemba,'),
('kam', 'REV', 5, 10, 'na wamatwie ũsumbĩ na athembi kwa Ngai waitũ; nao nĩmasumbĩkĩte nthĩ.'),
('kam', 'REV', 5, 11, 'Nakwa noona, na neew’a wasya wa alaĩka aingĩ ndee syonthe sya kĩvĩla kyu kya ũsumbĩ na sya ila syũmbe syĩ thayũ na sya ala atumĩa; na ũtalo wamo waĩ ngili ĩkũmi kũndũ ngili ĩkũmi, na ngili kũndũ ngili;'),
('kam', 'REV', 5, 12, 'makyasya na wasya mũnene, Katena kala kooaiwe nĩwaĩle kwosa vinya, na ũthwii, na ũĩ, na ũtonyi, na nguma, na ndaĩa, na ũathimo.'),
('kam', 'REV', 5, 13, 'Na kĩla kyoombiwe kyonthe kĩla kĩ ĩtunĩ, na kĩla kĩ nthĩ, na kĩla kĩ ungu wa nthĩ, na kĩla kĩ ũkanganĩ ĩũlũ, na syĩndũ syonthe ila syĩ nthĩnĩ wasyo, neewie ikyasya, Ũathimo, na nguma, na ndaĩa, na ũtonyi, nĩ sya ũla wĩkalĩte kĩvĩlanĩ kya ũsumbi, na wa Katena, kũvika tene na tene.'),
('kam', 'REV', 5, 14, 'Na ila syũmbe inya syĩ thayũ syasya, Ameni. Na ala atumĩa mavalũka nthĩ, mathaitha.'),
('kam', 'REV', 6, 1, 'Na noona Katena akyũmbũa ũmwe wa ala mosiĩlo mũonza, na neew’a kĩmwe kya ila syũmbe inya syĩ thayũ kĩkyasya na wasya ta wa kĩtundumo, Ũka.'),
('kam', 'REV', 6, 2, 'Na noona, na sisya, mbalasi nzaũ, na ũla ũmĩtũlĩte aĩ na ũta; na anengwa ngovia ya ũsumbĩ: na aumaala aikĩlan’ya, na nĩ kana akĩlan’ye.'),
('kam', 'REV', 6, 3, 'Na oombũa ũsiĩlo wa kelĩ, neew’a kyũmbe kya kelĩ kĩla kĩ thayũ kĩkyasya, Ũka.'),
('kam', 'REV', 6, 4, 'Na mbalasi ĩngĩ ndune yaumaala: na ũla ũmĩtũlĩte anengwa kũveta mũuo kũũ nthĩ, nĩ kana moaane ene kwa ene: na anengwa ũvyũ mũnene.'),
('kam', 'REV', 6, 5, 'Na oombũa ũsiĩlo wa katatũ, neew’a kyũmbe kya katatũ kĩla kĩ thayũ kĩkyasya Ũka. Na noona, na sisya, mbalasi nziũ; na ũla ũmĩtũlĩte aĩ na kĩthimi kw’okonĩ kwake.'),
('kam', 'REV', 6, 6, 'Na neew’a ta wasya katĩ wa ila syũmbe inya syĩ thayũ ũkyasya, Kĩvava kya nganũ nĩ silingi, na ivava itatũ sya mbaale nĩ silingi na mauta na mbinyu ndũkaithũkye.'),
('kam', 'REV', 6, 7, 'Na oombũa ũsiĩlo wa kana, neew’a wasya wa kyũmbe kya kana kĩ thayũ kĩkyasya, Ũka.'),
('kam', 'REV', 6, 8, 'Na noona, na sisya, mbalasi yĩ mũkũyũ: na ũla ũmĩtũlĩte, syĩtwa yake nĩ kĩkw’ũ; na vala maveva ma akw’ũ mekalaa vaatĩanĩa nake. Nao manengwa ũkũmũ ĩũlũ wa kĩlungu kya kana kya nthĩ, moae na ũvyũ, na yũa, na kĩkw’ũ, na nyamũ mbai sya nthĩ.'),
('kam', 'REV', 6, 9, 'Na oombũa ũsiĩlo wa katano, noona ungu wa kĩthembeo mathayũ ma ala mooaiwe kwondũ wa ndeto ya Ngai, na kwondũ wa ũkũsĩ ũla maĩ naw’o:'),
('kam', 'REV', 6, 10, 'nao manĩĩsya, makyasya, Nĩ kũvika ĩndĩĩ, ame Mwĩaĩĩ, ũla mũtheu na wa w’o, ũteũsila na kũĩvanĩsya nthakame yaitũ kwa ala matwĩe nthĩ?'),
('kam', 'REV', 6, 11, 'Nao manengwa kĩla ũmwe ngũa nzaũ ndasa; na matavw’a mathũmũange kavinda kanini, kũvika yĩla atethya ma wĩa vamwe nao na ana‐a‐asa moo, ala meũawa o ũndũ mo mooaiwe, methĩwe meanĩtye ũtalo woo.'),
('kam', 'REV', 6, 12, 'Na noona akyũmbũa ũsiĩlo wa thanthatũ, na kwaĩ kĩtetemo kĩnene kya nthĩ; na syũa yatw’ĩka yiũ ta ĩkunia ya w’ĩa, na mwei w’onthe watw’ĩka ta nthakame;'),
('kam', 'REV', 6, 13, 'na ndata sya ĩtunĩ syavalũka nthĩ, o tondũ kĩkũyũ kĩtĩkasya makũyũ makyo mate maviku yĩla kĩũthingithangw’a nĩ kĩseve kĩnene.'),
('kam', 'REV', 6, 14, 'Na ĩtu yavetwa ta ũa wa ũsomwa ũilingwa; na iĩma syonthe na ithama syonthe syaumw’a vandũ vasyo.'),
('kam', 'REV', 6, 15, 'Na asumbĩ ma nthĩ, na anene me mbee ũsumbĩnĩ, na anene ma asikalĩ ngili, na athwii, na ala me vinya, na ngombo syonthe na ala mate ngombo, meevitha ngunganĩ na mbainĩ sya iĩma;'),
('kam', 'REV', 6, 16, 'na maitavya iĩma na mbai, makyasya, Tũvalũkĩlei, na mũitũvitha ũthyũ wa ũla wĩkalĩte kĩvĩlanĩ kya ũsumbĩ, na ũthatu wa kala Katena:'),
('kam', 'REV', 6, 17, 'nũndũ mũthenya mũnene wa ũthatu woo nĩ mũku; na nũũ ũla ũtonya kũũngama?'),
('kam', 'REV', 7, 1, 'Ĩtina wa ũu nĩnoonie alaĩka ana maũngeme ikotonĩ inya sya nthĩ, makĩkwata iseve inya sya nthĩ, nĩ kana kĩseve kĩikauutane nthĩ, kana ũkanganĩ, kana mũtĩnĩ o na wĩva.'),
('kam', 'REV', 7, 2, 'Na noona mũlaĩka ũngĩ akyambata kuma wumĩlonĩ wa syũa, e na ũsiĩlo wa Ngai ũla wĩ thayũ: na anĩĩsya alaĩka asu ana ala manengetwe kũmĩthũkya nthĩ na ũkanga,'),
('kam', 'REV', 7, 3, 'akyasya, Mũikathũkye nthĩ, kana ũkanga, kana mĩtĩ, kũvika twamba ũsyĩkĩa ngombo sya Ngai waitũ, ũsiĩlo itulyanĩ syasyo.'),
('kam', 'REV', 7, 4, 'Na neew’a ũtalo wa ala meekĩĩtwe ũsiĩlo, ngĩlĩ ĩana na mĩongo ĩna na inya, ala meekĩĩtwe ũsiĩlo kuma mbaĩnĩ syonthe sya ana ma Isilaeli:'),
('kam', 'REV', 7, 5, 'Ma mbaĩ ya Yuta ngili ĩkũmi na ilĩ ala meekĩĩtwe ũsiĩlo; Ma mbaĩ ya Leuveni ngili ĩkũmĩ na ilĩ; Ma mbaĩ ya Ngati ngili ĩkũmi na ilĩ;'),
('kam', 'REV', 7, 6, 'Ma mbaĩ ya Aseli ngili ĩkũmi na ilĩ; Ma mbaĩ ya Navitali ngili ĩkũmĩ na ilĩ; Ma mbaĩ ya Manase ngili ĩkũmi na ilĩ;'),
('kam', 'REV', 7, 7, 'Ma mbaĩ ya Simeoni ngili ĩkũmi na ilĩ; Ma mbaĩ ya Livai ngili ĩkũmi na ilĩ; Ma mbaĩ ya Isakali ngili ĩkũmi na ilĩ;'),
('kam', 'REV', 7, 8, 'Ma mbaĩ ya Nzevuluni ngili ĩkũmi na ilĩ; Ma mbaĩ ya Yosevu ngili ĩkũmi na ilĩ; Ma mbaĩ ya Mbenyamini ngili ĩkũmi na ilĩ ala meekĩĩtwe ũsiĩlo.'),
('kam', 'REV', 7, 9, 'Ĩtĩna wa maũndũ asu noona, na sisya, ĩkomano ĩnene ya andũ, yĩla mũndũ o na wĩva ũtatonya ũyĩtalĩkya, kuma andũnĩ ma kĩla mũthemba na mbaĩ na ngo na ithyomo, maũngeme mbee wa kĩla kĩvĩla kya ũsumbĩ na mbee wa kala Katena, mekie ngũa nzaũ ndasa, na makuĩte makindũ na moko;'),
('kam', 'REV', 7, 10, 'na manĩĩsya, makyasya, Ũtangĩĩo nĩ wa, Ngai waitũ ũla wĩkalĩle kĩvĩla kya ũsumbĩ, na wa kala Katena.'),
('kam', 'REV', 7, 11, 'Na alaĩka onthe meethĩwa maũngeme ndee syonthe sya kĩvĩla kyu kya ũsumbĩ, na ndee sya ala atumĩa na sya ila syũmbe inya syĩ thayũ; na mavalũka mbee wa kĩvĩla kya ũsumbĩ na mothyũ, na mamũthaitha Ngai,'),
('kam', 'REV', 7, 12, 'makyasya, Amenĩ: Ũathimo, na ndaĩa, na ũĩ, na mũvea, na nguma, na vinya, na ũtonyĩ, nĩ ma Ngai waitũ, kũvika tene na tene. Ameni.'),
('kam', 'REV', 7, 13, 'Na ũmwe wa atumĩa asũngĩa, aimbĩa, Aa mekĩe ngũa nzaũ ndasa naaũ, na maumie va?'),
('kam', 'REV', 7, 14, 'Nakwa namwĩa, Vwana wakwa, we nĩwĩsĩ. Na ambĩa, Aa nĩo ala maumĩte thĩnanĩ ũla mũnene, na nĩmathambisye ngũa syoo, na maitw’ĩkĩthya nzaũ nthakamenĩ ya kala Katena.'),
('kam', 'REV', 7, 15, 'Kwondũ wa ũu me mbee wa kĩvĩla kya ũsumbĩ kya Ngai; na nĩmamũthũkũmaa mũthenya na ũtukũ ĩkalũnĩ yake: na ũla wĩkalĩle kĩvĩla kya ũsumbĩ akatambũũkya ĩeema yake ĩũlũ woo.'),
('kam', 'REV', 7, 16, 'Maikew’a nzaa ĩngĩ, o na maikew’a waũni ĩngĩ; o na syũa yĩikamavikĩa, kana ũvyũvu o na wĩva:'),
('kam', 'REV', 7, 17, 'nũndũ Katena ũla wĩ katĩ wa kĩvĩla kya ũsumbĩ akeethĩwa mũĩthi woo, na akamatongoesya na kũmavikya kũla kwĩ nthongo sya manzĩ ma thayũ: na Ngai akavyaĩa methoi onthe methonĩ moo.'),
('kam', 'REV', 8, 1, 'Na akyũmbũa ũsiĩlo wa mũonza, kwakilya ki ĩtunĩ ĩvinda ya nyunzu ya saa.'),
('kam', 'REV', 8, 2, 'Na noona alaĩka mũonza ala maũngamaa mbee wa Ngai; nao manengwa masoo mũonza.'),
('kam', 'REV', 8, 3, 'Na mũlaĩka ũngĩ aumĩla, na aũngama mbee wa kĩthembeo, akuĩte kĩtoeesya kya thaavu; na anengwa ũvani mwingĩ, nĩ kana awongele mboyanĩ sya atheu onthe ĩũlũ wa kĩthembeo kya thaavu kĩla kyaĩ mbee wa kĩvĩla kya ũsumbĩ.'),
('kam', 'REV', 8, 4, 'Na syũki ya ũla ũvani, vamwe na mboya sya atheu, syambata kwa Ngai kuma kw’okonĩ kwa mũlaĩka ũsu.'),
('kam', 'REV', 8, 5, 'Na mũlaĩka oosa kĩtoeesya; na akyusũsya mwaki wa kĩthembeo, na akĩkya nthĩ: na ĩtina kweethĩwa itundumo, na mawasya, na motisi, na kĩtetemo kya nthĩ.'),
('kam', 'REV', 8, 6, 'Na alaĩka asu mũonza ala maĩ na masoo mũonza meeyũmban’ya nĩ kana mavuve.'),
('kam', 'REV', 8, 7, 'Na ũla wa mbee avuva soo, na kweethĩwa mbua ya mavia na mwaki, ivulene na nthakame, nasyo syekw’a nthĩ: na kĩlungu kya katatũ kya nthĩ kyavya, na kĩlungu kya katatũ kya mĩtĩ kyavya, na nyeki syonthe nziũ syavya.'),
('kam', 'REV', 8, 8, 'Na mũlaĩka wa kelĩ avuva soo, na kweethĩwa kĩndũ kĩilyĩ kĩĩma kĩnene kyakene mwaki kyekw’a ũkanganĩ: na kĩlungu kya katatũ kya ũkanga kyatw’ĩka nthakame;'),
('kam', 'REV', 8, 9, 'na nyamũ syakw’a, kĩlungu kya katatũ kya ila syaĩ ũkanganĩ, o ila syaĩ thayũ; na kĩlungu kya katatũ kya ngalawa kyaanangĩka.'),
('kam', 'REV', 8, 10, 'Na mũlaĩka wa katatũ avuva soo, na ndata nene yavalũka kuma ĩtunĩ, yakene ta ũmũĩ, nayo yavalũkĩla kĩlungu kya katatũ kya mbũsĩ, na nthongo sya manzĩ;'),
('kam', 'REV', 8, 11, 'na syĩtwa ya ndata ĩsu nĩ Avisintho: na kĩlungu kya katatũ kya manzĩ kyeekĩwa ũũ; na andũ aingĩ makw’a nĩ manzĩ asu, nĩkwĩthĩwa maĩ na ũũ mũno.'),
('kam', 'REV', 8, 12, 'Na mũlaĩka wa kana avuva soo, na kĩlungu kya katatũ kya syũa kyakũnwa, na kĩlungu kya katatũ kya mwei, na kĩlungu kya katatũ kya ndata; nĩ kana kĩlungu kya katatũ kyasyo kĩkĩwe kĩvindu, na nĩ kana kũikethĩwe kyeni kĩlungu kya katatũ kya mũthenya, na ũtukũ no ta ũu.'),
('kam', 'REV', 8, 13, 'Na noona, na neew’a ndiũ ĩmwe, ĩkĩũlũka ĩtunĩ katĩ, ĩkyasya na wasya mũnene, Woo, woo, woo, kwa ala matwĩe nthĩ, nũndũ wa mawasya ala matiele ma masoo ma alaĩka atatũ, ala mevuva masoo ĩtina.'),
('kam', 'REV', 9, 1, 'Na mũlaĩka wa katano avuva soo, na noona ndata yumĩte ĩtunĩ ĩvalũkĩte nthĩ: nake anengwa ũvungũo wa yĩla ĩima yĩte kĩtulu.'),
('kam', 'REV', 9, 2, 'Na ayĩvingũa yĩla ĩima yĩte kĩtulu; na syũki yambata kuma ĩimanĩ, ta syũki ya iko ĩnene mũno; na syũa na yayaya syeekĩwa kĩvindu nũndũ wa syũki yĩu ya yĩla ĩima.'),
('kam', 'REV', 9, 3, 'Na ngie syauma syũkinĩ yĩu syathi ĩũlũ wa nthĩ; nasyo syanengwa ũkũmũ, o ta ing’auũ sya nthĩ syĩ ũkũmũ.'),
('kam', 'REV', 9, 4, 'Na syatavw’a itikathũkye nyeki sya nthĩ, kana kĩndũ kiũ o na kĩva, kana mũtĩ o na wĩva, ĩndĩ no andũ asu ala mate na ũsiĩlo wa Ngai itulyanĩ syoo.'),
('kam', 'REV', 9, 5, 'Na syatw’ĩĩwa itikamoae, ĩndĩ nĩ kana imathĩn’ye myei ĩtano: na kũthĩn’ya kwasyo kwaĩ ta kũthĩn’ya kwa kĩng’auũ kĩũmĩte mũndũ.'),
('kam', 'REV', 9, 6, 'Na mĩthenya ĩsu andũ makamantha kĩkw’ũ, na maikakyona nongi; na makenda kũkw’a, ĩndĩ kĩkw’ũ kĩkamakĩa.'),
('kam', 'REV', 9, 7, 'Na mũmbĩlwe wa ngie wailyĩ mbalasi iseũvĩw’e kaũ; na mĩtwenĩ yasyo kwaĩ ta ngovia sya ũsumbĩ iilyĩ thaavu, na mothyũ masyo mailyĩ mothyũ ma andũ.'),
('kam', 'REV', 9, 8, 'Na syaĩ na nzw’ĩĩ sya aka, na maeo masyo mailyĩ maeo ma mĩnyambũ.'),
('kam', 'REV', 9, 9, 'Na syaĩ na ngao ithũinĩ, ta ngao sya iaa, na kĩuumo kya nthwau syasyo kyaĩ ta kĩuumo kya ngalĩ, na mbalasi mbingĩ isembete kaũnĩ.'),
('kam', 'REV', 9, 10, 'Na syĩ na isithe ta ila sya ing’auũ, na moa; na vinya wa ũmew’ĩthya andũ woo myei ĩtano wĩ isithenĩ syasyo.'),
('kam', 'REV', 9, 11, 'Na syĩ na mũsumbĩ ĩũlũ wasyo, ũla mũlaĩka wa yĩla ĩima yĩte kĩtulu: syĩtwa yake Kĩevelania nĩ Avatoni, na Kĩkiliki nĩ Avolioni.'),
('kam', 'REV', 9, 12, 'Woo wa mbee nĩwavĩta: sisya, nĩmokĩte Mawoo angĩ elĩ ĩtina.'),
('kam', 'REV', 9, 13, 'Na mũlaĩka wa thanthatũ avuva soo, na neew’a wasya ũmwe wumĩte mbyanĩ sya kĩthembeo kya thaavu kĩla kĩ mbee wa Ngai,'),
('kam', 'REV', 9, 14, 'ũmwe aimwĩa mũlaĩka ũsu wa thanthatũ ũla waĩ na soo, akyasya, Thasya ala alaĩka ana ala movetwe ũsĩnĩ ũnene ũla wĩtawa Euvalati.'),
('kam', 'REV', 9, 15, 'Na alaĩka asu ana mathaw’a ala maseũvĩtw’e kwondũ wa saa na mũthenya na mwei na mwaka, nĩ kana moae kĩlungu kya katatũ kya andũ.'),
('kam', 'REV', 9, 16, 'Na ũtalo wa ita sya ala matũlĩte mbalasi wai ngili mĩongo ĩlĩ kũndũ ngili ĩkũmi: nĩneewie ũtalo woo.'),
('kam', 'REV', 9, 17, 'Na ta ũu noona mbalasi woninĩ, na ala maitũlĩte, me na ngao ithũinĩ iilyĩ ta sya mwaki na sya samawi na sya mũvĩlĩtĩ: na mĩtwe ya mbalasi ĩilyĩ ta mĩtwe ya mĩnyambũ; na makanyw’a masyo maumawa nĩ mwaki na syũki na mũvĩlĩtĩ.'),
('kam', 'REV', 9, 18, 'Kĩlungu kya katatũ kya andũ kyooaiwe na mothĩn’yo asu atatũ, mwaki na syũki na mũvĩlĩtĩ, ila syaumie makanyw’anĩ masyo.'),
('kam', 'REV', 9, 19, 'Nũndũ vinya wa mbalasi wĩ makanyw’anĩ masyo, na isithenĩ syasyo; nũndũ isithe iilyĩ nzoka, na syĩ na mĩtwe; na nĩsyĩw’ĩthasya woo nasyo.'),
('kam', 'REV', 9, 20, 'Na ala matialĩte ma andũ, ala mataaũawa nĩ mothĩn’yo asu, matyaalyũla ngoo ũndũ wa mawĩa ma moko moo, maikathaithe ndaimoni, na mivw’anano ya thaavu, na ya vetha, na ya ũthuku, na ya ĩvia, na ya mũtĩ; ĩla ĩtatonya kwona, o na kwĩw’a, o na kũkinya:'),
('kam', 'REV', 9, 21, 'o na matyaaĩalyũla ũndũ wa maũaani moo, kana ũndũ wa maũoi moo, kana ũndũ wa ũlaalai woo, kana ũndũ wa mong’ei moo.'),
('kam', 'REV', 10, 1, 'Na noona mũlaĩka ũngĩ wĩ na vinya aitheea kuma ĩtunĩ, evw’ĩkĩte ĩthweo; na ũtaathi waĩ mũtwenĩ wake, na ũthyũ wake wailyĩ syũa, na nyaĩĩ syake syailyĩ ituĩ sya mwaki;'),
('kam', 'REV', 10, 2, 'na kw’okonĩ kwake aĩ na kavuku kanini kavuan’ye: nake akinya na kũũ kwake kwa aũme ũkanganĩ, na kũla kwa aka akinya nthĩ;'),
('kam', 'REV', 10, 3, 'na akũthũka, o ũndũ mũnyambũ ũlumaa: na akũthũka, itundumo mũonza syaumya mawasya masyo.'),
('kam', 'REV', 10, 4, 'Na itundumo mũonza syaumya mawasya masyo, nakilĩlye kũandĩka: na neew’a wasya ũkyuma ĩtunĩ ũkyasya, Siĩla maũndũ asu maneenwa nĩ itundumo mũonza, na ndũkamaandĩke.'),
('kam', 'REV', 10, 5, 'Na mũlaĩka ũla noonie aũngeme ũkanganĩ na nthĩ ookĩlya kw’oko kwake kwa aũme elekelye ĩtunĩ,'),
('kam', 'REV', 10, 6, 'na eevĩta na ũla wĩ thayũ kũvika tene na tene, ũla wombie ĩtu na syĩndũ ila syĩ vo, na nthĩ na syĩndũ ila syĩ vo, na ũkanga na syĩndũ ila syĩ vo, kana kũikethĩwa kweteela ĩngĩ:'),
('kam', 'REV', 10, 7, 'ĩndĩ mĩthenya ya wasya wa mũlaĩka ũsu wa mũonza, o yĩla wĩvuva soo, nĩvo nzama ya Ngai ĩkeanĩw’a, kwĩanana na ũvoo mũseo ũla watavisye ngombo syake athani.'),
('kam', 'REV', 10, 8, 'Na wasya ũla neewie kuma ĩtunĩ, neew’a ũineena nakwa ĩngĩ, ũkyasya, Enda, wose ĩvuku yĩla ĩvuan’ye kw’okonĩ kwa mũlaĩka ũla ũũngeme ũkanganĩ na nthĩ.'),
('kam', 'REV', 10, 9, 'Nakwa naendie kwa mũlaĩka, namwĩa nanenge kala kavuku. Na ambĩa, Kose, ũkaye; na kakeekĩa ĩvu yaku ũũ, ĩndĩ kanyw’anĩ waku kakeethĩwa ke mũyo ta ũkĩ wa nzũkĩ.'),
('kam', 'REV', 10, 10, 'Na noosa kala kavuku kanini kw’okonĩ kwa mũlaĩka ũsu, nakaya; na kanyw’anĩ wakwa kaĩ mũyo ta ũkĩ wa nzũkĩ: na nakaya, ĩvu yakwa yeekĩwa ũũ.'),
('kam', 'REV', 10, 11, 'Nao mambĩa, Mũvaka wathane ĩngĩ ũndũ wa ngo nyingĩ sya andũ na mbaĩ na ithyomo na asumbĩ.'),
('kam', 'REV', 11, 1, 'Na nanengiwe mũangi ũilyĩ ndata: na ũmwe ambĩa, Ũkĩla, ũthime ĩkalũ ya Ngai, na kĩthembeo, na ala mathaithaa vo.'),
('kam', 'REV', 11, 2, 'Na nza ĩla yĩ ũtee wa ĩkalũ mĩtie ũtee, ndũkamĩthime; nĩkwĩthĩwa ĩnengetwe Andũ‐ma‐mbaĩ‐ingĩ; na makakinyanga ndũa ĩla ntheu myei mĩongo ĩna na ĩlĩ.'),
('kam', 'REV', 11, 3, 'Nakwa nganenga ngũsĩ syakwa ilĩ kwathana, na makathana mĩthenya ngili na maana elĩ na mĩongo thanthatũ, mevw’ĩkĩte ngũa sya makunia.'),
('kam', 'REV', 11, 4, 'Asu nĩo mĩthata ĩlĩ na nĩo ila syĩndũ ilĩ syĩkĩawa mataa ila iũngeme mbee wa Mwĩaĩi wa nthĩ.'),
('kam', 'REV', 11, 5, 'Na ethĩwa mũndũ o na wĩva nũnũkwenda kũmeka naĩ, mwaki nĩwumaa makanyw’anĩ moo, na ũimina amaitha moo; na ethĩwa mũndũ o na wĩva nũnũkwenda kũmeka naĩ, mũvaka oawe ũu.'),
('kam', 'REV', 11, 6, 'Asu me na ũkũmũ wa kũvinga ĩtu, mbua ndĩkaue mĩthenyanĩ ya wathani woo: na me na ũkũmũ ĩũlũ wa iw’ũ kwialyũla syĩthĩwe nthakame, na kũmĩkũna nthĩ na kĩla ũthĩn’yo, o ũndũ mekwanda.'),
('kam', 'REV', 11, 7, 'Na yĩla makethĩwa maminĩte ũkũsĩ woo, ĩla nyamũ yumaa ĩimanĩ yĩte kĩtulu ĩkakwatya kaũ nao, nayo ĩkamakĩlya vinya, na kũmoaa.'),
('kam', 'REV', 11, 8, 'Na simba syoo ikeethĩwa nzĩanĩ ya ndũa ĩsu nene, ĩla yĩtawa Sotomo na Misili mĩneenelenĩ ya veva, navo nĩ vala Mwĩaĩi woo wambiwe.'),
('kam', 'REV', 11, 9, 'Na ala maumaa katĩ wa ngo sya andũ na mbaĩ na ithyomo na mĩthemba ya andũ makasisya simba syoo mĩthenya ĩtatũ na nyunzu, na maiketĩkĩla simba syoo syĩnzĩwe nthĩ.'),
('kam', 'REV', 11, 10, 'Na ala matwĩe nthĩ makatana nũndũ woo, na kwĩw’a mũyo; na makatwaanĩa mĩthĩnzĩo ene kwa ene; nĩkwĩthĩwa athani asu elĩ nĩmanathĩnĩtye ala matwĩe nthĩ.'),
('kam', 'REV', 11, 11, 'Na ĩtina wa mĩthenya ĩsu ĩtatũ na nyunzu veva wa thayũ kuma kwa Ngai wamalika nthĩnĩ, na maũngama na maũũ moo; na w’ĩa mũnene wamakwata ala mamasyaasya.'),
('kam', 'REV', 11, 12, 'Nao meew’a wasya mũnene kuma ĩtunĩ ũkĩmea, Ambatai kũũ. Na mambata me ĩthweonĩ malika ĩtunĩ; na amaitha moo mamasyaĩĩsya.'),
('kam', 'REV', 11, 13, 'Na ĩvinda yĩu kwaĩ kĩtetemo kĩnene kya nthĩ, na kĩlungu kya ĩkũmi kya ĩla ndũa kyavalũka; na andũ ngili mũonza mooaiwe nĩ kĩtetemo kyu kya nthĩ: na ala matialile malikwa nĩ w’ĩa, na mamũtaĩa Ngai wa ĩtunĩ.'),
('kam', 'REV', 11, 14, 'Woo wa kelĩ nĩwavĩta: sisya, Woo wa katatũ nĩwũkĩte mĩtũkĩ.'),
('kam', 'REV', 11, 15, 'Na mũlaĩka wa mũonza avuva soo; na kweethĩwa mawasya manene ĩtunĩ, nao masya, Ũsumbĩ wa nthĩ nũtw’ĩkĩte ũsumbĩ wa Mwĩaĩi waitũ, na wa Klisto wake: nake akasumbĩka kũvika tene na tene.'),
('kam', 'REV', 11, 16, 'Na ala atumĩa mĩongo ĩlĩ na ana, ala mekalaa mbee wa Ngai ivĩlanĩ syoo sya ũsumbĩ, mavalũka na mothyũ moo na mamũthaitha Ngai,'),
('kam', 'REV', 11, 17, 'makyasya, Nĩtũũkũtũngĩa mũvea, we Mwĩaĩi Ngai, Mwene Vinya W’onthe, ũla wĩ vo, na ũla waĩ vo, nĩkwĩthĩwa nĩwosete vinya waku mũnene, na kũsumbĩka.'),
('kam', 'REV', 11, 18, 'Na mbaĩ syaĩ nthilĩku, na ũthilĩku waku wooka, na ĩvinda ya ũsilĩla akw’ũ, na ĩvinda ya kũnenga ĩtuvi ngombo syaku athani, na ala atheu, na ala makĩaa syĩtwa yaku, anini na anene; na kũmananga ala manangaa nthĩ.'),
('kam', 'REV', 11, 19, 'Na ĩkalũ ya Ngai yĩla yĩ ĩtunĩ yavingũwa; na kwooneka ĩkalũnĩ yake ĩsandũkũ ya ũtianĩo wake; na kweethĩwa motisi, na mawasya, na itundumo, na kĩtetemo kya nthĩ, na mbua nene ya mavia.'),
('kam', 'REV', 12, 1, 'Na kwooneka kyama kĩnene ĩtunĩ; mũndũ mũka evw’ĩkĩte syũa, na mwei waĩ ungu wa nyaĩĩ syake, na mũtwenĩ wake kwaĩ ngovia ya ũsumbĩ yĩ ndata ĩkũmi na ilĩ;'),
('kam', 'REV', 12, 2, 'nake aĩ ĩvu: na akaya, akyaũnya nĩ woo wa ũsyaa.'),
('kam', 'REV', 12, 3, 'Na kwooneka kyama kĩngĩ ĩtunĩ; na sisya, mũkũnga mũnene mũtune wĩ na mĩtwe mũonza na mbya ĩkũmi, na mĩtweni yaw’o ngovia sya ũsumbĩ mũonza.'),
('kam', 'REV', 12, 4, 'Na kĩsithe kyaw’o kyakusya kĩlungu kya katatũ kya ndata sya ĩtunĩ, na kyasyĩkya nthĩ: na mũkũnga ũsu mũnene waũngama mbee wa mũndũ mũka ũsu wakilĩlye ũsyaa, nĩ kana asyaa, ũtonye kũmelya kana kake.'),
('kam', 'REV', 12, 5, 'Nake asyaa mwana, mũndũ mũũme, ũla ũkasumbĩka mbaĩ syonthe na ndata ya kĩaa: na kana kake kavulw’a kũvika kwa Ngai, na kĩvĩlanĩ kyake kya ũsumbĩ.'),
('kam', 'REV', 12, 6, 'Na mũndũ mũka akĩa na athi weũnĩ, vandũ vala waseũvĩw’e nĩ Ngai, nĩ kana mamũĩthĩsye vo mĩthenya ngili na maana elĩ na mĩongo thanthatũ.'),
('kam', 'REV', 12, 7, 'Na kwaĩ kaũ ĩtunĩ: Mikaeli na alaĩka make maithi kũkita na ũla mũkũnga mũnene; na mũkũnga ũsu na alaĩka maw’o mokita;'),
('kam', 'REV', 12, 8, 'nao maiaakĩlya vinya, o na vaiaaoneka vandũ voo ĩtunĩ ĩngĩ.'),
('kam', 'REV', 12, 9, 'Na mũkũnga ũsu mũnene wekw’a nthĩ, naw’o nĩ nzoka ĩla ngũũ, yĩtawa Ndevili, na ĩngĩ Satani, mũkengani wa nthĩ yonthe; ekw’a nthĩ, na alaĩka make mekw’a nthĩ vamwe nake.'),
('kam', 'REV', 12, 10, 'Na neew’a wasya mũnene ĩtunĩ, ũkyasya, Yu ve ũtangĩĩo, na vinya, na ũsumbĩ wa Ngai waitũ, na ũkũmũ wa Klĩsto wake: nũndũ mũvinganĩsya wa ana‐a‐asa maitũ nĩwekw’a nthĩ, ũla ũmavinganĩasya mbee wa Ngai waitũ mũthenya na ũtukũ.'),
('kam', 'REV', 12, 11, 'Nao mamũkĩlya vinya nũndũ wa nthakame ya kala Katena ka ĩlondu na nũndũ wa ndeto ya ũkũsĩ woo; na matyaamenda mathayũ moo o na kũvika kĩkw’ũ.'),
('kam', 'REV', 12, 12, 'Kwondũ wa ũu tanai, inyw’ĩ matu, na inyw’ĩ ala mũtwĩe nthĩnĩ wamo. Woo nĩ wanthĩ na wa ũkanga: nũndũ ndevili nĩwamũtheeea inyw’ĩ, e na ũthilĩku mũnene, akĩmanya kana e na kavinda o kanini.'),
('kam', 'REV', 12, 13, 'Na ũla mũkũnga mũnene woona kana nĩwekw’a nthĩ, wathĩnisye mũndũ mũka ũla wasyaie ũla mwana mũũme.'),
('kam', 'REV', 12, 14, 'Na mũndũ mũka anengwa nthwau ilĩ sya ndiũ ĩla nene, nĩ kana aũlũke avike kwake weũnĩ, vala ũĩthĩaw’a ĩvinda, na mavinda, na nyunzu, ya ĩvinda, aume mbee wa nzoka ĩsu.'),
('kam', 'REV', 12, 15, 'Na ĩla nzoka nene yaumya kĩw’ũ ta ũsĩ kanyw’anĩ wayo yaatĩĩsya mũndũ mũka, nĩ kana atwawe nĩ ũsĩ.'),
('kam', 'REV', 12, 16, 'Na nthĩ yamũtetheesya mũndũ mũka, na nthĩ yaathamya kanyw’a wayo, na yamelya ũsĩ ũla mũkũnga mũnene waumya kanyw’anĩ waw’o.'),
('kam', 'REV', 12, 17, 'Na ũla mũkũnga mũnene wamũthatĩa mũndũ mũka mũno, na wathi wũkite na ũtialo wa ũsyao wake, ũla ũkwataa mĩao ya Ngai, na kũlũmya ũkũsĩ wa Yesũ: naw’o waũngama kĩthangathĩnĩ kya ũkanga.'),
('kam', 'REV', 13, 1, 'Na noona nyamũ ĩkyuma ũkanganĩ, ĩ na mbya ĩkũmi na mĩtwe mũonza na mbyanĩ syayo kwaĩ ngovia sya ũsumbĩ ĩkũmi, na mĩtwenĩ yayo masyĩtwa ma kuũmana.'),
('kam', 'REV', 13, 2, 'Na nyamũ ĩla noonie yailyĩ ngo, na maũũ mayo maĩ ta ma nduva, na kanyw’a wayo waĩ ta kanyw’a wa mũnyambũ: na ũla mũkũnga mũnene wamĩnenga vinya waw’o, na kĩvĩla kya ũsumbĩ kyaw’o, na ũkũmũ mũnene.'),
('kam', 'REV', 13, 3, 'Na noona mũtwe ũmwe wayo ta ũkũnĩtwe kũvika kĩkw’ũ; na ĩkũnwa yayo ya kĩkw’ũ yavow’a: na nthĩ yonthe yaseng’a ĩatĩĩe ĩla nyamũ;'),
('kam', 'REV', 13, 4, 'na mathaitha ũla mũkũnga mũnene, nũndũ nũmĩnengete ĩla nyamũ ũkũmũ waw’o; na mamĩthaitha ĩla nyamũ, makyasya, Nũũ ũla ũvw’anene na nyamũ ĩno? Na nũũ ũla ũtonya kũkita nayo?'),
('kam', 'REV', 13, 5, 'Nayo yanengwa kanyw’a wa ũneena maũndũ manene na kũumana; na yanengwa ũkũmũ wa kwĩka maũndũ mayo myei mĩongo ĩna na ĩlĩ.'),
('kam', 'REV', 13, 6, 'Na yaathamya kanyw’a wayo ĩmũume Ngai, kũyĩuma syĩtwa yake, na ĩeema yake, o na ala matwĩe ĩtunĩ.'),
('kam', 'REV', 13, 7, 'Nayo yanengwa kũkita na ala atheu, na kũmakĩlya vinya: nayo yanengwa ũkũmũ ĩũlũ wa kĩla mũthemba wa andũ na ũko wa andũ na kĩthyomo na mbaĩ.'),
('kam', 'REV', 13, 8, 'Na onthe ala matwĩe nthĩ makamĩthaitha, kĩla mũndũ ũla syĩtwa yake yĩtaandĩkwa ĩvukunĩ ya thayũ ya Katena ka ĩlondu kooaiwe kuma mwambĩlĩlyo wa nthĩ.'),
('kam', 'REV', 13, 9, 'Ethĩwa mũndũ e na kũtũ, nĩew’e.'),
('kam', 'REV', 13, 10, 'Ethĩwa mũndũ o na wĩva akatava, akatavwa: ethĩwa mũndũ o na wĩva akooaana na ũvyũ, mũvaka we oawe na ũvyũ. Vaa nĩvo ve wũmĩĩsyo na mũĩkĩĩo wa ala atheu.'),
('kam', 'REV', 13, 11, 'Na noona nyamũ ĩngĩ ĩkyuma nthĩnĩ wa nthĩ; nayo yaĩ na mbya ilĩ iilyĩ sya katena ka ĩlondu, na yaneena ta mũkũnga.'),
('kam', 'REV', 13, 12, 'Nayo yĩkaa na ũkũmũ w’onthe wa ĩla nyamũ ya mbee ĩsyaĩtye. Na ĩtumaa nthĩ na ala matwĩe ĩũlũ wayo mathaitha nyamũ ĩla ya mbee, ĩla yavoiw’e ĩkũnwa yayo ya kĩkw’ũ.'),
('kam', 'REV', 13, 13, 'Nayo yeeka syama nene, o na kũtuma mwaki wuma ĩtunĩ ũkavika nthĩ, andũ mene.'),
('kam', 'REV', 13, 14, 'Na yamakenga ala matwĩe nthĩ nũndũ wa syama ĩnengetwe kwĩka o nyamũ ĩsu yene; ĩkĩmatavya ala matwĩe nthĩ, kana maseũvye mũvw’anano wa ĩla nyamũ, ĩla ĩ na ĩkũnwa ya ũvyũ na yavoa.'),
('kam', 'REV', 13, 15, 'Na yanengwa kwĩkĩa mũvw’anano ũsu wa nyamũ mĩthũmũ, nĩ kana mũvw’anano wa nyamũ ũneene, o na ũtume onthe ala matethaitha mũvw’anano ũsu wa nyamũ moawa.'),
('kam', 'REV', 13, 16, 'Na yatuma onthe, anini na anene, athwii na ngya, ala mate ngombo na ngombo, mekĩwa ũvano kw’okonĩ kwa aũme kwoo, kana itulyanĩ syoo;'),
('kam', 'REV', 13, 17, 'na nĩ kana mũndũ o na wĩva ndakatonye kũthooa kana kũthoosya, ate ũla wĩ na ũvano ũsu, naw’o nĩ syĩtwa ya nyamũ kana namba ya syĩtwa yayo.'),
('kam', 'REV', 13, 18, 'Vaa nĩvo ve ũĩ. Ũla wĩ na ũmanyi, natale namba ya nyamũ ĩsu; nũndũ nĩ namba ya mũndũ: na namba yake nĩ Maana thanthatũ na mĩongo thanthatũ na thanthatũ.'),
('kam', 'REV', 14, 1, 'Na noona, na sisya, kala Katena ka ĩlondu aũngeme kĩĩmanĩ kya Saioni, na vamwe nake andũ ngili ĩana na mĩongo ĩna na inya, me na syĩtwa yake, na syĩtwa ya Ĩthe wake, maandĩkĩtwe itulyanĩ syoo.'),
('kam', 'REV', 14, 2, 'Na neew’a wasya ũkyuma ĩtunĩ, ta wasya wa iw’ũ nyingĩ, na wasya wa kĩtundumo kĩnene: na wasya ũla neewie waĩ ta wasya wa aingi ma mbeve makĩinga mbeve syoo:'),
('kam', 'REV', 14, 3, 'na maina wathi weũ mbee wa kĩvĩla kya ũsumbĩ, na mbee wa ila syũmbe inya syĩ thayũ na ala atumĩa: na vai mũndũ waatonya kwĩmanyĩsya wathi ũsu, ate o ala ngili ĩana na mĩongo ĩna na inya, ala methooetwe kumw’a nthĩ.'),
('kam', 'REV', 14, 4, 'Aa nĩo ala matavukĩt’we nĩ aka; nũndũ nĩ atheu vyũ. Asu nĩo ala mavikĩlaa Katena ka ĩlondu o vala ũendaa. Aa mathooetwe kumw’a andũnĩ, methĩwe ũsyao wa mbee kwa Ngai na kwa kala Katena.'),
('kam', 'REV', 14, 5, 'Na makanyw’anĩ moo vaiaaoneka ũvũngũ: mati na ũndũ ũtaĩle.'),
('kam', 'REV', 14, 6, 'Na noona mũlaĩka ũngĩ akĩũlũka ĩtunĩ katĩ, e na ũvoo mũseo wa tene na tene wa ũtavan’ya kwa ala matwĩe nthĩ, na kwa kĩla mũthemba na mbaĩ na kĩthyomo na ũko wa andũ;'),
('kam', 'REV', 14, 7, 'na aneena na wasya mũnene, Kĩai Ngai, na mũtaĩei; nũndũ saa wa kũsilĩla kwake nĩ mũku: na mũthaithei ũla wombie ĩtu na nthĩ na ũkanga na nthongo sya manzĩ.'),
('kam', 'REV', 14, 8, 'Na mũlaĩka ũngĩ, wa kelĩ, aatĩĩa, akyasya, Nĩ mbalũku, nĩ mbalũkũ Mbaviloni ĩla ndũa nene, ĩla yatumie mbaĩ syonthe inyw’a mbinyu ya ũthilĩku wa ũlaalai wayo.'),
('kam', 'REV', 14, 9, 'Na mũlaĩka ũngĩ, wa katatũ, aatĩĩa asu, akyasya na wasya mũnene, Ethĩwa mũndũ o na wĩva nũnũũthaitha nyamũ ĩsu na mũvw’anano wayo, na akĩtĩkĩla kwĩkĩwa ũvano kĩtulyanĩ kyake, kana kw’okonĩ kwake,'),
('kam', 'REV', 14, 10, 'akanyw’a mbinyu ya ũthilĩku wa Ngai, ĩla ĩseũvĩtw’e ĩtavulenw’e kĩkombenĩ kya ũthatu wake; na akathĩnĩw’a na mwaki na mũvĩlĩtĩ mbee wa alaĩka atheu na mbee wa kala Katena:'),
('kam', 'REV', 14, 11, 'na syũki ya thĩna woo yambataa kũvika tene na tene; na maithũmũaa mũthenya na ũtukũ, asu mathaithaa ĩla nyamũ na mũvw’anano wayo, na o ũla wĩtĩkĩlaa kwĩkĩwa ũvano wa syĩtwa yayo.'),
('kam', 'REV', 14, 12, 'Vaa nĩvo ve wũmĩĩsyo wa atheu, ala makwataa mĩao ya Ngai, na mũĩkĩĩo wa Yesũ.'),
('kam', 'REV', 14, 13, 'Na neew’a wasya ũkyuma ĩtunĩ ũiasya, Andĩka, Nĩ aathime akw’ũ ala makusaa nthĩnĩ wa Mwĩaĩi kuma yu: ĩĩ, easya ũu Veva, kana mathũmũĩe mawĩa moo maito; nũndũ mawĩa moo nĩmaatĩanĩe nao.'),
('kam', 'REV', 14, 14, 'Na noona, na sisya, ĩthweo yeũ; na ĩũlũ wa ĩthweo noona ũmwe ailyĩ nthĩ ũtilyĩ mwana wa mũndũ, e na ngovia ya ũsumbĩ ya thaavu mũtwenĩ wake, na kw’okonĩ kwake e na kavyũ koĩ ke ngoto.'),
('kam', 'REV', 14, 15, 'Na mũlaĩka ũngĩ auma ĩkalũnĩ, akyanĩĩsya ũla ũilyĩ ĩũlũ wa ĩthweo, akĩmwĩa, Likya kavyũ kaku, ũkethe: nũndũ saa wa ũketha nĩ mũviku; nũndũ ngetha ya nthĩ nĩminĩte kũma.'),
('kam', 'REV', 14, 16, 'Na ũla wailyĩ ĩũlũ wa ĩthweo ekya nthĩ kavyũ kake; na nthĩ yakethwa.'),
('kam', 'REV', 14, 17, 'Na mũlaĩka ũngĩ auma ĩkalũnĩ yĩla yĩ ĩtunĩ, o nake e na kavyũ koĩ ke ngoto.'),
('kam', 'REV', 14, 18, 'Na mũlaĩka ũngĩ auma kĩthembeonĩ, ũla wĩ na vinya ĩũlũ wa mwaki; na anĩĩsya ũla wĩ na kala kavyũ koĩ, akyasya, Likya kavyũ kaku ũtile itũngo sya mũsavivũ wa nthĩ; nĩkwĩthĩwa nzavivũ syaw’o nĩ mbĩu ki.'),
('kam', 'REV', 14, 19, 'Na mũlaĩka ekya kavyũ nthĩ, na aketha ũsyao wa mũsavivũ wa nthĩ, na awĩkya kĩangĩonĩ, kĩangĩo kĩla kĩnene kya ũthilĩku wa Ngai.'),
('kam', 'REV', 14, 20, 'Na kĩangĩo kyangĩwa ũtee wa ndũa, na nthakame yauma kĩangĩonĩ, o na kũvika mĩkwa ya mĩtwe ya mbalasi, kũvika maĩli maana elĩ.'),
('kam', 'REV', 15, 1, 'Na noona kyama kĩngĩ ĩtunĩ, kĩnene na kya ũseng’ya, alaĩka mũonza makuĩte mothĩn’yo mũonza, nao nĩ ma mũminũkĩlyo, nĩkwĩthĩwa nthĩnĩ wamo ũthilĩku wa Ngai nũkwĩanĩa.'),
('kam', 'REV', 15, 2, 'Na noona kĩndũ kĩilyĩ ũkanga wa kĩsisyo ũvulene na mwaki; na ala makĩlĩtye vinya na kwĩyumya vala ve ĩla nyamũ, na mũvw’anano wayo, na namba ya syĩtwa yayo, maũngeme ũtee wa ũkanga wa kĩsisyo, me na mbeve sya Ngai.'),
('kam', 'REV', 15, 3, 'Nao meina wathi wa Mose ngombo ya Ngai, na wathi wa kala Katena, makyasya, Mawĩa maku nĩ manene na ma ũseng’ya, Mwĩaĩi Ngai, Mwene Vinya W’onthe; moendelo maku nĩ malũngalu na ma w’o, we Mũsumbĩ wa tene tene.'),
('kam', 'REV', 15, 4, 'Nũũ ũtakakĩa, Mwĩaĩi, na kũtaĩa syĩtwa yaku? Nũndũ nue weka mũtheu; nĩkwĩthĩwa mbaĩ syonthe ikooka na kũthaitha mbee waku; nũndũ meko maku ma ũlũngalu nĩmonanĩtw’e.'),
('kam', 'REV', 15, 5, 'Na ĩtina wa maũndũ asu noona, na ĩkalũ ya ĩeema ya ũkũsĩ ĩtunĩ yavingũwa:'),
('kam', 'REV', 15, 6, 'na ala alaĩka mũonza ala me na mothĩn’yo mũonza mauma ĩkalũnĩ, mevw’ĩkĩte mavia me thooa mũnene, matheu na matisu, na meevotoele nondonĩ syoo ndavũ sya thaavu.'),
('kam', 'REV', 15, 7, 'Na kĩmwe kya ila syũmbe inya syĩ thayũ kyamanenga alaĩka asu mũonza mbakũli mũonza sya thaavu syusĩe ũthilĩku wa Ngai, ũla wĩ thayũ kũvika tene na tene.'),
('kam', 'REV', 15, 8, 'Na ĩkalũ yausũa syũki yumĩte ũtheunĩ mũtisu wa Ngai, na vinyanĩ wake; na vaiaĩ mũndũ waatonya kũvota ĩkalũnĩ mũvaka mothĩn’yo mũonza ma alaĩka asu mũonza mathela.'),
('kam', 'REV', 16, 1, 'Na neew’a wasya mũnene ũiuma ĩkalũnĩ, ũimatavya ala alaĩka mũonza atĩĩ, Endai, na mũiĩta ila mbakũli mũonza sya ũthilĩku wa Ngai nthĩ.'),
('kam', 'REV', 16, 2, 'Na ũla wa mbee aenda, na eta mbakũli yake nthĩ; na kweethĩwa itau nthũku mũno na syĩ na woo mũnene andũnĩ ala me na ũvano wa ĩla nyamũ, na ala mathaithaa mũvw’anano wayo.'),
('kam', 'REV', 16, 3, 'Na ũla wa kelĩ eta mbakũli yake ũkanganĩ; naw’o watw’ĩka nthakame ta ya mũndũ mũkw’ũ; na kyonthe kĩ thayũ kyakw’a, kya ila syĩ ũkanganĩ.'),
('kam', 'REV', 16, 4, 'Na ũla wa katatũ eta mbakũli yake mbũsĩnĩ na nthongonĩ sya manzĩ; nasyo syatw’ĩka nthakame.'),
('kam', 'REV', 16, 5, 'Na neew’a mũlaĩka wa manzĩ aiasya, We wĩ mũlũngalu, ũla wĩ vo na ũla waĩ vo, we Ũla Mũtheu, nĩkwĩthĩwa nĩwasilĩla ũu:'),
('kam', 'REV', 16, 6, 'nũndũ nĩmetĩkisye nthakame ya atheu na athani, naku wamanenga nthakame manyw’e: nĩmaĩlwe.'),
('kam', 'REV', 16, 7, 'Na neew’a kĩthembeo kĩiasya, Ĩĩ, we Mwĩaĩi Ngai, Mwene Vinya W’onthe, motw’ĩo maku nĩ ma w’o na nĩ malũngalu.'),
('kam', 'REV', 16, 8, 'Na ũla wa kana eta mbakũli yake ĩũlũ wa syũa; na yanengwa kũvĩvya andũ na mwaki.'),
('kam', 'REV', 16, 9, 'Na andũ mavĩvw’a na ũvyũvu mũnene: na mayĩuma syĩtwa ya Ngai ũla wĩ na ũkũmũ ĩũlũ wa mothĩn’yo asu; na matyaalyũla ngoo na kũmũnenga ndaĩa.'),
('kam', 'REV', 16, 10, 'Na ũla wa katano eta mbakũli yake kĩvĩlanĩ kya ũsumbĩ kya ĩla nyamũ; na ũsumbĩ wayo weekĩwa kĩvindu; na matanyũka nĩmĩ syoo nũndũ wa woo,'),
('kam', 'REV', 16, 11, 'na mamũuma Ngai wa ĩtunĩ nũndũ wa mawoo moo na itau syoo; na matyaaalyũla ngoo ũndũ wa mawĩa moo.'),
('kam', 'REV', 16, 12, 'Na ũla wa thanthatũ eta mbakũli yake ĩũlũ wa ũla ũsĩ mũnene, wĩtawa Euvalati; na manzĩ maw’o mang’ala, nĩ kana nzĩa ĩseũvĩw’e asumbi ala meũka kuma wumĩlonĩ wa syũa.'),
('kam', 'REV', 16, 13, 'Na noona maveva atatũ mavuku, mailyĩ syoa, maiuma kanyw’anĩ wa ũla mũkũnga, na kanyw’anĩ wa ĩla nyamũ, na kanyw’anĩ wa mwathani wa ũvũngũ:'),
('kam', 'REV', 16, 14, 'nĩkwĩthĩwa nĩ maveva ma ndaimoni, mekaa syama; ala meuma mathi kwa asumbĩ ma nthĩ yonthe kũmomban’ya kaũnĩ wa mũthenya mũnene wa Ngai, Mwene Vinya W’onthe.'),
('kam', 'REV', 16, 15, '(Sisya, nĩũka ta kĩng’ei. Nĩ mũathime ũla ũsyaĩĩasya na kũsũvĩa ngũa syake, ndakathi e mũthei, na makona nthoni syake.)'),
('kam', 'REV', 16, 16, 'Na mamomban’ya vamwe vala vetawa Kĩevelania Ali‐Maketoni.'),
('kam', 'REV', 16, 17, 'Na ũla wa mũonza eta mbakũli yake ĩũlũ wa yayaya; na wasya mũnene wauma ĩkalũnĩ kuma kĩvĩlanĩ kya ũsumbĩ, ũkyasya, Nĩ kwĩke:'),
('kam', 'REV', 16, 18, 'na kwaĩ motisi, na mawasya, na itundumo; na kwaĩ kĩtetemo kĩnene kya nthĩ, o na kũiaaithĩwa kĩngĩ takyo kuma andũ meethĩwa kũũ nthĩ, kĩtetemo kĩnenevete ũu, kĩan’ya vinya ũu.'),
('kam', 'REV', 16, 19, 'Na ĩla ndũa nene yaanw’a ilungu itatũ, na ndũa sya i mbaĩ syavalũka: na Mbaviloni ĩla ndũa nene yalilikanwa mbee wa Ngai, ĩnengwe kĩkombe kya mbinyu ya wai wa ũthilĩku wake.'),
('kam', 'REV', 16, 20, 'Na ithama syonthe syakĩa, na iĩma nasyo ityaaoneka ĩngĩ.'),
('kam', 'REV', 16, 21, 'Na mbua nene ya mavia, kĩla ĩvia ũito wayo waĩ ta talendi ĩmwe, yamatheeea andũ kuma ĩtunĩ: na andũ mamũuma Ngai nũndũ wa ũthĩn’yo ũsu wa mbua ya mavia; nĩkwĩthĩwa ũthĩn’yo wayo nĩ mũnene mũno.'),
('kam', 'REV', 17, 1, 'Na kwookie ũmwe wa alaĩka asu mũonza ala maĩ na mbakũli mũonza, aneena nakwa, akyasya, Ũka vaa, nĩngũkwon’ya ũsilĩlo wa yĩla ĩlwaya ĩnene yĩla yĩkalaa ĩũlũ wa iw’ũ nyingĩ;'),
('kam', 'REV', 17, 2, 'yĩla asumbĩ ma nthĩ malaalaile nayo, na ala matwĩe nthĩ matoonw’a nĩ mbinyu ya ũiaalai wayo.'),
('kam', 'REV', 17, 3, 'Nake angua nĩ Vevanĩ kũvika weũnĩ: na noona mũndũ mũka ekalĩle nyamũ ndune mũno, yusũĩte masyĩtwa ma kũumana, ĩ na mĩtwe mũonza na mbya ĩkũmi.'),
('kam', 'REV', 17, 4, 'Na ũ mũndũ mũka eevw’ĩkĩte ngũa ĩilyĩ ta ndune na ĩngĩ ndune mũno, na aseũvĩtw’e na thaavu na tũvila twĩ thooa mũnene na malũlũ, na kw’okonĩ kwake aĩ na kĩkombe kya thaavu kyusĩwe nĩ mothatyo, nao nĩ maũndũ mavuku ma ũlaalai wake,'),
('kam', 'REV', 17, 5, 'na kĩtulyanĩ kyake vaandĩkĩtwe syĩtwa, NZAMA, MBAVILONI ĨLA NENE, INYIA WA MALWAYA NA WA MOTHATYO MA NTHĨ.'),
('kam', 'REV', 17, 6, 'Na noona mũndũ mũka ũsu aitoonw’a nĩ nthakame ya atheu, na nthakame ya ngũsĩ sya Yesũ. Namwona, naseng’a na ũseng’yo mũnene.'),
('kam', 'REV', 17, 7, 'Na ũla mũlaĩka angũlya, Nĩ kyaũ kĩũkũseng’ya? Nĩngũũtavya nzama ya mũndũ mũka ũũ, na ya nyamũ ĩla ĩmũkuĩte, ĩla ĩ na mĩtwe mũonza na mbya ĩkũmi.'),
('kam', 'REV', 17, 8, 'Nyamũ ĩla woona yaĩ vo, na yu ndĩ vo; na nĩkilĩlye kwambata kuma yĩla ĩimanĩ yĩte kĩtulu, na kũthi wanangĩkonĩ. Na ala matwĩe nthĩ makaseng’a, ala masyĩtwa moo mataaandĩkwa ĩvukunĩ ya thayũ kuma mwambĩlĩlyo wa nthĩ, moona ĩla nyamũ, ũndũ yaĩ vo, na yu ndĩ vo, na ĩkeethĩwa vo.'),
('kam', 'REV', 17, 9, 'Vaa nĩvo ve kĩlĩko kĩ na ũĩ. Mĩtwe ĩsu mũonza nĩ iĩma mũonza, ila mũndũ mũka wĩkalĩle:'),
('kam', 'REV', 17, 10, 'nasyo nĩ asumbĩ mũonza; atano nĩ avalũku, ũmwe e vo, na ũla ũngĩ ndanamba kũka; nake ooka, mũvaka ekale kavinda kanini.'),
('kam', 'REV', 17, 11, 'Na nyamũ ĩla yaĩ vo, na yu ndĩ vo, nayo nĩyo ya nyanya, na nĩ ya ila mũonza; nayo ĩthi wanangĩkonĩ.'),
('kam', 'REV', 17, 12, 'Na mbya ĩkũmi ila wonie nĩ asumbĩ ĩkũmi, ala matanamba kwosa ũsumbĩ; ĩndĩ meosa ũkũmũ ta asumbĩ, vamwe na nyamũ ĩsu, ĩvinda ya saa ũmwe.'),
('kam', 'REV', 17, 13, 'Asu me na kĩlilikano kĩmwe, na memĩnenga nyamũ ĩsu vinya na ũkũmũ woo.'),
('kam', 'REV', 17, 14, 'Asu makokita na kala Katena ka ĩlondu, nake Katena akamakĩlya vinya, nĩkwĩthĩwa we nĩ Mwĩaĩi wa eaĩi na Mũsumbĩ wa asumbĩ; na ala me nake, ala meetiwe, anyuve na me na kĩthito, makakĩlya vinya.'),
('kam', 'REV', 17, 15, 'Nake ambĩa, Iw’ũ ila wonie, vala yĩla ĩlwaya yĩkalaa, nĩ ngo sya andũ, na makomano, na mbaĩ, na ithyomo.'),
('kam', 'REV', 17, 16, 'Na mbya ĩkũmi ila wonie na ĩla nyamũ, asu makamena yĩla ĩlwaya, na makayĩtia yoka, na yĩ ĩthei, na makaya nyama syayo, na makayĩvĩvya vyũ na mwaki.'),
('kam', 'REV', 17, 17, 'Nũndũ Ngai ekĩĩte ngoonĩ syoo kwĩka kwenda kwake, na kwĩtĩkĩla ũndũ ũmwe, na kũmĩnenga ĩla nyamũ ũsumbĩ woo, mũvaka ndeto sya Ngai syĩanĩe.'),
('kam', 'REV', 17, 18, 'Na mũndũ mũka ũla wonie nĩwe ĩla ndũa nene, ĩla ĩsumbĩkaa ĩũlũ wa asumbĩ ma nthĩ.'),
('kam', 'REV', 18, 1, 'Na ĩtina wa maũndũ asu noona mũlaĩka ũngĩ aitheea kuma ĩtunĩ, e na ũkũmũ mũnene; na nthĩ yeekĩiwe kyeni nĩ ũtheu wake mũtisu.'),
('kam', 'REV', 18, 2, 'Nake aneena na wasya wĩ vinya mũno, aiasya, Nĩ mbalũku, nĩ mbalũku, Mbaviloni ĩla ndũa nene, na nĩtw’ĩkĩte ũtũo wa ndaimoni, na kolokolo wa kĩla veva mũvuku, na kolokolo wa kĩla nyũnyi, mbuku na mene.'),
('kam', 'REV', 18, 3, 'Nĩkwĩthĩwa mbaĩ syonthe nĩ mbalũku nũndũ wa mbinyu ya ũthatu wa ũlaalai wake; na asumbĩ ma nthĩ nĩmalaalaile nake, na atandĩthya ma nthĩ nĩmathuiw’e nĩ wingĩ wa wanango wake.'),
('kam', 'REV', 18, 4, 'Na neew’a wasya ũngĩ ũkyuma ĩtunĩ, ũiasya, Umai nthĩnĩ wake, andũ makwa, nĩ kana mũikethĩwe na mũamba na naĩ syake, na mũikose mothĩn’yo make:'),
('kam', 'REV', 18, 5, 'nũndũ naĩ syake nivikĩte o na ĩtunĩ, na Ngai nũlilikanĩte mothũku make.'),
('kam', 'REV', 18, 6, 'Mũĩvanĩsyei o ũndũ waĩvanĩasya, na mũimũĩvanĩsya kũndũ kwĩlĩ kwĩanana na meko make: kĩkombenĩ kĩla wavulanilye, mũvulanĩlyei kũndũ kwĩlĩ.'),
('kam', 'REV', 18, 7, 'O ũndũ we wetaĩe, na kwĩkala motanunĩ ma mwĩĩ, mũnenge mathĩna na kĩmeto o ta ũu: nĩkwĩthĩwa easya ngoonĩ yake, Nĩilyĩ nthi nĩ mũsumbĩ mũndũ mũka, na ndi ndiwa na ndikethĩwa na kĩmeto nongi.'),
('kam', 'REV', 18, 8, 'Kwondũ wa ũu mũthenya o ũmwe mothĩn’yo make makooka, kĩkw’ũ, na kĩmeto, na yũa; nake akavĩvw’a vyũ na mwaki; nĩkwĩthĩwa Mwĩaĩi Ngai ũla wamũsilĩle e na vinya.'),
('kam', 'REV', 18, 9, 'Na asumbĩ ma nthĩ, ala malaalaile nake na kwĩkala motanunĩ ma mwĩĩ vamwe nake, makamũĩĩa na kũmeta masisya syũki ya kũvya kwake,'),
('kam', 'REV', 18, 10, 'makĩũngama kũasa nũndũ wa w’ĩa wa thĩna wake, makyasya, Woo, woo, ndũa nene, Mbaviloni, ndũa ĩla yĩ vinya! Nĩkwĩthĩwa saa ũmwe ũsilĩlo waku nĩwooka.'),
('kam', 'REV', 18, 11, 'Na atandĩthya ma nthĩ nĩmeũmũĩĩa na kũmeta, nĩkwĩthĩwa vai mũndũ ũthooaa mĩio yoo ĩngĩ;'),
('kam', 'REV', 18, 12, 'mĩio ya thaavu, na vetha, na tũvila twĩ thooa mũnene, na malũlũ, na ngũa sya katane nzeo, na ila itilyĩ ta ndune, na sya alili, na ila ndune mũno; na mĩtĩ yonthe ĩla ĩnyungaa nesa, na mĩio yonthe ĩseũvĩtw’e na maeo ma nzou, na mĩio yonthe ĩseũvĩtw’e na mĩtĩ ĩ thooa mũnene, na ya ũthuku, na kĩaa, na mavia maseo;'),
('kam', 'REV', 18, 13, 'na mũtalasini, na ĩliki, na ũvani, na manukato, na ũvumba, na mbinyu, na mauta ma mũthata, na mũtu mũvinyu, na nganũ, na ng’ombe, na malondu, na mbalasi, na ngalĩ, na ngombo, na mathayũ ma andũ.'),
('kam', 'REV', 18, 14, 'Na mosyao ala ngoo yaku yendie nĩmakũtiie, na syĩndũ syonthe ila syaĩ nou na nzeo mũno nikwaĩe, na andũ maikasyona ĩngĩ nongi.'),
('kam', 'REV', 18, 15, 'Na atandĩthya ma mĩio ĩsu, ala mathuiw’e nĩwe, makaũngama kũasa mũno nũndũ wa w’ĩa wa thĩna wake, makĩĩa na kũmeta;'),
('kam', 'REV', 18, 16, 'makyasya, Woo, woo, ndũa nene, ĩla ĩneevw’ĩkĩte ngũa sya katane nzeo na ila itilyĩ ta ndune na ila ndune mũno, na kwanakavw’a na thaavu na tũvila twĩ thooa mũnene na lũlũ!'),
('kam', 'REV', 18, 17, 'Nũndũ saa ũmwe ũthwii wĩana ũu nĩwaminwa. Na kĩla mũnene wa ngalawa, na kĩla mũndũ ũendaa ũkanganĩ o na va, na atwai ma ngalawa, na onthe ala matwĩw’e nĩ wĩa wa ũkanganĩ, maũngama kũasa,'),
('kam', 'REV', 18, 18, 'na maneena na wasya mũnene makĩsisya syũki ya kũvya kwayo, makyasya, Nĩ ndũa yĩva ĩtilyĩ ndũa ĩsu nene?'),
('kam', 'REV', 18, 19, 'Na mekya kĩtoo mĩtwenĩ yoo, na maneena na wasya mũnene, makĩĩa na kũmeta, makyasya, Woo, woo, ĩla ndũa nene, ĩla ntnĩnĩ wayo onthe ala maĩ na ngalawa syoo ũkanganĩ mathuĩtw’e nũndũ wayo kũnenevya thooa! Nũndũ saa ũmwe nĩyatw’ĩka ĩanzo.'),
('kam', 'REV', 18, 20, 'Tanai ĩũlũ wayo, we ĩtu, na inyw’ĩ atheu, na inyw’ĩ atũmwa, na inyw’ĩ athani; nĩkwĩthĩwa Ngai nũsilĩlĩte ũsilĩlo wenyu ĩũlũ wayo.'),
('kam', 'REV', 18, 21, 'Na mũlaĩka wĩ vinya ookĩlya ĩvia yailyĩ ĩvia ĩnene ya ũthia na ayĩkya ũkanganĩ, aiasya, O ta ũu Mbaviloni, ĩla ndũa nene, ĩkekw’a nthĩ na ũvalũko mũnene, na ndĩkoneka ĩngĩ nongi.'),
('kam', 'REV', 18, 22, 'Na mawasya ma aingi ma mbeve na aini ma mbathi na avuvi ma nzumalĩ na avuvi ma masoo maikew’ĩka nthĩnĩ waku nongi; na vai ndũĩka, o na yĩva, ĩkoneka nthĩnĩ waku ĩngĩ nongi; na wasya wa ĩvia ya ũthia ndũkew’ĩka nthĩnĩ waku nongi;'),
('kam', 'REV', 18, 23, 'na kyeni kya taa kĩikakena nthini waku nongi: na wasya wa mũtwaani na wa mũtwawa ndũkew’ĩka nthĩnĩ waku ĩngĩ nongi: nĩkwĩthĩwa atandĩthya maku maĩ anene ma nthĩ; nũndũ mbaĩ syonthe nĩsyakengiwe nĩ ũoi waku.'),
('kam', 'REV', 18, 24, 'Na nthĩnĩ wayo kwoonekie nthakame ya athani na ala atheu, na ya onthe ala mooaiwe nthĩ.'),
('kam', 'REV', 19, 1, 'Ĩtina wa maũndũ asu neew’a wasya mũnene wa nguthu nene ĩtunĩ, ũiasya, Aleluya; Ũtangĩĩo, na ndaĩa, na vinya, nĩ sya Ngai waitũ:'),
('kam', 'REV', 19, 2, 'nũndũ motw’ĩo make nĩ ma w’o na nĩ malũngalu; nũndũ nũsilĩle yĩla ĩlwaya ĩnene, yĩla yathũkisye nthĩ na ũlaalai wayo, nake nĩwaĩvanĩsye nthakame ya ngombo syake kw’okonĩ kwayo.'),
('kam', 'REV', 19, 3, 'Na masya ĩvinda ya kelĩ, Aleluya. Na syũki yayo yambataa kũvika tene na tene.'),
('kam', 'REV', 19, 4, 'Na ala atumĩa mĩongo ĩlĩ na ana na ila syũmbe inya syĩ thayũ mavalũka nthĩ na mamũthaitha Ngai ũla wĩkalaa kĩvĩlanĩ kya ũsumbĩ, maiasya, Ameni: Aleluya.'),
('kam', 'REV', 19, 5, 'Na wasya wauma kĩvĩlanĩ kya ũsumbĩ, ũiasya, Mũkumyei Ngaĩ waitũ, inyw’onthe ngombo syake, inyw’ĩ ala mũmũkĩaa, anini na anene.'),
('kam', 'REV', 19, 6, 'Na neew’a ta wasya wa nguthu nene, na ta wasya wa iw’ũ nyingĩ, na ta wasya wa itundumo ila syĩ vinya mũno, ũiasya, Aleluya: nĩkwĩthĩwa Mwĩaĩi Ngai waitũ, Mwene Vinya W’onthe, nũsumbĩkĩte.'),
('kam', 'REV', 19, 7, 'Tũtanei na kwĩw’a mũyo mũno, na tũimũnenga we ndaĩa: nĩkwĩthĩwa mũtwaano wa kala Katena nĩ mũviku, na mũka wake nĩwĩseũvĩtye.'),
('kam', 'REV', 19, 8, 'Nake anengwa kwĩkĩa ngũa ya katane nzeo, ndisu na ntheu: nũndũ ngũa ĩsu ya katane nzeo nĩ meko malũngalu ma atheu.'),
('kam', 'REV', 19, 9, 'Na ambĩa, Andĩka, Nĩ aathime ala metĩtwe mbokanĩ ya mũtwaano ya kala Katena. Na ambĩa, Ii nĩ ndeto sya w’o sya Ngai.'),
('kam', 'REV', 19, 10, 'Nakwa navalũka maũũnĩ make nĩmũthaithe. Nake ambĩa, Sisya, ndũkeke ũu: nyie nĩ ngombo vamwe naku na vamwe na ana‐a‐ĩthe maku ala makwataa ũkũsĩ wa Yesũ; thaitha Ngai: nũndũ ũkũsĩ wa Yesũ nĩw’o veva wa wathani.'),
('kam', 'REV', 19, 11, 'Na noona ĩtu yĩvingũkĩte; na sisya, mbalasi nzaũ, na ũla ũmĩtũlĩte, eetawa Mũkĩthito na Mũw’o; na asilaa na ũkwatya kaũ na ũlũngalu.'),
('kam', 'REV', 19, 12, 'Na metho make nĩ ũmũĩ wa mwaki, na mũtwenĩ wake ve ngovia nyingĩ sya ũsumbĩ; nake e na syĩtwa yĩandĩkĩtwe, yĩla yĩtesĩkĩwe nĩ mũndũ o na wĩva ate o we mwene.'),
('kam', 'REV', 19, 13, 'Nake eevw’ĩkĩte ngũa ĩminzangĩw’e nthakame: na syĩtwa yake eetawa Ndeto ya Ngai.'),
('kam', 'REV', 19, 14, 'Na ita ila syĩ ĩtunĩ syamũatĩĩa itũlĩte mbalasi nzaũ, syĩvw’ĩkĩte katane nzeo, nzaũ na ntheu.'),
('kam', 'REV', 19, 15, 'Na ũvyũ mũĩ wauma kanyw’anĩ wake, nĩ kana akũne mbaĩ naw’o: na akaisumbĩka na ndata ya kĩaa: nake ekinyangĩa kĩangĩonĩ kya mbinyu ya wai wa ũthilĩku wa Ngai, Mwene Vinya W’onthe.'),
('kam', 'REV', 19, 16, 'Na ngũanĩ yake na nthũnũnĩ yake e na syĩtwa yĩandĩkĩtwe, MŨSUMBĨ WA ASUMBĨ NA MWĨAĨI WA EAĨI.'),
('kam', 'REV', 19, 17, 'Na noona mũlaĩka ũmwe aũngeme syũanĩ; na aneena na wasya mũnene, aitavya nyũnyi syonthe ila ilũlũkaa ĩtunĩ katĩ, Ũkai mũmbane vamwe mbokanĩ ĩla nene ya Ngai;'),
('kam', 'REV', 19, 18, 'nĩ kana mũye nyama sya asumbĩ, na nyama sya anene ma asikalĩ ngili, na nyama sya andũ ala me na vinya, na nyama sya mbalasi na sya ala masyĩkalĩlaa, na nyama sya andũ onthe, ala mate ngombo na ngombo, anini na anene.'),
('kam', 'REV', 19, 19, 'Na noona ĩla nyamũ, na asumbĩ ma nthĩ, na ita syoo, mombanĩte makwatye kaũ na ũla wĩkalĩle ĩla mbalasi, na ita syake.'),
('kam', 'REV', 19, 20, 'Na ĩla nyamũ yakwatwa, na vamwe nayo ũla mwathani wa ũvũngũ ũla wekie syama mbee wayo, na kwondũ wasyo wamakengie ala mosete ũvano wa ĩla nyamũ na ala mathaithie mũvw’anano wayo: me elĩ mekiw’e me thayũ ĩianĩ ya mwaki ũla wakanaa na mũvĩlĩtĩ:'),
('kam', 'REV', 19, 21, 'na ala matialile mooaiwe na ũvyũ wa ũla wekalĩle ĩla mbalasi, naw’o nĩ ũvyũ ũla waumie kanyw’anĩ wake: na nyũnyi syonthe syavũnw’a nĩ nyama syoo.'),
('kam', 'REV', 20, 1, 'Na noona mũlaĩka aitheea kuma ĩtunĩ, e na ũvungũo wa yĩla ĩima yĩte kĩtulu na mũnyololo mũnene kw’okonĩ kwake.'),
('kam', 'REV', 20, 2, 'Nake akwata ũla mũkũnga, nzoka ngũũ, nayo nĩ Ndevili na nĩwe Satani, na amwova myaka ngili,'),
('kam', 'REV', 20, 3, 'na amwĩkya ĩimanĩ yĩte kĩtulu na ayĩvinga, na asyĩsiĩla ĩũlũ wake, nĩ kana ndakakenge mbaĩ ĩngĩ, mũvaka ĩla myaka ngili ĩthele: ĩtina wa ũu mũvaka athaw’e kavinda kanini.'),
('kam', 'REV', 20, 4, 'Na noona ivĩla sya ũsumbĩ, namo mekala ĩũlũ wasyo, na manengwa kũsila: na noona mathayũ ma ala matililwe mĩtwe kwondũ wa ũkũsĩ wa Yesũ, na ndeto ya Ngai, na ala mataathaitha ĩla nyamũ, kana mũvw’anano wayo, na ala mataaosa ũvano itulyanĩ syoo na mokonĩ moo; nao meethĩwa thayũ, na masumbĩka vamwe na Klĩsto myaka ngili.'),
('kam', 'REV', 20, 5, 'Akw’ũ ala matialile matyaaĩthĩwa thayũ mũvaka myaka ĩsu ngili ĩthele. Ũu nĩw’o ũthayũũkyo wa mbee.'),
('kam', 'REV', 20, 6, 'Nĩ mũathime na nĩ mũtheu ũla wĩ na kĩanda ũthayũũkyonĩ wa mbee: ĩũlũ wa asu kĩkw’ũ kya kelĩ kĩti na ũkũmũ; ĩndĩ makeethĩwa athembi ma Ngai ma Klĩsto, na makasumbĩka vamwe nake myaka ngili.'),
('kam', 'REV', 20, 7, 'Na myaka ĩsu ngili yathela, Satani akathaw’a kuma kolokolonĩ wake,'),
('kam', 'REV', 20, 8, 'na akauma akenge mbaĩ ila syĩ ikotonĩ inya sya nthĩ, Ngoki na Makoki, kũmomban’ya vamwe kaũnĩ: ũtalo wamo nĩ ta kĩthangathĩ kya ũkanganĩ.'),
('kam', 'REV', 20, 9, 'Nao mambata ĩũlũ wa ũthanthau wa nthĩ, na mathyũlũlũka mwako wa maeema wa atheu, na ndũa ĩla yendetwe; na mwaki watheea kuma ĩtunĩ, na wamamina.'),
('kam', 'REV', 20, 10, 'Na ndevili ũla wamakengie ekw’a ĩianĩ ya mwaki na mũvĩlĩtĩ, nĩvo ve ĩla nyamũ na ũla mwathani wa ũvũngũ; namo makanyamaw’a mũthenya ya ũtukũ tene na tene.'),
('kam', 'REV', 20, 11, 'Na noona kĩvĩla kĩnene kyeũ kya ũsumbĩ, na ũla wĩkalĩte ĩũlũ wakyo, nthĩ na ĩtu syakĩa ũthyũ wake; na vaiaaoneka vandũ vasyo.'),
('kam', 'REV', 20, 12, 'Na noona akw’ũ, anene na anini, maũngeme mbee wa kĩvĩla kya kyeũ; na mavuku mavuanw’a: na ĩvuku yĩngĩ yavuanw’a, nayo nĩ ĩvuku ya thayũ: na ala akw’ũ masilĩlwa na maũndũ ala maandĩkĩtwe mavukunĩ asu, kwĩanana na meko moo.'),
('kam', 'REV', 20, 13, 'Na ũkanga waumya akw’ũ ala maĩ nthĩnĩ waw’o; na kĩkw’ũ na vandũ vala maveva ma akw’ũ mekalaa syaumya akw’ũ ala maĩ nthĩnĩ wasyo: na masilĩlwe kĩla mũndũ kwĩanana na meko make.'),
('kam', 'REV', 20, 14, 'Na kĩkw’ũ na vala maveva ma ala akw’ũ mekalaa syekw’a ĩianĩ ya mwaki. Kĩĩ nĩkyo kĩkw’ũ kya kelĩ, nakyo nĩ ĩia ya mwaki.'),
('kam', 'REV', 20, 15, 'Na ethĩwa mũndũ o na wĩva alea kwoneka aaĩndĩkĩtwe ĩvukunĩ ya thayũ, nĩwekiw’e ĩianĩ ya mwaki.'),
('kam', 'REV', 21, 1, 'Na noona ĩtu yeũ na nthĩ nzaũ: nĩkwĩthĩwa ĩtu ya mbee na nthĩ ya mbee nĩ mbĩtu; na ũkanga ndwĩ vo ĩngĩ.'),
('kam', 'REV', 21, 2, 'Na noona ũla mũsyĩ mũtheu, Yelusaleme mweũ, ũitheea kuma ĩtunĩ kwa Ngai, ũmbanĩtw’e ta mũtwawa ũseũvĩw’e mũũme.'),
('kam', 'REV', 21, 3, 'Na neew’a wasya mũnene kuma kĩvĩlanĩ kya ũsumbĩ, ũiasya, Sisya, ĩeema ya Ngai yĩ vamwe na andũ, nake akatũa vamwe nao, namo makeethĩwa andũ make, na Ngai mwene akeethĩwa vamwe nao, Ngai woo:'),
('kam', 'REV', 21, 4, 'na akavyaĩa methoi onthe methonĩ moo; na kĩkw’ũ kĩikethĩwa vo ĩngĩ; o na kũikethĩwa ĩngĩ kũmeta, kana kũĩa, kana woo: maũndũ ma mbee nĩ mavĩtu.'),
('kam', 'REV', 21, 5, 'Na ũla wĩkalĩte kĩvĩlanĩ kya ũsumbĩ asya, Sisya, nĩngũtw’a maũndũ onthe meũ. Na asya, Andĩka: nĩkwĩthĩwa ndeto ii nĩ sya kĩthito na nĩ sya w’o.'),
('kam', 'REV', 21, 6, 'Na ambĩa, Nĩ kwĩke. Nyie nĩ Aliva na Omeka, mwambĩlĩyo na mũminũkĩlyo. Ngamũnenga ũla wĩ na waũni manzĩ ma nthongo ya manzĩ ma thayũ mana.'),
('kam', 'REV', 21, 7, 'Ũla ũkĩlasya akatiĩwa maũndũ asu; nakwa ngeethĩwa Ngai wake, nake akeethĩwa mwana wakwa.'),
('kam', 'REV', 21, 8, 'Ĩndĩ ala makĩaa, na ala matetĩkĩlaa, na ala mathatasya, na oaani, na ilaalai, na aoi, na athaithi ma mĩvw’anano, na onthe ala maneenaa ũvũngũ, kĩanda kyoo kĩkeethĩwa ĩianĩ yĩla yakanaa mwaki na mũvĩlĩtĩ; nayo nĩa kĩkw’ũ kya kelĩ.'),
('kam', 'REV', 21, 9, 'Na kwooka ũmwe wa alaĩka asu mũonza ala maĩ na mbakũli mũonza, ala makuĩte mothĩn’yo mũonza ma mũminũkĩlyo; na aneena nakwa, aiasya, Ũka vaa, nĩngũkwon’ya mũtwawa, mũka wa kala Katena.'),
('kam', 'REV', 21, 10, 'Na angua nĩ Vevanĩ kũvika kĩĩmanĩ kĩnene na kĩtũlu, na ambon’ya mũsyĩ ũla mũtheu Yelusaleme, ũitheea kuma ĩtunĩ kwa Ngai,'),
('kam', 'REV', 21, 11, 'wĩ na ũtheu mũtisu wa Ngai: kyeni kyaw’o kyailyĩ kavila ka thooa mũnene, ta kavila ketawa yasivi, katheu ta kĩsisyo:'),
('kam', 'REV', 21, 12, 'wĩ na ũvai mũnene na mũtũlu; wĩ na mbingĩlo ĩkũmi na ilĩ, na mbingĩlonĩ alaĩka ĩkũmi na elĩ; na masyĩtwa maandĩkĩtwe mbingĩlonĩ, nao nĩ masyĩtwa ma mbaĩ ĩkũmi na ilĩ sya ana ma Isilaeli:'),
('kam', 'REV', 21, 13, 'ngalĩ ya wumĩlonĩ wa syũa kwaĩ mbingĩlo itatũ; na ngalĩ ya ĩũlũ mbingĩlo itatũ; na ngalĩ ya ĩtheo mbingĩlo itatũ; na ngalĩ ya ũthũĩlonĩ wa syũa mbingĩlo itatũ.'),
('kam', 'REV', 21, 14, 'Na ũvai wa mũsyĩ waĩ na myambĩlĩlyo ĩkũmi na ĩlĩ, na ĩũlũ wayo masyĩtwa ĩkũmi na elĩ ma ala atũmwa ĩkũmi na elĩ ma kala Katena.'),
('kam', 'REV', 21, 15, 'Na ũla waneenie nakwa aĩ na kĩthimi kya mũangi wa thaavu nĩ kana athime mũsyĩ, na mbingĩlo syaw’o, na ũvai waw’o.'),
('kam', 'REV', 21, 16, 'Na mũsyĩ ũsu wĩanene ngalĩ inya, ũasa waw’o wĩanene na ũthanthau waw’o: na athima mũsyĩ na mũangi ũsu, na eethĩa nĩ maĩli ngili ĩmwe na maana atano: ũasa na ũthanthau na ũtũlu waw’o nĩsyĩanene.'),
('kam', 'REV', 21, 17, 'Na athima ũvai waw’o, mĩkono ĩana na mĩongo ĩna na ĩna, kũthima kwa mũndũ, nakw’o nĩ kwa mũlaĩka.'),
('kam', 'REV', 21, 18, 'Na ũvai waw’o waakĩtwe na yasivi: na mũsyĩ waĩ wa thaavu mũtheu, ta kĩsisyo kĩtheu.'),
('kam', 'REV', 21, 19, 'Myambĩlĩlyo ya ũvai wa mũsyĩ yanakavĩtw’e na mĩthemba yonthe ya tũvila twĩ thooa mũnene. Mwambĩlĩlyo wa mbee waĩ wa yasivi; wa kelĩ, savili; wa katatũ, kasitoni; wa kana, sumalatĩ;'),
('kam', 'REV', 21, 20, 'wa katano, salitonyi; wa thanthatũ, salitũ; wa mũonza, savaliyati; wa nyanya, nzamalati ntheu; wa kenda, tovasi; wa ĩkũmi, kilisovilise; wa ĩkũmi na ũmwe, samawi; na wa ĩkũmi na ĩlĩ, amethusito.'),
('kam', 'REV', 21, 21, 'Na mbingĩlo ĩkũmi na ilĩ syaĩ sya malũlũ ĩkũmi na elĩ; kĩla mbingĩlo yaĩ ya lũlũ ũmwe: na nzĩa ya mũsyĩ yaĩ thaavu mũtheu, ta kĩsisyo kĩtheu.'),
('kam', 'REV', 21, 22, 'Na ndyaaona ĩkalũ nthĩnĩ waw’o: nĩkwĩthĩwa Mwĩaĩi Ngai Mwene Vinya W’onthe, na kala Katena, nĩo ĩkalũ yaw’o.'),
('kam', 'REV', 21, 23, 'Na mũsyĩ ũsu ndwĩ vata wa syũa, kana mwei, kũkena ĩũlũ waw’o: nũndũ ũtheu mũtisu wa Ngai ũwĩkĩaa kyeni, na taa waw’o nĩ kala Katena.'),
('kam', 'REV', 21, 24, 'Na mbaĩ ikaendaa na kyeni kyaw’o: na asumbĩ ma nthĩ makaete ndaĩa yoo nthĩnĩ waw’o.'),
('kam', 'REV', 21, 25, 'Na mbingĩlo syaw’o itikavingwa o na ĩndĩĩ mũthenya (nũndũ kũikethĩwa ũtukũ kw’o):'),
('kam', 'REV', 21, 26, 'na makaete ndaĩa na nguma sya mbaĩ nthĩnĩ waw’o:'),
('kam', 'REV', 21, 27, 'na nthĩnĩ waw’o vaikavota nongi kĩndũ kĩvuku, kana ũla wĩkaa ũthũku na ũvũngũ; ĩndĩ no ala maandĩkĩtwe ĩvukunĩ ya thayũ ya kala Katena.'),
('kam', 'REV', 22, 1, 'Nake ambon’ya ũsĩ wa manzĩ ma thayũ, mũtisu ta kĩsisyo, wumĩte kĩvĩlanĩ kya ũsumbĩ kya Ngai na kya kala Katena,'),
('kam', 'REV', 22, 2, 'wĩ katĩ wa nzĩa nene yaw’o. Na mũingo ũũ wa ũsĩ o na mũingo ũya vaĩ mũtĩ wa thayũ, ũsyaĩte mĩthemba ĩkũmi na ĩlĩ ya mosyao, ũsyaaa mosyao maw’o kĩla mwei: na matũ ma mũtĩ ũsu nĩ ma kũvosya mbaĩ.'),
('kam', 'REV', 22, 3, 'Na kũikethĩwa kĩumo ĩngĩ: na kĩvĩla kya ũsumbĩ kya Ngai na kya Katena kĩkeethĩwa nthĩnĩ waw’o: na ngombo syake ikamũthũkũmaa;'),
('kam', 'REV', 22, 4, 'na ikoonaa ũthyũ wake; na syĩtwa yake yĩkeethĩwa itulyanĩ syasyo.'),
('kam', 'REV', 22, 5, 'Na kũikethĩwa ũtukũ ĩngĩ; na mati vata wa kyeni kya taa, kana kyeni kya syũa; nĩkwĩthĩwa Mwĩaĩi Ngai akamanenga kyeni: nao makasumbĩka tene na tene.'),
('kam', 'REV', 22, 6, 'Na ambĩa, Ndeto ii nĩ sya kĩthito na nĩ sya w’o: na Mwĩaĩi, Ngai wa maveva ma athani, atũma mũlaĩka wake asyon’ye ngombo syake maũndũ ala matatĩa kwĩthĩwa mĩtũkĩ.'),
('kam', 'REV', 22, 7, 'Na sisya, nyie ngooka mĩtũkĩ. Nĩ mũathime ũla ũkwataa ndeto sya wathani wa ĩvuku yĩĩ.'),
('kam', 'REV', 22, 8, 'Nakwa Yoana ninyie neewie na kwona maũndũ asu. Na yĩla neewie na kwona, navalũka nĩthaithĩe maũũnĩ ma mũlaĩka ũla wambonisye maũndũ asu.'),
('kam', 'REV', 22, 9, 'Nake ambĩa, Sisya, ndũkeke ũu: nyie nĩ ngombo vamwe naku na vamwe na ana‐a‐ĩthe maku athani, na vamwe na ala makwataa ndeto sya ĩvuku yĩĩ: thaitha Ngai.'),
('kam', 'REV', 22, 10, 'Na ambĩa, Ndũkaisiĩle ndeto sya wathani wa ĩvuku yĩĩ; nĩkwĩthĩwa ĩvinda nĩ ĩthengeeu.'),
('kam', 'REV', 22, 11, 'Ũla ũte mũlũngalu, naendeeae na ũla ũte ũlũngalu: na ũla mũvuku, naendeeae na kũvukw’a: na ũla mũlũngalu, naendeeae na ũlũngalu: na ũla mũtheu, naendeeae na kũthew’a.'),
('kam', 'REV', 22, 12, 'Sisya, ngooka mĩtũkĩ; na ĩtuvi yakwa yĩ vamwe nakwa, kũmũtuva kĩla mũndũ kwĩanana na wĩa wake ũndũ ũilyĩ.'),
('kam', 'REV', 22, 13, 'Nyie nĩ Aliva na Omeka, wa mbee na wa ĩtina, mwambĩlĩlyo na mũminũkĩlyo.'),
('kam', 'REV', 22, 14, 'Nĩ aathime ala mathambasya ngũa syoo, nĩ kana methĩwe na ũkũmũ wa kũvika mũtĩnĩ wa thayũ, na mesĩle mbingĩlonĩ malike mũsyĩ.'),
('kam', 'REV', 22, 15, 'Ũtee ve ngitĩ, na aoi, na ilaalai, na oaani, na ala mathaithaa mĩvw’anano, na kĩla mũndũ wenda ũvũngũ na kũwĩka.'),
('kam', 'REV', 22, 16, 'Nyie Yesũ nĩnamũtũmie mũlaĩka amũkũsĩĩe inyw’ĩ maũndũ aa kwondũ wa makanisa. Ninyie kĩtina na ũsyao wa Ndaviti, ndata ĩla ĩtisaa, ĩla ya kĩoko.'),
('kam', 'REV', 22, 17, 'Na Veva na mũtwawa measya, Ũka. Na ũla wĩw’aa nĩasye, Ũka. Na ũla wĩ na waũni, nĩoke: o ũla ũnũkwenda, nĩose manzĩ ma thayũ mana.'),
('kam', 'REV', 22, 18, 'Nĩmũkũsĩĩa kĩla mũndũ ũla wĩw’aa ndeto sya wathani wa ĩvuku yĩĩ, Ethĩwa mũndũ o na wĩva akasyongeleela, Ngaĩ akamwongeleela mothĩn’yo ala maandĩkĩtwe ĩvukunĩ yĩĩ:'),
('kam', 'REV', 22, 19, 'na ethĩwa mũndũ o na wĩva akaola ndeto sya ĩvuku ya wathani ũũ, Ngai akaveta kĩanda kyake ũla mũtĩnĩ wa thayũ, na nthĩnĩ wa mũsyĩ ũla mũtheu, o ila iandĩkĩtwe ĩvukunĩ yĩĩ.'),
('kam', 'REV', 22, 20, 'Ũla ũnũũkũsĩĩa maũndũ aa easya, Ĩĩ: ngooka mĩtũkĩ. Ameni: ũka, Mwĩaĩi Yesũ.'),
('kam', 'REV', 22, 21, 'Mumo wa Mwĩaĩi Yesũ nĩwĩthĩwe na atheu. Ameni.')
